public class CharadesActivityManager : ActivityManager
{
	public enum WordDifficulty
	{
		Easy,
		Medium,
		Hard
	}

	[Serializable]
	private struct WordListAsset
	{
		public WordDifficulty Difficulty;

		public TextAsset WordList;
	}

	private const string WORD_DIFFICULTY_KEY = "WORD_DIFFICULTY";

	private const string LAST_ROUND_END_TIME_KEY = "ROUND_END_TIME";

	private const string DEFAULT_WORD = "RecRoom";

	[SerializeField]
	private MeshExtruderTool extruderTool;

	[SerializeField]
	private float roundDuration = 40f;

	[SerializeField]
	private float roundCooldown = 2f;

	[SerializeField]
	private float countdownAudioStartTime = 10f;

	[SerializeField]
	[Header("Word List")]
	private WordListAsset[] wordListAssets;

	[SerializeField]
	[Header("Button")]
	private NetworkCollider bigGreenButtonCollider;

	[SerializeField]
	private ParticleSystem winParticles;

	private List<string>[] wordLists;

	private bool playedCountdownAudio;

	protected override bool PlayerRequirementsMet => base.PlayerManager.GetActivePlayers().Length > 0;

	protected override void Awake()
	{
		base.Awake();
		string[] names = Enum.GetNames(typeof(WordDifficulty));
		wordLists = new List<string>[names.Length];
		WordListAsset[] array = wordListAssets;
		for (int i = 0; i < array.Length; i++)
		{
			WordListAsset wordListAsset = array[i];
			int difficulty = (int)wordListAsset.Difficulty;
			wordLists[difficulty] = new List<string>(LoadWordList(wordListAsset.WordList));
		}
		base.PlayerManager.RolesUpdatedEvent += MasterOnPlayerRolesChanged;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (base.PlayerManager != null)
		{
			base.PlayerManager.RolesUpdatedEvent -= MasterOnPlayerRolesChanged;
		}
	}

	protected override void OnServerActivityLoad()
	{
	}

	protected override void OnServerActivityDestroy()
	{
	}

	protected override void OnClientActivityLoad()
	{
		bigGreenButtonCollider.ServerPlayerTriggerEnterEvent += MasterOnPlayerBigGreenButtonPress;
	}

	public string GetRandomWord()
	{
		int currentDifficulty = (int)GetCurrentDifficulty();
		if (wordLists[currentDifficulty] == null || wordLists[currentDifficulty].Count == 0)
		{
			return "RecRoom";
		}
		return wordLists[currentDifficulty][UnityEngine.Random.Range(0, wordLists[currentDifficulty].Count)];
	}

	private string[] LoadWordList(TextAsset wordListAsset)
	{
		return wordListAsset.text.Split(new string[2] { "\r\n", "\n" }, StringSplitOptions.RemoveEmptyEntries);
	}

	private void SetCurrentDifficulty(WordDifficulty difficulty)
	{
		base.ActivityData.SetData("WORD_DIFFICULTY", (int)difficulty);
	}

	private WordDifficulty GetCurrentDifficulty()
	{
		return (WordDifficulty)base.ActivityData.GetData("WORD_DIFFICULTY", 0);
	}

	private void MasterOnPlayerBigGreenButtonPress(GameObject thisGameObject, Player player, Player.BodyPart bodyPart, Vector3 point)
	{
		if (PhotonNetwork.isMasterClient && !base.PlayerManager.IsPlayerSpectator(player.PhotonPlayer))
		{
			if (base.GameState == ActivityGameState.PlayingGame)
			{
				MasterEndRound(success: true);
			}
			else if (base.GameState == ActivityGameState.PreGame && (float)PhotonNetwork.time - GetLastRoundEndTime() >= roundCooldown)
			{
				MasterEnterGameState(ActivityGameState.Countdown);
			}
		}
	}

	public void EndRound(bool success)
	{
		base.photonView.RPC("RpcEndRound", PhotonNetwork.masterClient, success);
	}

	protected override IEnumerator PreGameStateCoroutine()
	{
		base.PlayerManager.MasterResetPlayerScores();
		PhotonPlayer[] spectators = base.PlayerManager.GetSpectators();
		if (spectators.Length == 0)
		{
			NotifyNewPerformer(null);
			yield break;
		}
		PhotonPlayer newActivePlayer = spectators[UnityEngine.Random.Range(0, spectators.Length)];
		PhotonPlayer[] activePlayers = base.PlayerManager.GetActivePlayers();
		PhotonPlayer previousWinner = ((activePlayers != null && activePlayers.Length != 0) ? activePlayers[0] : null);
		if (previousWinner != null)
		{
			base.PlayerManager.RequestToVacateRole(previousWinner);
		}
		if (newActivePlayer != null)
		{
			base.PlayerManager.RequestAutoAssignRole(newActivePlayer);
		}
	}

	protected override IEnumerator PlayingGameStateCoroutine()
	{
		PhotonPlayer[] activePlayers = base.PlayerManager.GetActivePlayers();
		if (!extruderTool.IsHeld || (activePlayers != null && activePlayers.Length > 0 && extruderTool.Owner != activePlayers[0].ToPlayer()))
		{
			extruderTool.ResetToLastSpawnPosition();
			base.photonView.RPC("RpcPickupExtruderTool", activePlayers[0]);
		}
		playedCountdownAudio = false;
		SetGameDuration(roundDuration);
		SetGameStartTime((float)PhotonNetwork.time);
		MasterPlaySoundAllPlayers("start_playing_activity");
		yield break;
	}

	protected override void MasterTryUpdateGame()
	{
		if (PhotonNetwork.isMasterClient && base.GameState == ActivityGameState.PlayingGame)
		{
			float timeRemaining = GetTimeRemaining();
			if (timeRemaining <= 0f)
			{
				MasterEndRound(success: false);
			}
			else if (timeRemaining <= countdownAudioStartTime && timeRemaining + 1f > countdownAudioStartTime && !playedCountdownAudio)
			{
				playedCountdownAudio = true;
				MasterPlaySoundAllPlayers("timer_expiring");
			}
		}
	}

	private void Update()
	{
		MasterTryUpdateGame();
	}

	private void MasterEndRound(bool success)
	{
		if (base.GameState == ActivityGameState.PlayingGame)
		{
			PhotonPlayer playerAtActiveSlot = base.PlayerManager.GetPlayerAtActiveSlot(0);
			MasterActivityWon(playerAtActiveSlot);
			if (success)
			{
				base.photonView.RPC("RpcPlayEndRoundParticles", PhotonTargets.All);
				float timeRemaining = GetTimeRemaining();
				float num = roundDuration - timeRemaining;
				MasterShowNotificationAllPlayers("You Win!", 3f, "Guessed in " + num + " seconds");
			}
			else
			{
				MasterPlaySoundAllPlayers("you_lose");
				MasterShowNotificationAllPlayers("You Lose!", 3f);
			}
			SetLastRoundEndTime((float)PhotonNetwork.time);
			MasterPlaySoundAllPlayers("timer_expired");
			MasterPlaySoundAllPlayers("stop_music");
			MasterEnterGameState(ActivityGameState.PreGame);
		}
	}

	[PunRPC]
	public void RpcEndRound(bool success)
	{
		MasterEndRound(success);
	}

	[PunRPC]
	public void RpcPlayEndRoundParticles()
	{
		base.ActivityAudio.OnScore();
		winParticles.Play();
	}

	[PunRPC]
	public void RpcPickupExtruderTool()
	{
		if (Player.LocalPlayer != null)
		{
			PlayerHand playerHand = Player.LocalPlayer.DominantHand;
			if (playerHand.Tool != null)
			{
				playerHand = Player.LocalPlayer.GetOtherHand(playerHand.Type);
			}
			if (playerHand.Tool == null)
			{
				Player.LocalPlayer.ToolController.TryPickupTool(extruderTool, (int)playerHand.Type);
			}
		}
	}

	private float GetLastRoundEndTime()
	{
		return base.ActivityData.GetData("ROUND_END_TIME", -1f);
	}

	private void SetLastRoundEndTime(float endTime)
	{
		base.ActivityData.SetData("ROUND_END_TIME", endTime);
	}

	private void MasterOnPlayerRolesChanged(PhotonPlayer updatedPlayer)
	{
		if (PhotonNetwork.isMasterClient)
		{
			NotifyNewPerformer(updatedPlayer);
		}
	}

	private void NotifyNewPerformer(PhotonPlayer updatedPlayer)
	{
		StartCoroutine(RunNotifyNewPerformer(updatedPlayer));
	}

	private IEnumerator RunNotifyNewPerformer(PhotonPlayer updatedPlayer)
	{
		yield return new WaitForSeconds(3f);
		PhotonPlayer[] newActivePlayers = base.PlayerManager.GetActivePlayers();
		if (newActivePlayers != null && newActivePlayers.Length > 0 && (updatedPlayer == null || newActivePlayers[0] == updatedPlayer))
		{
			MasterShowNotification(newActivePlayers[0], "Your turn!", 3f);
		}
	}
}
public class CharadesJumbotronUI : JumbotronUI
{
	private const string KEEP_GUESSING_STRING = "Keep Guessing!";

	[SerializeField]
	[Header("Spectators")]
	private JumbotronPlayerEntry[] spectatorEntries;

	[SerializeField]
	[Header("End Game")]
	private Button endGameButton;

	[SerializeField]
	private Text endGameButtonText;

	[Header("Timer")]
	[SerializeField]
	private Text timerText;

	private string endGameButtonDefaultText = string.Empty;

	public void ButtonPress_StopGame()
	{
		CharadesActivityManager charadesActivityManager = (CharadesActivityManager)ActivityManager.Instance;
		if (charadesActivityManager != null)
		{
			charadesActivityManager.EndRound(success: true);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		endGameButtonDefaultText = endGameButtonText.text;
	}

	protected override void UpdateUI()
	{
		base.UpdateUI();
		PhotonPlayer[] spectators = ActivityManager.Instance.PlayerManager.GetSpectators();
		int i;
		for (i = 0; i < spectators.Length && i < spectatorEntries.Length; i++)
		{
			spectatorEntries[i].Show(spectators[i], null);
		}
		for (; i < spectatorEntries.Length; i++)
		{
			spectatorEntries[i].ShowWaiting(null);
		}
		bool flag = ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player);
		bool active = ActivityManager.Instance.GameState == ActivityGameState.PlayingGame;
		if (endGameButton != null)
		{
			endGameButton.gameObject.SetActive(active);
			endGameButton.interactable = !flag;
			endGameButtonText.text = ((!endGameButton.interactable) ? "Keep Guessing!" : endGameButtonDefaultText);
		}
	}

	private void Update()
	{
		if (ActivityManager.Instance.GameState == ActivityGameState.PlayingGame)
		{
			timerText.text = ActivityManager.Instance.GetTimeRemaining().ToTimeString();
		}
	}
}
public class CharadesWordText : Photon.MonoBehaviour
{
	private const string WORD_KEY = "WORD";

	[SerializeField]
	private Text text;

	[SerializeField]
	private string spectatorWord = "No Peeking!";

	private ActivityData activityData;

	private void Awake()
	{
		activityData = GetComponent<ActivityData>();
	}

	private void Start()
	{
		ActivityManager.Instance.PlayerManager.RolesUpdatedEvent += OnPlayerRolesUpdated;
		if (base.hasAuthority)
		{
			CharadesActivityManager charadesActivityManager = (CharadesActivityManager)ActivityManager.Instance;
			if (charadesActivityManager != null)
			{
				activityData.SetData("WORD", charadesActivityManager.GetRandomWord());
				base.photonView.RPC("RpcOnWordUpdated", PhotonTargets.All);
			}
		}
	}

	private void OnDestroy()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.PlayerManager.RolesUpdatedEvent -= OnPlayerRolesUpdated;
		}
	}

	private void OnPlayerRolesUpdated(PhotonPlayer updatedPlayer)
	{
		UpdateWord();
	}

	private void UpdateWord()
	{
		if (ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			text.text = spectatorWord;
		}
		else
		{
			text.text = activityData.GetData("WORD", spectatorWord);
		}
	}

	[PunRPC]
	public void RpcOnWordUpdated()
	{
		UpdateWord();
	}
}
