public class PhysicsButtonVisual : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float releaseSpeed = 0.5f;

	[SerializeField]
	private Transform unpressedTransform;

	[SerializeField]
	private Transform pressedTransform;

	private Rigidbody rigidbody;

	private Vector3 buttonDownDirection;

	private void Awake()
	{
		rigidbody = GetComponent<Rigidbody>();
		buttonDownDirection = (pressedTransform.position - unpressedTransform.position).normalized;
		rigidbody.position = unpressedTransform.position;
		rigidbody.velocity = Vector3.zero;
	}

	private void FixedUpdate()
	{
		Vector3 lhs = unpressedTransform.position - rigidbody.position;
		if (Vector3.Dot(lhs, buttonDownDirection) >= 0f - Mathf.Epsilon)
		{
			rigidbody.position = unpressedTransform.position;
			rigidbody.velocity = Vector3.zero;
			return;
		}
		rigidbody.velocity = -buttonDownDirection * releaseSpeed;
		Vector3 lhs2 = pressedTransform.position - rigidbody.position;
		if (Vector3.Dot(lhs2, buttonDownDirection) <= Mathf.Epsilon)
		{
			rigidbody.position = pressedTransform.position;
		}
	}
}
public class TimerText : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private TextMesh[] timerTextMeshes;

	[SerializeField]
	private Text[] timerTexts;

	private void Start()
	{
		OnTimerUpdate(0f);
	}

	private void Update()
	{
		float timer = 0f;
		if (ActivityManager.Instance.GameState == ActivityGameState.PlayingGame)
		{
			timer = ActivityManager.Instance.GetTimeRemaining();
		}
		OnTimerUpdate(timer);
	}

	private void OnTimerUpdate(float timer)
	{
		string text = timer.ToTimeString();
		Text[] array = timerTexts;
		foreach (Text text2 in array)
		{
			text2.text = text;
		}
		TextMesh[] array2 = timerTextMeshes;
		foreach (TextMesh textMesh in array2)
		{
			textMesh.text = text;
		}
	}
}
public class DiscGolfActivityManager : ActivityManager
{
	[Serializable]
	private struct Hole
	{
		public DiscGolfGoal Goal;

		public Transform[] FrisbeeSpawnPoints;

		public int Par;
	}

	private const string ACTIVITY_CURRENT_HOLE_KEY = "CURRENT_HOLE";

	private const string PLAYER_STROKE_COUNT_KEY = "STROKE_COUNT";

	private const string PLAYER_HAS_THROWN_KEY = "HAS_THROWN";

	private const string PLAYER_HAS_SCORED_KEY = "HAS_SCORED";

	[Header("Course Layout")]
	[SerializeField]
	private Hole[] holes;

	[SerializeField]
	private NetworkedGameObjectPool frisbeePool;

	[Header("Scoring")]
	[SerializeField]
	private float throwScore = 1f;

	[SerializeField]
	private float hazardScore = 1f;

	[SerializeField]
	[Header("Score Notifications")]
	private string scoreHoleInOne = "Hole In One!";

	[SerializeField]
	private string scoreLessThanNeg2 = "Albatross";

	[SerializeField]
	private string scoreNeg2 = "Eagle";

	[SerializeField]
	private string scoreNeg1 = "Birdie";

	[SerializeField]
	private string scoreZero = "Par";

	[SerializeField]
	private string scorePos1 = "Bogey";

	[SerializeField]
	private string scorePos2 = "Double Bogey";

	[SerializeField]
	private string scorePos3 = "Triple Bogey";

	private PhotonPlayer winner;

	private int winningScore;

	protected override bool PlayerRequirementsMet => base.PlayerManager.GetActivePlayers().Length > 0;

	protected override void OnServerActivityLoad()
	{
	}

	protected override void OnServerActivityDestroy()
	{
	}

	protected override void OnClientActivityLoad()
	{
		GameObject[] pool = frisbeePool.Pool;
		foreach (GameObject gameObject in pool)
		{
			Frisbee component = gameObject.GetComponent<Frisbee>();
			component.ServerPhotonViewCollisionEnterEvent += MasterOnFrisbeePhotonViewCollisionEnter;
			component.ServerOtherCollisionEnterEvent += MasterOnFrisbeeOtherCollisionEnter;
			component.ServerReleaseEvent += MasterOnFrisbeeRelease;
			component.ServerPickupEvent += MasterOnFrisbeePickup;
			component.ServerKillzoneResetEvent += MasterOnFrisbeeHazard;
			component.BeamEnabled = true;
		}
		base.GameStateChangedEvent += OnGameStateChange;
		base.ActivityData.RegisterCallback("CURRENT_HOLE", OnCurrentHoleChanged);
		UpdateGoalBeams();
	}

	private void OnGameStateChange(ActivityGameState oldState, ActivityGameState newState)
	{
		UpdateGoalBeams();
	}

	private void OnCurrentHoleChanged(ActivityData sender, PhotonPlayer player, string key)
	{
		UpdateGoalBeams();
	}

	protected override IEnumerator PreGameStateCoroutine()
	{
		KillAllFrisbees();
		yield return MasterRespawnAllPlayers();
	}

	protected override IEnumerator PlayingGameStateCoroutine()
	{
		base.ActivityData.SetData("CURRENT_HOLE", -1);
		KillAllFrisbees();
		MasterPlaySoundAllPlayers("start_playing_activity");
		yield return MasterRespawnAllActivePlayers();
		yield return MasterStartNextHole();
	}

	protected override IEnumerator PostGameStateCoroutine()
	{
		MasterActivityWon(winner);
		yield return new WaitForSeconds(3f);
		if (winner != null)
		{
			MasterShowNotificationAllPlayers("Game Over!", 2f);
			MasterShowNotificationAllPlayers(winner.name + " Wins!", 3f);
		}
	}

	private void MasterPlayerScored(Player thrower, DiscGolfGoal goal, int holeIndex)
	{
		int dataForPlayer = base.ActivityData.GetDataForPlayer(thrower.PhotonPlayer, "STROKE_COUNT", 0);
		dataForPlayer++;
		base.ActivityData.SetDataForPlayer(thrower.PhotonPlayer, "STROKE_COUNT", dataForPlayer);
		base.ActivityData.SetDataForPlayer(thrower.PhotonPlayer, "HAS_SCORED", data: true);
		int num = dataForPlayer - holes[holeIndex].Par;
		base.PlayerManager.MasterAddPlayerScore(thrower.PhotonPlayer, num);
		MasterShowNotificationAllPlayers(ScoreNotificationString(dataForPlayer, num), 2f, thrower.PlayerName);
		int playerSlot = base.PlayerManager.GetPlayerSlot(thrower.PhotonPlayer);
		frisbeePool.Release(frisbeePool.Pool[playerSlot]);
		goal.PlayGoalParticles();
		PlayScoreAllPlayers();
		MasterTryUpdateGame();
	}

	protected override void MasterRemovePlayer(PhotonPlayer player)
	{
		base.MasterRemovePlayer(player);
		base.ActivityData.RemoveDataForPlayer(player, "STROKE_COUNT");
		base.ActivityData.RemoveDataForPlayer(player, "HAS_THROWN");
		base.ActivityData.RemoveDataForPlayer(player, "HAS_SCORED");
	}

	protected override void MasterTryUpdateGame()
	{
		PhotonPlayer[] activePlayers = base.PlayerManager.GetActivePlayers();
		foreach (PhotonPlayer player in activePlayers)
		{
			if (!base.ActivityData.GetDataForPlayer(player, "HAS_SCORED", defaultValue: false))
			{
				return;
			}
		}
		int data = base.ActivityData.GetData("CURRENT_HOLE", -1);
		if (data == holes.Length - 1)
		{
			winningScore = int.MaxValue;
			winner = null;
			PhotonPlayer[] activePlayers2 = base.PlayerManager.GetActivePlayers();
			foreach (PhotonPlayer player2 in activePlayers2)
			{
				int playerScore = base.PlayerManager.GetPlayerScore(player2);
				if (playerScore < winningScore)
				{
					winningScore = playerScore;
					winner = player2;
				}
			}
			MasterEnterGameState(ActivityGameState.PostGame);
		}
		else
		{
			MasterStartNextHole();
		}
	}

	private Coroutine MasterStartNextHole()
	{
		return StartCoroutine(StartNextHoleCoroutine());
	}

	private IEnumerator StartNextHoleCoroutine()
	{
		int currentHoleIndex = base.ActivityData.GetData("CURRENT_HOLE", -1);
		KillAllFrisbees();
		if (currentHoleIndex >= 0)
		{
			yield return new WaitForSeconds(3f);
			yield return MasterShowNotificationAllPlayers("Hole " + (currentHoleIndex + 1) + " Complete", 2f);
		}
		currentHoleIndex++;
		base.ActivityData.SetData("CURRENT_HOLE", currentHoleIndex);
		MasterShowNotificationAllPlayers("Hole " + (currentHoleIndex + 1), 5f, "Par " + holes[currentHoleIndex].Par);
		PhotonPlayer[] activePlayers = base.PlayerManager.GetActivePlayers();
		foreach (PhotonPlayer player in activePlayers)
		{
			base.ActivityData.SetDataForPlayer(player, "STROKE_COUNT", 0);
			base.ActivityData.SetDataForPlayer(player, "HAS_THROWN", data: false);
			base.ActivityData.SetDataForPlayer(player, "HAS_SCORED", data: false);
			int slot = base.PlayerManager.GetPlayerSlot(player);
			SpawnFrisbee(slot, holes[currentHoleIndex].FrisbeeSpawnPoints[slot], restrictToPlayer: true);
		}
	}

	private string ScoreNotificationString(int hits, int score)
	{
		string empty = string.Empty;
		if (hits == 1)
		{
			return scoreHoleInOne;
		}
		if (score < -2)
		{
			return scoreLessThanNeg2;
		}
		return score switch
		{
			-2 => scoreNeg2, 
			-1 => scoreNeg1, 
			0 => scoreZero, 
			1 => scorePos1, 
			2 => scorePos2, 
			3 => scorePos3, 
			_ => "+" + score, 
		};
	}

	private void MasterOnFrisbeePhotonViewCollisionEnter(Tool tool, PhotonView hitPhotonView, Vector3 point)
	{
		if (base.GameState == ActivityGameState.PlayingGame && PhotonNetwork.isMasterClient)
		{
			PhotonPlayer throwerFromFrisbee = GetThrowerFromFrisbee(tool);
			DiscGolfGoal component = hitPhotonView.GetComponent<DiscGolfGoal>();
			int data = base.ActivityData.GetData("CURRENT_HOLE", -1);
			bool dataForPlayer = base.ActivityData.GetDataForPlayer(throwerFromFrisbee, "HAS_SCORED", defaultValue: false);
			if (!base.PlayerManager.IsPlayerSpectator(throwerFromFrisbee) && !dataForPlayer && data >= 0 && data < holes.Length && component == holes[data].Goal)
			{
				MasterPlayerScored(throwerFromFrisbee.ToPlayer(), component, data);
			}
		}
	}

	private void MasterOnFrisbeeOtherCollisionEnter(Tool tool, Layers hitLayer, Vector3 point)
	{
		if (base.GameState != ActivityGameState.PlayingGame || !PhotonNetwork.isMasterClient)
		{
			return;
		}
		PhotonPlayer throwerFromFrisbee = GetThrowerFromFrisbee(tool);
		if (throwerFromFrisbee != null)
		{
			bool dataForPlayer = base.ActivityData.GetDataForPlayer(throwerFromFrisbee, "HAS_SCORED", defaultValue: false);
			bool dataForPlayer2 = base.ActivityData.GetDataForPlayer(throwerFromFrisbee, "HAS_THROWN", defaultValue: false);
			if (!base.PlayerManager.IsPlayerSpectator(throwerFromFrisbee) && !dataForPlayer && dataForPlayer2)
			{
				int dataForPlayer3 = base.ActivityData.GetDataForPlayer(throwerFromFrisbee, "STROKE_COUNT", 0);
				base.ActivityData.SetDataForPlayer(throwerFromFrisbee, "STROKE_COUNT", dataForPlayer3 + 1);
				base.ActivityData.SetDataForPlayer(throwerFromFrisbee, "HAS_THROWN", data: false);
			}
		}
	}

	private void MasterOnFrisbeePickup(Tool tool)
	{
		if (base.GameState == ActivityGameState.PlayingGame && PhotonNetwork.isMasterClient)
		{
			PhotonPlayer throwerFromFrisbee = GetThrowerFromFrisbee(tool);
			bool dataForPlayer = base.ActivityData.GetDataForPlayer(throwerFromFrisbee, "HAS_SCORED", defaultValue: false);
			int dataForPlayer2 = base.ActivityData.GetDataForPlayer(throwerFromFrisbee, "STROKE_COUNT", 0);
			if (!base.PlayerManager.IsPlayerSpectator(throwerFromFrisbee) && !dataForPlayer)
			{
				MasterShowNotification(throwerFromFrisbee, "Stroke " + (dataForPlayer2 + 1), 2f);
			}
		}
	}

	private void MasterOnFrisbeeRelease(Tool tool)
	{
		if (base.GameState == ActivityGameState.PlayingGame && PhotonNetwork.isMasterClient)
		{
			PhotonPlayer throwerFromFrisbee = GetThrowerFromFrisbee(tool);
			bool dataForPlayer = base.ActivityData.GetDataForPlayer(throwerFromFrisbee, "HAS_SCORED", defaultValue: false);
			if (!base.PlayerManager.IsPlayerSpectator(throwerFromFrisbee) && !dataForPlayer)
			{
				base.ActivityData.SetDataForPlayer(throwerFromFrisbee, "HAS_THROWN", data: true);
			}
		}
	}

	private void MasterOnFrisbeeHazard(Tool tool, Killzone killzone)
	{
		if (PhotonNetwork.isMasterClient)
		{
			PhotonPlayer throwerFromFrisbee = GetThrowerFromFrisbee(tool);
			MasterShowNotification(throwerFromFrisbee, "Hazard!", 2f);
		}
	}

	private PhotonPlayer GetThrowerFromFrisbee(Tool tool)
	{
		if (tool.PlayerInteractionRestriction.AllowedSlots != null && tool.PlayerInteractionRestriction.AllowedSlots.Length > 0)
		{
			return base.PlayerManager.GetPlayerAtActiveSlot(tool.PlayerInteractionRestriction.AllowedSlots[0]);
		}
		return tool.Owner.PhotonPlayer;
	}

	private void SpawnFrisbee(int slotIndex, Transform spawnPoint, bool restrictToPlayer)
	{
		GameObject gameObject = frisbeePool.Acquire(slotIndex, spawnPoint.position, spawnPoint.rotation);
		Frisbee component = gameObject.GetComponent<Frisbee>();
		if (restrictToPlayer)
		{
			component.PlayerInteractionRestriction.MasterRestrictToActivePlayerSlot(slotIndex);
		}
		else
		{
			component.PlayerInteractionRestriction.MasterResetToDefaulRestrictions();
		}
		if (gameObject == null)
		{
			UnityEngine.Debug.LogError("Could not acquire a frisbee from pool");
		}
	}

	private void KillAllFrisbees()
	{
		GameObject[] pool = frisbeePool.Pool;
		foreach (GameObject gameObject in pool)
		{
			if (gameObject.activeSelf)
			{
				frisbeePool.Release(gameObject);
			}
		}
	}

	private void UpdateGoalBeams()
	{
		for (int i = 0; i < holes.Length; i++)
		{
			int data = base.ActivityData.GetData("CURRENT_HOLE", -1);
			holes[i].Goal.BeamEnabled = base.GameState != ActivityGameState.PlayingGame || data == i;
		}
	}

	private void PlayScoreAllPlayers()
	{
		base.photonView.RPC("RpcPlayScoreAudio", PhotonTargets.All);
	}

	[PunRPC]
	public void RpcPlayScoreAudio()
	{
		base.ActivityAudio.OnScore();
	}
}
