	[Header("DiscGolf Strings")]
	private ScoreboardEntryTextMeshes[] competitiveWinnerFlags;

	public override void Reset()
	{
		base.Reset();
		ScoreboardEntryTextMeshes[] array = competitiveWinnerFlags;
		foreach (ScoreboardEntryTextMeshes scoreboardEntryTextMeshes in array)
		{
			scoreboardEntryTextMeshes.Text = string.Empty;
		}
	}

	protected override void Start()
	{
		base.Start();
		ScoreboardEntryTextMeshes[] array = competitiveWinnerFlags;
		foreach (ScoreboardEntryTextMeshes scoreboardEntryTextMeshes in array)
		{
			scoreboardEntryTextMeshes.Text = string.Empty;
		}
	}

	protected override void OnActivityWon(PhotonPlayer player, ActivityTeam team)
	{
		base.OnActivityWon(player, team);
		PhotonPlayer[] activePlayersSortedBySlot = ActivityManager.Instance.PlayerManager.GetActivePlayersSortedBySlot();
		for (int i = 0; i < activePlayersSortedBySlot.Length && i < competitiveWinnerFlags.Length; i++)
		{
