	{
		string text = ((score <= 0) ? string.Empty : "+");
		return text + score;
	}
}
public class AttackPoint : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float radius;

	[SerializeField]
	private Color highlightColor = new Color(0.3f, 0.5f, 0f, 1f);

	private Renderer[] renderers;

	private Color previousColor;

	private Color _color;

	public Player Occupier { get; private set; }

	public Color Color
	{
		get
		{
			return _color;
		}
		set
		{
			_color = value;
			if (renderers != null)
			{
				Renderer[] array = renderers;
				foreach (Renderer renderer in array)
				{
					Color color = _color;
					color.a = renderer.material.color.a;
					renderer.material.color = color;
				}
			}
		}
	}

	private void Awake()
	{
		renderers = GetComponentsInChildren<Renderer>();
	}

	private void Update()
	{
		if (Occupier != null && !PlayerInRadius(Occupier))
		{
			Occupier = null;
			Color = previousColor;
		}
		if (!(Occupier == null))
		{
			return;
		}
		for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
		{
			Player recRoomPlayer = Player.GetRecRoomPlayer(i);
			if (PlayerInRadius(recRoomPlayer))
			{
				Occupier = recRoomPlayer;
				previousColor = Color;
				Color = highlightColor;
				break;
			}
		}
	}

	private bool PlayerInRadius(Player player)
	{
		if (player == null || player.Head == null)
		{
			return false;
		}
		return Vector3.ProjectOnPlane(player.Head.transform.position - base.transform.position, Vector3.up).sqrMagnitude <= radius * radius;
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = Color.green;
		Gizmos.DrawWireSphere(base.transform.position, radius);
	}
}
