public class DodgeballActivityManager : ActivityManager
{
	private const string SCORING_TEAM_KEY = "SCORING_TEAM";

	private const string ROUND_RUNNING_KEY = "ROUND_RUNNING";

	private const string CURRENT_ROUND_KEY = "CURRENT_ROUND";

	private const string IS_ALIVE_KEY = "IS_ALIVE";

	private const string THROWER_KEY = "THROWER";

	private const string FIRST_HIT_KEY = "FIRST_HIT";

	private const string FIRST_HIT_POINT_KEY = "FIRST_HIT_POINT";

	private const float DUMMY_SPAWN_HEIGHT = 1.5f;

	[SerializeField]
	[Header("Resources")]
	private NetworkedGameObjectPool ballPool;

	[SerializeField]
	private ParticleSystem playerHitParticles;

	[SerializeField]
	[Header("Gameplay")]
	private int maxRounds = 5;

	[Header("Court")]
	[SerializeField]
	private Transform[] ballSpawnPoints;

	private DodgeballActivityAudio dodgeballAudio;

	private int ScoreToWin => maxRounds / 2 + 1;

	protected override bool PlayerRequirementsMet => base.PlayerManager.GetActiveTeams().Length > 1;

	protected override void OnServerActivityLoad()
	{
	}

	protected override void OnServerActivityDestroy()
	{
		if (base.GameState == ActivityGameState.PlayingGame)
		{
			ResetGame();
		}
	}

	protected override void OnClientActivityLoad()
	{
		GameObject[] pool = ballPool.Pool;
		foreach (GameObject gameObject in pool)
		{
			Dodgeball component = gameObject.GetComponent<Dodgeball>();
			component.ServerPlayerCollisionEnterEvent += MasterOnDodgeballPlayerCollisionEnter;
			component.ServerToolCollisionEnterEvent += MasterOnDodgeballToolCollisionEnter;
			component.ServerOtherCollisionEnterEvent += MasterOnDodgeballOtherCollisionEnter;
			component.ServerPickupEvent += MasterOnDodgeballPickup;
			component.ServerReleaseEvent += MasterOnDodgeballRelease;
			component.ActivityData.RegisterCallback("IS_ALIVE", OnBallStateChanged);
			component.GetComponent<PUNNetworkTransform>().CurrentExtrapolationMode = PUNNetworkTransform.ExtrapolationMode.DynamicTime;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		dodgeballAudio = GetComponent<DodgeballActivityAudio>();
	}

	protected override IEnumerator PreGameStateCoroutine()
	{
		base.PlayerManager.MasterResetTeamScores();
		KillAllDodgeballs();
		SpawnAllDodgeballs();
		MasterRespawnAllActivePlayers();
		MasterRespawnAllSpectators();
		yield break;
	}

	protected override IEnumerator PlayingGameStateCoroutine()
	{
		SetCurrentRound(0);
		SetIsRoundRunning(isRunning: false);
		SetLastScoringTeam(null);
		base.TeleportRestrictions.MasterDisableAllActivePlayerTeleportation();
		MarkAllTeamPlayersAlive();
		MasterRespawnAllSpectators();
		MasterTryUpdateGame();
		yield break;
	}

	protected override void MasterRemovePlayer(PhotonPlayer player)
	{
		base.MasterRemovePlayer(player);
		base.ActivityData.RemoveDataForPlayer(player, "IS_ALIVE");
	}

	protected override void MasterTryUpdateGame()
	{
		if (!PhotonNetwork.isMasterClient || base.GameState != ActivityGameState.PlayingGame)
		{
			return;
		}
		if (GetIsRoundRunning())
		{
			ActivityTeam winningTeam = null;
			if (IsRoundOver(out winningTeam))
			{
				MasterEndRound(winningTeam);
			}
			return;
		}
		ActivityTeam lastScoringTeam = GetLastScoringTeam();
		int num = ((lastScoringTeam != null) ? base.PlayerManager.GetTeamScore(lastScoringTeam) : 0);
		if (num >= ScoreToWin)
		{
			MasterGameOver(lastScoringTeam);
		}
		else
		{
			MasterStartRound();
		}
	}

	private bool GetIsRoundRunning()
	{
		return base.ActivityData.GetData("ROUND_RUNNING", defaultValue: false);
	}

	private void SetIsRoundRunning(bool isRunning)
	{
		base.ActivityData.SetData("ROUND_RUNNING", isRunning);
	}

	private int GetCurrentRound()
	{
		return base.ActivityData.GetData("CURRENT_ROUND", -1);
	}

	private void SetCurrentRound(int currentRound)
	{
		base.ActivityData.SetData("CURRENT_ROUND", currentRound);
	}

	private void MasterStartRound()
	{
		if (PhotonNetwork.isMasterClient)
		{
			StartCoroutine(StartRoundCoroutine());
		}
	}

	private IEnumerator StartRoundCoroutine()
	{
		KillAllDodgeballs();
		base.TeleportRestrictions.MasterDisableAllActivePlayerTeleportation();
		MarkAllTeamPlayersAlive();
		yield return MasterRespawnAllActivePlayers();
		int currentRound = GetCurrentRound();
		if (currentRound == 0)
		{
			yield return MasterShowNotificationAllPlayers("Best " + ScoreToWin + " of " + maxRounds + " rounds", 1.5f);
			yield return new WaitForSeconds(1f);
		}
		yield return MasterShowNotificationAllPlayers("Round " + (currentRound + 1), 1.5f);
		MasterShowNotificationAllPlayers("Go!", 2f);
		MasterPlaySoundAllPlayers("start_playing_activity");
		SpawnAllDodgeballs();
		base.TeleportRestrictions.MasterEnableAllActivePlayerTeleportation();
		SetIsRoundRunning(isRunning: true);
		MasterTryUpdateGame();
	}

	private void MasterEndRound(ActivityTeam winningTeam)
	{
		if (PhotonNetwork.isMasterClient)
		{
			StartCoroutine(EndRoundCoroutine(winningTeam));
		}
	}

	private IEnumerator EndRoundCoroutine(ActivityTeam winningTeam)
	{
		base.PlayerManager.MasterAddTeamScore(winningTeam, 1);
		SetLastScoringTeam(winningTeam);
		base.ActivityAudio.OnScore();
		int nextRound = GetCurrentRound() + 1;
		SetCurrentRound(nextRound);
		SetIsRoundRunning(isRunning: false);
		yield return new WaitForSeconds(2f);
		if (base.PlayerManager.GetTeamScore(winningTeam) < ScoreToWin)
		{
			yield return MasterShowNotificationAllPlayers("Round Over!", 3f);
			yield return new WaitForSeconds(1f);
		}
		MasterTryUpdateGame();
	}

	private void MasterGameOver(ActivityTeam winningTeam)
	{
		if (PhotonNetwork.isMasterClient)
		{
			StartCoroutine(GameOverCoroutine(winningTeam));
		}
	}

	private IEnumerator GameOverCoroutine(ActivityTeam winningTeam)
	{
		KillAllDodgeballs();
		yield return MasterShowNotificationAllPlayers("Game Over!", 2f);
		yield return MasterShowNotificationAllPlayers("Team " + winningTeam.Name + " Wins!", 3f);
		MarkAllTeamPlayersAlive();
		MasterPlaySoundAllPlayers("stop_music");
		MasterActivityWon(winningTeam);
		MasterEnterGameState(ActivityGameState.PreGame);
	}

	private void MasterPlayerOut(PhotonPlayer outPlayer, PhotonPlayer thrower, Vector3 outPosition)
	{
		if (PhotonNetwork.isMasterClient && base.GameState == ActivityGameState.PlayingGame && GetIsRoundRunning() && IsPlayerAlive(outPlayer))
		{
			MarkPlayerDead(outPlayer);
			base.photonView.RPC("RpcPlayerOut", PhotonTargets.All, outPlayer, thrower, outPosition);
		}
	}

	private bool IsRoundOver(out ActivityTeam winningTeam)
	{
		int num = 0;
		ActivityTeam activityTeam = null;
		ActivityTeam[] activeTeams = base.PlayerManager.GetActiveTeams();
		foreach (ActivityTeam activityTeam2 in activeTeams)
		{
			if (IsTeamAlive(activityTeam2))
			{
				activityTeam = activityTeam2;
				num++;
			}
		}
		if (num > 1)
		{
			winningTeam = null;
			return false;
		}
		winningTeam = activityTeam;
		return true;
	}

	private void ResetGame()
	{
		base.PlayerManager.MasterResetTeamScores();
		KillAllDodgeballs();
	}

	private bool GetIsBallAlive(Dodgeball ball)
	{
		return ball.ActivityData.GetData("IS_ALIVE", defaultValue: false);
	}

	private void SetBallAlive(Dodgeball ball, bool alive)
	{
		ball.ActivityData.SetData("IS_ALIVE", alive);
	}

	private void OnBallStateChanged(ActivityData sender, PhotonPlayer player, string key)
	{
		Dodgeball component = sender.GetComponent<Dodgeball>();
		if (component != null)
		{
			bool isBallAlive = GetIsBallAlive(component);
			component.SupportsAssistedCatching = !isBallAlive;
			if (isBallAlive)
			{
				component.FireTrail.Play();
			}
			else
			{
				component.FireTrail.Stop();
			}
		}
	}

	private Player GetBallThrower(Dodgeball ball)
	{
		int data = ball.ActivityData.GetData("THROWER", -1);
		return (data != -1) ? base.PlayerManager.GetPlayerAtActiveSlot(data).ToPlayer() : null;
	}

	private void SetBallThrower(Dodgeball ball, Player thrower)
	{
		int data = ((!(thrower == null)) ? base.PlayerManager.GetPlayerSlot(thrower.PhotonPlayer) : (-1));
		ball.ActivityData.SetData("THROWER", data);
	}

	private Player GetBallFirstHitPlayer(Dodgeball ball, out Vector3 hitPoint)
	{
		int data = ball.ActivityData.GetData("FIRST_HIT", -1);
		hitPoint = Vector3.zero;
		Player player = ((data != -1) ? base.PlayerManager.GetPlayerAtActiveSlot(data).ToPlayer() : null);
		if (player != null)
		{
			hitPoint = ball.ActivityData.GetData("FIRST_HIT_POINT", Vector3.zero);
		}
		return player;
	}

	private void SetBallFirstHitPlayer(Dodgeball ball, Player firstHit)
	{
		SetBallFirstHitPlayer(ball, firstHit, Vector3.zero);
	}

	private void SetBallFirstHitPlayer(Dodgeball ball, Player firstHit, Vector3 hitPoint)
	{
		int data = ((!(firstHit == null)) ? base.PlayerManager.GetPlayerSlot(firstHit.PhotonPlayer) : (-1));
		ball.ActivityData.SetData("FIRST_HIT", data);
		ball.ActivityData.SetData("FIRST_HIT_POINT", hitPoint);
	}

	private void MasterOnDodgeballPlayerCollisionEnter(Tool tool, Player hitPlayer, Player.BodyPart bodyPart, Vector3 point)
	{
		Dodgeball component = tool.GetComponent<Dodgeball>();
		if (!PhotonNetwork.isMasterClient || component == null)
		{
			return;
		}
		Player ballThrower = GetBallThrower(component);
		if (tool.IsHeld || !GetIsBallAlive(component) || ballThrower == null)
		{
			return;
		}
		Vector3 hitPoint;
		Player ballFirstHitPlayer = GetBallFirstHitPlayer(component, out hitPoint);
		if (ballFirstHitPlayer == null && hitPlayer != ballThrower && AreOpponents(ballThrower.PhotonPlayer, hitPlayer.PhotonPlayer))
		{
			SetBallFirstHitPlayer(component, hitPlayer, point);
			PlayerHit(point);
			return;
		}
		if (ballFirstHitPlayer != null && hitPlayer != ballFirstHitPlayer)
		{
			MasterPlayerOut(ballFirstHitPlayer.PhotonPlayer, ballThrower.PhotonPlayer, hitPoint);
		}
		SetBallAlive(component, alive: false);
	}

	private void MasterOnDodgeballOtherCollisionEnter(Tool tool, Layers colliderLayer, Vector3 point)
	{
		MasterOnDodgeballCollisionEnter(tool, point);
	}

	private void MasterOnDodgeballToolCollisionEnter(Tool tool, Tool otherTool, Vector3 point)
	{
		MasterOnDodgeballCollisionEnter(tool, point);
	}

	private void MasterOnDodgeballCollisionEnter(Tool tool, Vector3 point)
	{
		Dodgeball component = tool.GetComponent<Dodgeball>();
		if (PhotonNetwork.isMasterClient && !(component == null))
		{
			Vector3 hitPoint = Vector3.zero;
			Player ballFirstHitPlayer = GetBallFirstHitPlayer(component, out hitPoint);
			Player ballThrower = GetBallThrower(component);
			if (ballFirstHitPlayer != null && ballThrower != null)
			{
				MasterPlayerOut(ballFirstHitPlayer.PhotonPlayer, ballThrower.PhotonPlayer, hitPoint);
			}
			SetBallAlive(component, alive: false);
		}
	}

	private void MasterOnDodgeballPickup(Tool tool)
	{
		Dodgeball component = tool.GetComponent<Dodgeball>();
		if (!PhotonNetwork.isMasterClient || component == null)
		{
			return;
		}
		Player ballThrower = GetBallThrower(component);
		if (GetIsBallAlive(component) && ballThrower != null && ballThrower != component.Owner)
		{
			if (GetBallFirstHitPlayer(component, out var hitPoint) == null)
			{
				hitPoint = component.transform.position;
			}
			PlayerCatch(component.Owner.PhotonPlayer, ballThrower.PhotonPlayer, hitPoint);
		}
		SetBallThrower(component, null);
		SetBallFirstHitPlayer(component, null);
		SetBallAlive(component, alive: false);
	}

	private void MasterOnDodgeballRelease(Tool tool)
	{
		Dodgeball component = tool.GetComponent<Dodgeball>();
		if (PhotonNetwork.isMasterClient && !(component == null))
		{
			SetBallThrower(component, tool.Owner);
			SetBallFirstHitPlayer(component, null);
			SetBallAlive(component, alive: true);
		}
	}

	private void SpawnAllDodgeballs()
	{
		Transform[] array = ballSpawnPoints;
		foreach (Transform spawnPoint in array)
		{
			SpawnDodgeball(spawnPoint);
		}
	}

	public void SpawnDodgeball(Transform spawnPoint)
	{
		if (ballPool.Availability > 0)
		{
			GameObject gameObject = ballPool.Acquire(spawnPoint.position, spawnPoint.rotation);
			Dodgeball dodgeball = ((!(gameObject == null)) ? gameObject.GetComponent<Dodgeball>() : null);
			if (dodgeball != null && base.GameState == ActivityGameState.PlayingGame)
			{
				SetBallAlive(dodgeball, alive: false);
				SetBallFirstHitPlayer(dodgeball, null);
				SetBallThrower(dodgeball, null);
			}
		}
	}

	private void KillAllDodgeballs()
	{
		ballPool.MasterDisableAll();
	}

	public void KillDodgeball(Dodgeball ball)
	{
		ballPool.Release(ball.gameObject);
	}

	public void PlayerHit(Vector3 position)
	{
		if (PhotonNetwork.isMasterClient && base.GameState == ActivityGameState.PlayingGame && GetIsRoundRunning())
		{
			base.photonView.RPC("RpcPlayPlayerHitParticles", PhotonTargets.All, position);
		}
	}

	[PunRPC]
	public void RpcPlayPlayerHitParticles(Vector3 hitPosition)
	{
		dodgeballAudio.OnPlayerHit(hitPosition);
		playerHitParticles.transform.position = hitPosition;
		playerHitParticles.Play();
	}

	public void PlayerCatch(PhotonPlayer catcher, PhotonPlayer thrower, Vector3 position)
	{
		if (PhotonNetwork.isMasterClient && base.GameState == ActivityGameState.PlayingGame && GetIsRoundRunning())
		{
			base.photonView.RPC("RpcOnPlayerCatch", PhotonTargets.All, catcher, thrower, position);
		}
	}

	public bool AreOpponents(PhotonPlayer player1, PhotonPlayer player2)
	{
		return !base.PlayerManager.IsPlayerSpectator(player1) && !base.PlayerManager.IsPlayerSpectator(player2) && IsPlayerAlive(player1) && IsPlayerAlive(player2) && !base.PlayerManager.PlayersOnSameTeam(player1, player2);
	}

	private void RunPlayerOut(PhotonPlayer outPlayer, PhotonPlayer thrower, Vector3 outPoint)
	{
		Player player = outPlayer.ToPlayer();
		Player player2 = thrower.ToPlayer();
		if (player != null && player2 != null)
		{
			StartCoroutine(PlayerOutCoroutine(player, player2, outPoint));
		}
	}

	private IEnumerator PlayerOutCoroutine(Player outPlayer, Player thrower, Vector3 point)
	{
		if (outPlayer.isLocal)
		{
			dodgeballAudio.OnPlayerOut(point);
			Player.LocalPlayer.CanInteractWithTools = false;
			Player.LocalPlayer.PlayerLocomotion.TeleportEnabled = false;
			RpcShowNotification("You're Out!", "Hit by " + thrower.PlayerName, 3f);
			yield return new WaitForSeconds(3f);
			yield return MasterRespawnPlayerAsSpectator(outPlayer);
			Player.LocalPlayer.CanInteractWithTools = true;
			Player.LocalPlayer.PlayerLocomotion.TeleportEnabled = true;
			base.photonView.RPC("RpcOnActivePlayerRespawn", PhotonTargets.MasterClient, outPlayer.PhotonPlayer);
		}
		else if (thrower.isLocal)
		{
			dodgeballAudio.OnPlayerOut(point);
			Vector3 notificationOffset = 0.35f * ((Player.LocalPlayer.Head.transform.position - point).normalized + Vector3.up);
			RpcShowWorldSpaceNotification(point + notificationOffset, "Out!", null, 3f);
			RpcShowNotification("You Hit " + outPlayer.PlayerName, null, 3f);
		}
	}

	private void RunPlayerCatch(PhotonPlayer catcher, PhotonPlayer thrower, Vector3 catchPoint)
	{
		if (catcher.isLocal)
		{
			dodgeballAudio.OnPlayerSave(catchPoint);
			RpcShowNotification("Caught!", null, 3f);
		}
		if (thrower.isLocal)
		{
			dodgeballAudio.OnPlayerSave(catchPoint);
			Vector3 vector = 0.35f * ((Player.LocalPlayer.Head.transform.position - catchPoint).normalized + Vector3.up);
			RpcShowWorldSpaceNotification(catchPoint + vector, "Catch!", null, 3f);
			RpcShowNotification(catcher.name + " Caught It!", null, 3f);
		}
	}

	private Coroutine RunPlayerRespawn(Vector3 position, Quaternion rotation)
	{
		return StartCoroutine(PlayerRespawnCoroutine(position, rotation));
	}

	private IEnumerator PlayerRespawnCoroutine(Vector3 position, Quaternion rotation)
	{
		Player.LocalPlayer.Respawn(position, rotation);
		yield return new WaitForSeconds(Player.RespawnDuration);
		Player.LocalPlayer.CanInteractWithTools = true;
		Player.LocalPlayer.PlayerLocomotion.TeleportEnabled = true;
	}

	protected override Coroutine MasterRespawnAllActivePlayers()
	{
		return StartCoroutine(RespawnAllActivePlayers());
	}

	private IEnumerator RespawnAllActivePlayers()
	{
		PhotonPlayer[] players = base.PlayerManager.GetActivePlayers();
		PhotonPlayer[] array = players;
		foreach (PhotonPlayer player in array)
		{
			Transform spawnPoint = base.PlayerManager.GetSpawnPoint(player);
			base.photonView.RPC("RpcPlayerRespawn", player, spawnPoint.position, spawnPoint.rotation);
		}
		yield return new WaitForSeconds(Player.RespawnDuration);
	}

	private void MarkPlayerDead(PhotonPlayer player)
	{
		base.PlayerManager.MasterSetPlayerSpectator(player, isSpectator: true);
		base.ActivityData.SetDataForPlayer(player, "IS_ALIVE", data: false);
	}

	private void MarkPlayerAlive(PhotonPlayer player)
	{
		base.PlayerManager.MasterSetPlayerSpectator(player, isSpectator: false);
		base.ActivityData.SetDataForPlayer(player, "IS_ALIVE", data: true);
	}

	private void MarkAllTeamPlayersAlive()
	{
		ActivityTeam[] activeTeams = base.PlayerManager.GetActiveTeams();
		foreach (ActivityTeam team in activeTeams)
		{
			PhotonPlayer[] teamPlayers = base.PlayerManager.GetTeamPlayers(team);
			foreach (PhotonPlayer player in teamPlayers)
			{
				MarkPlayerAlive(player);
			}
		}
	}

	private bool IsTeamAlive(ActivityTeam team)
	{
		PhotonPlayer[] teamPlayers = base.PlayerManager.GetTeamPlayers(team);
		foreach (PhotonPlayer player in teamPlayers)
		{
			if (IsPlayerAlive(player))
			{
				return true;
			}
		}
		return false;
	}

	private bool IsPlayerAlive(PhotonPlayer player)
	{
		return base.ActivityData.GetDataForPlayer(player, "IS_ALIVE", defaultValue: false);
	}

	[PunRPC]
	public void RpcPlayerOut(PhotonPlayer outPlayer, PhotonPlayer thrower, Vector3 outPoint)
	{
		RunPlayerOut(outPlayer, thrower, outPoint);
	}

	[PunRPC]
	public void RpcOnPlayerCatch(PhotonPlayer catcher, PhotonPlayer thrower, Vector3 catchPoint)
	{
		RunPlayerCatch(catcher, thrower, catchPoint);
	}

	[PunRPC]
	public void RpcPlayerRespawn(Vector3 spawnPosition, Quaternion spawnRotation)
	{
		RunPlayerRespawn(spawnPosition, spawnRotation);
	}

	[PunRPC]
	public void RpcOnActivePlayerRespawn(PhotonPlayer player)
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterTryUpdateGame();
		}
	}

	private ActivityTeam GetLastScoringTeam()
	{
		int data = base.ActivityData.GetData("SCORING_TEAM", -1);
		if (data == -1)
		{
			return null;
		}
		return base.PlayerManager.GetTeam(data);
	}

	private void SetLastScoringTeam(ActivityTeam lastScoringTeam)
	{
		int data = lastScoringTeam?.Id ?? (-1);
		base.ActivityData.SetData("SCORING_TEAM", data);
	}
}
