public class DormroomActivityManager : ActivityManager
{
	public const string INTRO_OOBE_PROPERTY = "IntroOOBEProperty";

	public const int INTRO_OOBE_UNFINISHED = 0;

	public const int INTRO_OOBE_COMPLETED = 1;

	[SerializeField]
	private bool forceOobe;

	[SerializeField]
	private string blockedUserMessage = "You are currently blocked.\nYou can rejoin in {0}mins {1}secs.";

	[SerializeField]
	private TeleportationPortal exitTeleportationPortal;

	protected override void OnServerActivityLoad()
	{
		int userBlockedDurationSecondsRemaning = SingletonMonoBehaviour<SettingsManager>.Instance.GetUserBlockedDurationSecondsRemaning();
		if (userBlockedDurationSecondsRemaning > 0)
		{
			StartCoroutine(BlockedCoroutine(userBlockedDurationSecondsRemaning));
		}
		else if (forceOobe || RecroomPrefs.GetInt("IntroOOBEProperty", 0) == 0)
		{
			RecroomPrefs.SetInt("IntroOOBEProperty", 1);
			StartCoroutine(OOBECoroutine());
		}
		else
		{
			StartCoroutine(IntroCoroutine());
		}
	}

	protected override void OnClientActivityLoad()
	{
	}

	protected override void OnServerActivityDestroy()
	{
	}

	private IEnumerator BlockedCoroutine(int durationSeconds)
	{
		exitTeleportationPortal.gameObject.SetActive(value: false);
		while (Player.LocalPlayer == null)
		{
			yield return null;
		}
		PlayerMenu menu = Player.LocalPlayer.PlayerUI.Menu;
		menu.SetHeaderButtonsInteractable(interactable: false);
		while (durationSeconds > 0)
		{
			menu.ShowAlertMessage(message: string.Format(blockedUserMessage, durationSeconds / 60, durationSeconds % 60), title: string.Empty);
			yield return new WaitForSeconds(1f);
			durationSeconds--;
		}
		menu.StopShowAlertMessage();
		menu.SetHeaderButtonsInteractable(interactable: true);
		menu.Visible = false;
		exitTeleportationPortal.gameObject.SetActive(value: true);
		OnServerActivityLoad();
	}

	private IEnumerator IntroCoroutine()
	{
		while (Player.LocalPlayer == null)
		{
			yield return null;
		}
		if (PUNNetworkManager.Instance != null && PUNNetworkManager.Instance.GetAlertMessage(out var alertMessage, out var alertTitle))
		{
			Player.LocalPlayer.PlayerUI.Menu.ShowAlertMessage(alertTitle, alertMessage);
		}
	}

	private IEnumerator OOBECoroutine()
	{
		yield break;
	}
}
public class MessageOfTheDay : UnityEngine.MonoBehaviour
{
	private const string MESSAGE_OF_THE_DAY_URL = "http://www.againstgrav.com/motd";

	private const string MESSAGE_OF_THE_DAY_PLAYER_PREFS_KEY = "MessageOfTheDay";

	[SerializeField]
	private Text messageText;

	private IEnumerator Start()
	{
		if (RecroomPrefs.HasKey("MessageOfTheDay"))
		{
			messageText.text = RecroomPrefs.GetString("MessageOfTheDay", messageText.text);
		}
		WWW www = new WWW("http://www.againstgrav.com/motd");
		yield return www;
		if (string.IsNullOrEmpty(www.error))
		{
			string message = www.text;
			messageText.text = message;
			RecroomPrefs.SetString("MessageOfTheDay", message);
		}
		else
		{
			UnityEngine.Debug.LogError("Message of the day download failed: " + www.error);
		}
	}
}
public class IntroActivityManager : ActivityManager
{
	public const string INTRO_OOBE_PROPERTY = "IntroOOBEProperty";

	public const int INTRO_OOBE_UNFINISHED = 0;

	public const int INTRO_OOBE_COMPLETED = 1;

	private const string MESSAGE_OF_THE_DAY_URL = "http://www.againstgrav.com/motd";

	private const string MESSAGE_OF_THE_DAY_PLAYER_PREFS_KEY = "MessageOfTheDay";

	[Header("Intro")]
	[SerializeField]
	private string defaultMessageOfTheDay = string.Empty;

	[SerializeField]
	private GameObject lockerRoomDoor;

	[SerializeField]
	private bool forceOobe;

	[SerializeField]
	private string blockedUserMessage = "You are currently blocked.\nYou can rejoin in {0}mins {1}secs.";

	private Coroutine recurringNotificationCoroutine;

	private string messageOfTheDay;

	protected override void Awake()
	{
		base.Awake();
		StartCoroutine(DownloadMessageOfTheDayCoroutine());
		if (!string.IsNullOrEmpty(PUNNetworkManager.Instance.PlayerToAutoJoin))
		{
			TeleportationPortal componentInChildren = lockerRoomDoor.GetComponentInChildren<TeleportationPortal>();
			componentInChildren.DestinationUserId = PUNNetworkManager.Instance.PlayerToAutoJoin;
		}
	}

	protected override void OnServerActivityLoad()
	{
		int userBlockedDurationSecondsRemaning = SingletonMonoBehaviour<SettingsManager>.Instance.GetUserBlockedDurationSecondsRemaning();
		if (userBlockedDurationSecondsRemaning > 0)
		{
			StartCoroutine(BlockedCoroutine(userBlockedDurationSecondsRemaning));
		}
		else if (forceOobe || RecroomPrefs.GetInt("IntroOOBEProperty", 0) == 0)
		{
			RecroomPrefs.SetInt("IntroOOBEProperty", 1);
			StartCoroutine(OOBECoroutine());
		}
		else
		{
			StartCoroutine(IntroCoroutine());
		}
	}

	protected override void OnServerActivityDestroy()
	{
		StopRecurringNotification();
	}

	protected override void OnClientActivityLoad()
	{
	}

	private IEnumerator BlockedCoroutine(int durationSeconds)
	{
		while (Player.LocalPlayer == null)
		{
			yield return null;
		}
		while (durationSeconds > 0)
		{
			string punishmentMessage = string.Format(blockedUserMessage, durationSeconds / 60, durationSeconds % 60);
			Player.LocalPlayer.PlayerUI.Menu.ShowAlertMessage(string.Empty, punishmentMessage);
			yield return new WaitForSeconds(1f);
			durationSeconds--;
		}
		OnServerActivityLoad();
	}

	private IEnumerator IntroCoroutine()
	{
		yield return new WaitForSeconds(2f);
		if (PUNNetworkManager.Instance != null && PUNNetworkManager.Instance.GetAlertMessage(out var alertMessage, out var alertTitle))
		{
			Player.LocalPlayer.PlayerUI.Menu.ShowAlertMessage(alertTitle, alertMessage);
		}
		else
		{
			float timeout = Time.time + 3f;
			while (messageOfTheDay == null && Time.time < timeout)
			{
				yield return null;
			}
			if (messageOfTheDay == null)
			{
				messageOfTheDay = RecroomPrefs.GetString("MessageOfTheDay", defaultMessageOfTheDay);
			}
			Player.LocalPlayer.PlayerUI.Menu.ShowMessageOfTheDay(messageOfTheDay);
		}
		yield return new WaitForSeconds(1f);
		lockerRoomDoor.SetActive(value: true);
	}

	private IEnumerator OOBECoroutine()
	{
		while (Player.LocalPlayer == null)
		{
			yield return null;
		}
		Player.LocalPlayer.PlayerLocomotion.TeleportEnabled = false;
		yield return new WaitForSeconds(2f);
		StartRecurringNotification("Press Menu To Begin", 5f, 10f);
		Player.LocalPlayer.PlayerUI.Menu.ShowOOBEMessage = true;
		while (!Player.LocalPlayer.PlayerUI.Menu.Visible)
		{
			yield return null;
		}
		StopRecurringNotification();
		while (Player.LocalPlayer.PlayerUI.Menu.Visible)
		{
			yield return null;
		}
		Player.LocalPlayer.PlayerLocomotion.TeleportEnabled = true;
		lockerRoomDoor.SetActive(value: true);
		StartRecurringNotification("Teleport To Enter", 5f, 10f);
	}

	private void StartRecurringNotification(string notificationText, float notificationDuration, float repeatTime)
	{
		StopRecurringNotification();
		recurringNotificationCoroutine = StartCoroutine(RecurringNotificationCoroutine(notificationText, notificationDuration, repeatTime));
	}

	private void StopRecurringNotification()
	{
		if (recurringNotificationCoroutine != null)
		{
			StopCoroutine(recurringNotificationCoroutine);
		}
	}

	private IEnumerator RecurringNotificationCoroutine(string notificationText, float notificationDuration, float repeatTime)
	{
		while (true)
		{
			SingletonMonoBehaviour<WorldSpaceNotification>.Instance.Play(notificationText, notificationDuration);
			yield return new WaitForSeconds(repeatTime);
		}
	}

	private IEnumerator DownloadMessageOfTheDayCoroutine()
	{
		WWW www = new WWW("http://www.againstgrav.com/motd");
		yield return www;
		if (string.IsNullOrEmpty(www.error))
		{
			messageOfTheDay = www.text;
			RecroomPrefs.SetString("MessageOfTheDay", messageOfTheDay);
		}
		else
		{
			UnityEngine.Debug.LogError("Message of the day download failed: " + www.error);
		}
	}
}
