[ExecuteInEditMode]
public class Mirror : UnityEngine.MonoBehaviour
{
	private class ReflectionData
	{
		public RenderTexture texture;

		public MaterialPropertyBlock propertyBlock;
	}

	[SerializeField]
	private bool disablePixelLights = true;

	[SerializeField]
	[Tooltip("Mirror will use up to the anti-aliasing level specified in QualitySettings, without exceeding this value (1, 2, 4, or 8)")]
	private int maxAntiAliasing = 1;

	private Dictionary<Camera, ReflectionData> m_Reflections = new Dictionary<Camera, ReflectionData>();

	private Camera mirrorCamera;

	private Skybox mirrorSkybox;

	private static bool s_InsideRendering = false;

	private static int TexturePropertyID;

	private static readonly Rect LeftEyeRect = new Rect(0f, 0f, 0.5f, 1f);

	private static readonly Rect RightEyeRect = new Rect(0.5f, 0f, 0.5f, 1f);

	private static readonly Rect DefaultRect = new Rect(0f, 0f, 1f, 1f);

	private void OnValidate()
	{
		if (maxAntiAliasing != 1 && maxAntiAliasing != 2 && maxAntiAliasing != 4 && maxAntiAliasing != 8)
		{
			maxAntiAliasing = 1;
		}
	}

	private void Awake()
	{
		TexturePropertyID = Shader.PropertyToID("_ReflectionTex");
	}

	public void OnWillRenderObject()
	{
		Renderer component = GetComponent<Renderer>();
		if (!base.enabled || !component || !component.enabled)
		{
			return;
		}
		Camera current = Camera.current;
		if (!current || current == mirrorCamera || s_InsideRendering)
		{
			return;
		}
		s_InsideRendering = true;
		ReflectionData reflectionData = GetReflectionData(current);
		int pixelLightCount = QualitySettings.pixelLightCount;
		if (disablePixelLights)
		{
			QualitySettings.pixelLightCount = 0;
		}
		UpdateCameraModes(current);
		if (current.stereoEnabled)
		{
			if (current.stereoTargetEye == StereoTargetEyeMask.Both || current.stereoTargetEye == StereoTargetEyeMask.Left)
			{
				Vector3 vector = InputTracking.GetLocalPosition(VRNode.LeftEye);
				Quaternion quaternion = InputTracking.GetLocalRotation(VRNode.LeftEye);
				Matrix4x4 projectionMatrix = GetProjectionMatrix(current, VRNode.LeftEye);
				if (current.transform.parent != null)
				{
					vector = current.transform.parent.TransformPoint(vector);
					quaternion = current.transform.parent.TransformRotation(quaternion);
				}
				RenderMirror(reflectionData.texture, vector, quaternion, projectionMatrix, LeftEyeRect);
			}
			if (current.stereoTargetEye == StereoTargetEyeMask.Both || current.stereoTargetEye == StereoTargetEyeMask.Right)
			{
				Vector3 vector2 = InputTracking.GetLocalPosition(VRNode.RightEye);
				Quaternion quaternion2 = InputTracking.GetLocalRotation(VRNode.RightEye);
				Matrix4x4 projectionMatrix2 = GetProjectionMatrix(current, VRNode.RightEye);
				if (current.transform.parent != null)
				{
					vector2 = current.transform.parent.TransformPoint(vector2);
					quaternion2 = current.transform.parent.TransformRotation(quaternion2);
				}
				RenderMirror(reflectionData.texture, vector2, quaternion2, projectionMatrix2, RightEyeRect);
			}
		}
		else
		{
			RenderMirror(reflectionData.texture, current.transform.position, current.transform.rotation, current.projectionMatrix, DefaultRect);
		}
		component.SetPropertyBlock(reflectionData.propertyBlock);
		if (disablePixelLights)
		{
			QualitySettings.pixelLightCount = pixelLightCount;
		}
		s_InsideRendering = false;
	}

	private void RenderMirror(RenderTexture targetTexture, Vector3 camPosition, Quaternion camRotation, Matrix4x4 camProjectionMatrix, Rect camViewport)
	{
		mirrorCamera.ResetWorldToCameraMatrix();
		mirrorCamera.transform.position = camPosition;
		mirrorCamera.transform.rotation = camRotation;
		mirrorCamera.projectionMatrix = camProjectionMatrix;
		mirrorCamera.targetTexture = targetTexture;
		mirrorCamera.rect = camViewport;
		Vector3 position = base.transform.position;
		Vector3 normal = -base.transform.up;
		Vector4 plane = Plane(position, normal);
		mirrorCamera.worldToCameraMatrix *= CalculateReflectionMatrix(plane);
		Vector4 clipPlane = CameraSpacePlane(mirrorCamera, position, normal);
		mirrorCamera.projectionMatrix = mirrorCamera.CalculateObliqueMatrix(clipPlane);
		mirrorCamera.transform.position = mirrorCamera.cameraToWorldMatrix.GetPosition();
		mirrorCamera.transform.rotation = mirrorCamera.cameraToWorldMatrix.GetRotation();
		bool invertCulling = GL.invertCulling;
		GL.invertCulling = !invertCulling;
		mirrorCamera.Render();
		GL.invertCulling = invertCulling;
	}

	private void OnDisable()
	{
		if ((bool)mirrorCamera)
		{
			UnityEngine.Object.DestroyImmediate(mirrorCamera.gameObject);
			mirrorCamera = null;
		}
		foreach (ReflectionData value in m_Reflections.Values)
		{
			UnityEngine.Object.DestroyImmediate(value.texture);
		}
		m_Reflections.Clear();
	}

	private void UpdateCameraModes(Camera src)
	{
		if (!mirrorCamera)
		{
			GameObject gameObject = new GameObject("MirrorCam" + base.gameObject.name, typeof(Camera), typeof(Skybox), typeof(FlushOnPostRender));
			gameObject.hideFlags = HideFlags.HideAndDontSave;
			mirrorSkybox = gameObject.GetComponent<Skybox>();
			mirrorCamera = gameObject.GetComponent<Camera>();
			mirrorCamera.enabled = false;
		}
		mirrorCamera.clearFlags = src.clearFlags;
		mirrorCamera.backgroundColor = src.backgroundColor;
		if (src.clearFlags == CameraClearFlags.Skybox)
		{
			Skybox skybox = src.GetComponent(typeof(Skybox)) as Skybox;
			if (!skybox || !skybox.material)
			{
				mirrorSkybox.enabled = false;
			}
			else
			{
				mirrorSkybox.enabled = true;
				mirrorSkybox.material = skybox.material;
			}
		}
		mirrorCamera.farClipPlane = src.farClipPlane;
		mirrorCamera.nearClipPlane = src.nearClipPlane;
		mirrorCamera.orthographic = src.orthographic;
		mirrorCamera.fieldOfView = src.fieldOfView;
		mirrorCamera.aspect = src.aspect;
		mirrorCamera.orthographicSize = src.orthographicSize;
	}

	private ReflectionData GetReflectionData(Camera currentCamera)
	{
		ReflectionData value = null;
		if (!m_Reflections.TryGetValue(currentCamera, out value))
		{
			value = new ReflectionData();
			value.propertyBlock = new MaterialPropertyBlock();
			m_Reflections[currentCamera] = value;
		}
		int num = currentCamera.pixelWidth;
		int pixelHeight = currentCamera.pixelHeight;
		int b = Mathf.Min(QualitySettings.antiAliasing, maxAntiAliasing);
		b = Mathf.Max(1, b);
		if (currentCamera.stereoEnabled)
		{
			num *= 2;
		}
		if (!value.texture || value.texture.width != num || value.texture.height != pixelHeight || value.texture.antiAliasing != b)
		{
			if ((bool)value.texture)
			{
				UnityEngine.Object.DestroyImmediate(value.texture);
			}
			value.texture = new RenderTexture(num, pixelHeight, 24);
			value.texture.antiAliasing = b;
			value.texture.hideFlags = HideFlags.DontSave;
			value.propertyBlock.SetTexture(TexturePropertyID, value.texture);
		}
		return value;
	}

	private Vector4 Plane(Vector3 pos, Vector3 normal)
	{
		return new Vector4(normal.x, normal.y, normal.z, 0f - Vector3.Dot(pos, normal));
	}

	private Vector4 CameraSpacePlane(Camera cam, Vector3 pos, Vector3 normal)
	{
		Matrix4x4 worldToCameraMatrix = cam.worldToCameraMatrix;
		Vector3 pos2 = worldToCameraMatrix.MultiplyPoint(pos);
		Vector3 normalized = worldToCameraMatrix.MultiplyVector(normal).normalized;
		return Plane(pos2, normalized);
	}

	private static Matrix4x4 CalculateReflectionMatrix(Vector4 plane)
	{
		Matrix4x4 identity = Matrix4x4.identity;
		identity.m00 = 1f - 2f * plane[0] * plane[0];
		identity.m01 = -2f * plane[0] * plane[1];
		identity.m02 = -2f * plane[0] * plane[2];
		identity.m03 = -2f * plane[3] * plane[0];
		identity.m10 = -2f * plane[1] * plane[0];
		identity.m11 = 1f - 2f * plane[1] * plane[1];
		identity.m12 = -2f * plane[1] * plane[2];
		identity.m13 = -2f * plane[3] * plane[1];
		identity.m20 = -2f * plane[2] * plane[0];
		identity.m21 = -2f * plane[2] * plane[1];
		identity.m22 = 1f - 2f * plane[2] * plane[2];
		identity.m23 = -2f * plane[3] * plane[2];
		identity.m30 = 0f;
		identity.m31 = 0f;
		identity.m32 = 0f;
		identity.m33 = 1f;
		return identity;
	}

	private static Matrix4x4 GetProjectionMatrix(Camera cam, VRNode node)
	{
		EVREye eEye = ((node == VRNode.RightEye) ? EVREye.Eye_Right : EVREye.Eye_Left);
		HmdMatrix44_t projectionMatrix = OpenVR.System.GetProjectionMatrix(eEye, cam.nearClipPlane, cam.farClipPlane, EGraphicsAPIConvention.API_DirectX);
		return new Matrix4x4
		{
			m00 = projectionMatrix.m0,
			m01 = projectionMatrix.m1,
			m02 = projectionMatrix.m2,
			m03 = projectionMatrix.m3,
			m10 = projectionMatrix.m4,
			m11 = projectionMatrix.m5,
			m12 = projectionMatrix.m6,
			m13 = projectionMatrix.m7,
			m20 = projectionMatrix.m8,
			m21 = projectionMatrix.m9,
			m22 = projectionMatrix.m10,
			m23 = projectionMatrix.m11,
			m30 = projectionMatrix.m12,
			m31 = projectionMatrix.m13,
			m32 = projectionMatrix.m14,
			m33 = projectionMatrix.m15
		};
	}
}
[RequireComponent(typeof(Joint))]
[RequireComponent(typeof(Rigidbody))]
public class JointMaxStretch : UnityEngine.MonoBehaviour
{
	[Tooltip("Max distance this bone can stretch from it's parent before resetting to it's original offset")]
	[SerializeField]
	private float maxStretch = 0.2f;

	private Rigidbody rigidbody;

	private Joint joint;

	private Vector3 defaultPosition;

	private Quaternion defaultRotation;

	private float maxDistanceFromConnectedBody;

	private void Awake()
	{
		rigidbody = GetComponent<Rigidbody>();
		joint = GetComponent<Joint>();
		defaultPosition = joint.connectedBody.transform.InverseTransformPoint(base.transform.position);
		defaultRotation = joint.connectedBody.transform.InverseTransformRotation(base.transform.rotation);
	}

	private void Update()
	{
		if (Vector3.Distance(base.transform.position, joint.connectedBody.transform.position) > defaultPosition.magnitude + maxStretch)
		{
			base.transform.position = joint.connectedBody.transform.TransformPoint(defaultPosition);
			base.transform.rotation = joint.connectedBody.transform.TransformRotation(defaultRotation);
			rigidbody.ClearVelocity();
		}
	}
}
public class Radio : Tool
{
	[Header("Audio")]
	[SerializeField]
	private AudioSource audioSource;

	[SerializeField]
	private RecRoomAudioClip[] tracks;

	[SerializeField]
	private bool randomInitialTrack;

	private int currentTrackNumber;

	protected override void Start()
	{
		base.Start();
		if (base.hasAuthority)
		{
			if (randomInitialTrack)
			{
				currentTrackNumber = -1;
				PlayRandomTrack(randomTrackPosition: true);
			}
			else
			{
				base.photonView.RPC("RpcRadioPlayTrack", PhotonTargets.All, 0, 0f);
			}
		}
	}

	public override void OnInputDown()
	{
		int num = (currentTrackNumber + 1) % tracks.Length;
		base.photonView.RPC("RpcRadioPlayTrack", PhotonTargets.All, num, 0f);
	}

	public void Update()
	{
		if (!audioSource.isPlaying && base.hasAuthority)
		{
			PlayRandomTrack();
		}
	}

	private void PlayRandomTrack(bool randomTrackPosition = false)
	{
		int num = UnityEngine.Random.Range(0, tracks.Length);
		if (num == currentTrackNumber)
		{
			num++;
			if (num > tracks.Length - 1)
			{
				num = 0;
			}
		}
		float num2 = 0f;
		if (randomTrackPosition)
		{
			num2 = UnityEngine.Random.Range(0f, tracks[num].audioClip.length * 0.9f);
		}
		base.photonView.RPC("RpcRadioPlayTrack", PhotonTargets.All, num, num2);
	}

	protected override void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		base.OnPhotonPlayerConnected(newPlayer);
		if (base.hasAuthority && audioSource.isPlaying)
		{
			base.photonView.RPC("RpcRadioPlayTrack", PhotonTargets.All, currentTrackNumber, audioSource.time);
		}
	}

	[PunRPC]
	public void RpcRadioPlayTrack(int trackNumber, float time)
	{
		if (trackNumber < tracks.Length && tracks[trackNumber] != null)
		{
			audioSource.Stop();
			audioSource.clip = tracks[trackNumber].audioClip;
			audioSource.Play();
			audioSource.time = time;
			currentTrackNumber = trackNumber;
		}
	}
}
