public class LockerRoomOptimizationManager : SingletonMonoBehaviour<LockerRoomOptimizationManager>
{
	[Serializable]
	public class OptimizationRegion
	{
		public string label;

		public Transform[] activeTransforms;

		public GameObject[] activeRenderersRoots;

		private bool initialized;

		private List<Renderer> activeRenderers;

		private bool _active;

		public bool Active
		{
			get
			{
				return _active;
			}
			set
			{
				if (value == _active && initialized)
				{
					return;
				}
				Initialize();
				_active = value;
				foreach (Renderer activeRenderer in activeRenderers)
				{
					if (activeRenderer != null)
					{
						activeRenderer.enabled = value;
					}
				}
				Transform[] array = activeTransforms;
				foreach (Transform transform in array)
				{
					if (transform != null)
					{
						transform.gameObject.SetActive(value);
					}
				}
			}
		}

		private void Initialize()
		{
			if (initialized)
			{
				return;
			}
			activeRenderers = new List<Renderer>();
			GameObject[] array = activeRenderersRoots;
			foreach (GameObject gameObject in array)
			{
				if (!(gameObject != null))
				{
					continue;
				}
				Renderer[] componentsInChildren = gameObject.GetComponentsInChildren<Renderer>();
				Renderer[] array2 = componentsInChildren;
				foreach (Renderer renderer in array2)
				{
					if (renderer != null && renderer.enabled)
					{
						activeRenderers.Add(renderer);
					}
				}
			}
			initialized = true;
		}
	}

	[SerializeField]
	private OptimizationRegion lockerRoom;

	[SerializeField]
	private OptimizationRegion changingRoom;

	private void Awake()
	{
		SingletonMonoBehaviour<LockerRoomOptimizationManager>.Instance = this;
	}

	private void Update()
	{
		if (Player.LocalPlayer != null)
		{
			lockerRoom.Active = !Player.LocalPlayer.IsInChangingRoom;
			changingRoom.Active = Player.LocalPlayer.IsInChangingRoom;
		}
	}
}
public class SlideshowScreen : PunBehaviour
{
	[SerializeField]
	private Texture2D[] slideshow;

	[SerializeField]
	private Renderer screenRenderer;

	[SerializeField]
	private Button rightButton;

	[SerializeField]
	private Button leftButton;

	[SerializeField]
	private bool loop = true;

	private int slideIndex;

	private bool _isVisible;

	public bool IsVisible
	{
		get
		{
			return _isVisible;
		}
		private set
		{
			_isVisible = value;
			screenRenderer.gameObject.SetActive(_isVisible);
			leftButton.gameObject.SetActive(_isVisible);
			rightButton.gameObject.SetActive(_isVisible);
