[RequireComponent(typeof(Tool))]
public class ToolCleanup : Photon.MonoBehaviour
{
	[Tooltip("Min distance from original spawn position before a tool is considered eligible for cleanup")]
	public float MinDisplacementBeforeCleanup = 0.1f;

	[Tooltip("Min distance from the closest player before a tool is considered eligible for cleanup")]
	public float MinPlayerDistanceBeforeCleanup = 3f;

	[Tooltip("Delay before eligible tools are cleaned up")]
	public float DelayUntilCleanup = 15f;

	private Tool tool;

	private Vector3 originalPosition;

	private Quaternion originalRotation;

	private bool isResetting;

	private bool hasMoved;

	private float resetTimerStart;

	private void Awake()
	{
		tool = GetComponent<Tool>();
		tool.ResetEvent += OnReset;
		OnReset(tool);
	}

	private void OnReset(Tool tool)
	{
		ResetCleanupOriginalPosition();
	}

	public void ResetCleanupOriginalPosition()
	{
		isResetting = false;
		hasMoved = false;
		originalPosition = base.transform.position;
		originalRotation = base.transform.rotation;
	}

	public void CheckCleanup()
	{
		if (!isResetting)
		{
			if (!hasMoved || !base.hasAuthority || !base.gameObject.activeSelf)
			{
				hasMoved = Vector3.Distance(base.transform.position, originalPosition) > MinDisplacementBeforeCleanup;
				resetTimerStart = Time.time;
			}
			else if (tool.IsHeld || (MinPlayerDistanceBeforeCleanup > 0f && Player.IsCloseToAnyPlayer(base.transform.position, MinPlayerDistanceBeforeCleanup)))
			{
				resetTimerStart = Time.time;
			}
			else if (resetTimerStart + DelayUntilCleanup < Time.time)
			{
				isResetting = true;
				tool.ResetToDefault(originalPosition, originalRotation);
			}
		}
	}
}
[DisallowMultipleComponent]
public class ToolCleanupManager : SingletonMonoBehaviour<ToolCleanupManager>
{
	[Tooltip("Min distance from original spawn position before a tool is considered eligible for cleanup")]
	[SerializeField]
	private float minDisplacementBeforeCleanup = 0.1f;

	[Tooltip("Min distance from the closest player before a tool is considered eligible for cleanup")]
	[SerializeField]
	private float minPlayerDistanceBeforeCleanup = 3f;

	[SerializeField]
	[Tooltip("Delay before eligible tools are cleaned up")]
	private float delayUntilCleanup = 15f;

	[Tooltip("Tools that should be excluded from cleanup")]
	[SerializeField]
	private Tool[] excludedTools;

	private int index;

	private List<ToolCleanup> tools;

	private void Awake()
	{
		SingletonMonoBehaviour<ToolCleanupManager>.Instance = this;
	}

	private void Start()
	{
		if (excludedTools == null)
		{
			excludedTools = new Tool[0];
		}
		tools = new List<ToolCleanup>();
		GameObject[] rootGameObjects = SceneManager.GetActiveScene().GetRootGameObjects();
		foreach (GameObject gameObject in rootGameObjects)
		{
			Tool[] componentsInChildren = gameObject.GetComponentsInChildren<Tool>(includeInactive: true);
			foreach (Tool tool in componentsInChildren)
			{
				AddToolHelper(tool);
			}
		}
		if (tools.Count == 0)
		{
			base.enabled = false;
		}
	}

	private void Update()
	{
		if (tools != null && tools.Count != 0)
		{
			index %= tools.Count;
			if (tools[index] == null || tools[index].gameObject == null)
			{
				tools.RemoveAt(index);
				index %= tools.Count;
			}
			else
			{
				tools[index].CheckCleanup();
				index = (index + 1) % tools.Count;
			}
		}
	}

	public void AddTool(Tool tool)
	{
		AddToolHelper(tool);
	}

	public void RemoveTool(Tool tool)
	{
		ToolCleanup cleanup = tool.GetComponent<ToolCleanup>();
		if (cleanup == null)
		{
			return;
		}
		int num = tools.FindIndex((ToolCleanup c) => c == cleanup);
		if (num < 0)
		{
			return;
		}
		tools.RemoveAt(num);
		if (tools.Count == 0)
		{
			index = 0;
			return;
		}
		if (num < index)
		{
			index--;
		}
		index %= tools.Count;
	}

	private void AddToolHelper(Tool tool)
	{
		if (tool.IsOnline && !excludedTools.Contains(tool))
		{
			ToolCleanup toolCleanup = tool.GetComponent<ToolCleanup>();
			if (toolCleanup == null)
			{
				toolCleanup = tool.gameObject.AddComponent<ToolCleanup>();
				toolCleanup.MinDisplacementBeforeCleanup = minDisplacementBeforeCleanup;
				toolCleanup.MinPlayerDistanceBeforeCleanup = minPlayerDistanceBeforeCleanup;
				toolCleanup.DelayUntilCleanup = delayUntilCleanup;
			}
			tools.Add(toolCleanup);
		}
	}
}
public class ModeratorActivityDebugMenu : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private UIDebugRoomPanel roomPanelPrefab;

	[SerializeField]
	private RectTransform panelRoot;

	[SerializeField]
	private Text extraInfo;

	[SerializeField]
	private RectTransform noRoomsPanel;

	private List<UIDebugRoomPanel> roomPanels;

	private Canvas canvas;

	private Vector2 gameListScrollViewPos;

	private bool touchpadButton
	{
		get
		{
			if (SingletonMonoBehaviour<CameraRig>.Instance != null)
			{
				ControllerIO leftHandControllerIO = SingletonMonoBehaviour<CameraRig>.Instance.LeftHandControllerIO;
				ControllerIO rightHandControllerIO = SingletonMonoBehaviour<CameraRig>.Instance.RightHandControllerIO;
				return (leftHandControllerIO != null && leftHandControllerIO.TeleportButtonDown) || (rightHandControllerIO != null && rightHandControllerIO.TeleportButtonDown);
			}
			return false;
		}
	}

	private void Start()
	{
		roomPanelPrefab.gameObject.SetActive(value: false);
		roomPanels = new List<UIDebugRoomPanel>();
		canvas = GetComponent<Canvas>();
		InvokeRepeating("UpdateRooms", 0.1f, 1f);
	}

	private void Update()
	{
		if (canvas.worldCamera == null && ViveControllerInput.Instance != null && ViveControllerInput.Instance.ControllerCamera != null)
		{
			canvas.worldCamera = ViveControllerInput.Instance.ControllerCamera;
		}
		if (touchpadButton)
		{
			UpdateMenuPosition();
		}
	}

	private void UpdateRooms()
	{
		RoomInfo[] array = null;
		if (PhotonNetwork.insideLobby)
		{
			array = PhotonNetwork.GetRoomList();
		}
		if (array != null && array.Length > 0)
		{
			RoomInfo[] array2 = array;
			foreach (RoomInfo roomInfo in array2)
			{
				if (string.IsNullOrEmpty(roomInfo.name) || roomInfo.playerCount == 0)
				{
					return;
				}
				bool flag = true;
				foreach (UIDebugRoomPanel roomPanel in roomPanels)
				{
					if (roomPanel.Room.name == roomInfo.name)
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					AddRoomPanel(roomInfo);
				}
			}
		}
		UIDebugRoomPanel[] array3 = roomPanels.ToArray();
		foreach (UIDebugRoomPanel uIDebugRoomPanel in array3)
		{
			bool flag2 = false;
			RoomInfo[] array4 = array;
			foreach (RoomInfo roomInfo2 in array4)
			{
				if (uIDebugRoomPanel.Room.name == roomInfo2.name)
				{
					flag2 = true;
					break;
				}
			}
			if (!flag2)
			{
				roomPanels.Remove(uIDebugRoomPanel);
				UnityEngine.Object.Destroy(uIDebugRoomPanel.gameObject);
			}
		}
		noRoomsPanel.gameObject.SetActive(roomPanels.Count == 0);
	}

	private void AddRoomPanel(RoomInfo room)
	{
		if (room != null)
		{
			UIDebugRoomPanel uIDebugRoomPanel = UnityEngine.Object.Instantiate(roomPanelPrefab);
			uIDebugRoomPanel.transform.SetParent(panelRoot, worldPositionStays: false);
			uIDebugRoomPanel.gameObject.SetActive(value: true);
			uIDebugRoomPanel.Room = room;
			uIDebugRoomPanel.ParentMenu = this;
			roomPanels.Add(uIDebugRoomPanel);
		}
	}

	private void UpdateMenuPosition()
	{
		Transform transform = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform;
		base.transform.rotation = Quaternion.Euler(0f, transform.rotation.eulerAngles.y, 0f);
		base.transform.position = transform.position + base.transform.forward * 2.5f;
	}

	public void Button_JoinRandomActivity()
	{
		ActivityManager.Instance.SwitchActivity(null);
	}

	private void OnGUI()
	{
		if (!PhotonNetwork.insideLobby)
		{
			return;
		}
		GUILayout.BeginArea(new Rect(5f, 5f, Screen.width - 10, Screen.height - 10));
		gameListScrollViewPos = GUILayout.BeginScrollView(gameListScrollViewPos);
		RoomInfo[] roomList = PhotonNetwork.GetRoomList();
		if (roomList != null && roomList.Length > 0)
		{
			if (GUILayout.Button("Create a new RecRoom", GUILayout.Width(200f)))
			{
				PUNNetworkManager.Instance.SwitchActivity("lockerroom");
			}
			GUILayout.Space(10f);
			RoomInfo[] array = roomList;
			foreach (RoomInfo roomInfo in array)
			{
				GUILayout.BeginHorizontal();
				GUI.enabled = roomInfo.playerCount < roomInfo.maxPlayers;
				if (GUILayout.Button("Join room", GUILayout.ExpandWidth(expand: false)))
				{
					PUNNetworkManager.Instance.JoinRoom(roomInfo.name);
				}
				GUI.enabled = true;
				if (GUILayout.Button("More info", GUILayout.ExpandWidth(expand: false)))
				{
					PrintExtraInfo(roomInfo);
				}
				string text = string.Format("{0}/{1} players | {2} | {3}", roomInfo.playerCount, roomInfo.maxPlayers, (string)roomInfo.customProperties["C0"], (string)roomInfo.customProperties["C1"]);
				GUILayout.Label(text);
				GUILayout.EndHorizontal();
			}
		}
		else
		{
			GUILayout.Box("NOBODY is playing :(");
		}
		GUILayout.EndScrollView();
		GUILayout.EndArea();
	}

	public void PrintExtraInfo(RoomInfo room)
	{
		StopAllCoroutines();
		StartCoroutine(RunPrintExtraInfo(room));
	}

	public IEnumerator RunPrintExtraInfo(RoomInfo room)
	{
		extraInfo.text = "Loading...";
		if (!room.customProperties.ContainsKey("C6"))
		{
			yield break;
		}
		string steamIdString = null;
		try
		{
			steamIdString = (string)room.customProperties["C6"];
		}
		catch (Exception ex)
		{
			Exception ex2 = ex;
			UnityEngine.Debug.LogException(ex2);
			extraInfo.text = "Failed" + Environment.NewLine + ex2.Message;
			yield break;
		}
		string[] steamIds = steamIdString.Split(',');
		extraInfo.text = "Loading...";
		string menuText = (string)room.customProperties["C0"] + "/" + (string)room.customProperties["C1"] + ":" + Environment.NewLine;
		string[] array = steamIds;
		foreach (string steamId in array)
		{
			if (!string.IsNullOrEmpty(steamId) && ulong.TryParse(steamId, out var id))
			{
				CSteamID cId = new CSteamID(id);
				while (SteamFriends.RequestUserInformation(new CSteamID(id), bRequireNameOnly: true))
				{
					yield return null;
				}
				PrintFriendInfo(cId);
				menuText = menuText + ">" + SteamFriends.GetFriendPersonaName(cId) + Environment.NewLine;
				extraInfo.text = menuText;
			}
		}
	}

	private void PrintFriendInfo(CSteamID steamId)
	{
		string friendPersonaName = SteamFriends.GetFriendPersonaName(steamId);
		UnityEngine.Debug.Log(string.Concat(friendPersonaName, " - ", SteamFriends.GetFriendPersonaState(steamId), " - ", SteamFriends.GetFriendRelationship(steamId), " - level :", SteamFriends.GetFriendSteamLevel(steamId)));
		int friendRichPresenceKeyCount = SteamFriends.GetFriendRichPresenceKeyCount(steamId);
		for (int i = 0; i < friendRichPresenceKeyCount; i++)
		{
			string friendRichPresenceKeyByIndex = SteamFriends.GetFriendRichPresenceKeyByIndex(steamId, i);
			UnityEngine.Debug.Log("\t\t" + i + " - " + friendRichPresenceKeyByIndex);
		}
	}
}
