public class PaddleballActivityManager : ActivityManager
{
	private const string SCORING_PLAYER_KEY = "SCORING_PLAYER";

	private const string ROUND_RUNNING_KEY = "ROUND_RUNNING";

	[SerializeField]
	private Goal[] goals;

	[SerializeField]
	private PaddleballBall ball;

	[SerializeField]
	private PaddleballPaddle[] paddles;

	[SerializeField]
	private PlayerGameObjectMap ballSpawnPoints;

	[SerializeField]
	private int scoreOnGoal = 5;

	[SerializeField]
	private int scoreToWin = 25;

	[SerializeField]
	private ParticleSystem goalParticles;

	protected override bool PlayerRequirementsMet => base.PlayerManager.GetActivePlayers().Length > 1;

	protected override void OnServerActivityLoad()
	{
	}

	protected override void OnClientActivityLoad()
	{
		Goal[] array = goals;
		foreach (Goal goal in array)
		{
			goal.NetworkCollider.ServerToolTriggerEnterEvent += MasterOnGoalTriggerEnter;
		}
		ball.NetworkTransform.CurrentExtrapolationMode = PUNNetworkTransform.ExtrapolationMode.DynamicDistance;
		ball.Rigidbody.useGravity = false;
	}

	protected override void OnServerActivityDestroy()
	{
		Goal[] array = goals;
		foreach (Goal goal in array)
		{
			if ((bool)goal)
			{
				goal.NetworkCollider.ServerToolTriggerEnterEvent -= MasterOnGoalTriggerEnter;
			}
		}
	}

	protected override IEnumerator PreGameStateCoroutine()
	{
		base.PlayerManager.MasterResetPlayerScores();
		MasterRespawnAllActivePlayers();
		yield break;
	}

	protected override IEnumerator PlayingGameStateCoroutine()
	{
		Goal[] array = goals;
		foreach (Goal goal in array)
		{
			int ownerSlot = goal.OwnerPlayerSlot;
			PhotonPlayer owner = base.PlayerManager.GetPlayerAtActiveSlot(ownerSlot);
			if (owner == null)
			{
				goal.photonView.TransferOwnership(PhotonNetwork.masterClient);
			}
			else
			{
				goal.photonView.TransferOwnership(owner);
			}
		}
		base.PlayerManager.MasterResetPlayerScores();
		ball.Disable();
		PaddleballPaddle[] array2 = paddles;
		foreach (PaddleballPaddle paddle in array2)
		{
			paddle.ResetToLastSpawnPosition();
		}
		SetIsRoundRunning(isRunning: false);
		SetLastScoringPlayer(null);
		yield return MasterRespawnAllActivePlayers();
		yield return new WaitForSeconds(2f);
		MasterTryUpdateGame();
	}

	protected override void MasterTryUpdateGame()
	{
		if (PhotonNetwork.isMasterClient && !GetIsRoundRunning())
		{
			PhotonPlayer lastScoringPlayer = GetLastScoringPlayer();
			int num = ((lastScoringPlayer != null) ? base.PlayerManager.GetPlayerScore(lastScoringPlayer) : 0);
			if (num >= scoreToWin)
			{
				MasterGameOver(lastScoringPlayer);
			}
			else
			{
				MasterServe();
			}
		}
	}

	private bool GetIsRoundRunning()
	{
		return base.ActivityData.GetData("ROUND_RUNNING", defaultValue: false);
	}

	private void SetIsRoundRunning(bool isRunning)
	{
		base.ActivityData.SetData("ROUND_RUNNING", isRunning);
	}

	private void MasterServe()
	{
		if (PhotonNetwork.isMasterClient)
		{
			StartCoroutine(ServeCoroutine());
		}
	}

	private IEnumerator ServeCoroutine()
	{
		int lastScoringPlayerScore = 0;
		PhotonPlayer lastScoringPlayer = GetLastScoringPlayer();
		if (lastScoringPlayer != null)
		{
			lastScoringPlayerScore = base.PlayerManager.GetPlayerScore(lastScoringPlayer);
			SetLastScoringPlayer(null);
		}
		SetIsRoundRunning(isRunning: true);
		Player servingPlayer = GetServingPlayer(lastScoringPlayer == null, lastScoringPlayer).ToPlayer();
		ResetBall(servingPlayer);
		MasterPlaySoundAllPlayers("start_playing_activity");
		yield return MasterShowNotificationAllPlayers(servingPlayer.PlayerName + "'s Serve!", 2f);
		if (lastScoringPlayerScore == scoreToWin - 1)
		{
			MasterShowNotificationAllPlayers("Match Point!", 2f);
		}
	}

	private void MasterGameOver(PhotonPlayer winner)
	{
		if (PhotonNetwork.isMasterClient)
		{
			StartCoroutine(GameOverCoroutine(winner));
		}
	}

	private IEnumerator GameOverCoroutine(PhotonPlayer winner)
	{
		MasterActivityWon(winner);
		yield return new WaitForSeconds(1f);
		yield return MasterShowNotificationAllPlayers("Game Over!", 2f);
		yield return MasterShowNotificationAllPlayers(winner.name + " Wins!", 3f);
		MasterPlaySoundAllPlayers("stop_music");
		MasterEnterGameState(ActivityGameState.PreGame);
	}

	private void ResetBall(Player servingPlayer)
	{
		GameObject forPlayer = ballSpawnPoints.GetForPlayer(ActivityManager.Instance.PlayerManager.GetPlayerSlot(servingPlayer.PhotonPlayer));
		if (!(forPlayer == null))
		{
			ball.ResetToDefault(forPlayer.transform.position, forPlayer.transform.rotation);
		}
	}

	private void MasterOnGoalTriggerEnter(GameObject goalGameObject, Tool tool, Vector3 point)
	{
		if (!PhotonNetwork.isMasterClient || base.GameState != ActivityGameState.PlayingGame || GetLastScoringPlayer() != null || tool != ball)
		{
			return;
		}
		Goal component = goalGameObject.GetComponent<Goal>();
		if (component != null)
		{
			PhotonPlayer playerAtActiveSlot = base.PlayerManager.GetPlayerAtActiveSlot(component.OwnerPlayerSlot);
			PhotonPlayer otherPlayer = GetOtherPlayer(playerAtActiveSlot);
			if (otherPlayer != null)
			{
				MasterPlayerScored(otherPlayer.ToPlayer(), point);
			}
		}
	}

	private void MasterPlayerScored(Player scorer, Vector3 goalHitPosition)
	{
		if (PhotonNetwork.isMasterClient)
		{
			StartCoroutine(PlayerScoredCoroutine(scorer, goalHitPosition));
		}
	}

	private IEnumerator PlayerScoredCoroutine(Player scorer, Vector3 goalHitPosition)
	{
		SetIsRoundRunning(isRunning: false);
		ball.Disable();
		base.photonView.RPC("RpcPlayGoalParticles", PhotonTargets.All, goalHitPosition);
		base.PlayerManager.MasterAddPlayerScore(scorer.PhotonPlayer, scoreOnGoal);
		int score = base.PlayerManager.GetPlayerScore(scorer.PhotonPlayer);
		SetLastScoringPlayer(scorer);
		if (score < scoreToWin)
		{
			MasterPlaySoundAllPlayers("score");
			yield return MasterShowNotificationAllPlayers(scorer.PlayerName + " Scored!", 2f);
			yield return new WaitForSeconds(1f);
		}
		MasterTryUpdateGame();
	}

	[PunRPC]
	public void RpcPlayGoalParticles(Vector3 hitPosition)
	{
		base.ActivityAudio.OnScore();
		goalParticles.transform.position = hitPosition;
		goalParticles.Play();
	}

	private PhotonPlayer GetServingPlayer(bool firstServe, PhotonPlayer lastScoringPlayer)
	{
		PhotonPlayer[] activePlayersSortedBySlot = base.PlayerManager.GetActivePlayersSortedBySlot();
		if (activePlayersSortedBySlot != null)
		{
			if (firstServe || activePlayersSortedBySlot.Length == 1)
			{
				return activePlayersSortedBySlot[0];
			}
			PhotonPlayer[] array = activePlayersSortedBySlot;
			foreach (PhotonPlayer photonPlayer in array)
			{
				if (photonPlayer != lastScoringPlayer)
				{
					return photonPlayer;
				}
			}
		}
		return null;
	}

	private PhotonPlayer GetOtherPlayer(PhotonPlayer excludedPlayer)
	{
		PhotonPlayer[] activePlayersSortedBySlot = base.PlayerManager.GetActivePlayersSortedBySlot();
		foreach (PhotonPlayer photonPlayer in activePlayersSortedBySlot)
		{
			if (photonPlayer != excludedPlayer)
			{
				return photonPlayer;
			}
		}
		return null;
	}

	private PhotonPlayer GetLastScoringPlayer()
	{
		int data = base.ActivityData.GetData("SCORING_PLAYER", -1);
		if (data == -1)
		{
			return null;
		}
		return base.PlayerManager.GetPlayerAtActiveSlot(data);
	}

	private void SetLastScoringPlayer(Player lastScoringPlayer)
	{
		int data = ((!(lastScoringPlayer == null)) ? base.PlayerManager.GetPlayerSlot(lastScoringPlayer.PhotonPlayer) : (-1));
		base.ActivityData.SetData("SCORING_PLAYER", data);
	}
