public class PaddleballPaddleCollider : ToolCollider
{
	public override Vector3 GetCollisionNormal(Collision collision)
	{
		Vector3 recentLinearVelocity = ThisTrackedVelocity.RecentLinearVelocity;
		if (recentLinearVelocity.magnitude < 0.5f)
		{
			return (!(Vector3.Dot(collision.relativeVelocity, base.transform.forward) < 0f)) ? base.transform.forward : (-base.transform.forward);
		}
		return (!(Vector3.Dot(recentLinearVelocity, base.transform.forward) < 0f)) ? base.transform.forward : (-base.transform.forward);
	}
}
public class Bullet : UnityEngine.MonoBehaviour
{
	public delegate void PlayerImpact(Bullet thisBullet, Player hitPlayer, Player.BodyPart hitBodyPart, Vector3 impactPoint);

	public delegate void PlayerGunImpact(Bullet thisBullet, Player hitPlayer, Gun hitGun, Vector3 impactPoint);

	public delegate void OtherImpact(Bullet thisBullet, Vector3 impactPoint);

	[Header("Physics")]
	[SerializeField]
	private float mass = 0.1f;

	[SerializeField]
	private float colliderRadius = 0.033f;

	[SerializeField]
	private ImpactDecal impactDecalPrefab;

	[SerializeField]
	[Header("Trails")]
	private TrailRenderer blueTrail;

	[SerializeField]
	private TrailRenderer redTrail;

	[SerializeField]
	[Header("Cleanup")]
	private float selfDestructTime = 10f;

	[SerializeField]
	private Renderer[] renderers;

	private float fireTime;

	private Vector3 velocity = Vector3.zero;

	private Rigidbody gunRigidbody;

	private Color _color;

	[HideInInspector]
	public Player Shooter;

	private RaycastHit[] hits;

	private RaycastHitComparer raycastHitComparer;

	public Color Color
	{
		get
		{
			return _color;
		}
		set
		{
			_color = value;
			Renderer[] array = renderers;
			foreach (Renderer renderer in array)
			{
				renderer.material.color = _color;
			}
			if (_color.r > _color.b)
			{
				redTrail.gameObject.SetActive(value: true);
				blueTrail.gameObject.SetActive(value: false);
			}
			else
			{
				blueTrail.gameObject.SetActive(value: true);
				redTrail.gameObject.SetActive(value: false);
			}
		}
	}

	public event Action<Bullet> DestroyEvent;

	public event PlayerImpact PlayerImpactEvent;

	public event PlayerGunImpact PlayerGunImpactEvent;

	public event OtherImpact OtherImpactEvent;

	public void Fire(Vector3 position, Quaternion rotation, Vector3 velocity, Rigidbody gunRigidody)
	{
		base.enabled = true;
		blueTrail.Clear();
		redTrail.Clear();
		base.transform.position = position;
		base.transform.rotation = rotation;
		this.velocity = velocity;
		gunRigidbody = gunRigidody;
		fireTime = Time.time;
	}

	private void Awake()
	{
		base.enabled = false;
		SingletonMonoBehaviour<ObjectPool>.Instance.RegisterObjectPrefab(impactDecalPrefab.gameObject);
		redTrail.gameObject.SetActive(value: false);
		blueTrail.gameObject.SetActive(value: false);
		hits = new RaycastHit[20];
		raycastHitComparer = new RaycastHitComparer();
	}

	private void ReleaseBullet()
	{
		SingletonMonoBehaviour<ObjectPool>.Instance.Release(base.gameObject);
		if (this.DestroyEvent != null)
		{
			this.DestroyEvent(this);
		}
	}

	private void Update()
	{
		if (Time.time - fireTime >= selfDestructTime)
		{
			ReleaseBullet();
			return;
		}
		Vector3 position = base.transform.position;
		base.transform.position += velocity * Time.deltaTime;
		velocity += Physics.gravity * Time.deltaTime;
		Vector3 vector = base.transform.position - position;
		if (vector.sqrMagnitude <= Mathf.Epsilon || !Physics.CheckCapsule(position, base.transform.position, colliderRadius, 1457664, QueryTriggerInteraction.Ignore))
		{
			return;
		}
		float magnitude = vector.magnitude;
		Vector3 direction = vector / magnitude;
		int num = Physics.SphereCastNonAlloc(position, colliderRadius, direction, hits, magnitude, 1457664, QueryTriggerInteraction.Ignore);
		if (hits == null || num == 0)
		{
			return;
		}
		Array.Sort(hits, 0, num, raycastHitComparer);
		for (int i = 0; i < num; i++)
		{
			if (!(hits[i].rigidbody == gunRigidbody))
			{
				if (hits[i].distance != 0f)
				{
					Vector3 vector2 = mass * velocity;
					Vector3 collisionForce = vector2 / Time.deltaTime;
					OnRaycastCollisionEnter(collisionForce, hits[i]);
					break;
				}
				ReleaseBullet();
			}
		}
	}

	private void OnRaycastCollisionEnter(Vector3 collisionForce, RaycastHit raycastCollision)
	{
		Player player = null;
		Tool tool = null;
		if ((player = raycastCollision.collider.GetColliderPlayer(out var bodyPart)) != null)
		{
			OnPlayerHit(player, bodyPart, raycastCollision.point);
		}
		else if ((tool = raycastCollision.collider.GetColliderTool()) != null)
		{
			OnToolHit(tool, raycastCollision.point);
		}
		else
		{
			OnOtherHit(raycastCollision.point);
		}
		GameObject gameObject = null;
		if (raycastCollision.rigidbody != null)
		{
			gameObject = raycastCollision.rigidbody.gameObject;
			raycastCollision.rigidbody.AddForceAtPosition(collisionForce, raycastCollision.point);
		}
		else
		{
			gameObject = raycastCollision.collider.gameObject;
		}
		SpawnImpactDecal(raycastCollision.point, raycastCollision.normal, gameObject);
		ReleaseBullet();
	}

	private void SpawnImpactDecal(Vector3 position, Vector3 normal, GameObject hitGameObject)
	{
		ImpactDecal impactDecal = SingletonMonoBehaviour<ObjectPool>.Instance.Acquire<ImpactDecal>(impactDecalPrefab.name);
		if (impactDecal != null)
		{
			impactDecal.Color = Color;
			impactDecal.Splat(position, normal, hitGameObject);
		}
	}

	private bool IsValidPlayerHit(Player hitPlayer)
	{
		bool flag = ActivityManager.Instance != null && ActivityManager.Instance.PlayerManager.IsPlayerSpectator(hitPlayer.PhotonPlayer);
		bool flag2 = ActivityManager.Instance != null && ActivityManager.Instance.PlayerManager.IsPlayerSpectator(Shooter.PhotonPlayer);
		return hitPlayer != Shooter && !flag && !flag2 && (Shooter.isLocal || hitPlayer.isLocal);
	}

	private void OnPlayerHit(Player hitPlayer, Player.BodyPart hitBodyPart, Vector3 impactPoint)
	{
		if (IsValidPlayerHit(hitPlayer) && this.PlayerImpactEvent != null)
		{
			this.PlayerImpactEvent(this, hitPlayer, hitBodyPart, impactPoint);
		}
	}

	private void OnToolHit(Tool tool, Vector3 impactPoint)
	{
		Gun component = tool.GetComponent<Gun>();
		if (component != null && component.IsHeld && IsValidPlayerHit(component.Owner) && this.PlayerGunImpactEvent != null)
		{
			this.PlayerGunImpactEvent(this, component.Owner, component, impactPoint);
			return;
		}
		if (tool.OwnershipTransferAllowed && tool.IsOnline && !tool.IsHeld && Shooter.photonView.isOwnerActive && tool.photonView.ownerId != Shooter.photonView.ownerId)
		{
			tool.photonView.TransferOwnership(Shooter.photonView.ownerId);
		}
		if (this.OtherImpactEvent != null)
		{
			this.OtherImpactEvent(this, impactPoint);
		}
	}

	private void OnOtherHit(Vector3 impactPoint)
	{
		if (this.OtherImpactEvent != null)
		{
			this.OtherImpactEvent(this, impactPoint);
		}
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = Color.green;
		Gizmos.DrawWireSphere(base.transform.position, colliderRadius);
	}
}
