public class Gun : Tool
{
	[SerializeField]
	private bool gunHitsEnabled = true;

	[SerializeField]
	[Header("Visuals")]
	private PooledParticle muzzleFlashPrefab;

	[SerializeField]
	private PulsingBeam pulsingBeam;

	[Header("Barrel")]
	[SerializeField]
	private Transform barrelTransform;

	[Header("Bullets")]
	[SerializeField]
	private Bullet bulletPrefab;

	[SerializeField]
	private float bulletFireSpeed = 10f;

	[SerializeField]
	private float maximumFiringRate = 10f;

	[SerializeField]
	private float automaticFiringRate = 10f;

	[Header("Misfire")]
	[SerializeField]
	private BoxCollider worldOverlapCollider;

	[HideInInspector]
	public bool SpawnedFromPool;

	private PaintballActivityManager activityManager;

	private GunAudio gunAudio;

	private Animator animator;

	private GunRenderer gunRenderer;

	private static readonly int triggerId = Animator.StringToHash("Trigger");

	private float triggerAmount;

	private float lastFireTime;

	private float TimeSinceLastFire => Time.time - lastFireTime;

	private bool IsOutOfBounds => worldOverlapCollider.CheckOverlap(2048, QueryTriggerInteraction.Ignore) || !ActivityBounds.PointInBounds(base.transform.position);

	private bool IsMisfire => IsOutOfBounds || (base.IsHeld && base.Owner != null && (base.Owner.IsOutOfBounds || base.Owner.IsOverlappingWorld));

	protected override void Awake()
	{
		base.Awake();
		gunAudio = GetComponent<GunAudio>();
		animator = GetComponentInChildren<Animator>();
		gunRenderer = GetComponent<GunRenderer>();
	}

	protected override void Start()
	{
		base.Start();
		activityManager = ActivityManager.Instance as PaintballActivityManager;
		SingletonMonoBehaviour<ObjectPool>.Instance.RegisterObjectPrefab(bulletPrefab.gameObject);
		SingletonMonoBehaviour<ObjectPool>.Instance.RegisterObjectPrefab(muzzleFlashPrefab.gameObject);
		if (SpawnedFromPool)
		{
			pulsingBeam.gameObject.SetActive(value: false);
			autoLock = true;
		}
		else
		{
			pulsingBeam.gameObject.SetActive(value: true);
		}
	}

	private void Update()
	{
		if (base.hasAuthority)
		{
			triggerAmount = InputAmount;
			animator.SetFloat(triggerId, triggerAmount);
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
		UpdateColor();
		pulsingBeam.gameObject.SetActive(value: false);
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
	}

	protected override void Reset(Vector3 position, Quaternion rotation, double networkTimestamp)
	{
		gunRenderer.ResetAccentColor();
		if (!SpawnedFromPool)
		{
			pulsingBeam.gameObject.SetActive(value: true);
		}
		base.Reset(position, rotation, networkTimestamp);
	}

	public override void OnOwnerRoleUpdated()
	{
		UpdateColor();
	}

	public override void OnInputDown()
	{
		base.OnInputDown();
		if (base.hasAuthority && maximumFiringRate >= 0f && TimeSinceLastFire >= 1f / maximumFiringRate)
		{
			Fire();
		}
	}

	public override void OnInputPressed()
	{
		base.OnInputPressed();
		if (base.hasAuthority && automaticFiringRate > 0f && TimeSinceLastFire >= 1f / automaticFiringRate)
		{
			Fire();
		}
	}

	private void UpdateColor()
	{
		ActivityTeam activityTeam = ((!(base.Owner != null)) ? null : base.Owner.Team);
		if (activityTeam != null)
		{
			gunRenderer.AccentColor = activityTeam.Color;
		}
		else
		{
			gunRenderer.ResetAccentColor();
		}
	}

	public void Fire()
	{
		lastFireTime = Time.time;
		base.photonView.RPC("RpcFireBullet", PhotonTargets.All, barrelTransform.position, barrelTransform.rotation, barrelTransform.forward * bulletFireSpeed, IsMisfire);
	}

	private Bullet FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, bool isMisfire)
	{
		if (isMisfire)
		{
			gunAudio.OnMisfire();
			return null;
		}
		Bullet bullet = SingletonMonoBehaviour<ObjectPool>.Instance.Acquire<Bullet>(bulletPrefab.name);
		if (bullet != null)
		{
			bullet.Shooter = base.Owner;
			bullet.DestroyEvent += OnBulletDestroy;
			bullet.PlayerImpactEvent += OnBulletPlayerImpact;
			bullet.PlayerGunImpactEvent += OnBulletPlayerGunImpact;
			bullet.OtherImpactEvent += OnBulletOtherImpact;
			bullet.Color = gunRenderer.AccentColor;
			bullet.Fire(position, rotation, velocity, base.Rigidbody);
			PooledParticle pooledParticle = SingletonMonoBehaviour<ObjectPool>.Instance.Acquire<PooledParticle>(muzzleFlashPrefab.name);
			if (pooledParticle != null)
			{
				pooledParticle.transform.position = barrelTransform.position;
				pooledParticle.transform.rotation = barrelTransform.rotation;
				pooledParticle.Play();
			}
			gunAudio.OnFire();
		}
		return bullet;
	}

	private void OnBulletDestroy(Bullet bullet)
	{
		bullet.DestroyEvent -= OnBulletDestroy;
		bullet.PlayerImpactEvent -= OnBulletPlayerImpact;
		bullet.PlayerGunImpactEvent -= OnBulletPlayerGunImpact;
		bullet.OtherImpactEvent -= OnBulletOtherImpact;
	}

	private void OnBulletPlayerImpact(Bullet bullet, Player player, Player.BodyPart bodyPart, Vector3 position)
	{
		gunAudio.OnBulletHitPlayer(position);
		if (activityManager != null)
		{
			activityManager.PlayerHit(player, bodyPart, bullet.Shooter, position);
		}
	}

	private void OnBulletPlayerGunImpact(Bullet bullet, Player hitPlayer, Gun hitGun, Vector3 position)
	{
		if (gunHitsEnabled)
		{
			gunAudio.OnBulletHitPlayer(position);
			if (activityManager != null)
			{
				activityManager.PlayerHit(hitPlayer, Player.BodyPart.None, bullet.Shooter, position);
			}
		}
		else
		{
			OnBulletOtherImpact(bullet, position);
		}
	}

	private void OnBulletOtherImpact(Bullet bullet, Vector3 position)
	{
		gunAudio.OnBulletHitEnvironment(position);
	}

	[PunRPC]
	public void RpcFireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, bool misFire)
	{
		FireBullet(position, rotation, velocity, IsMisfire);
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading)
		{
			triggerAmount = (float)stream.ReceiveNext();
			if (animator.isActiveAndEnabled)
			{
				animator.SetFloat(triggerId, triggerAmount);
			}
		}
		else
		{
			stream.SendNext(triggerAmount);
		}
	}
}
