	{
		PlayGameEventAudio(blueFlagTaken);
	}

	public void OnPlayerHit()
	{
		PlayGameEventAudio(playerHit);
	}

	public void OnPlayerOut()
	{
		PlayGameEventAudio(playerOut);
	}

	public void OnPlayerDamaged(Vector3 position)
	{
		PlayGameEventAudio3D(playerDamaged, position);
	}
}
public class PaintballActivityManager : ActivityManager
{
	[Serializable]
	private struct DamageSetting
	{
		public Player.BodyPart BodyPart;

		public int Damage;
	}

	[Serializable]
	private struct CTFTeamSettings
	{
		public int TeamId;

		public FlagTool Flag;

		public Transform GoalPosition;

		public float GoalRadius;

		public Transform HomePosition;

		public float HomeRadius;
	}

	public enum GameMode
	{
		TeamBattle,
		CaptureTheFlag,
		None
	}

	private const string RESETTING_FLAGS_KEY = "RESETTING_FLAGS";

	private const string PLAYER_HEALTH_KEY = "PLAYER_HEALTH";

	private const string GAME_MODE_KEY = "GAME_MODE";

	private const string PLAYER_INVINCIBLE_KEY = "PLAYER_INVINCIBLE";

	private const string PLAYER_KILLS_KEY = "PLAYER_KILLS";

	private const string PLAYER_DEATHS_KEY = "PLAYER_DEATHS";

	private const string PLAYER_FLAGS_KEY = "PLAYER_FLAGS";

	private Coroutine localPlayerOutOfBoundsCoroutine;

	[SerializeField]
	private NetworkedGameObjectPool playerGunPool;

	[Header("Combat")]
	[SerializeField]
	private int playerSpawnHealth = 100;

	[SerializeField]
	private DamageSetting[] damageSettings;

	[SerializeField]
	private bool friendlyFireEnabled;

	[Header("Team Battle")]
	[SerializeField]
	private int teamBattleScoreToWin = 50;

	[SerializeField]
	private float teamBattleMaximumGameTime = 600f;

	[Header("Capture The Flag")]
	[SerializeField]
	private int ctfScoreToWin = 3;

	[SerializeField]
	private CTFTeamSettings[] ctfTeamSettings;

	[SerializeField]
	private float ctfMaximumGameTime = 600f;

	[SerializeField]
	[Header("Rank")]
	private int killRank = 2;

	[SerializeField]
	private int deathRank = 1;

	[SerializeField]
	private int flagCaptureRank = 10;

	[SerializeField]
	[Header("Out of Bounds")]
	private float outOfBoundsRespawnDuration = 3f;

	[SerializeField]
	[Header("Notifications")]
	private float playerKilledFeedbackDuration = 1.5f;

	[SerializeField]
	private float playerKilledNotificationDuration = 3f;

	private PaintballActivityAudio paintballAudio;

	private bool playedOneMinuteRemainingVO;

	private bool playedTenSecondsRemainingVO;

	protected override bool PlayerRequirementsMet => base.PlayerManager.GetActiveTeams().Length > 1;

	protected override void OnServerActivityLoad()
	{
		for (int i = 0; i < ctfTeamSettings.Length; i++)
		{
			ctfTeamSettings[i].Flag.MasterSetGoal(ctfTeamSettings[i].GoalPosition.position, ctfTeamSettings[i].GoalRadius);
			ctfTeamSettings[i].Flag.MasterSetHome(ctfTeamSettings[i].HomePosition.position, ctfTeamSettings[i].HomeRadius);
			base.PlayerManager.MasterSetToolTeam(ctfTeamSettings[i].Flag, base.PlayerManager.GetTeam(ctfTeamSettings[i].TeamId));
		}
		SetGameMode(GameMode.CaptureTheFlag);
	}

	protected override void OnServerActivityDestroy()
	{
	}

	protected override void OnClientActivityLoad()
	{
		CTFTeamSettings[] array = ctfTeamSettings;
		for (int i = 0; i < array.Length; i++)
		{
			CTFTeamSettings cTFTeamSettings = array[i];
			cTFTeamSettings.Flag.Color = base.PlayerManager.GetTeam(cTFTeamSettings.TeamId).Color;
			cTFTeamSettings.Flag.ServerPickupEvent += OnFlagPickup;
			cTFTeamSettings.Flag.ServerReleaseEvent += OnFlagDrop;
			cTFTeamSettings.Flag.ResetEvent += OnFlagReset;
			cTFTeamSettings.Flag.InGoalEvent += OnFlagEnteredGoal;
		}
		GameObject[] pool = playerGunPool.Pool;
		foreach (GameObject gameObject in pool)
		{
			Gun component = gameObject.GetComponent<Gun>();
			component.ResetEvent += OnGunReset;
			component.SpawnedFromPool = true;
			ToolCleanup component2 = component.GetComponent<ToolCleanup>();
			component2.MinDisplacementBeforeCleanup = -1f;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		paintballAudio = GetComponent<PaintballActivityAudio>();
	}

	private void Update()
	{
		if (!PhotonNetwork.isMasterClient || base.GameState != ActivityGameState.PlayingGame || GetGameMode() != GameMode.CaptureTheFlag || GetAreFlagsResetting())
		{
			return;
		}
		for (int i = 0; i < ctfTeamSettings.Length; i++)
		{
			int num = (i + 1) % ctfTeamSettings.Length;
			if (ctfTeamSettings[i].Flag.IsAtHome() && !ctfTeamSettings[i].Flag.IsHeld && ctfTeamSettings[num].Flag.IsInGoal())
			{
				Player capturingPlayer = ctfTeamSettings[num].Flag.Owner;
				ActivityTeam team = base.PlayerManager.GetTeam(ctfTeamSettings[i].TeamId);
				OnFlagCaptured(capturingPlayer, team);
				break;
			}
		}
	}

	private void FixedUpdate()
	{
		if (base.GameState == ActivityGameState.PlayingGame)
		{
			float timeRemaining = GetTimeRemaining();
			if (timeRemaining <= 0f && PhotonNetwork.isMasterClient)
			{
				ActivityTeam maxScoreTeam = null;
				base.PlayerManager.GetMaxTeamScore(out maxScoreTeam);
				MasterGameOver(maxScoreTeam);
			}
			else if (timeRemaining <= 60f && timeRemaining + 1f > 60f && !playedOneMinuteRemainingVO)
			{
				paintballAudio.OnOneMinuteRemaining();
				playedOneMinuteRemainingVO = true;
			}
			else if (timeRemaining <= 10f && timeRemaining + 1f > 10f && !playedTenSecondsRemainingVO)
			{
				paintballAudio.OnTenSecondsRemaining();
				playedTenSecondsRemainingVO = true;
			}
		}
	}

	protected override IEnumerator PreGameStateCoroutine()
	{
		DisableAllFlags();
		base.PlayerManager.MasterResetTeamScores();
		yield break;
	}

	protected override void MasterTryUpdateGame()
	{
		if (PhotonNetwork.isMasterClient && base.GameState == ActivityGameState.PlayingGame)
		{
			switch (GetGameMode())
			{
			case GameMode.TeamBattle:
				UpdateTeamBattle();
				break;
			case GameMode.CaptureTheFlag:
				UpdateCaptureTheFlag();
				break;
			}
		}
	}

	protected override void MasterInitializePlayer(PhotonPlayer player)
	{
		base.MasterInitializePlayer(player);
		if (PhotonNetwork.isMasterClient)
		{
			if (GetGameMode() != GameMode.CaptureTheFlag || base.GameState == ActivityGameState.PreGame || base.GameState == ActivityGameState.Countdown)
			{
				DisableAllFlags();
			}
			if (base.GameState == ActivityGameState.PlayingGame && !base.PlayerManager.IsPlayerSpectator(player))
			{
				SetPlayerKills(player, 0);
				SetPlayerDeaths(player, 0);
				SetPlayerFlagCaptures(player, 0);
				base.photonView.RPC("RpcEnterGamePaintball", player);
			}
		}
	}

	private Coroutine RunPlayerEnterGame()
	{
		return StartCoroutine(RunPlayerEnterGameCoroutine());
	}

	private IEnumerator RunPlayerEnterGameCoroutine()
	{
		playedOneMinuteRemainingVO = false;
		playedTenSecondsRemainingVO = false;
		SetPlayerInvincibility(PhotonNetwork.player, invincible: true);
		Player.LocalPlayer.CanInteractWithTools = true;
		Player.LocalPlayer.PlayerLocomotion.TeleportEnabled = true;
		PlayerHand dominantHand = Player.LocalPlayer.DominantHand;
		base.photonView.RPC("RpcMasterRequestPlayerGunSpawn", PhotonTargets.MasterClient, PhotonNetwork.player, dominantHand.transform.position, dominantHand.transform.rotation);
		paintballAudio.StartPlayingMusic();
		yield return new WaitForSeconds(Player.SpawnDuration);
		SetPlayerInvincibility(PhotonNetwork.player, invincible: false);
		SetPlayerHealth(PhotonNetwork.player, playerSpawnHealth);
		ActivityTeam team = base.PlayerManager.GetPlayerTeam(PhotonNetwork.player);
		switch (GetGameMode())
		{
		case GameMode.CaptureTheFlag:
			paintballAudio.OnCaptureTheFlagStart();
			RpcShowNotification("Capture The Flag", "First team to " + ctfScoreToWin, 2f);
			yield return new WaitForSeconds(2f);
			break;
		case GameMode.TeamBattle:
			paintballAudio.OnTeamBattleStart();
			RpcShowNotification("Team Battle", "First team to " + teamBattleScoreToWin + " Hits", 2f);
			yield return new WaitForSeconds(2f);
			break;
		}
		if (team.IsBlueTeam)
		{
			paintballAudio.OnBlueTeamJoin();
		}
		else
		{
			paintballAudio.OnRedTeamJoin();
		}
		RpcShowNotification(team.Name + " Team", null, 2f);
		yield return new WaitForSeconds(2f);
	}

	protected override void MasterRemovePlayer(PhotonPlayer player)
	{
		base.MasterRemovePlayer(player);
		base.ActivityData.RemoveDataForPlayer(player, "PLAYER_KILLS");
		base.ActivityData.RemoveDataForPlayer(player, "PLAYER_DEATHS");
		base.ActivityData.RemoveDataForPlayer(player, "PLAYER_FLAGS");
	}

	protected override IEnumerator PlayingGameStateCoroutine()
	{
		switch (GetGameMode())
		{
		case GameMode.TeamBattle:
			StartGameTeamBattle();
			break;
		case GameMode.CaptureTheFlag:
			StartGameCaptureTheFlag();
			break;
		}
		yield break;
	}

	private void MasterGameOver(ActivityTeam winningTeam)
	{
		if (PhotonNetwork.isMasterClient)
		{
			ClearGameStartTime();
			MasterActivityWon(winningTeam);
			base.photonView.RPC("RpcOnGameOver", PhotonTargets.All, winningTeam?.Id ?? ActivityTeam.InvalidTeamId);
			MasterEnterGameState(ActivityGameState.PreGame);
		}
	}

	private void RunGameOver(ActivityTeam winningTeam)
	{
		StartCoroutine(RunGameOverCoroutine(winningTeam));
	}

	private IEnumerator RunGameOverCoroutine(ActivityTeam winningTeam)
	{
		if (winningTeam != null)
		{
			yield return new WaitForSeconds(3f);
		}
		RpcShowNotification("Game Over!", null, 2f);
		paintballAudio.StopPlayingMusic();
		paintballAudio.OnGameOver();
		yield return new WaitForSeconds(2f);
		if (winningTeam != null)
		{
			RpcShowNotification(winningTeam.Name + " Team Wins!", null, 3f);
			if (winningTeam.IsBlueTeam)
			{
				paintballAudio.OnBlueTeamWin();
			}
			else
			{
				paintballAudio.OnRedTeamWin();
			}
		}
		else
		{
			RpcShowNotification("Tie Game!", null, 3f);
			paintballAudio.OnTieGame();
		}
		yield return new WaitForSeconds(2f);
		base.photonView.RPC("RpcMasterRequestPlayerRespawn", PhotonNetwork.masterClient, PhotonNetwork.player);
	}

	private void OnGunReset(Tool tool)
	{
		if (PhotonNetwork.isMasterClient)
		{
			playerGunPool.Release(tool.gameObject);
		}
	}

	private Coroutine StartGameTeamBattle()
	{
		return StartCoroutine(TeamBattleStartGameCoroutine());
	}

	private IEnumerator TeamBattleStartGameCoroutine()
	{
		DisableAllFlags();
		base.PlayerManager.MasterResetTeamScores();
		SetGameDuration(teamBattleMaximumGameTime);
		yield return MasterRespawnAllActivePlayers();
		MasterInitializeAllPlayers();
		SetGameStartTime((float)PhotonNetwork.time);
	}

	private void ScoreTeamBattle(Player scoringPlayer)
	{
		ActivityTeam playerTeam = base.PlayerManager.GetPlayerTeam(scoringPlayer.PhotonPlayer);
		base.PlayerManager.MasterAddTeamScore(playerTeam, 1);
		MasterTryUpdateGame();
	}

	private void UpdateTeamBattle()
	{
		ActivityTeam maxScoreTeam = null;
		int maxTeamScore = base.PlayerManager.GetMaxTeamScore(out maxScoreTeam);
		if (maxTeamScore >= teamBattleScoreToWin)
		{
			MasterGameOver(maxScoreTeam);
		}
	}

	private Coroutine StartGameCaptureTheFlag()
	{
		return StartCoroutine(CaptureTheFlagStartGameCoroutine());
	}

	private IEnumerator CaptureTheFlagStartGameCoroutine()
	{
		DisableAllFlags();
		MasterRestictAllActivePlayerInteractions();
		base.PlayerManager.MasterResetTeamScores();
		SetGameDuration(ctfMaximumGameTime);
		yield return MasterRespawnAllActivePlayers();
		MasterInitializeAllPlayers();
		SetGameStartTime((float)PhotonNetwork.time);
		yield return StartRoundCaptureTheFlag(0, null);
	}

	private Coroutine StartRoundCaptureTheFlag(int maxScore, ActivityTeam maxScoreTeam)
	{
		return StartCoroutine(CaptureTheFlagStartRoundCoroutine(maxScore, maxScoreTeam));
	}

	private IEnumerator CaptureTheFlagStartRoundCoroutine(int maxScore, ActivityTeam maxScoreTeam)
	{
		if (maxScore > 0)
		{
			yield return new WaitForSeconds(3f);
		}
		yield return MasterShowNotificationAllPlayers("Flags Spawning", 1.5f);
		RespawnAllFlags();
		if (maxScore > ctfScoreToWin - 1 && maxScoreTeam != null)
		{
			MasterShowNotificationAllPlayers(maxScoreTeam.Name + " Team Close To Winning!", 1.5f);
		}
	}

	private void OnFlagCaptured(Player capturingPlayer, ActivityTeam capturingTeam)
	{
		AddPlayerFlagCaptures(capturingPlayer.PhotonPlayer, 1);
		base.PlayerManager.MasterAddTeamScore(capturingTeam, 1);
		SetAreFlagsResetting(resetting: true);
		DisableAllFlags();
		base.photonView.RPC("RpcOnFlagCapture", PhotonTargets.All, capturingTeam.Id, capturingPlayer.PhotonPlayer);
		MasterTryUpdateGame();
	}

	private void DisableAllFlags()
	{
		CTFTeamSettings[] array = ctfTeamSettings;
		for (int i = 0; i < array.Length; i++)
		{
			CTFTeamSettings cTFTeamSettings = array[i];
			cTFTeamSettings.Flag.Disable();
		}
	}

	private void RespawnAllFlags()
	{
		SetAreFlagsResetting(resetting: true);
		CTFTeamSettings[] array = ctfTeamSettings;
		for (int i = 0; i < array.Length; i++)
		{
			CTFTeamSettings cTFTeamSettings = array[i];
			cTFTeamSettings.Flag.ResetToLastSpawnPosition();
		}
		SetAreFlagsResetting(resetting: false);
	}

	private void UpdateCaptureTheFlag()
	{
		ActivityTeam maxScoreTeam = null;
		int maxTeamScore = base.PlayerManager.GetMaxTeamScore(out maxScoreTeam);
		if (maxTeamScore >= ctfScoreToWin)
		{
			MasterGameOver(maxScoreTeam);
		}
		else if (GetAreFlagsResetting())
		{
			StartRoundCaptureTheFlag(maxTeamScore, maxScoreTeam);
		}
	}

	private bool GetAreFlagsResetting()
	{
		return base.ActivityData.GetData("RESETTING_FLAGS", defaultValue: true);
	}

	private void SetAreFlagsResetting(bool resetting)
	{
		base.ActivityData.SetData("RESETTING_FLAGS", resetting);
	}

	private void OnFlagPickup(Tool flagTool)
	{
		if (!PhotonNetwork.isMasterClient || base.GameState != ActivityGameState.PlayingGame)
		{
			return;
		}
		FlagTool component = flagTool.GetComponent<FlagTool>();
		ActivityTeam playerTeam = base.PlayerManager.GetPlayerTeam(component.Owner.PhotonPlayer);
		ActivityTeam toolTeam = base.PlayerManager.GetToolTeam(component);
		if (playerTeam != null && toolTeam != null)
		{
			if (toolTeam == playerTeam)
			{
				component.ResetToLastSpawnPosition();
			}
			else if (toolTeam != playerTeam)
			{
				base.photonView.RPC("RpcOnFlagStolen", PhotonTargets.All, toolTeam.Id);
			}
		}
	}

	private void OnFlagDrop(Tool flagTool)
	{
		if (PhotonNetwork.isMasterClient && base.GameState == ActivityGameState.PlayingGame)
		{
			FlagTool component = flagTool.GetComponent<FlagTool>();
			ActivityTeam playerTeam = base.PlayerManager.GetPlayerTeam(component.Owner.PhotonPlayer);
			ActivityTeam toolTeam = base.PlayerManager.GetToolTeam(component);
			if (playerTeam != null && toolTeam != null && toolTeam != playerTeam && !GetAreFlagsResetting())
			{
				base.photonView.RPC("RpcOnFlagDropped", PhotonTargets.All, toolTeam.Id);
			}
		}
	}

	private void OnFlagReset(Tool flagTool)
	{
		if (PhotonNetwork.isMasterClient && base.GameState == ActivityGameState.PlayingGame)
		{
			FlagTool component = flagTool.GetComponent<FlagTool>();
			ActivityTeam toolTeam = base.PlayerManager.GetToolTeam(component);
			if (toolTeam != null && !GetAreFlagsResetting())
			{
				base.photonView.RPC("RpcOnFlagReturned", PhotonTargets.All, toolTeam.Id);
			}
		}
	}

	private FlagTool GetTeamFlag(ActivityTeam team)
	{
		FlagTool result = null;
		CTFTeamSettings[] array = ctfTeamSettings;
		for (int i = 0; i < array.Length; i++)
		{
			CTFTeamSettings cTFTeamSettings = array[i];
			if (cTFTeamSettings.TeamId == team.Id)
			{
				result = cTFTeamSettings.Flag;
				break;
			}
		}
		return result;
	}

	private void OnFlagEnteredGoal(FlagTool flag)
	{
		Player player = flag.Owner;
		if (!(player != Player.LocalPlayer))
		{
			ActivityTeam playerTeam = base.PlayerManager.GetPlayerTeam(player.PhotonPlayer);
			FlagTool teamFlag = GetTeamFlag(playerTeam);
			if (!teamFlag.IsAtHome() || teamFlag.IsHeld)
			{
				RpcShowNotification("Cannot Score!", "Your flag is away", 1.5f);
			}
		}
	}

	private void ResetAllPlayerStats()
	{
		ActivityTeam[] activeTeams = base.PlayerManager.GetActiveTeams();
		foreach (ActivityTeam team in activeTeams)
		{
			PhotonPlayer[] teamPlayers = base.PlayerManager.GetTeamPlayers(team);
			foreach (PhotonPlayer player in teamPlayers)
			{
				SetPlayerKills(player, 0);
				SetPlayerDeaths(player, 0);
				SetPlayerFlagCaptures(player, 0);
			}
		}
	}

	public int GetPlayerRank(PhotonPlayer player)
	{
		int playerKills = GetPlayerKills(player);
		int playerDeaths = GetPlayerDeaths(player);
		int playerFlagCaptures = GetPlayerFlagCaptures(player);
		return playerKills * killRank - playerDeaths * deathRank + playerFlagCaptures * flagCaptureRank;
	}

	public int GetPlayerKills(PhotonPlayer player)
	{
		return base.ActivityData.GetDataForPlayer(player, "PLAYER_KILLS", 0);
	}

	private void SetPlayerKills(PhotonPlayer player, int kills)
	{
		base.ActivityData.SetDataForPlayer(player, "PLAYER_KILLS", kills);
	}

	private void AddPlayerKills(PhotonPlayer player, int delta)
	{
		int playerKills = GetPlayerKills(player);
		SetPlayerKills(player, playerKills + delta);
	}

	public int GetPlayerDeaths(PhotonPlayer player)
	{
		return base.ActivityData.GetDataForPlayer(player, "PLAYER_DEATHS", 0);
	}

	private void SetPlayerDeaths(PhotonPlayer player, int deaths)
	{
		base.ActivityData.SetDataForPlayer(player, "PLAYER_DEATHS", deaths);
	}

	private void AddPlayerDeaths(PhotonPlayer player, int delta)
	{
		int playerDeaths = GetPlayerDeaths(player);
		SetPlayerDeaths(player, playerDeaths + delta);
	}

	public int GetPlayerFlagCaptures(PhotonPlayer player)
	{
		return base.ActivityData.GetDataForPlayer(player, "PLAYER_FLAGS", 0);
	}

	private void SetPlayerFlagCaptures(PhotonPlayer player, int captures)
	{
		base.ActivityData.SetDataForPlayer(player, "PLAYER_FLAGS", captures);
	}

	private void AddPlayerFlagCaptures(PhotonPlayer player, int delta)
	{
		int playerFlagCaptures = GetPlayerFlagCaptures(player);
		SetPlayerFlagCaptures(player, playerFlagCaptures + delta);
	}

	public void PlayerHit(Player hitPlayer, Player.BodyPart hitBodyPart, Player shooter, Vector3 position)
	{
		base.photonView.RPC("RpcPlayerHit", PhotonTargets.MasterClient, hitPlayer.PhotonPlayer, (int)hitBodyPart, shooter.PhotonPlayer, position);
	}

	private void MasterPlayerHit(PhotonPlayer hitPlayer, Player.BodyPart hitBodyPart, PhotonPlayer shooter, Vector3 position)
	{
		if (PhotonNetwork.isMasterClient && PlayerCanTakeDamage(hitPlayer, shooter))
		{
			int damage = GetDamage(hitBodyPart);
			AddPlayerHealth(hitPlayer, -damage);
			if (GetPlayerIsAlive(hitPlayer))
			{
				OnPlayerDamaged(hitPlayer, position);
			}
			else
			{
				OnPlayerKilled(hitPlayer, shooter, position);
			}
		}
	}

	private void OnPlayerDamaged(PhotonPlayer damagedPlayer, Vector3 position)
	{
		base.photonView.RPC("RpcPlayerDamaged", damagedPlayer, position);
	}

	private void OnPlayerKilled(PhotonPlayer deadPlayer, PhotonPlayer shooter, Vector3 position)
	{
		base.photonView.RPC("RpcPlayerKilledShooter", shooter, deadPlayer, position);
		base.photonView.RPC("RpcPlayerKilledDeadPlayer", deadPlayer, shooter, position);
		AddPlayerKills(shooter, 1);
		AddPlayerDeaths(deadPlayer, 1);
		base.PlayerManager.FireScoresUpdated();
		if (GetGameMode() == GameMode.TeamBattle)
		{
			ScoreTeamBattle(shooter.ToPlayer());
		}
	}

	private void RunPlayerDamaged(Vector3 position)
	{
		paintballAudio.OnPlayerDamaged(position);
	}

	private void RunPlayerKilledShooter(Player deadPlayer, Vector3 position)
	{
		paintballAudio.OnPlayerDamaged(position);
		paintballAudio.OnPlayerHit();
		Vector3 vector = 0.35f * ((Player.LocalPlayer.Head.transform.position - position).normalized + Vector3.up);
		RpcShowWorldSpaceNotification(position + vector, "Hit!", null, playerKilledFeedbackDuration);
		RpcShowNotification("You Hit " + deadPlayer.PlayerName, null, playerKilledNotificationDuration);
		SingletonMonoBehaviour<LeaderboardManager>.Instance.IncrementLeaderboardScore(PlayerStats.RecroomSteamLeaderboards.paintball_hits_weekly);
		SingletonMonoBehaviour<LeaderboardManager>.Instance.IncrementLeaderboardScore(PlayerStats.RecroomSteamLeaderboards.paintball_hits_alltime);
	}

	private Coroutine RunPlayerKilledDeadPlayer(Player shooter, Vector3 position)
	{
		return StartCoroutine(PlayerKilledDeadPlayerCoroutine(shooter, position));
	}

	private IEnumerator PlayerKilledDeadPlayerCoroutine(Player shooter, Vector3 position)
	{
		if (shooter != null)
		{
			paintballAudio.OnPlayerDamaged(position);
		}
		SetPlayerInvincibility(PhotonNetwork.player, invincible: true);
		Player.LocalPlayer.CanInteractWithTools = false;
		Player.LocalPlayer.PlayerLocomotion.TeleportEnabled = false;
		if (shooter != null)
		{
			RpcShowNotification("You're Out!", "Hit by " + shooter.PlayerName, playerKilledNotificationDuration);
			paintballAudio.OnPlayerOut();
		}
		else
		{
			RpcShowNotification("You're Out!", "Out of Bounds!", playerKilledNotificationDuration);
		}
		yield return new WaitForSeconds(playerKilledNotificationDuration);
		Player.LocalPlayer.Despawn();
		base.photonView.RPC("RpcMasterRequestPlayerRespawn", PhotonNetwork.masterClient, PhotonNetwork.player);
	}

	private Coroutine RunPlayerRespawn(Vector3 position, Quaternion rotation)
	{
		return StartCoroutine(PlayerRespawnCoroutine(position, rotation));
	}

	private IEnumerator PlayerRespawnCoroutine(Vector3 position, Quaternion rotation)
	{
		Player.LocalPlayer.Respawn(position, rotation);
		yield return new WaitForSeconds(Player.RespawnDuration);
		if (base.GameState == ActivityGameState.PlayingGame)
		{
			PlayerHand dominantHand = Player.LocalPlayer.DominantHand;
			base.photonView.RPC("RpcMasterRequestPlayerGunSpawn", PhotonTargets.MasterClient, PhotonNetwork.player, dominantHand.transform.position, dominantHand.transform.rotation);
		}
		SetPlayerInvincibility(PhotonNetwork.player, invincible: false);
		SetPlayerHealth(PhotonNetwork.player, playerSpawnHealth);
		Player.LocalPlayer.CanInteractWithTools = true;
		Player.LocalPlayer.PlayerLocomotion.TeleportEnabled = true;
	}

	private void MasterSpawnPlayerGun(PhotonPlayer player, Vector3 spawnPosition, Quaternion spawnRotation)
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		if (playerGunPool.Availability == 0)
		{
			GameObject[] lRUPool = playerGunPool.LRUPool;
			foreach (GameObject gameObject in lRUPool)
			{
				Gun component = gameObject.GetComponent<Gun>();
				if (component != null && !component.IsHeld)
				{
					playerGunPool.Release(component.gameObject);
					break;
				}
			}
		}
		GameObject gameObject2 = playerGunPool.Acquire(spawnPosition, spawnRotation);
		Gun gun = ((!(gameObject2 != null)) ? null : gameObject2.GetComponent<Gun>());
		if (gun == null)
		{
			UnityEngine.Debug.LogError("There are no guns available in the gun pool.");
			return;
		}
		base.photonView.RPC("RpcPickupPlayerSpawnGun", player, gun.photonView.viewID);
	}

	private void RunPickupPlayerSpawnGun(Gun gun)
	{
		PlayerHand playerHand = Player.LocalPlayer.DominantHand;
		if (playerHand.Tool != null)
		{
			playerHand = Player.LocalPlayer.GetOtherHand(playerHand.Type);
		}
		if (playerHand.Tool == null)
		{
			Player.LocalPlayer.ToolController.TryPickupTool(gun, (int)playerHand.Type);
		}
	}

	public override void OnLocalPlayerOutOfBounds()
	{
		if (base.GameState == ActivityGameState.PlayingGame && localPlayerOutOfBoundsCoroutine == null)
		{
			localPlayerOutOfBoundsCoroutine = StartCoroutine(LocalPlayerOutOfBoundsCoroutine());
		}
	}

	private IEnumerator LocalPlayerOutOfBoundsCoroutine()
	{
		RpcShowNotification("Out of Bounds!", "Get Back To The Field!", 1.5f);
		yield return new WaitForSeconds(1.5f);
		int seconds = (int)outOfBoundsRespawnDuration;
		while (seconds > 0)
		{
			RpcShowNotification("Respawn in " + seconds, null, 1f);
			seconds--;
			float timer = 0f;
			while (timer <= 1f)
			{
				yield return null;
				timer += Time.deltaTime;
				if (!Player.LocalPlayer.IsOutOfBounds)
				{
					RpcShowNotification("You're back!", null, 1.5f);
					localPlayerOutOfBoundsCoroutine = null;
					yield break;
				}
			}
		}
		AddPlayerDeaths(PhotonNetwork.player, 1);
		base.PlayerManager.FireScoresUpdated();
		RunPlayerKilledDeadPlayer(null, Vector3.zero);
		localPlayerOutOfBoundsCoroutine = null;
	}

	private bool PlayerCanTakeDamage(PhotonPlayer hitPlayer, PhotonPlayer shooter)
	{
		return base.GameState == ActivityGameState.PlayingGame && GetPlayerIsAlive(hitPlayer) && !GetPlayerInvincibility(hitPlayer) && (friendlyFireEnabled || !base.PlayerManager.PlayersOnSameTeam(hitPlayer, shooter));
	}

	private int GetDamage(Player.BodyPart hitBodyPart)
	{
		DamageSetting[] array = damageSettings;
		for (int i = 0; i < array.Length; i++)
		{
			DamageSetting damageSetting = array[i];
			if (damageSetting.BodyPart == hitBodyPart)
			{
				return damageSetting.Damage;
			}
		}
		return 0;
	}

