public class PaintballPlayerManager : TeamPlayerManager
{
	private struct SpawnPointScore
	{
		public int Index;

		public float Score;
	}

	[Serializable]
	private struct ProximityScoreSettings
	{
		public float MinThreshold;

		public float MaxThreshold;

		public float MinScore;

		public float MaxScore;
	}

	[SerializeField]
	private float occupationThreshold = 1f;

	[SerializeField]
	private ProximityScoreSettings enemyScoreSettings;

	[SerializeField]
	private ProximityScoreSettings teammateScoreSettings;

	private List<SpawnPointScore> spawnPointScores = new List<SpawnPointScore>();

	public override Transform GetSpawnPoint(PhotonPlayer player, string previousActivity = null)
	{
		Transform transform = null;
		if (ActivityManager.Instance.GameState == ActivityGameState.PlayingGame && !IsPlayerSpectator(player))
		{
			ActivityTeam playerTeam = GetPlayerTeam(player);
			TeamRole teamRole = GetTeamRole(playerTeam);
			spawnPointScores.Clear();
			for (int i = 0; i < teamRole.SpawnPoints.Length; i++)
			{
				float score = 0f;
				if (TryGetSpawnPointScore(playerTeam, i, teamRole.SpawnPoints[i].position, out score))
				{
					spawnPointScores.Add(new SpawnPointScore
					{
						Index = i,
						Score = score
					});
				}
			}
			if (spawnPointScores.Count > 0)
			{
				spawnPointScores.Sort((SpawnPointScore a, SpawnPointScore b) => a.Score.CompareTo(b.Score));
				int index = spawnPointScores[spawnPointScores.Count - 1].Index;
				SetLastSpawnTime(playerTeam, index, (float)PhotonNetwork.time);
				transform = teamRole.SpawnPoints[index];
			}
		}
		if (transform != null)
		{
			return transform;
		}
		return GetNextSpectatorSpawnPoint();
	}

	private bool TryGetSpawnPointScore(ActivityTeam team, int spawnPointIndex, Vector3 spawnPosition, out float score)
	{
		score = 0f;
		float lastSpawnTime = GetLastSpawnTime(team, spawnPointIndex);
		float num = (float)PhotonNetwork.time - lastSpawnTime;
		if (num < minOccupationDuration)
		{
			return false;
		}
		float score2 = 0f;
		PhotonPlayer[] teamPlayers = GetTeamPlayers(team);
		if (!TryGetPlayersScore(spawnPosition, teamPlayers, teammateScoreSettings, out score2))
		{
			return false;
		}
		float score3 = 0f;
		ActivityTeam otherTeam = GetOtherTeam(team);
		if (otherTeam != null)
		{
			PhotonPlayer[] teamPlayers2 = GetTeamPlayers(GetOtherTeam(team));
			if (!TryGetPlayersScore(spawnPosition, teamPlayers2, enemyScoreSettings, out score3))
			{
				return false;
			}
		}
		score = score3 + score2;
		return true;
	}

	private bool TryGetPlayersScore(Vector3 spawnPoint, PhotonPlayer[] photonPlayers, ProximityScoreSettings scoreSettings, out float score)
	{
		score = 0f;
		foreach (PhotonPlayer photonPlayer in photonPlayers)
		{
			Player player = photonPlayer.ToPlayer();
			if (!(player == null))
			{
				float magnitude = Vector3.ProjectOnPlane(player.Head.transform.position - spawnPoint, Vector3.up).magnitude;
				if (magnitude < occupationThreshold)
				{
					score = 0f;
					return false;
				}
				float t = Mathf.Clamp01((magnitude - scoreSettings.MinThreshold) / (scoreSettings.MaxThreshold - scoreSettings.MinThreshold));
				score += Mathf.Lerp(scoreSettings.MinScore, scoreSettings.MaxScore, t);
			}
		}
		return true;
	}
}
public class PaintballScoreboard : Scoreboard
{
	[SerializeField]
	[Header("Paintball")]
	private PaintballScoreboardPlayerEntry header;

	[SerializeField]
	private PaintballScoreboardPlayerEntry redTeamHeader;

	[SerializeField]
	private PaintballScoreboardPlayerEntry[] redTeamPlayerEntries;

	[SerializeField]
	private PaintballScoreboardPlayerEntry blueTeamHeader;

	[SerializeField]
	private PaintballScoreboardPlayerEntry[] blueTeamPlayerEntries;

	[SerializeField]
	private TextMesh timerText;

	private PaintballActivityManager _paintballActivityManager;

	private PaintballActivityManager PaintballActivityManager
	{
		get
		{
			if (_paintballActivityManager == null)
			{
				_paintballActivityManager = (PaintballActivityManager)ActivityManager.Instance;
			}
			return _paintballActivityManager;
		}
	}

	protected override void Start()
	{
		base.Start();
		PaintballActivityManager.GameMode mode = ((!(PaintballActivityManager != null)) ? PaintballActivityManager.GameMode.CaptureTheFlag : PaintballActivityManager.GetGameMode());
		header.ShowOnlyLabels(mode);
		PaintballScoreboardPlayerEntry[] array = redTeamPlayerEntries;
		foreach (PaintballScoreboardPlayerEntry paintballScoreboardPlayerEntry in array)
		{
			paintballScoreboardPlayerEntry.Hide(mode);
		}
		PaintballScoreboardPlayerEntry[] array2 = blueTeamPlayerEntries;
		foreach (PaintballScoreboardPlayerEntry paintballScoreboardPlayerEntry2 in array2)
		{
			paintballScoreboardPlayerEntry2.Hide(mode);
		}
	}

	protected override void OnScoresChanged()
	{
		ActivityTeam[] allTeams = ActivityManager.Instance.PlayerManager.GetAllTeams();
		PaintballActivityManager.GameMode mode = ((!(PaintballActivityManager != null)) ? PaintballActivityManager.GameMode.CaptureTheFlag : PaintballActivityManager.GetGameMode());
		header.ShowOnlyLabels(mode);
		ActivityTeam[] array = allTeams;
		foreach (ActivityTeam activityTeam in array)
		{
			if (activityTeam.IsBlueTeam)
			{
				UpdateTeam(blueTeamHeader, blueTeamPlayerEntries, activityTeam, mode);
			}
			else
			{
				UpdateTeam(redTeamHeader, redTeamPlayerEntries, activityTeam, mode);
			}
		}
	}

	private void Update()
	{
		if (!(PaintballActivityManager == null) && !(timerText == null))
		{
			float seconds = 0f;
			if (PaintballActivityManager.GameState == ActivityGameState.PlayingGame)
			{
				seconds = PaintballActivityManager.GetTimeRemaining();
			}
			timerText.text = seconds.ToTimeString();
		}
	}

	private void UpdateTeam(PaintballScoreboardPlayerEntry teamHeader, PaintballScoreboardPlayerEntry[] playerEntries, ActivityTeam team, PaintballActivityManager.GameMode mode)
	{
		int teamScore = ActivityManager.Instance.PlayerManager.GetTeamScore(team);
		teamHeader.ShowOnlyScore(team.Color, team.Name + " Team", teamScore, mode);
		PhotonPlayer[] teamPlayers = ActivityManager.Instance.PlayerManager.GetTeamPlayers(team);
		int teamMaxPlayers = ActivityManager.Instance.PlayerManager.GetTeamMaxPlayers(team);
		int num = 0;
		int num2 = 0;
		if (PaintballActivityManager != null)
		{
			Array.Sort(teamPlayers, (PhotonPlayer a, PhotonPlayer b) => PaintballActivityManager.GetPlayerRank(a).CompareTo(PaintballActivityManager.GetPlayerRank(b)));
			Array.Reverse(teamPlayers);
			for (; num2 < teamPlayers.Length; num2++)
			{
				UpdatePlayerEntry(playerEntries, team.Color, teamPlayers[num2], num2 + 1, num++, mode);
			}
		}
		for (; num2 < teamMaxPlayers; num2++)
		{
			playerEntries[num++].Hide(team.Color, mode);
		}
	}

	private void UpdatePlayerEntry(PaintballScoreboardPlayerEntry[] playerEntries, Color teamColor, PhotonPlayer player, int rank, int playerEntryIndex, PaintballActivityManager.GameMode mode)
	{
		int playerFlagCaptures = PaintballActivityManager.GetPlayerFlagCaptures(player);
		int playerKills = PaintballActivityManager.GetPlayerKills(player);
		int playerDeaths = PaintballActivityManager.GetPlayerDeaths(player);
		playerEntries[playerEntryIndex].Show(teamColor, player.name, rank, playerFlagCaptures, playerKills, playerDeaths, mode);
	}
}
public class PaintballScoreboardPlayerEntry : UnityEngine.MonoBehaviour
{
	private const float HIDE_ALPHA = 0.1f;

	[SerializeField]
	private Text rankText;

	[SerializeField]
	private Text nameText;

	[SerializeField]
	private Text flagCapturesText;

	[SerializeField]
	private Text killsText;

	[SerializeField]
	private Text deathsText;

	[SerializeField]
	private Text kdText;

	private UnityEngine.UI.Image[] backgrounds;

	[SerializeField]
	private float defaultAlpha = 1f;

	private void Awake()
	{
		backgrounds = GetComponentsInChildren<UnityEngine.UI.Image>();
	}

	public void Show(Color teamColor, string name, int rank, int flagCaptures, int kills, int deaths, PaintballActivityManager.GameMode mode)
	{
		teamColor.a = defaultAlpha;
		UnityEngine.UI.Image[] array = backgrounds;
		foreach (UnityEngine.UI.Image image in array)
		{
			image.color = teamColor;
		}
		rankText.text = rank.ToString();
		nameText.text = name;
		killsText.text = kills.ToString();
		deathsText.text = deaths.ToString();
		flagCapturesText.text = flagCaptures.ToString();
		flagCapturesText.transform.parent.gameObject.SetActive(mode == PaintballActivityManager.GameMode.CaptureTheFlag);
		if (deaths == 0)
		{
			kdText.text = "-";
		}
		else
		{
			float num = (float)kills / (float)deaths;
			kdText.text = num.ToString("F2");
		}
		kdText.transform.parent.gameObject.SetActive(mode == PaintballActivityManager.GameMode.TeamBattle);
	}

	public void ShowOnlyScore(Color teamColor, string name, int score, PaintballActivityManager.GameMode mode)
	{
		teamColor.a = defaultAlpha;
		UnityEngine.UI.Image[] array = backgrounds;
		foreach (UnityEngine.UI.Image image in array)
		{
			image.color = teamColor;
		}
		rankText.text = "-";
		nameText.text = name;
		deathsText.text = "-";
		switch (mode)
		{
		case PaintballActivityManager.GameMode.CaptureTheFlag:
			killsText.text = "-";
			kdText.text = "-";
			kdText.transform.parent.gameObject.SetActive(value: false);
			flagCapturesText.text = score.ToString();
			flagCapturesText.transform.parent.gameObject.SetActive(value: true);
			break;
		case PaintballActivityManager.GameMode.TeamBattle:
			killsText.text = score.ToString();
			kdText.text = "-";
			kdText.transform.parent.gameObject.SetActive(value: true);
			flagCapturesText.text = "-";
			flagCapturesText.transform.parent.gameObject.SetActive(value: false);
			break;
		}
	}

	public void ShowOnlyLabels(PaintballActivityManager.GameMode mode)
	{
		flagCapturesText.transform.parent.gameObject.SetActive(mode == PaintballActivityManager.GameMode.CaptureTheFlag);
		kdText.transform.parent.gameObject.SetActive(mode == PaintballActivityManager.GameMode.TeamBattle);
	}

	public void Hide(Color teamColor, PaintballActivityManager.GameMode mode)
	{
		teamColor.a = 0.1f;
		UnityEngine.UI.Image[] array = backgrounds;
		foreach (UnityEngine.UI.Image image in array)
		{
			image.color = teamColor;
		}
		Hide(mode);
	}

	public void Hide(PaintballActivityManager.GameMode mode)
	{
		rankText.text = string.Empty;
		nameText.text = string.Empty;
		killsText.text = string.Empty;
		deathsText.text = string.Empty;
		flagCapturesText.text = string.Empty;
		flagCapturesText.transform.parent.gameObject.SetActive(mode == PaintballActivityManager.GameMode.CaptureTheFlag);
		kdText.text = string.Empty;
		kdText.transform.parent.gameObject.SetActive(mode == PaintballActivityManager.GameMode.TeamBattle);
	}
}
