public class ActivityBodyBubbleSettings : UnityEngine.MonoBehaviour
{
	[SerializeField]
	[Header("Body Bubble Supported")]
	private bool defaultSupportsBodyBubble = true;

	[SerializeField]
	private bool preGameSupportsBodyBubble = true;

	[SerializeField]
	private bool spectatorSupportsBodyBubble;

	[SerializeField]
	private bool allActivePlayersSupportsBodyBubble = true;

	[Header("Configuration")]
	[SerializeField]
	private float bubbleRadius = 0.85f;

	private ActivityManager thisActivity;

	public float BubbleRadius => bubbleRadius;

	private void Awake()
	{
		thisActivity = GetComponent<ActivityManager>();
	}

	public bool BodyBubbleSupported(PhotonPlayer player)
	{
		if (thisActivity == null)
		{
			return defaultSupportsBodyBubble;
		}
		if (thisActivity.PlayerManager.IsPlayerSpectator(player))
		{
			return spectatorSupportsBodyBubble;
		}
		if (thisActivity.GameState != ActivityGameState.PlayingGame)
		{
			return preGameSupportsBodyBubble;
		}
		return allActivePlayersSupportsBodyBubble;
	}
}
