	}

	[PunRPC]
	public void RpcNetworkCollectibleEnable(bool enabled)
	{
		Visuals.Visible = enabled;
	}

	[PunRPC]
	public void RpcNetworkCollectiblePicked(PhotonPlayer pPlayer)
	{
		AudioManager.Play3DSFX(pickedupAudio, base.transform.position);
		Player player = pPlayer.ToPlayer();
		if (player != null && player.isLocal)
		{
			if (player.LeftHand != null && player.LeftHand.Tool != null)
			{
				player.LeftHand.Tool.OnCollectiblePicked(this);
			}
			if (player.RightHand != null && player.RightHand.Tool != null)
			{
				player.RightHand.Tool.OnCollectiblePicked(this);
			}
		}
	}

	public void UpdateResetTimer()
	{
		int data = PhotonNetwork.ServerTimestamp + ResetDurationSeconds * 1000;
		ActivityData.SetData(RESET_PROPERTY_KEY, data);
	}

	public void StopResetTimer()
	{
		SetEnabled(enabled: false);
		ActivityData.SetData(RESET_PROPERTY_KEY, 0);
	}

	public void GiveToPlayer(Player player)
	{
		if (player != null)
		{
			base.photonView.RPC("RpcNetworkCollectiblePicked", PhotonTargets.All, player.PhotonPlayer);
		}
		SetEnabled(enabled: false);
		UpdateResetTimer();
	}
}
public class PlayerBodyBubble : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float playerHeadHeight = 0.4f;

	private float radius;

	public Player ThisPlayer { get; set; }

	public float Radius
	{
		get
		{
			return radius;
		}
		set
		{
			radius = value;
			base.transform.localScale = radius * 2f * Vector3.one;
		}
	}

	public Vector3 PlayerHeadOffset => Vector3.up * (playerHeadHeight - Radius);

	private void FixedUpdate()
	{
		base.transform.position = ThisPlayer.Head.transform.position + PlayerHeadOffset;
	}

	public Tool RunTeleportCollision(Vector3 teleportStart, Vector3 teleportEnd, float hitForce)
	{
		Vector3 vector = teleportEnd - teleportStart;
		float magnitude = vector.magnitude;
		if (magnitude < Mathf.Epsilon)
		{
			vector = Vector3.zero;
		}
		else
		{
			vector /= magnitude;
		}
		Tool tool = null;
		Vector3 origin = teleportStart + ThisPlayer.Head.HeightOffset + PlayerHeadOffset;
		RaycastHit[] array = Physics.SphereCastAll(origin, radius, vector, magnitude, 402432, QueryTriggerInteraction.Ignore);
		RaycastHit[] array2 = array;
		for (int i = 0; i < array2.Length; i++)
		{
			RaycastHit raycastHit = array2[i];
			tool = raycastHit.collider.GetColliderTool();
			if (tool != null && tool.SupportsTeleportHits)
			{
				tool.ApplyForce(raycastHit.point, vector * hitForce);
				break;
			}
		}
		return tool;
	}
}
public class PlayerLineTrail : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private int maxHistoricalSegments = 3;

	[SerializeField]
	private float vertexSpacing = 0.25f;

	[SerializeField]
	private Vector2 alphas = new Vector2(0f, 1f);

	[SerializeField]
	private Vector2 widths = new Vector2(0.2f, 0.8f);

	private LineRenderer lineRenderer;

	private BezierPath bezierPath = new BezierPath();

	private Queue<Vector3> points = new Queue<Vector3>();

	public Color Color
	{
		set
		{
			if (lineRenderer != null)
			{
				Color start = value;
				start.a = alphas.x;
				Color end = value;
				end.a = alphas.y;
				lineRenderer.SetColors(start, end);
			}
		}
	}

	private void Awake()
	{
		lineRenderer = GetComponent<LineRenderer>();
		if (lineRenderer != null)
		{
			lineRenderer.SetWidth(widths.x, widths.y);
		}
		Color = Color.white;
		lineRenderer.enabled = false;
	}

	public void Clear()
	{
		points.Clear();
		UpdatePath();
	}

	public void SetLatestPlayerPosition(Vector3 sourcePlayerPosition, Vector3 destinationPlayerPosition)
	{
		Vector3 vector = Vector3.up * widths.y / 2f;
		if (points.Count == 0)
		{
			points.Enqueue(sourcePlayerPosition + vector);
		}
		while (points.Count > maxHistoricalSegments)
		{
			points.Dequeue();
		}
		points.Enqueue(destinationPlayerPosition + vector);
		UpdatePath();
	}

	private void UpdatePath()
	{
		bezierPath.Clear();
		Vector3[] array = points.ToArray();
		for (int i = 0; i < array.Length - 1; i++)
		{
			Vector3 vector = array[i];
			Vector3 vector2 = array[i + 1];
			Vector3 vector3 = vector2 - vector;
			float magnitude = vector3.magnitude;
			Vector3 normalized = vector3.normalized;
			Vector3 zero = Vector3.zero;
			zero = ((i + 1 != array.Length - 1) ? (vector2 - array[i + 2]).normalized : (-normalized));
			Vector3 controlPoint = vector + normalized * 0.5f * magnitude;
			Vector3 controlPoint2 = vector2 + zero * 0.5f * magnitude;
			if (bezierPath.CurveCount == 0)
			{
				bezierPath.AddCurve(vector, controlPoint, controlPoint2, vector2);
			}
			else
			{
				bezierPath.AddCurve(controlPoint, controlPoint2, vector2);
			}
		}
		if (bezierPath.CurveCount == 0)
		{
			lineRenderer.enabled = false;
			return;
		}
		int num = Mathf.RoundToInt(bezierPath.PathLength / vertexSpacing);
		Vector3[] array2 = new Vector3[num];
		for (int j = 0; j < num; j++)
		{
			ref Vector3 reference = ref array2[j];
			reference = bezierPath.EvaluatePath((float)j / (float)(num - 1));
		}
		lineRenderer.enabled = true;
		lineRenderer.SetVertexCount(num);
		lineRenderer.SetPositions(array2);
	}
}
