public class SoccerActivityManager : ActivityManager
{
	private const string IS_GAME_OVER_JKEY = "IS_GAME_OVER";

	private const string IS_ROUND_RUNNING_KEY = "ROUND_RUNNING";

	private const string LAST_BALL_HIT_PLAYER_KEY = "LAST_BALL_HIT";

	private const string IS_FIRST_ROUND_KEY = "IS_FIRST_ROUND";

	[SerializeField]
	[Header("Tools")]
	private Goal[] goals;

	[SerializeField]
	private SoccerBall ball;

	[SerializeField]
	private NetworkedGameObjectPool shieldPool;

	[SerializeField]
	[Header("Collectibles")]
	private Transform collectiblesRoot;

	private NetworkCollectible[] collectibles;

	[Header("Visuals")]
	[SerializeField]
	private ParticleSystem goalParticles;

	[SerializeField]
	private ParticleSystem localHitParticles;

	[SerializeField]
	private ParticleSystem ballHitBigParticlesPrefab;

	[SerializeField]
	[Header("Game Parameters")]
	private float maxGameDuration = 180f;

	private SoccerActivityAudio soccerAudio;

	private bool playedOneMinuteRemainingVO;

	private bool playedTenSecondsRemainingVO;

	protected override bool PlayerRequirementsMet => base.PlayerManager.GetActiveTeams().Length > 1;

	protected override void Awake()
	{
		base.Awake();
		soccerAudio = GetComponent<SoccerActivityAudio>();
		collectibles = collectiblesRoot.GetComponentsInChildren<NetworkCollectible>(includeInactive: true);
	}

	protected override IEnumerator Start()
	{
		if (ballHitBigParticlesPrefab != null)
		{
			SingletonMonoBehaviour<ObjectPool>.Instance.RegisterObjectPrefab(ballHitBigParticlesPrefab.gameObject);
		}
		return base.Start();
	}

	protected override void OnClientActivityLoad()
	{
		ball.ServerPhotonViewTriggerEnterEvent += MasterOnBallPhotonViewTriggerEnter;
		ball.ForceApplied += OnPlayerBallHit;
		base.PlayerManager.RolesUpdatedEvent += OnPlayerRoleUpdated;
		NetworkCollectible[] array = collectibles;
		foreach (NetworkCollectible networkCollectible in array)
		{
			networkCollectible.NetworkCollider.ServerPlayerTriggerEnterEvent += MasterOnCollectiblePlayerCollisionEnter;
			networkCollectible.NetworkCollider.ServerToolTriggerEnterEvent += MasterOnCollectibleToolCollisionEnter;
			networkCollectible.ActivityData = base.ActivityData;
			networkCollectible.SetEnabled(enabled: false);
		}
		GameObject[] pool = shieldPool.Pool;
		foreach (GameObject gameObject in pool)
		{
			SoccerShield component = gameObject.GetComponent<SoccerShield>();
			if (component != null)
			{
				component.ServerReleaseEvent += OnMasterShieldReleased;
			}
		}
	}

	private void MasterOnCollectibleToolCollisionEnter(GameObject thisGameObject, Tool tool, Vector3 point)
	{
		if (tool.IsHeld && tool.Owner != null)
		{
			NetworkCollectible component = thisGameObject.GetComponent<NetworkCollectible>();
			if (component != null && component.gameObject.activeSelf)
			{
				component.GiveToPlayer(tool.Owner);
			}
		}
	}

	private void MasterOnCollectiblePlayerCollisionEnter(GameObject thisGameObject, Player player, Player.BodyPart bodyPart, Vector3 point)
	{
		NetworkCollectible component = thisGameObject.GetComponent<NetworkCollectible>();
		if (component != null && component.gameObject.activeSelf)
		{
			component.GiveToPlayer(player);
		}
	}

	protected override void OnServerActivityLoad()
	{
	}

	protected override void OnServerActivityDestroy()
	{
	}

	protected override void MasterInitializePlayer(PhotonPlayer player)
	{
		base.MasterInitializePlayer(player);
		if (PhotonNetwork.isMasterClient)
		{
			base.photonView.RPC("RpcEnterGameSoccer", player);
		}
	}

	private Coroutine RunPlayerEnterGame()
	{
		return StartCoroutine(RunPlayerEnterGameCoroutine());
	}

	private IEnumerator RunPlayerEnterGameCoroutine()
	{
		playedOneMinuteRemainingVO = false;
		playedTenSecondsRemainingVO = false;
		while (Player.LocalPlayer == null)
		{
			yield return null;
		}
		UpdateLocalPlayerShield();
		if (base.GameState != ActivityGameState.PlayingGame)
		{
			yield break;
		}
		soccerAudio.StartPlayingMusic();
		yield return new WaitForSeconds(Player.SpawnDuration);
		RpcShowNotification("Timed Round", maxGameDuration.ToTimeString() + " Minutes Remaining", 2f);
		yield return new WaitForSeconds(2f);
		if (!base.PlayerManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			ActivityTeam team = base.PlayerManager.GetPlayerTeam(PhotonNetwork.player);
			if (team.IsBlueTeam)
			{
				soccerAudio.OnBlueTeamJoin();
			}
			else
			{
				soccerAudio.OnRedTeamJoin();
			}
			RpcShowNotification(team.Name + " Team", null, 2f);
			yield return new WaitForSeconds(2f);
		}
	}

	private void UpdateLocalPlayerShield()
	{
		if (Player.LocalPlayer == null)
		{
			return;
		}
		SoccerShield soccerShield = ((!(Player.LocalPlayer.LeftHand.Tool != null)) ? null : Player.LocalPlayer.LeftHand.Tool.GetComponent<SoccerShield>());
		SoccerShield soccerShield2 = ((!(Player.LocalPlayer.RightHand.Tool != null)) ? null : Player.LocalPlayer.RightHand.Tool.GetComponent<SoccerShield>());
		if (base.PlayerManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			if (soccerShield != null)
			{
				Player.LocalPlayer.LeftHand.ReleaseTool();
			}
			if (soccerShield2 != null)
			{
				Player.LocalPlayer.RightHand.ReleaseTool();
			}
		}
		else if (soccerShield == null && soccerShield2 == null)
		{
			PlayerHand dominantHand = Player.LocalPlayer.DominantHand;
			base.photonView.RPC("RpcRequestShield", PhotonTargets.MasterClient, PhotonNetwork.player, dominantHand.transform.position, dominantHand.transform.rotation);
		}
	}

	private void OnMasterShieldReleased(Tool shieldTool)
	{
		if (PhotonNetwork.isMasterClient)
		{
			shieldPool.Release(shieldTool.gameObject);
		}
	}

	private void OnPlayerRoleUpdated(PhotonPlayer photonPlayer)
	{
		if (photonPlayer != null && photonPlayer.isLocal)
		{
			UpdateLocalPlayerShield();
		}
	}

	protected override IEnumerator PreGameStateCoroutine()
	{
		ball.ResetToLastSpawnPosition();
		MasterEnableAllPlayersTeleport(teleportEnabled: true);
		yield break;
	}

	protected override IEnumerator PlayingGameStateCoroutine()
	{
		SetIsFirstRound(isFirstRound: true);
		SetIsRoundRunning(isRoundRunning: false);
		SetIsGameTimerPaused(pause: true);
		SetGameStartTime((float)PhotonNetwork.time);
		SetGameDuration(maxGameDuration);
		SetIsGameOver(isGameOver: false);
		ball.Disable();
		base.PlayerManager.MasterResetTeamScores();
		MasterEnableActivePlayerTeleport(teleportEnabled: false);
		yield return MasterRespawnAllActivePlayers();
		MasterInitializeAllPlayers();
		yield return new WaitForSeconds(5f);
		MasterTryUpdateGame();
	}

	protected override void MasterTryUpdateGame()
	{
		if (PhotonNetwork.isMasterClient && base.GameState == ActivityGameState.PlayingGame && !GetIsRoundRunning())
		{
			StartRound();
		}
	}

	private void Update()
	{
		if (base.GameState != ActivityGameState.PlayingGame)
		{
			return;
		}
		UpdateTimer();
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		uint serverTimestamp = (uint)PhotonNetwork.ServerTimestamp;
		NetworkCollectible[] array = collectibles;
		foreach (NetworkCollectible networkCollectible in array)
		{
			if (!networkCollectible.Visuals.Visible)
			{
				uint data = (uint)base.ActivityData.GetData(networkCollectible.RESET_PROPERTY_KEY, 0);
				if (data == 0 || data <= serverTimestamp)
				{
					networkCollectible.SetEnabled(enabled: true);
				}
			}
		}
	}

	private void UpdateTimer()
	{
		if (base.GameState == ActivityGameState.PlayingGame && !GetIsGameTimerPaused())
		{
			float timeRemaining = GetTimeRemaining();
			if (timeRemaining <= 60f && timeRemaining + 1f > 60f && !playedOneMinuteRemainingVO)
			{
				soccerAudio.OnOneMinuteRemaining();
				playedOneMinuteRemainingVO = true;
				RpcShowNotification("One Minute Remaining!", null, 2f);
			}
			else if (timeRemaining <= 10f && timeRemaining + 1f > 10f && !playedTenSecondsRemainingVO)
			{
				soccerAudio.OnTenSecondsRemaining();
				playedTenSecondsRemainingVO = true;
				RpcShowNotification("Ten Seconds Remaining!", null, 2f);
			}
			else if (timeRemaining <= 0f && PhotonNetwork.isMasterClient && !GetIsGameOver())
			{
				ActivityTeam maxScoreTeam = null;
				base.PlayerManager.GetMaxTeamScore(out maxScoreTeam);
				MasterGameOver(maxScoreTeam);
			}
		}
	}

	private void StartRound()
	{
		StartCoroutine(StartRoundCoroutine());
	}

	private IEnumerator StartRoundCoroutine()
	{
		if (GetIsFirstRound())
		{
			SetIsFirstRound(isFirstRound: false);
		}
		else
		{
			yield return MasterRespawnAllActivePlayers();
		}
		ball.ResetToLastSpawnPosition();
		MasterEnableActivePlayerTeleport(teleportEnabled: false);
		yield return CountdownNotificationsAllPlayers();
		MasterShowNotificationAllPlayers("Go!", 1.5f);
		MasterEnableActivePlayerTeleport(teleportEnabled: true);
		SetIsGameTimerPaused(pause: false);
		SetIsRoundRunning(isRoundRunning: true);
	}

	private bool GetIsFirstRound()
	{
		return base.ActivityData.GetData("IS_FIRST_ROUND", defaultValue: true);
	}

	private void SetIsFirstRound(bool isFirstRound)
	{
		base.ActivityData.SetData("IS_FIRST_ROUND", isFirstRound);
	}

	private bool GetIsRoundRunning()
	{
		return base.ActivityData.GetData("ROUND_RUNNING", defaultValue: false);
	}

	private void SetIsRoundRunning(bool isRoundRunning)
	{
		base.ActivityData.SetData("ROUND_RUNNING", isRoundRunning);
	}

	private bool GetIsGameOver()
	{
		return base.ActivityData.GetData("IS_GAME_OVER", defaultValue: false);
	}

	private void SetIsGameOver(bool isGameOver)
	{
		base.ActivityData.SetData("IS_GAME_OVER", isGameOver);
	}

	private void OnBallScore(ActivityTeam scoringTeam, PhotonPlayer scoringPlayer, Vector3 scorePosition)
	{
		base.PlayerManager.MasterAddTeamScore(scoringTeam, 1);
		ball.Disable();
		SetIsGameTimerPaused(pause: true);
		SetIsRoundRunning(isRoundRunning: false);
		StartCoroutine(OnBallScoreCoroutine(scoringTeam, scoringPlayer, scorePosition));
	}

	private IEnumerator OnBallScoreCoroutine(ActivityTeam scoringTeam, PhotonPlayer scoringPlayer, Vector3 scorePosition)
	{
		base.photonView.RPC("RpcOnScore", PhotonTargets.All, scoringTeam.Id, scoringPlayer, scorePosition);
		yield return new WaitForSeconds(6f);
		MasterTryUpdateGame();
	}

	private PhotonPlayer GetLastBallHitPlayer()
	{
		return base.ActivityData.GetData<PhotonPlayer>("LAST_BALL_HIT", null);
	}

	private void SetLastBallHitPlayer(PhotonPlayer player)
	{
		base.ActivityData.SetData("LAST_BALL_HIT", player);
	}

	private void MasterOnBallPhotonViewTriggerEnter(Tool tool, PhotonView hitPhotonView, Vector3 point)
	{
		if (!PhotonNetwork.isMasterClient || base.GameState != ActivityGameState.PlayingGame || !GetIsRoundRunning() || GetIsGameOver())
		{
			return;
		}
		Goal[] array = goals;
		foreach (Goal goal in array)
		{
			if (goal.gameObject == hitPhotonView.gameObject)
			{
				ActivityTeam team = base.PlayerManager.GetTeam(goal.OwnerTeamSlot);
				ActivityTeam otherTeam = base.PlayerManager.GetOtherTeam(team);
				PhotonPlayer lastBallHitPlayer = GetLastBallHitPlayer();
				OnBallScore(otherTeam, lastBallHitPlayer, point);
				break;
			}
		}
	}

	private void OnPlayerBallHit(Player player, Tool tool, Vector3 position, Vector3 force)
	{
		SoccerShield playerShield = GetPlayerShield(player);
		if (playerShield != null && playerShield.UsingPowerup)
		{
			if (ballHitBigParticlesPrefab != null)
			{
				PooledParticle pooledParticle = SingletonMonoBehaviour<ObjectPool>.Instance.Acquire<PooledParticle>(ballHitBigParticlesPrefab.name);
				if (pooledParticle != null)
				{
					pooledParticle.transform.position = playerShield.PowerupVisual.position;
					pooledParticle.transform.rotation = playerShield.transform.rotation;
					pooledParticle.Play();
				}
			}
			ball.FireTrail.Play();
		}
		if (player.isLocal)
		{
			if (localHitParticles != null)
			{
				localHitParticles.transform.position = position;
				localHitParticles.Play();
			}
			soccerAudio.OnLocalBallHit(position, 0f);
		}
		else
		{
			soccerAudio.OnRemoteBallHit(position, 0f);
		}
		if (PhotonNetwork.isMasterClient)
		{
			SetLastBallHitPlayer(player.PhotonPlayer);
		}
	}

	private SoccerShield GetPlayerShield(Player player)
	{
		SoccerShield soccerShield = null;
		if (player != null)
		{
			if (player.RightHand.IsHoldingTool)
			{
				soccerShield = player.RightHand.Tool as SoccerShield;
			}
			if (soccerShield == null && player.LeftHand.IsHoldingTool)
			{
				soccerShield = player.LeftHand.Tool as SoccerShield;
			}
		}
		return soccerShield;
	}

	private IEnumerator ShieldPickupCoroutine(SoccerShield shield)
	{
		if (shield == null)
		{
			yield break;
		}
		float timeout = 5f;
		float startTime = Time.time;
		while (!shield.gameObject.activeSelf && Time.time - startTime < timeout)
		{
			yield return null;
		}
		if (!shield.gameObject.activeSelf)
		{
			yield break;
		}
		PlayerHand dominantHand = Player.LocalPlayer.DominantHand;
		if (!(dominantHand == null))
		{
			if (dominantHand.Tool != null)
			{
				dominantHand.Tool.Release(Player.LocalPlayer, Vector3.zero, Vector3.zero);
			}
			Player.LocalPlayer.ToolController.TryPickupTool(shield, (int)dominantHand.Type);
		}
	}

	private void MasterGameOver(ActivityTeam winningTeam)
	{
		if (PhotonNetwork.isMasterClient)
		{
			SetIsGameOver(isGameOver: true);
			MasterActivityWon(winningTeam);
			base.photonView.RPC("RpcOnGameOver", PhotonTargets.All, winningTeam?.Id ?? ActivityTeam.InvalidTeamId);
			NetworkCollectible[] array = collectibles;
			foreach (NetworkCollectible networkCollectible in array)
			{
				networkCollectible.StopResetTimer();
			}
		}
	}

	private void RunGameOver(ActivityTeam winningTeam)
	{
		StartCoroutine(RunGameOverCoroutine(winningTeam));
	}

	private IEnumerator RunGameOverCoroutine(ActivityTeam winningTeam)
	{
		soccerAudio.StopPlayingMusic();
		soccerAudio.OnGameOver();
		RpcShowNotification("Game Over!", null, 2f);
		yield return new WaitForSeconds(2f);
		if (winningTeam != null)
		{
			if (winningTeam.IsBlueTeam)
			{
				soccerAudio.OnBlueTeamWin();
			}
			else
			{
				soccerAudio.OnRedTeamWin();
			}
			RpcShowNotification(winningTeam.Name + " Team Wins!", null, 3f);
			yield return new WaitForSeconds(3f);
		}
		else
		{
			soccerAudio.OnTieGame();
			RpcShowNotification("Tie Game!", null, 3f);
			yield return new WaitForSeconds(3f);
		}
		MasterEnterGameState(ActivityGameState.PreGame);
	}

	private void MasterSpawnPlayerShield(PhotonPlayer photonPlayer, Vector3 handPosition, Quaternion handRotation)
	{
		if (PhotonNetwork.isMasterClient)
		{
			GameObject gameObject = shieldPool.Acquire(handPosition, handRotation);
			SoccerShield soccerShield = ((!(gameObject != null)) ? null : gameObject.GetComponent<SoccerShield>());
			if (soccerShield == null)
			{
				UnityEngine.Debug.LogError("There are no shields available in the shield pool.");
				return;
			}
			base.photonView.RPC("RpcPickupShield", photonPlayer, soccerShield.photonView.viewID);
		}
	}

	[PunRPC]
	public void RpcOnScore(int scoringTeamId, PhotonPlayer scoringPlayer, Vector3 scoringPoint)
	{
		base.ActivityAudio.OnScore();
		goalParticles.transform.position = scoringPoint;
		goalParticles.Play();
		ActivityTeam team = base.PlayerManager.GetTeam(scoringTeamId);
		if (team.IsBlueTeam)
		{
			soccerAudio.OnBlueTeamScored();
		}
		else
		{
			soccerAudio.OnRedTeamScored();
		}
		RpcShowNotification(team.Name + " Team Scores!", "Scored by " + ((scoringPlayer == null) ? team.Name : scoringPlayer.name), 3f);
	}

	[PunRPC]
	public void RpcRequestShield(PhotonPlayer requestingPlayer, Vector3 handPosition, Quaternion handRotation)
	{
		MasterSpawnPlayerShield(requestingPlayer, handPosition, handRotation);
	}

	[PunRPC]
	public void RpcPickupShield(int shieldPhotonViewId)
	{
		PhotonView photonView = PhotonView.Find(shieldPhotonViewId);
		SoccerShield shield = ((!(photonView != null)) ? null : photonView.GetComponent<SoccerShield>());
		StartCoroutine(ShieldPickupCoroutine(shield));
	}

