public class SoccerShield : Tool
{
	public TeleportChargeVisual ChargeVisual;

	public Transform PowerupVisual;

	public float PowerupDepletionRateSeconds = 15f;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip powerupStart;

	private float _powerup;

	private bool _usingPowerup;

	private float defaultMaxTeleportDistance;

	private float fillPowerup;

	private float powerupFillSpeed = 1f;

	public float Powerup
	{
		get
		{
			return _powerup;
		}
		private set
		{
			_powerup = Mathf.Clamp01(value);
			ChargeVisual.Charge = Powerup;
			if (Powerup == 0f && UsingPowerup)
			{
				UsingPowerup = false;
			}
		}
	}

	public bool UsingPowerup
	{
		get
		{
			return _usingPowerup;
		}
		private set
		{
			bool flag = value && Powerup > 0f;
			if (_usingPowerup != flag)
			{
				_usingPowerup = flag;
				UpdatePowerupFX();
			}
		}
	}

	protected override void Start()
	{
		base.Start();
		defaultMaxTeleportDistance = ActivityManager.Instance.TeleportRestrictions.MaxTeleportDistance;
	}

	public override void OnOwnerRoleUpdated()
	{
		UpdateColor();
	}

	private void UpdatePowerupFX()
	{
		PowerupVisual.gameObject.SetActive(UsingPowerup);
		if (UsingPowerup)
		{
			AudioManager.Play3DSFX(powerupStart, base.transform);
		}
	}

	private void Update()
	{
		if (!base.IsHeld || !(base.Owner != null) || !base.Owner.isLocal)
		{
			return;
		}
		if (fillPowerup > 0f)
		{
			float num = Time.deltaTime * powerupFillSpeed;
			fillPowerup -= num;
			Powerup += num;
			if (Powerup >= 1f)
			{
				fillPowerup = 0f;
			}
		}
		if (UsingPowerup)
		{
			float num2 = Time.deltaTime * 1f / PowerupDepletionRateSeconds;
			Powerup -= num2;
		}
		ActivityManager.Instance.TeleportRestrictions.MaxTeleportDistance = ((!UsingPowerup) ? defaultMaxTeleportDistance : (defaultMaxTeleportDistance * 2f));
		base.Owner.PlayerLocomotion.MaxToolHitHoldTimeOverride = ((!UsingPowerup) ? ((float?)null) : new float?(0.1f));
	}

	public override void OnInputDown()
	{
		UsingPowerup = true;
	}

	public override void OnCollectiblePicked(NetworkCollectible collectible)
	{
		base.OnCollectiblePicked(collectible);
		if (base.Owner != null && base.Owner.isLocal)
		{
			fillPowerup = collectible.Value;
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
		UpdateColor();
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
		if (player != null && player.isLocal && ActivityManager.Instance != null)
		{
			ActivityManager.Instance.TeleportRestrictions.MaxTeleportDistance = defaultMaxTeleportDistance;
			Powerup = 0f;
			UsingPowerup = false;
		}
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading)
		{
			UsingPowerup = (bool)stream.ReceiveNext();
			Powerup = (float)stream.ReceiveNext();
		}
		else
		{
			stream.SendNext(UsingPowerup);
			stream.SendNext(Powerup);
		}
	}

	private void UpdateColor()
	{
		ActivityTeam activityTeam = ((!(base.Owner != null)) ? null : base.Owner.Team);
		if (activityTeam != null)
		{
			base.ToolRenderer.AccentColor = activityTeam.Color;
		}
		else
		{
			base.ToolRenderer.ResetAccentColor();
		}
	}
}
