		}
	}

	private void ToggleRightBar()
	{
		m_RightBar_IsOn = !m_RightBar_IsOn;
		if (m_RightBar_IsOn)
		{
			m_RightBar_A.MoveOut(GUIAnimSystemFREE.eGUIMove.SelfAndChildren);
			m_RightBar_B.MoveIn(GUIAnimSystemFREE.eGUIMove.SelfAndChildren);
