				RenderTextureFormat.RGHalf => fcPixelFormat.RGf16, 
				RenderTextureFormat.RHalf => fcPixelFormat.Rf16, 
				RenderTextureFormat.ARGBFloat => fcPixelFormat.RGBAf32, 
				RenderTextureFormat.RGFloat => fcPixelFormat.RGf32, 
				RenderTextureFormat.RFloat => fcPixelFormat.Rf32, 
				RenderTextureFormat.ARGBInt => fcPixelFormat.RGBAi32, 
				RenderTextureFormat.RGInt => fcPixelFormat.RGi32, 
				RenderTextureFormat.RInt => fcPixelFormat.Ri32, 
				_ => fcPixelFormat.Unknown, 
