				TextureFormat.RGBA32 => fcPixelFormat.RGBAu8, 
				TextureFormat.ARGB32 => fcPixelFormat.RGBAu8, 
				TextureFormat.RGBAHalf => fcPixelFormat.RGBAf16, 
				TextureFormat.RGHalf => fcPixelFormat.RGf16, 
				TextureFormat.RHalf => fcPixelFormat.Rf16, 
				TextureFormat.RGBAFloat => fcPixelFormat.RGBAf32, 
				TextureFormat.RGFloat => fcPixelFormat.RGf32, 
