	public static void DismissHSWDisplay()
	{
		if (isHmdPresent)
		{
			OVRPlugin.DismissHSW();
		}
	}

	private void Awake()
	{
		if (instance != null)
		{
			base.enabled = false;
			UnityEngine.Object.DestroyImmediate(this);
			return;
		}
		instance = this;
		UnityEngine.Debug.Log(string.Concat("Unity v", Application.unityVersion, ", Oculus Utilities v", OVRPlugin.wrapperVersion, ", OVRPlugin v", OVRPlugin.version, ", SDK v", OVRPlugin.nativeSDKVersion, "."));
		if (SystemInfo.graphicsDeviceType != GraphicsDeviceType.Direct3D11)
		{
			UnityEngine.Debug.LogWarning("VR rendering requires Direct3D11. Your graphics device: " + SystemInfo.graphicsDeviceType);
		}
		RuntimePlatform platform = Application.platform;
		isSupportedPlatform |= platform == RuntimePlatform.Android;
		isSupportedPlatform |= platform == RuntimePlatform.OSXEditor;
		isSupportedPlatform |= platform == RuntimePlatform.OSXPlayer;
		isSupportedPlatform |= platform == RuntimePlatform.WindowsEditor;
		isSupportedPlatform |= platform == RuntimePlatform.WindowsPlayer;
		if (!isSupportedPlatform)
		{
			UnityEngine.Debug.LogWarning("This platform is unsupported");
			return;
		}
		if (display == null)
		{
			display = new OVRDisplay();
		}
		if (tracker == null)
		{
			tracker = new OVRTracker();
		}
		if (resetTrackerOnLoad)
		{
			display.RecenterPose();
		}
		OVRPlugin.occlusionMesh = false;
		OVRPlugin.ignoreVrFocus = runInBackground;
	}

	private void Update()
	{
		paused = !OVRPlugin.hasVrFocus;
		if (OVRPlugin.shouldQuit)
		{
			Application.Quit();
		}
		if (OVRPlugin.shouldRecenter)
		{
			display.RecenterPose();
		}
		if (trackingOriginType != _trackingOriginType)
		{
			trackingOriginType = _trackingOriginType;
		}
		tracker.isEnabled = usePositionTracking;
		OVRPlugin.useIPDInPositionTracking = useIPDInPositionTracking;
		isHmdPresent = OVRPlugin.hmdPresent;
		if (isHmdPresent)
		{
			OVRPlugin.queueAheadFraction = ((!queueAhead) ? 0f : 0.25f);
		}
		if (useRecommendedMSAALevel && QualitySettings.antiAliasing != display.recommendedMSAALevel)
		{
			QualitySettings.antiAliasing = display.recommendedMSAALevel;
			UnityEngine.Debug.Log("MSAA level: " + QualitySettings.antiAliasing);
		}
		if (_wasHmdPresent && !isHmdPresent)
		{
			try
			{
				if (OVRManager.HMDLost != null)
				{
					OVRManager.HMDLost();
				}
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex);
			}
		}
		if (!_wasHmdPresent && isHmdPresent)
		{
			try
			{
				if (OVRManager.HMDAcquired != null)
				{
					OVRManager.HMDAcquired();
				}
			}
			catch (Exception ex2)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex2);
			}
		}
		_wasHmdPresent = isHmdPresent;
		isUserPresent = OVRPlugin.userPresent;
		if (_wasUserPresent && !isUserPresent)
		{
			try
			{
				if (OVRManager.HMDUnmounted != null)
				{
					OVRManager.HMDUnmounted();
				}
			}
			catch (Exception ex3)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex3);
			}
		}
		if (!_wasUserPresent && isUserPresent)
		{
			try
			{
				if (OVRManager.HMDMounted != null)
				{
					OVRManager.HMDMounted();
				}
			}
			catch (Exception ex4)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex4);
			}
		}
		_wasUserPresent = isUserPresent;
		hasVrFocus = OVRPlugin.hasVrFocus;
		if (_hadVrFocus && !hasVrFocus)
		{
			try
			{
				if (OVRManager.VrFocusLost != null)
				{
					OVRManager.VrFocusLost();
				}
			}
			catch (Exception ex5)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex5);
			}
		}
		if (!_hadVrFocus && hasVrFocus)
		{
			try
			{
				if (OVRManager.VrFocusAcquired != null)
				{
					OVRManager.VrFocusAcquired();
				}
			}
			catch (Exception ex6)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex6);
			}
		}
		_hadVrFocus = hasVrFocus;
		if (enableAdaptiveResolution)
		{
			if (VRSettings.renderScale < maxRenderScale)
			{
				VRSettings.renderScale = maxRenderScale;
			}
			else
			{
				maxRenderScale = Mathf.Max(maxRenderScale, VRSettings.renderScale);
			}
			float min = minRenderScale / VRSettings.renderScale;
			float value = OVRPlugin.GetEyeRecommendedResolutionScale() / VRSettings.renderScale;
			value = Mathf.Clamp(value, min, 1f);
			VRSettings.renderViewportScale = value;
		}
		string text = OVRPlugin.audioOutId;
		if (!prevAudioOutIdIsCached)
		{
			prevAudioOutId = text;
			prevAudioOutIdIsCached = true;
		}
		else if (text != prevAudioOutId)
		{
			try
			{
				if (OVRManager.AudioOutChanged != null)
				{
					OVRManager.AudioOutChanged();
				}
			}
			catch (Exception ex7)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex7);
			}
			prevAudioOutId = text;
		}
		string text2 = OVRPlugin.audioInId;
		if (!prevAudioInIdIsCached)
		{
			prevAudioInId = text2;
			prevAudioInIdIsCached = true;
		}
		else if (text2 != prevAudioInId)
		{
			try
			{
				if (OVRManager.AudioInChanged != null)
				{
					OVRManager.AudioInChanged();
				}
			}
			catch (Exception ex8)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex8);
			}
			prevAudioInId = text2;
		}
		if (wasPositionTracked && !tracker.isPositionTracked)
		{
			try
			{
				if (OVRManager.TrackingLost != null)
				{
					OVRManager.TrackingLost();
				}
			}
			catch (Exception ex9)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex9);
			}
		}
		if (!wasPositionTracked && tracker.isPositionTracked)
		{
			try
			{
				if (OVRManager.TrackingAcquired != null)
				{
					OVRManager.TrackingAcquired();
				}
			}
			catch (Exception ex10)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex10);
			}
		}
		wasPositionTracked = tracker.isPositionTracked;
		isHSWDisplayed = OVRPlugin.hswVisible;
		if (isHSWDisplayed && Input.anyKeyDown)
		{
			DismissHSWDisplay();
		}
		if (!isHSWDisplayed && _wasHSWDisplayed)
		{
			try
			{
				if (OVRManager.HSWDismissed != null)
				{
					OVRManager.HSWDismissed();
				}
			}
			catch (Exception ex11)
			{
				UnityEngine.Debug.LogError("Caught Exception: " + ex11);
			}
		}
		_wasHSWDisplayed = isHSWDisplayed;
		display.Update();
		OVRInput.Update();
	}

	private void LateUpdate()
	{
		OVRHaptics.Process();
	}

	public void ReturnToLauncher()
	{
		PlatformUIConfirmQuit();
	}

	public static void PlatformUIConfirmQuit()
	{
		if (isHmdPresent)
		{
			OVRPlugin.ShowUI(OVRPlugin.PlatformUI.ConfirmQuit);
		}
	}

	public static void PlatformUIGlobalMenu()
	{
		if (isHmdPresent)
		{
			OVRPlugin.ShowUI(OVRPlugin.PlatformUI.GlobalMenu);
		}
	}
}
public class OVROverlay : UnityEngine.MonoBehaviour
{
	public enum OverlayType
	{
		None,
		Underlay,
		Overlay,
		OverlayShowLod
	}

	private const int maxInstances = 15;

	private static OVROverlay[] instances = new OVROverlay[15];

	private OverlayType currentOverlayType = OverlayType.Overlay;

	private Texture texture;

	private IntPtr texId = IntPtr.Zero;

	private int layerIndex = -1;

	private Renderer rend;

	private void ApplyTexture()
	{
		if (!(rend.material.mainTexture == texture))
		{
			texture = rend.material.mainTexture;
			texId = texture.GetNativeTexturePtr();
		}
	}

	private void Awake()
	{
		UnityEngine.Debug.Log("Overlay Awake");
		rend = GetComponent<Renderer>();
		ApplyTexture();
	}

	private void OnEnable()
	{
		if (!OVRManager.isHmdPresent)
		{
			base.enabled = false;
			return;
		}
		OnDisable();
		for (int i = 0; i < 15; i++)
		{
			if (instances[i] == null || instances[i] == this)
			{
				layerIndex = i;
				instances[i] = this;
				break;
			}
		}
	}

	private void OnDisable()
	{
		if (layerIndex != -1)
		{
			rend.enabled = true;
			OVRPlugin.SetOverlayQuad(onTop: true, headLocked: false, IntPtr.Zero, IntPtr.Zero, OVRPose.identity.ToPosef(), Vector3.one.ToVector3f(), layerIndex);
			instances[layerIndex] = null;
		}
		layerIndex = -1;
	}

	private void Update()
	{
		ApplyTexture();
	}

	private void OnRenderObject()
	{
		if (Camera.current.cameraType == CameraType.Game && layerIndex != -1 && currentOverlayType != OverlayType.None)
		{
			bool onTop = currentOverlayType == OverlayType.Overlay;
			bool flag = false;
			Transform parent = base.transform;
			while (parent != null && !flag)
			{
				flag |= parent == Camera.current.transform;
				parent = parent.parent;
			}
			OVRPose oVRPose = ((!flag) ? base.transform.ToTrackingSpacePose() : base.transform.ToHeadSpacePose());
			Vector3 lossyScale = base.transform.lossyScale;
			for (int i = 0; i < 3; i++)
			{
				int index2;
				int index = (index2 = i);
				float num = lossyScale[index2];
				lossyScale[index] = num / Camera.current.transform.lossyScale[i];
			}
			bool flag2 = OVRPlugin.SetOverlayQuad(onTop, flag, texId, IntPtr.Zero, oVRPose.flipZ().ToPosef(), lossyScale.ToVector3f(), layerIndex);
			rend.enabled = !flag2;
		}
	}
}
public class OVRPlatformMenu : UnityEngine.MonoBehaviour
{
	public enum eHandler
	{
		ResetCursor,
		ShowGlobalMenu,
		ShowConfirmQuit
	}

	private enum eBackButtonAction
	{
		NONE,
		DOUBLE_TAP,
		SHORT_PRESS,
		LONG_PRESS
	}

	public GameObject cursorTimer;

	public Color cursorTimerColor = new Color(0f, 0.643f, 1f, 1f);

	public float fixedDepth = 3f;

	public KeyCode keyCode = KeyCode.Escape;

	public eHandler doubleTapHandler;

	public eHandler shortPressHandler = eHandler.ShowConfirmQuit;

	public eHandler longPressHandler = eHandler.ShowGlobalMenu;

	private GameObject instantiatedCursorTimer;

	private Material cursorTimerMaterial;

	private float doubleTapDelay = 0.25f;

	private float shortPressDelay = 0.25f;

	private float longPressDelay = 0.75f;

	private int downCount;

	private int upCount;

	private float initialDownTime = -1f;

	private bool waitForUp;

	private eBackButtonAction ResetAndSendAction(eBackButtonAction action)
	{
		UnityEngine.MonoBehaviour.print(string.Concat("ResetAndSendAction( ", action, " );"));
		downCount = 0;
		upCount = 0;
		initialDownTime = -1f;
		waitForUp = false;
		ResetCursor();
		if (action == eBackButtonAction.LONG_PRESS)
		{
			waitForUp = true;
		}
		return action;
	}

	private eBackButtonAction HandleBackButtonState()
	{
		if (waitForUp)
		{
			if (Input.GetKeyDown(keyCode) || Input.GetKey(keyCode))
			{
				return eBackButtonAction.NONE;
			}
			waitForUp = false;
		}
		if (Input.GetKeyDown(keyCode))
		{
			downCount++;
			if (downCount == 1)
			{
				initialDownTime = Time.realtimeSinceStartup;
			}
		}
		else if (downCount > 0)
		{
			if (Input.GetKey(keyCode))
			{
				if (downCount <= upCount)
				{
					downCount++;
				}
				float num = Time.realtimeSinceStartup - initialDownTime;
				if (num > shortPressDelay)
				{
					float timerRotateRatio = (num - shortPressDelay) / (longPressDelay - shortPressDelay);
					UpdateCursor(timerRotateRatio);
				}
				if (num > longPressDelay)
				{
					return ResetAndSendAction(eBackButtonAction.LONG_PRESS);
				}
			}
			else if (initialDownTime >= 0f)
			{
				if (upCount < downCount)
				{
					upCount++;
				}
				float num2 = Time.realtimeSinceStartup - initialDownTime;
				if (num2 < doubleTapDelay)
				{
					if (downCount == 2 && upCount == 2)
					{
						return ResetAndSendAction(eBackButtonAction.DOUBLE_TAP);
					}
				}
				else if (num2 > shortPressDelay)
				{
					if (downCount == 1 && upCount == 1)
					{
						return ResetAndSendAction(eBackButtonAction.SHORT_PRESS);
					}
				}
				else if (num2 < longPressDelay)
				{
					return ResetAndSendAction(eBackButtonAction.NONE);
				}
			}
		}
		return eBackButtonAction.NONE;
	}

	private void Awake()
	{
		if (!OVRManager.isHmdPresent)
		{
			base.enabled = false;
		}
		else if (cursorTimer != null && instantiatedCursorTimer == null)
		{
			instantiatedCursorTimer = UnityEngine.Object.Instantiate(cursorTimer);
			if (instantiatedCursorTimer != null)
			{
				cursorTimerMaterial = instantiatedCursorTimer.GetComponent<Renderer>().material;
				cursorTimerMaterial.SetColor("_Color", cursorTimerColor);
				instantiatedCursorTimer.GetComponent<Renderer>().enabled = false;
			}
		}
	}

	private void OnDestroy()
	{
		if (cursorTimerMaterial != null)
		{
			UnityEngine.Object.Destroy(cursorTimerMaterial);
		}
	}

	private void OnApplicationFocus(bool focusState)
	{
	}

	private void OnApplicationPause(bool pauseStatus)
	{
		if (!pauseStatus)
		{
			Input.ResetInputAxes();
		}
	}

	private void ShowConfirmQuitMenu()
	{
		ResetCursor();
	}

	private void ShowGlobalMenu()
	{
	}

	private void DoHandler(eHandler handler)
	{
		if (handler == eHandler.ResetCursor)
		{
			ResetCursor();
		}
		if (handler == eHandler.ShowConfirmQuit)
		{
			ShowConfirmQuitMenu();
		}
		if (handler == eHandler.ShowGlobalMenu)
		{
			ShowGlobalMenu();
		}
	}

	private void Update()
	{
	}

	private void UpdateCursor(float timerRotateRatio)
	{
		timerRotateRatio = Mathf.Clamp(timerRotateRatio, 0f, 1f);
		if (instantiatedCursorTimer != null)
		{
			instantiatedCursorTimer.GetComponent<Renderer>().enabled = true;
			float value = Mathf.Clamp(1f - timerRotateRatio, 0f, 1f);
			cursorTimerMaterial.SetFloat("_ColorRampOffset", value);
			Vector3 forward = Camera.main.transform.forward;
			Vector3 position = Camera.main.transform.position;
			instantiatedCursorTimer.transform.position = position + forward * fixedDepth;
			instantiatedCursorTimer.transform.forward = forward;
		}
	}

	private void ResetCursor()
	{
		if (instantiatedCursorTimer != null)
		{
			cursorTimerMaterial.SetFloat("_ColorRampOffset", 1f);
			instantiatedCursorTimer.GetComponent<Renderer>().enabled = false;
		}
	}
}
