	}

	private static bool GetCap(Caps cap)
	{
		if (version >= OVRP_0_1_3.version)
		{
			return OVRP_0_1_3.ovrp_GetCaps2((uint)(1 << (int)cap)) != 0;
		}
		return ((uint)OVRP_0_1_0.ovrp_GetCaps() & (uint)(1 << (int)cap)) != 0;
	}

	private static void SetCap(Caps cap, bool value)
	{
		if (GetCap(cap) != value)
		{
			int num = (int)OVRP_0_1_0.ovrp_GetCaps();
			num = ((!value) ? (num & ~(1 << (int)cap)) : (num | (1 << (int)cap)));
			OVRP_0_1_0.ovrp_SetCaps((Caps)num);
		}
	}

