public class OVRSceneSampleController : UnityEngine.MonoBehaviour
{
	public KeyCode quitKey = KeyCode.Escape;

	public Texture fadeInTexture;

	public float speedRotationIncrement = 0.05f;

	private OVRPlayerController playerController;

	private OVRCameraRig cameraController;

	public string layerName = "Default";

	private bool visionMode = true;

	private OVRGridCube gridCube;

	private void Awake()
	{
		OVRCameraRig[] componentsInChildren = base.gameObject.GetComponentsInChildren<OVRCameraRig>();
		if (componentsInChildren.Length == 0)
		{
			UnityEngine.Debug.LogWarning("OVRMainMenu: No OVRCameraRig attached.");
		}
		else if (componentsInChildren.Length > 1)
		{
			UnityEngine.Debug.LogWarning("OVRMainMenu: More then 1 OVRCameraRig attached.");
		}
		else
		{
			cameraController = componentsInChildren[0];
		}
		OVRPlayerController[] componentsInChildren2 = base.gameObject.GetComponentsInChildren<OVRPlayerController>();
		if (componentsInChildren2.Length == 0)
		{
			UnityEngine.Debug.LogWarning("OVRMainMenu: No OVRPlayerController attached.");
		}
		else if (componentsInChildren2.Length > 1)
		{
			UnityEngine.Debug.LogWarning("OVRMainMenu: More then 1 OVRPlayerController attached.");
		}
		else
		{
			playerController = componentsInChildren2[0];
		}
	}

	private void Start()
	{
		if (!Application.isEditor)
		{
			Cursor.visible = false;
			Cursor.lockState = CursorLockMode.Locked;
		}
		if (cameraController != null)
		{
			gridCube = base.gameObject.AddComponent<OVRGridCube>();
			gridCube.SetOVRCameraController(ref cameraController);
		}
	}

	private void Update()
	{
		UpdateRecenterPose();
		UpdateVisionMode();
		if (playerController != null)
		{
			UpdateSpeedAndRotationScaleMultiplier();
		}
		if (Input.GetKeyDown(KeyCode.F11))
		{
			Screen.fullScreen = !Screen.fullScreen;
		}
		if (Input.GetKeyDown(KeyCode.M))
		{
			VRSettings.showDeviceView = !VRSettings.showDeviceView;
		}
		if (Input.GetKeyDown(quitKey))
		{
			Application.Quit();
		}
	}

	private void UpdateVisionMode()
	{
		if (Input.GetKeyDown(KeyCode.F2))
		{
			visionMode ^= visionMode;
			OVRManager.tracker.isEnabled = visionMode;
		}
	}

	private void UpdateSpeedAndRotationScaleMultiplier()
	{
		float moveScaleMultiplier = 0f;
		playerController.GetMoveScaleMultiplier(ref moveScaleMultiplier);
		if (Input.GetKeyDown(KeyCode.Alpha7))
		{
			moveScaleMultiplier -= speedRotationIncrement;
		}
		else if (Input.GetKeyDown(KeyCode.Alpha8))
		{
			moveScaleMultiplier += speedRotationIncrement;
		}
		playerController.SetMoveScaleMultiplier(moveScaleMultiplier);
		float rotationScaleMultiplier = 0f;
		playerController.GetRotationScaleMultiplier(ref rotationScaleMultiplier);
		if (Input.GetKeyDown(KeyCode.Alpha9))
		{
			rotationScaleMultiplier -= speedRotationIncrement;
		}
		else if (Input.GetKeyDown(KeyCode.Alpha0))
		{
			rotationScaleMultiplier += speedRotationIncrement;
		}
		playerController.SetRotationScaleMultiplier(rotationScaleMultiplier);
	}

	private void UpdateRecenterPose()
	{
		if (Input.GetKeyDown(KeyCode.R))
		{
			OVRManager.display.RecenterPose();
		}
	}
}
public class OVRScreenFade : UnityEngine.MonoBehaviour
{
	public float fadeTime = 2f;

	public Color fadeColor = new Color(0.01f, 0.01f, 0.01f, 1f);

	private Material fadeMaterial;

	private bool isFading;

	private YieldInstruction fadeInstruction = new WaitForEndOfFrame();

	private void Awake()
	{
		fadeMaterial = new Material(Shader.Find("Oculus/Unlit Transparent Color"));
		SceneManager.sceneLoaded += SceneManager_sceneLoaded;
	}

	private void OnEnable()
	{
		StartCoroutine(FadeIn());
	}

	private void SceneManager_sceneLoaded(Scene scene, LoadSceneMode loadSceneMode)
	{
		StartCoroutine(FadeIn());
	}

	private void OnDestroy()
	{
		if (fadeMaterial != null)
		{
			UnityEngine.Object.Destroy(fadeMaterial);
		}
		SceneManager.sceneLoaded -= SceneManager_sceneLoaded;
	}

	private IEnumerator FadeIn()
	{
		float elapsedTime = 0f;
		fadeMaterial.color = fadeColor;
		Color color = fadeColor;
		isFading = true;
		while (elapsedTime < fadeTime)
		{
			yield return fadeInstruction;
			elapsedTime += Time.deltaTime;
			color.a = 1f - Mathf.Clamp01(elapsedTime / fadeTime);
			fadeMaterial.color = color;
		}
		isFading = false;
	}

	private void OnPostRender()
	{
		if (isFading)
		{
			fadeMaterial.SetPass(0);
			GL.PushMatrix();
			GL.LoadOrtho();
			GL.Color(fadeMaterial.color);
			GL.Begin(7);
			GL.Vertex3(0f, 0f, -12f);
			GL.Vertex3(0f, 1f, -12f);
			GL.Vertex3(1f, 1f, -12f);
			GL.Vertex3(1f, 0f, -12f);
			GL.End();
			GL.PopMatrix();
		}
	}
}
[ExecuteInEditMode]
public class OVRTrackerBounds : UnityEngine.MonoBehaviour
{
	private static readonly int numPlanes = 6;

	private Plane[] plane = new Plane[numPlanes];

	public bool enableFade = true;

	[Tooltip("Distance from volume to start fading")]
	public float fadeDistance = 0.1f;

	[Tooltip("Maximum fade amount (from 0.0 to 1.0)")]
	public float fadeMaximum = 0.2f;

	public Color fadeColor = Color.black;

	public bool enableIcons;

	public Texture2D[] iconTextures;

	public RawImage iconImage;

	public bool enableArrow = true;

	public GameObject arrowObject;

	public Vector3 arrowOffset = Vector3.zero;

	public float arrowDistance = 0.2f;

	public float animSpeed = 10f;

	public float animDistance = 0.2f;

	public float waitTime = 10f;

	private Material fadeMaterial;

	private Color iconColor = new Color(1f, 1f, 1f, 1f);

	public void SetEnableFade(bool b)
	{
		enableFade = b;
	}

	public void SetEnableArrow(bool b)
	{
		enableArrow = b;
	}

	private void Awake()
	{
		if (Application.isPlaying)
		{
			fadeMaterial = new Material(Shader.Find("Oculus/Unlit Transparent Color"));
		}
	}

	private void OnDestroy()
	{
		if (fadeMaterial != null)
		{
			UnityEngine.Object.Destroy(fadeMaterial);
		}
	}

	private void ComputePlanes()
	{
		OVRTracker.Frustum frustum = OVRManager.tracker.GetFrustum();
		float nearZ = frustum.nearZ;
		float farZ = frustum.farZ;
		float f = (float)Math.PI / 180f * frustum.fov.x * 0.5f;
		float f2 = (float)Math.PI / 180f * frustum.fov.y * 0.5f;
		float num = Mathf.Sin(f);
		float num2 = Mathf.Sin(f2);
		ref Plane reference = ref plane[0];
		reference = new Plane(Vector3.zero, farZ * new Vector3(num, num2, 1f), farZ * new Vector3(num, 0f - num2, 1f));
		ref Plane reference2 = ref plane[1];
		reference2 = new Plane(Vector3.zero, farZ * new Vector3(0f - num, 0f - num2, 1f), farZ * new Vector3(0f - num, num2, 1f));
		ref Plane reference3 = ref plane[2];
		reference3 = new Plane(Vector3.zero, farZ * new Vector3(0f - num, num2, 1f), farZ * new Vector3(num, num2, 1f));
		ref Plane reference4 = ref plane[3];
		reference4 = new Plane(Vector3.zero, farZ * new Vector3(num, 0f - num2, 1f), farZ * new Vector3(0f - num, 0f - num2, 1f));
		ref Plane reference5 = ref plane[4];
		reference5 = new Plane(farZ * new Vector3(num, num2, 1f), farZ * new Vector3(0f - num, num2, 1f), farZ * new Vector3(0f - num, 0f - num2, 1f));
		ref Plane reference6 = ref plane[5];
		reference6 = new Plane(nearZ * new Vector3(0f - num, 0f - num2, 1f), nearZ * new Vector3(0f - num, num2, 1f), nearZ * new Vector3(num, num2, 1f));
	}

	private float DistanceToPlanes(Vector3 p, out int closestPlane)
	{
		float num = float.NegativeInfinity;
		closestPlane = 0;
		for (int i = 0; i < numPlanes; i++)
		{
			float distanceToPoint = plane[i].GetDistanceToPoint(p);
			if (distanceToPoint > num)
			{
				closestPlane = i;
				num = distanceToPoint;
			}
		}
		return num;
	}

	private static float SmoothStep(float a, float b, float x)
	{
		float num = Mathf.Clamp01((x - a) / (b - a));
		return num * num * (3f - 2f * num);
	}

	private void Update()
	{
		if (!Application.isPlaying || !OVRManager.tracker.isPresent || Time.time < waitTime)
		{
			if ((bool)arrowObject && arrowObject.activeSelf)
			{
				arrowObject.SetActive(value: false);
			}
			if (iconImage != null)
			{
				iconImage.enabled = false;
				iconImage.gameObject.SetActive(value: false);
			}
			return;
		}
		ComputePlanes();
		OVRPose pose = OVRManager.tracker.GetPose();
		Matrix4x4 matrix4x = Matrix4x4.TRS(pose.position, pose.orientation, Vector3.one);
		OVRPose oVRPose = default(OVRPose);
		oVRPose.position = InputTracking.GetLocalPosition(VRNode.Head);
		Vector3 p = matrix4x.inverse.MultiplyPoint(oVRPose.position);
		int closestPlane;
		float num = DistanceToPlanes(p, out closestPlane);
		if (enableIcons)
		{
			if (num > 0f - fadeDistance)
			{
				iconImage.gameObject.SetActive(value: true);
				iconImage.enabled = true;
				iconImage.texture = iconTextures[closestPlane];
				iconColor.a = SmoothStep(0f - fadeDistance, 0f, num);
				iconImage.color = iconColor;
			}
			else
			{
				iconImage.enabled = false;
				iconImage.gameObject.SetActive(value: false);
			}
		}
		if ((bool)arrowObject)
		{
			if (enableArrow && num > 0f - arrowDistance)
			{
				arrowObject.SetActive(value: true);
				Vector3 normal = plane[closestPlane].normal;
				Vector3 vector = matrix4x.MultiplyVector(normal);
				arrowObject.transform.localPosition = arrowOffset + vector * Mathf.Sin(Time.time * animSpeed) * animDistance;
				arrowObject.transform.rotation = Quaternion.FromToRotation(Vector3.forward, -vector);
			}
			else
			{
				arrowObject.SetActive(value: false);
			}
		}
		fadeMaximum = Mathf.Clamp01(fadeMaximum);
		fadeColor.a = SmoothStep(0f - fadeDistance, 0f, num) * fadeMaximum;
	}

	private void OnRenderObject()
	{
		if (Application.isPlaying && OVRManager.tracker.isPresent && !(Time.time < waitTime) && enableFade && (double)fadeColor.a > 0.0)
		{
			fadeMaterial.color = fadeColor;
			fadeMaterial.SetPass(0);
			GL.PushMatrix();
			GL.LoadOrtho();
			GL.Begin(7);
			GL.Vertex3(0f, 0f, 0f);
			GL.Vertex3(0f, 1f, 0f);
			GL.Vertex3(1f, 1f, 0f);
			GL.Vertex3(1f, 0f, 0f);
			GL.End();
			GL.PopMatrix();
		}
	}
}
