	public class Decoder : IDisposable
	{
		private IntPtr dec;

		private float[] decodedScratchBuffer;

		public Decoder()
		{
			dec = CAPI.ovr_Voip_CreateDecoder();
			decodedScratchBuffer = new float[4800];
		}

		public void Dispose()
		{
			if (dec != IntPtr.Zero)
			{
				CAPI.ovr_Voip_DestroyEncoder(dec);
				dec = IntPtr.Zero;
			}
		}

		public float[] Decode(byte[] data)
		{
			CAPI.ovr_VoipDecoder_Decode(dec, data, (uint)data.Length);
			ulong num = (ulong)CAPI.ovr_VoipDecoder_GetDecodedPCM(dec, decodedScratchBuffer, (UIntPtr)(ulong)decodedScratchBuffer.Length);
			if (num != 0)
			{
				float[] array = new float[num];
				Array.Copy(decodedScratchBuffer, array, (int)num);
				return array;
			}
			return null;
		}
	}
	public class Encoder : IDisposable
	{
		private IntPtr enc;

		public Encoder()
		{
			enc = CAPI.ovr_Voip_CreateEncoder();
		}

		public void Dispose()
		{
			if (enc != IntPtr.Zero)
			{
				CAPI.ovr_Voip_DestroyEncoder(enc);
				enc = IntPtr.Zero;
			}
		}

		public byte[] Encode(float[] samples)
		{
			CAPI.ovr_VoipEncoder_AddPCM(enc, samples, (uint)samples.Length);
			ulong num = (ulong)CAPI.ovr_VoipEncoder_GetCompressedDataSize(enc);
			if (num != 0)
			{
				byte[] array = new byte[num];
				ulong num2 = (ulong)CAPI.ovr_VoipEncoder_GetCompressedData(enc, array, (UIntPtr)num);
				if (num2 != num)
				{
					throw new Exception("Read size differed from reported size");
				}
				return array;
			}
			return null;
		}
	}
