	public class VoipAudioSource : UnityEngine.MonoBehaviour
	{
		public bool spatialize = true;

		private BufferedAudioStream bufferedAudioStream;

		private Decoder decoder;

		protected List<float> debugOutputData;

		private void Start()
		{
			AudioSource audioSource = base.gameObject.AddComponent<AudioSource>();
			UnityEngine.Debug.Log(audioSource);
			audioSource.spatialize = spatialize;
			bufferedAudioStream = new BufferedAudioStream(audioSource);
			decoder = new Decoder();
		}

		public void Stop()
		{
		}

		public void AddCompressedData(byte[] compressedData)
		{
			if (decoder == null || bufferedAudioStream == null)
			{
				throw new Exception("VoipAudioSource failed to init");
			}
			float[] array = decoder.Decode(compressedData);
			if (array != null && array.Length > 0)
			{
				bufferedAudioStream.AddData(array);
				if (debugOutputData != null)
				{
					debugOutputData.AddRange(array);
				}
			}
		}

		private void Update()
		{
			if (bufferedAudioStream == null)
			{
				throw new Exception("VoipAudioSource failed to init");
			}
			bufferedAudioStream.Update();
		}
	}
	public class VoipAudioSourceHiLevel : UnityEngine.MonoBehaviour
	{
		public class FilterReadDelegate : UnityEngine.MonoBehaviour
		{
			public VoipAudioSourceHiLevel parent;

			private float[] scratchBuffer;

			private void Awake()
			{
				int num = (int)(uint)CAPI.ovr_Voip_GetOutputBufferMaxSize();
				scratchBuffer = new float[num];
			}

			private void OnAudioFilterRead(float[] data, int channels)
			{
				int num = data.Length / channels;
				int num2 = num;
				if (num2 > scratchBuffer.Length)
				{
					Array.Clear(data, 0, data.Length);
					throw new Exception($"Audio system tried to pull {num} bytes, max voip internal ring buffer size {scratchBuffer.Length}");
				}
				int pCM = parent.pcmSource.GetPCM(scratchBuffer, num2);
				if (pCM < num2)
				{
					if (verboseLogging)
					{
						UnityEngine.Debug.LogFormat("Voip starved!!!, want {0}, but only have {1} available", num, pCM);
					}
					return;
				}
				int num3 = 0;
				for (int i = 0; i < num; i++)
				{
					float num4 = scratchBuffer[i];
					for (int j = 0; j < channels; j++)
					{
						data[num3++] = num4;
					}
				}
			}
		}

		private int initialPlaybackDelayMS;

		public AudioSource audioSource;

		protected IVoipPCMSource pcmSource;

		private static int audioSystemPlaybackFrequency;

		private static bool verboseLogging = true;

		public ulong senderID
		{
			set
			{
				pcmSource.SetSenderID(value);
			}
		}

		protected void Stop()
		{
		}

		private VoipSampleRate SampleRateToEnum(int rate)
		{
			return rate switch
			{
				48000 => VoipSampleRate.HZ48000, 
				44100 => VoipSampleRate.HZ44100, 
				24000 => VoipSampleRate.HZ24000, 
				_ => VoipSampleRate.Unknown, 
			};
		}

		protected void Awake()
		{
			CreatePCMSource();
			if (audioSource == null)
			{
				audioSource = base.gameObject.AddComponent<AudioSource>();
			}
			audioSource.gameObject.AddComponent<FilterReadDelegate>();
			FilterReadDelegate component = audioSource.gameObject.GetComponent<FilterReadDelegate>();
			component.parent = this;
			initialPlaybackDelayMS = 40;
			audioSystemPlaybackFrequency = AudioSettings.outputSampleRate;
			CAPI.ovr_Voip_SetOutputSampleRate(SampleRateToEnum(audioSystemPlaybackFrequency));
			if (verboseLogging)
			{
				UnityEngine.Debug.LogFormat("freq {0}", audioSystemPlaybackFrequency);
			}
		}

		private void Start()
		{
			audioSource.Stop();
		}

		protected virtual void CreatePCMSource()
		{
			pcmSource = new VoipPCMSourceNative();
		}

		protected static int MSToElements(int ms)
		{
			return ms * audioSystemPlaybackFrequency / 1000;
		}

		private void Update()
		{
			pcmSource.Update();
			if (!audioSource.isPlaying && pcmSource.PeekSizeElements() >= MSToElements(initialPlaybackDelayMS))
			{
				if (verboseLogging)
				{
					UnityEngine.Debug.LogFormat("buffered {0} elements, starting playback", pcmSource.PeekSizeElements());
				}
				audioSource.Play();
			}
		}
	}
	public class VoipInput : UnityEngine.MonoBehaviour
	{
		public delegate void OnCompressedData(byte[] compressedData);

		public OnCompressedData onCompressedData;

		protected IMicrophone micInput;

		private Encoder encoder;

		public bool enableMicRecording;

		protected void Start()
		{
			encoder = new Encoder();
			if (UnityEngine.Application.platform == RuntimePlatform.WindowsEditor || UnityEngine.Application.platform == RuntimePlatform.WindowsPlayer)
			{
				micInput = new MicrophoneInputNative();
			}
			else
			{
				micInput = new MicrophoneInput();
			}
			enableMicRecording = true;
		}

		private void OnApplicationQuit()
		{
			micInput.Stop();
		}

		private void Update()
		{
			if (micInput == null || encoder == null)
			{
				throw new Exception("VoipInput failed to init");
			}
			if (micInput == null || !enableMicRecording)
			{
				return;
			}
			float[] array = micInput.Update();
			if (array != null && array.Length > 5120)
			{
				UnityEngine.Debug.Log($"Giant input mic data {array.Length}");
			}
			else
			{
				if (array == null || array.Length <= 0)
				{
					return;
				}
				int num = 0;
				int num2 = array.Length;
				int val = 480;
				do
				{
					int num3 = Math.Min(val, num2);
					float[] array2 = new float[num3];
					Array.Copy(array, num, array2, 0, num3);
					num += num3;
					num2 -= num3;
					byte[] array3 = null;
					array3 = encoder.Encode(array2);
					if (array3 != null && array3.Length > 0)
					{
						onCompressedData(array3);
					}
				}
				while (num2 > 0);
			}
		}
	}
