	public class OpusDecoder : IDisposable
	{
		private const int MaxFrameSize = 5760;

		private IntPtr _handle = IntPtr.Zero;

		private string _version = string.Empty;

		private bool _previousPacketInvalid;

		private int _channelCount = 2;

		private Bandwidth? _previousPacketBandwidth;

		private float[] lostDataFloats;

		private float[] tempData;

		private float[] pcm;

		public string Version => _version;

		public Bandwidth? PreviousPacketBandwidth => _previousPacketBandwidth;

		public OpusDecoder(SamplingRate outputSamplingRateHz, Channels numChannels)
		{
			if (outputSamplingRateHz != SamplingRate.Sampling08000 && outputSamplingRateHz != SamplingRate.Sampling12000 && outputSamplingRateHz != SamplingRate.Sampling16000 && outputSamplingRateHz != SamplingRate.Sampling24000 && outputSamplingRateHz != SamplingRate.Sampling48000)
			{
				throw new ArgumentOutOfRangeException("outputSamplingRateHz", string.Concat("Must use one of the pre-defined sampling rates (", outputSamplingRateHz, ")"));
			}
			if (numChannels != Channels.Mono && numChannels != Channels.Stereo)
			{
				throw new ArgumentOutOfRangeException("numChannels", "Must be Mono or Stereo");
			}
			_channelCount = (int)numChannels;
			_handle = Wrapper.opus_decoder_create(outputSamplingRateHz, numChannels);
			_version = Marshal.PtrToStringAnsi(Wrapper.opus_get_version_string());
			if (_handle == IntPtr.Zero)
			{
				throw new OpusException(OpusStatusCode.AllocFail, "Memory was not allocated for the encoder");
			}
		}

		public short[] DecodePacketLost()
		{
			_previousPacketInvalid = true;
			int num = Wrapper.get_opus_decoder_ctl(_handle, OpusCtlGetRequest.LastPacketDurationRequest);
			short[] src = new short[num * _channelCount];
			int num2 = Wrapper.opus_decode(_handle, null, src, 0, _channelCount);
			if (num2 == 0)
			{
				return new short[0];
			}
			short[] array = new short[num2 * _channelCount];
			Buffer.BlockCopy(src, 0, array, 0, array.Length * 2);
			return array;
		}

		public float[] DecodePacketLostFloat()
		{
			_previousPacketInvalid = true;
			int num = Wrapper.get_opus_decoder_ctl(_handle, OpusCtlGetRequest.LastPacketDurationRequest);
			if (lostDataFloats == null || lostDataFloats.Length != num * _channelCount)
			{
				lostDataFloats = new float[num * _channelCount];
			}
			int num2 = Wrapper.opus_decode(_handle, null, lostDataFloats, 0, _channelCount);
			if (num2 == 0)
			{
				return new float[0];
			}
			if (pcm == null || pcm.Length != num2 * _channelCount)
			{
				pcm = new float[num2 * _channelCount];
			}
			Buffer.BlockCopy(lostDataFloats, 0, pcm, 0, pcm.Length * 4);
			return pcm;
		}

		public short[] DecodePacket(byte[] packetData)
		{
			short[] src = new short[5760 * _channelCount];
			int num = Wrapper.opus_packet_get_bandwidth(packetData);
			int num2 = 0;
			if (num == -4)
			{
				num2 = Wrapper.opus_decode(_handle, null, src, 0, _channelCount);
				_previousPacketInvalid = true;
			}
			else
			{
				_previousPacketBandwidth = (Bandwidth)num;
				num2 = Wrapper.opus_decode(_handle, packetData, src, 0, _channelCount);
				_previousPacketInvalid = false;
			}
			if (num2 == 0)
			{
				return new short[0];
			}
			short[] array = new short[num2 * _channelCount];
			Buffer.BlockCopy(src, 0, array, 0, array.Length * 2);
			return array;
		}

		public float[] DecodePacketFloat(byte[] packetData)
		{
			if (tempData == null || tempData.Length != 5760 * _channelCount)
			{
				tempData = new float[5760 * _channelCount];
			}
			int num = Wrapper.opus_packet_get_bandwidth(packetData);
			int num2 = 0;
			if (num == -4)
			{
				num2 = Wrapper.opus_decode(_handle, null, tempData, 0, _channelCount);
				_previousPacketInvalid = true;
			}
			else
			{
				_previousPacketBandwidth = (Bandwidth)num;
				num2 = Wrapper.opus_decode(_handle, packetData, tempData, 0, _channelCount);
				_previousPacketInvalid = false;
			}
			if (num2 == 0)
			{
				return new float[0];
			}
			if (pcm == null || pcm.Length != num2 * _channelCount)
			{
				pcm = new float[num2 * _channelCount];
			}
			Buffer.BlockCopy(tempData, 0, pcm, 0, pcm.Length * 4);
			return pcm;
		}

		public void Dispose()
		{
			if (_handle != IntPtr.Zero)
			{
				Wrapper.opus_decoder_destroy(_handle);
				_handle = IntPtr.Zero;
			}
		}
	}
