	public class LocalVoice : OpusEncoder, IDisposable
	{
		private int voiceDetectorCalibrateCount;

		private static byte idCnt;

		internal byte id;

		internal byte evNumber;

		private Client client;

		private IAudioStream audioStream;

		private int sourceSamplingRateHz;

		internal object userData;

		internal int frameSize;

		private float[] frameBuffer;

		internal int sourceFrameSize;

		private float[] sourceFrameBuffer;

		public byte AudioGroup { get; set; }

		public bool Transmit { get; set; }

		public bool IsTransmitting => Transmit && (!VoiceDetector.On || VoiceDetector.Detected);

		public VoiceDetector VoiceDetector { get; private set; }

		public LevelMeter LevelMeter { get; private set; }

		public bool VoiceDetectorCalibrating => voiceDetectorCalibrateCount > 0;

		internal LocalVoice(Client client, byte id, IAudioStream audioStream, object userData, int encoderSamplingRateHz, int numChannels, int bitrate, int delay)
			: base((SamplingRate)encoderSamplingRateHz, (Channels)numChannels, bitrate, OpusApplicationType.Voip, (Delay)delay)
		{
			this.client = client;
			this.id = id;
			this.audioStream = audioStream;
			sourceSamplingRateHz = audioStream.SamplingRate;
			this.userData = userData;
			frameSize = VoiceUtil.DelayToFrameSize(delay, encoderSamplingRateHz, numChannels);
			sourceFrameSize = frameSize * sourceSamplingRateHz / (int)base.InputSamplingRate;
			frameBuffer = new float[frameSize];
			if (sourceFrameSize == frameSize)
			{
				sourceFrameBuffer = frameBuffer;
			}
			else
			{
				sourceSamplingRateHz = audioStream.SamplingRate;
				sourceFrameBuffer = new float[sourceFrameSize];
				this.client.DebugReturn(DebugLevel.WARNING, "[PV] Local voice #" + this.id + " audio source frequency " + sourceSamplingRateHz + " and encoder sampling rate " + (int)base.InputSamplingRate + " do not match. Resampling will occur before encoding.");
			}
			LevelMeter = new LevelMeter(sourceSamplingRateHz, numChannels);
			VoiceDetector = new VoiceDetector(sourceSamplingRateHz, numChannels);
		}

		public void VoiceDetectorCalibrate(int durationMs)
		{
			voiceDetectorCalibrateCount = sourceSamplingRateHz * (int)base.InputChannels * durationMs / 1000;
			LevelMeter.ResetAccumAvgPeakAmp();
		}

		internal void service()
		{
			while (processStream())
			{
			}
		}

		private bool readStream()
		{
			if (!audioStream.GetData(sourceFrameBuffer))
			{
				return false;
			}
			LevelMeter.process(sourceFrameBuffer);
			if (voiceDetectorCalibrateCount != 0)
			{
				voiceDetectorCalibrateCount -= sourceFrameBuffer.Length;
				if (voiceDetectorCalibrateCount <= 0)
				{
					voiceDetectorCalibrateCount = 0;
					VoiceDetector.Threshold = LevelMeter.AccumAvgPeakAmp * 2f;
				}
			}
			if (VoiceDetector.On)
			{
				VoiceDetector.process(sourceFrameBuffer);
				if (!VoiceDetector.Detected)
				{
					return false;
				}
			}
			if (sourceFrameSize != frameSize)
			{
				VoiceUtil.Resample(sourceFrameBuffer, frameBuffer, (int)base.InputChannels);
			}
			return true;
		}

		private bool processStream()
		{
			if (client.State == ClientState.Joined && Transmit)
			{
				if (readStream())
				{
					client.sendFrame(id, evNumber++, compress(frameBuffer), AudioGroup);
					return true;
				}
				return false;
			}
			return false;
		}

		private byte[] compress(float[] buffer)
		{
			return Encode(buffer);
		}
	}
	internal class RemoteVoice : OpusDecoder
	{
		internal byte lastEvNumber;

		private Client client;

		internal VoiceInfo Info { get; private set; }

		internal RemoteVoice(Client client, VoiceInfo info, SamplingRate outputSamplingRateHz, Channels numChannels, byte lastEventNumber)
			: base(outputSamplingRateHz, numChannels)
		{
			this.client = client;
			Info = info;
			lastEvNumber = lastEventNumber;
		}

		internal float[] decompress(byte[] buffer)
		{
			float[] array;
			if (buffer == null && client.UseLossCompensation)
			{
				array = DecodePacketLostFloat();
				client.DebugReturn(DebugLevel.ALL, "[PV] lost packet decoded length: " + array.Length);
			}
			else
			{
				array = DecodePacketFloat(buffer);
			}
			return array;
		}
	}
	public class Client : LoadBalancingClient
	{
		private byte globalAudioGroup;

		private bool debugEchoMode;

		private byte voiceIdCnt;

		private List<LocalVoice> localVoices = new List<LocalVoice>();

		private Dictionary<int, Dictionary<byte, RemoteVoice>> remoteVoices = new Dictionary<int, Dictionary<byte, RemoteVoice>>();

		private System.Random rnd = new System.Random();

		public bool DebugEchoMode
		{
			get
			{
				return debugEchoMode;
			}
			set
			{
				debugEchoMode = value;
				if (base.State == ClientState.Joined)
				{
					if (debugEchoMode)
					{
						sendVoicesInfo(base.LocalPlayer.ID, localVoices);
						return;
					}
					object[] customEventContent = new object[2]
					{
						(byte)0,
						EventSubcode.DebugEchoRemoveMyVoices
					};
					ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions raiseEventOptions = new ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions();
					raiseEventOptions.TargetActors = new int[1] { base.LocalPlayer.ID };
					OpRaiseEvent(201, customEventContent, sendReliable: true, raiseEventOptions);
				}
			}
		}

		public int DebugLostPercent { get; set; }

		public bool UseLossCompensation { get; set; }

		public int FramesLost { get; private set; }

		public int FramesReceived { get; private set; }

		public Action<int, byte, VoiceInfo> OnRemoteVoiceInfoAction { get; set; }

		public Action<int, byte> OnRemoteVoiceRemoveAction { get; set; }

		public Action<int, byte, float[]> OnAudioFrameAction { get; set; }

		public IEnumerable<RemoteVoiceInfo> RemoteVoiceInfos
		{
			get
			{
				foreach (KeyValuePair<int, Dictionary<byte, RemoteVoice>> playerVoices in remoteVoices)
				{
					foreach (KeyValuePair<byte, RemoteVoice> voice in playerVoices.Value)
					{
						yield return new RemoteVoiceInfo(playerVoices.Key, voice.Key, voice.Value.Info);
					}
				}
			}
		}

		public byte GlobalAudioGroup
		{
			get
			{
				return globalAudioGroup;
			}
			set
			{
				loadBalancingPeer.DebugOut = DebugLevel.ALL;
				globalAudioGroup = value;
				if (base.State == ClientState.Joined)
				{
					if (globalAudioGroup != 0)
					{
						loadBalancingPeer.OpChangeGroups(new byte[0], new byte[1] { globalAudioGroup });
					}
					else
					{
						loadBalancingPeer.OpChangeGroups(new byte[0], null);
					}
				}
				foreach (LocalVoice localVoice in localVoices)
				{
					localVoice.AudioGroup = globalAudioGroup;
				}
			}
		}

		public new Action<EventData> OnEventAction { get; set; }

		public Client()
		{
			UseLossCompensation = true;
			base.OnEventAction = onEventActionVoiceClient;
		}

		public new void Service()
		{
			base.Service();
			foreach (LocalVoice localVoice in localVoices)
			{
				localVoice.service();
			}
		}

		public LocalVoice CreateLocalVoice(IAudioStream audioStream, VoiceInfo voiceInfo)
		{
			byte b = 0;
			if (voiceIdCnt == byte.MaxValue)
			{
				bool[] array = new bool[256];
				foreach (LocalVoice localVoice2 in localVoices)
				{
					array[localVoice2.id] = true;
				}
				for (byte b2 = 1; b2 != 0; b2++)
				{
					if (!array[b2])
					{
						b = b2;
						break;
					}
				}
			}
			else
			{
				voiceIdCnt++;
				b = voiceIdCnt;
			}
			if (b != 0)
			{
				LocalVoice localVoice = new LocalVoice(this, b, audioStream, voiceInfo.UserData, voiceInfo.SamplingRate, voiceInfo.Channels, voiceInfo.Bitrate, voiceInfo.EncoderDelay);
				localVoices.Add(localVoice);
				DebugReturn(DebugLevel.INFO, string.Concat("[PV] Local voice #", localVoice.id, " added: src_f=", audioStream.SamplingRate, " enc_f=", localVoice.InputSamplingRate, " ch=", localVoice.InputChannels, " d=", localVoice.EncoderDelay, " s=", localVoice.frameSize, " b=", localVoice.Bitrate, " ud=", voiceInfo.UserData));
				if (base.State == ClientState.Joined)
				{
					sendVoicesInfo(0, new List<LocalVoice> { localVoice });
				}
				localVoice.AudioGroup = globalAudioGroup;
				return localVoice;
			}
			return null;
		}

		public void RemoveLocalVoice(LocalVoice v)
		{
			localVoices.Remove(v);
			if (base.State == ClientState.Joined)
			{
				sendVoiceRemove(new List<LocalVoice> { v });
			}
			DebugReturn(DebugLevel.INFO, "[PV] Local voice #" + v.id + " removed");
		}

		public virtual bool ChangeAudioGroups(byte[] groupsToRemove, byte[] groupsToAdd)
		{
			return loadBalancingPeer.OpChangeGroups(groupsToRemove, groupsToAdd);
		}

		private void sendVoicesInfo(int playerId, List<LocalVoice> voicesToSend)
		{
			object[] array = new object[voicesToSend.Count];
			object[] customEventContent = new object[3]
			{
				(byte)0,
				EventSubcode.VoiceInfo,
				array
			};
			int num = 0;
			foreach (LocalVoice item in voicesToSend)
			{
				array[num] = new Hashtable
				{
					{
						(byte)1,
						item.id
					},
					{
						(byte)2,
						item.InputSamplingRate
					},
					{
						(byte)3,
						item.InputChannels
					},
					{
						(byte)4,
						item.EncoderDelay
					},
					{
						(byte)5,
						item.Bitrate
					},
					{
						(byte)10,
						item.userData
					},
					{
						(byte)11,
						item.evNumber
					}
				};
				num++;
				DebugReturn(DebugLevel.INFO, string.Concat("[PV] Voice #", item.id, " info sent: f=", item.InputSamplingRate, ", ch=", item.InputChannels, " d=", item.EncoderDelay, " s=", item.frameSize, " b=", item.Bitrate, " ev=", item.evNumber));
			}
			ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions raiseEventOptions = new ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions();
			if (playerId != 0)
			{
				raiseEventOptions.TargetActors = new int[1] { playerId };
			}
			else if (DebugEchoMode)
			{
				raiseEventOptions.Receivers = ExitGames.Client.Photon.LoadBalancing.ReceiverGroup.All;
			}
			OpRaiseEvent(201, customEventContent, sendReliable: true, raiseEventOptions);
		}

		private void sendVoiceRemove(List<LocalVoice> voicesToSend)
		{
			byte[] array = new byte[voicesToSend.Count];
			object[] customEventContent = new object[3]
			{
				(byte)0,
				EventSubcode.VoiceRemove,
				array
			};
			int num = 0;
			foreach (LocalVoice item in voicesToSend)
			{
				array[num] = item.id;
				num++;
				DebugReturn(DebugLevel.INFO, "[PV] Voice #" + item.id + " remove sent");
			}
			ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions raiseEventOptions = new ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions();
