			{
				raiseEventOptions.Receivers = ExitGames.Client.Photon.LoadBalancing.ReceiverGroup.All;
			}
			OpRaiseEvent(201, customEventContent, sendReliable: true, raiseEventOptions);
		}

		internal void sendFrame(byte voiceId, byte evNumber, byte[] frame, byte audioGroup)
		{
			object[] customEventContent = new object[3] { voiceId, evNumber, frame };
			ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions raiseEventOptions = new ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions();
			if (DebugEchoMode)
			{
				raiseEventOptions.Receivers = ExitGames.Client.Photon.LoadBalancing.ReceiverGroup.All;
			}
			raiseEventOptions.InterestGroup = audioGroup;
			OpRaiseEvent(201, customEventContent, sendReliable: false, raiseEventOptions);
			loadBalancingPeer.SendOutgoingCommands();
		}

		private void onEventActionVoiceClient(EventData ev)
		{
			switch (ev.Code)
			{
			case byte.MaxValue:
			{
				int num = (int)ev[254];
				if (num == base.LocalPlayer.ID)
				{
					clearRemoteVoices();
					sendVoicesInfo(0, localVoices);
					if (globalAudioGroup != 0)
					{
						loadBalancingPeer.OpChangeGroups(new byte[0], new byte[1] { globalAudioGroup });
					}
				}
				else
				{
					sendVoicesInfo(num, localVoices);
				}
				break;
			}
			case 254:
			{
				int num = (int)ev[254];
				if (num == base.LocalPlayer.ID)
				{
					clearRemoteVoices();
				}
				else
				{
					onPlayerLeave(num);
				}
				break;
			}
			case 201:
			{
				object[] array = (object[])ev[245];
				if ((byte)array[0] == 0)
				{
					switch ((byte)array[1])
					{
					case 1:
						onVoiceInfo(ev, array[2]);
						break;
					case 2:
						onVoiceRemove(ev, array[2]);
						break;
					case 10:
					{
						Dictionary<byte, RemoteVoice> value = null;
						if (!remoteVoices.TryGetValue(base.LocalPlayer.ID, out value))
						{
							break;
						}
						foreach (KeyValuePair<byte, RemoteVoice> item in value)
						{
							if (OnRemoteVoiceRemoveAction != null)
							{
								OnRemoteVoiceRemoveAction(base.LocalPlayer.ID, item.Key);
							}
						}
						remoteVoices.Remove(base.LocalPlayer.ID);
						break;
					}
					default:
						DebugReturn(DebugLevel.ERROR, "[PV] Unknown sevent subcode " + array[1]);
						break;
					}
				}
				else
				{
					onFrame(ev, array);
				}
				break;
			}
			}
			if (OnEventAction != null)
			{
				OnEventAction(ev);
			}
		}

		private void clearRemoteVoices()
		{
			if (OnRemoteVoiceRemoveAction != null)
			{
				foreach (KeyValuePair<int, Dictionary<byte, RemoteVoice>> remoteVoice in remoteVoices)
				{
					foreach (KeyValuePair<byte, RemoteVoice> item in remoteVoice.Value)
					{
						OnRemoteVoiceRemoveAction(remoteVoice.Key, item.Key);
					}
				}
			}
			remoteVoices.Clear();
			DebugReturn(DebugLevel.INFO, "[PV] Remote voices cleared");
		}

		private void onPlayerLeave(int playerId)
		{
			Dictionary<byte, RemoteVoice> value = null;
			if (remoteVoices.TryGetValue(playerId, out value))
			{
				remoteVoices.Remove(playerId);
				DebugReturn(DebugLevel.INFO, "[PV] Player " + playerId + " voices removed on leave");
				if (OnRemoteVoiceRemoveAction == null)
				{
					return;
				}
				{
					foreach (KeyValuePair<byte, RemoteVoice> item in value)
					{
						OnRemoteVoiceRemoveAction(playerId, item.Key);
					}
					return;
				}
			}
			DebugReturn(DebugLevel.WARNING, "[PV] Voices of player " + playerId + " not found when trying to remove on player leave");
		}

		private void onVoiceInfo(EventData ev, object payload)
		{
			int num = (int)ev[254];
			Dictionary<byte, RemoteVoice> value = null;
			if (!remoteVoices.TryGetValue(num, out value))
			{
				value = new Dictionary<byte, RemoteVoice>();
				remoteVoices[num] = value;
			}
			value = remoteVoices[num];
			object[] array = (object[])payload;
			foreach (object obj in array)
			{
				Hashtable hashtable = (Hashtable)obj;
				byte b = (byte)hashtable[(byte)1];
				if (!value.ContainsKey(b))
				{
					SamplingRate samplingRate = (SamplingRate)(int)hashtable[(byte)2];
					Channels channels = (Channels)(int)hashtable[(byte)3];
					int num2 = (int)hashtable[(byte)4];
					int num3 = (int)hashtable[(byte)5];
					object obj2 = hashtable[(byte)10];
					byte b2 = (byte)hashtable[(byte)11];
					DebugReturn(DebugLevel.INFO, string.Concat("[PV] Player ", num, " voice #", b, " info received: f=", samplingRate, ", ch=", channels, " d=", num2, " b=", num3, " ud=", obj2, " ev=", b2));
					VoiceInfo voiceInfo = new VoiceInfo((int)samplingRate, (int)channels, num2, num3, obj2);
					value[b] = new RemoteVoice(this, voiceInfo, samplingRate, channels, b2);
					if (OnRemoteVoiceInfoAction != null)
					{
						OnRemoteVoiceInfoAction(num, b, voiceInfo);
					}
				}
				else
				{
					DebugReturn(DebugLevel.WARNING, "[PV] Info duplicate for voice #" + b + " of player " + num);
				}
			}
		}

		private void onVoiceRemove(EventData ev, object payload)
		{
			int num = (int)ev[254];
			byte[] array = (byte[])payload;
			Dictionary<byte, RemoteVoice> value = null;
			if (remoteVoices.TryGetValue(num, out value))
			{
				byte[] array2 = array;
				foreach (byte b in array2)
				{
					if (value.Remove(b))
					{
						DebugReturn(DebugLevel.INFO, "[PV] Voice #" + b + " of player " + num + " removed");
						if (OnRemoteVoiceRemoveAction != null)
						{
							OnRemoteVoiceRemoveAction(num, b);
						}
					}
					else
					{
						DebugReturn(DebugLevel.WARNING, "[PV] Voice #" + b + " of player " + num + " not found when trying to remove");
					}
				}
			}
			else
			{
				DebugReturn(DebugLevel.WARNING, "[PV] Voice list of player " + num + " not found when trying to remove voice(s)");
			}
		}

		private void onFrame(EventData ev, object[] content)
		{
			int num = (int)ev[254];
			Dictionary<byte, RemoteVoice> value = null;
			byte b = (byte)content[0];
			byte b2 = (byte)content[1];
			byte[] frame = (byte[])content[2];
			if (DebugLostPercent > 0 && rnd.Next(100) < DebugLostPercent)
			{
				DebugReturn(DebugLevel.WARNING, "[PV] Debug Lost Sim: 1 packet dropped");
				return;
			}
			FramesReceived++;
			if (remoteVoices.TryGetValue(num, out value))
			{
				RemoteVoice value2 = null;
				if (value.TryGetValue(b, out value2))
				{
					if (b2 != value2.lastEvNumber)
					{
						int num2 = byteDiff(b2, value2.lastEvNumber);
						if (num2 != 0)
						{
							DebugReturn(DebugLevel.ALL, "[PV] evNumer: " + b2 + " playerVoice.lastEvNumber: " + value2.lastEvNumber + " missing: " + num2);
						}
						value2.lastEvNumber = b2;
						if (UseLossCompensation)
						{
							for (int i = 0; i < num2; i++)
							{
								receiveFrame(null, value2, num, b);
							}
						}
						FramesLost += num2;
					}
					receiveFrame(frame, value2, num, b);
				}
				else
				{
					DebugReturn(DebugLevel.WARNING, "[PV] Frame event for not inited voice #" + b + " of player " + num);
				}
			}
			else
			{
				DebugReturn(DebugLevel.WARNING, "[PV] Frame event for voice #" + b + " of not inited player " + num);
			}
		}

		private byte byteDiff(byte latest, byte last)
		{
			return (byte)(latest - (last + 1));
		}

		private void receiveFrame(byte[] frame, RemoteVoice remoteVoice, int playerId, byte voiceId)
		{
			float[] arg = remoteVoice.decompress(frame);
			if (OnAudioFrameAction != null)
			{
				OnAudioFrameAction(playerId, voiceId, arg);
			}
		}
	}
	public static class VoiceUtil
	{
		internal static void Resample(float[] src, float[] dst, int channels)
		{
			for (int i = 0; i < dst.Length; i += channels)
			{
				int num = i * src.Length / dst.Length;
				for (int j = 0; j < channels; j++)
				{
					dst[i + j] = src[num + j];
				}
			}
		}

		public static int FrameSizeToDelay(int frameSize, int samplingRate, int numChannels)
		{
			return SamplesToDelay(frameSize / numChannels, samplingRate);
		}

		public static int SamplesToDelay(int samples, int samplingRate)
		{
			return 2 * samples * 1000 / samplingRate;
		}

		public static int DelayToFrameSize(int _encoderDelay, int _inputSamplingRate, int numChannels)
		{
			return DelayToSamples(_encoderDelay, _inputSamplingRate) * numChannels;
		}

		public static int DelayToSamples(int _encoderDelay, int _inputSamplingRate)
		{
			return (int)((decimal)(_inputSamplingRate / 1000) * (decimal)_encoderDelay / 2m);
		}

		internal static string tostr<T>(T[] x, int lim = 10)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < ((x.Length >= lim) ? lim : x.Length); i++)
			{
				stringBuilder.Append("-");
				stringBuilder.Append(x[i]);
			}
			return stringBuilder.ToString();
		}

		internal static int bestEncoderSampleRate(int f)
		{
			int num = int.MaxValue;
			int result = 48000;
			foreach (object value in Enum.GetValues(typeof(SamplingRate)))
			{
				int num2 = Math.Abs((int)value - f);
				if (num2 < num)
				{
					num = num2;
					result = (int)value;
				}
			}
			return result;
		}
	}
	public class LevelMeter
	{
		private float ampSum;

		private float ampPeak;

		private int bufferSize;

		private float[] buffer;

		private int prevValuesPtr;

		private float accumAvgPeakAmpSum;

		private int accumAvgPeakAmpCount;

		public float CurrentAvgAmp => ampSum / (float)bufferSize;

		public float CurrentPeakAmp { get; private set; }

		public float AccumAvgPeakAmp => (accumAvgPeakAmpCount != 0) ? (accumAvgPeakAmpSum / (float)accumAvgPeakAmpCount) : 0f;

		internal LevelMeter(int samplingRate, int numChannels)
		{
			bufferSize = samplingRate * numChannels / 2;
			buffer = new float[bufferSize];
		}

		public void ResetAccumAvgPeakAmp()
		{
			accumAvgPeakAmpSum = 0f;
			accumAvgPeakAmpCount = 0;
		}

		internal void process(float[] buf)
		{
			foreach (float num in buf)
			{
				float num2 = num;
				if (num2 < 0f)
				{
					num2 = 0f - num2;
				}
				ampSum = ampSum + num2 - buffer[prevValuesPtr];
				buffer[prevValuesPtr] = num2;
				if (ampPeak < num2)
				{
					ampPeak = num2;
				}
				if (prevValuesPtr == 0)
				{
					CurrentPeakAmp = ampPeak;
					ampPeak = 0f;
					accumAvgPeakAmpSum += CurrentPeakAmp;
					accumAvgPeakAmpCount++;
				}
				prevValuesPtr = (prevValuesPtr + 1) % bufferSize;
			}
		}
	}
	public class VoiceDetector
	{
		private int activityDelay;

		private int autoSilenceCounter;

		private int valuesCountPerSec;

		private int activityDelayValuesCount;

		public bool On { get; set; }

		public float Threshold { get; set; }

		public bool Detected { get; private set; }

		public int ActivityDelayMs
		{
			get
			{
				return activityDelay;
			}
			set
			{
				activityDelay = value;
				activityDelayValuesCount = value * valuesCountPerSec / 1000;
			}
		}

		internal VoiceDetector(int samplingRate, int numChannels)
		{
			valuesCountPerSec = samplingRate * numChannels;
			Threshold = 0.01f;
			ActivityDelayMs = 500;
		}

		internal void process(float[] buffer)
		{
			if (On)
			{
				foreach (float num in buffer)
				{
					if (num > Threshold)
					{
						Detected = true;
						autoSilenceCounter = 0;
					}
					else
					{
						autoSilenceCounter++;
					}
				}
				if (autoSilenceCounter > activityDelayValuesCount)
				{
					Detected = false;
				}
			}
			else
			{
				Detected = false;
			}
		}
	}
}
public class PhotonVoiceNetwork : UnityEngine.MonoBehaviour
{
	private static PhotonVoiceNetwork _instance;

	private static GameObject _singleton;

	private static object instanceLock = new object();

	private static bool destroyed = false;

	internal UnityVoiceClient client;

	private static string microphoneDevice = null;

	internal static PhotonVoiceNetwork instance
	{
		get
		{
			lock (instanceLock)
			{
				if (destroyed)
				{
					return null;
				}
				if (_instance == null)
				{
					_singleton = new GameObject();
					_instance = _singleton.AddComponent<PhotonVoiceNetwork>();
					_singleton.name = "PhotonVoiceNetworkSingleton";
					UnityEngine.Object.DontDestroyOnLoad(_singleton);
				}
				return _instance;
			}
		}
	}

	public static Client Client => instance.client;

	public static ClientState ClientState => instance.client.State;

	public static string CurrentRoomName => (instance.client.CurrentRoom != null) ? instance.client.CurrentRoom.Name : string.Empty;

	public static string MicrophoneDevice
	{
		get
		{
			return microphoneDevice;
		}
		set
		{
			if (value != null && !Microphone.devices.Contains(value))
			{
				UnityEngine.Debug.LogError("PUNVoice: " + value + " is not a valid microphone device");
				return;
			}
			microphoneDevice = value;
			if (PhotonVoiceSettings.Instance.DebugInfo)
			{
				UnityEngine.Debug.Log("PUNVoice: Setting global microphone device to " + microphoneDevice);
			}
			PhotonVoiceRecorder[] array = UnityEngine.Object.FindObjectsOfType<PhotonVoiceRecorder>();
			foreach (PhotonVoiceRecorder photonVoiceRecorder in array)
			{
				if (photonVoiceRecorder.photonView.isMine && photonVoiceRecorder.MicrophoneDevice == null)
				{
					photonVoiceRecorder.MicrophoneDevice = null;
				}
			}
		}
	}

	private void OnDestroy()
	{
		if (!(this != _instance))
		{
			destroyed = true;
		}
	}

	private void Awake()
	{
		client = new UnityVoiceClient(this);
		if (Microphone.devices.Length >= 1)
		{
		}
	}

	public static bool Connect()
	{
		instance.client.AppId = PhotonNetwork.PhotonServerSettings.VoiceAppID;
		instance.client.AppVersion = "1.0";
		if (PhotonNetwork.PhotonServerSettings.HostType == ServerSettings.HostingOption.SelfHosted)
		{
			return instance.client.Connect(PhotonNetwork.networkingPeer.MasterServerAddress, null, null, null, null);
		}
		return instance.client.ConnectToRegionMaster(PhotonNetwork.networkingPeer.CloudRegion.ToString());
	}

	public static void Disconnect()
	{
		instance.client.Disconnect();
	}

	protected void OnEnable()
	{
		if (!(this != _instance))
		{
			Application.RequestUserAuthorization(UserAuthorization.Microphone);
		}
	}

	protected void OnApplicationQuit()
	{
		if (!(this != _instance))
		{
			client.Disconnect();
		}
	}

	protected void Update()
	{
		if (!(this != _instance))
		{
			client.DebugLostPercent = PhotonVoiceSettings.Instance.DebugLostPercent;
			client.Service();
		}
	}

	public static LocalVoice CreateLocalVoice(IAudioStream audioClip, VoiceInfo voiceInfo)
	{
		return instance.client.CreateLocalVoice(audioClip, voiceInfo);
	}

	public static void RemoveLocalVoice(LocalVoice voice)
	{
		if (!destroyed)
		{
			instance.client.RemoveLocalVoice(voice);
		}
	}

	private void OnJoinedRoom()
	{
		if (this != _instance)
		{
			return;
		}
		ClientState state = client.State;
		if (state == ClientState.Joined)
		{
			if (PhotonVoiceSettings.Instance.AutoConnect)
			{
				client.OpLeaveRoom();
			}
		}
		else if (PhotonVoiceSettings.Instance.AutoConnect)
		{
			client.Reconnect();
		}
	}

	private void OnLeftRoom()
	{
		if (!(this != _instance) && PhotonVoiceSettings.Instance.AutoDisconnect)
		{
			client.Disconnect();
		}
	}

	private void OnDisconnectedFromPhoton()
	{
		if (!(this != _instance) && PhotonVoiceSettings.Instance.AutoDisconnect)
		{
			client.Disconnect();
		}
	}

	internal static void LinkSpeakerToRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		instance.client.LinkSpeakerToRemoteVoice(speaker);
	}

	internal static void UnlinkSpeakerFromRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		if (!destroyed)
		{
			instance.client.UnlinkSpeakerFromRemoteVoice(speaker);
		}
	}
}
internal class UnityVoiceClient : Client
{
	private Dictionary<KeyValuePair<int, byte>, PhotonVoiceSpeaker> voiceSpeakers = new Dictionary<KeyValuePair<int, byte>, PhotonVoiceSpeaker>();

	private bool reconnect;

	internal UnityVoiceClient(PhotonVoiceNetwork network)
	{
		base.OnRemoteVoiceInfoAction = OnRemoteVoiceInfo;
		base.OnRemoteVoiceRemoveAction = OnRemoteVoiceRemove;
		base.OnAudioFrameAction = OnAudioFrame;
		base.OnStateChangeAction = OnStateChange;
		base.OnOpResponseAction = OnOpResponse;
		loadBalancingPeer.DebugOut = DebugLevel.INFO;
	}

	public void Reconnect()
	{
		if (base.State == ClientState.Disconnected)
		{
			PhotonVoiceNetwork.Connect();
			return;
		}
		reconnect = true;
		Disconnect();
	}

	public override void DebugReturn(DebugLevel level, string message)
	{
		message = "PUNVoice: " + message;
		switch (level)
		{
		case DebugLevel.ERROR:
			UnityEngine.Debug.LogError(message);
			return;
		case DebugLevel.WARNING:
			UnityEngine.Debug.LogWarning(message);
			return;
		case DebugLevel.INFO:
			if (PhotonNetwork.logLevel >= PhotonLogLevel.Informational)
			{
				UnityEngine.Debug.Log(message);
				return;
			}
			break;
		}
		if (level == DebugLevel.ALL && PhotonNetwork.logLevel == PhotonLogLevel.Full)
		{
			UnityEngine.Debug.Log(message);
		}
	}

	public void OnOpResponse(OperationResponse resp)
	{
		if (resp.ReturnCode != 0)
		{
			return;
		}
		byte operationCode = resp.OperationCode;
		if (operationCode == 226)
		{
			PhotonVoiceRecorder[] array = UnityEngine.Object.FindObjectsOfType<PhotonVoiceRecorder>();
			PhotonVoiceRecorder[] array2 = array;
			foreach (PhotonVoiceRecorder photonVoiceRecorder in array2)
			{
				photonVoiceRecorder.SendMessage("OnJoinedVoiceRoom");
			}
		}
	}

	private void linkVoice(int playerId, byte voiceId, VoiceInfo voiceInfo, PhotonVoiceSpeaker speaker)
	{
		speaker.OnVoiceLinked(voiceInfo.SamplingRate, voiceInfo.Channels, voiceInfo.EncoderDelay, PhotonVoiceSettings.Instance.PlayDelayMs);
		KeyValuePair<int, byte> key = new KeyValuePair<int, byte>(playerId, voiceId);
		if (voiceSpeakers.TryGetValue(key, out var value))
		{
			if (value == speaker)
			{
				return;
			}
			if (PhotonVoiceSettings.Instance.DebugInfo)
			{
				UnityEngine.Debug.Log("PUNVoice: Player " + playerId + " voice #" + voiceId + " speaker replaced");
			}
		}
		else if (PhotonVoiceSettings.Instance.DebugInfo)
		{
			UnityEngine.Debug.Log("PUNVoice: Player " + playerId + " voice #" + voiceId + " speaker created");
		}
		voiceSpeakers[key] = speaker;
	}

	public void OnRemoteVoiceInfo(int playerId, byte voiceId, VoiceInfo voiceInfo)
	{
		KeyValuePair<int, byte> key = new KeyValuePair<int, byte>(playerId, voiceId);
		if (voiceSpeakers.ContainsKey(key))
		{
			UnityEngine.Debug.LogWarning("PUNVoice: Info duplicate for voice #" + voiceId + " of player " + playerId);
		}
		PhotonVoiceSpeaker photonVoiceSpeaker = null;
		PhotonVoiceSpeaker[] array = UnityEngine.Object.FindObjectsOfType<PhotonVoiceSpeaker>();
		PhotonVoiceSpeaker[] array2 = array;
		foreach (PhotonVoiceSpeaker photonVoiceSpeaker2 in array2)
		{
			if (photonVoiceSpeaker2.photonView.viewID == (int)voiceInfo.UserData)
			{
				photonVoiceSpeaker = photonVoiceSpeaker2;
				break;
			}
		}
		if (!(photonVoiceSpeaker == null))
		{
			linkVoice(playerId, voiceId, voiceInfo, photonVoiceSpeaker);
		}
	}

	public void LinkSpeakerToRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		foreach (RemoteVoiceInfo remoteVoiceInfo in base.RemoteVoiceInfos)
		{
			if (speaker.photonView.viewID == (int)remoteVoiceInfo.Info.UserData)
			{
				linkVoice(remoteVoiceInfo.PlayerId, remoteVoiceInfo.VoiceId, remoteVoiceInfo.Info, speaker);
			}
		}
	}

	public void OnRemoteVoiceRemove(int playerId, byte voiceId)
	{
		KeyValuePair<int, byte> key = new KeyValuePair<int, byte>(playerId, voiceId);
		if (!unlinkSpeaker(key))
		{
			UnityEngine.Debug.LogWarning("PUNVoice: Voice #" + voiceId + " of player " + playerId + " not found.");
		}
		else if (PhotonVoiceSettings.Instance.DebugInfo)
		{
			UnityEngine.Debug.Log("PUNVoice: Player " + playerId + " voice #" + voiceId + " speaker unlinked");
		}
	}

	private bool unlinkSpeaker(KeyValuePair<int, byte> key)
	{
		if (voiceSpeakers.TryGetValue(key, out var value))
		{
			value.OnVoiceUnlinked();
		}
		return voiceSpeakers.Remove(key);
	}

	public void UnlinkSpeakerFromRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		List<KeyValuePair<int, byte>> list = new List<KeyValuePair<int, byte>>();
		foreach (KeyValuePair<KeyValuePair<int, byte>, PhotonVoiceSpeaker> voiceSpeaker in voiceSpeakers)
		{
			if (voiceSpeaker.Value == speaker)
			{
				list.Add(voiceSpeaker.Key);
				if (PhotonVoiceSettings.Instance.DebugInfo)
				{
					UnityEngine.Debug.Log("PUNVoice: Player " + voiceSpeaker.Key.Key + " voice #" + voiceSpeaker.Key.Value + " speaker unlinked");
				}
			}
		}
		foreach (KeyValuePair<int, byte> item in list)
		{
			unlinkSpeaker(item);
		}
	}

	public void OnAudioFrame(int playerId, byte voiceId, float[] frame)
	{
		PhotonVoiceSpeaker value = null;
		if (voiceSpeakers.TryGetValue(new KeyValuePair<int, byte>(playerId, voiceId), out value))
		{
			value.OnAudioFrame(frame);
			return;
		}
		UnityEngine.Debug.LogWarning("PUNVoice: Audio Frame event for not existing speaker for voice #" + voiceId + " of player " + playerId);
	}

	public void OnStateChange(ClientState state)
	{
		if (PhotonNetwork.logLevel >= PhotonLogLevel.Informational)
		{
			UnityEngine.Debug.Log("PUNVoice: Voice Client state: " + state);
		}
		switch (state)
		{
		case ClientState.JoinedLobby:
			if (PhotonNetwork.inRoom)
			{
				OpJoinOrCreateRoom(PhotonNetwork.room.name + "_voice_", new ExitGames.Client.Photon.LoadBalancing.RoomOptions
				{
					IsVisible = false
				}, null);
			}
			else
			{
				UnityEngine.Debug.LogWarning("PUNVoice: PUN client is not in room yet. Disconnecting voice client.");
				Disconnect();
			}
			break;
		case ClientState.Disconnected:
			if (reconnect)
			{
				PhotonVoiceNetwork.Connect();
			}
			reconnect = false;
			break;
		}
	}
}
internal class AudioClipWrapper : IAudioStream
{
	private AudioClip audioClip;

	private int readPos;

	private float startTime;

	private bool playing = true;

	public int SamplingRate => audioClip.frequency;

	public bool Loop { get; set; }

	public AudioClipWrapper(AudioClip audioClip)
	{
		this.audioClip = audioClip;
		startTime = Time.time;
	}

	public bool GetData(float[] buffer)
	{
		if (!playing)
		{
			return false;
		}
		int num = (int)((Time.time - startTime) * (float)audioClip.frequency);
		int num2 = buffer.Length / audioClip.channels;
		if (num > readPos + num2)
		{
			audioClip.GetData(buffer, readPos);
			readPos += num2;
			if (readPos >= audioClip.samples)
			{
				if (Loop)
				{
					readPos = 0;
					startTime = Time.time;
				}
				else
				{
					playing = false;
				}
			}
			return true;
		}
		return false;
	}
}
internal class MicWrapper : IAudioStream
{
	private AudioClip mic;

	private string device;

	private int micPrevPos;

	private int micLoopCnt;

	private int readAbsPos;

	public int SamplingRate => mic.frequency;

	public int Channels => mic.channels;

	public MicWrapper(string device, int suggestedFrequency)
	{
		this.device = device;
		Microphone.GetDeviceCaps(device, out var minFreq, out var maxFreq);
		int frequency = suggestedFrequency;
		if (suggestedFrequency < minFreq || (maxFreq != 0 && suggestedFrequency > maxFreq))
		{
			UnityEngine.Debug.LogWarning("PUNVoice: MicWrapper does not support suggested frequency " + suggestedFrequency + " (min: " + minFreq + ",max: " + maxFreq + "). Setting to " + maxFreq);
			frequency = maxFreq;
		}
		mic = Microphone.Start(device, loop: true, 1, frequency);
	}

	public bool GetData(float[] buffer)
	{
		int position = Microphone.GetPosition(device);
		if (position < micPrevPos)
		{
			micLoopCnt++;
		}
		micPrevPos = position;
		int num = micLoopCnt * mic.samples + position;
		int num2 = buffer.Length / mic.channels;
		int num3 = readAbsPos + num2;
		if (num3 < num)
		{
			mic.GetData(buffer, readAbsPos % mic.samples);
			readAbsPos = num3;
			return true;
		}
		return false;
	}
}
[RequireComponent(typeof(PhotonVoiceSpeaker))]
public class PhotonVoiceRecorder : Photon.MonoBehaviour
{
	private LocalVoice voice;

	private string microphoneDevice;

	public AudioClip AudioClip;

	public bool LoopAudioClip = true;

	private string log0;

	private string log1;

	public VoiceDetector VoiceDetector => (!base.photonView.isMine || voice == null) ? null : voice.VoiceDetector;

	public string MicrophoneDevice
	{
		get
		{
			return microphoneDevice;
		}
		set
		{
			if (value != null && !Microphone.devices.Contains(value))
			{
				UnityEngine.Debug.LogError("PUNVoice: " + value + " is not a valid microphone device");
				return;
			}
			microphoneDevice = value;
			if (voice != null && AudioClip == null)
			{
				PhotonVoiceSettings instance = PhotonVoiceSettings.Instance;
				Application.RequestUserAuthorization(UserAuthorization.Microphone);
				string text = ((MicrophoneDevice == null) ? PhotonVoiceNetwork.MicrophoneDevice : MicrophoneDevice);
				if (PhotonVoiceSettings.Instance.DebugInfo)
				{
					UnityEngine.Debug.Log("PUNVoice: Setting recorder's microphone device to " + text);
				}
				MicWrapper micWrapper = new MicWrapper(text, (int)instance.SamplingRate);
				bool debugEchoMode = PhotonVoiceNetwork.Client.DebugEchoMode;
				PhotonVoiceNetwork.Client.DebugEchoMode = false;
				VoiceInfo voiceInfo = new VoiceInfo((int)instance.SamplingRate, micWrapper.Channels, (int)instance.Delay, instance.Bitrate, base.photonView.viewID);
				PhotonVoiceNetwork.RemoveLocalVoice(voice);
				LocalVoice localVoice = voice;
				voice = PhotonVoiceNetwork.CreateLocalVoice(micWrapper, voiceInfo);
				voice.AudioGroup = localVoice.AudioGroup;
				voice.Transmit = localVoice.Transmit;
				voice.VoiceDetector.On = localVoice.VoiceDetector.On;
				voice.VoiceDetector.Threshold = localVoice.VoiceDetector.Threshold;
				PhotonVoiceNetwork.Client.DebugEchoMode = debugEchoMode;
			}
		}
	}

	public byte AudioGroup
	{
		get
		{
			return (byte)((voice != null) ? voice.AudioGroup : 0);
		}
		set
		{
			if (voice != null)
			{
				voice.AudioGroup = value;
			}
		}
	}

	public bool IsTransmitting => voice != null && voice.IsTransmitting;

	public LevelMeter LevelMeter => (voice == null) ? null : voice.LevelMeter;

	public bool Transmit
	{
		get
		{
			return voice != null && voice.Transmit;
		}
		set
		{
			if (voice != null)
			{
				voice.Transmit = value;
			}
		}
	}

	public bool Detect
	{
		get
		{
			return voice != null && voice.VoiceDetector.On;
		}
		set
		{
			if (voice != null)
			{
				voice.VoiceDetector.On = value;
			}
		}
	}

	public bool VoiceDetectorCalibrating => voice.VoiceDetectorCalibrating;

	private void Start()
	{
		if (base.photonView.isMine)
		{
			PhotonVoiceSettings instance = PhotonVoiceSettings.Instance;
			if (MicrophoneDevice == null && PhotonVoiceNetwork.MicrophoneDevice == null)
			{
				UnityEngine.Debug.LogWarning("PUNVoice : PhotonVoiceRecorder is disabled since we do not have a microphone.");
				base.enabled = false;
				return;
			}
			Application.RequestUserAuthorization(UserAuthorization.Microphone);
			int num = 0;
			IAudioStream audioStream;
			if (AudioClip == null)
			{
				string text = ((MicrophoneDevice == null) ? PhotonVoiceNetwork.MicrophoneDevice : MicrophoneDevice);
				if (PhotonVoiceSettings.Instance.DebugInfo)
				{
					UnityEngine.Debug.Log("PUNVoice: Setting recorder's microphone device to " + text);
				}
				MicWrapper micWrapper = new MicWrapper(text, (int)instance.SamplingRate);
				num = micWrapper.Channels;
				audioStream = micWrapper;
			}
			else
			{
				audioStream = new AudioClipWrapper(AudioClip);
				num = AudioClip.channels;
				if (LoopAudioClip)
				{
					((AudioClipWrapper)audioStream).Loop = true;
				}
			}
			VoiceInfo voiceInfo = new VoiceInfo((int)instance.SamplingRate, num, (int)instance.Delay, instance.Bitrate, base.photonView.viewID);
			voice = PhotonVoiceNetwork.CreateLocalVoice(audioStream, voiceInfo);
			VoiceDetector.On = PhotonVoiceSettings.Instance.VoiceDetection;
			VoiceDetector.Threshold = PhotonVoiceSettings.Instance.VoiceDetectionThreshold;
		}
		else
		{
			base.enabled = false;
		}
	}

	private void OnDestroy()
	{
		if (voice != null)
		{
			PhotonVoiceNetwork.RemoveLocalVoice(voice);
		}
	}

	private void OnEnable()
	{
		Application.RequestUserAuthorization(UserAuthorization.Microphone);
	}

	private void OnDisable()
	{
	}

	private void OnJoinedVoiceRoom()
	{
		if (base.photonView.isMine && voice != null)
		{
			voice.Transmit = PhotonVoiceSettings.Instance.AutoTransmit && SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.AlwaysOn;
		}
	}

	public void VoiceDetectorCalibrate(int durationMs)
	{
		if (base.photonView.isMine)
		{
			voice.VoiceDetectorCalibrate(durationMs);
		}
	}

	private string tostr<T>(T[] x, int lim = 10)
	{
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < ((x.Length >= lim) ? lim : x.Length); i++)
		{
			stringBuilder.Append("-");
			stringBuilder.Append(x[i]);
		}
		return stringBuilder.ToString();
	}

	public string ToStringFull()
	{
		int minFreq = 0;
		int maxFreq = 0;
		Microphone.GetDeviceCaps(MicrophoneDevice, out minFreq, out maxFreq);
		return $"Mic '{MicrophoneDevice}': {minFreq}..{maxFreq} Hz";
	}
}
public class PhotonVoiceSettings : UnityEngine.MonoBehaviour
{
	public bool AutoConnect = true;

	public bool AutoDisconnect;

	public bool AutoTransmit = true;

	public SamplingRate SamplingRate = SamplingRate.Sampling24000;

	public Delay Delay = Delay.Delay20ms;

	public int Bitrate = 30000;

	public bool VoiceDetection;

	public float VoiceDetectionThreshold = 0.01f;

	public int PlayDelayMs = 200;

	public int DebugLostPercent;

	public bool DebugInfo;

	private static PhotonVoiceSettings instance;

	private static object instanceLock = new object();

	public static PhotonVoiceSettings Instance
	{
		get
		{
			if (instance == null)
			{
				instance = PhotonVoiceNetwork.instance.gameObject.AddComponent<PhotonVoiceSettings>();
			}
			return instance;
		}
	}

	private void Awake()
	{
		lock (instanceLock)
		{
			if (instance == null)
			{
				instance = this;
			}
			else
			{
				UnityEngine.Debug.LogError("PUNVoice: Attempt to create multiple instances of PhotonVoiceSettings");
			}
		}
	}
}
[RequireComponent(typeof(AudioSource))]
public class PhotonVoiceSpeaker : Photon.MonoBehaviour
{
	private const int maxPlayLagMs = 100;

	private int maxPlayLagSamples;

	private int playDelaySamples;

	private int frameSize;

	private int frameSamples;

	private int streamSamplePos;

	private int sourceTimeSamplesPrev;

	private int playLoopCount;

	private float lastRecvTime;

	private int streamSamplePosAvg;

	private AudioSource source;

	private int playSamplePos
	{
		get
		{
			return (source.clip != null) ? (playLoopCount * source.clip.samples + source.timeSamples) : 0;
		}
		set
		{
			if (source.clip != null)
			{
				source.timeSamples = value % source.clip.samples;
				playLoopCount = value / source.clip.samples;
				sourceTimeSamplesPrev = source.timeSamples;
			}
		}
	}

	public float LastRecvTime => lastRecvTime;

	public bool IsPlaying => source.isPlaying;

	public int CurrentBufferLag { get; private set; }

	public bool IsVoiceLinked => source != null && source.clip != null;

	public bool IsVoiceDetected { get; private set; }

	private void Awake()
	{
		source = GetComponent<AudioSource>();
		PhotonVoiceNetwork.LinkSpeakerToRemoteVoice(this);
	}

	internal void OnVoiceLinked(int frequency, int channels, int encoderDelay, int playDelayMs)
	{
		frameSize = VoiceUtil.DelayToFrameSize(encoderDelay, frequency, channels);
		frameSamples = VoiceUtil.DelayToSamples(encoderDelay, frequency);
		maxPlayLagSamples = 100 * frequency / 1000 + frameSamples;
		playDelaySamples = playDelayMs * frequency / 1000 + frameSamples;
		CurrentBufferLag = playDelaySamples;
		streamSamplePosAvg = playDelaySamples;
		source.loop = true;
		source.clip = AudioClip.Create("PhotonVoice", frequency, channels, frequency, stream: false);
		streamSamplePos = 0;
		playSamplePos = 0;
		source.Play();
		source.Pause();
	}

	public void Pause()
	{
		if ((bool)source)
		{
			source.Pause();
		}
	}

	internal void OnVoiceUnlinked()
	{
		if (source.clip != null)
		{
			source.Stop();
			source.clip = null;
		}
	}

	private void Update()
	{
		if (!(source != null) || !(source.clip != null))
		{
			return;
		}
		if (source.isPlaying)
		{
			if (source.timeSamples < sourceTimeSamplesPrev)
			{
				playLoopCount++;
			}
			sourceTimeSamplesPrev = source.timeSamples;
		}
		int num = playSamplePos;
		CurrentBufferLag = (CurrentBufferLag * 39 + (streamSamplePos - num)) / 40;
		streamSamplePosAvg = num + CurrentBufferLag;
		if (streamSamplePosAvg > streamSamplePos)
		{
			streamSamplePosAvg = streamSamplePos;
		}
		if (num < streamSamplePos - playDelaySamples && !source.isPlaying)
		{
			source.UnPause();
		}
		if (num > streamSamplePos - frameSamples && source.isPlaying)
		{
			if (PhotonVoiceSettings.Instance.DebugInfo)
			{
				UnityEngine.Debug.LogWarning("PUNVoice: PhotonVoiceSpeaker: player overrun: " + num + "/" + streamSamplePos + "(" + streamSamplePosAvg + ") = " + (streamSamplePos - num));
			}
			source.Pause();
			num = (playSamplePos = streamSamplePos - playDelaySamples);
			CurrentBufferLag = playDelaySamples;
		}
		if (!source.isPlaying)
		{
			return;
		}
		int num3 = streamSamplePos - playDelaySamples - maxPlayLagSamples;
		if (num < num3)
		{
			if (PhotonVoiceSettings.Instance.DebugInfo)
			{
				UnityEngine.Debug.LogWarning("PUNVoice: PhotonVoiceSpeaker: player underrun: " + num + "/" + streamSamplePos + "(" + streamSamplePosAvg + ") = " + (streamSamplePos - num));
			}
			num = streamSamplePos - playDelaySamples;
			playSamplePos = num;
			CurrentBufferLag = playDelaySamples;
		}
	}

	private void OnDestroy()
	{
		PhotonVoiceNetwork.UnlinkSpeakerFromRemoteVoice(this);
		if (source != null)
		{
			source.Stop();
		}
	}

	private void OnApplicationQuit()
	{
		if (source != null)
		{
			source.Stop();
		}
	}

	internal void OnAudioFrame(float[] frame)
	{
		if (frame.Length != frameSize)
		{
			UnityEngine.Debug.LogError("PUNVoice: Audio frames are not of  size: " + frame.Length + " != " + frameSize);
			UnityEngine.Debug.LogError("PUNVoice: " + frame[0] + " " + frame[1] + " " + frame[2] + " " + frame[3] + " " + frame[4] + " " + frame[5] + " " + frame[6]);
			return;
		}
		lastRecvTime = Time.time;
		source.clip.SetData(frame, streamSamplePos % source.clip.samples);
		streamSamplePos += frame.Length / source.clip.channels;
		bool isVoiceDetected = false;
		foreach (float num in frame)
		{
			if (num > PhotonVoiceSettings.Instance.VoiceDetectionThreshold)
			{
				isVoiceDetected = true;
				break;
			}
		}
		IsVoiceDetected = isVoiceDetected;
	}
}
