		{
			ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
			hashtable.Add((byte)247, new string[0]);
			ExitGames.Client.Photon.Hashtable gameProperties = hashtable;
			hashtable = new ExitGames.Client.Photon.Hashtable();
			hashtable.Add((byte)247, expectedUsers);
			ExitGames.Client.Photon.Hashtable expectedProperties = hashtable;
			PhotonNetwork.networkingPeer.OpSetPropertiesOfRoom(gameProperties, expectedProperties);
		}
	}

