public class ConnectAndJoinRandom : Photon.MonoBehaviour
{
	public bool AutoConnect = true;

	public byte Version = 1;

	private bool ConnectInUpdate = true;

	public virtual void Start()
	{
		PhotonNetwork.autoJoinLobby = false;
	}

	public virtual void Update()
	{
		if (ConnectInUpdate && AutoConnect && !PhotonNetwork.connected)
		{
			UnityEngine.Debug.Log("Update() was called by Unity. Scene is loaded. Let's connect to the Photon Master Server. Calling: PhotonNetwork.ConnectUsingSettings();");
			ConnectInUpdate = false;
			PhotonNetwork.ConnectUsingSettings(Version + "." + SceneManagerHelper.ActiveSceneBuildIndex);
		}
	}

	public virtual void OnConnectedToMaster()
	{
		UnityEngine.Debug.Log("OnConnectedToMaster() was called by PUN. Now this client is connected and could join a room. Calling: PhotonNetwork.JoinRandomRoom();");
		PhotonNetwork.JoinRandomRoom();
	}

	public virtual void OnJoinedLobby()
	{
		UnityEngine.Debug.Log("OnJoinedLobby(). This client is connected and does get a room-list, which gets stored as PhotonNetwork.GetRoomList(). This script now calls: PhotonNetwork.JoinRandomRoom();");
		PhotonNetwork.JoinRandomRoom();
	}

	public virtual void OnPhotonRandomJoinFailed()
	{
		UnityEngine.Debug.Log("OnPhotonRandomJoinFailed() was called by PUN. No random room available, so we create one. Calling: PhotonNetwork.CreateRoom(null, new RoomOptions() {maxPlayers = 4}, null);");
		PhotonNetwork.CreateRoom(null, new RoomOptions
		{
			maxPlayers = 4
		}, null);
	}

	public virtual void OnFailedToConnectToPhoton(DisconnectCause cause)
	{
		UnityEngine.Debug.LogError("Cause: " + cause);
	}

	public void OnJoinedRoom()
	{
		UnityEngine.Debug.Log("OnJoinedRoom() called by PUN. Now this client is in a room. From here on, your game would be running. For reference, all callbacks are listed in enum: PhotonNetworkingMessage");
	}
}
[RequireComponent(typeof(PhotonView))]
public class HighlightOwnedGameObj : Photon.MonoBehaviour
{
	public GameObject PointerPrefab;

	public float Offset = 0.5f;

	private Transform markerTransform;

	private void Update()
	{
		if (base.photonView.isMine)
		{
			if (markerTransform == null)
			{
				GameObject gameObject = UnityEngine.Object.Instantiate(PointerPrefab);
				gameObject.transform.parent = base.gameObject.transform;
				markerTransform = gameObject.transform;
			}
			Vector3 position = base.gameObject.transform.position;
			markerTransform.position = new Vector3(position.x, position.y + Offset, position.z);
			markerTransform.rotation = Quaternion.identity;
		}
		else if (markerTransform != null)
		{
			UnityEngine.Object.Destroy(markerTransform.gameObject);
			markerTransform = null;
		}
	}
}
[RequireComponent(typeof(PhotonView))]
public class InRoomChat : Photon.MonoBehaviour
{
	public Rect GuiRect = new Rect(0f, 0f, 250f, 300f);

	public bool IsVisible = true;

	public bool AlignBottom;

	public List<string> messages = new List<string>();

	private string inputLine = string.Empty;

	private Vector2 scrollPos = Vector2.zero;

	public static readonly string ChatRPC = "Chat";

	public void Start()
	{
		if (AlignBottom)
		{
			GuiRect.y = (float)Screen.height - GuiRect.height;
		}
	}

	public void OnGUI()
	{
		if (!IsVisible || PhotonNetwork.connectionStateDetailed != PeerState.Joined)
		{
			return;
		}
		if (Event.current.type == EventType.KeyDown && (Event.current.keyCode == KeyCode.KeypadEnter || Event.current.keyCode == KeyCode.Return))
		{
			if (!string.IsNullOrEmpty(inputLine))
			{
				base.photonView.RPC("Chat", PhotonTargets.All, inputLine);
				inputLine = string.Empty;
				GUI.FocusControl(string.Empty);
				return;
			}
			GUI.FocusControl("ChatInput");
		}
		GUI.SetNextControlName(string.Empty);
		GUILayout.BeginArea(GuiRect);
		scrollPos = GUILayout.BeginScrollView(scrollPos);
		GUILayout.FlexibleSpace();
		for (int num = messages.Count - 1; num >= 0; num--)
		{
			GUILayout.Label(messages[num]);
		}
		GUILayout.EndScrollView();
		GUILayout.BeginHorizontal();
		GUI.SetNextControlName("ChatInput");
		inputLine = GUILayout.TextField(inputLine);
		if (GUILayout.Button("Send", GUILayout.ExpandWidth(expand: false)))
		{
			base.photonView.RPC("Chat", PhotonTargets.All, inputLine);
			inputLine = string.Empty;
			GUI.FocusControl(string.Empty);
		}
		GUILayout.EndHorizontal();
		GUILayout.EndArea();
	}

	[PunRPC]
	public void Chat(string newLine, PhotonMessageInfo mi)
	{
		string text = "anonymous";
		if (mi != null && mi.sender != null)
		{
			text = (string.IsNullOrEmpty(mi.sender.name) ? ("player " + mi.sender.ID) : mi.sender.name);
		}
		messages.Add(text + ": " + newLine);
	}

	public void AddLine(string newLine)
	{
		messages.Add(newLine);
	}
}
public class InRoomRoundTimer : UnityEngine.MonoBehaviour
{
	private const string StartTimeKey = "st";

	public int SecondsPerTurn = 5;

	public double StartTime;

	public Rect TextPos = new Rect(0f, 80f, 150f, 300f);

	private bool startRoundWhenTimeIsSynced;

	private void StartRoundNow()
	{
		if (PhotonNetwork.time < 9.999999747378752E-05)
		{
			startRoundWhenTimeIsSynced = true;
			return;
		}
		startRoundWhenTimeIsSynced = false;
		ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
		hashtable["st"] = PhotonNetwork.time;
		PhotonNetwork.room.SetCustomProperties(hashtable);
	}

	public void OnJoinedRoom()
	{
		if (PhotonNetwork.isMasterClient)
		{
			StartRoundNow();
		}
		else
		{
			UnityEngine.Debug.Log("StartTime already set: " + PhotonNetwork.room.customProperties.ContainsKey("st"));
		}
	}

	public void OnPhotonCustomRoomPropertiesChanged(ExitGames.Client.Photon.Hashtable propertiesThatChanged)
	{
		if (propertiesThatChanged.ContainsKey("st"))
		{
			StartTime = (double)propertiesThatChanged["st"];
		}
	}

	public void OnMasterClientSwitched(PhotonPlayer newMasterClient)
	{
		if (!PhotonNetwork.room.customProperties.ContainsKey("st"))
		{
			UnityEngine.Debug.Log("The new master starts a new round, cause we didn't start yet.");
			StartRoundNow();
		}
	}

	private void Update()
	{
		if (startRoundWhenTimeIsSynced)
		{
			StartRoundNow();
		}
	}

	public void OnGUI()
	{
		double num = PhotonNetwork.time - StartTime;
		double num2 = (double)SecondsPerTurn - num % (double)SecondsPerTurn;
		int num3 = (int)(num / (double)SecondsPerTurn);
		GUILayout.BeginArea(TextPos);
		GUILayout.Label($"elapsed: {num:0.000}");
		GUILayout.Label($"remaining: {num2:0.000}");
		GUILayout.Label($"turn: {num3:0}");
		if (GUILayout.Button("new round"))
		{
			StartRoundNow();
		}
		GUILayout.EndArea();
	}
}
public class InRoomTime : UnityEngine.MonoBehaviour
{
	private const string StartTimeKey = "#rt";

	private int roomStartTimestamp;

	public double RoomTime
	{
		get
		{
			uint roomTimestamp = (uint)RoomTimestamp;
			double num = roomTimestamp;
			return num / 1000.0;
		}
	}

	public int RoomTimestamp => PhotonNetwork.inRoom ? (PhotonNetwork.ServerTimestamp - roomStartTimestamp) : 0;

	public bool IsRoomTimeSet => PhotonNetwork.inRoom && PhotonNetwork.room.customProperties.ContainsKey("#rt");

	internal IEnumerator SetRoomStartTimestamp()
	{
		if (!IsRoomTimeSet && PhotonNetwork.isMasterClient)
		{
			if (PhotonNetwork.ServerTimestamp == 0)
			{
				yield return 0;
			}
			ExitGames.Client.Photon.Hashtable startTimeProp = new ExitGames.Client.Photon.Hashtable { ["#rt"] = PhotonNetwork.ServerTimestamp };
			PhotonNetwork.room.SetCustomProperties(startTimeProp);
		}
	}

	public void OnJoinedRoom()
	{
		StartCoroutine("SetRoomStartTimestamp");
	}

	public void OnMasterClientSwitched(PhotonPlayer newMasterClient)
	{
		StartCoroutine("SetRoomStartTimestamp");
	}

	public void OnPhotonCustomRoomPropertiesChanged(ExitGames.Client.Photon.Hashtable propertiesThatChanged)
	{
		if (propertiesThatChanged.ContainsKey("#rt"))
		{
			roomStartTimestamp = (int)propertiesThatChanged["#rt"];
		}
	}
}
public class InputToEvent : UnityEngine.MonoBehaviour
{
	private GameObject lastGo;

	public static Vector3 inputHitPos;

	public bool DetectPointedAtGameObject;

	private Vector2 pressedPosition = Vector2.zero;

	private Vector2 currentPos = Vector2.zero;

	public bool Dragging;

	private Camera m_Camera;

	public static GameObject goPointedAt { get; private set; }

	public Vector2 DragVector => (!Dragging) ? Vector2.zero : (currentPos - pressedPosition);

	private void Start()
	{
		m_Camera = GetComponent<Camera>();
	}

	private void Update()
	{
		if (DetectPointedAtGameObject)
		{
			goPointedAt = RaycastObject(Input.mousePosition);
		}
		if (Input.touchCount > 0)
		{
			Touch touch = Input.GetTouch(0);
			currentPos = touch.position;
			if (touch.phase == TouchPhase.Began)
			{
				Press(touch.position);
			}
			else if (touch.phase == TouchPhase.Ended)
			{
				Release(touch.position);
			}
			return;
		}
		currentPos = Input.mousePosition;
		if (Input.GetMouseButtonDown(0))
		{
			Press(Input.mousePosition);
		}
		if (Input.GetMouseButtonUp(0))
		{
			Release(Input.mousePosition);
		}
		if (Input.GetMouseButtonDown(1))
		{
			pressedPosition = Input.mousePosition;
			lastGo = RaycastObject(pressedPosition);
			if (lastGo != null)
			{
				lastGo.SendMessage("OnPressRight", SendMessageOptions.DontRequireReceiver);
			}
		}
	}

	private void Press(Vector2 screenPos)
	{
		pressedPosition = screenPos;
		Dragging = true;
		lastGo = RaycastObject(screenPos);
		if (lastGo != null)
		{
			lastGo.SendMessage("OnPress", SendMessageOptions.DontRequireReceiver);
		}
	}

	private void Release(Vector2 screenPos)
	{
		if (lastGo != null)
		{
			GameObject gameObject = RaycastObject(screenPos);
			if (gameObject == lastGo)
			{
				lastGo.SendMessage("OnClick", SendMessageOptions.DontRequireReceiver);
			}
			lastGo.SendMessage("OnRelease", SendMessageOptions.DontRequireReceiver);
			lastGo = null;
		}
		pressedPosition = Vector2.zero;
		Dragging = false;
	}

	private GameObject RaycastObject(Vector2 screenPos)
	{
		if (Physics.Raycast(m_Camera.ScreenPointToRay(screenPos), out var hitInfo, 200f))
		{
			inputHitPos = hitInfo.point;
			return hitInfo.collider.gameObject;
		}
		return null;
	}
}
