[DisallowMultipleComponent]
public class ActivityData : Photon.MonoBehaviour
{
	public delegate void ValueChangedCallback(ActivityData sender, PhotonPlayer player, string key);

	public string GetKey(string subkey)
	{
		return $"{base.photonView.viewID}.{subkey}";
	}

	public void RegisterCallback(string key, ValueChangedCallback callback)
	{
		ActivityDataManager.Instance.RegisterCallback(this, key, callback);
	}

	public void UnregisterCallback(string key, ValueChangedCallback callback)
	{
		if (ActivityDataManager.Instance != null)
		{
			ActivityDataManager.Instance.UnregisterCallback(this, key, callback);
		}
	}

	public bool ContainsData(string key)
	{
		key = GetKey(key);
		return PhotonNetwork.room != null && PhotonNetwork.room.customProperties.ContainsKey(key) && PhotonNetwork.room.customProperties[key] != null;
	}

	public T GetData<T>(string key, T defaultValue)
	{
		key = GetKey(key);
		if (PhotonNetwork.room != null && PhotonNetwork.room.customProperties.ContainsKey(key))
		{
			return (T)PhotonNetwork.room.customProperties[key];
		}
		return defaultValue;
	}

	public void SetData<T>(string key, T data)
	{
		if (PhotonNetwork.room != null)
		{
			PhotonNetwork.room.SetCustomProperties(GetKey(key), data);
		}
	}

	public void SetData<T>(string key, T data, T expectedValue)
	{
		if (PhotonNetwork.room != null)
		{
			PhotonNetwork.room.SetCustomProperties(GetKey(key), data, expectedValue);
		}
	}

	public void RemoveData(string key)
	{
		if (PhotonNetwork.room != null)
		{
			PhotonNetwork.room.SetCustomProperties<object>(GetKey(key), null);
		}
	}

	public string GetKeyForPlayer(PhotonPlayer player, string subkey)
	{
		return $"PLAYERID{player.ID}.{subkey}";
	}

	public void RegisterCallbackForPlayer(PhotonPlayer player, string key, ValueChangedCallback callback)
	{
		ActivityDataManager.Instance.RegisterCallback(this, key, callback);
	}

	public void UnregisterCallbackForPlayer(PhotonPlayer player, string key, ValueChangedCallback callback)
	{
		if (ActivityDataManager.Instance != null)
		{
			ActivityDataManager.Instance.UnregisterCallback(this, key, callback);
		}
	}

	public bool ContainsDataForPlayer(PhotonPlayer player, string key)
	{
		key = GetKeyForPlayer(player, key);
		return PhotonNetwork.room != null && PhotonNetwork.room.customProperties.ContainsKey(key) && PhotonNetwork.room.customProperties[key] != null;
	}

	public T GetDataForPlayer<T>(PhotonPlayer player, string key, T defaultValue)
	{
		key = GetKeyForPlayer(player, key);
		if (PhotonNetwork.room != null && PhotonNetwork.room.customProperties.ContainsKey(key))
		{
			return (T)PhotonNetwork.room.customProperties[key];
		}
		return defaultValue;
	}

	public void SetDataForPlayer<T>(PhotonPlayer player, string key, T data)
	{
		if (PhotonNetwork.room != null)
		{
			PhotonNetwork.room.SetCustomProperties(GetKeyForPlayer(player, key), data);
		}
	}

	public void SetDataForPlayer<T>(PhotonPlayer player, string key, T data, T expectedValue)
	{
		if (PhotonNetwork.room != null)
		{
			PhotonNetwork.room.SetCustomProperties(GetKeyForPlayer(player, key), data, expectedValue);
		}
	}

	public void RemoveDataForPlayer(PhotonPlayer player, string key)
	{
		if (PhotonNetwork.room != null)
		{
			PhotonNetwork.room.SetCustomProperties<object>(GetKeyForPlayer(player, key), null);
		}
	}
}
[DisallowMultipleComponent]
public class ActivityDataManager : Photon.MonoBehaviour
{
	private class CallbackMap
	{
		public ActivityData ActivityData;

		public PhotonPlayer Player;

		public string SubKey;

		public ActivityData.ValueChangedCallback Callbacks;
	}

	public static ActivityDataManager Instance;

	private Dictionary<string, CallbackMap> activityDataCallbackMap = new Dictionary<string, CallbackMap>();

	private void Awake()
	{
		Instance = this;
	}

	private void OnDestroy()
	{
		if (Instance == this)
		{
			Instance = null;
		}
	}

	public void RegisterCallback(ActivityData activityData, string subkey, ActivityData.ValueChangedCallback callback)
	{
		string key = activityData.GetKey(subkey);
		if (activityDataCallbackMap.ContainsKey(key))
		{
			CallbackMap callbackMap = activityDataCallbackMap[key];
			callbackMap.Callbacks = (ActivityData.ValueChangedCallback)Delegate.Combine(callbackMap.Callbacks, callback);
			return;
		}
		activityDataCallbackMap[key] = new CallbackMap
		{
			ActivityData = activityData,
			Player = null,
			SubKey = subkey,
			Callbacks = callback
		};
	}

	public void UnregisterCallback(ActivityData activityData, string subkey, ActivityData.ValueChangedCallback callback)
	{
		string key = activityData.GetKey(subkey);
		if (activityDataCallbackMap.ContainsKey(key))
		{
			CallbackMap callbackMap = activityDataCallbackMap[key];
			callbackMap.Callbacks = (ActivityData.ValueChangedCallback)Delegate.Remove(callbackMap.Callbacks, callback);
			if (activityDataCallbackMap[key].Callbacks == null)
			{
				activityDataCallbackMap.Remove(key);
			}
		}
	}

	public void RegisterCallbackForPlayer(ActivityData activityData, PhotonPlayer player, string subkey, ActivityData.ValueChangedCallback callback)
	{
		string keyForPlayer = activityData.GetKeyForPlayer(player, subkey);
		if (activityDataCallbackMap.ContainsKey(keyForPlayer))
		{
			CallbackMap callbackMap = activityDataCallbackMap[keyForPlayer];
			callbackMap.Callbacks = (ActivityData.ValueChangedCallback)Delegate.Combine(callbackMap.Callbacks, callback);
			return;
		}
		activityDataCallbackMap[keyForPlayer] = new CallbackMap
		{
			ActivityData = activityData,
			Player = player,
			SubKey = subkey,
			Callbacks = callback
		};
	}

	public void UnregisterCallbackForPlayer(ActivityData activityData, PhotonPlayer player, string subkey, ActivityData.ValueChangedCallback callback)
	{
		string keyForPlayer = activityData.GetKeyForPlayer(player, subkey);
		if (activityDataCallbackMap.ContainsKey(keyForPlayer))
		{
			CallbackMap callbackMap = activityDataCallbackMap[keyForPlayer];
			callbackMap.Callbacks = (ActivityData.ValueChangedCallback)Delegate.Remove(callbackMap.Callbacks, callback);
			if (activityDataCallbackMap[keyForPlayer].Callbacks == null)
			{
				activityDataCallbackMap.Remove(keyForPlayer);
			}
		}
	}

	private void OnPhotonCustomRoomPropertiesChanged(ExitGames.Client.Photon.Hashtable propertiesThatChanged)
	{
		foreach (string item in propertiesThatChanged.Keys.OfType<string>())
		{
			if (activityDataCallbackMap.ContainsKey(item))
			{
				CallbackMap callbackMap = activityDataCallbackMap[item];
				callbackMap.Callbacks(callbackMap.ActivityData, callbackMap.Player, callbackMap.SubKey);
			}
		}
	}
}
public class ActivityGameStateSpecificGameObject : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private ActivityGameState[] supportedStates;

	private void Start()
	{
		ActivityManager.Instance.GameStateChangedEvent += OnActivityStateChanged;
		OnActivityStateChanged(ActivityGameState.Uninitialized, ActivityManager.Instance.GameState);
	}

	private void OnDestroy()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.GameStateChangedEvent -= OnActivityStateChanged;
		}
	}

	private void OnActivityStateChanged(ActivityGameState current, ActivityGameState next)
	{
		bool flag = false;
		for (int i = 0; i < supportedStates.Length; i++)
		{
			if (supportedStates[i] == next)
			{
				flag = true;
				break;
			}
		}
		Tool component = base.gameObject.GetComponent<Tool>();
		if (!base.gameObject.activeSelf && flag && component != null)
		{
			component.ResetToLastSpawnPosition();
		}
		else
		{
			base.gameObject.SetActive(flag);
		}
	}
}
public enum ActivityGameState
{
	Uninitialized = -1,
	PreGame,
	PlayingGame,
	PostGame,
	Countdown
}
[RequireComponent(typeof(ActivityData))]
[RequireComponent(typeof(ActivityPhysics))]
[RequireComponent(typeof(ActivityTeleportRestrictions))]
[RequireComponent(typeof(ActivityAudio))]
[RequireComponent(typeof(ActivityPostEffects))]
[RequireComponent(typeof(PhotonView))]
[RequireComponent(typeof(ActivityPlayerManager))]
[DisallowMultipleComponent]
public abstract class ActivityManager : Photon.MonoBehaviour
{
	protected const string GAME_DURATION_KEY = "GAME_DURATION";

	protected const string GAME_START_TIME_KEY = "GAME_START_TIME";

	protected const string GAME_PAUSE_TIME_KEY = "GAME_PAUSE_TIME";

	protected const float ESTIMATED_ROUNDTRIP_LATENCY = 0.2f;

	protected const float HIT_NOTIFICATION_OFFSET_DISTANCE = 0.35f;

	public static ActivityManager Instance;

	public static bool CollectPreviousActivityFeedback;

	public static bool PreviousActivityFeedbackEnabled = true;

	[SerializeField]
	protected bool supportsPlayingGame;

	[SerializeField]
	protected bool supportsOutOfBounds;

	[SerializeField]
	private string onLoadNotificationText = "Activity";

	[Tooltip("Per activity audio properties of the VOIP rolloff. ASK Cam if you dont know what this is!")]
	public AudioRolloff CustomPlayerVoipAudioRolloff;

	public AudioRolloff Custom3DSFXAudioRolloff;

	protected bool wasMasterClient;

	protected Coroutine gameStateCoroutine;

	private ActivityGameState _gameState = ActivityGameState.Uninitialized;

	private Coroutine changeActivityCoroutine;

	public static bool IsInitialized => Instance != null;

	public bool SupportsPlayingGame => supportsPlayingGame;

	public bool SupportsOutOfBounds => supportsOutOfBounds;

	public ActivityPlayerManager PlayerManager { get; protected set; }

	public ActivityData ActivityData { get; protected set; }

	public ActivityTeleportRestrictions TeleportRestrictions { get; protected set; }

	public ActivityAudio ActivityAudio { get; protected set; }

	public static string ActivityName => SceneManagerHelper.ActiveSceneName;

	public bool IsPlaying => GameState == ActivityGameState.PlayingGame;

	public ActivityGameState GameState => _gameState;

	protected virtual bool CollectFeedback => supportsPlayingGame;

	public bool ReadyToPlay => PlayerRequirementsMet;

	protected virtual bool PlayerRequirementsMet => false;

	public event Action GameModeChangedEvent;

	public event Action<ActivityGameState, ActivityGameState> GameStateChangedEvent;

	public event Action<PhotonPlayer, ActivityTeam> ActivityWonEvent;

	public event Action MasterClientChangedEvent;

	[PunRPC]
	protected void RpcEnterGameState(ActivityGameState state)
	{
		ActivityGameState gameState = _gameState;
		_gameState = state;
		if (this.GameStateChangedEvent != null)
		{
			this.GameStateChangedEvent(gameState, state);
		}
		if (PhotonNetwork.isMasterClient)
		{
			PUNNetworkManager.Instance.SetGameInProgress(state == ActivityGameState.PlayingGame);
			switch (_gameState)
			{
			case ActivityGameState.PreGame:
				MasterStartPreGameState();
				break;
			case ActivityGameState.PlayingGame:
				MasterStartPlayingGameState();
				break;
			case ActivityGameState.PostGame:
				MasterStartPostGameState();
				break;
			case ActivityGameState.Countdown:
				MasterStartCountdownState();
				break;
			}
		}
	}

	protected void MasterEnterGameState(ActivityGameState state)
	{
		if (PhotonNetwork.isMasterClient)
		{
			base.photonView.RPC("RpcEnterGameState", PhotonTargets.All, state);
		}
	}

	private void MasterStopGameStateCoroutine()
	{
		if (PhotonNetwork.isMasterClient && gameStateCoroutine != null)
		{
			StopCoroutine(gameStateCoroutine);
			gameStateCoroutine = null;
		}
	}

	private void MasterStartPreGameState()
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterStopGameStateCoroutine();
			gameStateCoroutine = StartCoroutine(PreGameStateCoroutine());
		}
	}

	private void MasterStartCountdownState()
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterStopGameStateCoroutine();
			gameStateCoroutine = StartCoroutine(CountdownStateCoroutine());
		}
	}

	private IEnumerator CountdownStateCoroutine()
	{
		yield return CountdownNotificationsAllPlayers();
		if (ReadyToPlay)
		{
			MasterPlaySoundAllPlayers("game_on");
			MasterShowNotificationAllPlayers("Game On!", 1f);
			MasterEnterGameState(ActivityGameState.PlayingGame);
		}
		else
		{
			MasterPlaySoundAllPlayers("countdown_notification");
			yield return MasterShowNotificationAllPlayers("Countdown Stopped. Not enough players.", 3f);
			MasterEnterGameState(ActivityGameState.PreGame);
		}
	}

	private void MasterStartPlayingGameState()
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterStopGameStateCoroutine();
			gameStateCoroutine = StartCoroutine(PlayingGameStateCoroutine());
		}
	}

	private void MasterStartPostGameState()
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterPlaySoundAllPlayers("game_over");
			MasterStopGameStateCoroutine();
			gameStateCoroutine = StartCoroutine(PostGameStateCoroutine());
		}
	}

	protected virtual IEnumerator PreGameStateCoroutine()
	{
		PlayerManager.MasterResetPlayerScores();
		yield return MasterRespawnAllPlayers();
	}

	protected virtual IEnumerator PlayingGameStateCoroutine()
	{
		yield break;
	}

	protected virtual IEnumerator PostGameStateCoroutine()
	{
		yield break;
	}

	protected virtual void Awake()
	{
		if (Instance == null)
		{
			Instance = this;
		}
		ActivityAudio = GetComponent<ActivityAudio>();
		TeleportRestrictions = GetComponent<ActivityTeleportRestrictions>();
		TeleportRestrictions.ThisActivity = this;
		PlayerManager = GetComponent<ActivityPlayerManager>();
		PlayerManager.ThisActivity = this;
		ActivityData = GetComponent<ActivityData>();
	}

	protected virtual IEnumerator Start()
	{
		yield return null;
		if (PhotonNetwork.isMasterClient)
		{
			OnServerActivityLoad();
			if (SupportsPlayingGame)
			{
				MasterEnterGameState(ActivityGameState.PreGame);
			}
			wasMasterClient = true;
		}
		OnClientActivityLoad();
		if (SingletonMonoBehaviour<PlayerInputManager>.Instance != null)
		{
			SingletonMonoBehaviour<PlayerInputManager>.Instance.PerformanceCounters.ResetHistograms();
		}
		if (PhotonNetwork.isMasterClient)
		{
			MasterSpawnNewPlayer(PhotonNetwork.player);
			MasterInitializePlayer(PhotonNetwork.player);
		}
	}

	protected virtual void OnDestroy()
	{
		PhotonNetwork.player.SetCustomProperties("prev_activity", ActivityName);
		CollectPreviousActivityFeedback = CollectFeedback && PreviousActivityFeedbackEnabled;
		if (PhotonNetwork.isMasterClient)
		{
			OnServerActivityDestroy();
		}
		StopAllCoroutines();
		if (Instance == this)
		{
			Instance = null;
		}
		if (Player.LocalPlayer != null)
		{
			Player.LocalPlayer.OnActivityManagerDestroyed();
		}
	}

