	private IEnumerator AttemptToMergeRoomsCoroutine()
	{
		string[] expectedUsers = new string[PhotonNetwork.otherPlayers.Length];
		for (int i = 0; i < PhotonNetwork.otherPlayers.Length; i++)
		{
			expectedUsers[i] = PhotonNetwork.otherPlayers[i].userId;
		}
		base.photonView.RPC("RpcPartyFollowLeader", PhotonTargets.Others, null, PhotonNetwork.player.userId, ActivityName);
		if (Player.LocalPlayer != null)
		{
			yield return Player.LocalPlayer.DespawnLocal(prepForLevelSwitch: true);
		}
		PUNNetworkManager.Instance.SwitchActivity(ActivityName, expectedUsers);
		changeActivityCoroutine = null;
	}

