	public bool HasAGameTimer()
	{
		return ActivityData.ContainsData("GAME_DURATION");
	}

	public float GetTimeRemaining()
	{
		float gameDuration = GetGameDuration();
		float currentTime = (float)PhotonNetwork.time;
		if (GetIsGameTimerPaused())
		{
			currentTime = GetGamePauseTime();
		}
		float gameTimeElapsed = GetGameTimeElapsed(currentTime);
		return Mathf.Max(0f, gameDuration - gameTimeElapsed);
	}

	private float GetGameTimeElapsed(float currentTime)
	{
		float gameStartTime = GetGameStartTime();
		if (gameStartTime >= 0f)
		{
			return currentTime - gameStartTime;
		}
		return 0f;
	}

	protected float GetGameDuration()
	{
		return ActivityData.GetData("GAME_DURATION", float.MaxValue);
	}

	protected void SetGameDuration(float duration)
	{
		ActivityData.SetData("GAME_DURATION", duration);
	}

	protected float GetGameStartTime()
	{
		return ActivityData.GetData("GAME_START_TIME", -1f);
	}

	protected void SetGameStartTime(float startTime)
	{
		ActivityData.SetData("GAME_START_TIME", startTime);
	}

	protected void ClearGameStartTime()
	{
		ActivityData.SetData("GAME_START_TIME", -1f);
	}

	protected bool GetIsGameTimerPaused()
	{
		return GetGamePauseTime() >= 0f;
	}

	protected void SetIsGameTimerPaused(bool pause)
	{
		float num = (float)PhotonNetwork.time;
		bool isGameTimerPaused = GetIsGameTimerPaused();
		if (pause && !isGameTimerPaused)
		{
			SetGamePauseTime(num);
		}
		else if (!pause && isGameTimerPaused)
		{
			float gameDuration = GetGameDuration();
			float timeRemaining = GetTimeRemaining();
			float num2 = gameDuration - timeRemaining;
			float gameStartTime = num - num2;
			SetGameStartTime(gameStartTime);
			SetGamePauseTime(-1f);
		}
	}

	protected float GetGamePauseTime()
	{
		return ActivityData.GetData("GAME_PAUSE_TIME", -1f);
	}

	protected void SetGamePauseTime(float pauseTime)
	{
		ActivityData.SetData("GAME_PAUSE_TIME", pauseTime);
	}

