	public void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (PhotonNetwork.isMasterClient)
		{
			base.photonView.RPC("RpcEnterGameState", newPlayer, GameState);
			MasterSpawnNewPlayer(newPlayer);
			MasterInitializePlayer(newPlayer);
			if (GameState == ActivityGameState.PlayingGame)
			{
				ActivityTeam playerTeam = PlayerManager.GetPlayerTeam(newPlayer);
				MasterShowNotificationAllOtherPlayers(newPlayer, newPlayer.name + " has joined the " + ((playerTeam == null) ? "game!" : (playerTeam.Name + " team!")), 3f);
				MasterTryUpdateGame();
			}
		}
	}

	public virtual void OnMasterClientSwitched(PhotonPlayer newMasterClient)
	{
		if (!PhotonNetwork.isMasterClient && wasMasterClient)
		{
			StopAllCoroutines();
			wasMasterClient = false;
		}
		else if (PhotonNetwork.isMasterClient)
		{
			wasMasterClient = true;
			PhotonPlayer[] playerList = PhotonNetwork.playerList;
			foreach (PhotonPlayer photonPlayer in playerList)
			{
				if (photonPlayer.ToPlayer() == null)
				{
					MasterSpawnNewPlayer(photonPlayer);
				}
			}
			if (GameState == ActivityGameState.PlayingGame)
			{
				MasterTryUpdateGame();
			}
			else if (GameState == ActivityGameState.Countdown || (GameState == ActivityGameState.PlayingGame && !ReadyToPlay))
			{
				MasterEnterGameState(ActivityGameState.PreGame);
			}
			else if (GameState == ActivityGameState.Uninitialized)
			{
				OnServerActivityLoad();
				if (SupportsPlayingGame)
				{
					MasterEnterGameState(ActivityGameState.PreGame);
				}
			}
		}
		if (this.MasterClientChangedEvent != null)
		{
			this.MasterClientChangedEvent();
		}
	}

	public virtual void OnPhotonPlayerDisconnected(PhotonPlayer photonPlayer)
	{
		MasterRemovePlayer(photonPlayer);
		if (PhotonNetwork.isMasterClient && GameState == ActivityGameState.PlayingGame)
		{
			if (!ReadyToPlay)
			{
				MasterShowNotificationAllPlayers("Game Over!", 3f, photonPlayer.name + " left the game");
				MasterEnterGameState(ActivityGameState.PreGame);
			}
			else
			{
				MasterShowNotificationAllPlayers(photonPlayer.name + " left the game", 3f);
				MasterTryUpdateGame();
			}
		}
	}
