[DisallowMultipleComponent]
public abstract class ActivityPlayerManager : PunBehaviour
{
	protected const int DEFAULT_PLAYER_COUNT = 0;

	protected const int DEFAULT_PLAYER_SLOT = -1;

	protected readonly string ACTIVE_PLAYER_SLOT_KEY = "ACTIVE_PLAYER_SLOT";

	protected readonly string TEAM_ID_KEY = "TEAM_ID";

	protected readonly string SCORE_KEY = "SCORE";

	protected readonly string IS_SPECTATOR_KEY = "IS_SPECTATOR";

	[SerializeField]
	protected bool supportsJoinInProgress = true;

	[Tooltip("How many seconds before you are kicked out of the activity for being AFK")]
	[Header("AFK settings")]
	public float AFKKickToIntroTimeout = 60f;

	[Tooltip("How many seconds before we start showing you warning for AFK")]
	public float AFKWarningStartTimeout = 30f;

	[HideInInspector]
	public ActivityManager ThisActivity;

	protected ActivityData activityData;

	protected List<ActivityTeam> teams = new List<ActivityTeam>();

	private List<bool> occupiedRoleScratchSpace = new List<bool>();

	public abstract int MaxActivePlayers { get; }

	public event Action<PhotonPlayer> RolesUpdatedEvent;

	public event Action ScoresChangedEvent;

	protected virtual void Awake()
	{
		activityData = GetComponent<ActivityData>();
	}

	protected virtual void Start()
	{
	}

	public abstract Transform GetSpawnPoint(PhotonPlayer player, string previousActivity = null);

	public abstract Transform GetNextSpectatorSpawnPoint();

	public void RequestAutoAssignRole(PhotonPlayer player)
	{
		base.photonView.RPC("RpcRequestAutoAssignActivityPlayerRole", PhotonTargets.MasterClient, player, ActivityTeam.InvalidTeamId);
	}

	public void RequestAutoAssignRoleOnDifferentTeam(PhotonPlayer player)
	{
		int num = ((player == null) ? null : GetPlayerTeam(player))?.Id ?? ActivityTeam.InvalidTeamId;
		base.photonView.RPC("RpcRequestAutoAssignActivityPlayerRole", PhotonTargets.MasterClient, player, num);
	}

	public void RequestToVacateRole(PhotonPlayer player)
	{
		int playerSlot = GetPlayerSlot(player);
		if (playerSlot != -1)
		{
			base.photonView.RPC("RpcRequestToVacatePlayerRole", PhotonTargets.MasterClient, player);
		}
	}

	public int GetPlayerSlot(PhotonPlayer player)
	{
		return activityData.GetDataForPlayer(player, ACTIVE_PLAYER_SLOT_KEY, -1);
	}

	public bool IsPlayerSpectator(PhotonPlayer player)
	{
		return activityData.GetDataForPlayer(player, IS_SPECTATOR_KEY, defaultValue: true);
	}

	public PhotonPlayer GetPlayerAtActiveSlot(int slot)
	{
		PhotonPlayer[] activePlayers = GetActivePlayers();
		foreach (PhotonPlayer photonPlayer in activePlayers)
		{
			if (GetPlayerSlot(photonPlayer) == slot)
			{
				return photonPlayer;
			}
		}
		return null;
	}

