	protected abstract bool TryGetNextAutoAssignRole(out int slot, out int teamId, int forbiddenTeamId);

	protected bool TryFindLowestUnoccupiedSlot(PhotonPlayer[] occupiers, int minSlot, int slotCount, out int unoccupiedSlot)
	{
		unoccupiedSlot = -1;
		if (slotCount <= 0 || minSlot == -1)
		{
			return false;
		}
		occupiedRoleScratchSpace.Clear();
		for (int i = 0; i < slotCount; i++)
		{
			occupiedRoleScratchSpace.Add(item: false);
		}
		foreach (PhotonPlayer player in occupiers)
		{
			int num = GetPlayerSlot(player) - minSlot;
			if (num >= 0 && num < slotCount)
			{
				occupiedRoleScratchSpace[num] = true;
			}
		}
		for (int k = 0; k < occupiedRoleScratchSpace.Count; k++)
		{
			if (!occupiedRoleScratchSpace[k])
			{
				unoccupiedSlot = k + minSlot;
				return true;
			}
		}
		return false;
	}

