	public int GetMaxPlayerScore(out PhotonPlayer maxScorePlayer)
	{
		int num = 0;
		maxScorePlayer = null;
		PhotonPlayer[] activePlayers = GetActivePlayers();
		PhotonPlayer[] array = activePlayers;
		foreach (PhotonPlayer photonPlayer in array)
		{
			int playerScore = GetPlayerScore(photonPlayer);
			if (playerScore > num)
			{
				num = playerScore;
				maxScorePlayer = photonPlayer;
			}
			else if (playerScore == num)
			{
				maxScorePlayer = null;
			}
		}
		return num;
	}

	public int GetMaxTeamScore(out ActivityTeam maxScoreTeam)
	{
		int num = 0;
		maxScoreTeam = null;
		ActivityTeam[] activeTeams = GetActiveTeams();
		ActivityTeam[] array = activeTeams;
		foreach (ActivityTeam activityTeam in array)
		{
			int teamScore = GetTeamScore(activityTeam);
			if (teamScore > num)
			{
				num = teamScore;
				maxScoreTeam = activityTeam;
			}
			else if (teamScore == num)
			{
				maxScoreTeam = null;
			}
		}
		return num;
	}

	[PunRPC]
	public void RpcRequestActivityPlayerRole(PhotonPlayer photonPlayer, int slot, int teamId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			PhotonPlayer playerAtActiveSlot = GetPlayerAtActiveSlot(slot);
			if (playerAtActiveSlot == null)
			{
				MasterSetPlayerActiveSlot(photonPlayer, slot);
				MasterSetPlayerSpectator(photonPlayer, isSpectator: false);
				MasterSetPlayerTeam(photonPlayer, GetTeam(teamId));
				base.photonView.RPC("RpcPlayerRolesUpdated", PhotonTargets.All, photonPlayer);
			}
		}
	}

	[PunRPC]
	public void RpcRequestAutoAssignActivityPlayerRole(PhotonPlayer photonPlayer, int forbiddenTeamId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			bool flag = ThisActivity.GameState != ActivityGameState.PlayingGame || supportsJoinInProgress;
			int slot = -1;
			int teamId = ActivityTeam.InvalidTeamId;
			if (flag && TryGetNextAutoAssignRole(out slot, out teamId, forbiddenTeamId))
			{
				RpcRequestActivityPlayerRole(photonPlayer, slot, teamId);
			}
		}
	}

	[PunRPC]
	public void RpcRequestToVacatePlayerRole(PhotonPlayer player)
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterSetPlayerActiveSlot(player, -1);
			MasterSetPlayerSpectator(player, isSpectator: true);
			MasterSetPlayerTeam(player, null);
			base.photonView.RPC("RpcPlayerRolesUpdated", PhotonTargets.All, player);
		}
	}

	[PunRPC]
	public void RpcScoresChanged()
	{
		if (this.ScoresChangedEvent != null)
		{
			this.ScoresChangedEvent();
		}
	}

	[PunRPC]
	public void RpcPlayerRolesUpdated(PhotonPlayer photonPlayer)
	{
		if (this.RolesUpdatedEvent != null)
		{
			this.RolesUpdatedEvent(photonPlayer);
		}
	}

	public override void OnPhotonPlayerDisconnected(PhotonPlayer otherPlayer)
	{
		base.OnPhotonPlayerDisconnected(otherPlayer);
		activityData.RemoveDataForPlayer(otherPlayer, ACTIVE_PLAYER_SLOT_KEY);
		activityData.RemoveDataForPlayer(otherPlayer, TEAM_ID_KEY);
		activityData.RemoveDataForPlayer(otherPlayer, SCORE_KEY);
		activityData.RemoveDataForPlayer(otherPlayer, IS_SPECTATOR_KEY);
		base.photonView.RPC("RpcPlayerRolesUpdated", PhotonTargets.All, otherPlayer);
	}
