public class ActivityPresence : Photon.MonoBehaviour
{
	[Serializable]
	private struct RichPresenceStatusMapping
	{
		public string Name;

		public ActivityGameState[] GameStates;
	}

	[SerializeField]
	private string activityName;

	[SerializeField]
	private RichPresenceStatusMapping[] richPresenceStatusMappings;

	private void Start()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.GameStateChangedEvent += OnActvityGameStateChanged;
		}
		if (SteamManager.Initialized)
		{
			SteamFriends.SetRichPresence("activity", (!(ActivityManager.Instance != null)) ? string.Empty : ActivityManager.ActivityName);
			UpdateRichPresenceStatus();
		}
	}

	private void OnDisable()
	{
		SetRichPresenceStatus(null);
	}

	private void OnDestroy()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.GameStateChangedEvent -= OnActvityGameStateChanged;
		}
	}

	private void OnActvityGameStateChanged(ActivityGameState oldState, ActivityGameState newState)
	{
		UpdateRichPresenceStatus();
	}

	private void UpdateRichPresenceStatus()
	{
		string richPresenceStatus = null;
		if (ActivityManager.Instance != null)
		{
			RichPresenceStatusMapping[] array = richPresenceStatusMappings;
			for (int i = 0; i < array.Length; i++)
			{
				RichPresenceStatusMapping richPresenceStatusMapping = array[i];
				if (richPresenceStatusMapping.GameStates == null || richPresenceStatusMapping.GameStates.Length == 0 || richPresenceStatusMapping.GameStates.Contains(ActivityManager.Instance.GameState))
				{
					richPresenceStatus = richPresenceStatusMapping.Name;
					break;
				}
			}
		}
		SetRichPresenceStatus(richPresenceStatus);
	}

	private void SetRichPresenceStatus(string statusText)
	{
		if (SteamManager.Initialized)
		{
			SteamFriends.SetRichPresence("status", statusText);
		}
	}
}
