[DisallowMultipleComponent]
public class ActivityTeleportRestrictions : Photon.MonoBehaviour
{
	[Header("Mode")]
	[SerializeField]
	private bool useStraightLaser;

	[SerializeField]
	private bool teleportPlayerLineTrailsEnabled;

	[SerializeField]
	[Header("Cooldown")]
	private float defaultTeleportCooldown;

	[SerializeField]
	private float spectatorTeleportCooldown;

	[SerializeField]
	private float activePlayerTeleportCooldown;

	[SerializeField]
	private float toolHitTeleportCooldown = 2f;

	[Header("Max Teleport Distance")]
	[SerializeField]
	private float maxTeleportDistance = 12f;

	[SerializeField]
	private float maxTeleportAngle = 45f;

	[SerializeField]
	[Header("Teleport Tool Hit")]
	private bool teleportToolHitEnabled;

	[Header("Player Teleport Buffer")]
	[SerializeField]
	public float GamePlayMinTeleportBuffer = 0.5f;

	private bool globalDisableAllActivePlayers;

	public ActivityManager ThisActivity { get; set; }

	public bool UseStraightLaser => useStraightLaser;

	public bool TeleportPlayerLineTrailsEnabled => teleportPlayerLineTrailsEnabled;

	public float MaxTeleportDistance
	{
		get
		{
			return maxTeleportDistance;
		}
		set
		{
			maxTeleportDistance = value;
		}
	}

	public float MaxTeleportAngle => maxTeleportAngle;

	public bool TeleportToolHitEnabled => teleportToolHitEnabled;

	public virtual float GetTeleportCooldown(Player player, bool justHitTool)
	{
		if (justHitTool)
		{
			return toolHitTeleportCooldown;
		}
		if (ThisActivity.GameState != ActivityGameState.PlayingGame)
		{
			return defaultTeleportCooldown;
		}
		if (ThisActivity.PlayerManager.IsPlayerSpectator(player.PhotonPlayer))
		{
			return spectatorTeleportCooldown;
		}
		return activePlayerTeleportCooldown;
	}

	public bool IsValidRegion(Player player, TeleportRestriction restrictions)
	{
		if (restrictions == null)
		{
			return true;
		}
		if (ThisActivity.GameState != ActivityGameState.PlayingGame && restrictions.AllowedInPreGame)
		{
			return true;
		}
		if (ThisActivity.PlayerManager.IsPlayerSpectator(player.PhotonPlayer))
		{
			return restrictions.AllowSpectators;
		}
		if (globalDisableAllActivePlayers)
		{
			return false;
		}
		if (restrictions.AllowAllActivePlayers)
		{
			return true;
		}
		if (restrictions.AllowedTeamIds != null && restrictions.AllowedTeamIds.Length > 0)
		{
			ActivityTeam playerTeam = ThisActivity.PlayerManager.GetPlayerTeam(player.PhotonPlayer);
			if (playerTeam != null && restrictions.AllowedTeamIds.Contains(playerTeam.Id))
			{
				return true;
			}
		}
		if (restrictions.AllowedSlots != null && restrictions.AllowedSlots.Length > 0)
		{
			int playerSlot = ThisActivity.PlayerManager.GetPlayerSlot(player.PhotonPlayer);
			if (restrictions.AllowedSlots.Contains(playerSlot))
			{
				return true;
			}
		}
		return false;
	}

	public void MasterEnableAllActivePlayerTeleportation()
	{
		if (PhotonNetwork.isMasterClient)
		{
			base.photonView.RPC("RpcSetActivePlayerTeleportation", PhotonTargets.All, true);
		}
	}

	public void MasterDisableAllActivePlayerTeleportation()
	{
		if (PhotonNetwork.isMasterClient)
		{
			base.photonView.RPC("RpcSetActivePlayerTeleportation", PhotonTargets.All, false);
		}
	}

	[PunRPC]
	public void RpcSetActivePlayerTeleportation(bool enable)
	{
		globalDisableAllActivePlayers = !enable;
	}
}
