public class DefaultPlayerManager : ActivityPlayerManager
{
	[Serializable]
	private struct SpawnPointCollection
	{
		public string Name;

		public Transform[] SpawnPoints;
	}

	[SerializeField]
	private SpawnPointCollection[] activityEntrySpawnPoints;

	[SerializeField]
	private Transform[] defaultSpawnPoints;

	private int nextSpawnPointIndex = -1;

	public override int MaxActivePlayers => 0;

	public override Transform GetSpawnPoint(PhotonPlayer player, string previousActivity = null)
	{
		Transform[] spawnPoints = defaultSpawnPoints;
		if (!string.IsNullOrEmpty(previousActivity))
		{
			for (int i = 0; i < activityEntrySpawnPoints.Length; i++)
			{
				if (activityEntrySpawnPoints[i].Name == previousActivity)
				{
					spawnPoints = activityEntrySpawnPoints[i].SpawnPoints;
					break;
				}
			}
		}
		return GetNextSpawnPoint(spawnPoints);
	}

	public override Transform GetNextSpectatorSpawnPoint()
	{
		return GetNextSpawnPoint(defaultSpawnPoints);
	}

	private Transform GetNextSpawnPoint(Transform[] spawnPoints)
	{
		nextSpawnPointIndex++;
		return spawnPoints[nextSpawnPointIndex % spawnPoints.Length];
	}

	protected override bool TryGetNextAutoAssignRole(out int slot, out int teamId, int forbiddenTeamId)
	{
		slot = -1;
		teamId = ActivityTeam.InvalidTeamId;
		return false;
	}
}
public class FreeForAllPlayerManager : ActivityPlayerManager
{
	[Serializable]
	private struct FreeForAllPlayerRole
	{
		public ActivityRoleSelector RoleSelector;

		public Transform SpawnPoint;

		public Color Color;
	}

	[SerializeField]
	[Header("Pre-Game")]
	private Transform[] preGameSpawnPoints;

	[SerializeField]
	[Header("Playing Game")]
	private FreeForAllPlayerRole[] playerRoles;

	[SerializeField]
	private Transform[] spectatorSpawnPoints;

	private int nextSpawnPointIndex = -1;

	private int maxActivePlayers;

	public override int MaxActivePlayers => maxActivePlayers;

	protected override void Start()
	{
		base.Start();
		int num = 0;
		FreeForAllPlayerRole[] array = playerRoles;
		for (int i = 0; i < array.Length; i++)
		{
			FreeForAllPlayerRole freeForAllPlayerRole = array[i];
			freeForAllPlayerRole.RoleSelector.ActivePlayerSlot = num++;
			freeForAllPlayerRole.RoleSelector.TeamId = ActivityTeam.InvalidTeamId;
			freeForAllPlayerRole.RoleSelector.Color = freeForAllPlayerRole.Color;
			freeForAllPlayerRole.RoleSelector.UpdateLabel(null);
		}
		maxActivePlayers = num;
	}

	public override Transform GetSpawnPoint(PhotonPlayer player, string previousActivity = null)
	{
		if (ActivityManager.Instance.GameState == ActivityGameState.PlayingGame && !IsPlayerSpectator(player))
		{
			return playerRoles[GetPlayerSlot(player) % playerRoles.Length].SpawnPoint;
		}
		return GetNextSpectatorSpawnPoint();
	}

	public override Transform GetNextSpectatorSpawnPoint()
	{
		nextSpawnPointIndex++;
		return (ActivityManager.Instance.GameState == ActivityGameState.PlayingGame) ? spectatorSpawnPoints[nextSpawnPointIndex % spectatorSpawnPoints.Length] : preGameSpawnPoints[nextSpawnPointIndex % preGameSpawnPoints.Length];
	}

	protected override bool TryGetNextAutoAssignRole(out int slot, out int teamId, int forbiddenTeamId)
	{
		slot = -1;
		teamId = ActivityTeam.InvalidTeamId;
		PhotonPlayer[] activePlayers = GetActivePlayers();
		if (activePlayers.Length >= playerRoles.Length)
		{
			return false;
		}
		if (TryFindLowestUnoccupiedSlot(activePlayers, 0, playerRoles.Length, out slot))
		{
			return true;
		}
		return false;
	}
}
