public class OccupiableSpawnPoint : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool automaticallyRelease = true;

	[SerializeField]
	private float sphereCheckRadius = 0.25f;

	[SerializeField]
	private Vector3 sphereCheckCenter = Vector3.zero;

	public bool Occupied { get; private set; }

	public event Action<OccupiableSpawnPoint> AutomaticallyReleasedEvent;

	private void Update()
	{
		if (!Occupied || !automaticallyRelease)
		{
			return;
		}
		Vector3 position = base.transform.TransformPoint(sphereCheckCenter);
		if (!Physics.CheckSphere(position, sphereCheckRadius, 402432, QueryTriggerInteraction.Ignore))
		{
			if (this.AutomaticallyReleasedEvent != null)
			{
				this.AutomaticallyReleasedEvent(this);
			}
			Release();
		}
	}

	public void Occupy()
	{
		Occupied = true;
	}

	public void Release()
	{
		Occupied = false;
	}

	private void OnDrawGizmos()
	{
		if (automaticallyRelease)
		{
			Gizmos.color = ((!Occupied) ? Color.green : Color.red);
			Gizmos.DrawWireSphere(base.transform.TransformPoint(sphereCheckCenter), sphereCheckRadius);
		}
	}
}
[DisallowMultipleComponent]
public class PlayerInteractionRestriction : Photon.MonoBehaviour
{
	[Header("Pre Game State")]
	public bool AllowedInPreGame = true;

	[Header("Playing Game State")]
	public bool AllowSpectators = true;

	public bool AllowAllActivePlayers = true;

	public int[] AllowedTeamIds;

	public int[] AllowedSlots;

	protected bool defaultAllowedInPreGame;

	protected bool defaultAllowSpectators;

	protected bool defaultAllowAllActivePlayers;

	protected int[] defaultAllowedTeamIds;

	protected int[] defaultAllowedSlots;

	public virtual bool PlayerInteractionAllowed(Player player)
	{
		if (!ActivityManager.Instance.SupportsPlayingGame)
		{
			return true;
		}
		if (ActivityManager.Instance.GameState != ActivityGameState.PlayingGame && AllowedInPreGame)
		{
			return true;
		}
		bool flag = ActivityManager.Instance.PlayerManager.IsPlayerSpectator(player.PhotonPlayer);
		if (flag && AllowSpectators)
		{
			return true;
		}
		if (!flag && AllowAllActivePlayers)
		{
			return true;
		}
		if (AllowedTeamIds != null && AllowedTeamIds.Length > 0)
		{
			ActivityTeam playerTeam = ActivityManager.Instance.PlayerManager.GetPlayerTeam(player.PhotonPlayer);
			if (playerTeam != null && AllowedTeamIds.Contains(playerTeam.Id))
			{
				return true;
			}
		}
		if (AllowedSlots != null && AllowedSlots.Length > 0)
		{
			int playerSlot = ActivityManager.Instance.PlayerManager.GetPlayerSlot(player.PhotonPlayer);
			if (AllowedSlots.Contains(playerSlot))
			{
				return true;
			}
		}
		return false;
	}

	protected virtual void Awake()
	{
		defaultAllowedInPreGame = AllowedInPreGame;
		defaultAllowSpectators = AllowSpectators;
		defaultAllowAllActivePlayers = AllowAllActivePlayers;
		defaultAllowedTeamIds = AllowedTeamIds;
		defaultAllowedSlots = AllowedSlots;
	}

	public void MasterResetToDefaulRestrictions()
	{
		if (PhotonNetwork.isMasterClient)
		{
			base.photonView.RPC("RpcRestrictPlayerInteractions", PhotonTargets.All, defaultAllowedInPreGame, defaultAllowSpectators, defaultAllowAllActivePlayers, defaultAllowedTeamIds, defaultAllowedSlots);
		}
	}

	public void MasterRestrictToActivePlayerSlot(int slot)
	{
		if (PhotonNetwork.isMasterClient)
		{
			base.photonView.RPC("RpcRestrictPlayerInteractions", PhotonTargets.All, false, false, false, null, new int[1] { slot });
		}
	}

	public void MasterRestrictToTeam(int teamId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			base.photonView.RPC("RpcRestrictPlayerInteractions", PhotonTargets.All, false, false, false, new int[1] { teamId }, null);
		}
	}

	[PunRPC]
	public void RpcRestrictPlayerInteractions(bool allowedInPreGame, bool allowSpectators, bool allowAllActivePlayers, int[] allowedTeamIds, int[] allowedSlots)
	{
		AllowedInPreGame = allowedInPreGame;
		AllowSpectators = allowSpectators;
		AllowAllActivePlayers = allowAllActivePlayers;
		AllowedTeamIds = allowedTeamIds;
		AllowedSlots = allowedSlots;
	}

	private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (base.hasAuthority)
		{
			base.photonView.RPC("RpcRestrictPlayerInteractions", newPlayer, AllowedInPreGame, AllowSpectators, AllowAllActivePlayers, AllowedTeamIds, AllowedSlots);
		}
	}
}
public class Scoreboard : UnityEngine.MonoBehaviour
{
	[Serializable]
	protected class ScoreboardEntryTextMeshes
	{
		[SerializeField]
		private TextMesh[] TextMeshes;

		public string Text
		{
			set
			{
				TextMesh[] textMeshes = TextMeshes;
				foreach (TextMesh textMesh in textMeshes)
				{
					textMesh.text = value;
				}
			}
		}
	}

	[SerializeField]
	protected ScoreboardEntryTextMeshes[] competitiveScores;

	[SerializeField]
	protected ScoreboardEntryTextMeshes[] competitiveNames;

	private float gameplayTimer;

	public virtual void Reset()
	{
		gameplayTimer = 0f;
		ScoreboardEntryTextMeshes[] array = competitiveScores;
		foreach (ScoreboardEntryTextMeshes scoreboardEntryTextMeshes in array)
		{
			scoreboardEntryTextMeshes.Text = FormatScoreString(0);
		}
	}

	protected virtual void Start()
	{
		ActivityManager.Instance.PlayerManager.RolesUpdatedEvent += OnPlayerRolesUpdated;
		ActivityManager.Instance.PlayerManager.ScoresChangedEvent += OnScoresChanged;
		ActivityManager.Instance.ActivityWonEvent += OnActivityWon;
		ActivityManager.Instance.GameModeChangedEvent += OnScoresChanged;
	}

	private void OnDestroy()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.PlayerManager.RolesUpdatedEvent -= OnPlayerRolesUpdated;
			ActivityManager.Instance.PlayerManager.ScoresChangedEvent -= OnScoresChanged;
			ActivityManager.Instance.ActivityWonEvent -= OnActivityWon;
			ActivityManager.Instance.GameModeChangedEvent -= OnScoresChanged;
		}
	}

	private void Update()
	{
		if (gameplayTimer > 0f)
		{
			gameplayTimer = Mathf.Max(gameplayTimer - Time.deltaTime, 0f);
		}
	}

	protected virtual void OnScoresChanged()
	{
		for (int i = 0; i < competitiveScores.Length; i++)
		{
			competitiveScores[i].Text = string.Empty;
			competitiveNames[i].Text = string.Empty;
		}
		PhotonPlayer[] activePlayersSortedBySlot = ActivityManager.Instance.PlayerManager.GetActivePlayersSortedBySlot();
		for (int j = 0; j < activePlayersSortedBySlot.Length && j < competitiveScores.Length; j++)
		{
			int playerScore = ActivityManager.Instance.PlayerManager.GetPlayerScore(activePlayersSortedBySlot[j]);
			competitiveScores[j].Text = FormatScoreString(playerScore);
			competitiveNames[j].Text = activePlayersSortedBySlot[j].name;
		}
	}

	protected virtual void OnPlayerRolesUpdated(PhotonPlayer player)
	{
		OnScoresChanged();
	}

	protected virtual void OnActivityWon(PhotonPlayer player, ActivityTeam team)
	{
	}

	protected virtual string FormatScoreString(int score, bool threeDecimalPoints = false)
	{
		return score.ToString((!threeDecimalPoints) ? "D2" : "D3");
	}
}
public class TeamPlayerManager : ActivityPlayerManager
{
	[Serializable]
	protected class TeamRole
	{
		public ActivityTeam Team;

		public int SlotCount;

		public Transform[] SpawnPoints;

		[HideInInspector]
		public int MinSlotId;
	}

	protected const string LAST_SPAWN_TIME_KEY = "LAST_SPAWN_TIME";

	[SerializeField]
	protected float spawnPointOccupationRadius = 0.5f;

	[SerializeField]
	protected float minOccupationDuration = 5f;

	[Header("Pre-Game")]
	[SerializeField]
	protected Transform[] preGameSpawnPoints;

	[SerializeField]
	[Header("Playing Game")]
	protected TeamRole[] teamRoles;

	[SerializeField]
	protected Transform[] spectatorSpawnPoints;

	[SerializeField]
	protected bool randomizeSpawnPoint;

	protected int nextSpawnPointIndex = -1;

	protected int maxActivePlayers;

	public override int MaxActivePlayers => maxActivePlayers;

	protected override void Start()
	{
		base.Start();
		int num = 0;
		int num2 = 0;
		TeamRole[] array = teamRoles;
		foreach (TeamRole teamRole in array)
		{
			teamRole.Team.Id = num2;
			teams.Add(teamRole.Team);
			teamRole.MinSlotId = num;
			num += teamRole.SlotCount;
			num2++;
		}
		maxActivePlayers = num;
	}

	public override Transform GetSpawnPoint(PhotonPlayer player, string previousActivity = null)
	{
		Transform transform = null;
		if (ActivityManager.Instance.GameState == ActivityGameState.PlayingGame && !IsPlayerSpectator(player))
		{
			transform = ((!randomizeSpawnPoint) ? GetPlayerSpawnPoint(player) : GetRandomSpawnPoint(player));
		}
		if (transform != null)
		{
			return transform;
		}
		return GetNextSpectatorSpawnPoint();
	}

	public override ActivityTeam GetOtherTeam(ActivityTeam team)
	{
		TeamRole[] array = teamRoles;
		foreach (TeamRole teamRole in array)
		{
			if (teamRole.Team != team)
			{
				return teamRole.Team;
			}
		}
		return null;
	}

	private Transform GetPlayerSpawnPoint(PhotonPlayer player)
	{
		ActivityTeam playerTeam = GetPlayerTeam(player);
		TeamRole teamRole = GetTeamRole(playerTeam);
		if (teamRole != null && teamRole.SpawnPoints != null && teamRole.SpawnPoints.Length > 0)
		{
			int playerSlot = GetPlayerSlot(player);
			int num = playerSlot - teamRole.MinSlotId;
			return teamRole.SpawnPoints[num % teamRole.SpawnPoints.Length];
		}
		return null;
	}

	private Transform GetRandomSpawnPoint(PhotonPlayer player)
	{
		ActivityTeam playerTeam = GetPlayerTeam(player);
		TeamRole teamRole = GetTeamRole(playerTeam);
		if (teamRole != null && teamRole.SpawnPoints != null && teamRole.SpawnPoints.Length > 0)
		{
			int num = teamRole.SpawnPoints.Length;
			int num2 = UnityEngine.Random.Range(0, num);
			for (int i = 0; i < num; i++)
			{
				float lastSpawnTime = GetLastSpawnTime(playerTeam, num2);
				float num3 = (float)PhotonNetwork.time - lastSpawnTime;
				if (num3 >= minOccupationDuration)
				{
					Transform result = teamRole.SpawnPoints[num2];
					SetLastSpawnTime(playerTeam, num2, (float)PhotonNetwork.time);
					return result;
				}
				num2 = (num2 + 1) % num;
			}
		}
		return GetPlayerSpawnPoint(player);
	}

	public override Transform GetNextSpectatorSpawnPoint()
	{
		nextSpawnPointIndex++;
		return (ActivityManager.Instance.GameState == ActivityGameState.PlayingGame) ? spectatorSpawnPoints[nextSpawnPointIndex % spectatorSpawnPoints.Length] : preGameSpawnPoints[nextSpawnPointIndex % preGameSpawnPoints.Length];
	}

	public override int GetTeamMaxPlayers(ActivityTeam team)
	{
		return GetTeamRole(team)?.SlotCount ?? 0;
	}

	protected override bool TryGetNextAutoAssignRole(out int slot, out int teamId, int forbiddenTeamId)
	{
		ActivityTeam team = GetTeam(forbiddenTeamId);
		slot = -1;
		teamId = ActivityTeam.InvalidTeamId;
		int num = 0;
		TeamRole[] array = teamRoles;
		foreach (TeamRole teamRole in array)
		{
			num += teamRole.SlotCount;
		}
		PhotonPlayer[] activePlayers = GetActivePlayers();
		if (activePlayers.Length >= num)
		{
			return false;
		}
		int num2 = -1;
		List<TeamRole> list = new List<TeamRole>();
		TeamRole[] array2 = teamRoles;
		foreach (TeamRole teamRole2 in array2)
		{
			int teamPlayerCount = GetTeamPlayerCount(teamRole2.Team);
			if ((team == null || team != teamRole2.Team) && (num2 < 0 || teamPlayerCount <= num2))
			{
				if (num2 < 0 || teamPlayerCount < num2)
				{
					list.Clear();
					num2 = teamPlayerCount;
				}
				list.Add(teamRole2);
			}
		}
		if (list.Count == 0)
		{
			return false;
		}
		TeamRole teamRole3 = list[UnityEngine.Random.Range(0, list.Count)];
		PhotonPlayer[] teamPlayers = GetTeamPlayers(teamRole3.Team);
		if (TryFindLowestUnoccupiedSlot(teamPlayers, teamRole3.MinSlotId, teamRole3.SlotCount, out slot))
		{
			teamId = teamRole3.Team.Id;
			return true;
		}
		return false;
	}

	protected TeamRole GetTeamRole(ActivityTeam team)
	{
		if (team != null)
		{
			TeamRole[] array = teamRoles;
			foreach (TeamRole teamRole in array)
			{
				if (teamRole.Team == team)
				{
					return teamRole;
				}
			}
		}
		return null;
	}

	protected float GetLastSpawnTime(ActivityTeam team, int spawnPointIndex)
	{
		return activityData.GetData(GetKey(team, spawnPointIndex, "LAST_SPAWN_TIME"), 0f);
	}

	protected void SetLastSpawnTime(ActivityTeam team, int spawnPointIndex, float spawnTime)
	{
		activityData.SetData(GetKey(team, spawnPointIndex, "LAST_SPAWN_TIME"), spawnTime);
	}

	protected string GetKey(ActivityTeam team, int spawnPointIndex, string subkey)
	{
		return $"TEAM{team.Id}.SP{spawnPointIndex}.{subkey}";
	}
}
