public class TeleportationPortal : UnityEngine.MonoBehaviour
{
	public Transform Target;

	[SerializeField]
	private bool supportsActivityLoading;

	[SerializeField]
	private string destinationActivity = string.Empty;

	[Tooltip("If the user can teleport with a tool in hand?")]
	public bool CanCarryTools;

	public Renderer HighlightRenderer;

	[SerializeField]
	private Color highlightColor = Color.cyan;

	private Material highlightMaterial;

	private Material defaultMaterial;

	[HideInInspector]
	public Vector3? TargetPositionOverride;

	[HideInInspector]
	public Quaternion? TargetRotationOverride;

	private bool _highlight;

	public bool SupportsActivityLoading => supportsActivityLoading;

	public string DestinationActivity => destinationActivity;

	public string DestinationUserId { get; set; }

	public bool Highlight
	{
		get
		{
			return _highlight;
		}
		set
		{
			if (HighlightRenderer != null && _highlight != value)
			{
				_highlight = value;
				HighlightRenderer.material = ((!_highlight) ? defaultMaterial : highlightMaterial);
			}
		}
	}

	public bool IsValid => base.isActiveAndEnabled && (Target != null || SupportsActivityLoading || TargetPositionOverride.HasValue);

	private void Awake()
	{
		if (HighlightRenderer != null)
		{
			defaultMaterial = HighlightRenderer.material;
			highlightMaterial = new Material(defaultMaterial);
			highlightMaterial.EnableKeyword("_EMISSION");
			highlightMaterial.SetColor("_EmissionColor", highlightColor);
		}
	}

	private void OnDisable()
	{
		if (Highlight)
		{
			Highlight = false;
		}
	}
}
