[DisallowMultipleComponent]
public class PlayerAnalytics : Photon.MonoBehaviour
{
	private string activityName = "lockerroom";

	private Player thisPlayer;

	private bool joinedEmptyActivityTracking;

	private float joinedEmptyActivityTime;

	private bool isLogActivityEnded;

	private float startTime;

	private void Start()
	{
		thisPlayer = GetComponent<Player>();
		if (base.isLocal)
		{
			int roomPlayerCount = PUNNetworkManager.Instance.GetRoomPlayerCount();
			if (PhotonNetwork.inRoom && roomPlayerCount > 1)
			{
				joinedEmptyActivityTracking = true;
				joinedEmptyActivityTime = Time.unscaledTime;
			}
			activityName = ActivityManager.ActivityName;
			AnalyticsHelper.ActivityLoad(activityName, roomPlayerCount);
			startTime = Time.unscaledTime;
			ActivityManager.Instance.GameStateChangedEvent += ActivityManager_GameStateChangedEvent;
			thisPlayer.LeftHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
			thisPlayer.RightHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
		}
	}

	private void OnDestroy()
	{
		if (base.isLocal)
		{
			ProcessJoinedEmptyActivityEnded(anotherPlayerJoined: false, appQuit: false);
			LogActivityEnded();
			if (ActivityManager.Instance != null)
			{
				ActivityManager.Instance.GameStateChangedEvent -= ActivityManager_GameStateChangedEvent;
			}
		}
	}

	private void OnApplicationQuit()
	{
		if (base.isLocal)
		{
			ProcessJoinedEmptyActivityEnded(anotherPlayerJoined: false, appQuit: true);
			LogActivityEnded();
		}
	}

	public void OnPhotonPlayerConnected(PhotonPlayer otherPlayer)
	{
		if (base.isLocal)
		{
			ProcessJoinedEmptyActivityEnded(anotherPlayerJoined: true, appQuit: false);
			AnalyticsHelper.NetworkPhotonPlayerConnected(otherPlayer);
		}
	}

	public void OnPhotonPlayerDisconnected(PhotonPlayer otherPlayer)
	{
		if (base.isLocal)
		{
			AnalyticsHelper.NetworkPhotonPlayerDisconnected(otherPlayer);
		}
	}

	private void OnJoinedRoom()
	{
		if (base.isLocal)
		{
			AnalyticsHelper.NetworkPhotonJoinedRoom();
		}
	}

	private void PlayerHandGestures_GestureDetected(PlayerHand myHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture)
	{
		if (base.isLocal)
		{
			AnalyticsHelper.UserHandGesture(myHand, otherHand, gesture);
		}
	}

	private void ActivityManager_GameStateChangedEvent(ActivityGameState oldState, ActivityGameState newState)
	{
		if (base.isLocal)
		{
			AnalyticsHelper.ActivityStateChange(newState);
		}
	}

	private void ProcessJoinedEmptyActivityEnded(bool anotherPlayerJoined, bool appQuit)
	{
		if (joinedEmptyActivityTracking)
		{
			float duration = Time.unscaledTime - joinedEmptyActivityTime;
			AnalyticsHelper.ActivityJoinedEmpty(duration, anotherPlayerJoined, appQuit);
			joinedEmptyActivityTracking = false;
		}
	}

	private void LogActivityEnded()
	{
		if (!isLogActivityEnded)
		{
			AnalyticsHelper.ActivityUnload(activityName, Time.unscaledTime - startTime);
			if (SingletonMonoBehaviour<PlayerInputManager>.Instance != null)
			{
				SingletonMonoBehaviour<PlayerInputManager>.Instance.PerformanceCounters.LogHistogramsToAnalytics(activityName);
			}
			isLogActivityEnded = true;
		}
	}
}
[DisallowMultipleComponent]
[RequireComponent(typeof(AudioSource))]
public class ActivityAudio : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class GameEventAudio
	{
		public RecRoomAudioClip SFX;

		public RecRoomAudioClip VO;
	}

	[Header("Announcer Voice Over")]
	[SerializeField]
	protected RecRoomAudioClip scoreVO;

	[SerializeField]
	protected RecRoomAudioClip gameOnVO;

	[SerializeField]
	protected RecRoomAudioClip gameOverVO;

	[SerializeField]
	[Header("Notifications")]
	protected RecRoomAudioClip countdownNotification;

	[SerializeField]
	protected RecRoomAudioClip startPlayingActivity;

	[SerializeField]
	protected RecRoomAudioClip scoreSound;

	[SerializeField]
	protected RecRoomAudioClip crowdCheer;

	[SerializeField]
	protected RecRoomAudioClip explosion;

	[SerializeField]
	protected RecRoomAudioClip customTeleport;

	[SerializeField]
	protected RecRoomAudioClip youLose;

	[SerializeField]
	protected RecRoomAudioClip timerExpiring;

	[Header("Music")]
	[SerializeField]
	protected RecRoomAudioClip loopedAmbience;

	[SerializeField]
	protected RecRoomAudioClip gameplayMusic;

	[SerializeField]
	[Header("General Settings")]
	protected AudioSource ambientSource;

	[SerializeField]
	protected AudioSource musicSource;

	[Header("Team Game")]
	[SerializeField]
	private GameEventAudio redTeamJoin;

	[SerializeField]
	private GameEventAudio blueTeamJoin;

	[SerializeField]
	private GameEventAudio gameOver;

	[SerializeField]
	private GameEventAudio redTeamWins;

	[SerializeField]
	private GameEventAudio blueTeamWins;

	[SerializeField]
	private GameEventAudio tieGame;

	[SerializeField]
	private GameEventAudio redTeamScored;

	[SerializeField]
	private GameEventAudio blueTeamScored;

	[SerializeField]
	private GameEventAudio oneMinuteRemaining;

	[SerializeField]
	private GameEventAudio tenSecondsRemaining;

	protected AudioSource timerExpiredAudioSource;

	public RecRoomAudioClip CustomTeleport => customTeleport;

	private void Start()
	{
		if (ambientSource != null && loopedAmbience != null)
		{
			ambientSource.playOnAwake = false;
			ambientSource.volume = loopedAmbience.volume;
			ambientSource.clip = loopedAmbience.audioClip;
			ambientSource.loop = true;
			ambientSource.Play();
		}
		if (musicSource != null && gameplayMusic != null)
		{
			musicSource.playOnAwake = false;
			musicSource.volume = gameplayMusic.volume;
			musicSource.clip = gameplayMusic.audioClip;
			musicSource.loop = true;
		}
	}

	public void OnCountdownNotification()
	{
		PlayClip(countdownNotification);
	}

	protected void OnStartPlayingActivity()
	{
		StartPlayingMusic();
		PlayClip(startPlayingActivity);
	}

	public void StartPlayingMusic()
	{
		if (musicSource != null && !musicSource.isPlaying)
		{
			musicSource.Play();
		}
	}

	public void StopPlayingMusic()
	{
		if (musicSource != null)
		{
			musicSource.Stop();
		}
	}

	protected void StartPlayingTimerExpired()
	{
		StopPlayingTimerExpired();
		timerExpiredAudioSource = AudioManager.Play2DSFX(timerExpiring);
	}

	protected void StopPlayingTimerExpired()
	{
		if (timerExpiredAudioSource != null && timerExpiredAudioSource.gameObject != null)
		{
			UnityEngine.Object.Destroy(timerExpiredAudioSource.gameObject);
		}
	}

	public void OnScore()
	{
		PlayClip(scoreSound);
		PlayClip(crowdCheer);
		PlayClip(explosion);
	}

	public void OnWin()
	{
		PlayClip(crowdCheer);
		StopPlayingMusic();
	}

	public void PlaySound(string sound)
	{
		switch (sound)
		{
		case "game_over":
			PlayClip(gameOverVO);
			break;
		case "out":
			OnScore();
			break;
		case "score":
			OnScore();
			PlayClip(scoreVO);
			break;
		case "game_on":
			PlayClip(gameOnVO);
			break;
		case "start_playing_activity":
			OnStartPlayingActivity();
			break;
		case "stop_music":
			StopPlayingMusic();
			break;
		case "countdown_notification":
			PlayClip(countdownNotification);
			break;
		case "timer_expiring":
			StartPlayingTimerExpired();
			break;
		case "timer_expired":
			StopPlayingTimerExpired();
			break;
		case "you_lose":
			PlayClip(youLose);
			break;
		default:
			UnityEngine.Debug.Log("Unrecognized sound requested!");
			break;
		}
	}

	public void OnBlueTeamJoin()
	{
		PlayGameEventAudio(blueTeamJoin);
	}

	public void OnRedTeamJoin()
	{
		PlayGameEventAudio(redTeamJoin);
	}

	public void OnGameOver()
	{
		PlayGameEventAudio(gameOver);
	}

	public void OnRedTeamWin()
	{
		PlayGameEventAudio(redTeamWins);
	}

	public void OnBlueTeamWin()
	{
		PlayGameEventAudio(blueTeamWins);
	}

	public void OnTieGame()
	{
		PlayGameEventAudio(tieGame);
	}

	public void OnRedTeamScored()
	{
		PlayGameEventAudio(redTeamScored);
	}

	public void OnBlueTeamScored()
	{
		PlayGameEventAudio(blueTeamScored);
	}

	public void OnOneMinuteRemaining()
	{
		PlayGameEventAudio(oneMinuteRemaining);
	}

	public void OnTenSecondsRemaining()
	{
		PlayGameEventAudio(tenSecondsRemaining);
	}

	protected void PlayClip(RecRoomAudioClip clip)
	{
		if (clip != null)
		{
			AudioManager.Play2DSFX(clip);
		}
	}

	protected void PlayGameEventAudio(GameEventAudio eventAudio)
	{
		if (eventAudio.SFX != null)
		{
			PlayClip(eventAudio.SFX);
		}
		if (eventAudio.VO != null)
		{
			PlayClip(eventAudio.VO);
		}
	}

	protected void PlayGameEventAudio3D(GameEventAudio eventAudio, Vector3 position)
	{
		if (eventAudio.SFX != null)
		{
			AudioManager.Play3DSFX(eventAudio.SFX, position);
		}
		if (eventAudio.VO != null)
		{
			PlayClip(eventAudio.VO);
		}
	}
}
[Serializable]
public class RecRoomAudioClip
{
	public AudioClip audioClip;

	[Range(0f, 1f)]
	public float volume = 1f;

	[Range(0f, 2f)]
	public float pitchVariation;
}
[Serializable]
public class AudioRolloff
{
	public bool IsActive;

	public AudioRolloffMode rolloffMode;

	public float minDistance = 2f;

	public float maxDistance = 100f;

	[Tooltip("Only used if the rolloffMode is custom, this is the red volumetric curve.")]
	public AnimationCurve customCurve;

	public void Get(AudioSource audioSource)
	{
		rolloffMode = audioSource.rolloffMode;
		minDistance = audioSource.minDistance;
		maxDistance = audioSource.maxDistance;
		if (rolloffMode == AudioRolloffMode.Custom)
		{
			customCurve = audioSource.GetCustomCurve(AudioSourceCurveType.CustomRolloff);
		}
	}

	public void Set(AudioSource audioSource)
	{
		if (IsActive)
		{
			audioSource.rolloffMode = rolloffMode;
			audioSource.minDistance = minDistance;
			audioSource.maxDistance = maxDistance;
			if (rolloffMode == AudioRolloffMode.Custom)
			{
				audioSource.SetCustomCurve(AudioSourceCurveType.CustomRolloff, customCurve);
			}
		}
	}
}
public class AudioManager : SingletonMonoBehaviour<AudioManager>
{
	private enum SFXType
	{
		_2D,
		_3D
	}

	public enum VOIPFilter
	{
		LowerPitch,
		LowPitch,
		None
	}

	[Header("Global settings")]
	public AudioMixer MasterMixer;

	public AudioMixer SFXMixer;

	[Header("Other")]
	[Tooltip("The SFX volume when someone is talking. dB")]
	[Range(-80f, 20f)]
	public float SFXMixerVolumeLow = -10f;

	[SerializeField]
	private AudioSource sfx3DAudioSourcePrefab;

	[SerializeField]
	private AudioSource sfx2DAudioSourcePrefab;

	[Header("Tool specific audio clips")]
	public RecRoomAudioClip ToolLockedAudio;

	public RecRoomAudioClip ToolUnLockedAudio;

	private static int last2DClipNumber;

	private static int last3DClipNumber;

	private static string MUSIC_VOLUME_PERCENT_PREF = "MUSIC_VOLUME_PERCENT_PREF";

	private float musicMixerVolumeDefault;

	private float currentMusicVolume;

	private float targetMusicVolume;

	private float _musicVolumePercentage = 1f;

	private static string VOICE_VOLUME_PERCENT_PREF = "VOICE_VOLUME_PERCENT_PREF";

	private float voiceMixerVolumeDefault;

	private float currentVoiceVolume;

	private float targetVoiceVolume;

	private float _voiceVolumePercentage = 1f;

	private static string SFX_VOLUME_PERCENT_PREF = "SFX_VOLUME_PERCENT_PREF";

	private float _sfxVolumePercentage = 1f;

	private bool sfxVolumeLowered;

	private float lastSFXVolumeLoweredTime;

	private float sfxMixerVolumeDefault;

	private float currentSFXVolume;

	private float targetSFXVolume;

	private float sfxVolumeInterpolationSpeed = 10f;

	public float MusicVolumePercentage
	{
		get
		{
			return _musicVolumePercentage;
		}
		set
		{
			if (_musicVolumePercentage != value)
			{
				_musicVolumePercentage = value;
				targetMusicVolume = ApplyPercentToDB(musicMixerVolumeDefault, _musicVolumePercentage);
				RecroomPrefs.SetFloat(MUSIC_VOLUME_PERCENT_PREF, _musicVolumePercentage);
			}
		}
	}

	public float VoiceVolumePercentage
	{
		get
		{
			return _voiceVolumePercentage;
		}
		set
		{
			if (_voiceVolumePercentage != value)
			{
				_voiceVolumePercentage = value;
				targetVoiceVolume = ApplyPercentToDB(voiceMixerVolumeDefault, _voiceVolumePercentage);
				RecroomPrefs.SetFloat(VOICE_VOLUME_PERCENT_PREF, _voiceVolumePercentage);
			}
		}
	}

	public float SfxVolumePercentage
	{
		get
		{
			return _sfxVolumePercentage;
		}
		set
		{
			if (_sfxVolumePercentage != value)
			{
				_sfxVolumePercentage = value;
				targetSFXVolume = ApplyPercentToDB((!sfxVolumeLowered) ? sfxMixerVolumeDefault : SFXMixerVolumeLow, SfxVolumePercentage);
				RecroomPrefs.SetFloat(SFX_VOLUME_PERCENT_PREF, _sfxVolumePercentage);
			}
		}
	}

	private void Awake()
	{
		SingletonMonoBehaviour<AudioManager>.Instance = this;
	}

	private void Start()
	{
		if (SFXMixer.GetFloat("MasterVolume", out var value))
		{
			sfxMixerVolumeDefault = (currentSFXVolume = (targetSFXVolume = value));
		}
		if (MasterMixer.GetFloat("MusicVolume", out var value2))
		{
			musicMixerVolumeDefault = (currentMusicVolume = (targetMusicVolume = value2));
		}
		if (MasterMixer.GetFloat("VoiceVolume", out var value3))
		{
			voiceMixerVolumeDefault = (currentVoiceVolume = (targetVoiceVolume = value3));
		}
		MusicVolumePercentage = RecroomPrefs.GetFloat(MUSIC_VOLUME_PERCENT_PREF, 1f);
		SfxVolumePercentage = RecroomPrefs.GetFloat(SFX_VOLUME_PERCENT_PREF, 1f);
		VoiceVolumePercentage = RecroomPrefs.GetFloat(VOICE_VOLUME_PERCENT_PREF, 1f);
	}

	private void Update()
	{
		UpdateSFXVolume();
	}

	public AudioMixerGroup GetVOIPMixerOutput(VOIPFilter filter)
	{
		string subPath = "VOIP_Master";
		switch (filter)
		{
		case VOIPFilter.LowerPitch:
			subPath = "VOIP_LowerPitch";
			break;
		case VOIPFilter.LowPitch:
			subPath = "VOIP_LowPitch";
			break;
		}
		return MasterMixer.FindMatchingGroups(subPath)[0];
	}

	private void UpdateSFXVolume()
	{
		if (PhotonNetwork.connected && PhotonNetwork.otherPlayers != null)
		{
			bool flag = false;
			PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
			foreach (PhotonPlayer photonPlayer in otherPlayers)
			{
				Player player = photonPlayer.TagObject as Player;
				if (player != null && player.IsTalking)
				{
					flag = true;
					lastSFXVolumeLoweredTime = Time.time;
					break;
				}
			}
			if (!sfxVolumeLowered && flag)
			{
				targetSFXVolume = ApplyPercentToDB(SFXMixerVolumeLow, SfxVolumePercentage);
				sfxVolumeLowered = true;
			}
			else if (sfxVolumeLowered && Time.time - lastSFXVolumeLoweredTime > 1f)
			{
				targetSFXVolume = ApplyPercentToDB(sfxMixerVolumeDefault, SfxVolumePercentage);
				sfxVolumeLowered = false;
			}
		}
		if (currentSFXVolume != targetSFXVolume)
		{
			currentSFXVolume = Mathf.SmoothStep(currentSFXVolume, targetSFXVolume, Time.deltaTime * sfxVolumeInterpolationSpeed);
			SFXMixer.SetFloat("MasterVolume", currentSFXVolume);
		}
		if (currentMusicVolume != targetMusicVolume)
		{
			currentMusicVolume = Mathf.SmoothStep(currentMusicVolume, targetMusicVolume, Time.deltaTime * sfxVolumeInterpolationSpeed);
			MasterMixer.SetFloat("MusicVolume", currentMusicVolume);
		}
		if (currentVoiceVolume != targetVoiceVolume)
		{
			currentVoiceVolume = Mathf.SmoothStep(currentVoiceVolume, targetVoiceVolume, Time.deltaTime * sfxVolumeInterpolationSpeed);
			MasterMixer.SetFloat("VoiceVolume", currentVoiceVolume);
		}
	}

	private float ApplyPercentToDB(float volume, float percent)
	{
		float num = volume + 80f;
		return num * Mathf.Log10(percent.ReMapRange(new Vector2(0f, 1f), new Vector2(1f, 10f))) - 80f;
	}

	public static AudioSource Play2DSFX(RecRoomAudioClip clip)
	{
		if (clip == null)
		{
			return null;
		}
		return Play2DSFX(clip.audioClip, SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position, clip.volume, clip.pitchVariation);
	}

	public static AudioSource Play2DSFX(AudioClip clip, Vector3 point, float volume = 1f, float pitchVariation = 0f)
	{
		return PlaySFX(SFXType._2D, clip, point, volume, pitchVariation);
	}

	public static AudioSource Play3DSFX(RecRoomAudioClip clip, Vector3 point)
	{
		if (clip == null)
		{
			return null;
		}
		return Play3DSFX(clip.audioClip, point, clip.volume, clip.pitchVariation);
	}

	public static AudioSource Play3DSFX(RecRoomAudioClip recClip, Transform followTarget)
	{
		if (recClip == null || followTarget == null)
		{
			return null;
		}
		AudioSource audioSource = PlaySFX(SFXType._3D, recClip.audioClip, followTarget.position, recClip.volume, recClip.pitchVariation);
		SFXAudioSource component = audioSource.GetComponent<SFXAudioSource>();
		if (component != null)
		{
			component.FollowTarget = followTarget;
		}
		return audioSource;
	}

	public static AudioSource Play3DSFX(AudioClip clip, Vector3 point, float volume = 1f, float pitchVariation = 0f)
	{
		return PlaySFX(SFXType._3D, clip, point, volume, pitchVariation);
	}

	public static AudioSource PlayRandom2DSFX(RecRoomAudioClip[] clips, Vector3 point, bool allowRepeat = false)
	{
		if (clips == null || clips.Length == 0)
		{
			UnityEngine.Debug.Log("Warning: SFX array is null or empty...");
			return null;
		}
		int num = (last2DClipNumber = GetRandomClipNumber(clips.Length, last2DClipNumber, allowRepeat));
		return PlaySFX(SFXType._2D, clips[num].audioClip, point, clips[num].volume, clips[num].pitchVariation);
	}

	public static AudioSource PlayRandom3DSFX(RecRoomAudioClip[] clips, Vector3 point, bool allowRepeat = false)
	{
		if (clips == null || clips.Length == 0)
		{
			UnityEngine.Debug.Log("Warning: SFX array is null or empty...");
			return null;
		}
		int num = (last3DClipNumber = GetRandomClipNumber(clips.Length, last3DClipNumber, allowRepeat));
		return PlaySFX(SFXType._3D, clips[num].audioClip, point, clips[num].volume, clips[num].pitchVariation);
	}

	private static AudioSource PlaySFX(SFXType type, AudioClip clip, Vector3 point, float volume, float pitchVariation)
	{
		if (clip == null || SingletonMonoBehaviour<AudioManager>.Instance == null)
		{
			return null;
		}
		AudioSource audioSource = null;
		switch (type)
		{
		case SFXType._2D:
			audioSource = UnityEngine.Object.Instantiate(SingletonMonoBehaviour<AudioManager>.Instance.sfx2DAudioSourcePrefab);
			break;
		case SFXType._3D:
			audioSource = UnityEngine.Object.Instantiate(SingletonMonoBehaviour<AudioManager>.Instance.sfx3DAudioSourcePrefab);
			break;
		}
		if (audioSource != null)
		{
			audioSource.transform.parent = SingletonMonoBehaviour<AudioManager>.Instance.transform;
			audioSource.transform.position = point;
			audioSource.clip = clip;
			audioSource.volume = volume;
			if (pitchVariation > 0f)
			{
				audioSource.pitch += UnityEngine.Random.Range(0f - pitchVariation, pitchVariation);
			}
			audioSource.Play();
			UnityEngine.Object.Destroy(audioSource.gameObject, clip.length);
		}
		return audioSource;
	}

	private static int GetRandomClipNumber(int arrayLength, int lastClipNumber, bool allowRepeat)
	{
		if (!allowRepeat && arrayLength == 1)
		{
			UnityEngine.Debug.Log("Warning: trying to disallow repeats when there's only one sound in the array. Sounds will repeat #dealwithit");
			allowRepeat = true;
		}
		int num = UnityEngine.Random.Range(0, arrayLength);
		if (!allowRepeat && num == lastClipNumber)
		{
			num = ++num % arrayLength;
		}
		return num;
	}
}
public class CollisionAudio : UnityEngine.MonoBehaviour
{
	private class CollisionRecord
	{
		public GameObject Collider;

		public float CollisionTime;
	}

	[Serializable]
	public class AudioClipsToLayer
	{
		public string Name;

		public LayerMask Layers;

		public string Tag = string.Empty;

		public AnimationCurve velocityToVolumeCurve;

		public RecRoomAudioClip[] Clips;

		[Tooltip("Per clip cooldown to limit the number of consecutive audios. Set it to 0 for most clips")]
		public float InstanceLimitDuration;

		public float LastInstanceTime { get; set; }

		public bool CanPlay(GameObject go, LayerMask layerMask)
		{
			if ((Time.time <= InstanceLimitDuration || Time.time - LastInstanceTime > InstanceLimitDuration) && (Layers.value & (int)layerMask) == (int)layerMask && (string.IsNullOrEmpty(Tag) || go.CompareTag(Tag)))
			{
				LastInstanceTime = Time.time;
				return true;
			}
			return false;
		}
	}

	private const float MAX_COLLISION_MAGNITUDE = 25f;

	private float cooldown = 0.1f;

	[SerializeField]
	private AudioClipsToLayer[] audioMappings;

	private List<CollisionRecord> collisionHistory = new List<CollisionRecord>();

	private void OnCollisionEnter(Collision collision)
	{
		CollisionRecord collisionRecord = null;
		foreach (CollisionRecord item in collisionHistory)
		{
			if (item.Collider == collision.gameObject)
			{
				collisionRecord = item;
				break;
			}
		}
		bool flag = collisionRecord == null || Time.time - collisionRecord.CollisionTime > cooldown;
		if (collisionRecord == null)
		{
			CollisionRecord collisionRecord2 = new CollisionRecord();
			collisionRecord2.Collider = collision.gameObject;
			collisionRecord2.CollisionTime = Time.time;
			collisionRecord = collisionRecord2;
			collisionHistory.Add(collisionRecord);
		}
		else
		{
			collisionRecord.CollisionTime = Time.time;
		}
		if (!flag || collision.contacts.Length <= 0)
		{
			return;
		}
		int num = 1 << collision.gameObject.layer;
		AudioClipsToLayer[] array = audioMappings;
		foreach (AudioClipsToLayer audioClipsToLayer in array)
		{
			if (audioClipsToLayer.CanPlay(collision.gameObject, num))
			{
				RecRoomAudioClip recRoomAudioClip = audioClipsToLayer.Clips[UnityEngine.Random.Range(0, audioClipsToLayer.Clips.Length)];
				float magnitude = collision.relativeVelocity.magnitude;
				if (audioClipsToLayer.velocityToVolumeCurve != null && audioClipsToLayer.velocityToVolumeCurve.length > 0)
				{
					recRoomAudioClip.volume = audioClipsToLayer.velocityToVolumeCurve.Evaluate(Mathf.Clamp01(magnitude / 25f));
				}
				else
				{
					recRoomAudioClip.volume = Mathf.Clamp01(magnitude / 25f);
				}
				AudioManager.Play3DSFX(recRoomAudioClip, collision.contacts[0].point);
				break;
			}
		}
	}
}
[DisallowMultipleComponent]
