public class ActivitySelectMenuController : MenuController
{
	[SerializeField]
	[Header("Play Game")]
	private Button playButton;

	[SerializeField]
	private Text playButtonText;

	[SerializeField]
	private Button replayButton;

	[SerializeField]
	private Button restartButton;

	[SerializeField]
	private string playButtonDefaultText = string.Empty;

	[Header("Join Game")]
	[SerializeField]
	private Button joinGameButton;

	[SerializeField]
	private Text joinGameButtonText;

	[SerializeField]
	private Button leaveGameButton;

	[SerializeField]
	private string joinGameButtonDefaultText = string.Empty;

	[Header("Teams")]
	[SerializeField]
	private Button switchTeamsButton;

	public override bool Visible
	{
		set
		{
			base.Visible = value;
			if (ActivityManager.Instance != null && base.Owner.isLocal)
			{
				if (value)
				{
					ActivityManager.Instance.PlayerManager.RolesUpdatedEvent += OnRolesUpdated;
					ActivityManager.Instance.GameStateChangedEvent += OnGameStateChanged;
					ActivityManager.Instance.MasterClientChangedEvent += UpdateUI;
				}
				else
				{
					ActivityManager.Instance.PlayerManager.RolesUpdatedEvent -= OnRolesUpdated;
					ActivityManager.Instance.GameStateChangedEvent -= OnGameStateChanged;
					ActivityManager.Instance.MasterClientChangedEvent -= UpdateUI;
				}
			}
		}
	}

	public override void Refresh()
	{
		base.Refresh();
		UpdateUI();
	}

	private void OnGameStateChanged(ActivityGameState previousState, ActivityGameState nextState)
	{
		UpdateUI();
	}

	private void OnRolesUpdated(PhotonPlayer updatedPlayer)
	{
		UnityEngine.Debug.Log("ActivitySelectMenuController OnRolesUpdated : ");
		UpdateUI();
	}

	private void UpdateUI()
	{
		if (!(base.Owner == null) && base.Owner.isLocal)
		{
			if (ActivityManager.Instance == null)
			{
				UnityEngine.Debug.LogError("ActivitySelectMenuController->UpdateUI() has ActivityManager as null");
				return;
			}
			PhotonPlayer[] activePlayersSortedBySlot = ActivityManager.Instance.PlayerManager.GetActivePlayersSortedBySlot();
			int maxActivePlayers = ActivityManager.Instance.PlayerManager.MaxActivePlayers;
			bool flag = ActivityManager.Instance.GameState == ActivityGameState.PreGame;
			ActivityTeam[] allTeams = ActivityManager.Instance.PlayerManager.GetAllTeams();
			bool flag2 = allTeams != null && allTeams.Length > 0;
			bool flag3 = ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player);
			bool flag4 = activePlayersSortedBySlot == null || activePlayersSortedBySlot.Length < maxActivePlayers;
			joinGameButton.gameObject.SetActive(flag3 && flag);
			joinGameButton.interactable = flag4;
			joinGameButtonText.text = ((!flag4) ? "Game Full" : joinGameButtonDefaultText);
			leaveGameButton.gameObject.SetActive(!flag3 && flag);
			switchTeamsButton.gameObject.SetActive(flag2 && flag);
			switchTeamsButton.interactable = !flag3 && ActivityManager.Instance.PlayerManager.CanSwitchTeams(PhotonNetwork.player);
			UpdatePlayButtons();
		}
	}

	private void UpdatePlayButtons()
	{
		if (ActivityManager.Instance != null)
		{
			bool flag = ActivityManager.Instance.GameState == ActivityGameState.PreGame;
			bool supportsPlayingGame = ActivityManager.Instance.SupportsPlayingGame;
			bool flag2 = ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player);
			restartButton.gameObject.SetActive(value: false);
			playButton.gameObject.SetActive(supportsPlayingGame && flag);
			playButton.interactable = ActivityManager.Instance.ReadyToPlay && !flag2;
			playButtonText.text = ((!playButton.interactable && !flag2) ? "Not Enough Players..." : playButtonDefaultText);
			replayButton.gameObject.SetActive(supportsPlayingGame && ActivityManager.Instance.GameState == ActivityGameState.PostGame);
		}
		else
		{
			playButton.gameObject.SetActive(value: false);
			replayButton.gameObject.SetActive(value: false);
		}
	}

	public void ButtonPress_Play()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.PlayActivity();
			UpdateUI();
		}
	}

	public void ButtonPress_Replay()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.ReplayActivity();
			UpdateUI();
		}
	}

	public void ButtonPress_Restart()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.RestartActivity();
			UpdateUI();
		}
	}

	public void ButtonPress_JoinGame()
	{
		if (ActivityManager.Instance != null && ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			ActivityManager.Instance.PlayerManager.RequestAutoAssignRole(PhotonNetwork.player);
			UpdateUI();
		}
	}

	public void ButtonPress_LeaveGame()
	{
		if (ActivityManager.Instance != null && !ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			ActivityManager.Instance.PlayerManager.RequestToVacateRole(PhotonNetwork.player);
			UpdateUI();
		}
	}

	public void ButtonPress_SwitchTeam()
	{
		if (ActivityManager.Instance != null && !ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			ActivityManager.Instance.PlayerManager.RequestAutoAssignRoleOnDifferentTeam(PhotonNetwork.player);
		}
		UpdateUI();
	}
}
