public class MenuController : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Transform visualRoot;

	[SerializeField]
	private RecRoomAudioClip menuVisibleAudio;

	[SerializeField]
	protected MenuController subMenu;

	private bool[] previousButtonInteractability;

	private Button[] buttons;

	private bool _visible;

	public Player Owner { get; set; }

	public virtual bool Visible
	{
		get
		{
			return _visible;
		}
		set
		{
			if (_visible != value)
			{
				_visible = value;
				visualRoot.gameObject.SetActive(_visible);
				if (_visible)
				{
					AudioManager.Play3DSFX(menuVisibleAudio, base.transform.position);
				}
				if (this.VisibleChanged != null)
				{
					this.VisibleChanged(this, _visible);
				}
			}
		}
	}

	public event Action<MenuController, bool> VisibleChanged;

	protected virtual void Awake()
	{
		if (visualRoot == null)
		{
			visualRoot = base.transform;
		}
		visualRoot.gameObject.SetActive(_visible);
		buttons = GetComponentsInChildren<Button>();
		if (buttons != null && buttons.Length > 0)
		{
			previousButtonInteractability = new bool[buttons.Length];
		}
	}

	protected virtual void OnEnable()
	{
		ShowSubMenu(show: false);
	}

	protected virtual void OnDisable()
	{
	}

	public virtual void Refresh()
	{
		if (subMenu != null && subMenu.Visible)
		{
			subMenu.Refresh();
		}
	}

	public void UpdateButtonInteractability()
	{
		if (buttons == null)
		{
			return;
		}
		for (int i = 0; i < buttons.Length; i++)
		{
			if (buttons[i] != null)
			{
				if (!Owner.PlayerUI.Menu.Visible)
				{
					previousButtonInteractability[i] = buttons[i].interactable;
					buttons[i].interactable = false;
				}
				else
				{
					buttons[i].interactable = previousButtonInteractability[i];
				}
			}
		}
	}

	public void Button_HideSelf()
	{
		Visible = false;
	}

	public void Button_HideSubMenu()
	{
		ShowSubMenu(show: false);
	}

	public void Button_ShowSubMenu()
	{
		ShowSubMenu(show: true);
	}

	public bool ShowSubMenu(bool show)
	{
		if (subMenu != null && subMenu.Visible != show)
		{
			subMenu.Visible = show;
			return true;
		}
		return false;
	}
}
