public class PartyMenuController : MenuController
{
	[SerializeField]
	private UIPlayerPanel playerPanelPrefab;

	[SerializeField]
	private RectTransform localPlayerList;

	[SerializeField]
	private RectTransform friendList;

	[SerializeField]
	private RectTransform noPeoplePanel;

	private RemotePlayerMenuController playerSpecificMenu;

	private UIPlayerPanel[] localPlayerPanels;

	private Dictionary<CSteamID, UIPlayerPanel> remoteFriendPanels;

	private Callback<FriendRichPresenceUpdate_t> friendRichPresenceUpdate;

	private Callback<PersonaStateChange_t> personaStateChange;

	private Dictionary<CSteamID, Texture> avatarTextures;

	private bool initialized;

	private void LazyInit()
	{
		if (initialized)
		{
			return;
		}
		playerPanelPrefab.gameObject.SetActive(value: false);
		friendList.gameObject.SetActive(value: false);
		if (base.Owner != null)
		{
			localPlayerPanels = new UIPlayerPanel[7];
			for (int i = 0; i < localPlayerPanels.Length; i++)
			{
				localPlayerPanels[i] = UnityEngine.Object.Instantiate(playerPanelPrefab);
				localPlayerPanels[i].transform.SetParent(localPlayerList, worldPositionStays: false);
			}
			avatarTextures = new Dictionary<CSteamID, Texture>();
			remoteFriendPanels = new Dictionary<CSteamID, UIPlayerPanel>();
			if (SteamManager.Initialized)
			{
				friendRichPresenceUpdate = Callback<FriendRichPresenceUpdate_t>.Create(OnFriendRichPresenceUpdate);
				personaStateChange = Callback<PersonaStateChange_t>.Create(OnPersonaStateChange);
			}
			initialized = true;
		}
		if (subMenu != null)
		{
			playerSpecificMenu = subMenu as RemotePlayerMenuController;
			playerSpecificMenu.PartyMenuController = this;
		}
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		if (base.Owner != null)
		{
			base.Owner.PlayerParty.PartyUpdateReceived += Refresh;
		}
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		if (base.Owner != null)
		{
			base.Owner.PlayerParty.PartyUpdateReceived -= Refresh;
		}
	}

	public override void Refresh()
	{
		base.Refresh();
		if (base.Owner != null)
		{
			LazyInit();
			RefreshLocalSessionPlayers();
			RefreshFriends();
		}
	}

	private void RefreshLocalSessionPlayers()
	{
		int num = 0;
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			Player player = photonPlayer.ToPlayer();
			if (player != null)
			{
				UIPlayerPanel uIPlayerPanel = localPlayerPanels[num];
				num++;
				uIPlayerPanel.gameObject.SetActive(value: true);
				uIPlayerPanel.SetPlayer(player);
				string playerName = player.PlayerName;
				string localPlayerStatus = GetLocalPlayerStatus(player);
				Texture steamUserAvatar = GetSteamUserAvatar(player.SteamID);
				Color? partyColor = ((!player.PlayerParty.IsInParty) ? ((Color?)null) : player.PlayerParty.PartyColor);
				uIPlayerPanel.PlayerName = playerName;
				uIPlayerPanel.PlayerStatus = localPlayerStatus;
				uIPlayerPanel.PlayerAvatar = steamUserAvatar;
				uIPlayerPanel.PartyColor = partyColor;
				if (playerSpecificMenu.Target == player)
				{
					playerSpecificMenu.PlayerName = playerName;
					playerSpecificMenu.PlayerStatus = localPlayerStatus;
					playerSpecificMenu.PlayerAvatar = steamUserAvatar;
					playerSpecificMenu.PartyColor = partyColor;
				}
				RemoveFriendPanel(player.SteamID);
			}
		}
		for (int j = num; j < localPlayerPanels.Length; j++)
		{
			localPlayerPanels[j].gameObject.SetActive(value: false);
		}
		noPeoplePanel.gameObject.SetActive(num == 0);
	}

	private void RefreshFriends()
	{
		if (!SteamManager.Initialized)
		{
			return;
		}
		int friendCount = SteamFriends.GetFriendCount(EFriendFlags.k_EFriendFlagImmediate);
		for (int i = 0; i < friendCount; i++)
		{
			CSteamID friendByIndex = SteamFriends.GetFriendByIndex(i, EFriendFlags.k_EFriendFlagImmediate);
			if (IsInRecRoom(friendByIndex) && !IsInLocalGame(friendByIndex) && !remoteFriendPanels.ContainsKey(friendByIndex))
			{
				AddFriendPanel(friendByIndex);
			}
		}
	}

	private void AddFriendPanel(CSteamID friendId)
	{
		UIPlayerPanel uIPlayerPanel = UnityEngine.Object.Instantiate(playerPanelPrefab);
		uIPlayerPanel.transform.SetParent(friendList, worldPositionStays: false);
		uIPlayerPanel.gameObject.SetActive(value: true);
		uIPlayerPanel.SetFriendSteamId(friendId);
		uIPlayerPanel.PlayerName = GetSteamUserName(friendId);
		uIPlayerPanel.PlayerStatus = GetSteamUserStatus(friendId);
		uIPlayerPanel.PlayerAvatar = GetSteamUserAvatar(friendId);
		uIPlayerPanel.PartyColor = null;
		remoteFriendPanels.Add(friendId, uIPlayerPanel);
		friendList.gameObject.SetActive(value: true);
	}

	private void RemoveFriendPanel(CSteamID friendId)
	{
		if (remoteFriendPanels.ContainsKey(friendId))
		{
			UnityEngine.Object.Destroy(remoteFriendPanels[friendId].gameObject);
			remoteFriendPanels.Remove(friendId);
			friendList.gameObject.SetActive(remoteFriendPanels.Count > 0);
		}
	}

	private string GetLocalPlayerStatus(Player player)
	{
		StringBuilder stringBuilder = new StringBuilder();
		if (PUNNetworkManager.Instance.IsInLockerRoom)
		{
			stringBuilder.Append("In Locker Room with you");
		}
		else
		{
			stringBuilder.AppendFormat("Playing {0} with you", ActivityManager.ActivityName);
		}
		if (player.Ignore)
		{
			stringBuilder.Append(" [IGNORED]");
		}
		else if (player.Mute)
		{
			stringBuilder.Append(" [MUTED]");
		}
		return stringBuilder.ToString();
	}

	private string GetSteamUserName(CSteamID steamId)
	{
		return (!SteamManager.Initialized) ? null : SteamFriends.GetFriendPersonaName(steamId);
	}

	private string GetSteamUserStatus(CSteamID steamId)
	{
		return (!SteamManager.Initialized) ? null : SteamFriends.GetFriendRichPresence(steamId, "status");
	}

	private string GetSteamUserJoinCommand(CSteamID steamId)
	{
		return (!SteamManager.Initialized) ? null : SteamFriends.GetFriendRichPresence(steamId, "connect");
	}

	private Texture GetSteamUserAvatar(CSteamID steamId, bool forceUpdate = false)
	{
		if (SteamManager.Initialized && steamId.IsValid())
		{
			if (!forceUpdate && avatarTextures.ContainsKey(steamId))
			{
				return avatarTextures[steamId];
			}
			if (!SteamFriends.RequestUserInformation(steamId, bRequireNameOnly: false))
			{
				int mediumFriendAvatar = SteamFriends.GetMediumFriendAvatar(steamId);
				if (mediumFriendAvatar != 0 && SteamUtils.GetImageSize(mediumFriendAvatar, out var pnWidth, out var pnHeight) && pnWidth != 0 && pnHeight != 0)
				{
					byte[] array = new byte[pnWidth * pnHeight * 4];
					bool imageRGBA = SteamUtils.GetImageRGBA(mediumFriendAvatar, array, (int)(pnWidth * pnHeight * 4));
					Texture2D texture2D = new Texture2D((int)pnWidth, (int)pnHeight, TextureFormat.RGBA32, mipmap: false, linear: true);
					texture2D.LoadRawTextureData(array);
					texture2D.Apply();
					avatarTextures.Add(steamId, texture2D);
					return texture2D;
				}
			}
		}
		return null;
	}

	private void OnPersonaStateChange(PersonaStateChange_t param)
	{
		CSteamID cSteamID = (CSteamID)param.m_ulSteamID;
		if (!IsInRecRoom(cSteamID) && remoteFriendPanels.ContainsKey(cSteamID))
		{
			RemoveFriendPanel(cSteamID);
			return;
		}
		UIPlayerPanel panelForPlayer = GetPanelForPlayer(cSteamID);
		if (panelForPlayer != null)
		{
			if ((param.m_nChangeFlags & EPersonaChange.k_EPersonaChangeName) != 0)
			{
				string playerName = (panelForPlayer.PlayerName = GetSteamUserName(cSteamID));
				if (playerSpecificMenu.SteamID == cSteamID)
				{
					playerSpecificMenu.PlayerName = playerName;
				}
			}
			if ((param.m_nChangeFlags & EPersonaChange.k_EPersonaChangeAvatar) != 0)
			{
				Texture playerAvatar = (panelForPlayer.PlayerAvatar = GetSteamUserAvatar(cSteamID, forceUpdate: true));
				if (playerSpecificMenu.SteamID == cSteamID)
				{
					playerSpecificMenu.PlayerAvatar = playerAvatar;
				}
			}
		}
		else if (IsInRecRoom(cSteamID) && !IsInLocalGame(cSteamID) && !remoteFriendPanels.ContainsKey(cSteamID) && SteamFriends.GetFriendRelationship(cSteamID) == EFriendRelationship.k_EFriendRelationshipFriend)
		{
			AddFriendPanel(cSteamID);
		}
	}

	private void OnFriendRichPresenceUpdate(FriendRichPresenceUpdate_t param)
	{
		if (remoteFriendPanels.ContainsKey(param.m_steamIDFriend))
		{
			string steamUserStatus = GetSteamUserStatus(param.m_steamIDFriend);
			remoteFriendPanels[param.m_steamIDFriend].PlayerStatus = steamUserStatus;
			if (playerSpecificMenu.SteamID == param.m_steamIDFriend)
			{
				playerSpecificMenu.PlayerStatus = steamUserStatus;
				playerSpecificMenu.JoinGameCommand = GetSteamUserJoinCommand(param.m_steamIDFriend);
			}
		}
	}

	private bool IsInRecRoom(CSteamID friendId)
	{
		FriendGameInfo_t pFriendGameInfo;
		return SteamFriends.GetFriendPersonaState(friendId) != EPersonaState.k_EPersonaStateOffline && SteamFriends.GetFriendGamePlayed(friendId, out pFriendGameInfo) && pFriendGameInfo.m_gameID == (CGameID)SteamManager.RECROOM_APP_ID;
	}

	private bool IsInLocalGame(CSteamID friendID)
	{
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			Player player = photonPlayer.ToPlayer();
			if (player != null && player.SteamID == friendID)
			{
				return true;
			}
		}
		return false;
	}

	private UIPlayerPanel GetPanelForPlayer(CSteamID steamId)
	{
		if (remoteFriendPanels.ContainsKey(steamId))
		{
			return remoteFriendPanels[steamId];
		}
		UIPlayerPanel[] array = localPlayerPanels;
		foreach (UIPlayerPanel uIPlayerPanel in array)
		{
			if (uIPlayerPanel.SteamID == steamId)
			{
				return uIPlayerPanel;
			}
		}
		return null;
	}

	public void ShowPlayerMenu(Player player)
	{
		playerSpecificMenu.InitForPlayer(player);
		playerSpecificMenu.PlayerName = player.PlayerName;
		playerSpecificMenu.PlayerStatus = GetLocalPlayerStatus(player);
		playerSpecificMenu.PlayerAvatar = GetSteamUserAvatar(player.SteamID);
		playerSpecificMenu.PartyColor = ((!player.PlayerParty.IsInParty) ? ((Color?)null) : player.PlayerParty.PartyColor);
		ShowSubMenu(show: true);
	}

	public void ShowFriendMenu(CSteamID steamId)
	{
		playerSpecificMenu.InitForFriend(steamId);
		playerSpecificMenu.PlayerName = GetSteamUserName(steamId);
		playerSpecificMenu.PlayerStatus = GetSteamUserStatus(steamId);
		playerSpecificMenu.PlayerAvatar = GetSteamUserAvatar(steamId);
		playerSpecificMenu.PartyColor = null;
		playerSpecificMenu.JoinGameCommand = GetSteamUserJoinCommand(steamId);
		ShowSubMenu(show: true);
	}
}
public class PlayerFeedbackConfirmationMenuController : ConfirmationMenuController
{
	[Serializable]
	private struct StarButton
	{
		public Button Button;

		public UnityEngine.UI.Image Highlight;
	}

	[SerializeField]
	[Header("Feedback Buttons")]
	private StarButton[] starButtons;

	[SerializeField]
	private Button[] otherButtons;

	[SerializeField]
	private Text thankYouText;

	private Coroutine confirmationFeedbackCoroutine;

	public override bool Visible
	{
		set
		{
			base.Visible = value;
			if (Visible)
			{
				thankYouText.gameObject.SetActive(value: false);
				StarButton[] array = starButtons;
				for (int i = 0; i < array.Length; i++)
				{
					StarButton starButton = array[i];
					starButton.Button.interactable = true;
					starButton.Highlight.gameObject.SetActive(value: false);
				}
				Button[] array2 = otherButtons;
				foreach (Button button in array2)
				{
					button.interactable = true;
				}
			}
			else
			{
				StopFeedbackCoroutine();
			}
		}
	}

	public override void ButtonPress_Value(int value)
	{
		base.ConfirmationValue = value;
		int? confirmationValue = base.ConfirmationValue;
		if (confirmationValue.HasValue && confirmationValue.Value <= 0)
		{
			Visible = false;
		}
		else
		{
			StartCoroutine(ShowConfirmationFeedbackCoroutine());
		}
	}

	private void StopFeedbackCoroutine()
	{
		if (confirmationFeedbackCoroutine != null)
		{
			StopCoroutine(confirmationFeedbackCoroutine);
		}
	}

	private void StartFeedbackCoroutine()
	{
		StopFeedbackCoroutine();
		confirmationFeedbackCoroutine = StartCoroutine(ShowConfirmationFeedbackCoroutine());
	}

	private IEnumerator ShowConfirmationFeedbackCoroutine()
	{
		thankYouText.gameObject.SetActive(value: true);
		int i = 0;
		while (true)
		{
			int? confirmationValue = base.ConfirmationValue;
			if (confirmationValue.HasValue && i < confirmationValue.Value && i < starButtons.Length)
			{
				starButtons[i].Button.interactable = false;
				starButtons[i].Highlight.gameObject.SetActive(value: true);
				i++;
				continue;
			}
			break;
		}
		for (; i < starButtons.Length; i++)
		{
			starButtons[i].Button.interactable = false;
			starButtons[i].Highlight.gameObject.SetActive(value: false);
		}
		Button[] array = otherButtons;
		foreach (Button button in array)
		{
			button.interactable = false;
		}
		yield return new WaitForSeconds(0.25f);
		Visible = false;
	}
}
