		voteToKickButtonDefaultText = voteToKickButtonText.text;
		moderatorKickPlayer.gameObject.SetActive(value: false);
	}

	protected override void OnDisable()
	{
		if (Target != null)
		{
			Target.PlayerData.UnregisterCallback("VoteToKickCount", OnTargetVoteToKickCountChange);
		}
		base.OnDisable();
	}

	public void InitForPlayer(Player targetPlayer)
	{
		isLocalPlayer = true;
		Target = targetPlayer;
		if (Target != null)
		{
			Target.PlayerData.RegisterCallback("VoteToKickCount", OnTargetVoteToKickCountChange);
		}
		SteamID = targetPlayer.SteamID;
		Refresh();
	}

	private void OnTargetVoteToKickCountChange(PlayerData sender, string key)
	{
		Refresh();
	}

	public void InitForFriend(CSteamID friendId)
	{
		isLocalPlayer = false;
		Target = null;
		SteamID = friendId;
		Refresh();
	}

	public void ButtonPress_ToggleMute()
	{
		if (Target != null)
		{
			Target.Mute = !Target.Mute;
			PartyMenuController.Refresh();
		}
	}

	public void ButtonPress_ToggleIgnore()
	{
		if (Target != null)
		{
			ConfirmationMenuController confirmationMenuController = base.Owner.PlayerUI.Menu.ShowConfirmation(((!Target.Ignore) ? "Ignore" : "Unignore") + "'" + Target.PlayerName + "'?", (!Target.Ignore) ? "This user will be invisible to you." : "This user will be visible to you.");
			confirmationMenuController.ConfirmAction += IgnorePlayerConfirmation;
			followCameraVisible = false;
		}
	}

	public void ButtonPress_ToggleFollowCameraMode()
	{
		if (base.Owner != null && (bool)base.Owner.PlayerUI.UIPlayerCamera)
		{
			base.Owner.PlayerUI.UIPlayerCamera.CycleFollowMode();
		}
	}

	private void IgnorePlayerConfirmation(ConfirmationMenuController confirmMenu)
	{
		confirmMenu.ConfirmAction -= IgnorePlayerConfirmation;
		if (confirmMenu.Confirm == true)
		{
			Target.Ignore = !Target.Ignore;
		}
		followCameraVisible = true;
		PartyMenuController.Refresh();
	}

	public void ButtonPress_InviteToParty()
	{
		if (base.Owner.PlayerParty.IsInPartyWith(Target))
		{
			ConfirmationMenuController confirmationMenuController = base.Owner.PlayerUI.Menu.ShowConfirmation("Uninvite '" + Target.PlayerName + "'?", "This user will be removed from your party.");
			confirmationMenuController.ConfirmAction += KickPlayerConfirmation;
			followCameraVisible = false;
		}
		else
		{
			base.Owner.PlayerParty.InvitePlayer(Target);
		}
	}

	private void KickPlayerConfirmation(ConfirmationMenuController confirmMenu)
	{
		confirmMenu.ConfirmAction -= KickPlayerConfirmation;
		if (confirmMenu.Confirm == true)
		{
			PartyMenuController.Owner.PlayerParty.KickPlayer(Target);
		}
		followCameraVisible = true;
		PartyMenuController.Refresh();
	}

	public void ButtonPress_ShowSteamProfile()
	{
		if (SteamManager.Initialized)
		{
			SteamFriends.ActivateGameOverlayToUser("steamid", SteamID);
		}
	}

	public void ButtonPress_JoinGame()
	{
		PUNNetworkManager.Instance.ProcessRichJoinCommand(JoinGameCommand);
	}

	public void ButtonPress_InviteToGame()
	{
		if (SteamManager.Initialized)
		{
			SteamFriends.InviteUserToGame(SteamID, PUNNetworkManager.Instance.RichJoinCommand);
		}
	}

	public void ButtonPress_ModeratorKickPlayer(int durationSeconds)
	{
		if (Target != null)
		{
			Target.PlayerModeration.KickPlayer(durationSeconds);
		}
	}

	public void ButtonPress_VoteToKick()
	{
		if (Target != null)
		{
			Target.PlayerModeration.VoteToKickPlayer(base.Owner);
		}
	}

	public override void Refresh()
	{
		base.Refresh();
		if ((isLocalPlayer && (Target == null || Target.PhotonPlayer == null)) || (!isLocalPlayer && !SteamID.IsValid()))
		{
			Visible = false;
		}
		else if (Target != null)
		{
			localPlayerUI.gameObject.SetActive(value: true);
			remoteFriendUI.gameObject.SetActive(value: false);
			bool flag = base.Owner.PlayerParty.IsInPartyWith(Target);
			inviteButton.gameObject.SetActive(!flag);
			uninviteButton.gameObject.SetActive(flag);
			muteButton.gameObject.SetActive(!Target.Mute);
			unmuteButton.gameObject.SetActive(Target.Mute);
			ignoreButton.gameObject.SetActive(!Target.Ignore);
			unignoreButton.gameObject.SetActive(Target.Ignore);
			localPlayerSteamProfileButton.interactable = SteamID.IsValid();
			voteToKickButton.interactable = !Target.PlayerModeration.IsVotedForKick;
			voteToKickButtonText.text = ((!Target.PlayerModeration.IsVotedForKick) ? voteToKickButtonDefaultText : $"Vote: {Target.PlayerModeration.VoteToKickCount}");
		}
		else
		{
			localPlayerUI.gameObject.SetActive(value: false);
			remoteFriendUI.gameObject.SetActive(value: true);
			inviteToGameButton.interactable = PUNNetworkManager.Instance.IsJoinable();
			friendSteamProfileButton.interactable = SteamID.IsValid();
		}
	}
