public class UIPlayerCamera : UnityEngine.MonoBehaviour
{
	public enum FollowMode
	{
		POV,
		Selfie,
		BirdsEye,
		ThirdPerson
	}

	[SerializeField]
	[Header("Camera")]
	private Transform lensTransform;

	public Vector2 Resolution = new Vector2(1280f, 1080f);

	[SerializeField]
	private float fieldOfView = 60f;

	[SerializeField]
	private float nearClip = 0.05f;

	[SerializeField]
	private float farClip = 100f;

	[SerializeField]
	[Header("Smoothing")]
	private float positionSmoothingTime = 0.05f;

	[Header("Follow")]
	[SerializeField]
	private FollowMode currentFollowMode = FollowMode.Selfie;

	[SerializeField]
	private Texture playerInvisibleTexture;

	[SerializeField]
	private Texture playerIgnoringTexture;

	[SerializeField]
	private Texture emptyTexture;

	private Vector3 velocity = Vector3.zero;

	private Vector3 rotationVelocity = Vector3.zero;

	private float aspect = 1f;

	public Camera Camera { get; private set; }

	public RenderTexture RenderTexture { get; private set; }

	public Player Player { get; private set; }

	public Renderer TargetRenderer { get; private set; }

	public TeleportationPortal PlayerTeleportPortal { get; private set; }

	public Transform UIRoot { get; private set; }

	public bool IsActive => Player != null && Player.IsVisible && TargetRenderer != null && !Player.LocalPlayer.IsInChangingRoom;

	protected void Start()
	{
		aspect = Resolution.x / Resolution.y;
		RenderTexture = new RenderTexture((int)Resolution.x, (int)Resolution.y, 24);
		GameObject gameObject = new GameObject();
		gameObject.name = base.gameObject.name + "_FollowCamera";
		gameObject.tag = "Untagged";
		gameObject.transform.SetParent(base.transform.parent, worldPositionStays: true);
		Camera = gameObject.AddComponent<Camera>();
		Camera.cullingMask = -65537;
		Camera.stereoTargetEye = StereoTargetEyeMask.None;
		Camera.targetTexture = RenderTexture;
		Camera.aspect = aspect;
		Camera.fieldOfView = fieldOfView;
		Camera.nearClipPlane = nearClip;
		Camera.farClipPlane = farClip;
	}

	protected void OnDestroy()
	{
		if (RenderTexture != null)
		{
			UnityEngine.Object.Destroy(RenderTexture);
		}
		if (Camera != null)
		{
			UnityEngine.Object.Destroy(Camera.gameObject);
		}
	}

	private void OnDisable()
	{
		if (Camera != null)
		{
			Camera.enabled = false;
		}
	}

	private void OnEnable()
	{
		if (Camera != null)
		{
			Camera.enabled = true;
			Camera.transform.position = lensTransform.position;
			Camera.transform.rotation = lensTransform.rotation;
		}
	}

	private void Update()
	{
		bool isActive = IsActive;
		Camera.gameObject.SetActive(isActive);
		if (isActive)
		{
			Camera.transform.position = Vector3.SmoothDamp(Camera.transform.position, lensTransform.position, ref velocity, positionSmoothingTime);
			Camera.transform.rotation = UnityExtensions.SmoothDamp(Camera.transform.rotation, lensTransform.rotation, ref rotationVelocity, positionSmoothingTime);
			Transform transform = Player.Head.transform;
			TargetRenderer.material.mainTexture = RenderTexture;
			Vector3 vector = Quaternion.Euler(0f, transform.rotation.eulerAngles.y, 0f) * Vector3.forward;
			if (PlayerTeleportPortal != null)
			{
				PlayerTeleportPortal.TargetPositionOverride = Player.CurrentFloorPosition - vector * UnityEngine.Random.Range(1f, 1.5f);
				PlayerTeleportPortal.TargetRotationOverride = Quaternion.LookRotation(transform.position - PlayerTeleportPortal.TargetPositionOverride.Value);
			}
			switch (currentFollowMode)
			{
			case FollowMode.POV:
				base.transform.position = transform.position + transform.forward * 0.1f;
				base.transform.rotation = transform.rotation;
				break;
			case FollowMode.Selfie:
				base.transform.position = transform.position + vector + Vector3.up * 0.25f;
				base.transform.rotation = Quaternion.LookRotation(transform.position - base.transform.position);
				break;
			case FollowMode.BirdsEye:
				base.transform.position = transform.position + Vector3.up * 5f;
				base.transform.rotation = Quaternion.LookRotation(transform.position - base.transform.position);
				break;
			case FollowMode.ThirdPerson:
				base.transform.position = transform.position - vector + Vector3.up * 0.3f;
				base.transform.rotation = Quaternion.LookRotation(transform.position - base.transform.position);
				break;
			}
		}
		else if (TargetRenderer != null)
		{
			if (Player != null)
			{
				if (Player.Ignore || Player.RemoteIgnored)
				{
					TargetRenderer.material.mainTexture = playerIgnoringTexture;
				}
				else if (!Player.IsVisible || Player.LocalPlayer.IsInChangingRoom)
				{
					TargetRenderer.material.mainTexture = playerInvisibleTexture;
				}
				else
				{
					TargetRenderer.material.mainTexture = emptyTexture;
				}
			}
			else
			{
				TargetRenderer.material.mainTexture = emptyTexture;
			}
		}
		if (PlayerTeleportPortal != null)
		{
			PlayerTeleportPortal.gameObject.SetActive(isActive && !Player.isLocal && ActivityManager.Instance.GameState != ActivityGameState.PlayingGame && ActivityManager.Instance.GameState != ActivityGameState.Countdown);
		}
		if (UIRoot != null)
		{
			UIRoot.gameObject.SetActive(Player != null && Player.IsVisible);
		}
	}

	public void Setup(Player targetPlayer, Renderer targetRenderer = null, TeleportationPortal teleportPortal = null, Transform uiRoot = null)
	{
		Player = targetPlayer;
		TargetRenderer = targetRenderer;
		if (PlayerTeleportPortal != null && PlayerTeleportPortal.Highlight && teleportPortal == null)
		{
			PlayerTeleportPortal.Highlight = false;
		}
		PlayerTeleportPortal = teleportPortal;
		UIRoot = uiRoot;
	}

	public void CycleFollowMode()
	{
		currentFollowMode = (FollowMode)((int)(currentFollowMode + 1) % Enum.GetNames(typeof(FollowMode)).Length);
	}
}
public class UIPlayerPanel : Selectable
{
	[SerializeField]
	private PartyMenuController partyMenuController;

	[SerializeField]
	[Header("Player specific")]
	private RawImage avatar;

	[SerializeField]
	private UnityEngine.UI.Image partyColorImage;

	[SerializeField]
	private Text playerNameText;

	[SerializeField]
	private Text playerStatusText;

	[Header("Audio")]
	[SerializeField]
	private UnityEngine.UI.Image speakingIndicator;

	[SerializeField]
	private UnityEngine.UI.Image muteIndicator;

	[Range(0f, 1f)]
	[SerializeField]
	private float speakingColorAlpha = 0.9f;

	[Range(0f, 1f)]
	[SerializeField]
	private float notSpeakingColorAlpha = 0.1f;

	private float speakingColorFadeSpeed = 15f;

	private Player player;

	private int pointerCount;

	public CSteamID SteamID { get; private set; }

	public string PlayerName
	{
		get
		{
			return playerNameText.text;
		}
		set
		{
			playerNameText.text = value;
		}
	}

	public string PlayerStatus
	{
		get
		{
			return playerStatusText.text;
		}
		set
		{
			playerStatusText.text = value;
		}
	}

	public Texture PlayerAvatar
	{
		get
		{
			return avatar.texture;
		}
		set
		{
			avatar.texture = value;
			avatar.gameObject.SetActive(value != null);
		}
	}

	public Color? PartyColor
	{
		get
		{
			return (!partyColorImage.gameObject.activeSelf) ? ((Color?)null) : new Color?(partyColorImage.color);
		}
		set
		{
			partyColorImage.gameObject.SetActive(value.HasValue);
			if (value.HasValue)
			{
				partyColorImage.color = value.Value;
			}
		}
	}

	public void SetFriendSteamId(CSteamID steamId)
	{
		player = null;
		SteamID = steamId;
	}

