public class CameraRig : SingletonMonoBehaviour<CameraRig>
{
	[SerializeField]
	private GameObject blindQuad;

	[SerializeField]
	private Camera cameraIO;

	[SerializeField]
	private ControllerIO leftHandControllerIO;

	[SerializeField]
	private ControllerIO rightHandControllerIO;

	[SerializeField]
	private HeadGestureDetect headGestureDetect;

	private Texture defaultTonemappingLUT;

	public Camera CameraIO => cameraIO;

	public ControllerIO LeftHandControllerIO => leftHandControllerIO;

	public ControllerIO RightHandControllerIO => rightHandControllerIO;

	public HeadGestureDetect HeadGestureDetect => headGestureDetect;

	public bool Blind
	{
		get
		{
			return blindQuad.activeSelf;
		}
		set
		{
			blindQuad.SetActive(value);
		}
	}

	public Vector3 CameraFloorOffsetLocalSpace
	{
		get
		{
			Vector3 vector = CameraIO.transform.position - base.transform.position;
			Vector3 vector2 = Vector3.ProjectOnPlane(vector, Vector3.up);
			return base.transform.InverseTransformVector(vector2);
		}
	}

	private void Awake()
	{
		SingletonMonoBehaviour<CameraRig>.Instance = this;
	}

	private void Start()
	{
		TonemappingColorGrading component = CameraIO.GetComponent<TonemappingColorGrading>();
		if (component != null)
		{
			defaultTonemappingLUT = component.lut.texture;
		}
	}

	public void SwapHands()
	{
		ControllerIO controllerIO = leftHandControllerIO;
		leftHandControllerIO = rightHandControllerIO;
		rightHandControllerIO = controllerIO;
		if (Player.LocalPlayer != null)
		{
			Player.LocalPlayer.SetupControllerIOForHands();
		}
	}

	public void SetTonemappingLUT(Texture lutTexture)
	{
		if (lutTexture == null)
		{
			lutTexture = defaultTonemappingLUT;
		}
		TonemappingColorGrading[] array = UnityEngine.Object.FindObjectsOfType<TonemappingColorGrading>();
		foreach (TonemappingColorGrading tonemappingColorGrading in array)
		{
			TonemappingColorGrading.LUTSettings lut = tonemappingColorGrading.lut;
			lut.texture = lutTexture;
			tonemappingColorGrading.lut = lut;
		}
	}
}
public class ControllerIO : UnityEngine.MonoBehaviour
{
	public enum HandType
	{
		LeftHand,
		RightHand
	}

	private enum InputMode
	{
		Debug,
		SteamVR,
		Oculus
	}

	[SerializeField]
	private HandType hand;

	[SerializeField]
	[Header("Editor Debug Settings")]
	private Vector3 debugCameraOffset;

	[SerializeField]
	private Vector3 debugCameraRotationOffset;

	[SerializeField]
	private int debugTriggerMouseButton;

	[SerializeField]
	private KeyCode debugMenuKey;

	[SerializeField]
	private KeyCode debugTeleportKey;

	[SerializeField]
	private KeyCode debugPushToTalkKey;

	[Header("SteamVR Settings")]
	[SerializeField]
	private EVRButtonId steamVrTriggerButton = EVRButtonId.k_EButton_Axis1;

	[SerializeField]
	private EVRButtonId steamVrMenuButton = EVRButtonId.k_EButton_ApplicationMenu;

	[SerializeField]
	private EVRButtonId steamVrTeleportButton = EVRButtonId.k_EButton_Axis0;

	[SerializeField]
	private EVRButtonId steamVrPushToTalkButton = EVRButtonId.k_EButton_Grip;

	[SerializeField]
	private EVRButtonId steamVrJoystickAxis = EVRButtonId.k_EButton_Axis0;

	[Header("OVR Settings")]
	[SerializeField]
	private OVRInput.Axis1D ovrTriggerAxis = OVRInput.Axis1D.PrimaryIndexTrigger;

	[SerializeField]
	private OVRInput.Button ovrTriggerButton = OVRInput.Button.PrimaryIndexTrigger;

	[SerializeField]
	private OVRInput.Button ovrMenuButton = OVRInput.Button.One;

	[SerializeField]
	private OVRInput.Button ovrTeleportButton = OVRInput.Button.PrimaryThumbstick;

	[SerializeField]
	private OVRInput.Button ovrPushToTalkButton = OVRInput.Button.PrimaryHandTrigger;

	[SerializeField]
	private OVRInput.Axis2D ovrJoystickAxis = OVRInput.Axis2D.PrimaryThumbstick;

	private bool hairTriggerButtonDown;

	private bool hairTriggerButtonUp;

	private uint steamVrDeviceIndex = uint.MaxValue;

	public HandType Hand => hand;

	public bool MenuButtonPressed { get; private set; }

	public bool MenuButtonDown { get; private set; }

	public bool MenuButtonUp { get; private set; }

	public bool TeleportButtonPressed { get; private set; }

	public bool TeleportButtonDown { get; private set; }

	public bool TeleportButtonUp { get; private set; }

	public bool PushToTalkButtonPressed { get; private set; }

	public bool PushToTalkButtonDown { get; private set; }

	public bool PushToTalkButtonUp { get; private set; }

	public Vector2 JoystickAxis { get; private set; }

	public float TriggerAxis { get; private set; }

	public bool TriggerButtonPressed { get; private set; }

	public bool TriggerButtonDown { get; private set; }

	public bool TriggerButtonUp { get; private set; }

	public bool HairTriggerButtonDownConsumed { get; set; }

	public bool HairTriggerButtonUpConsumed { get; set; }

	public bool HairTriggerButtonPressed { get; private set; }

	public bool HairTriggerButtonDown
	{
		get
		{
			return hairTriggerButtonDown;
		}
		private set
		{
			hairTriggerButtonDown = value;
			if (hairTriggerButtonDown)
			{
				HairTriggerButtonDownTime = Time.time;
				HairTriggerButtonDownConsumed = false;
			}
		}
	}

	public bool HairTriggerButtonUp
	{
		get
		{
			return hairTriggerButtonUp && !HairTriggerButtonUpConsumed;
		}
		private set
		{
			hairTriggerButtonUp = value;
			if (hairTriggerButtonUp)
			{
				HairTriggerButtonUpTime = Time.time;
				HairTriggerButtonUpConsumed = false;
			}
		}
	}

	public float HairTriggerButtonDownTime { get; private set; }

	public float HairTriggerButtonUpTime { get; private set; }

	public bool IsConnected { get; private set; }

	public bool IsTracking { get; private set; }

	public bool ModelVisible { get; set; }

	public Vector3? UIRaycastPosition { get; set; }

	public bool UISelectable { get; set; }

	public bool UIInteractionEnabled { get; set; }

	private InputMode inputMode => InputMode.SteamVR;

	public event Action TransformUpdated;

	private void Start()
	{
		if (inputMode == InputMode.SteamVR)
		{
			SteamVR_Utils.Event.Listen("new_poses", OnNewSteamVrPoses);
		}
	}

	private void OnDestroy()
	{
		if (inputMode == InputMode.SteamVR)
		{
			SteamVR_Utils.Event.Remove("new_poses", OnNewSteamVrPoses);
		}
	}

	private void Update()
	{
		switch (inputMode)
		{
		case InputMode.Debug:
			UpdateInputStateForEditor();
			break;
		case InputMode.SteamVR:
			UpdateInputStateForSteamVR();
			break;
		case InputMode.Oculus:
			UpdateInputStateForOculus();
			break;
		}
	}

	private void UpdateInputStateForEditor()
	{
		IsTracking = true;
		IsConnected = true;
		base.transform.position = Camera.main.transform.position + Camera.main.transform.TransformVector(debugCameraOffset);
		base.transform.rotation = Camera.main.transform.rotation * Quaternion.Euler(debugCameraRotationOffset);
		if (this.TransformUpdated != null)
		{
			this.TransformUpdated();
		}
		MenuButtonPressed = Input.GetKey(debugMenuKey);
		MenuButtonDown = Input.GetKeyDown(debugMenuKey);
		MenuButtonUp = Input.GetKeyUp(debugMenuKey);
		TeleportButtonPressed = Input.GetKey(debugTeleportKey);
		TeleportButtonDown = Input.GetKeyDown(debugTeleportKey);
		TeleportButtonUp = Input.GetKeyUp(debugTeleportKey);
		PushToTalkButtonPressed = Input.GetKey(debugPushToTalkKey);
		PushToTalkButtonDown = Input.GetKeyDown(debugPushToTalkKey);
		PushToTalkButtonUp = Input.GetKeyUp(debugPushToTalkKey);
		TriggerAxis = ((!Input.GetMouseButton(debugTriggerMouseButton)) ? 0f : 1f);
		TriggerButtonPressed = Input.GetMouseButton(debugTriggerMouseButton);
		TriggerButtonDown = Input.GetMouseButtonDown(debugTriggerMouseButton);
		TriggerButtonUp = Input.GetMouseButtonUp(debugTriggerMouseButton);
		HairTriggerButtonPressed = Input.GetMouseButton(debugTriggerMouseButton);
		HairTriggerButtonDown = Input.GetMouseButtonDown(debugTriggerMouseButton);
		HairTriggerButtonUp = Input.GetMouseButtonUp(debugTriggerMouseButton);
	}

	private void UpdateInputStateForSteamVR()
	{
		if (IsConnected)
		{
			SteamVR_Controller.Device device = SteamVR_Controller.Input((int)steamVrDeviceIndex);
			MenuButtonPressed = device.GetPress(steamVrMenuButton);
			MenuButtonDown = device.GetPressDown(steamVrMenuButton);
			MenuButtonUp = device.GetPressUp(steamVrMenuButton);
			TeleportButtonPressed = device.GetPress(steamVrTeleportButton);
			TeleportButtonDown = device.GetPressDown(steamVrTeleportButton);
			TeleportButtonUp = device.GetPressUp(steamVrTeleportButton);
			PushToTalkButtonPressed = device.GetPress(steamVrPushToTalkButton);
			PushToTalkButtonDown = device.GetPressDown(steamVrPushToTalkButton);
			PushToTalkButtonUp = device.GetPressUp(steamVrPushToTalkButton);
			JoystickAxis = device.GetAxis(steamVrJoystickAxis);
			TriggerAxis = device.GetAxis(steamVrTriggerButton).x;
			TriggerButtonPressed = device.GetPress(steamVrTriggerButton);
			TriggerButtonDown = device.GetPressDown(steamVrTriggerButton);
			TriggerButtonUp = device.GetPressUp(steamVrTriggerButton);
			HairTriggerButtonPressed = device.GetHairTrigger();
			HairTriggerButtonDown = device.GetHairTriggerDown();
			HairTriggerButtonUp = device.GetHairTriggerUp();
		}
	}

	private void UpdateInputStateForOculus()
	{
		OVRInput.Controller controller = ((hand == HandType.LeftHand) ? OVRInput.Controller.LTouch : OVRInput.Controller.RTouch);
		OVRPlugin.Node nodeId = ((hand != HandType.LeftHand) ? OVRPlugin.Node.HandRight : OVRPlugin.Node.HandLeft);
		IsConnected = OVRPlugin.GetNodePresent(nodeId);
		if (!IsConnected)
		{
			IsTracking = false;
		}
		else
		{
			IsTracking = OVRInput.GetControllerPositionTracked(controller) && OVRInput.GetControllerOrientationTracked(controller);
			if (IsTracking)
			{
				OVRPose oVRPose = OVRPlugin.GetNodePose(nodeId).ToOVRPose();
				base.transform.localPosition = oVRPose.position;
				base.transform.localRotation = oVRPose.orientation;
				if (this.TransformUpdated != null)
				{
					this.TransformUpdated();
				}
			}
		}
		if (IsConnected)
		{
			MenuButtonPressed = OVRInput.Get(ovrMenuButton, controller);
			MenuButtonDown = OVRInput.GetDown(ovrMenuButton, controller);
			MenuButtonUp = OVRInput.GetUp(ovrMenuButton, controller);
			TeleportButtonPressed = OVRInput.Get(ovrTeleportButton, controller);
			TeleportButtonDown = OVRInput.GetDown(ovrTeleportButton, controller);
			TeleportButtonUp = OVRInput.GetUp(ovrTeleportButton, controller);
			PushToTalkButtonPressed = OVRInput.GetDown(ovrPushToTalkButton, controller);
			PushToTalkButtonDown = OVRInput.GetDown(ovrPushToTalkButton, controller);
			PushToTalkButtonUp = OVRInput.GetUp(ovrPushToTalkButton, controller);
			JoystickAxis = OVRInput.Get(ovrJoystickAxis, controller);
			TriggerAxis = OVRInput.Get(ovrTriggerAxis, controller);
			TriggerButtonPressed = OVRInput.Get(ovrTriggerButton, controller);
			TriggerButtonDown = OVRInput.GetDown(ovrTriggerButton, controller);
			TriggerButtonUp = OVRInput.GetUp(ovrTriggerButton, controller);
			HairTriggerButtonPressed = OVRInput.Get(ovrTriggerButton, controller);
			HairTriggerButtonDown = OVRInput.GetDown(ovrTriggerButton, controller);
			HairTriggerButtonUp = OVRInput.GetUp(ovrTriggerButton, controller);
		}
	}

	private void OnNewSteamVrPoses(params object[] args)
	{
		TrackedDevicePose_t[] array = (TrackedDevicePose_t[])args[0];
		ETrackedControllerRole unDeviceType = ((hand == HandType.LeftHand) ? ETrackedControllerRole.LeftHand : ETrackedControllerRole.RightHand);
		steamVrDeviceIndex = (uint)(((int?)OpenVR.System?.GetTrackedDeviceIndexForControllerRole(unDeviceType)) ?? (-1));
		if (steamVrDeviceIndex >= array.Length)
		{
			IsConnected = false;
			IsTracking = false;
			return;
		}
		IsConnected = array[steamVrDeviceIndex].bDeviceIsConnected;
		IsTracking = array[steamVrDeviceIndex].bPoseIsValid;
		if (IsConnected && IsTracking)
		{
			SteamVR_Utils.RigidTransform rigidTransform = new SteamVR_Utils.RigidTransform(array[steamVrDeviceIndex].mDeviceToAbsoluteTracking);
			base.transform.localPosition = rigidTransform.pos;
			base.transform.localRotation = rigidTransform.rot;
			if (this.TransformUpdated != null)
			{
				this.TransformUpdated();
			}
		}
	}

	public void Vibrate(ushort durationMicroseconds = 1000)
	{
		switch (inputMode)
		{
		case InputMode.Debug:
			break;
		case InputMode.SteamVR:
			if (IsConnected)
			{
				SteamVR_Controller.Device device = SteamVR_Controller.Input((int)steamVrDeviceIndex);
				device.TriggerHapticPulse(durationMicroseconds);
			}
			break;
		case InputMode.Oculus:
			break;
		}
	}
}
public class DebugCameraControl : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private KeyCode exitKey = KeyCode.Escape;

	[SerializeField]
	private float yawSpeed = 360f;

	[SerializeField]
	private float pitchSpeed = 180f;

	[SerializeField]
	private float rollSpeed = 180f;

	[SerializeField]
	private float movementSpeed = 6f;

	[SerializeField]
	private float upDownSpeed = 6f;

	private bool GameViewFocused
	{
		get
		{
			return !Cursor.visible;
		}
		set
		{
			Cursor.lockState = (value ? CursorLockMode.Locked : CursorLockMode.None);
			Cursor.visible = !value;
		}
	}

	private void Awake()
	{
		if (false)
		{
			GameViewFocused = false;
		}
		else
		{
			UnityEngine.Object.Destroy(this);
		}
	}

	private void Update()
	{
		if (GameViewFocused)
		{
			Transform transform = Camera.main.transform;
			Vector3 vector = ReadMovementInput();
			Vector3 vector2 = transform.right * vector.x + transform.forward * vector.z;
			vector2 = Vector3.ProjectOnPlane(Vector3.ClampMagnitude(vector2, 1f), Vector3.up) * movementSpeed;
			vector2 += Vector3.up * vector.y * upDownSpeed;
			transform.position += vector2 * Time.deltaTime;
			Vector3 vector3 = ReadLookInput();
			float yAngle = vector3.y * yawSpeed * Time.deltaTime;
			transform.Rotate(0f, yAngle, 0f, Space.World);
			float xAngle = (0f - vector3.x) * pitchSpeed * Time.deltaTime;
			transform.Rotate(xAngle, 0f, 0f, Space.Self);
			float zAngle = (0f - vector3.z) * rollSpeed * Time.deltaTime;
			transform.Rotate(0f, 0f, zAngle, Space.Self);
			if (Input.GetKeyDown(exitKey))
			{
				GameViewFocused = false;
			}
		}
		else if (Input.GetMouseButton(0) || Input.GetMouseButton(1))
		{
			StartCoroutine(DelayedSetGameViewFocused(value: true));
		}
	}

	private IEnumerator DelayedSetGameViewFocused(bool value)
	{
		yield return new WaitForSeconds(0.1f);
		GameViewFocused = value;
	}

	private Vector3 ReadMovementInput()
	{
		return new Vector3(Input.GetAxis("Movement Right"), Input.GetAxis("Movement Up"), Input.GetAxis("Movement Forward"));
	}

	private Vector3 ReadLookInput()
	{
		return new Vector3(Input.GetAxis("Camera Pitch"), Input.GetAxis("Camera Yaw"), 0f);
	}
}
public class FlushOnPostRender : UnityEngine.MonoBehaviour
{
	private static int s_numFlushesThisFrame;

	private static int s_lastFrameCount;

	private void OnPostRender()
	{
		if (OpenVR.Compositor != null)
		{
			Compositor_FrameTiming pTiming = new Compositor_FrameTiming
			{
				m_nSize = (uint)Marshal.SizeOf(typeof(Compositor_FrameTiming))
			};
			OpenVR.Compositor.GetFrameTiming(ref pTiming, 0u);
			if (pTiming.m_nNumFramePresents > 1)
			{
				return;
			}
		}
		if (s_lastFrameCount != Time.frameCount)
		{
			s_lastFrameCount = Time.frameCount;
			s_numFlushesThisFrame = 0;
		}
		if (++s_numFlushesThisFrame <= 3)
		{
			GL.Flush();
		}
	}
}
public class BezierPath
{
	private const int TOTAL_POINTS_PER_BEZIER_CURVE = 4;

	private const int UNIQUE_POINTS_PER_BEZIER_CURVE = 3;

	private const int LENGTH_SEGMENTS = 5;

	private const float LENGTH_SEGMENT_FRACTION = 0.2f;

	private List<Vector3> points;

	private List<float> lengthAtCurve;

	public int CurveCount { get; private set; }

	public float PathLength { get; private set; }

	public BezierPath()
	{
		points = new List<Vector3>();
		lengthAtCurve = new List<float>();
		CurveCount = 0;
		PathLength = 0f;
	}

	public void AddCurve(Vector3 start, Vector3 controlPoint1, Vector3 controlPoint2, Vector3 end)
	{
		if (points.Count == 0)
		{
			points.Add(start);
		}
		else if (Vector3.Distance(start, points[points.Count - 1]) > Mathf.Epsilon)
		{
			UnityEngine.Debug.LogError("Tried to add discontinuity to Bezier Path.");
		}
		AddCurve(controlPoint1, controlPoint2, end);
	}

	public void AddCurve(Vector3 controlPoint1, Vector3 controlPoint2, Vector3 end)
	{
		if (points.Count == 0)
		{
			UnityEngine.Debug.LogError("Tried to add a Bezier Path curve without a starting point.");
		}
		points.Add(controlPoint1);
		points.Add(controlPoint2);
		points.Add(end);
		CurveCount++;
		PathLength += CurveLength(CurveCount - 1);
		lengthAtCurve.Add(PathLength);
	}

	public void Clear()
	{
		points.Clear();
		lengthAtCurve.Clear();
		CurveCount = 0;
		PathLength = 0f;
	}

	public Vector3 EvaluatePath(float t)
	{
		if (CurveCount <= 0)
		{
			return Vector3.zero;
		}
		int num = -1;
		float t2 = 0f;
		float num2 = Mathf.Clamp01(t) * PathLength;
		for (int i = 0; i < CurveCount; i++)
		{
			if (num2 <= lengthAtCurve[i])
			{
				num = i;
				float num3 = ((i != 0) ? lengthAtCurve[i - 1] : 0f);
				float num4 = lengthAtCurve[i] - num3;
				t2 = (num2 - num3) / num4;
				break;
			}
		}
		if (num < 0)
		{
			num = CurveCount - 1;
			t2 = 1f;
		}
		return EvaluateBezierCurve(num, t2);
	}

	public void DrawGizmos()
	{
		for (int i = 0; i < CurveCount; i++)
		{
			DrawGizmosBezierCurve(i);
		}
	}

	private Vector3 EvaluateBezierCurve(int curveIndex, float t)
	{
		Vector3 vector = points[curveIndex * 3];
		Vector3 vector2 = points[curveIndex * 3 + 1];
		Vector3 vector3 = points[curveIndex * 3 + 2];
		Vector3 vector4 = points[curveIndex * 3 + 3];
		float num = 1f - t;
		return vector * num * num * num + vector2 * 3f * num * num * t + vector3 * 3f * num * t * t + vector4 * t * t * t;
	}

	private float CurveLength(int curveIndex)
	{
		float num = 0f;
		float num2 = 0f;
		Vector3 vector = EvaluateBezierCurve(curveIndex, num2);
		for (int i = 0; i < 5; i++)
		{
			num2 += 0.2f;
			Vector3 vector2 = EvaluateBezierCurve(curveIndex, num2);
			num += (vector2 - vector).magnitude;
			vector = vector2;
		}
		return num;
	}

	private void DrawGizmosBezierCurve(int curveIndex)
	{
		Vector3 vector = points[curveIndex * 3];
		Vector3 to = points[curveIndex * 3 + 1];
		Vector3 vector2 = points[curveIndex * 3 + 2];
		Vector3 to2 = points[curveIndex * 3 + 3];
		Gizmos.color = Color.white;
		Gizmos.DrawLine(vector, to);
		Gizmos.DrawLine(vector2, to2);
		Gizmos.color = Color.blue;
		Gizmos.DrawLine(vector, to2);
	}
}
public class NetworkedGameObjectPool : PunBehaviour
{
	[SerializeField]
	private GameObject[] pool;

	private Dictionary<GameObject, float> lastAcquiredTimestamps = new Dictionary<GameObject, float>();

	private GameObject[] lruPool;

	public GameObject[] Pool => pool;

	public GameObject[] LRUPool => lruPool;

	public int Capacity => pool.Length;

	public int Availability
	{
		get
		{
			int num = 0;
			for (int i = 0; i < pool.Length; i++)
			{
				if (!pool[i].activeSelf)
				{
					num++;
				}
			}
			return num;
		}
	}

	private void Awake()
	{
		lruPool = new GameObject[pool.Length];
		Array.Copy(pool, lruPool, pool.Length);
		GameObject[] array = pool;
		foreach (GameObject key in array)
		{
			lastAcquiredTimestamps.Add(key, 0f);
		}
	}

	private void Start()
	{
		GameObject[] array = pool;
		foreach (GameObject gameObject in array)
		{
			gameObject.SetActive(value: false);
		}
	}

	public GameObject Acquire(Vector3 position, Quaternion rotation)
	{
		if (!base.hasAuthority)
		{
			return null;
		}
		for (int i = 0; i < LRUPool.Length; i++)
		{
			if (!LRUPool[i].activeSelf)
			{
				int index = GetIndex(LRUPool[i]);
				return Acquire(index, position, rotation);
			}
		}
		return null;
	}

	public GameObject Acquire(int index, Vector3 position, Quaternion rotation)
	{
		if (base.hasAuthority && index < pool.Length && !pool[index].activeSelf)
		{
			TryTransferOwnershipToMasterClient(pool[index]);
			EnablePoolObject(index, enable: true, position, rotation);
			return pool[index];
		}
		return null;
	}

	public void Release(GameObject pooledObject)
	{
		if (!base.hasAuthority)
		{
			return;
		}
		for (int i = 0; i < pool.Length; i++)
		{
			if (pool[i] == pooledObject)
			{
				TryTransferOwnershipToMasterClient(pool[i]);
				EnablePoolObject(i, enable: false, Vector3.zero, Quaternion.identity);
				break;
			}
		}
	}

	public void MasterDisableAll()
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		for (int i = 0; i < pool.Length; i++)
		{
			if (pool[i].activeSelf)
			{
				base.photonView.RPC("RpcEnablePoolObject", PhotonTargets.All, i, false, pool[i].transform.position, pool[i].transform.rotation, PhotonNetwork.time);
			}
		}
	}

	private int GetIndex(GameObject go)
	{
		for (int i = 0; i < pool.Length; i++)
		{
			if (pool[i] == go)
			{
				return i;
			}
		}
		return -1;
	}

	private void EnablePoolObject(int index, bool enable, Vector3 position, Quaternion rotation)
	{
		base.photonView.RPC("RpcEnablePoolObject", PhotonTargets.All, index, enable, position, rotation, PhotonNetwork.time);
	}

	[PunRPC]
	public void RpcEnablePoolObject(int index, bool enable, Vector3 position, Quaternion rotation, double networkTimestamp)
	{
		if (!enable)
		{
			pool[index].SetActive(enable);
		}
		pool[index].transform.position = position;
		pool[index].transform.rotation = rotation;
		if (enable)
		{
			pool[index].SetActive(enable);
			float value = (float)networkTimestamp;
			lastAcquiredTimestamps[pool[index]] = value;
			Array.Copy(pool, lruPool, pool.Length);
			Array.Sort(lruPool, (GameObject a, GameObject b) => lastAcquiredTimestamps[a].CompareTo(lastAcquiredTimestamps[b]));
		}
		PUNNetworkTransform[] componentsInChildren = pool[index].GetComponentsInChildren<PUNNetworkTransform>(includeInactive: true);
		PUNNetworkTransform[] array = componentsInChildren;
		foreach (PUNNetworkTransform pUNNetworkTransform in array)
		{
			pUNNetworkTransform.Snap(pUNNetworkTransform.transform.position, pUNNetworkTransform.transform.rotation, networkTimestamp);
		}
	}

	[PunRPC]
	public void RpcInitializePool(bool[] poolObjectsEnabled, Vector3[] poolObjectPositions, Quaternion[] poolObjectRotations, float[] poolLastAcquiredTimestamps)
	{
		for (int i = 0; i < poolObjectsEnabled.Length; i++)
		{
			pool[i].SetActive(poolObjectsEnabled[i]);
			pool[i].transform.position = poolObjectPositions[i];
			pool[i].transform.rotation = poolObjectRotations[i];
			lastAcquiredTimestamps[pool[i]] = poolLastAcquiredTimestamps[i];
		}
	}

	public override void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		base.OnPhotonPlayerConnected(newPlayer);
		if (base.hasAuthority)
		{
			bool[] array = new bool[pool.Length];
			Vector3[] array2 = new Vector3[pool.Length];
			Quaternion[] array3 = new Quaternion[pool.Length];
			float[] array4 = new float[pool.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = pool[i].activeSelf;
				ref Vector3 reference = ref array2[i];
				reference = pool[i].transform.position;
				ref Quaternion reference2 = ref array3[i];
				reference2 = pool[i].transform.rotation;
				array4[i] = lastAcquiredTimestamps[pool[i]];
			}
			base.photonView.RPC("RpcInitializePool", newPlayer, array, array2, array3, array4);
		}
	}

	private void TryTransferOwnershipToMasterClient(GameObject go)
	{
		PhotonView photonView = go.GetPhotonView();
		if (photonView != null)
		{
			photonView.TransferOwnership(PhotonNetwork.masterClient);
		}
	}
}
public class OccupiableSpawnPointPool : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private OccupiableSpawnPoint[] pool;

	private List<OccupiableSpawnPoint> available = new List<OccupiableSpawnPoint>();

	public int Availability => available.Count;

	private void Awake()
	{
		OccupiableSpawnPoint[] array = pool;
		foreach (OccupiableSpawnPoint occupiableSpawnPoint in array)
		{
			occupiableSpawnPoint.AutomaticallyReleasedEvent += Release;
		}
		Reset();
	}

	public OccupiableSpawnPoint AcquireNext()
	{
		if (Availability <= 0)
		{
			return null;
		}
		return AcquireAtIndex(0);
	}

	public OccupiableSpawnPoint AcquireRandom()
	{
		if (Availability <= 0)
		{
			return null;
		}
		return AcquireAtIndex(UnityEngine.Random.Range(0, available.Count));
	}

	public void Release(OccupiableSpawnPoint tf)
	{
		if (!available.Contains(tf))
		{
			tf.Release();
			available.Add(tf);
		}
	}

	public void Reset()
	{
		available.Clear();
		OccupiableSpawnPoint[] array = pool;
		foreach (OccupiableSpawnPoint occupiableSpawnPoint in array)
		{
			available.Add(occupiableSpawnPoint);
			if (occupiableSpawnPoint.Occupied)
			{
				occupiableSpawnPoint.Release();
			}
		}
	}

	private OccupiableSpawnPoint AcquireAtIndex(int index)
	{
		if (index >= available.Count)
		{
			return null;
		}
		OccupiableSpawnPoint occupiableSpawnPoint = available[index];
		available.RemoveAt(index);
		occupiableSpawnPoint.Occupy();
		return occupiableSpawnPoint;
	}
}
