	private void Awake()
	{
		playerTeleportDecal = UnityEngine.Object.Instantiate(playerTeleportDecalPrefab);
		playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.None;
		parabolicPointer.transform.localPosition = laserStartPosition.localPosition;
		parabolicPointer.LaserTeleporter = this;
		visualRoot.gameObject.SetActive(value: false);
		menuLaser.enabled = false;
	}

	private void Start()
	{
		Player.SetParentPlayerRoot(playerTeleportDecal.transform);
		GameObject obj = base.gameObject;
		obj.name = obj.name + "_" + Hand.Type;
		otherHand = ((Hand.Type != PlayerHand.HandType.Left) ? Player.LeftHand : Player.RightHand);
		parabolicPointer.ToolHitEnabled = Player.PlayerLocomotion.TeleportToolHitsEnabled;
		parabolicPointer.StraightLaser = StraightLaser;
	}

	private void OnDestroy()
	{
		if (pointer != null)
		{
			UnityEngine.Object.Destroy(pointer.gameObject);
		}
		if (playerTeleportDecal != null)
		{
			UnityEngine.Object.Destroy(playerTeleportDecal.gameObject);
		}
	}

	private void OnDisable()
	{
		if (pointer != null)
		{
			pointer.gameObject.SetActive(value: false);
		}
		if (playerTeleportDecal != null)
		{
			playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.None;
		}
	}

	private void Update()
	{
		if (Hand != null)
		{
			base.transform.position = Hand.transform.position;
			base.transform.rotation = Hand.transform.rotation;
		}
		else
		{
			UnityEngine.Debug.LogError("Laser teleporter update without Hand should never happen.");
		}
		if (Hand.isLocal)
		{
			UpdateTeleportationLaser();
			UpdateMenuLaser();
			UpdateButtonMaterial();
		}
		UpdateDecal();
	}

	private void UpdateTeleportationLaser()
	{
		bool flag = Hand.ControllerIO != null && Hand.ControllerIO.TeleportButtonDown;
		bool flag2 = Hand.ControllerIO != null && Hand.ControllerIO.TeleportButtonUp;
		bool flag3 = (Hand.ControllerIO != null && Hand.ControllerIO.TeleportButtonPressed) || flag || flag2;
		bool flag4 = Hand.ControllerIO != null && Hand.ControllerIO.PushToTalkButtonPressed;
		bool flag5 = otherHand.ControllerIO != null && otherHand.ControllerIO.PushToTalkButtonPressed;
		if (Hand.Type == PlayerHand.HandType.Right)
		{
			UpdateGripRotate(flag4 && flag5);
		}
		if (flag)
		{
			Player.PlayerLocomotion.JustTeleported = false;
		}
		bool flag6 = otherHand != null && IsValidTeleportMode(otherHand.PlayerHandRemote.Mode);
		if (Player.PlayerLocomotion.JustTeleported || flag6 || !flag3)
		{
			Mode = LaserMode.Disabled;
			return;
		}
		if (!Player.PlayerLocomotion.TeleportEnabled || Player.PlayerLocomotion.TeleportOnCooldown)
		{
			if (Mode != LaserMode.Cooldown)
			{
				Player.PlayerLocomotion.OnTeleportError();
			}
			Mode = LaserMode.Cooldown;
			return;
		}
		if (Mode == LaserMode.Disabled || Mode == LaserMode.Cooldown)
		{
			Player.PlayerLocomotion.OnTeleportLaserEnabled();
		}
		if (Vector3.Angle(base.transform.forward, Vector3.up) < Player.PlayerLocomotion.MaxTeleportPitchDegrees)
		{
			Mode = LaserMode.InvalidTeleportAngle;
			return;
		}
		parabolicPointer.PerformParabolicRaycasts(Player.PlayerLocomotion.MaxTeleportDistance, Player.PlayerLocomotion.ChargeAmount);
		bool flag7 = otherHand != null && otherHand.ControllerIO != null && otherHand.ControllerIO.TeleportButtonPressed;
		bool flag8 = otherHand != null && otherHand.ControllerIO != null && otherHand.ControllerIO.TeleportButtonUp;
		bool tryToTeleport = flag2 || flag8;
		if (parabolicPointer.TeleportationPortal != null && parabolicPointer.TeleportationPortal.IsValid)
		{
			Mode = UpdatePortalTeleport(parabolicPointer.TeleportationPortal, tryToTeleport);
			return;
		}
		bool rotate = flag7 || flag8;
		Mode = UpdateEnvironmentTeleport(parabolicPointer.PointOnTeleportRegion, parabolicPointer.SelectedPoint, parabolicPointer.TeleportRestrictions, rotate, tryToTeleport);
	}

	private void UpdateGripRotate(bool rotating)
	{
		if (rotating)
		{
			Vector3 vector = (Hand.transform.position + otherHand.transform.position) / 2f;
			Vector3? vector2 = handsCenter;
			if (!vector2.HasValue)
			{
				handsCenter = vector;
			}
			else
			{
				Vector3 to = vector - Hand.ThisPlayer.Head.transform.position;
				to.y = 0f;
				Vector3 vector3 = handsCenter.Value - Hand.ThisPlayer.Head.transform.position;
				vector3.y = 0f;
				float f = vector3.AngleSigned(to);
				if (Mathf.Abs(f) > 10f)
				{
					Quaternion quaternion = Quaternion.AngleAxis(Mathf.Sign(f) * 45f, Vector3.up);
					Vector3 playerForward = quaternion * Vector3.ProjectOnPlane(SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.forward, Vector3.up);
					Hand.ThisPlayer.PlayerLocomotion.MoveCameraRig(Hand.ThisPlayer.CurrentFloorPosition, playerForward);
					handsCenter = null;
				}
			}
		}
		else
		{
			handsCenter = null;
		}
		BlurOptimized component = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.GetComponent<BlurOptimized>();
		component.enabled = rotating;
		Hand.ThisPlayer.PlayerChaperone.ShowCurrentBounds = rotating;
	}

	private void UpdateMenuLaser()
	{
		bool hasValue = Hand.ControllerIO.UIRaycastPosition.HasValue;
		Vector3? hitPoint = Hand.ControllerIO.UIRaycastPosition;
		if (Mode != LaserMode.Disabled || (!hasValue && !UpdatePlayerMenuTargeting(ref hitPoint)))
		{
			menuLaser.enabled = false;
			return;
		}
		menuLaser.enabled = true;
		if (!hitPoint.HasValue)
		{
			hitPoint = laserStartPosition.position + base.transform.forward * 10f;
		}
		menuLaser.SetPosition(0, laserStartPosition.position);
		menuLaser.SetPosition(1, hitPoint.Value);
		Color color = menuLaser.material.color;
		color.a = ((!Hand.ControllerIO.UISelectable) ? 0.3f : 0.85f);
		menuLaser.material.color = color;
	}

	private LaserMode UpdatePortalTeleport(TeleportationPortal portal, bool tryToTeleport)
	{
		if (tryToTeleport)
		{
			Vector3 position = ((!(portal.Target != null)) ? portal.transform.position : portal.Target.position);
			if (portal.TargetPositionOverride.HasValue)
			{
				position = portal.TargetPositionOverride.Value;
			}
			PerformTeleport(position, Quaternion.identity, portal);
		}
		return LaserMode.ValidPortalPosition;
	}

	private LaserMode UpdateEnvironmentTeleport(bool pointOnTeleportRegion, Vector3 teleportPosition, TeleportRestriction restrictions, bool rotate, bool tryToTeleport)
	{
		if (!pointOnTeleportRegion || !CheckSafeTeleportPosition(teleportPosition, teleportPosition + Player.Head.HeightOffset))
		{
			return LaserMode.InvalidTeleportPosition;
		}
		if (restrictions != null && !ActivityManager.Instance.TeleportRestrictions.IsValidRegion(Player, restrictions))
		{
			return LaserMode.RestrictedTeleportPosition;
		}
		rotationEnabled = rotate;
		CurrentRotation = GetTeleportRotation(rotate);
		if (Player.PlayerLocomotion.TeleportToolHitsEnabled && parabolicPointer.HitTool != null)
		{
			lastToolHitSelectionTime = Time.time;
			lastToolHitData = new TeleportSelectionData
			{
				Position = teleportPosition,
				Rotation = CurrentRotation,
				HitTool = parabolicPointer.HitTool,
				HitToolPosition = parabolicPointer.HitToolPosition,
				HitToolNormal = parabolicPointer.HitToolNormal,
				HitToolDirection = (parabolicPointer.HitToolPosition - base.transform.position).normalized
			};
		}
		if (tryToTeleport)
		{
			PerformTeleport(teleportPosition, CurrentRotation, null);
		}
		return LaserMode.ValidTeleportPosition;
	}

	private void UpdateDecal()
	{
		if (playerTeleportDecal.VisibilityMode != PlayerTeleportDecal.DecalVisibilityMode.None)
		{
			playerTeleportDecal.UpdateAvatarDecal(Player, parabolicPointer.SelectedPoint);
			bool flag = Hand.isLocal && rotationEnabled;
			playerTeleportDecal.UpdateRotationDecal(flag, Player, CurrentRotation);
			bool flag2 = Hand.isLocal && ToolHitThisFrame;
			playerTeleportDecal.UpdateToolHitDecal(flag2, Player.PlayerLocomotion.ChargeAmount, lastToolHitData.HitToolPosition, lastToolHitData.HitToolNormal);
		}
	}

	private void PerformTeleport(Vector3 position, Quaternion rotation, TeleportationPortal portal)
	{
		if (ToolHitAvailable)
		{
			Player.PlayerLocomotion.TeleportTo(lastToolHitData.Position, lastToolHitData.Rotation, null, lastToolHitData.HitTool, lastToolHitData.HitToolPosition, lastToolHitData.HitToolDirection);
		}
		else
		{
			Player.PlayerLocomotion.TeleportTo(position, rotation, portal, null, Vector3.zero, Vector3.zero);
		}
		Hand.Vibrate();
	}

	private bool IsWithinToolHitWindow(float window)
	{
		return Time.time - lastToolHitSelectionTime < window;
	}

	private bool IsValidTeleportMode(LaserMode mode)
	{
		return mode != LaserMode.Disabled;
	}

	private bool UpdatePlayerMenuTargeting(ref Vector3? hitPoint)
	{
		bool result = false;
		if (Hand.ControllerIO != null && Hand.ControllerIO.MenuButtonDown)
		{
			lastMenuButtonDownTime = Time.time;
			wasHoldingToolWhenMenuButtonDown = Hand.Tool != null;
		}
		else
		{
			bool flag = Hand.Tool != null || wasHoldingToolWhenMenuButtonDown;
			bool flag2 = Hand.ControllerIO != null && (Hand.ControllerIO.MenuButtonPressed || Hand.ControllerIO.MenuButtonUp);
			if (!flag && flag2 && Time.time - lastMenuButtonDownTime >= menuLaserHoldDuration)
			{
				result = true;
				if (Physics.Raycast(new Ray(laserStartPosition.position, base.transform.forward), out var hitInfo, 20f, 1052672))
				{
					PlayerCollider component = hitInfo.collider.GetComponent<PlayerCollider>();
					if (component != null && component.ThisPlayer != null && !component.ThisPlayer.isLocal)
					{
						TargetRemotePlayer = component.ThisPlayer;
						hitPoint = hitInfo.point;
					}
				}
			}
			else
			{
				TargetRemotePlayer = null;
			}
		}
		if (TargetRemotePlayer != null)
		{
			TargetRemotePlayer.PlayerUI.GlowVisible = true;
		}
		return result;
	}

	private Quaternion GetTeleportRotation(bool isRotating)
	{
		if (isRotating)
		{
			Vector3 forward = Hand.ControllerToHandTransform.forward;
			forward.y = 0f;
			Vector3 forward2 = otherHand.ControllerToHandTransform.forward;
			forward2.y = 0f;
			int num = Mathf.FloorToInt(Vector3.Angle(forward, forward2));
			num *= 3;
			num -= num % 5;
			num = Mathf.Clamp(num, 0, 180);
			if (Vector3.Cross(forward, forward2).y < 0f)
			{
				num = -num;
			}
			return Quaternion.AngleAxis(num, Vector3.up);
		}
		return Quaternion.identity;
	}

	private bool CheckSafeTeleportPosition(Vector3 newPlayerFloorPosition, Vector3 newPlayerHeadPosition)
	{
		if (Physics.CheckSphere(newPlayerHeadPosition, headCollisionRadius, 3073, QueryTriggerInteraction.Ignore))
		{
			return false;
		}
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			Player player = photonPlayer.ToPlayer();
			if (player != null && !player.IsInChangingRoom)
			{
				float magnitude = (player.CurrentFloorPosition - newPlayerFloorPosition).magnitude;
				float num = ((!(ActivityManager.Instance != null) || ActivityManager.Instance.GameState != ActivityGameState.PlayingGame) ? player.PlayerLocomotion.TeleportBufferDistance : ActivityManager.Instance.TeleportRestrictions.GamePlayMinTeleportBuffer);
				if (magnitude <= num)
				{
					return false;
				}
			}
		}
		return true;
	}

	private void UpdateButtonMaterial()
	{
		float teleportCooldownValue = Player.PlayerLocomotion.TeleportCooldownValue;
		Vector3 vector = visualRoot.InverseTransformPoint(cooldownVisualCenter.position);
		Vector3 vector2 = visualRoot.InverseTransformDirection(cooldownVisualCenter.up);
		Vector3 vector3 = visualRoot.InverseTransformDirection(cooldownVisualCenter.forward);
		Material[] materials = cooldownRenderer.materials;
		foreach (Material material in materials)
		{
			material.SetVector("_PlaneCenterLocal", vector);
			material.SetVector("_PlaneNormalLocal", vector2);
			material.SetVector("_PlaneForwardLocal", vector3);
			material.SetFloat("_Progress", teleportCooldownValue);
		}
	}
}
public class ParabolicPointer : UnityEngine.MonoBehaviour
{
	public enum MeshMode
	{
		Valid,
		Invalid,
		Shortened,
		Disabled,
		Invisible
	}

	[Serializable]
	public class GraphicMaterials
	{
		public Material DefaultMaterial;

		public Material UIMaterial;
	}

	private const int MAX_PARABOLA_SEGMENTS = 20;

	[SerializeField]
	[Header("Parabola Mesh Properties")]
	private float parabolaSegmentLength = 1f;

	[SerializeField]
	private float meshDistanceBetweenVertices = 0.05f;

	[SerializeField]
	private float meshWidth = 0.04f;

	[SerializeField]
	private Vector2 uvScale = Vector2.one;

	[SerializeField]
	private float shortenedDistance = 0.66f;

	[SerializeField]
	private float reflectionOffset = 0.5f;

	public float PersonalSpaceFromLaser = 1f;

	public GraphicMaterials ValidTargetMaterials;

	public GraphicMaterials InvalidTargetMaterials;

	public GraphicMaterials ShortenedTargetMaterials;

	[SerializeField]
	private FloatValueCurve laserSpeedCurve;

	private Mesh parabolaMesh;

	private List<Vector3> laserScratchSpace;

	private bool isLocal;

	private float teleportSpeed;

	private BezierPath bezierPath = new BezierPath();

	private TeleportationPortal _teleportationPortal;

	private RaycastHit lastHit = default(RaycastHit);

	public Vector3 InitialParabolaTangent { get; private set; }

	public Vector3 FinalParabolaTangent { get; private set; }

	public Vector3 SelectedPoint { get; private set; }

	public bool Reflected { get; private set; }

	public Vector3 ReflectionPoint { get; private set; }

	public Vector3 ReflectionNormal { get; private set; }

	public float CurrentParabolaAngle { get; private set; }

	public MeshMode Mode { get; set; }

	public LaserTeleporter LaserTeleporter { get; set; }

	public bool ToolHitEnabled { get; set; }

	public bool StraightLaser { get; set; }

	public TeleportationPortal TeleportationPortal
	{
		get
		{
			return _teleportationPortal;
		}
		set
		{
			if (_teleportationPortal != value)
			{
				if (_teleportationPortal != null)
				{
					_teleportationPortal.Highlight = false;
				}
				if (value != null && value.IsValid && Mode != MeshMode.Disabled && LaserTeleporter.Visible)
				{
					value.Highlight = true;
					_teleportationPortal = value;
				}
				else
				{
					_teleportationPortal = null;
				}
			}
		}
	}

	public Player RemotePlayer { get; set; }

	public Tool HitTool { get; set; }

	public Vector3 HitToolPosition { get; set; }

	public Vector3 HitToolNormal { get; set; }

	public TeleportRestriction TeleportRestrictions { get; set; }

	public bool PointOnTeleportRegion { get; private set; }

	public bool PointOnNavMesh { get; internal set; }

	private Material LaserMaterial
	{
		get
		{
			GraphicMaterials graphicMaterials = null;
			return (Mode switch
			{
				MeshMode.Valid => ValidTargetMaterials, 
				MeshMode.Invalid => InvalidTargetMaterials, 
				MeshMode.Shortened => ShortenedTargetMaterials, 
				_ => InvalidTargetMaterials, 
			}).DefaultMaterial;
		}
	}

	private void Start()
	{
		laserScratchSpace = new List<Vector3>(20);
		parabolaMesh = new Mesh();
		parabolaMesh.MarkDynamic();
		parabolaMesh.name = "Parabolic Pointer";
		parabolaMesh.vertices = new Vector3[0];
		parabolaMesh.triangles = new int[0];
		if (LaserTeleporter != null && LaserTeleporter.Hand != null)
		{
			isLocal = LaserTeleporter.Hand.isLocal;
		}
		Mode = MeshMode.Disabled;
	}

	private void Update()
	{
		if (Mode != MeshMode.Disabled && Mode != MeshMode.Invisible && LaserTeleporter.Visible)
		{
			bool targetingLocalPlayer = !isLocal && RemotePlayer != null && RemotePlayer.isLocal;
			bezierPath = GenerateBezierPath(targetingLocalPlayer, base.transform.forward);
			float num = laserSpeedCurve.Evaluate(teleportSpeed);
			GenerateMesh(ref parabolaMesh, bezierPath, meshDistanceBetweenVertices, base.transform.forward, Time.time % 1f * num);
			Graphics.DrawMesh(parabolaMesh, Matrix4x4.identity, LaserMaterial, 2);
		}
	}

	public void PerformParabolicRaycasts(float maxFloorDistance, float speed)
	{
		teleportSpeed = speed;
		ClearRaycast();
		laserScratchSpace.Clear();
		bool flag = false;
		if (StraightLaser)
		{
			flag = CalculateStraightLinePoints(maxFloorDistance);
		}
		else
		{
			Vector3 a = CalculateParabolaAcceleration(maxFloorDistance);
			flag = CalculateParabolaPoints(a, parabolaSegmentLength);
		}
		Vector3 reflectionPoint = Vector3.zero;
		Vector3 reflectionPointTangent = Vector3.zero;
		Vector3 vector = Vector3.zero;
		bool flag2 = false;
		if (!PointOnTeleportRegion)
		{
			vector = base.transform.forward;
			if (flag)
			{
				vector = lastHit.normal;
				if (Mathf.Abs(Vector3.Dot(vector, Vector3.up)) <= 1f - Mathf.Epsilon)
				{
					vector = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
				}
			}
			flag2 = CalculateReflection(vector, parabolaSegmentLength, out reflectionPoint, out reflectionPointTangent);
		}
		Vector3 normalized = (laserScratchSpace[1] - laserScratchSpace[0]).normalized;
		Vector3 vector2 = laserScratchSpace[laserScratchSpace.Count - 1];
		Vector3 normalized2 = (laserScratchSpace[laserScratchSpace.Count - 2] - vector2).normalized;
		if (flag2)
		{
			SetParabolaPointsWithReflection(normalized, reflectionPointTangent, reflectionPoint, vector, vector2);
		}
		else
		{
			SetParabolaPoints(normalized, normalized2, vector2);
		}
	}

	public void SetParabolaPoints(Vector3 initialTangent, Vector3 finalPointTangent, Vector3 finalPoint)
	{
		InitialParabolaTangent = initialTangent;
		FinalParabolaTangent = finalPointTangent;
		SelectedPoint = finalPoint;
		Reflected = false;
		ReflectionPoint = Vector3.zero;
		ReflectionNormal = Vector3.zero;
	}

	public void SetParabolaPointsWithReflection(Vector3 initialTangent, Vector3 reflectionPointTangent, Vector3 reflectionPoint, Vector3 reflectionNormal, Vector3 finalPoint)
	{
		InitialParabolaTangent = initialTangent;
		FinalParabolaTangent = reflectionPointTangent;
		SelectedPoint = finalPoint;
		Reflected = true;
		ReflectionPoint = reflectionPoint;
		ReflectionNormal = reflectionNormal;
	}

	private bool DoRaycast(Ray ray, float magnitude, out RaycastHit hit)
	{
		bool flag = false;
		hit = default(RaycastHit);
		if (!flag && Physics.Raycast(ray, out hit, magnitude, 19456, QueryTriggerInteraction.Collide))
		{
			flag = true;
			if (hit.collider.gameObject.layer == 14 || hit.collider.gameObject.CompareTag("TeleportRegion"))
			{
				TeleportRestrictions = hit.collider.gameObject.GetComponent<TeleportRestriction>();
				TeleportationPortal = hit.collider.gameObject.GetComponent<TeleportationPortal>();
				PointOnTeleportRegion = true;
			}
			else if (hit.collider.gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics))
			{
				PlayerCollider component = hit.collider.gameObject.GetComponent<PlayerCollider>();
				if (component != null && component.ThisPlayer != null)
				{
					RemotePlayer = component.ThisPlayer;
				}
			}
			else if (hit.collider.gameObject.IsInLayerMask(LayerMasks.ToolPhysics))
			{
				Tool colliderTool = hit.collider.GetColliderTool();
				if (colliderTool == null || colliderTool.IsHeld)
				{
					flag = false;
				}
				else if (ToolHitEnabled && colliderTool.SupportsTeleportHits)
				{
					HitTool = colliderTool;
					HitToolPosition = hit.point;
					HitToolNormal = hit.normal;
				}
			}
		}
		return flag;
	}

	private void ClearRaycast()
	{
		TeleportationPortal = null;
		TeleportRestrictions = null;
		RemotePlayer = null;
		HitTool = null;
		HitToolPosition = Vector3.zero;
		HitToolNormal = Vector3.zero;
		PointOnTeleportRegion = false;
	}

	private static float ParabolicCurve(float p0, float v0, float a, float t)
	{
		return p0 + v0 * t + 0.5f * a * t * t;
	}

	private static float ParabolicCurveDeriv(float v0, float a, float t)
	{
		return v0 + a * t;
	}

	private static Vector3 ParabolicCurve(Vector3 p0, Vector3 v0, Vector3 a, float t)
	{
		Vector3 result = default(Vector3);
		for (int i = 0; i < 3; i++)
		{
			result[i] = ParabolicCurve(p0[i], v0[i], a[i], t);
		}
		return result;
	}

	private static Vector3 ParabolicCurveDeriv(Vector3 v0, Vector3 a, float t)
	{
		Vector3 result = default(Vector3);
		for (int i = 0; i < 3; i++)
		{
			result[i] = ParabolicCurveDeriv(v0[i], a[i], t);
		}
		return result;
	}

	private bool CalculateParabolaPoints(Vector3 a, float segmentLength)
	{
		bool result = false;
		Vector3 forward = base.transform.forward;
		Vector3 position = base.transform.position;
		laserScratchSpace.Add(position);
		Vector3 vector = position;
		float num = 0f;
		Ray ray = new Ray(position, base.transform.forward);
		Vector3 vector2 = position;
		RaycastHit hit = default(RaycastHit);
		for (int i = 0; i < 20; i++)
		{
			num += segmentLength / ParabolicCurveDeriv(forward, a, num).magnitude;
			vector2 = ParabolicCurve(position, forward, a, num);
			Vector3 vector3 = vector2 - vector;
			ray = new Ray(vector, vector3.normalized);
			if (DoRaycast(ray, vector3.magnitude, out hit))
			{
				result = true;
				lastHit = hit;
				laserScratchSpace.Add(hit.point);
				break;
			}
			laserScratchSpace.Add(vector2);
			vector = vector2;
		}
		return result;
	}

	private bool CalculateStraightLinePoints(float maxDistance)
	{
		bool result = false;
		Vector3 forward = base.transform.forward;
		Vector3 position = base.transform.position;
		laserScratchSpace.Add(position);
		Ray ray = new Ray(position, forward);
		if (DoRaycast(ray, maxDistance, out var hit))
		{
			result = true;
			lastHit = hit;
			laserScratchSpace.Add(hit.point);
		}
		else
		{
			laserScratchSpace.Add(position + forward * maxDistance);
		}
		return result;
	}

	private bool CalculateReflection(Vector3 reflectionPointNormal, float segmentLength, out Vector3 reflectionPoint, out Vector3 reflectionPointTangent)
	{
		reflectionPoint = laserScratchSpace[laserScratchSpace.Count - 1];
		reflectionPointTangent = (laserScratchSpace[laserScratchSpace.Count - 2] - reflectionPoint).normalized;
		Vector3 vector = reflectionPoint + reflectionPointNormal * reflectionOffset;
		bool result = false;
		bool flag = false;
		while (laserScratchSpace.Count < 20)
		{
			Vector3 vector2 = vector - Vector3.up * segmentLength;
			Vector3 vector3 = vector2 - vector;
			Ray ray = new Ray(vector, vector3.normalized);
			if (DoRaycast(ray, vector3.magnitude, out var hit))
			{
				result = true;
				if (!flag)
				{
					flag = true;
					laserScratchSpace.Add(vector);
				}
				laserScratchSpace.Add(hit.point);
				break;
			}
			laserScratchSpace.Add(vector2);
			vector = vector2;
		}
		return result;
	}

	private BezierPath GenerateBezierPath(bool targetingLocalPlayer, Vector3 defaultTangent)
	{
		bezierPath.Clear();
		if (Mode == MeshMode.Shortened)
		{
			Vector3 vector = defaultTangent * shortenedDistance;
			Vector3 end = base.transform.position + vector;
			Vector3 vector2 = base.transform.position + 0.5f * vector;
			bezierPath.AddCurve(base.transform.position, vector2, vector2, end);
		}
		else if (targetingLocalPlayer)
		{
			Vector3 finalPoint = ((!Reflected) ? SelectedPoint : ReflectionPoint);
			finalPoint += FinalParabolaTangent * PersonalSpaceFromLaser;
			AddBezierPath(base.transform.position, InitialParabolaTangent, finalPoint, FinalParabolaTangent);
		}
		else if (ToolHitEnabled && HitTool != null)
		{
			AddBezierPath(base.transform.position, InitialParabolaTangent, ReflectionPoint, FinalParabolaTangent);
		}
		else if (Reflected)
		{
			AddBezierPath(base.transform.position, InitialParabolaTangent, ReflectionPoint, FinalParabolaTangent);
			if (!StraightLaser)
			{
				Vector3 normalized = (SelectedPoint - ReflectionPoint + 0.25f * ReflectionNormal).normalized;
				CalculateParabolaControlPoints(ReflectionPoint, normalized, SelectedPoint, Vector3.up, out var initialControlPoint, out var finalControlPoint);
				bezierPath.AddCurve(initialControlPoint, finalControlPoint, SelectedPoint);
			}
		}
		else
		{
			AddBezierPath(base.transform.position, InitialParabolaTangent, SelectedPoint, FinalParabolaTangent);
		}
		return bezierPath;
	}

	private void AddBezierPath(Vector3 initialPoint, Vector3 initialTangent, Vector3 finalPoint, Vector3 finalTangent)
	{
		CalculateParabolaControlPoints(initialPoint, InitialParabolaTangent, finalPoint, FinalParabolaTangent, out var initialControlPoint, out var finalControlPoint);
		bezierPath.AddCurve(initialPoint, initialControlPoint, finalControlPoint, finalPoint);
	}

	private void GenerateMesh(ref Mesh mesh, BezierPath path, float sampleLength, Vector3 forward, float uvoffset)
	{
		float pathLength = path.PathLength;
		int num = Mathf.RoundToInt(pathLength / sampleLength);
		mesh.Clear();
		Vector3 vector = Vector3.zero;
		Vector3 vector2 = Vector3.zero;
		if (path.CurveCount <= 0 || num <= 0)
		{
			return;
		}
		Vector3[] array = new Vector3[num * 2];
		Vector2[] array2 = new Vector2[num * 2];
		float num2 = meshWidth / 2f;
		Vector3 normalized = Vector3.Cross(forward, Vector3.up).normalized;
		for (int i = 0; i < num; i++)
		{
			Vector3 vector3 = path.EvaluatePath((float)i / ((float)num - 1f));
			ref Vector3 reference = ref array[2 * i];
			reference = vector3 - normalized * num2;
			ref Vector3 reference2 = ref array[2 * i + 1];
			reference2 = vector3 + normalized * num2;
			float num3 = uvoffset;
			if (i == num - 1 && i > 1)
			{
				float magnitude = (vector2 - vector).magnitude;
				float magnitude2 = (vector3 - vector).magnitude;
				num3 += 1f - magnitude2 / magnitude;
			}
			ref Vector2 reference3 = ref array2[2 * i];
			reference3 = Vector2.Scale(new Vector2(0f, i), uvScale) - new Vector2(0f, num3);
			ref Vector2 reference4 = ref array2[2 * i + 1];
			reference4 = Vector2.Scale(new Vector2(1f, i), uvScale) - new Vector2(0f, num3);
			vector2 = vector;
			vector = vector3;
		}
		int[] array3 = new int[6 * (array.Length - 2)];
		for (int j = 0; j < array.Length / 2 - 1; j++)
		{
			int num4 = 2 * j;
			int num5 = 2 * j + 1;
			int num6 = 2 * j + 2;
			int num7 = 2 * j + 3;
			array3[12 * j] = num4;
			array3[12 * j + 1] = num5;
			array3[12 * j + 2] = num6;
			array3[12 * j + 3] = num6;
			array3[12 * j + 4] = num5;
			array3[12 * j + 5] = num7;
			array3[12 * j + 6] = num6;
			array3[12 * j + 7] = num5;
			array3[12 * j + 8] = num4;
			array3[12 * j + 9] = num7;
			array3[12 * j + 10] = num5;
			array3[12 * j + 11] = num6;
		}
		mesh.vertices = array;
		mesh.uv = array2;
		mesh.triangles = array3;
		mesh.RecalculateBounds();
		mesh.RecalculateNormals();
	}

	private void CalculateParabolaControlPoints(Vector3 initialPoint, Vector3 initialTangent, Vector3 finalPoint, Vector3 finalTangent, out Vector3 initialControlPoint, out Vector3 finalControlPoint)
	{
		float num = ((!(Vector3.Dot(initialTangent, finalTangent) >= 0.99f)) ? ((finalPoint - initialPoint).magnitude / (initialTangent - finalTangent).magnitude) : 0f);
		Vector3 vector = initialPoint + initialTangent * num;
		initialControlPoint = 0.33f * initialPoint + 0.67f * vector;
		finalControlPoint = 0.33f * finalPoint + 0.67f * vector;
	}

	private Vector3 CalculateParabolaAcceleration(float maxFloorDistance)
	{
		Vector3 normalized = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized;
		Vector3 normalized2 = Vector3.Cross(normalized, Vector3.up).normalized;
		Vector3 normalized3 = (Quaternion.AngleAxis(45f, normalized2) * normalized).normalized;
		float num = Vector3.Dot(normalized3, normalized);
		float num2 = maxFloorDistance / num;
		Vector3 vector = Vector3.Project(normalized3, Vector3.up);
		return -2f * vector / num2;
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = Color.white;
		if (lastHit.collider != null)
		{
			Gizmos.DrawWireSphere(lastHit.point + lastHit.normal, 0.1f);
			Gizmos.DrawLine(lastHit.point, lastHit.point + lastHit.normal);
		}
		if (laserScratchSpace != null)
		{
			for (int i = 1; i < laserScratchSpace.Count; i++)
			{
				Gizmos.color = Color.white;
				Gizmos.DrawSphere(laserScratchSpace[i], 0.02f);
				Gizmos.color = Color.yellow;
				Gizmos.DrawLine(laserScratchSpace[i - 1], laserScratchSpace[i]);
			}
		}
	}
}
[DisallowMultipleComponent]
[RequireComponent(typeof(CastCollisionRigidbody))]
public class RigidbodyPickup : Photon.MonoBehaviour
{
	protected const float interpolateToHandDuration = 0.06f;

	[SerializeField]
	[Tooltip("If true then this will accelerate towards the players hand over time.  Otherwise snap to player's hand.")]
	protected bool interpolateToHand = true;

	protected Coroutine attachToHandCoroutine;

	protected PUNNetworkTransform networkTransform;

	protected TrackedVelocity trackedVelocity;

	protected Rigidbody pickupHand;

	protected Vector3 localPickupPosition = Vector3.zero;

	protected Quaternion localPickupRotation = Quaternion.identity;

	public Rigidbody Rigidbody { get; protected set; }

	public bool IsPickedUp { get; protected set; }

	public Vector3 TargetRigidbodyPosition
	{
		get
		{
			if (pickupHand == null)
			{
				return base.transform.position;
			}
			return pickupHand.transform.TransformPoint(localPickupPosition);
		}
	}

	public Quaternion TargetRigidbodyRotation
	{
		get
		{
			if (pickupHand == null)
			{
				return base.transform.rotation;
			}
			return pickupHand.transform.rotation * localPickupRotation;
		}
	}

	private void Awake()
	{
		Rigidbody = GetComponent<Rigidbody>();
		trackedVelocity = GetComponent<TrackedVelocity>();
		networkTransform = GetComponent<PUNNetworkTransform>();
	}

	public virtual void Pickup(Rigidbody hand, Vector3 handSpacePickupPosition, Quaternion handSpacePickupRotation)
	{
		Release();
		Rigidbody.isKinematic = true;
		IsPickedUp = true;
		pickupHand = hand;
		localPickupPosition = handSpacePickupPosition;
		localPickupRotation = handSpacePickupRotation;
		if (networkTransform != null)
		{
			networkTransform.SynchronizationEnabled = base.hasAuthority;
		}
		attachToHandCoroutine = StartCoroutine(AttachToHandCoroutine());
	}

	public virtual void Release()
	{
		Rigidbody.isKinematic = false;
		IsPickedUp = false;
		pickupHand = null;
		localPickupPosition = Vector3.zero;
		localPickupRotation = Quaternion.identity;
		if (networkTransform != null)
		{
			networkTransform.SynchronizationEnabled = true;
			if (!base.hasAuthority)
			{
				networkTransform.StartDynamicTimeExtrapolation();
			}
		}
		ClearAttachToHandCoroutine();
	}

	private IEnumerator AttachToHandCoroutine()
	{
		Vector3 velocity = Vector3.zero;
		Vector3 angularVelocity = Vector3.zero;
		Rigidbody.ClearVelocity();
		if (trackedVelocity != null)
		{
			trackedVelocity.Reset(Vector3.zero, Vector3.zero);
		}
		float timer = 0f;
		while (interpolateToHand && timer < 0.06f)
		{
			Vector3 nextPosition = Vector3.SmoothDamp(Rigidbody.position, TargetRigidbodyPosition, ref velocity, 0.06f);
			Vector3 targetEulerAngles = TargetRigidbodyRotation.eulerAngles;
			Vector3 eulerAngles = base.transform.rotation.eulerAngles;
			eulerAngles.x = Mathf.SmoothDampAngle(eulerAngles.x, targetEulerAngles.x, ref angularVelocity.x, 0.06f);
			eulerAngles.y = Mathf.SmoothDampAngle(eulerAngles.y, targetEulerAngles.y, ref angularVelocity.y, 0.06f);
			eulerAngles.z = Mathf.SmoothDampAngle(eulerAngles.z, targetEulerAngles.z, ref angularVelocity.z, 0.06f);
			Quaternion nextRotation = Quaternion.Euler(eulerAngles);
			InterpolateRigidbodyTransform(nextPosition, nextRotation);
			Rigidbody.ClearVelocity();
			yield return new WaitForFixedUpdate();
			timer += Time.fixedDeltaTime;
		}
		while (true)
		{
			yield return new WaitForFixedUpdate();
			InterpolateRigidbodyTransform(TargetRigidbodyPosition, TargetRigidbodyRotation);
		}
	}

	private void InterpolateRigidbodyTransform(Vector3 position, Quaternion rotation)
	{
		Vector3 vector = (position - Rigidbody.position) / Time.fixedDeltaTime;
		Vector3 vector2 = UnityExtensions.AngularVelocityFromTo(Rigidbody.rotation, rotation) / Time.fixedDeltaTime;
		Rigidbody.velocity = vector.ValueOrZeroIfBogus();
		Rigidbody.angularVelocity = vector2.ValueOrZeroIfBogus();
		Rigidbody.MovePosition(position.ValueOrZeroIfBogus());
		Rigidbody.MoveRotation(rotation.ValueOrIdentityIfBogus());
	}

	private void ClearAttachToHandCoroutine()
	{
		if (attachToHandCoroutine != null)
		{
			StopCoroutine(attachToHandCoroutine);
			attachToHandCoroutine = null;
		}
	}
}
public class PUNNetworkManager : Photon.MonoBehaviour
{
	[Serializable]
	private class ActivityInfo
	{
		public string name;

		public int maxPlayers = 8;

		public bool canJoinInProgress = true;
	}

	public const string VR_REQUIRED_SCENE_NAME = "vr_device_required";

	public const string LOCKER_ROOM_SCENE_NAME = "lockerroom";

	public const string DORM_ROOM_SCENE_NAME = "dormroom";

	public const string EMPTY_SCENE_NAME = "empty";

	private const string ROOM_PROP_KEY_ACTIVITY = "C1";

	private const string ROOM_PROP_KEY_PRIVATE = "C2";

	private const string ROOM_PROP_KEY_AVAILABLE_SPACE = "C3";

	private const string ROOM_PROP_KEY_GAME_IN_PROGRESS = "C4";

	private const string ROOM_PROP_KEY_ROOM_NAME = "C5";

	private const string ROOM_PROP_KEY_PLAYER_STEAMIDS = "C6";

	private const string ROOM_PROP_KEY_SERVER_ADDRESS = "ip";

	private const string RICH_JOIN_COMMAND_PREFIX = "+join:";

	public const int DEFAULT_ROOM_SIZE = 8;

	private const int MAX_JOIN_RETRIES = 4;

	private const float JOIN_PLAYER_TIMEOUT = 20f;

	private const int SERIALIZE_RATE = 30;

	public static PUNNetworkManager Instance;

	public AnimationCurve DynamicNetworkExtrapolationCurve;

	public ColorVault GroupColorVault;

	[SerializeField]
	private ActivityInfo[] activities;

	[SerializeField]
	private string disconnectAlertTitle;

	[SerializeField]
	private string timeoutCouldntConnectMessage;

	[SerializeField]
	private string timeoutDisconnectMessage;

	[SerializeField]
	private string genericDisconnectMessage;

	private string alertTitle;

	private string alertMessage;

	private Callback<GameRichPresenceJoinRequested_t> gameRichPresenceJoinRequested;

	private bool roomJoinFailed;

	private short roomJoinErrorCode;

	private bool friendListUpdated;

	public string PlayerToAutoJoin { get; private set; }

	public bool IsInLockerRoom => IsInActivity("lockerroom");

	public bool IsInDormRoom => IsInActivity("dormroom");

	public string RichJoinCommand => "+join:" + PhotonNetwork.player.userId;

	public event Action<Player> OnRecRoomPlayerConnected;

	private void Awake()
	{
		Instance = this;
		PhotonNetwork.sendRate = 30;
		PhotonNetwork.sendRateOnSerialize = 30;
		PhotonNetwork.UseRpcMonoBehaviourCache = true;
		PhotonNetwork.automaticallySyncScene = true;
		PhotonNetwork.lobby = new TypedLobby("lobby", LobbyType.SqlLobby);
		PhotonNetwork.autoJoinLobby = false;
	}

	private void Start()
	{
		if (Microphone.devices.Length > 0)
		{
			PhotonVoiceNetwork.MicrophoneDevice = Microphone.devices[0];
		}
		CheckCommandLineArgsForRichPresenceJoin();
		if (SteamManager.Initialized)
		{
			gameRichPresenceJoinRequested = Callback<GameRichPresenceJoinRequested_t>.Create(OnGameRichPresenceJoinRequested);
		}
	}

	public void SetGameInProgress(bool gameInProgress)
	{
		if (PhotonNetwork.isMasterClient && PhotonNetwork.inRoom)
		{
			PhotonNetwork.room.SetCustomProperties("C4", gameInProgress ? 1 : 0);
		}
	}

	public bool IsInActivity(string activity)
	{
		return SceneManagerHelper.ActiveSceneName == activity;
	}

	public bool CanJoinInProgress(string activity)
	{
		return GetActivityInfo(activity)?.canJoinInProgress ?? true;
	}

	public int GetMaxPlayers(string activity, int roomSize)
	{
		ActivityInfo activityInfo = GetActivityInfo(activity);
		return (activityInfo == null) ? 8 : Mathf.Min(activityInfo.maxPlayers, roomSize);
	}

	private ActivityInfo GetActivityInfo(string activity)
	{
		ActivityInfo[] array = activities;
		foreach (ActivityInfo activityInfo in array)
		{
			if (activityInfo.name == activity)
			{
				return activityInfo;
			}
		}
		return null;
	}

	public void SetAlertMessage(string message, string title = null)
	{
		alertMessage = message;
		alertTitle = title;
	}

	public bool GetAlertMessage(out string message, out string title)
	{
		bool result = alertMessage != null;
		message = alertMessage;
		title = alertTitle;
		alertMessage = null;
		alertTitle = null;
		return result;
	}

	private void OnConnectionFail(DisconnectCause cause)
	{
		UnityEngine.Debug.LogError("Connection failed: " + cause);
		HandleConnectionFailure(wasConnected: true, cause);
	}

	private void OnFailedToConnectToPhoton(DisconnectCause cause)
	{
		UnityEngine.Debug.LogError("Failed to connect: " + cause);
		HandleConnectionFailure(wasConnected: false, cause);
	}

	private void HandleConnectionFailure(bool wasConnected, DisconnectCause cause)
	{
		string format = ((cause != DisconnectCause.TimeoutDisconnect && cause != DisconnectCause.DisconnectByServer && cause != DisconnectCause.ExceptionOnConnect) ? genericDisconnectMessage : ((!wasConnected) ? timeoutCouldntConnectMessage : timeoutDisconnectMessage));
		string message = string.Format(format, (int)cause);
		SetAlertMessage(message, disconnectAlertTitle);
		PhotonNetwork.Disconnect();
		SwitchActivity("dormroom", null, createPrivateRoom: false, 0, offlineMode: true);
	}

	private void OnMasterClientSwitched(PhotonPlayer newMasterClient)
	{
		if (ActivityManager.IsInitialized)
		{
			UnityEngine.Debug.Log("OnMasterClientSwitched : " + newMasterClient);
			AnalyticsHelper.NetworkMasterClientChanged(ActivityManager.ActivityName, ActivityManager.Instance.GameState, PhotonNetwork.playerList.Length);
		}
		if (newMasterClient.isLocal)
		{
			UpdateRoomPlayerSteamIDs();
		}
	}

	public void SwitchActivity(string activity, string[] expectedUsers = null, bool createPrivateRoom = false, int roomSize = 0, bool offlineMode = false)
	{
		StopAllCoroutines();
		if (activity == "dormroom")
		{
			createPrivateRoom = true;
			roomSize = 1;
		}
		StartCoroutine(SwitchActivityCoroutine(activity, expectedUsers, createPrivateRoom, roomSize, offlineMode));
	}

	public void JoinRoom(string roomName)
	{
		StopAllCoroutines();
		StartCoroutine(JoinRoomCoroutine(roomName));
	}

	public void JoinPlayer(string playerId, string fallbackActivity = null)
	{
		StopAllCoroutines();
		StartCoroutine(JoinPlayerCoroutine(playerId, fallbackActivity));
	}

	private void OnPhotonRandomJoinFailed(object[] codeAndMsg)
	{
		roomJoinErrorCode = (short)codeAndMsg[0];
		roomJoinFailed = true;
	}

	private void OnPhotonJoinRoomFailed(object[] codeAndMsg)
	{
		roomJoinErrorCode = (short)codeAndMsg[0];
		roomJoinFailed = true;
	}

	private void OnPhotonCreateRoomFailed(object[] codeAndMsg)
	{
		roomJoinErrorCode = (short)codeAndMsg[0];
		roomJoinFailed = true;
	}

	private void OnUpdatedFriendList()
	{
		friendListUpdated = true;
	}

	private IEnumerator SwitchActivityCoroutine(string activity, string[] expectedUsers, bool createPrivateRoom, int roomSize, bool offlineMode)
	{
		string previousRoomName = ((PhotonNetwork.room == null) ? null : PhotonNetwork.room.name);
		yield return StartCoroutine(LeaveRoomCoroutine());
		yield return StartCoroutine(InitializeNewConnection(offlineMode));
		if (!createPrivateRoom && !offlineMode)
		{
			yield return StartCoroutine(JoinRandomRoomCoroutine(activity, expectedUsers, previousRoomName, excludeInProgress: true));
			if (PhotonNetwork.connectionStateDetailed != PeerState.Joined && CanJoinInProgress(activity))
			{
				yield return StartCoroutine(JoinRandomRoomCoroutine(activity, expectedUsers, previousRoomName, excludeInProgress: false));
			}
		}
		if (PhotonNetwork.connectionStateDetailed != PeerState.Joined)
		{
			yield return StartCoroutine(CreateRoomCoroutine(activity, expectedUsers, createPrivateRoom, roomSize));
		}
		if (PhotonNetwork.connectionStateDetailed == PeerState.Joined)
		{
			if (PhotonNetwork.isMasterClient)
			{
				activity = (string)PhotonNetwork.room.customProperties["C1"];
				PhotonNetwork.LoadLevel(activity);
				PhotonNetwork.room.SetCustomProperties("ip", PhotonNetwork.ServerAddress);
			}
		}
		else
		{
			SwitchActivity("dormroom");
		}
	}

	private IEnumerator InitializeNewConnection(bool offlineMode)
	{
		if (offlineMode != PhotonNetwork.offlineMode)
		{
			if (!PhotonNetwork.offlineMode && PhotonNetwork.connected)
			{
				PhotonNetwork.Disconnect();
				while (PhotonNetwork.connectedAndReady)
				{
					yield return null;
				}
			}
			PhotonNetwork.offlineMode = offlineMode;
		}
		if (!offlineMode && !PhotonNetwork.connected)
		{
			PhotonNetwork.ConnectUsingSettings(BuildSettings.Version);
			while (!PhotonNetwork.connectedAndReady)
			{
				yield return null;
			}
		}
	}

	private IEnumerator LeaveRoomCoroutine()
	{
		if (PhotonNetwork.connectionStateDetailed == PeerState.Uninitialized || PhotonNetwork.connectionStateDetailed == PeerState.PeerCreated)
		{
			yield break;
		}
		if (PhotonNetwork.offlineMode)
		{
			PhotonNetwork.DestroyAll();
		}
		if (PhotonNetwork.room != null)
		{
			PhotonNetwork.LeaveRoom();
			yield return new WaitUntil(() => PhotonNetwork.connectionStateDetailed == PeerState.ConnectedToMaster || PhotonNetwork.connectionStateDetailed == PeerState.Disconnected || PhotonNetwork.connectionStateDetailed == PeerState.PeerCreated);
		}
		PhotonVoiceNetwork.Disconnect();
		SceneManager.LoadScene("empty");
	}

	private IEnumerator JoinRandomRoomCoroutine(string activity, string[] expectedUsers, string excludedRoomName, bool excludeInProgress)
	{
		yield return new WaitUntil(() => PhotonNetwork.connectionStateDetailed == PeerState.ConnectedToMaster || PhotonNetwork.connectionStateDetailed == PeerState.JoinedLobby);
		int partySize = 1;
		if (expectedUsers != null)
		{
			partySize += expectedUsers.Length;
		}
		string sqlLobbyFilter = string.Format("{0} = {1} AND {2} >= {3}", "C2", 0, "C3", partySize);
		if (!string.IsNullOrEmpty(activity))
		{
			sqlLobbyFilter += string.Format(" AND {0} = \"{1}\"", "C1", activity);
		}
		else
		{
			bool excludeInProgress2 = default(bool);
			string activityNameList = (from a in activities
				where a.canJoinInProgress || excludeInProgress2
				select $"\"{a.name}\"").Aggregate((string a, string b) => $"{a},{b}");
			sqlLobbyFilter += string.Format(" AND {0} IN ({1})", "C1", activityNameList);
		}
		if (!string.IsNullOrEmpty(excludedRoomName))
		{
			sqlLobbyFilter += string.Format(" AND {0} <> \"{1}\"", "C5", excludedRoomName);
		}
		if (excludeInProgress)
		{
			sqlLobbyFilter += string.Format(" AND {0} = {1}", "C4", 0);
		}
		UnityEngine.Debug.Log("Searching for match: " + sqlLobbyFilter);
		roomJoinFailed = false;
		if (PhotonNetwork.JoinRandomRoom(null, 0, MatchmakingMode.RandomMatching, PhotonNetwork.lobby, sqlLobbyFilter, expectedUsers))
		{
			yield return new WaitUntil(() => PhotonNetwork.connectionStateDetailed == PeerState.Joined || roomJoinFailed);
		}
	}

	private IEnumerator CreateRoomCoroutine(string activity, string[] expectedUsers, bool createPrivateRoom, int roomSize)
	{
		yield return new WaitUntil(() => PhotonNetwork.connectionStateDetailed == PeerState.ConnectedToMaster || PhotonNetwork.connectionStateDetailed == PeerState.JoinedLobby);
		string roomName = Guid.NewGuid().ToString();
		int playerCount = 1;
		if (expectedUsers != null)
		{
			playerCount += expectedUsers.Length;
		}
		if (string.IsNullOrEmpty(activity))
		{
			int index = UnityEngine.Random.Range(0, activities.Length);
			activity = activities[index].name;
		}
		if (roomSize <= 0)
		{
			roomSize = 8;
		}
		ExitGames.Client.Photon.Hashtable roomProperties = new ExitGames.Client.Photon.Hashtable
		{
			{ "C1", activity },
			{
				"C2",
				createPrivateRoom ? 1 : 0
			},
			{
				"C3",
				GetMaxPlayers(activity, roomSize) - playerCount
			},
			{ "C4", 0 },
			{ "C5", roomName },
			{
				"C6",
				(!(Player.LocalPlayer != null)) ? string.Empty : Player.LocalPlayer.SteamID.m_SteamID.ToString()
			},
			{
				"ip",
				string.Empty
			}
		};
		string[] roomPropertyNames = new string[7] { "C1", "C2", "C3", "C4", "C5", "C6", "ip" };
		RoomOptions roomOptions = new RoomOptions
		{
			customRoomProperties = roomProperties,
			customRoomPropertiesForLobby = roomPropertyNames,
			maxPlayers = (byte)roomSize,
			publishUserId = true,
			PlayerTtl = 1000
		};
		roomJoinFailed = false;
		if (PhotonNetwork.CreateRoom(roomName, roomOptions, PhotonNetwork.lobby, expectedUsers))
		{
			yield return new WaitUntil(() => PhotonNetwork.connectionStateDetailed == PeerState.Joined || roomJoinFailed);
		}
	}

	private IEnumerator JoinRoomCoroutine(string roomName)
	{
		yield return StartCoroutine(LeaveRoomCoroutine());
		yield return StartCoroutine(InitializeNewConnection(offlineMode: false));
		for (int retry = 0; retry < 4; retry++)
		{
			if (PhotonNetwork.connectionStateDetailed == PeerState.Joined)
			{
				break;
			}
			yield return new WaitForSeconds(retry);
			roomJoinFailed = false;
			PhotonNetwork.JoinRoom(roomName);
			yield return new WaitUntil(() => PhotonNetwork.connectionStateDetailed == PeerState.Joined || roomJoinFailed);
		}
		if (PhotonNetwork.connectionStateDetailed != PeerState.Joined)
		{
			AnalyticsHelper.NetworkRoomJoinFailed(roomJoinErrorCode);
			SwitchActivity("lockerroom");
		}
	}

	private IEnumerator JoinPlayerCoroutine(string playerId, string fallbackActivity)
	{
		if (string.IsNullOrEmpty(fallbackActivity))
		{
			fallbackActivity = "lockerroom";
		}
		string previousRoomName = ((PhotonNetwork.room == null) ? null : PhotonNetwork.room.name);
		yield return StartCoroutine(LeaveRoomCoroutine());
		yield return StartCoroutine(InitializeNewConnection(offlineMode: false));
		float startTime = Time.realtimeSinceStartup;
		while (Time.realtimeSinceStartup - startTime < 20f)
		{
			friendListUpdated = false;
			PhotonNetwork.FindFriends(new string[1] { playerId });
			yield return new WaitUntil(() => friendListUpdated);
			if (PhotonNetwork.Friends[0].IsInRoom && PhotonNetwork.Friends[0].Room != previousRoomName)
			{
				JoinRoom(PhotonNetwork.Friends[0].Room);
				yield break;
			}
		}
		AnalyticsHelper.NetworkFailedToFollowPartyLeader();
		SwitchActivity(fallbackActivity);
	}

	private void OnJoinedRoom()
	{
		if (!PhotonNetwork.offlineMode)
		{
			PhotonVoiceNetwork.Connect();
		}
		DelayedClearExpectedUsers();
		StartCoroutine(RunWaitForRecroomPlayerCreated(PhotonNetwork.player));
	}

	private void OnLeftRoom()
	{
		UpdateRichPresenceJoin();
	}

	private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		UpdateRoomPlayerCount();
		DelayedClearExpectedUsers();
		StartCoroutine(RunWaitForRecroomPlayerCreated(newPlayer));
	}

	private IEnumerator RunWaitForRecroomPlayerCreated(PhotonPlayer newPlayer)
	{
		float timer = 5f;
		while (timer >= 0f)
		{
			timer -= Time.deltaTime;
			yield return null;
			Player player = newPlayer.ToPlayer();
			if (player != null && player.IsInitialized)
			{
				RecRoomPlayerCreated(player);
				yield break;
			}
		}
		if (newPlayer.isLocal)
		{
			if (!PhotonNetwork.otherPlayers.Any((PhotonPlayer p) => !p.isMasterClient && p.ToPlayer() != null) || PhotonNetwork.GetPing() < 500)
			{
				UnityEngine.Debug.LogError("Zombie room encountered - closing room");
				AnalyticsHelper.NetworkReportZombieRoom();
				PhotonNetwork.room.open = false;
			}
			else
			{
				UnityEngine.Debug.LogError("Possible zombie room encountered (other players have been spawned)");
			}
			SwitchActivity(PhotonNetwork.room.customProperties["C1"] as string);
		}
	}

	private void RecRoomPlayerCreated(Player player)
	{
		UpdateRoomPlayerSteamIDs();
		if (this.OnRecRoomPlayerConnected != null)
		{
			this.OnRecRoomPlayerConnected(player);
		}
	}

	private void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		UpdateRoomPlayerCount();
		UpdateRoomPlayerSteamIDs();
	}

	private void UpdateRoomPlayerSteamIDs()
	{
		if (!PhotonNetwork.isMasterClient || !PhotonNetwork.inRoom)
		{
			return;
		}
		string text = string.Empty;
		for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
		{
			Player player = PhotonNetwork.playerList[i].ToPlayer();
			if (player != null && player.SteamID.IsValid())
			{
				text = text + player.SteamID.m_SteamID + ",";
			}
		}
		PhotonNetwork.room.SetCustomProperties("C6", text);
	}

	private void OnPhotonCustomRoomPropertiesChanged(ExitGames.Client.Photon.Hashtable propertiesThatChanged)
	{
		if (propertiesThatChanged.ContainsKey((byte)247))
		{
			UpdateRoomPlayerCount();
		}
		if (propertiesThatChanged.ContainsKey("C3"))
		{
			UpdateRichPresenceJoin();
		}
	}

	private void DelayedClearExpectedUsers()
	{
		CancelInvoke("ClearExpectedUsers");
		Invoke("ClearExpectedUsers", 20f);
	}

	private void ClearExpectedUsers()
	{
		if (PhotonNetwork.isMasterClient && PhotonNetwork.connectedAndReady && PhotonNetwork.room != null && !PhotonNetwork.offlineMode)
		{
			PhotonNetwork.room.ClearExpectedUsers();
		}
	}

	private void UpdateRoomPlayerCount()
	{
		if (PhotonNetwork.isMasterClient && PhotonNetwork.inRoom)
		{
			string activity = (string)PhotonNetwork.room.customProperties["C1"];
			int maxPlayers = PhotonNetwork.room.maxPlayers;
			int maxPlayers2 = GetMaxPlayers(activity, maxPlayers);
			int roomPlayerCount = GetRoomPlayerCount();
			PhotonNetwork.room.SetCustomProperties("C3", maxPlayers2 - roomPlayerCount);
		}
	}

	public int GetRoomPlayerCount()
	{
		int num = PhotonNetwork.playerList.Length;
		if (PhotonNetwork.room.expectedUsers != null)
		{
			string[] second = PhotonNetwork.playerList.Select((PhotonPlayer p) => p.userId).ToArray();
			num += PhotonNetwork.room.expectedUsers.Except(second).Count();
		}
		return num;
	}

	public bool IsJoinable()
	{
		return !PhotonNetwork.offlineMode && PhotonNetwork.inRoom && GetRoomPlayerCount() < PhotonNetwork.room.maxPlayers;
	}

	private void UpdateRichPresenceJoin()
	{
		if (SteamManager.Initialized)
		{
			SteamFriends.SetRichPresence("connect", (!IsJoinable()) ? null : RichJoinCommand);
		}
	}

	private void OnGameRichPresenceJoinRequested(GameRichPresenceJoinRequested_t param)
	{
		ProcessRichJoinCommand(param.m_rgchConnect);
	}

	public void ProcessRichJoinCommand(string connectCommand)
	{
		if (ActivityManager.Instance != null && !string.IsNullOrEmpty(connectCommand) && connectCommand.StartsWith("+join:"))
		{
			string playerId = connectCommand.Substring("+join:".Length);
			ActivityManager.Instance.JoinPlayer(playerId);
		}
	}

	private void CheckCommandLineArgsForRichPresenceJoin()
	{
		string[] commandLineArgs = Environment.GetCommandLineArgs();
		for (int i = 0; i < commandLineArgs.Length; i++)
		{
			if (commandLineArgs[i].StartsWith("+join:"))
			{
				PlayerToAutoJoin = commandLineArgs[i].Substring("+join:".Length);
			}
		}
	}

	public PhotonPlayer DebugChangeMasterClient()
	{
		int num = 0;
		for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
		{
			if (PhotonNetwork.playerList[i].isMasterClient)
			{
				num = i;
				break;
			}
		}
		num = (num + 1) % PhotonNetwork.playerList.Length;
		PhotonNetwork.SetMasterClient(PhotonNetwork.playerList[num]);
		return PhotonNetwork.playerList[num];
	}
}
[AddComponentMenu("Photon Networking/PUN Network Transform")]
[RequireComponent(typeof(PhotonView))]
[DisallowMultipleComponent]
public class PUNNetworkTransform : Photon.MonoBehaviour
{
	public enum ExtrapolationMode
	{
		None,
		DynamicDistance,
		DynamicTime
	}

	private const float k_MaxDynamicTimeExtrapolationDuration = 0.2f;

	private const float k_LocalMovementThreshold = 0.001f;

	private const float k_LocalRotationThreshold = 0.1f;

	private const float k_AccountForGravityThreshold = 0.05f;

	private const float k_InterpolationTime = 0.05f;

	[SerializeField]
	private float snapThreshold = 5f;

	[SerializeField]
	private float minSyncInterval = 5f;

	[NonSerialized]
	public bool SynchronizationEnabled = true;

	[NonSerialized]
	public ExtrapolationMode CurrentExtrapolationMode;

	private CastCollisionRigidbody castCollisionRigidbody;

	private Rigidbody rigidbody;

	private TrackedVelocity trackedVelocity;

	private Tool tool;

	private PlayerInteractionRestriction interactionRestriction;

	private float lastSyncTime;

	private bool syncRequested;

	private float networkLatency;

	private Vector3 lastExtrapolatedVelocity = Vector3.zero;

	private Vector3 lastExtrapolatedAngularVelocity = Vector3.zero;

	private double lastSnapTime;

	private bool syncHasData;

	private bool syncIsSleeping;

	private double syncNetworkTime;

	private Vector3 syncPosition;

	private Quaternion syncRotation;

	private Vector3 syncVelocity;

	private Vector3 syncAngularVelocity;

	private float dynamicTimeExtrapolationStartTime;

	private bool hasPhysicsDrivenRigidbody => rigidbody != null && !rigidbody.isKinematic;

	private void OnValidate()
	{
		if (snapThreshold < 0f)
		{
			snapThreshold = 0.01f;
		}
	}

	private void Awake()
	{
		trackedVelocity = GetComponent<TrackedVelocity>();
		castCollisionRigidbody = GetComponent<CastCollisionRigidbody>();
		rigidbody = ((!(castCollisionRigidbody == null)) ? castCollisionRigidbody.Rigidbody : null);
		tool = GetComponent<Tool>();
		interactionRestriction = GetComponent<PlayerInteractionRestriction>();
	}

	private void Start()
	{
		lastSnapTime = 0.0;
		syncHasData = false;
		syncNetworkTime = 0.0;
		syncPosition = base.transform.position;
		syncRotation = base.transform.rotation;
		syncVelocity = GetLinearVelocity();
		syncAngularVelocity = GetAngularVelocity();
		base.photonView.OwnerChangedEvent += OnPhotonOwnershipChanged;
	}

	private void OnDestroy()
	{
		base.photonView.OwnerChangedEvent -= OnPhotonOwnershipChanged;
	}

	private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (base.hasAuthority)
		{
			syncRequested = true;
		}
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading && info.sender != base.authority)
		{
			return;
		}
		if (stream.isWriting)
		{
			if (syncRequested || Time.fixedTime - lastSyncTime > minSyncInterval)
			{
				syncHasData = true;
				syncRequested = false;
			}
			else if (hasPhysicsDrivenRigidbody)
			{
				syncHasData = !rigidbody.IsSleeping();
			}
			else
			{
				syncHasData = (base.transform.position - syncPosition).magnitude > 0.001f || Quaternion.Angle(base.transform.rotation, syncRotation) > 0.1f;
			}
		}
		stream.Serialize(ref syncHasData);
		if (!syncHasData)
		{
			if (stream.isReading)
			{
				ResetPhysics(syncPosition, syncRotation);
				if (hasPhysicsDrivenRigidbody)
				{
					rigidbody.Sleep();
				}
			}
			return;
		}
		syncNetworkTime = PhotonNetwork.time;
		syncPosition = base.transform.position;
		syncRotation = base.transform.rotation;
		syncVelocity = GetLinearVelocity();
		syncAngularVelocity = GetAngularVelocity();
		syncIsSleeping = hasPhysicsDrivenRigidbody && rigidbody.IsSleeping();
		stream.Serialize(ref syncNetworkTime);
		stream.Serialize(ref syncPosition);
		stream.Serialize(ref syncRotation);
		stream.Serialize(ref syncVelocity);
		stream.Serialize(ref syncAngularVelocity);
		stream.Serialize(ref syncIsSleeping);
		networkLatency = (float)(PhotonNetwork.time - syncNetworkTime);
		if (stream.isReading)
		{
			float magnitude = (base.transform.position - syncPosition).magnitude;
			if (syncIsSleeping || lastSyncTime == 0f || magnitude > snapThreshold)
			{
				ResetPhysics(syncPosition, syncRotation);
			}
			if (syncIsSleeping && hasPhysicsDrivenRigidbody)
			{
				rigidbody.Sleep();
			}
		}
		lastSyncTime = Time.fixedTime;
	}

	public void Snap(Vector3 position, Quaternion rotation, double networkTimestamp)
	{
		lastSnapTime = networkTimestamp;
		ResetPhysics(position, rotation);
	}

	public void StartDynamicTimeExtrapolation()
	{
		dynamicTimeExtrapolationStartTime = Time.fixedTime;
	}

	private void FixedUpdate()
	{
		if (!base.hasAuthority && SynchronizationEnabled && syncHasData && lastSyncTime != 0f && syncNetworkTime >= lastSnapTime)
		{
			InterpolateTowardLatestSync();
		}
		if (CurrentExtrapolationMode == ExtrapolationMode.DynamicDistance && (tool == null || !tool.IsHeld))
		{
			Player player = Player.FindClosest(base.transform.position, interactionRestriction);
			if (player != null && player.photonView.ownerId != base.photonView.ownerId && (base.hasAuthority || player == Player.LocalPlayer))
			{
				base.photonView.TransferOwnership(player.photonView.ownerId);
			}
		}
	}

	private void UpdatePhysics(Vector3 velocity, Vector3 angularVelocity)
	{
		velocity = velocity.ValueOrZeroIfBogus();
		angularVelocity = angularVelocity.ValueOrZeroIfBogus();
		if (rigidbody != null)
		{
			rigidbody.velocity = velocity;
			rigidbody.angularVelocity = angularVelocity;
		}
		if (!hasPhysicsDrivenRigidbody)
		{
			Vector3 vector = velocity * Time.fixedDeltaTime + base.transform.position;
			Quaternion quaternion = UnityExtensions.QuaternionFromAngularVelocity(angularVelocity * Time.fixedDeltaTime) * base.transform.rotation;
			vector = vector.ValueOrZeroIfBogus();
			quaternion = quaternion.ValueOrIdentityIfBogus();
			if (rigidbody != null)
			{
				rigidbody.MovePosition(vector);
				rigidbody.MoveRotation(quaternion);
			}
			else
			{
				base.transform.position = vector;
				base.transform.rotation = quaternion;
			}
		}
	}

	private Vector3 GetLinearVelocity()
	{
		if (hasPhysicsDrivenRigidbody)
		{
			return rigidbody.velocity;
		}
		if (trackedVelocity != null)
		{
			return trackedVelocity.RecentLinearVelocity;
		}
		return Vector3.zero;
	}

	private Vector3 GetAngularVelocity()
	{
		if (hasPhysicsDrivenRigidbody)
		{
			return rigidbody.angularVelocity;
		}
		if (trackedVelocity != null)
		{
			return trackedVelocity.RecentAngularVelocity;
		}
		return Vector3.zero;
	}

	private void ResetPhysics(Vector3 position, Quaternion rotation)
	{
		ResetVelocity(Vector3.zero, Vector3.zero);
		base.transform.position = position.ValueOrZeroIfBogus();
		base.transform.rotation = rotation.ValueOrIdentityIfBogus();
	}

	private void ResetVelocity(Vector3 newVelocity, Vector3 newAngularVelocity)
	{
		newVelocity = newVelocity.ValueOrZeroIfBogus();
		newAngularVelocity = newAngularVelocity.ValueOrZeroIfBogus();
		if (rigidbody != null)
		{
			rigidbody.velocity = newVelocity;
			rigidbody.angularVelocity = newAngularVelocity;
		}
		if (!hasPhysicsDrivenRigidbody && trackedVelocity != null)
		{
			trackedVelocity.Reset(newVelocity, newAngularVelocity);
		}
		lastExtrapolatedVelocity = newVelocity;
		lastExtrapolatedAngularVelocity = newAngularVelocity;
	}

	private void InterpolateTowardLatestSync()
	{
		float timeSinceLastSync = GetTimeSinceLastSync();
		Vector3 extrapolatedSyncPosition = GetExtrapolatedSyncPosition(timeSinceLastSync);
		Quaternion extrapolatedSyncRotation = GetExtrapolatedSyncRotation(timeSinceLastSync);
		Vector3 velocity = (extrapolatedSyncPosition - base.transform.position) / 0.05f;
		Vector3 angularVelocity = UnityExtensions.AngularVelocityFromTo(base.transform.rotation, extrapolatedSyncRotation) / 0.05f;
		UpdatePhysics(velocity, angularVelocity);
	}

	private Vector3 GetExtrapolatedSyncPosition(float timeSinceLastSync)
	{
		Vector3 vector = syncVelocity * timeSinceLastSync;
		lastExtrapolatedVelocity = syncVelocity;
		lastExtrapolatedAngularVelocity = syncAngularVelocity;
		bool flag = ShouldAccountForGravity();
		if (flag)
		{
			vector += Physics.gravity * timeSinceLastSync * timeSinceLastSync / 2f;
			lastExtrapolatedVelocity += Physics.gravity * timeSinceLastSync;
		}
		Vector3 vector2 = syncPosition + vector;
		Vector3 normalized = vector.normalized;
		float magnitude = vector.magnitude;
		if (magnitude > Mathf.Epsilon && castCollisionRigidbody != null && castCollisionRigidbody.Cast(syncPosition, base.transform.rotation, normalized, magnitude, 2048, out var closestHit))
		{
			float num = timeSinceLastSync * (1f - closestHit.Distance / magnitude);
			if (flag)
			{
				vector2 -= Physics.gravity * num * num / 2f;
			}
			Vector3 vector3 = syncPosition + normalized * closestHit.Distance;
			Vector3 inDirection = vector2 - vector3;
			inDirection = Vector3.Reflect(inDirection, closestHit.Normal);
			Vector3 vector4 = Vector3.Project(inDirection, closestHit.Normal);
			Vector3 vector5 = inDirection - vector4;
			float num2 = ((!(closestHit.CastCollider.material == null)) ? closestHit.CastCollider.material.CombinedBounciness(closestHit.Collider.material) : 1f);
			Vector3 vector6 = vector5 + vector4 * num2;
			vector2 = vector3 + vector6;
			lastExtrapolatedVelocity = vector6 / inDirection.magnitude * syncVelocity.magnitude;
			if (flag)
			{
				vector2 += Physics.gravity * num * num / 2f;
				lastExtrapolatedVelocity += Physics.gravity * num;
			}
		}
		return vector2;
	}

	private Quaternion GetExtrapolatedSyncRotation(float timeSinceLastSync)
	{
		Vector3 angularVelocity = syncAngularVelocity * timeSinceLastSync;
		Quaternion quaternion = UnityExtensions.QuaternionFromAngularVelocity(angularVelocity);
		return quaternion * syncRotation;
	}

	private float GetTimeSinceLastSync()
	{
		float num = Time.fixedTime - lastSyncTime;
		if (CurrentExtrapolationMode != ExtrapolationMode.None)
		{
			num += GetExtrapolationAmount() * (networkLatency + 0.05f);
		}
		return num;
	}

	private float GetExtrapolationAmount()
	{
		float result = 1f;
		if (CurrentExtrapolationMode == ExtrapolationMode.DynamicDistance)
		{
			result = GetDynamicDistanceExtrapolation();
		}
		else if (CurrentExtrapolationMode == ExtrapolationMode.DynamicTime)
		{
			result = GetDynamicTimeExtrapolation();
		}
		return result;
	}

	private float GetDynamicDistanceExtrapolation()
	{
		float result = 1f;
		Player player = ((base.photonView.owner != null) ? (base.photonView.owner.TagObject as Player) : null);
		if (player != null && Player.LocalPlayer != null)
		{
			Vector3 position = player.Head.transform.position;
			Vector3 position2 = Player.LocalPlayer.Head.transform.position;
			Vector3 rhs = position2 - position;
			Vector3 lhs = base.transform.position - position;
			float num = Vector3.Dot(lhs, rhs);
			float sqrMagnitude = rhs.sqrMagnitude;
			float time = ((sqrMagnitude != 0f) ? (Mathf.Clamp01(num / sqrMagnitude) / 0.5f) : 0f);
			result = PUNNetworkManager.Instance.DynamicNetworkExtrapolationCurve.Evaluate(time);
		}
		return result;
	}

	private float GetDynamicTimeExtrapolation()
	{
		float time = Mathf.Clamp01((Time.fixedTime - dynamicTimeExtrapolationStartTime) / 0.2f);
		return PUNNetworkManager.Instance.DynamicNetworkExtrapolationCurve.Evaluate(time);
	}

	private bool ShouldAccountForGravity()
	{
		if (hasPhysicsDrivenRigidbody && rigidbody.useGravity)
		{
			float f = Vector3.Dot(syncVelocity, Physics.gravity.normalized);
			return Mathf.Abs(f) > 0.05f;
		}
		return false;
	}

	private void OnPhotonOwnershipChanged(int playerId)
	{
		syncHasData = false;
		if (base.hasAuthority)
		{
			syncRequested = true;
			ResetVelocity(lastExtrapolatedVelocity, lastExtrapolatedAngularVelocity);
		}
	}
}
public class PUNPrefabInstantiate : UnityEngine.MonoBehaviour
{
	[Serializable]
	public struct PrefabContainer
	{
		public string Name;

		public GameObject Prefab;

		public Transform[] CachedTransforms;
	}

	public static List<PUNPrefabInstantiate> All = new List<PUNPrefabInstantiate>();

	[Tooltip("Instantiate scene prefabs that belong to no one.")]
	public bool SceneLevelInstantiate = true;

	public PrefabContainer[] Containers;

	public int SceneIndex { get; private set; }

	private void Awake()
	{
		SceneIndex = SceneManager.GetActiveScene().buildIndex;
		if (GetCurrent() != null)
		{
			UnityEngine.Debug.LogError("You have multiple scene PUNPrefabInstantiates associated with the same scene." + SceneManager.GetActiveScene());
		}
		All.Add(this);
	}

	private void OnDestroy()
	{
		All.Remove(this);
	}

	public void Start()
	{
		if (SceneLevelInstantiate)
		{
			InstantiatePrefabs();
		}
	}

	public void InstantiatePrefabs()
	{
		if ((!PhotonNetwork.isMasterClient && SceneLevelInstantiate) || Containers == null || !(PUNNetworkManager.Instance != null))
		{
			return;
		}
		for (int i = 0; i < Containers.Length; i++)
		{
			for (int j = 0; j < Containers[i].CachedTransforms.Length; j++)
			{
				Transform transform = Containers[i].CachedTransforms[j];
				int num = Containers[i].Prefab.GetComponentsInChildren<PhotonView>(includeInactive: true).Length;
				int[] array = new int[num];
				for (int k = 0; k < array.Length; k++)
				{
					array[k] = ((!SceneLevelInstantiate) ? PhotonNetwork.AllocateViewID() : PhotonNetwork.AllocateSceneViewID());
				}
				PUNNetworkManager.Instance.photonView.RPC("SpawnOnNetwork", PhotonTargets.AllBuffered, SceneIndex, i, transform.position, transform.rotation, transform.localScale, array);
				PhotonNetwork.SendOutgoingCommands();
			}
		}
	}

	public static PUNPrefabInstantiate GetCurrent()
	{
		return Get(SceneManager.GetActiveScene().buildIndex);
	}

	public static PUNPrefabInstantiate Get(int sceneIndex)
	{
		foreach (PUNPrefabInstantiate item in All)
		{
			if (item != null && item.SceneIndex == sceneIndex)
			{
				return item;
			}
		}
		return null;
	}

	public void SpawnOnNetwork(int containerIndex, Vector3 pos, Quaternion rot, Vector3 scale, int[] ids)
	{
		GameObject gameObject = UnityEngine.Object.Instantiate(Containers[containerIndex].Prefab, pos, rot) as GameObject;
		gameObject.transform.localScale = scale;
		PhotonView[] componentsInChildren = gameObject.GetComponentsInChildren<PhotonView>(includeInactive: true);
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].viewID = ids[i];
		}
	}
}
public class ActivityBounds : UnityEngine.MonoBehaviour
{
	private static List<ActivityBounds> allBounds = new List<ActivityBounds>();

	private OverlapVolume overlapVolume;

	private void Awake()
	{
		overlapVolume = GetComponent<OverlapVolume>();
		allBounds.Add(this);
	}

	private void OnDestroy()
	{
		allBounds.Remove(this);
	}

	private bool ContainsPoint(Vector3 point)
	{
		return overlapVolume.CheckOverlap(point);
	}

	public static bool PointInBounds(Vector3 point)
	{
		if (allBounds.Count == 0)
		{
			return true;
		}
		for (int i = 0; i < allBounds.Count; i++)
		{
			if (allBounds[i].ContainsPoint(point))
			{
				return true;
			}
		}
		return false;
	}
}
public class AvatarColor : UnityEngine.MonoBehaviour
{
	public enum ColorType
	{
		Skin,
		Hair
	}

	public static List<AvatarColor> All = new List<AvatarColor>();

	[Tooltip("Matching guid value from the OutfitManager Color Vault")]
	public string GuidString = string.Empty;

	public ColorType Type = ColorType.Hair;

	private UnityEngine.UI.Image image;

	private Outline outline;

	private bool _selected;

	public Color Color { get; private set; }

	public bool Selected
	{
		get
		{
			return _selected;
		}
		private set
		{
			if (_selected != value)
			{
				_selected = value;
				if (outline != null)
				{
					outline.enabled = _selected;
				}
			}
		}
	}

	private void Start()
	{
		ColorVault colorVault = ((Type != ColorType.Hair) ? SingletonMonoBehaviour<OutfitManager>.Instance.SkinColorVault : SingletonMonoBehaviour<OutfitManager>.Instance.HairColorVault);
		ColorVault.ColorToGuid colorToGuid = colorVault.Find(GuidString);
		if (colorToGuid != null)
		{
			Color = colorToGuid.color;
			image = GetComponent<UnityEngine.UI.Image>();
			if (image != null)
			{
				image.color = Color;
				All.Add(this);
			}
			outline = GetComponent<Outline>();
		}
		else
		{
			UnityEngine.Debug.LogError(string.Concat(this, " has an invalid color guid '", GuidString, ". Check to make sure you have the exact matching guid from the OutfitManager."));
			base.gameObject.SetActive(value: false);
		}
		if (image != null && Player.LocalPlayer != null)
		{
			ColorVault.ColorToGuid colorToGuid2 = ((Type != ColorType.Hair) ? Player.LocalPlayer.PlayerOutfit.SkinColor : Player.LocalPlayer.PlayerOutfit.HairColor);
			Selected = colorToGuid2.guidString == GuidString;
		}
	}

	private void OnDestroy()
	{
		if (All != null && image != null)
		{
			All.Remove(this);
		}
	}

	public static void SetSelected(ColorType type, ColorVault.ColorToGuid colorToGuid)
	{
		foreach (AvatarColor item in All)
		{
			if (item.Type == type)
			{
				item.Selected = item.GuidString == colorToGuid.guidString;
			}
		}
	}
}
public class ColorVault : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class ColorToGuid
	{
		public string guidString;

		public Color color;
	}

	[Tooltip("Used only for decorative purposes.")]
	public string Label = "My Vault";

	public List<ColorToGuid> Colors;

	private Dictionary<string, ColorToGuid> colorMap = new Dictionary<string, ColorToGuid>();

	private void Awake()
	{
		foreach (ColorToGuid color in Colors)
		{
			if (colorMap.ContainsKey(color.guidString))
			{
				UnityEngine.Debug.LogError(string.Concat(this, " vault has duplicate guid for colors : ", color.guidString));
			}
			else
			{
				colorMap.Add(color.guidString, color);
			}
		}
	}

	public ColorToGuid Find(string guidStr)
	{
		if (colorMap.ContainsKey(guidStr))
		{
			return colorMap[guidStr];
		}
		return null;
	}
}
public class Outfit : UnityEngine.MonoBehaviour, IComparable<Outfit>
{
	private static readonly Color pickupHighlightColor = new Color(0.5f, 0.5f, 0.5f, 1f);

	public SkinnedMeshRenderer SkinnedMeshRenderer;

	[Tooltip("This guid is auto generated at the time of the prefab creation and should never change if you do not want to break an existing players outfit selection.")]
	[SerializeField]
	private string guidString = Guid.NewGuid().ToString();

	public OutfitManager.OutfitType Type = OutfitManager.OutfitType.None;

	[Tooltip("if this outfit will be displayed on the rack or not.")]
	public bool DisplayOnRack = true;

	[Tooltip("Defines if this outfit is effected by the global hair color changes.")]
	public bool UsesHairColor;

	[Tooltip("If you want to use a specific highlight material instead of the default emission one, set a material here.")]
	[SerializeField]
	private Material highlightMaterialOverride;

	[Tooltip("Used take off clothes, when disabled this outfit can not be removed by hand.")]
	[SerializeField]
	private bool outfitTriggerEnabled = true;

	[Header("Outfit Tool Settings")]
	[Tooltip("Used by the tool spawner to show an alternate visual on the rack.")]
	public Renderer ToolVisual;

	[Tooltip("This will be used as a sorting suggestion on the rack for the same type of clothes.")]
	[SerializeField]
	protected int preferredIndex;

	[Tooltip("We will group same type of outfits with the same preferred rack, to the corresponding rack if one exists. If not add them to the paging of the first available rack.")]
	public string PreferredRackName = string.Empty;

	[Tooltip("We try to set the position on the rack to be this transform.")]
	public Transform PreferredPivot;

	public Vector3 RackRotationOffsetEuler = Vector3.zero;

	public float RackHeightOffset;

	public Material ToolHighlightMaterialOverride;

	private Material highlightMaterial;

	private Material defaultMaterial;

	private bool _highlight;

	private Guid _guid = Guid.Empty;

	[NonSerialized]
	public Player.BodyPart CurrentBodyPart = Player.BodyPart.None;

	private OutfitTrigger outfitTrigger;

	private bool _enabled = true;

	private bool _visible = true;

	public bool Highlight
	{
		get
		{
			return _highlight;
		}
		set
		{
			if (_highlight != value)
			{
				_highlight = value;
				SkinnedMeshRenderer.material = ((!_highlight) ? defaultMaterial : highlightMaterial);
			}
		}
	}

	public Guid Guid
	{
		get
		{
			if (_guid == Guid.Empty)
			{
				_guid = new Guid(guidString);
			}
			return _guid;
		}
	}

	public int RackIndex { get; set; }

	public Player Owner { get; set; }

	public bool Enabled
	{
		get
		{
			return _enabled;
		}
		set
		{
			_enabled = value;
			if (_enabled)
			{
				Visible = true;
			}
			else
			{
				Visible = Visible;
			}
		}
	}

	public bool Visible
	{
		get
		{
			return _visible && Enabled;
		}
		set
		{
			_visible = value;
			SkinnedMeshRenderer.enabled = Visible;
		}
	}

	private void Awake()
	{
		if (ToolVisual != null)
		{
			ToolVisual.gameObject.SetActive(value: false);
		}
		Visible = false;
	}

	private void Start()
	{
		Visible = true;
		if (UsesHairColor)
		{
			Owner.PlayerOutfit.HairColorChanged += PlayerOutfit_HairColorChanged;
			if (Owner.PlayerOutfit.HairColor != null)
			{
				PlayerOutfit_HairColorChanged(Owner.PlayerOutfit.HairColor.color);
			}
		}
		if (outfitTriggerEnabled && Owner != null && Owner.isLocal && PUNNetworkManager.Instance.IsInDormRoom)
		{
			GameObject gameObject = new GameObject();
			outfitTrigger = gameObject.AddComponent<OutfitTrigger>();
			outfitTrigger.SetOutfitOwner(this);
			Owner.SetParentPlayerRoot(gameObject.transform);
		}
		defaultMaterial = SkinnedMeshRenderer.material;
		if (highlightMaterialOverride == null)
		{
			highlightMaterial = new Material(defaultMaterial);
			highlightMaterial.EnableKeyword("_EMISSION");
			highlightMaterial.SetColor("_EmissionColor", pickupHighlightColor);
		}
		else
		{
			highlightMaterial = highlightMaterialOverride;
		}
		if ((CurrentBodyPart == Player.BodyPart.LeftHand && !Owner.LeftHand.MeshesVisible) || (CurrentBodyPart == Player.BodyPart.RightHand && !Owner.RightHand.MeshesVisible) || !Owner.IsVisible)
		{
			base.gameObject.SetActive(value: false);
		}
	}

	private void OnDestroy()
	{
		if (UsesHairColor && Owner != null)
		{
			Owner.PlayerOutfit.HairColorChanged -= PlayerOutfit_HairColorChanged;
		}
		if (outfitTrigger != null)
		{
			UnityEngine.Object.Destroy(outfitTrigger.gameObject);
		}
	}

	private void PlayerOutfit_HairColorChanged(Color color)
	{
		if (UsesHairColor)
		{
			SkinnedMeshRenderer.material.color = color;
		}
	}

	public void SetTargetSkinnedMesh(SkinnedMeshRenderer targetRenderer)
	{
		Dictionary<string, Transform> dictionary = new Dictionary<string, Transform>();
		Transform[] bones = targetRenderer.bones;
		foreach (Transform transform in bones)
		{
			dictionary[transform.name] = transform;
		}
		Transform[] bones2 = SkinnedMeshRenderer.bones;
		for (int j = 0; j < bones2.Length; j++)
		{
			string text = bones2[j].name;
			if (!dictionary.TryGetValue(text, out bones2[j]))
			{
				UnityEngine.Debug.LogError("Failed to get bone: " + text + " - can not attach to " + targetRenderer, this);
				return;
			}
		}
		SkinnedMeshRenderer.bones = bones2;
		Transform parent = SkinnedMeshRenderer.rootBone.transform.parent;
		Vector3 localScale = parent.localScale;
		localScale.z = Mathf.Abs(localScale.z) * Mathf.Sign(targetRenderer.transform.lossyScale.z);
		parent.localScale = localScale;
	}

	public int CompareTo(Outfit other)
	{
		int type = (int)Type;
		int num = type.CompareTo((int)other.Type);
		return (num == 0) ? preferredIndex.CompareTo(other.preferredIndex) : num;
	}
}
public class OutfitDrawer : UnityEngine.MonoBehaviour
{
	private static List<OutfitDrawer> All = new List<OutfitDrawer>();

	public string Name = string.Empty;

	public OutfitManager.OutfitType OutfitType = OutfitManager.OutfitType.None;

	[SerializeField]
	protected Vector3 rotationOffsetEuler = Vector3.zero;

	[SerializeField]
	protected Transform startTransform;

	[SerializeField]
	[Tooltip("Diameter of the circle.")]
	protected float armLength = 1.35f;

	[Header("Drawer UI")]
	public Button SelectButton;

	public Interpolator DrawerInterpolator;

	public Vector3 DrawerOpenOffset = new Vector3(0f, 0f, -0.15f);

	private RecRoomAudioClip _pagingSound;

	private bool toolVisibilityDirty = true;

	private bool _isSelected;

	protected int maxIndex = -1;

	protected List<OutfitTool> outfitTools;

	private Vector3 defaultDrawerPosition = Vector3.zero;

	private Vector3 defaultButtonDrawerOffset = Vector3.zero;

	private float targetAngle;

	private float currentAngle;

	private float lastSwipeTime;

	private float swipeInterval = 0.3f;

	public RecRoomAudioClip PagingSound
	{
		get
		{
			return _pagingSound;
		}
		set
		{
			_pagingSound = value;
		}
	}

	public bool IsSelected
	{
		get
		{
			return _isSelected;
		}
		set
		{
			if (_isSelected == value)
			{
				return;
			}
			_isSelected = value;
			if (_isSelected)
			{
				foreach (OutfitDrawer item in All)
				{
					if (item != this)
					{
						item.IsSelected = false;
					}
				}
				currentAngle = 0f;
				targetAngle = 0f;
				base.transform.rotation = Quaternion.identity;
			}
			toolVisibilityDirty = true;
			UpdateToolVisibility();
		}
	}

	public int OutfitCount => outfitTools.Count;

	public Transform StartTransform => startTransform;

	public Vector3 OutfitSpawnPosition => SelectButton.transform.position + SelectButton.transform.forward * 0.1f + Vector3.up * 0.05f;

	protected void Awake()
	{
		outfitTools = new List<OutfitTool>();
		if (startTransform == null)
		{
			startTransform = base.transform;
		}
		if (DrawerInterpolator != null && SelectButton != null)
		{
			defaultDrawerPosition = DrawerInterpolator.transform.position;
			defaultButtonDrawerOffset = SelectButton.transform.position - DrawerInterpolator.transform.position;
		}
		All.Add(this);
	}

	private void Update()
	{
		if (DrawerInterpolator != null && SelectButton != null)
		{
			SelectButton.transform.position = defaultButtonDrawerOffset + DrawerInterpolator.transform.position;
		}
		UpdateHandSwipeGesture();
	}

	private void UpdateHandSwipeGesture()
	{
		if (IsSelected && Player.LocalPlayer != null && Player.LocalPlayer.IsInChangingRoom)
		{
			UpdatePerHandSwipe(Player.LocalPlayer.RightHand);
			UpdatePerHandSwipe(Player.LocalPlayer.LeftHand);
		}
		if (targetAngle != currentAngle)
		{
			currentAngle = Mathf.SmoothStep(currentAngle, targetAngle, Time.deltaTime * 8f);
			base.transform.rotation = Quaternion.AngleAxis(currentAngle, Vector3.up);
		}
	}

	private void UpdatePerHandSwipe(PlayerHand hand)
	{
		if (Time.time - lastSwipeTime > swipeInterval && hand != null && hand.IsVisible && !hand.IsHoldingTool)
		{
			Vector3 recentLinearVelocity = hand.TrackedVelocity.RecentLinearVelocity;
			float magnitude = recentLinearVelocity.magnitude;
			float num = Vector3.Angle(hand.PalmDirection, recentLinearVelocity);
			float num2 = Vector3.Angle(Vector3.up, recentLinearVelocity);
			float num3 = Vector3.Angle(Vector3.up, hand.transform.forward);
			if (magnitude > 2f && num <= 30f && Mathf.Abs(90f - num2) <= 15f && Mathf.Abs(90f - num3) <= 15f)
			{
				float num4 = Mathf.Sign(Vector3.Dot(Player.LocalPlayer.Head.transform.right, recentLinearVelocity)) * 90f;
				targetAngle += num4;
				lastSwipeTime = Time.time;
				AudioManager.Play3DSFX(_pagingSound, base.transform.position);
			}
		}
	}

	protected void OnDisable()
	{
		foreach (OutfitTool outfitTool in outfitTools)
		{
			outfitTool.transform.position = startTransform.position;
			outfitTool.transform.rotation = startTransform.rotation;
		}
	}

	protected void OnDestroy()
	{
		All.Remove(this);
	}

	public void UpdateToolVisibility()
	{
		if (toolVisibilityDirty)
		{
			StopAllCoroutines();
			StartCoroutine(RunUpdateToolVisibility());
			toolVisibilityDirty = false;
		}
	}

	private IEnumerator RunUpdateToolVisibility()
	{
		if (DrawerInterpolator != null)
		{
			DrawerInterpolator.TargetPosition = defaultDrawerPosition + ((!_isSelected) ? Vector3.zero : DrawerOpenOffset);
		}
		if (!IsSelected)
		{
			foreach (OutfitTool item in outfitTools)
			{
				item.AnimateIn = false;
				yield return null;
			}
			yield break;
		}
		for (int i = outfitTools.Count - 1; i >= 0; i--)
		{
			outfitTools[i].transform.position = OutfitSpawnPosition;
			outfitTools[i].AnimateIn = true;
			outfitTools[i].StartMovingBack();
			yield return new WaitForSeconds(0.075f);
		}
	}

	protected Vector3 GetPosition(Outfit outfit, int index, int maxCount)
	{
		Vector3 vector = Vector3.zero;
		if (outfit != null)
		{
			outfit.RackIndex = index;
			if (outfit.PreferredPivot != null)
			{
				vector = outfit.PreferredPivot.position - outfit.transform.position;
				vector.z = 0f;
			}
		}
		float num = 360 / maxCount;
		Quaternion quaternion = Quaternion.AngleAxis((float)(index + 1) * num, Vector3.up);
		Vector3 position = startTransform.position + quaternion * (base.transform.forward * armLength + vector) + outfit.RackHeightOffset * Vector3.up;
		return StartTransform.InverseTransformPoint(position);
	}

	protected Quaternion GetRotation(Outfit outfit, Vector3 position)
	{
		Vector3 vector = StartTransform.TransformPoint(position);
		Vector3 forward = vector - startTransform.position;
		return Quaternion.LookRotation(forward) * Quaternion.Euler(rotationOffsetEuler) * Quaternion.Euler(outfit.RackRotationOffsetEuler);
	}

	public bool IsOutfitToolVisible(OutfitTool tool)
	{
		return IsSelected;
	}

	public void UpdateOutfitPlacement()
	{
		for (int i = 0; i < outfitTools.Count; i++)
		{
			outfitTools[i].DrawerIndex = i;
			outfitTools[i].DrawerPosition = GetPosition(outfitTools[i].OutfitTarget, i, outfitTools.Count);
			outfitTools[i].DrawerRotation = GetRotation(outfitTools[i].OutfitTarget, outfitTools[i].DrawerPosition);
			outfitTools[i].gameObject.SetActive(value: true);
		}
	}

	public void AddOutfit(Outfit prefab)
	{
		GameObject gameObject = new GameObject(prefab.name + "_OutfitTool");
		gameObject.transform.position = startTransform.position;
		gameObject.transform.rotation = startTransform.rotation;
		gameObject.transform.SetParent(StartTransform, worldPositionStays: true);
		Renderer original = ((!(prefab.ToolVisual != null)) ? prefab.SkinnedMeshRenderer : prefab.ToolVisual);
		Renderer renderer = UnityEngine.Object.Instantiate(original);
		renderer.transform.SetParent(gameObject.transform, worldPositionStays: false);
		Collider collider = renderer.GetComponent<Collider>();
		if (collider == null)
		{
			collider = renderer.gameObject.AddComponent<BoxCollider>();
		}
		renderer.gameObject.AddComponent<ToolCollider>();
		Renderer renderer2 = UnityEngine.Object.Instantiate(original);
		renderer2.transform.SetParent(gameObject.transform, worldPositionStays: false);
		renderer2.gameObject.SetActive(value: false);
		renderer2.name = "ToolVisual_ghost";
		BoxCollider boxCollider = renderer2.gameObject.AddComponent<BoxCollider>();
		boxCollider.isTrigger = true;
		renderer2.gameObject.AddComponent<ToolCollider>();
		Material[] array = new Material[renderer2.materials.Length];
		for (int i = 0; i < renderer2.materials.Length; i++)
		{
			array[i] = SingletonMonoBehaviour<OutfitManager>.Instance.OutfitGhostMaterial;
		}
		renderer2.materials = array;
		Rigidbody rigidbody = gameObject.gameObject.AddComponent<Rigidbody>();
		rigidbody.useGravity = false;
		OutfitTool outfitTool = gameObject.gameObject.AddComponent<OutfitTool>();
		outfitTool.OutfitTarget = prefab;
		outfitTool.Drawer = this;
		outfitTool.DrawerIndex = 0;
		outfitTool.ToolCollider = collider;
		outfitTool.GhostVisual = renderer2;
		outfitTool.GhostCollider = boxCollider;
		ToolRenderer component = outfitTool.GetComponent<ToolRenderer>();
		component.SetupRenderer(renderer, prefab.ToolHighlightMaterialOverride);
		gameObject.gameObject.SetLayerRecursively(Layers.DynamicPhysics);
		gameObject.gameObject.SetActive(value: false);
		outfitTools.Add(outfitTool);
	}
}
public class OutfitManager : SingletonMonoBehaviour<OutfitManager>
{
	public enum OutfitType
	{
		None = -1,
		Hat = 0,
		BackHead = 1,
		Hair = 2,
		Eye = 10,
		Mouth = 20,
		Neck = 100,
		Shirt = 101,
		Belt = 102,
		Pocket = 103,
		TeamJersey = 104,
		Wrist = 200,
		Glove = 201,
		Watch = 202,
		TeamWrist = 203
	}

	[Serializable]
	public class OutfitToBodyPart
	{
		public Outfit outfit;

		public Player.BodyPart bodyPart;
	}

	[SerializeField]
	private List<Outfit> outfitPrefabs = new List<Outfit>();

	[SerializeField]
	[Tooltip("Minimum default set of outfits for players.")]
	private List<OutfitToBodyPart> defaultOutfits = new List<OutfitToBodyPart>();

	[Tooltip("Minimum default set of outfits for players.")]
	public List<OutfitToBodyPart> TeamOutfits = new List<OutfitToBodyPart>();

	[Tooltip("Set of outfits for our moderators.")]
	[SerializeField]
	private List<OutfitToBodyPart> moderatorOutfits = new List<OutfitToBodyPart>();

	public Material OutfitGhostMaterial;

	[Header("Sounds")]
	[SerializeField]
	private RecRoomAudioClip[] equipSounds;

	[SerializeField]
	private RecRoomAudioClip[] unEquipSounds;

	[SerializeField]
	private RecRoomAudioClip[] pageSounds;

	[Header("Colors")]
	public ColorVault SkinColorVault;

	public ColorVault HairColorVault;

	private Dictionary<OutfitType, List<Outfit>> outfitTypeMap;

	public List<OutfitToBodyPart> ModeratorOutfits => moderatorOutfits;

	public List<Outfit> OutfitPrefabs => outfitPrefabs;

	public RecRoomAudioClip[] EquipSounds => equipSounds;

	public RecRoomAudioClip[] UnEquipSounds => unEquipSounds;

	public RecRoomAudioClip[] PageSounds => pageSounds;

	private void Awake()
	{
		SingletonMonoBehaviour<OutfitManager>.Instance = this;
		InitializeOutfitTypeMap();
	}

	private void InitializeOutfitTypeMap()
	{
		outfitTypeMap = new Dictionary<OutfitType, List<Outfit>>();
		List<IGrouping<OutfitType, Outfit>> list = (from o in outfitPrefabs
			where o != null
			group o by o.Type into oType
			select (oType)).Distinct().ToList();
		foreach (IGrouping<OutfitType, Outfit> item in list)
		{
			OutfitType type = item.Key;
			List<Outfit> value = (from o in outfitPrefabs
				where o != null
				where o.Type == type && o.DisplayOnRack
				select o).ToList();
			outfitTypeMap.Add(type, value);
		}
	}

	public Outfit GetOutfit(string guidString)
	{
		return GetOutfit(new Guid(guidString));
	}

	public Outfit GetOutfit(Guid guid)
	{
		foreach (Outfit outfitPrefab in outfitPrefabs)
		{
			if (outfitPrefab != null && outfitPrefab.Guid == guid)
			{
				return outfitPrefab;
			}
		}
		return null;
	}

	public List<OutfitToBodyPart> GetMissingOutfitsFromDefaultSet(List<Outfit> currentOutfits)
	{
		List<OutfitToBodyPart> list = new List<OutfitToBodyPart>();
		foreach (OutfitToBodyPart defaultOutfit in defaultOutfits)
		{
			bool flag = false;
			foreach (Outfit currentOutfit in currentOutfits)
			{
				if (currentOutfit.Type == defaultOutfit.outfit.Type && currentOutfit.CurrentBodyPart == defaultOutfit.bodyPart)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				list.Add(defaultOutfit);
			}
		}
		return list;
	}

	public static Player.BodyPart GetMatchingBodyPart(OutfitType outfitType)
	{
		Player.BodyPart result = Player.BodyPart.Head;
		switch (outfitType)
		{
		case OutfitType.Hat:
		case OutfitType.BackHead:
		case OutfitType.Hair:
		case OutfitType.Eye:
		case OutfitType.Mouth:
			result = Player.BodyPart.Head;
			break;
		case OutfitType.Neck:
		case OutfitType.Shirt:
		case OutfitType.Belt:
		case OutfitType.Pocket:
		case OutfitType.TeamJersey:
			result = Player.BodyPart.Torso;
			break;
		case OutfitType.Wrist:
		case OutfitType.Glove:
		case OutfitType.Watch:
		case OutfitType.TeamWrist:
			result = Player.BodyPart.LeftHand;
			break;
		}
		return result;
	}

	public static bool IsTeamOutfit(OutfitType outfitType)
	{
		return outfitType == OutfitType.TeamJersey || outfitType == OutfitType.TeamWrist;
	}

	public static bool IsRequiredOutfitType(OutfitType outfitType)
	{
		return outfitType == OutfitType.Shirt || outfitType == OutfitType.Wrist;
	}

	public static bool IsMatchingBodyPart(Player.BodyPart bodyPart, OutfitType outfitType)
	{
		Player.BodyPart matchingBodyPart = GetMatchingBodyPart(outfitType);
		return matchingBodyPart == bodyPart || (matchingBodyPart == Player.BodyPart.LeftHand && bodyPart == Player.BodyPart.RightHand);
	}

	public void RandomizePlayerOutfit()
	{
		if (!(Player.LocalPlayer != null) || !(Player.LocalPlayer.PlayerOutfit != null))
		{
			return;
		}
		List<OutfitToBodyPart> list = new List<OutfitToBodyPart>();
		foreach (KeyValuePair<OutfitType, List<Outfit>> item in outfitTypeMap)
		{
			OutfitType key = item.Key;
			List<Outfit> value = item.Value;
			if ((IsRequiredOutfitType(key) || !(UnityEngine.Random.value > ((value.Count < 5) ? 0.3f : 0.6f))) && value.Count > 0)
			{
				Outfit outfit = value.Random();
				Player.BodyPart matchingBodyPart = GetMatchingBodyPart(outfit.Type);
				list.Add(new OutfitToBodyPart
				{
					bodyPart = matchingBodyPart,
					outfit = outfit
				});
				if (matchingBodyPart == Player.BodyPart.LeftHand && (outfit.Type == OutfitType.Wrist || outfit.Type == OutfitType.Glove))
				{
					list.Add(new OutfitToBodyPart
					{
						bodyPart = Player.BodyPart.RightHand,
						outfit = outfit
					});
				}
			}
		}
		Player.LocalPlayer.PlayerOutfit.UnEquipAll();
		foreach (OutfitToBodyPart item2 in list)
		{
			Player.LocalPlayer.PlayerOutfit.SetOutfit(item2.outfit, item2.bodyPart);
		}
	}

	public ColorVault.ColorToGuid FindHairColor(string hairColorGuid)
	{
		return FindColorFromVault(HairColorVault, hairColorGuid);
	}

	public ColorVault.ColorToGuid FindSkinColor(string skinColorGuid)
	{
		return FindColorFromVault(SkinColorVault, skinColorGuid);
	}

	private ColorVault.ColorToGuid FindColorFromVault(ColorVault vault, string colorGuid)
	{
		ColorVault.ColorToGuid colorToGuid = vault.Find(colorGuid);
		if (colorToGuid == null)
		{
			colorToGuid = vault.Colors.Random();
			if (!string.IsNullOrEmpty(colorGuid))
			{
				UnityEngine.Debug.LogWarning(string.Concat("Outfit Manager FindColor in ", vault, " can't find matching color for the guid ", colorGuid, ". Getting a random one."));
			}
		}
		return colorToGuid;
	}
}
public class OutfitToolSpawner : UnityEngine.MonoBehaviour
{
	public OutfitDrawer[] Drawers;

	[Header("Audio")]
	public RecRoomAudioClip openDrawer;

	public RecRoomAudioClip pagingSound;

	private Dictionary<OutfitManager.OutfitType, Dictionary<string, OutfitDrawer>> drawerMap = new Dictionary<OutfitManager.OutfitType, Dictionary<string, OutfitDrawer>>();

	private IEnumerator Start()
	{
		InitializeDrawerMap();
		Canvas canvas = GetComponentInChildren<Canvas>();
		if (canvas != null)
		{
			canvas.worldCamera = ViveControllerInput.Instance.ControllerCamera;
		}
		StartCoroutine(RunInitializeOutfitTools());
		while (Player.LocalPlayer == null)
		{
			yield return null;
		}
		Player.LocalPlayer.IsInChangingRoomUpdated += LocalPlayer_IsInChangingRoomUpdated;
		OutfitDrawer[] drawers = Drawers;
		foreach (OutfitDrawer drawer in drawers)
		{
			if (drawer != null)
			{
				drawer.SelectButton.interactable = true;
				drawer.PagingSound = pagingSound;
			}
		}
	}

	private void LocalPlayer_IsInChangingRoomUpdated(bool inChangingRoom)
	{
		if (inChangingRoom)
		{
			return;
		}
		OutfitDrawer[] drawers = Drawers;
		foreach (OutfitDrawer outfitDrawer in drawers)
		{
			if (outfitDrawer != null)
			{
				outfitDrawer.IsSelected = false;
			}
		}
	}

	private IEnumerator RunInitializeOutfitTools()
	{
		while (!SingletonMonoBehaviour<OutfitManager>.IsInitialized || Player.LocalPlayer == null)
		{
			yield return null;
		}
		foreach (Outfit prefab in SingletonMonoBehaviour<OutfitManager>.Instance.OutfitPrefabs)
		{
			if (prefab != null && prefab.DisplayOnRack)
			{
				OutfitDrawer drawer = GetRack(prefab);
				if (drawer == null)
				{
					UnityEngine.Debug.LogWarning(string.Concat("OutfitToolSpawner does not have a drawer for outfit type ", prefab.Type, ". Failed to spawn", prefab));
				}
				else
				{
					drawer.AddOutfit(prefab);
					yield return null;
				}
			}
		}
		OutfitDrawer[] drawers = Drawers;
		foreach (OutfitDrawer drawer2 in drawers)
		{
			drawer2.UpdateOutfitPlacement();
		}
	}

	private void InitializeDrawerMap()
	{
		for (int i = 0; i < Drawers.Length; i++)
		{
			if (drawerMap.ContainsKey(Drawers[i].OutfitType))
			{
				Dictionary<string, OutfitDrawer> dictionary = drawerMap[Drawers[i].OutfitType];
				if (string.IsNullOrEmpty(Drawers[i].Name) || dictionary.ContainsKey(Drawers[i].Name))
				{
					Drawers[i].Name = Guid.NewGuid().ToString();
				}
				dictionary.Add(Drawers[i].Name, Drawers[i]);
				continue;
			}
			Dictionary<string, OutfitDrawer> dictionary2 = new Dictionary<string, OutfitDrawer>();
			if (string.IsNullOrEmpty(Drawers[i].Name))
			{
				Drawers[i].Name = Guid.NewGuid().ToString();
			}
			dictionary2.Add(Drawers[i].Name, Drawers[i]);
			drawerMap.Add(Drawers[i].OutfitType, dictionary2);
		}
	}

	private OutfitDrawer GetRack(Outfit outfitPrefab)
	{
		if (!drawerMap.ContainsKey(outfitPrefab.Type))
		{
			return null;
		}
		Dictionary<string, OutfitDrawer> dictionary = drawerMap[outfitPrefab.Type];
		if (dictionary.ContainsKey(outfitPrefab.PreferredRackName))
		{
			return dictionary[outfitPrefab.PreferredRackName];
		}
		if (!string.IsNullOrEmpty(outfitPrefab.PreferredRackName))
		{
			OutfitDrawer[] drawers = Drawers;
			foreach (OutfitDrawer outfitDrawer in drawers)
			{
				if (outfitPrefab.PreferredRackName == outfitDrawer.Name)
				{
					return outfitDrawer;
				}
			}
		}
		if (dictionary.Count > 0)
		{
			return dictionary.Values.First();
		}
		return null;
	}

	public void Button_RackSelected(Button button)
	{
		OutfitDrawer[] drawers = Drawers;
		foreach (OutfitDrawer outfitDrawer in drawers)
		{
			if (outfitDrawer != null && outfitDrawer.SelectButton == button)
			{
				AudioManager.Play3DSFX(openDrawer, base.transform.position);
				outfitDrawer.IsSelected = !outfitDrawer.IsSelected;
				break;
			}
		}
	}
}
public class OutfitTrigger : UnityEngine.MonoBehaviour
{
	private BoxCollider boxCollider;

	public Outfit Outfit { get; private set; }

	public Transform TargetBone { get; set; }

	private void Awake()
	{
		UnityEngine.Object.DontDestroyOnLoad(this);
	}

	public void SetOutfitOwner(Outfit outfit)
	{
		Outfit = outfit;
		TargetBone = outfit.SkinnedMeshRenderer.bones[0];
		if (boxCollider != null)
		{
			UnityEngine.Object.Destroy(boxCollider);
			boxCollider = null;
		}
		boxCollider = base.gameObject.AddComponent<BoxCollider>();
		boxCollider.size = outfit.SkinnedMeshRenderer.bounds.size;
		boxCollider.isTrigger = true;
		boxCollider.tag = "Outfit";
		base.gameObject.layer = 15;
		base.name = outfit.name + "_trigger";
	}

	private void LateUpdate()
	{
		if (Outfit != null && TargetBone != null && Player.LocalPlayer != null && Player.LocalPlayer.IsInChangingRoom)
		{
			base.transform.position = Outfit.SkinnedMeshRenderer.bounds.center;
			base.transform.rotation = TargetBone.rotation;
		}
	}
}
[DisallowMultipleComponent]
public class PlayerOutfit : Photon.MonoBehaviour
{
	public struct OutfitGuidToBody : IEquatable<OutfitGuidToBody>
	{
		public Guid guid;

		public Player.BodyPart bodyPart;

		public OutfitGuidToBody(Guid g, Player.BodyPart b)
		{
			guid = g;
			bodyPart = b;
		}

		public bool Equals(OutfitGuidToBody other)
		{
			return other.guid == guid && other.bodyPart == bodyPart;
		}

		public override string ToString()
		{
			return guid.ToString() + "," + (int)bodyPart;
		}
	}

	public static readonly string PlayerHairColorProperty = "PlayerHairColorProperty";

	public static readonly string PlayerSkinColorProperty = "PlayerSkinColorProperty";

	public static readonly string PlayerOutFitProperty = "PlayerOutFitProperty";

	public static readonly string PlayerOutFitVersionProperty = "PlayerOutFitPropertyVersion";

	public static readonly string PlayerOutFitVersion = "5/12/2016";

	public bool PersistOutfitSelection = true;

	[SerializeField]
	private SkinnedMeshRenderer face;

	[SerializeField]
	private SkinnedMeshRenderer eyes;

	[SerializeField]
	private SkinnedMeshRenderer mouth;

	[SerializeField]
	private SkinnedMeshRenderer torso;

	[SerializeField]
	private SkinnedMeshRenderer leftHand;

	[SerializeField]
	private SkinnedMeshRenderer rightHand;

	[HideInInspector]
	public Player ThisPlayer;

	private ColorVault.ColorToGuid _hairColor;

	private ColorVault.ColorToGuid _skinColor;

	private Color? _teamIndicator;

	private List<Outfit> outfits = new List<Outfit>();

	private Dictionary<OutfitGuidToBody, Outfit> outfitGuidMap = new Dictionary<OutfitGuidToBody, Outfit>();

	private PlayerData playerData;

	private bool snapShotReady;

	private Dictionary<OutfitGuidToBody, Outfit> savedOutfitGuidMap = new Dictionary<OutfitGuidToBody, Outfit>();

	private string savedHairColorGuid = string.Empty;

	private string savedSkinColorGuid = string.Empty;

	public ColorVault.ColorToGuid HairColor
	{
		get
		{
			return _hairColor;
		}
		private set
		{
			_hairColor = value;
			if (base.isLocal)
			{
				AvatarColor.SetSelected(AvatarColor.ColorType.Hair, _hairColor);
				if (ThisPlayer.IsInChangingRoom)
				{
					AnalyticsHelper.AvatarHairColor(_hairColor);
				}
			}
			if (this.HairColorChanged != null)
			{
				this.HairColorChanged(_hairColor.color);
			}
		}
	}

	public ColorVault.ColorToGuid SkinColor
	{
		get
		{
			return _skinColor;
		}
		private set
		{
			_skinColor = value;
			if (base.isLocal)
			{
				AvatarColor.SetSelected(AvatarColor.ColorType.Skin, _skinColor);
				if (ThisPlayer.IsInChangingRoom)
				{
					AnalyticsHelper.AvatarSkinColor(_skinColor);
				}
			}
			face.material.color = _skinColor.color;
			torso.material.color = _skinColor.color;
			leftHand.material.color = _skinColor.color;
			rightHand.material.color = _skinColor.color;
		}
	}

	public Color? TeamIndicator
	{
		get
		{
			return _teamIndicator;
		}
		set
		{
			Color? teamIndicator = _teamIndicator;
			if (teamIndicator.GetValueOrDefault() != value.GetValueOrDefault() || (teamIndicator.HasValue ^ value.HasValue))
			{
				_teamIndicator = value;
				UpdateTeamOutfits();
			}
		}
	}

	public event Action<Color> HairColorChanged;

	private void Awake()
	{
		playerData = GetComponent<PlayerData>();
	}

	private void Start()
	{
		playerData.RegisterCallback(PlayerSkinColorProperty, OnPlayerSkinColorChanged);
		playerData.RegisterCallback(PlayerHairColorProperty, OnPlayerHairColorChanged);
		playerData.RegisterCallback(PlayerOutFitProperty, OnPlayerOutfitChanged);
		if (base.isLocal)
		{
			bool flag = true;
			bool flag2 = true;
			bool flag3 = true;
			if (PersistOutfitSelection)
			{
				string text = RecroomPrefs.GetString(PlayerOutFitVersionProperty, string.Empty);
				if (string.IsNullOrEmpty(text) || text != PlayerOutFitVersion)
				{
					RecroomPrefs.DeleteKey(PlayerSkinColorProperty);
					RecroomPrefs.DeleteKey(PlayerHairColorProperty);
					RecroomPrefs.DeleteKey(PlayerOutFitProperty);
					RecroomPrefs.SetString(PlayerOutFitVersionProperty, PlayerOutFitVersion);
					UnityEngine.Debug.LogWarning("PlayerOutfits has version change. Removing saved outfit selections and reverting to default.");
					RecroomPrefs.Save();
				}
				else
				{
					string text2 = RecroomPrefs.GetString(PlayerSkinColorProperty, string.Empty);
					if (!string.IsNullOrEmpty(text2))
					{
						playerData.SetData(PlayerSkinColorProperty, text2);
						flag2 = false;
					}
					string text3 = RecroomPrefs.GetString(PlayerHairColorProperty, string.Empty);
					if (!string.IsNullOrEmpty(text3))
					{
						playerData.SetData(PlayerHairColorProperty, text3);
						flag3 = false;
					}
					string text4 = RecroomPrefs.GetString(PlayerOutFitProperty, string.Empty);
					if (!string.IsNullOrEmpty(text4))
					{
						playerData.SetData(PlayerOutFitProperty, text4);
						flag = false;
					}
				}
			}
			if (flag3)
			{
				SetHairColor(SingletonMonoBehaviour<OutfitManager>.Instance.FindHairColor(string.Empty).guidString);
			}
			if (flag2)
			{
				SetSkinColor(SingletonMonoBehaviour<OutfitManager>.Instance.FindSkinColor(string.Empty).guidString);
			}
			if (flag)
			{
				SingletonMonoBehaviour<OutfitManager>.Instance.RandomizePlayerOutfit();
			}
			EquipDefaultOutfitSetForMissing();
			if (ActivityManager.Instance.SupportsPlayingGame)
			{
				EquipTeamOutfits();
			}
		}
		else
		{
			OnPlayerOutfitChanged(null, null);
			OnPlayerSkinColorChanged(null, null);
			OnPlayerHairColorChanged(null, null);
		}
		ThisPlayer.VisibilityChanged += ThisPlayer_VisibilityChanged;
		ThisPlayer.IsInChangingRoomUpdated += ThisPlayer_IsInChangingRoomUpdated;
	}

	private void EquipTeamOutfits()
	{
		foreach (OutfitManager.OutfitToBodyPart teamOutfit in SingletonMonoBehaviour<OutfitManager>.Instance.TeamOutfits)
		{
			SetOutfit(teamOutfit.outfit, teamOutfit.bodyPart);
		}
	}

	private void ThisPlayer_VisibilityChanged(bool visible)
	{
		if (base.isLocal)
		{
			return;
		}
		foreach (Outfit outfit in outfits)
		{
			outfit.gameObject.SetActive(visible);
		}
	}

	private void ThisPlayer_IsInChangingRoomUpdated(bool entered)
	{
		if (base.isLocal && entered)
		{
			SnapShotSelection();
		}
	}

	private void OnDestroy()
	{
		Outfit[] array = outfits.ToArray();
		foreach (Outfit outfit in array)
		{
			if (outfit != null)
			{
				UnityEngine.Object.Destroy(outfit.gameObject);
			}
		}
		outfits.Clear();
		ThisPlayer.VisibilityChanged -= ThisPlayer_VisibilityChanged;
		ThisPlayer.IsInChangingRoomUpdated -= ThisPlayer_IsInChangingRoomUpdated;
	}

	private void OnPlayerSkinColorChanged(PlayerData sender, string key)
	{
		string data = playerData.GetData(PlayerSkinColorProperty, string.Empty);
		ColorVault.ColorToGuid skinColor = SingletonMonoBehaviour<OutfitManager>.Instance.FindSkinColor(data);
		SkinColor = skinColor;
	}

	private void OnPlayerHairColorChanged(PlayerData sender, string key)
	{
		string data = playerData.GetData(PlayerHairColorProperty, string.Empty);
		ColorVault.ColorToGuid hairColor = SingletonMonoBehaviour<OutfitManager>.Instance.FindHairColor(data);
		HairColor = hairColor;
	}

	private void OnPlayerOutfitChanged(PlayerData sender, string key)
	{
		string data = playerData.GetData(PlayerOutFitProperty, string.Empty);
		ParseOutfitString(data);
	}

	private void EquipDefaultOutfitSetForMissing()
	{
		List<OutfitManager.OutfitToBodyPart> missingOutfitsFromDefaultSet = SingletonMonoBehaviour<OutfitManager>.Instance.GetMissingOutfitsFromDefaultSet(outfits);
		foreach (OutfitManager.OutfitToBodyPart item in missingOutfitsFromDefaultSet)
		{
			SetOutfit(item.outfit, item.bodyPart);
		}
	}

	private void UpdateTeamOutfits()
	{
		bool hasValue = TeamIndicator.HasValue;
		foreach (Outfit outfit in outfits)
		{
			if (OutfitManager.IsTeamOutfit(outfit.Type))
			{
				outfit.Enabled = hasValue;
				if (hasValue)
				{
					outfit.SkinnedMeshRenderer.material.color = TeamIndicator.Value;
				}
			}
			else
			{
				Player.BodyPart matchingBodyPart = OutfitManager.GetMatchingBodyPart(outfit.Type);
				if (matchingBodyPart.IsHand())
				{
					outfit.Enabled = !hasValue;
				}
			}
		}
	}

	public string GetOutfitNameList()
	{
		string text = string.Empty;
		for (int i = 0; i < outfits.Count; i++)
		{
			text = text + outfits[i].name + ((i == outfits.Count - 1) ? string.Empty : ",");
		}
		return text;
	}

	public void UnEquipAll()
	{
		Outfit[] array = outfits.ToArray();
		foreach (Outfit outfit in array)
		{
			UnEquipOutfit(outfit);
		}
	}

	public void ResetOutfitSelectionToDefault()
	{
		UnEquipAll();
		EquipDefaultOutfitSetForMissing();
	}

	public void SetHandVisible(PlayerHand.HandType type, bool isVisible)
	{
		int num;
		switch (type)
		{
		case PlayerHand.HandType.Unknown:
			return;
		case PlayerHand.HandType.Left:
			num = 2;
			break;
		default:
			num = 3;
			break;
		}
		Player.BodyPart bodyPart = (Player.BodyPart)num;
		foreach (Outfit outfit in outfits)
		{
			if (outfit.CurrentBodyPart == bodyPart)
			{
				outfit.gameObject.SetActive(isVisible && ThisPlayer.IsVisible);
			}
		}
	}

	public void SetSkinColor(string colorGuid)
	{
		playerData.SetData(PlayerSkinColorProperty, colorGuid);
		if (PersistOutfitSelection)
		{
			RecroomPrefs.SetString(PlayerSkinColorProperty, colorGuid);
			RecroomPrefs.Save();
		}
	}

	public void SetHairColor(string colorGuid)
	{
		playerData.SetData(PlayerHairColorProperty, colorGuid);
		if (PersistOutfitSelection)
		{
			RecroomPrefs.SetString(PlayerHairColorProperty, colorGuid);
			RecroomPrefs.Save();
		}
	}

	public bool SetOutfit(Outfit outfitPrefab, Player.BodyPart bodyPart, bool playAudio = false)
	{
		OutfitGuidToBody outfitGuidToBody = new OutfitGuidToBody(outfitPrefab.Guid, bodyPart);
		if (outfitGuidMap.ContainsKey(outfitGuidToBody))
		{
			return false;
		}
		Outfit[] array = outfits.ToArray();
		foreach (Outfit outfit in array)
		{
			if (outfit.Type == outfitPrefab.Type && outfit.CurrentBodyPart == bodyPart && outfit.Guid != outfitPrefab.Guid)
			{
				UnEquipOutfit(outfit);
			}
		}
		string text = SerializeOutfitsString(outfitGuidToBody);
		playerData.SetData(PlayerOutFitProperty, text);
		if (PersistOutfitSelection)
		{
			RecroomPrefs.SetString(PlayerOutFitProperty, text);
		}
		if (playAudio)
		{
			AudioManager.PlayRandom3DSFX(SingletonMonoBehaviour<OutfitManager>.Instance.EquipSounds, base.transform.position);
		}
		ThisPlayer.PlayerEvents.OutfitEquipped(bodyPart);
		return true;
	}

	public bool RemoveOutfit(Outfit outfit, bool playAudio = false)
	{
		OutfitGuidToBody key = new OutfitGuidToBody(outfit.Guid, outfit.CurrentBodyPart);
		if (!outfitGuidMap.ContainsKey(key))
		{
			return false;
		}
		outfitGuidMap.Remove(key);
		string text = SerializeOutfitsString();
		playerData.SetData(PlayerOutFitProperty, text);
		if (PersistOutfitSelection)
		{
			RecroomPrefs.SetString(PlayerOutFitProperty, text);
		}
		if (playAudio)
		{
			AudioManager.PlayRandom3DSFX(SingletonMonoBehaviour<OutfitManager>.Instance.UnEquipSounds, base.transform.position);
		}
		return true;
	}

	private string SerializeOutfitsString([Optional] OutfitGuidToBody outfitGuidToBody)
	{
		string text = string.Empty;
		foreach (OutfitGuidToBody key in outfitGuidMap.Keys)
		{
			text = text + key.ToString() + ";";
		}
		if (outfitGuidToBody.guid != Guid.Empty)
		{
			text += outfitGuidToBody.ToString();
		}
		return text;
	}

	private Dictionary<OutfitGuidToBody, bool> ParseOutfitMapString(string newMapString)
	{
		Dictionary<OutfitGuidToBody, bool> dictionary = new Dictionary<OutfitGuidToBody, bool>();
		string[] array = newMapString.Split(';');
		string[] array2 = array;
		foreach (string text in array2)
		{
			if (!string.IsNullOrEmpty(text))
			{
				string[] array3 = text.Split(',');
				if (array3.Length == 2)
				{
					Guid g = new Guid(array3[0]);
					int b = int.Parse(array3[1]);
					dictionary.Add(new OutfitGuidToBody(g, (Player.BodyPart)b), value: true);
				}
				else
				{
					UnityEngine.Debug.LogError("PlayerOutfit outfit map parse error, can not parse " + text);
				}
			}
		}
		return dictionary;
	}

	private void ParseOutfitString(string newMapString)
	{
		bool flag = false;
		Dictionary<OutfitGuidToBody, bool> dictionary = ParseOutfitMapString(newMapString);
		Outfit[] array = outfits.ToArray();
		foreach (Outfit outfit in array)
		{
			if (!dictionary.ContainsKey(new OutfitGuidToBody(outfit.Guid, outfit.CurrentBodyPart)))
			{
				UnEquipOutfit(outfit);
			}
		}
		foreach (OutfitGuidToBody key in dictionary.Keys)
		{
			if (key.guid != Guid.Empty)
			{
				Outfit outfit2 = SingletonMonoBehaviour<OutfitManager>.Instance.GetOutfit(key.guid);
				if (outfit2 != null && !outfitGuidMap.ContainsKey(key))
				{
					EquipOutfit(outfit2, key.bodyPart);
					flag = true;
				}
			}
		}
		if (base.isLocal && flag && PersistOutfitSelection)
		{
			RecroomPrefs.Save();
		}
		UpdateTeamOutfits();
	}

	private void UnEquipOutfit(Outfit outfit)
	{
		outfits.Remove(outfit);
		ThisPlayer.AnimateInOut.additionalRenderers.Remove(outfit.SkinnedMeshRenderer);
		OutfitGuidToBody key = new OutfitGuidToBody(outfit.Guid, outfit.CurrentBodyPart);
		if (outfitGuidMap.ContainsKey(key))
		{
			outfitGuidMap.Remove(key);
		}
		if (base.isLocal)
		{
			OutfitTool outfitTool = OutfitTool.Find(outfit.Guid);
			if (outfitTool != null)
			{
				outfitTool.IsUsedByPlayer = false;
			}
			if (ThisPlayer.IsInChangingRoom)
			{
				AnalyticsHelper.AvatarOutfitEquip(outfit, outfit.CurrentBodyPart, equip: false);
			}
		}
		UnityEngine.Object.Destroy(outfit.gameObject);
	}

	private void EquipOutfit(Guid outfitGuid, Player.BodyPart bodyPart)
	{
		EquipOutfit(SingletonMonoBehaviour<OutfitManager>.Instance.GetOutfit(outfitGuid), bodyPart);
	}

	private void EquipOutfit(Outfit prefab, Player.BodyPart bodyPart)
	{
		InstantiateNewOutfitPrefab(prefab, bodyPart);
		if (base.isLocal)
		{
			OutfitTool outfitTool = OutfitTool.Find(prefab.Guid);
			if (outfitTool != null)
			{
				outfitTool.IsUsedByPlayer = true;
			}
			if (ThisPlayer.IsInChangingRoom)
			{
				AnalyticsHelper.AvatarOutfitEquip(prefab, bodyPart, equip: true);
			}
		}
	}

	public Outfit InstantiateNewOutfitPrefab(Outfit prefab, Player.BodyPart bodyPart, bool ownedByPlayerOutfit = true)
	{
		Outfit outfit = UnityEngine.Object.Instantiate(prefab);
		outfit.Type = prefab.Type;
		outfit.CurrentBodyPart = bodyPart;
		outfit.Owner = ThisPlayer;
		if (ownedByPlayerOutfit)
		{
			OutfitGuidToBody key = new OutfitGuidToBody(outfit.Guid, outfit.CurrentBodyPart);
			if (!outfitGuidMap.ContainsKey(key))
			{
				outfitGuidMap.Add(key, outfit);
			}
			outfits.Add(outfit);
			ThisPlayer.AnimateInOut.additionalRenderers.Add(outfit.SkinnedMeshRenderer);
		}
		SetOutfitTarget(outfit);
		SetOutFitLayer(outfit);
		if (!base.isLocal)
		{
			outfit.gameObject.SetActive(ThisPlayer.IsVisible);
		}
		ThisPlayer.SetParentPlayerRoot(outfit.transform);
		return outfit;
	}

	private void SetOutFitLayer(Outfit outfit)
	{
		Layers layer = Layers.RemotePlayerPhysics;
		if (base.isLocal)
		{
			layer = ((!outfit.CurrentBodyPart.IsHand()) ? Layers.HiddenInFirstPerson : Layers.LocalPlayerPhysics);
		}
		outfit.gameObject.SetLayerRecursively(layer);
	}

	private void SetOutfitTarget(Outfit newOutfit)
	{
		SkinnedMeshRenderer targetSkinnedMesh = null;
		switch (newOutfit.Type)
		{
		case OutfitManager.OutfitType.Hat:
		case OutfitManager.OutfitType.BackHead:
		case OutfitManager.OutfitType.Hair:
			targetSkinnedMesh = face;
			break;
		case OutfitManager.OutfitType.Eye:
			targetSkinnedMesh = eyes;
			break;
		case OutfitManager.OutfitType.Mouth:
			targetSkinnedMesh = mouth;
			break;
		case OutfitManager.OutfitType.Neck:
		case OutfitManager.OutfitType.Shirt:
		case OutfitManager.OutfitType.Belt:
		case OutfitManager.OutfitType.Pocket:
		case OutfitManager.OutfitType.TeamJersey:
			targetSkinnedMesh = torso;
			break;
		case OutfitManager.OutfitType.Wrist:
		case OutfitManager.OutfitType.Glove:
		case OutfitManager.OutfitType.Watch:
		case OutfitManager.OutfitType.TeamWrist:
			if (newOutfit.CurrentBodyPart == Player.BodyPart.LeftHand)
			{
				targetSkinnedMesh = leftHand;
				break;
			}
			if (newOutfit.CurrentBodyPart == Player.BodyPart.RightHand)
			{
				targetSkinnedMesh = rightHand;
				break;
			}
			UnityEngine.Debug.LogError(string.Concat("An outfit (", newOutfit, ") with hand type is being placed to an incorrect body part. ", newOutfit.CurrentBodyPart));
			break;
		default:
			throw new Exception("PlayerOutfit.SetOutfitTarget can not set target for this outfit " + newOutfit);
		}
		newOutfit.SetTargetSkinnedMesh(targetSkinnedMesh);
	}

	public bool IsWearing(Guid guid, OutfitManager.OutfitType outfitType)
	{
		OutfitGuidToBody key = new OutfitGuidToBody(guid, OutfitManager.GetMatchingBodyPart(outfitType));
		return outfitGuidMap.ContainsKey(key);
	}

	public void SnapShotSelection()
	{
		savedHairColorGuid = HairColor.guidString;
		savedSkinColorGuid = SkinColor.guidString;
		savedOutfitGuidMap.Clear();
		outfitGuidMap.CopyMap(ref savedOutfitGuidMap);
		snapShotReady = true;
	}

	public void RestoreSelection()
	{
		if (!snapShotReady)
		{
			return;
		}
		SetHairColor(savedHairColorGuid);
		SetSkinColor(savedSkinColorGuid);
		Dictionary<OutfitGuidToBody, Outfit> copy = new Dictionary<OutfitGuidToBody, Outfit>();
		outfitGuidMap.CopyMap(ref copy);
		foreach (KeyValuePair<OutfitGuidToBody, Outfit> item in copy)
		{
			if (!savedOutfitGuidMap.ContainsKey(item.Key))
			{
				UnEquipOutfit(item.Value);
			}
		}
		foreach (KeyValuePair<OutfitGuidToBody, Outfit> item2 in savedOutfitGuidMap)
		{
			if (!outfitGuidMap.ContainsKey(item2.Key))
			{
				EquipOutfit(item2.Key.guid, item2.Key.bodyPart);
			}
		}
	}

	public void DebugEquipModeratorOutfits()
	{
		foreach (OutfitManager.OutfitToBodyPart moderatorOutfit in SingletonMonoBehaviour<OutfitManager>.Instance.ModeratorOutfits)
		{
			SetOutfit(moderatorOutfit.outfit, moderatorOutfit.bodyPart);
		}
	}
}
public class CollisionVibration : UnityEngine.MonoBehaviour
{
	private void OnCollisionEnter(Collision collision)
	{
		PlayerHand playerHand = null;
		Player.BodyPart bodyPart;
		Player colliderPlayer = collision.GetColliderPlayer(out bodyPart);
		Tool colliderTool = collision.GetColliderTool();
		if (colliderPlayer != null)
		{
			switch (bodyPart)
			{
			case Player.BodyPart.LeftHand:
				playerHand = colliderPlayer.LeftHand;
				break;
			case Player.BodyPart.RightHand:
				playerHand = colliderPlayer.RightHand;
				break;
			}
		}
		else if (colliderTool != null && colliderTool.IsHeld && colliderTool.Owner != null)
		{
			if (colliderTool.Owner.LeftHand.Tool == colliderTool)
			{
				playerHand = colliderTool.Owner.LeftHand;
			}
			else if (colliderTool.Owner.RightHand.Tool == colliderTool)
			{
				playerHand = colliderTool.Owner.RightHand;
			}
		}
		if (playerHand != null)
		{
			playerHand.Vibrate(50);
		}
	}
}
public class FaceStretchInteraction : UnityEngine.MonoBehaviour
{
	private static Color visualColor = new Color(0f, 1f, 0.8f, 1f);

	private static float visualScale = 0.05f;

	private static float colliderRadius = 0.025f;

	private static float defaultAlpha = 0.1f;

	private static float highlightAlpha = 0.7f;

	private Renderer visualRenderer;

	private List<PlayerHand> interactingHands = new List<PlayerHand>();

	private void OnTriggerEnter(Collider collider)
	{
		PlayerHand componentInParents = collider.gameObject.GetComponentInParents<PlayerHand>();
		if (componentInParents != null)
		{
			if (interactingHands.Count == 0)
			{
				Color color = visualRenderer.material.color;
				color.a = highlightAlpha;
				visualRenderer.material.color = color;
			}
			if (!interactingHands.Contains(componentInParents))
			{
				interactingHands.Add(componentInParents);
				componentInParents.Vibrate();
			}
		}
	}

	private void OnTriggerExit(Collider collider)
	{
		PlayerHand componentInParents = collider.gameObject.GetComponentInParents<PlayerHand>();
		if (componentInParents != null)
		{
			if (interactingHands.Contains(componentInParents))
			{
				interactingHands.Remove(componentInParents);
			}
			if (interactingHands.Count == 0)
			{
				Color color = visualRenderer.material.color;
				color.a = defaultAlpha;
				visualRenderer.material.color = color;
			}
		}
	}

	private void Awake()
	{
		GameObject gameObject = GameObject.CreatePrimitive(PrimitiveType.Sphere);
		gameObject.transform.SetParent(base.transform, worldPositionStays: false);
		gameObject.transform.localScale = Vector3.one * visualScale;
		UnityEngine.Object.Destroy(gameObject.GetComponent<Collider>());
		SphereCollider sphereCollider = base.gameObject.AddComponent<SphereCollider>();
		sphereCollider.radius = colliderRadius;
		sphereCollider.isTrigger = true;
		visualRenderer = gameObject.GetComponent<Renderer>();
		visualRenderer.material.shader = Shader.Find("Transparent/Diffuse");
		Color color = visualColor;
		color.a = defaultAlpha;
		visualRenderer.material.color = color;
	}

	private void Update()
	{
		foreach (PlayerHand interactingHand in interactingHands)
		{
			if (interactingHand.ControllerIO != null && interactingHand.ControllerIO.TriggerButtonPressed)
			{
				base.transform.position = interactingHand.transform.position;
			}
		}
	}
}
public class HeadGestureDetect : UnityEngine.MonoBehaviour
{
	public enum Gesture
	{
		TiltUp,
		TiltDown,
		NodUp,
		NodDown,
		FullNod,
		TurnLeft,
		TurnRight,
		ShakeLeft,
		ShakeRight,
		FullShake,
		LeanLeft,
		LeanRight,
		NodLeft,
		NodRight,
		FullSideNod
	}

	[SerializeField]
	private float nodSensitivity = 10f;

	[SerializeField]
	private float shakeSensitivity = 10f;

	[SerializeField]
	private float leanSensitivity = 10f;

	[SerializeField]
	private float nodNeutralZone = 5f;

	[SerializeField]
	private float shakeNeutralZone = 5f;

	[SerializeField]
	private float leanNeutralZone = 5f;

	[SerializeField]
	private float timeOut = 3f;

	[SerializeField]
	private Transform trackedHead;

	[Tooltip("Enabling this will fire all the different gestures and not just the full gestures.")]
	public bool DetailedDetection;

	private float countdown;

	private float baselineX;

	private float baselineY;

	private float baselineZ;

	private float pitch;

	private float yaw;

	private float roll;

	private float doSomethingTime;

	private bool tiltUp;

	private bool tiltDown;

	private bool nodUp;

	private bool nodDown;

	private bool turnLeft;

	private bool turnRight;

	private bool shakeLeft;

	private bool shakeRight;

	private bool leanLeft;

	private bool leanRight;

	private bool nodLeft;

	private bool nodRight;

	private int nods;

	private int shakes;

	private int sideNods;

	private float pitchAng;

	private float yawAng;

	private float rollAng;

	public event Action<Gesture> GestureDetected;

	private void Start()
	{
		if (trackedHead == null)
		{
			trackedHead = base.transform;
		}
		baselineX = Angle(trackedHead.localEulerAngles.x);
		baselineY = Angle(trackedHead.localEulerAngles.y);
		baselineZ = Angle(trackedHead.localEulerAngles.z);
		doSomethingTime = Time.time;
	}

	private void Update()
	{
		countdown = Time.time - doSomethingTime;
		pitch = Angle(trackedHead.localEulerAngles.x);
		yaw = Angle(trackedHead.localEulerAngles.y);
		roll = Angle(trackedHead.localEulerAngles.z);
		pitchAng = AngleBetween(pitch, baselineX);
		yawAng = AngleBetween(yaw, baselineY);
		rollAng = AngleBetween(roll, baselineZ);
		if (tiltUp && countdown > timeOut)
		{
			tiltUp = false;
			baselineX = pitch;
			return;
		}
		if (tiltDown && countdown > timeOut)
		{
			tiltDown = false;
			baselineX = pitch;
			return;
		}
		if (turnLeft && countdown > timeOut)
		{
			turnLeft = false;
			baselineY = yaw;
			return;
		}
		if (turnRight && countdown > timeOut)
		{
			turnRight = false;
			baselineY = yaw;
			return;
		}
		if (nods > 0 && countdown > timeOut)
		{
			nods = 0;
		}
		if (shakes > 0 && countdown > timeOut)
		{
			shakes = 0;
		}
		if (sideNods > 0 && countdown > timeOut)
		{
			sideNods = 0;
		}
		if (!tiltUp && pitchAng < 0f - nodSensitivity)
		{
			tiltUp = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TiltUp);
			}
		}
		if (tiltUp && pitchAng > nodNeutralZone && countdown < timeOut)
		{
			tiltUp = false;
			nodUp = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodUp);
			}
		}
		if (!tiltDown && pitchAng > nodSensitivity)
		{
			tiltDown = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TiltDown);
			}
		}
		if (tiltDown && pitchAng < nodNeutralZone && countdown < timeOut)
		{
			tiltDown = false;
			doSomethingTime = Time.time;
			nodDown = true;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodDown);
			}
		}
		if (nodDown && nodUp)
		{
			nods++;
			if (this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.FullNod);
			}
			doSomethingTime = Time.time;
			nodUp = false;
			nodDown = false;
		}
		if (!turnRight && yawAng > shakeSensitivity)
		{
			turnRight = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TurnRight);
			}
		}
		if (turnRight && yawAng < shakeNeutralZone && countdown < timeOut)
		{
			turnRight = false;
			shakeRight = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.ShakeRight);
			}
		}
		if (!turnLeft && yawAng < 0f - shakeSensitivity)
		{
			turnLeft = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TurnLeft);
			}
		}
		if (turnLeft && yawAng > 0f - shakeNeutralZone)
		{
			turnLeft = false;
			doSomethingTime = Time.time;
			shakeLeft = true;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.ShakeLeft);
			}
		}
		if (shakeLeft && shakeRight)
		{
			shakes++;
			if (this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.FullShake);
			}
			doSomethingTime = Time.time;
			shakeLeft = false;
			shakeRight = false;
		}
		if (!leanRight && rollAng < 0f - leanSensitivity)
		{
			leanRight = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.LeanRight);
			}
		}
		if (leanRight && rollAng > leanNeutralZone && countdown < timeOut)
		{
			leanRight = false;
			nodRight = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodRight);
			}
		}
		if (!leanLeft && rollAng > leanSensitivity)
		{
			leanLeft = true;
			doSomethingTime = Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.LeanLeft);
			}
		}
		if (leanLeft && rollAng < leanNeutralZone)
		{
			leanLeft = false;
			doSomethingTime = Time.time;
			nodLeft = true;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodLeft);
			}
		}
		if (nodLeft && nodRight)
		{
			sideNods++;
			if (this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.FullSideNod);
			}
			doSomethingTime = Time.time;
			nodLeft = false;
			nodRight = false;
		}
	}

	private float Angle(float a)
	{
		if (a > 180f)
		{
			a -= 360f;
		}
		return a;
	}

	private float AngleBetween(float a, float b)
	{
		float num = a - b;
		if (num > 180f || num < -180f)
		{
			num = 360f - num;
		}
		return num;
	}
}
[DisallowMultipleComponent]
public class NetworkToolController : Photon.MonoBehaviour
{
	private class ToolPickupProperty
	{
		private const string TOOL_PICKUP_PROPERTY = "Tool_Pickup.";

		public Tool tool { get; private set; }

		public Vector3 pickupPosition { get; private set; }

		public Quaternion pickupRotation { get; private set; }

		public int handType { get; private set; }

		public int serverTime { get; private set; }

		public ToolPickupProperty(object[] values)
		{
			tool = Tool.Find((int)values[0]);
			pickupPosition = (Vector3)values[1];
			pickupRotation = (Quaternion)values[2];
			handType = (int)values[3];
			serverTime = (int)values[4];
		}

		public ToolPickupProperty(Tool tool, Vector3 pickupPosition, Quaternion pickupRotation, int handType)
		{
			this.tool = tool;
			this.pickupPosition = pickupPosition;
			this.pickupRotation = pickupRotation;
			this.handType = handType;
			serverTime = PhotonNetwork.ServerTimestamp;
		}

		public object[] GetPhotonProperty()
		{
			return new object[5]
			{
				(!(tool.photonView != null)) ? (-1) : tool.photonView.viewID,
				pickupPosition,
				pickupRotation,
				handType,
				serverTime
			};
		}

		public static ToolPickupProperty GetToolPickup(Player player, PlayerHand.HandType handType)
		{
			string key = "Tool_Pickup." + (int)handType;
			if (player.owner.customProperties.ContainsKey(key))
			{
				return new ToolPickupProperty((object[])player.owner.customProperties[key]);
			}
			return null;
		}

		public static void RemoveProperty(Player player, PlayerHand.HandType handType)
		{
			string text = "Tool_Pickup." + (int)handType;
			if (player.owner.customProperties.ContainsKey(text))
			{
				player.owner.RemoveCustomProperties(text);
			}
		}

		public void SetPropertyForPlayer(Player player)
		{
			string propertyName = "Tool_Pickup." + handType;
			player.photonView.owner.SetCustomProperties(propertyName, GetPhotonProperty());
		}
	}

	private Player thisPlayer;

	private void Awake()
	{
		thisPlayer = GetComponent<Player>();
		ParseRoomPropertiesForToolHolder(PhotonNetwork.room.customProperties);
	}

	private void Start()
	{
		base.enabled = base.isLocal;
	}

	public void TryPickupTool(Tool tool, int handTypeId)
	{
		PlayerHand hand = thisPlayer.GetHand(handTypeId);
		hand.GetToolPickupPositionAndRotation(tool, useGravityPickup: true, Vector3.zero, out var handSpacePickupPosition, out var handSpacePickupRotation);
		TryPickupTool(tool, handSpacePickupPosition, handSpacePickupRotation, handTypeId);
	}

	public void TryPickupTool(Tool tool, Vector3 handSpacePickupPosition, Quaternion handSpacePickupRotation, int handTypeId)
	{
		if (tool.IsOnline)
		{
			int data = tool.ActivityData.GetData("Holder", PhotonPlayer.Invalid);
			if (data == PhotonPlayer.Invalid || data == base.photonView.ownerId)
			{
				ToolPickupProperty toolPickupProperty = new ToolPickupProperty(tool, handSpacePickupPosition, handSpacePickupRotation, handTypeId);
				toolPickupProperty.SetPropertyForPlayer(thisPlayer);
				tool.ActivityData.SetData("Holder", base.photonView.ownerId, data);
				PickupToolSuccess(tool);
			}
		}
		else
		{
			PickupToolSuccessHandPickup(tool, handSpacePickupPosition, handSpacePickupRotation, thisPlayer.GetHand(handTypeId));
		}
	}

	private void OnPhotonCustomRoomPropertiesChanged(ExitGames.Client.Photon.Hashtable propertiesThatChanged)
	{
		ParseRoomPropertiesForToolHolder(propertiesThatChanged);
	}

	private void ParseRoomPropertiesForToolHolder(ExitGames.Client.Photon.Hashtable properties)
	{
		if (!thisPlayer.isLocal)
		{
			return;
		}
		foreach (string item in properties.Keys.OfType<string>())
		{
			if (!item.Contains("Holder"))
			{
				continue;
			}
			int result = -1;
			string s = item.Split('.')[0];
			if (!int.TryParse(s, out result))
			{
				continue;
			}
			Tool tool = Tool.Find(result);
			if (!(tool != null))
			{
				continue;
			}
			Player player = Player.Find((int)properties[item]);
			PhotonPlayer[] playerList = PhotonNetwork.playerList;
			foreach (PhotonPlayer photonPlayer in playerList)
			{
				Player player2 = photonPlayer.ToPlayer();
				if (player2 != null && player2 != player && (player2.LeftHand.Tool == tool || player2.RightHand.Tool == tool))
				{
					player2.ToolController.ReleaseTool(tool);
				}
			}
			if (player != null)
			{
				player.ToolController.PickupToolSuccess(tool);
			}
		}
	}

	private void PickupToolSuccess(Tool tool)
	{
		ToolPickupProperty toolPickup = ToolPickupProperty.GetToolPickup(thisPlayer, PlayerHand.HandType.Left);
		ToolPickupProperty toolPickup2 = ToolPickupProperty.GetToolPickup(thisPlayer, PlayerHand.HandType.Right);
		ToolPickupProperty toolPickupProperty = null;
		if (toolPickup != null && toolPickup.tool == tool && toolPickup2 != null && toolPickup2.tool == tool)
		{
			toolPickupProperty = ((toolPickup.serverTime >= toolPickup2.serverTime) ? toolPickup : toolPickup2);
		}
		else if (toolPickup != null && toolPickup.tool == tool)
		{
			toolPickupProperty = toolPickup;
		}
		else if (toolPickup2 != null && toolPickup2.tool == tool)
		{
			toolPickupProperty = toolPickup2;
		}
		if (toolPickupProperty != null)
		{
			tool.photonView.TransferOwnership(thisPlayer.owner);
			PickupToolSuccessHandPickup(tool, toolPickupProperty.pickupPosition, toolPickupProperty.pickupRotation, thisPlayer.GetHand(toolPickupProperty.handType));
		}
	}

	private void PickupToolSuccessHandPickup(Tool tool, Vector3 pickupPosition, Quaternion pickupRotation, PlayerHand hand)
	{
		PlayerHand otherHand = thisPlayer.GetOtherHand(hand.Type);
		if (otherHand != null && otherHand.Tool == tool)
		{
			ReleaseTool(tool, otherHand, ignoreHolderProperty: true);
		}
		if (hand.Tool != tool)
		{
			hand.PickupTool(tool, pickupPosition, pickupRotation);
		}
	}

	public void ReleaseTool(Tool tool)
	{
		if (!(tool == null))
		{
			PlayerHand playerHand = null;
			if (thisPlayer.LeftHand.Tool == tool)
			{
				playerHand = thisPlayer.LeftHand;
			}
			else if (thisPlayer.RightHand.Tool == tool)
			{
				playerHand = thisPlayer.RightHand;
			}
			if (playerHand != null)
			{
				ReleaseTool(tool, playerHand);
			}
		}
	}

	private void ReleaseTool(Tool tool, PlayerHand hand, bool ignoreHolderProperty = false)
	{
		if (!(hand.Tool == tool))
		{
			return;
		}
		hand.ReleaseTool();
		if (tool.IsOnline && base.hasAuthority)
		{
			if (!ignoreHolderProperty)
			{
				tool.ActivityData.SetData("Holder", PhotonPlayer.Invalid, thisPlayer.photonView.ownerId);
			}
			ToolPickupProperty.RemoveProperty(thisPlayer, hand.Type);
		}
	}
}
public class OverlapVolume : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Vector3 localSize;

	private Vector3 localExtents;

	private Vector3 GlobalSize => Vector3.Scale(base.transform.lossyScale, localSize);

	private void Awake()
	{
		localExtents = localSize / 2f;
	}

	public bool CheckOverlap(Vector3 point)
	{
		Vector3 vector = base.transform.InverseTransformPoint(point);
		return vector.x < localExtents.x && vector.x > 0f - localExtents.x && vector.y < localExtents.y && vector.y > 0f - localExtents.y && vector.z < localExtents.z && vector.z > 0f - localExtents.z;
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.green;
		Gizmos.matrix = Matrix4x4.TRS(base.transform.position, base.transform.rotation, GlobalSize);
		Gizmos.DrawWireCube(Vector3.zero, Vector3.one);
	}
}
public class PersonalBubble : UnityEngine.MonoBehaviour
{
	[Flags]
	public enum BubbleMask
	{
		Hand_Local = 1,
		Hand_Remote = 2,
		Tool = 4
	}

	[Flags]
	public enum ToolMask
	{
		Ball = 1,
		BoxingGlove = 2,
		Bucket = 4,
		Card = 8,
		CardBox = 0x10,
		Clipboard = 0x20,
		Cone = 0x40,
		Dart = 0x80,
		Extrusion = 0x100,
		Frisbee = 0x200,
		Gun = 0x400,
		HandheldCameraTool = 0x800,
		HelpClipboard = 0x1000,
		LaundryBin = 0x2000,
		MeshExtruderTool = 0x4000,
		OutfitTool = 0x8000,
		PaddleballBall = 0x10000,
		PaddleballPaddle = 0x20000,
		Radio = 0x40000,
		WaterBottle = 0x80000,
		WaterJug = 0x100000
	}

	[SerializeField]
	[EnumFlags]
	private BubbleMask bubbleFlags;

	[SerializeField]
	[EnumFlags]
	private ToolMask excludedTools;

	[Tooltip("How long after leaving this zone we can show your hand back again? In seconds!")]
	[SerializeField]
	private float turnVisibleTimeout = 0.15f;

	[SerializeField]
	private BoxCollider boxCollider;

	private Player thisPlayer;

	private Vector3 boxSize = Vector3.one;

	private Dictionary<Type, ToolMask> toolMaskMap;

	private void Awake()
	{
		thisPlayer = GetComponentInParent<Player>();
		boxSize = boxCollider.size.MultiplyComponents(boxCollider.transform.lossyScale) / 2f;
		InitToolMaskMap();
	}

	private void FixedUpdate()
	{
		if (SingletonMonoBehaviour<SettingsManager>.Instance.PersonalBubble && ActivityManager.Instance != null && ActivityManager.Instance.GameState != ActivityGameState.PlayingGame && ActivityManager.Instance.GameState != ActivityGameState.Countdown && Player.LocalPlayer != null && !Player.LocalPlayer.IsInChangingRoom)
		{
			Vector3 center = boxCollider.transform.TransformPoint(boxCollider.center);
			Collider[] array = Physics.OverlapBox(center, boxSize, boxCollider.transform.rotation, 1455616);
			for (int i = 0; i < array.Length; i++)
			{
				CheckCollider(array[i]);
			}
		}
	}

	private void CheckCollider(Collider col)
	{
		GameObject gameObject = col.gameObject;
		bool flag = IsMaskActive(BubbleMask.Hand_Local);
		bool flag2 = IsMaskActive(BubbleMask.Hand_Remote);
		bool flag3 = IsMaskActive(BubbleMask.Tool);
		if ((flag && gameObject.IsInLayerMask(LayerMasks.LocalPlayerPhysics)) || (flag2 && gameObject.IsInLayerMask(LayerMasks.RemotePlayerPhysics)))
		{
			PlayerCollider component = gameObject.GetComponent<PlayerCollider>();
			if (component != null && component.ThisPlayer != null && component.BodyPart.IsHand())
			{
				bool isLocal = component.ThisPlayer.isLocal;
				if ((isLocal && flag) || (!isLocal && flag2))
				{
					PlayerHand playerHand = ((component.BodyPart != Player.BodyPart.LeftHand) ? component.ThisPlayer.RightHand : component.ThisPlayer.LeftHand);
					playerHand.SetInPersonalBubble(turnVisibleTimeout);
				}
			}
		}
		else if (flag3 && gameObject.IsInLayerMask(LayerMasks.ToolPhysics))
		{
			ToolCollider component2 = gameObject.GetComponent<ToolCollider>();
			if (component2 != null && component2.Tool != null && !IsToolExcluded(component2.Tool))
			{
				bool inPersonalBubble = !thisPlayer.isLocal || IsMaskActive(BubbleMask.Hand_Local);
				component2.Tool.InPersonalBubble = inPersonalBubble;
			}
		}
	}

	private bool IsMaskActive(BubbleMask mask)
	{
		return (mask & bubbleFlags) == mask;
	}

	private bool IsToolExcluded(Tool tool)
	{
		ToolMask toolMask = ToToolMask(tool);
		return toolMask != 0 && (toolMask & excludedTools) == toolMask;
	}

	private ToolMask ToToolMask(Tool tool)
	{
		Type type = tool.GetType();
		ToolMask value = (ToolMask)0;
		toolMaskMap.TryGetValue(type, out value);
		return value;
	}

	private void InitToolMaskMap()
	{
		if (toolMaskMap != null)
		{
			return;
		}
		toolMaskMap = new Dictionary<Type, ToolMask>();
		foreach (int value in Enum.GetValues(typeof(ToolMask)))
		{
			string typeName = ((ToolMask)value).ToString();
			Type type = Type.GetType(typeName);
			if (type != null && !toolMaskMap.ContainsKey(type))
			{
				toolMaskMap.Add(type, (ToolMask)value);
			}
		}
	}
}
public class PersonalMuteZone : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private BoxCollider boxCollider;

	private Player thisPlayer;

	private Vector3 boxSize = Vector3.one;

	[SerializeField]
	[Tooltip("Delay before mute is active, this is to filter out quick swipe of hand in front of face without meaning to mute.")]
	private float gestureMuteDelay = 0.35f;

	private bool wasGestureMuting;

	private float handInDuration;

	private bool isHandIn;

	private void Awake()
	{
		thisPlayer = GetComponentInParent<Player>();
		boxSize = boxCollider.size.MultiplyComponents(boxCollider.transform.lossyScale) / 2f;
		base.enabled = thisPlayer.isLocal;
	}

	private void FixedUpdate()
	{
		isHandIn = false;
		if (SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat != VoiceChat.AlwaysOn)
		{
			return;
		}
		Vector3 center = boxCollider.transform.TransformPoint(boxCollider.center);
		Collider[] array = Physics.OverlapBox(center, boxSize, boxCollider.transform.rotation, 1049088);
		for (int i = 0; i < array.Length; i++)
		{
			CheckHandIn(array[i]);
		}
		if (isHandIn)
		{
			handInDuration += Time.deltaTime;
			if (!thisPlayer.Mute && handInDuration >= gestureMuteDelay)
			{
				wasGestureMuting = true;
				Player.LocalPlayer.Mute = true;
				MenuNotification.PlayNext("Muted", 0.5f, null, followPlayer: false, null, 0.2f);
			}
		}
		else if (wasGestureMuting)
		{
			Player.LocalPlayer.Mute = false;
			wasGestureMuting = false;
			MenuNotification.PlayNext("Unmuted", 0.5f, null, followPlayer: false, null, 0.2f);
		}
	}

	private void CheckHandIn(Collider col)
	{
		GameObject gameObject = col.gameObject;
		PlayerCollider component = gameObject.GetComponent<PlayerCollider>();
		if (component != null && component.ThisPlayer != null && component.BodyPart.IsHand())
		{
			PlayerHand hand = component.ThisPlayer.GetHand(component.BodyPart);
			if (hand != null && hand.IsVisible)
			{
				isHandIn = true;
			}
		}
	}
}
