	private void UpdateAFKStatus()
	{
		if (!PhotonNetwork.offlineMode && PhotonNetwork.inRoom && ActivityManager.Instance != null)
		{
			float num = Time.unscaledTime - lastHeadMovedTime;
			bool flag = true;
			flag = OpenVR.System.GetTrackedDeviceActivityLevel(0u) == EDeviceActivityLevel.k_EDeviceActivityLevel_UserInteraction;
			float aFKKickToIntroTimeout = ActivityManager.Instance.PlayerManager.AFKKickToIntroTimeout;
			float aFKWarningStartTimeout = ActivityManager.Instance.PlayerManager.AFKWarningStartTimeout;
			AFKVisible = flag;
			if (flag)
			{
				lastHeadMovedTime = Time.unscaledTime;
				currentAfkCoundown = -1;
			}
			else if (num > aFKKickToIntroTimeout)
			{
				ReturnToDormRoom(afkIntroMessage);
				AnalyticsHelper.UserAFK();
				lastHeadMovedTime = Time.unscaledTime;
			}
			else if (num > aFKWarningStartTimeout)
			{
				int num2 = Mathf.CeilToInt(aFKKickToIntroTimeout - num);
				if (currentAfkCoundown != num2)
				{
					MenuNotification.PlayNext(afkWarningMessageTitle, 1f, afkWarningMessageSubTitle + num2, followPlayer: true, null, 0.3f);
					currentAfkCoundown = num2;
				}
			}
		}
		else
		{
			lastHeadMovedTime = Time.unscaledTime;
			currentAfkCoundown = -1;
		}
	}

