	public Coroutine SpawnLocal()
	{
		if (!base.isLocal)
		{
			UnityEngine.Debug.LogError("Player.SpawnLocal() can only be called on the LocalPlayer!");
		}
		isSpawned = true;
		UpdateVisibility();
		base.photonView.RPC("RpcBroadcastSpawnPlayer", PhotonTargets.Others);
		PhotonNetwork.SendOutgoingCommands();
		return CameraFade.Instance.Fade(fadeIn: true);
	}

	public Coroutine DespawnLocal(bool prepForLevelSwitch)
	{
		if (!base.isLocal)
		{
			UnityEngine.Debug.LogError("Player.DespawnLocal() can only be called on the LocalPlayer!");
		}
		if (!isSpawned)
		{
			return StartCoroutine(WaitForCameraFadeCoroutine());
		}
		PlayerLocomotion.OnPlayerDespawn();
		isSpawned = false;
		UpdateVisibility();
		ReleaseToolsFromBothHands(releaseDueToRespawn: true);
		base.photonView.RPC("RpcBroadcastDespawnPlayer", PhotonTargets.Others);
		PhotonNetwork.SendOutgoingCommands();
		return CameraFade.Instance.Fade(fadeIn: false, prepForLevelSwitch);
	}

	private IEnumerator WaitForCameraFadeCoroutine()
	{
		float startTime = Time.time;
		yield return new WaitWhile(() => CameraFade.Instance.IsFading && Time.time - startTime <= 3f);
	}

	[PunRPC]
	public IEnumerator RpcRespawnPlayer(Vector3 position, Quaternion rotation)
	{
		yield return DespawnLocal(prepForLevelSwitch: false);
		PlayerLocomotion.MoveCameraRig(position, rotation * Vector3.forward);
		yield return SpawnLocal();
	}

	[PunRPC]
	public IEnumerator RpcDespawnPlayer()
	{
		yield return DespawnLocal(prepForLevelSwitch: false);
	}

	[PunRPC]
	public void RpcBroadcastSpawnPlayer()
	{
		isSpawned = true;
		UpdateVisibility();
		if (IsVisible)
		{
			AnimateInOut.PlayEffect(animIn: true);
		}
	}

	[PunRPC]
	public void RpcBroadcastDespawnPlayer()
	{
		if (IsVisible)
		{
			AnimateInOut.PlayEffect(animIn: false);
		}
		PlayerLocomotion.OnPlayerDespawn();
		isSpawned = false;
		UpdateVisibility();
	}

