	private void UpdateVisibility()
	{
		bool isVisible = IsVisible;
		if (wasVisible != isVisible)
		{
			for (int i = 0; i < head.transform.childCount; i++)
			{
				head.transform.GetChild(i).gameObject.SetActive(isVisible);
			}
			Body.Visible = isVisible;
			for (int j = 0; j < leftHand.transform.childCount; j++)
			{
				leftHand.transform.GetChild(j).gameObject.SetActive(isVisible);
			}
			for (int k = 0; k < rightHand.transform.childCount; k++)
			{
				rightHand.transform.GetChild(k).gameObject.SetActive(isVisible);
			}
			if (this.VisibilityChanged != null)
			{
				this.VisibilityChanged(isVisible);
			}
			wasVisible = isVisible;
			AnimateInOut.SuppressAnimation = base.isLocal || !isVisible;
		}
		afkPlayerVisual.gameObject.SetActive(!base.isLocal && (!AFKVisible || InPersonalBubble) && !IsInChangingRoom && !Ignore && !RemoteIgnored);
		playerIdentity.gameObject.SetActive(isVisible || afkPlayerVisual.gameObject.activeSelf);
		ignoredPlayerVisual.gameObject.SetActive(!IsInChangingRoom && (Ignore || RemoteIgnored));
	}

