public class PlayerAfterImageParticles : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private ParticleSystem[] particleSystems;

	[SerializeField]
	private float speed = 5f;

	[SerializeField]
	private float emissionRate = 100f;

	[SerializeField]
	private Color defaultColor = new Color(0.45f, 0.45f, 0.45f, 1f);

	public Color Color
	{
		set
		{
			ParticleSystem[] array = particleSystems;
			foreach (ParticleSystem particleSystem in array)
			{
				particleSystem.startColor = value;
			}
		}
	}

	public void Run(Vector3 origin, Vector3 destination)
	{
		base.transform.position = origin;
		Vector3 vector = destination - origin;
		base.transform.rotation = Quaternion.LookRotation(-vector.normalized);
		float num = vector.magnitude / speed;
		ParticleSystem[] array = particleSystems;
		foreach (ParticleSystem particleSystem in array)
		{
			particleSystem.startLifetime = num;
			particleSystem.startSpeed = speed;
			particleSystem.Play();
		}
		UnityEngine.Object.Destroy(base.gameObject, num);
	}

	private void Awake()
	{
		ParticleSystem[] array = particleSystems;
		foreach (ParticleSystem particleSystem in array)
		{
			ParticleSystem.EmissionModule emission = particleSystem.emission;
			emission.rate = new ParticleSystem.MinMaxCurve
			{
				constantMax = emissionRate
			};
		}
		Color = defaultColor;
	}
}
