public class PlayerChaperone : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float lineThickness = 0.1f;

	[SerializeField]
	private Material material;

	[SerializeField]
	private MeshRenderer chaperoneBoundsRenderer;

	[SerializeField]
	private MeshRenderer chaperoneCenterRenderer;

	private MeshFilter chaperoneMeshFilter;

	private Vector3[] vertices;

	private Player thisPlayer;

	private HmdQuad_t playSpaceBounds = default(HmdQuad_t);

	public bool ShowCurrentBounds { get; set; }

	private void Awake()
	{
		thisPlayer = GetComponentInParent<Player>();
		chaperoneMeshFilter = chaperoneBoundsRenderer.gameObject.GetComponent<MeshFilter>();
	}

	private bool GetBounds(ref HmdQuad_t pRect)
	{
		bool flag = !SteamVR.active && !SteamVR.usingNativeSupport;
		if (flag)
		{
			EVRInitError peError = EVRInitError.None;
			OpenVR.Init(ref peError, EVRApplicationType.VRApplication_Other);
		}
		bool flag2 = OpenVR.Chaperone?.GetPlayAreaRect(ref pRect) ?? false;
		if (!flag2)
		{
			UnityEngine.Debug.LogWarning("Failed to get Calibrated Play Area bounds!  Make sure you have tracking first, and that your space is calibrated.");
		}
		if (flag)
		{
			OpenVR.Shutdown();
		}
		return flag2;
	}

	private void BuildBorderMesh()
	{
		HmdQuad_t pRect = default(HmdQuad_t);
		if (!GetBounds(ref pRect))
		{
			return;
		}
		HmdVector3_t[] array = new HmdVector3_t[4] { pRect.vCorners0, pRect.vCorners1, pRect.vCorners2, pRect.vCorners3 };
		vertices = new Vector3[array.Length * 2];
		Vector3 zero = Vector3.zero;
		for (int i = 0; i < array.Length; i++)
		{
			HmdVector3_t hmdVector3_t = array[i];
			ref Vector3 reference = ref vertices[i];
			reference = new Vector3(hmdVector3_t.v0, 0.01f, hmdVector3_t.v2);
			zero += vertices[i];
		}
		zero /= (float)array.Length;
		chaperoneCenterRenderer.transform.localPosition = zero;
		if (lineThickness == 0f)
		{
			chaperoneMeshFilter.mesh = null;
			return;
		}
		for (int j = 0; j < array.Length; j++)
		{
			int num = (j + 1) % array.Length;
			int num2 = (j + array.Length - 1) % array.Length;
			Vector3 normalized = (vertices[num] - vertices[j]).normalized;
			Vector3 normalized2 = (vertices[num2] - vertices[j]).normalized;
			Vector3 vector = vertices[j];
			vector += Vector3.Cross(normalized, Vector3.up) * lineThickness;
			vector += Vector3.Cross(normalized2, Vector3.down) * lineThickness;
			vertices[array.Length + j] = vector;
		}
		int[] triangles = new int[24]
		{
			7, 4, 0, 7, 0, 3, 6, 7, 3, 6,
			3, 2, 5, 6, 2, 5, 2, 1, 4, 5,
			1, 4, 1, 0
		};
		Vector2[] uv = new Vector2[8]
		{
			new Vector2(0f, 0f),
			new Vector2(1f, 0f),
			new Vector2(0f, 0f),
			new Vector2(1f, 0f),
			new Vector2(0f, 1f),
			new Vector2(1f, 1f),
			new Vector2(0f, 1f),
			new Vector2(1f, 1f)
		};
		Mesh mesh = new Mesh();
		chaperoneMeshFilter.mesh = mesh;
		mesh.vertices = vertices;
		mesh.uv = uv;
		mesh.triangles = triangles;
		if (material != null)
		{
			chaperoneBoundsRenderer.material = material;
		}
		else
		{
			chaperoneBoundsRenderer.material = Resources.GetBuiltinResource<Material>("Sprites-Default.mat");
		}
	}

	private void Update()
	{
		if (thisPlayer != null && thisPlayer.isLocal)
		{
			bool active = false;
			Vector3 vector = thisPlayer.CurrentFloorPosition;
			Quaternion quaternion = Quaternion.identity;
			if (thisPlayer.LeftHand != null && thisPlayer.LeftHand.PlayerHandRemote.Mode == LaserTeleporter.LaserMode.ValidTeleportPosition)
			{
				active = true;
				vector = thisPlayer.LeftHand.PlayerHandRemote.CurrentTarget;
				quaternion = thisPlayer.LeftHand.PlayerHandRemote.CurrentRotation;
			}
			else if (thisPlayer.RightHand != null && thisPlayer.RightHand.PlayerHandRemote.Mode == LaserTeleporter.LaserMode.ValidTeleportPosition)
			{
				active = true;
				vector = thisPlayer.RightHand.PlayerHandRemote.CurrentTarget;
				quaternion = thisPlayer.RightHand.PlayerHandRemote.CurrentRotation;
			}
			else if (ShowCurrentBounds)
			{
				active = true;
				vector = thisPlayer.CurrentFloorPosition;
				quaternion = Quaternion.identity;
			}
			base.transform.localRotation = quaternion;
			base.transform.position = vector - quaternion * (thisPlayer.CurrentFloorPosition - thisPlayer.transform.position);
			chaperoneBoundsRenderer.gameObject.SetActive(active);
			chaperoneCenterRenderer.gameObject.SetActive(SingletonMonoBehaviour<SettingsManager>.Instance.ShowRoomCenter || ShowCurrentBounds);
		}
	}

	public void OnEnable()
	{
		if (Application.isPlaying && thisPlayer != null && thisPlayer.isLocal)
		{
			StartCoroutine("UpdateBounds");
		}
	}

	private IEnumerator UpdateBounds()
	{
		chaperoneMeshFilter.mesh = null;
		CVRChaperone chaperone = OpenVR.Chaperone;
		if (chaperone != null)
		{
			while (chaperone.GetCalibrationState() != ChaperoneCalibrationState.OK)
			{
				yield return null;
			}
			BuildBorderMesh();
		}
	}

	public bool IsInBounds()
	{
		CVRChaperone chaperone = OpenVR.Chaperone;
		if (chaperone != null && chaperone.GetCalibrationState() == ChaperoneCalibrationState.OK)
		{
			if (!chaperone.GetPlayAreaRect(ref playSpaceBounds))
			{
				return false;
			}
			Vector3[] polygon = new Vector3[4]
			{
				HmdVector3ToHeadSpace(playSpaceBounds.vCorners0),
				HmdVector3ToHeadSpace(playSpaceBounds.vCorners1),
				HmdVector3ToHeadSpace(playSpaceBounds.vCorners2),
				HmdVector3ToHeadSpace(playSpaceBounds.vCorners3)
			};
			return IsInConvexPolygon(thisPlayer.Head.transform.position, polygon);
		}
		return false;
	}

	private Vector3 HmdVector3ToHeadSpace(HmdVector3_t hmdVector)
	{
		return thisPlayer.transform.TransformPoint(new Vector3(hmdVector.v0, hmdVector.v1, hmdVector.v2));
	}

	private bool IsInConvexPolygon(Vector3 testPoint, Vector3[] polygon)
	{
		if (polygon.Length == 0)
		{
			return false;
		}
		if (polygon.Length == 1)
		{
			return polygon[0].x == testPoint.x && polygon[0].z == testPoint.z;
		}
		int num = 0;
		int num2 = 0;
		for (int i = 0; i < polygon.Length; i++)
		{
			if (polygon[i].x == testPoint.x && polygon[i].z == testPoint.z)
			{
				return true;
			}
			float x = polygon[i].x;
			float z = polygon[i].z;
			int num3 = ((i < polygon.Length - 1) ? (i + 1) : 0);
			float x2 = polygon[num3].x;
			float z2 = polygon[num3].z;
			float x3 = testPoint.x;
			float z3 = testPoint.z;
			float num4 = (x3 - x) * (z2 - z) - (z3 - z) * (x2 - x);
			if (num4 > 0f)
			{
				num++;
			}
			if (num4 < 0f)
			{
				num2++;
			}
			if (num > 0 && num2 > 0)
			{
				return false;
			}
		}
		return true;
	}
}
