		set
		{
			if (_hoveredTool != value)
			{
				if (_hoveredTool != null && _hoveredTool.ToolRenderer.Mode != ToolRenderer.HighlightMode.Locked)
				{
					_hoveredTool.ToolRenderer.Mode = ToolRenderer.HighlightMode.None;
