public class PlayerLocomotion : Photon.MonoBehaviour
{
	private const string TELEPORT_BUFFER_PROP = "PlayerTeleportBuffer";

	[Tooltip("Duration with which we blind the user before teleportation.")]
	[SerializeField]
	[Header("Teleport")]
	private float teleportBlindDuration = 0.05f;

	[SerializeField]
	private float defaultMaxTeleportDistance = 12f;

	[SerializeField]
	private float defaultMaxTeleportPitchDegrees = 45f;

	[Header("Teleport Tool Hit")]
	[SerializeField]
	private float maxToolHitHoldTime = 2f;

	[SerializeField]
	private FloatValueCurve toolHitForceCurve;

	[HideInInspector]
	public float? MaxToolHitHoldTimeOverride;

	[SerializeField]
	[Header("Visuals")]
	private PlayerAfterImageParticles afterImageParticlesPrefab;

	[SerializeField]
	private PlayerLineTrail playerLineTrailPrefab;

	private Player thisPlayer;

	private PUNNetworkTransform networkTransform;

	private Coroutine teleportCoroutine;

	private float lastTeleportTime;

	private float lastTeleportEnabledTime;

	private PlayerLineTrail lineTrail;

	[HideInInspector]
	public bool TeleportEnabled = true;

	[HideInInspector]
	public bool JustTeleported;

	[HideInInspector]
	public bool JustHitToolWithTeleport;

	public float TeleportCooldownValue { get; private set; }

	public bool TeleportOnCooldown { get; private set; }

	public bool PlayerLineTrailsEnabled => ActivityManager.Instance != null && ActivityManager.Instance.TeleportRestrictions.TeleportPlayerLineTrailsEnabled;

	public bool TeleportToolHitsEnabled => ActivityManager.Instance != null && ActivityManager.Instance.TeleportRestrictions.TeleportToolHitEnabled;

	public float MaxTeleportDistance => (!(ActivityManager.Instance != null)) ? defaultMaxTeleportDistance : ActivityManager.Instance.TeleportRestrictions.MaxTeleportDistance;

	public float MaxTeleportPitchDegrees => (!(ActivityManager.Instance != null)) ? defaultMaxTeleportPitchDegrees : ActivityManager.Instance.TeleportRestrictions.MaxTeleportAngle;

	public TeleportBuffer TeleportBuffer
	{
		get
		{
			return (TeleportBuffer)thisPlayer.PlayerData.GetData("PlayerTeleportBuffer", 1);
		}
		set
		{
			thisPlayer.PlayerData.SetData("PlayerTeleportBuffer", (int)value);
		}
	}

	public float TeleportBufferDistance => SingletonMonoBehaviour<SettingsManager>.Instance.GetTeleportBufferSize(TeleportBuffer);

	public float ChargeAmount
	{
		get
		{
			float? maxToolHitHoldTimeOverride = MaxToolHitHoldTimeOverride;
			return GetChargeAmount((!maxToolHitHoldTimeOverride.HasValue) ? maxToolHitHoldTime : maxToolHitHoldTimeOverride.Value);
		}
	}

	private void Awake()
	{
		TeleportOnCooldown = false;
		TeleportCooldownValue = 0f;
		TeleportEnabled = true;
		JustTeleported = false;
		JustHitToolWithTeleport = false;
		lastTeleportTime = 0f;
		lastTeleportEnabledTime = 0f;
		thisPlayer = GetComponent<Player>();
		networkTransform = GetComponent<PUNNetworkTransform>();
		if (PlayerLineTrailsEnabled)
		{
			lineTrail = UnityEngine.Object.Instantiate(playerLineTrailPrefab);
			thisPlayer.SetParentPlayerRoot(lineTrail.transform);
		}
	}

	private void Start()
	{
		if (thisPlayer.isLocal)
		{
			TeleportBuffer = SingletonMonoBehaviour<SettingsManager>.Instance.TeleportBuffer;
		}
	}

	private void FixedUpdate()
	{
		UpdateTeleportCooldown();
	}

	public void TeleportTo(Vector3 destinationPlayerPosition, Quaternion teleportRotation, TeleportationPortal portal, Tool hitTool, Vector3 hitToolPoint, Vector3 hitToolDirection)
	{
		Vector3 currentFloorPosition = thisPlayer.CurrentFloorPosition;
		if (teleportCoroutine != null)
		{
			return;
		}
		if (portal != null)
		{
			if (portal.SupportsActivityLoading && ActivityManager.Instance != null)
			{
				if (!string.IsNullOrEmpty(portal.DestinationUserId))
				{
					ActivityManager.Instance.JoinPlayer(portal.DestinationUserId);
				}
				else if (thisPlayer.PlayerParty.IsInParty)
				{
					thisPlayer.PlayerUI.Menu.OpenLoadSceneMenu(portal.DestinationActivity);
				}
				else
				{
					ActivityManager.Instance.SwitchActivity(portal.DestinationActivity);
				}
				return;
			}
			if (!portal.CanCarryTools)
			{
				thisPlayer.ReleaseToolsFromBothHands();
			}
		}
		if (thisPlayer.LeftHand.Tool != null)
		{
			thisPlayer.LeftHand.Tool.OnTeleport();
		}
		if (thisPlayer.RightHand.Tool != null)
		{
			thisPlayer.RightHand.Tool.OnTeleport();
		}
		teleportCoroutine = StartCoroutine(RunTeleportTo(currentFloorPosition, destinationPlayerPosition, teleportRotation, portal, hitTool, hitToolPoint, hitToolDirection));
		thisPlayer.PlayerAudio.OnTeleport();
		if (thisPlayer.IsVisible && !thisPlayer.IsInChangingRoom)
		{
			base.photonView.RPC("RpcTeleport", PhotonTargets.Others, currentFloorPosition, (!(portal != null)) ? destinationPlayerPosition : portal.transform.position);
		}
		if (thisPlayer.PlayerUI.Menu != null && thisPlayer.PlayerUI.Menu.Visible)
		{
			thisPlayer.PlayerUI.Menu.Visible = false;
		}
		lastTeleportTime = Time.time;
		JustTeleported = true;
		JustHitToolWithTeleport = hitTool != null;
	}

	public void OnTeleportError()
	{
		thisPlayer.PlayerAudio.OnTeleportError();
	}

	public void OnTeleportLaserEnabled()
	{
		JustHitToolWithTeleport = false;
		lastTeleportEnabledTime = Time.time;
		thisPlayer.PlayerAudio.OnTeleportReady();
	}

	public void MoveCameraRig(Vector3 playerFloorPosition)
	{
		MoveCameraRig(playerFloorPosition, SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.forward);
	}

	public void MoveCameraRig(Vector3 playerFloorPosition, Vector3 playerForward)
	{
		playerForward = Vector3.ProjectOnPlane(playerForward, Vector3.up);
		Quaternion rotation = Quaternion.Euler(0f, SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.rotation).eulerAngles.y, 0f);
		Quaternion quaternion = Quaternion.LookRotation(playerForward, Vector3.up) * Quaternion.Inverse(rotation);
		Vector3 vector = playerFloorPosition - quaternion * SingletonMonoBehaviour<CameraRig>.Instance.CameraFloorOffsetLocalSpace;
		base.photonView.RPC("RpcSnapCameraRig", PhotonTargets.All, vector, quaternion, PhotonNetwork.time);
	}

	[PunRPC]
	public void RpcSnapCameraRig(Vector3 position, Quaternion rotation, double networkTimestamp)
	{
		position = position.ValueOrZeroIfBogus();
		rotation = rotation.ValueOrIdentityIfBogus();
		if (Player.LocalPlayer == thisPlayer)
		{
			SingletonMonoBehaviour<CameraRig>.Instance.transform.rotation = rotation;
			SingletonMonoBehaviour<CameraRig>.Instance.transform.position = position;
		}
		networkTransform.Snap(position, rotation, networkTimestamp);
		thisPlayer.Head.Snap(thisPlayer.Head.transform.position, thisPlayer.Head.transform.rotation, networkTimestamp);
		thisPlayer.LeftHand.Snap(thisPlayer.LeftHand.transform.position, thisPlayer.LeftHand.transform.rotation, networkTimestamp);
		thisPlayer.RightHand.Snap(thisPlayer.RightHand.transform.position, thisPlayer.RightHand.transform.rotation, networkTimestamp);
	}

	private float GetChargeAmount(float maxTime)
	{
		return Mathf.Clamp01((Time.time - lastTeleportEnabledTime) / maxTime);
	}

	private void UpdateTeleportCooldown()
	{
		if (ActivityManager.Instance != null && ActivityManager.Instance.SupportsPlayingGame)
		{
			float teleportCooldown = ActivityManager.Instance.TeleportRestrictions.GetTeleportCooldown(thisPlayer, TeleportToolHitsEnabled && JustHitToolWithTeleport);
			TeleportCooldownValue = ((teleportCooldown != 0f) ? Mathf.Clamp01((Time.time - lastTeleportTime) / teleportCooldown) : 1f);
		}
		else
		{
			TeleportCooldownValue = 1f;
		}
		TeleportOnCooldown = TeleportCooldownValue < 1f;
	}

	public IEnumerator RunTeleportTo(Vector3 sourcePlayerPosition, Vector3 destinationPlayerPosition, Quaternion teleportRotation, TeleportationPortal portal, Tool hitTool, Vector3 hitToolPoint, Vector3 hitToolDirection)
	{
		SingletonMonoBehaviour<CameraRig>.Instance.Blind = true;
		if (portal != null)
		{
			Vector3 newForward = Vector3.ProjectOnPlane((!portal.TargetRotationOverride.HasValue) ? portal.Target.forward : (portal.TargetRotationOverride.Value * Vector3.forward), Vector3.up);
			MoveCameraRig(destinationPlayerPosition, newForward);
		}
		else
		{
			Vector3 newForward2 = teleportRotation * Vector3.ProjectOnPlane(SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.forward, Vector3.up);
			MoveCameraRig(destinationPlayerPosition, newForward2);
		}
		yield return new WaitForSeconds(teleportBlindDuration);
		SingletonMonoBehaviour<CameraRig>.Instance.Blind = false;
		PlayTeleportTrail(sourcePlayerPosition, destinationPlayerPosition);
		if (hitTool != null)
		{
			float toolHitForce = toolHitForceCurve.Evaluate(ChargeAmount);
			hitTool.ApplyForce(hitToolPoint, hitToolDirection * toolHitForce);
		}
		thisPlayer.PlayerEvents.Teleport();
		teleportCoroutine = null;
	}

	[PunRPC]
	public void RpcTeleport(Vector3 sourceFloorPosition, Vector3 destinationFloorPosition)
	{
		if (thisPlayer.IsVisible)
		{
			thisPlayer.PlayerAudio.OnTeleport();
			PlayTeleportTrail(sourceFloorPosition, destinationFloorPosition);
			thisPlayer.PlayerEvents.Teleport();
		}
	}

	private void PlayTeleportTrail(Vector3 sourcePosition, Vector3 destinationPosition)
	{
		PlayerAfterImageParticles playerAfterImageParticles = UnityEngine.Object.Instantiate(afterImageParticlesPrefab);
		ActivityTeam team = thisPlayer.Team;
		if (team != null)
		{
			playerAfterImageParticles.Color = team.Color;
		}
		playerAfterImageParticles.Run(sourcePosition + thisPlayer.Head.HeightOffset, destinationPosition + thisPlayer.Head.HeightOffset);
		if (PlayerLineTrailsEnabled && lineTrail != null)
		{
			if (team != null)
			{
				lineTrail.Color = team.Color;
			}
			lineTrail.SetLatestPlayerPosition(sourcePosition, destinationPosition);
		}
	}

	public void OnPlayerDespawn()
	{
		if (PlayerLineTrailsEnabled && lineTrail != null)
		{
			lineTrail.Clear();
		}
	}
}
public class PlayerModeration : Photon.MonoBehaviour
{
	public const string VOTE_TO_KICK_COUNT_PREF = "VoteToKickCount";

	[Range(0f, 1f)]
	[SerializeField]
	private float minVoteToKickPlayerPercent = 0.85f;

	[SerializeField]
	private float minVoteToKickPlayerCount = 4f;

	[SerializeField]
	private int[] voteToKickPunishmentAccumulation = new int[3] { 10, 20, 60 };

	private List<PhotonPlayer> voteToKickList = new List<PhotonPlayer>();

	private Player thisPlayer;

	public int VoteToKickCount
	{
		get
		{
			return thisPlayer.PlayerData.GetData("VoteToKickCount", 0);
		}
		private set
		{
			thisPlayer.PlayerData.SetData("VoteToKickCount", value);
			if ((float)PhotonNetwork.playerList.Length > minVoteToKickPlayerCount)
			{
				float num = (float)value / (float)(PhotonNetwork.playerList.Length - 1);
				if (num >= minVoteToKickPlayerPercent)
				{
					KickUser(GetUserBlockDuration(), broadcastKick: true);
				}
			}
		}
	}

	public bool IsVotedForKick { get; private set; }

	public bool VoteKickHappened { get; set; }

	private void Awake()
	{
		thisPlayer = GetComponent<Player>();
	}

	public void KickPlayer(int duration = 0)
	{
		base.photonView.RPC("RpcModeratorKickPlayer", thisPlayer.PhotonPlayer, duration);
	}

	public void ShowWarningMessage(string title, string subtitle, float duration, float scale)
	{
		base.photonView.RPC("RpcModeratorShowWarning", thisPlayer.PhotonPlayer, title, subtitle, duration, scale);
	}

	[PunRPC]
	public void RpcModeratorShowWarning(string title, string subtitle, float duration, float scale)
	{
		MenuNotification.PlayNext(title, duration, subtitle, followPlayer: true, null, scale);
	}

	[PunRPC]
	public void RpcModeratorKickPlayer(int duration)
	{
		KickUser(duration);
	}

	[PunRPC]
	public void RpcModerationVoteToKick(PhotonPlayer otherPlayer)
	{
		if (base.isLocal && otherPlayer != null && !voteToKickList.Contains(otherPlayer))
		{
			voteToKickList.Add(otherPlayer);
			VoteToKickCount = voteToKickList.Count;
		}
	}

	[PunRPC]
	public void RpcModerationBroadcastKickMessage()
	{
		if (!base.isLocal)
		{
			MenuNotification.PlayNext($"User {thisPlayer.PlayerName} is voted out of the game.", 2.5f, null, followPlayer: true, null, 0.3f);
		}
	}

	private void KickUser(int duration, bool broadcastKick = false)
	{
		if (broadcastKick)
		{
			base.photonView.RPC("RpcModerationBroadcastKickMessage", PhotonTargets.Others);
		}
		AnalyticsHelper.ModerationUserKicked(duration);
		thisPlayer.ReturnToDormRoom(null);
		if (duration > 0)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.SetUserBlocked(duration);
		}
		SingletonMonoBehaviour<SessionManager>.Instance.NumberOfTimesUserGotKicked++;
		if (SingletonMonoBehaviour<WebManager>.Instance != null && SingletonMonoBehaviour<WebManager>.Instance.LocalPlayerModel != null)
		{
			SingletonMonoBehaviour<WebManager>.Instance.LocalPlayerModel.Reputation -= duration;
			SingletonMonoBehaviour<WebManager>.Instance.UpdateLocalPlayerModel();
		}
	}

	public void VoteToKickPlayer(Player localPlayer)
	{
		base.photonView.RPC("RpcModerationVoteToKick", thisPlayer.PhotonPlayer, localPlayer.PhotonPlayer);
		IsVotedForKick = true;
		AnalyticsHelper.ModerationVoteKicked(thisPlayer, localPlayer.PlayerModeration.VoteKickHappened);
		localPlayer.PlayerModeration.VoteKickHappened = true;
	}

	private int GetUserBlockDuration()
	{
		int num = 0;
		for (int i = 0; i <= SingletonMonoBehaviour<SessionManager>.Instance.NumberOfTimesUserGotKicked; i++)
		{
			int num2 = ((i >= voteToKickPunishmentAccumulation.Length) ? (voteToKickPunishmentAccumulation.Length - 1) : i);
			num += voteToKickPunishmentAccumulation[num2];
		}
		return num;
	}

	private void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		if (voteToKickList.Contains(player))
		{
			voteToKickList.Remove(player);
			VoteToKickCount = voteToKickList.Count;
		}
	}
}
[DisallowMultipleComponent]
[RequireComponent(typeof(Player))]
public class PlayerParty : Photon.MonoBehaviour
{
	public static readonly string PartyIdProperty = "PlayerPartyID";

	public static readonly string PartyColorIdProperty = "PlayerPartyColorID";

	public int MaxInviteCount = 4;

	[SerializeField]
	private RecRoomAudioClip newPartyInviteClip;

	private float timeEveryOneLeft;

	[Tooltip("Wait this long before dismembering your party after you loose everyone")]
	[SerializeField]
	private float partyIdleTimeoutWithNoPlayers = 15f;

	private float lastTimePartyListUpdated;

	[SerializeField]
	[Tooltip("Update the party membership list periodically.")]
	private float partyListUpdateInterval = 1f;

	[Tooltip("Party indicator band.")]
	public Outfit PartyBandPrefab;

	private Outfit partyBandLeft;

	private Outfit partyBandRight;

	private List<Player> groupPlayers;

	private List<Player> invitedPlayers;

	private Player thisPlayer;

	private bool partyColorDirty = true;

	private Color? _partyColor;

	public List<Player> PartyInvites { get; private set; }

	public bool IsInParty => !string.IsNullOrEmpty(CurrentPartyId);

	public int PartySize => IsInParty ? (groupPlayers.Count + 1) : 0;

	public string CurrentPartyId
	{
		get
		{
			return thisPlayer.PlayerData.GetData<string>(PartyIdProperty, null);
		}
		private set
		{
			if (SingletonMonoBehaviour<SessionManager>.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyId = value;
			}
			thisPlayer.PlayerData.SetData(PartyIdProperty, value);
