				}
				string text = null;
				foreach (Player groupPlayer in groupPlayers)
				{
					text = groupPlayer.PlayerParty.CurrentPartyColorId;
					if (!string.IsNullOrEmpty(text))
					{
						break;
					}
				}
				if (string.IsNullOrEmpty(text))
				{
					text = ((string.IsNullOrEmpty(SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId) || !IsGroupColorIdAvailable(SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId)) ? GetNextAvailableGroupColorId() : SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId);
				}
				CurrentPartyColorId = text;
			}
			partyColorDirty = true;
		}
	}

	public string CurrentPartyColorId
	{
		get
		{
			return thisPlayer.PlayerData.GetData<string>(PartyColorIdProperty, null);
		}
		private set
		{
			thisPlayer.PlayerData.SetData(PartyColorIdProperty, value);
			partyColorDirty = true;
			if (SingletonMonoBehaviour<SessionManager>.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId = value;
			}
		}
	}

	public Color? PartyColor
	{
		get
		{
			if (partyColorDirty)
			{
				_partyColor = null;
				string currentPartyColorId = CurrentPartyColorId;
				if (!string.IsNullOrEmpty(currentPartyColorId) && PUNNetworkManager.Instance != null)
				{
					ColorVault.ColorToGuid colorToGuid = PUNNetworkManager.Instance.GroupColorVault.Find(currentPartyColorId);
					if (colorToGuid != null)
					{
						_partyColor = colorToGuid.color;
						partyColorDirty = false;
					}
				}
			}
			return _partyColor;
		}
	}

	public event Action<bool> PartyInvitesUpdated;

	public event Action PartyUpdateReceived;

	private void Awake()
	{
		thisPlayer = GetComponent<Player>();
		PartyInvites = new List<Player>();
		groupPlayers = new List<Player>();
		invitedPlayers = new List<Player>();
	}

	private void Start()
	{
		if (base.isLocal && SingletonMonoBehaviour<SessionManager>.Instance != null)
		{
			CurrentPartyId = SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyId;
			if (IsInParty)
			{
				Invoke("DeferredUpdatePartyColor", 1f);
				Invoke("DeferredUpdatePartyColor", 5f);
			}
			thisPlayer.LeftHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
			thisPlayer.RightHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
		}
		partyBandRight = thisPlayer.PlayerOutfit.InstantiateNewOutfitPrefab(PartyBandPrefab, Player.BodyPart.RightHand, ownedByPlayerOutfit: false);
		partyBandLeft = thisPlayer.PlayerOutfit.InstantiateNewOutfitPrefab(PartyBandPrefab, Player.BodyPart.LeftHand, ownedByPlayerOutfit: false);
	}

	private void Update()
	{
		UpdateBraceletColor(PlayerHand.HandType.Left);
		UpdateBraceletColor(PlayerHand.HandType.Right);
		if (base.isLocal && Time.time - lastTimePartyListUpdated > partyListUpdateInterval)
		{
			lastTimePartyListUpdated = Time.time;
			UpdatePartyLists();
		}
	}

	private void UpdateBraceletColor(PlayerHand.HandType handType)
	{
		if (handType != PlayerHand.HandType.Unknown && !(thisPlayer == null))
		{
			Color? partyColor = PartyColor;
			PlayerHand playerHand = ((handType != PlayerHand.HandType.Left) ? thisPlayer.RightHand : thisPlayer.LeftHand);
			Outfit outfit = ((handType != PlayerHand.HandType.Left) ? partyBandRight : partyBandLeft);
			bool flag = partyColor.HasValue && playerHand != null && playerHand.IsVisible;
			outfit.gameObject.SetActive(flag);
			if (flag && outfit.SkinnedMeshRenderer.material.color != partyColor.Value)
			{
				outfit.SkinnedMeshRenderer.material.color = partyColor.Value;
				outfit.GetComponent<AnimateInOut>().PlayEffect(animIn: true);
			}
			else if (!IsInParty)
			{
				outfit.SkinnedMeshRenderer.material.color = Color.clear;
			}
		}
	}

	public virtual void OnPhotonPlayerPropertiesChanged(object[] playerAndUpdatedProps)
	{
		partyColorDirty = true;
	}

	public virtual void OnPhotonPlayerDisconnected(PhotonPlayer otherPlayer)
	{
		UpdatePartyLists(forcePartyChange: true);
	}

	private void PlayerHandGestures_GestureDetected(PlayerHand myHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture)
	{
		if (!base.isLocal || gesture != PlayerHandGestures.Gesture.Fistbump)
		{
			return;
		}
		bool flag = false;
		if (otherHand.ThisPlayer.PlayerParty.IsInParty && !IsInParty)
		{
			CurrentPartyId = otherHand.ThisPlayer.PlayerParty.CurrentPartyId;
			UpdatePartyLists();
			flag = true;
		}
		else if (!otherHand.ThisPlayer.PlayerParty.IsInParty && IsInParty)
		{
			flag = true;
		}
		else if (otherHand.ThisPlayer.PlayerParty.IsInParty && IsInParty && otherHand.ThisPlayer.PlayerParty.CurrentPartyId != CurrentPartyId)
		{
			flag = true;
			if (base.photonView.owner.ID > otherHand.ThisPlayer.photonView.owner.ID)
			{
				UpdatePartyLists();
				string currentPartyId = otherHand.ThisPlayer.PlayerParty.CurrentPartyId;
				foreach (Player groupPlayer in groupPlayers)
				{
					groupPlayer.photonView.RPC("RpcAutoJoinParty", groupPlayer.photonView.owner, currentPartyId);
				}
				CurrentPartyId = currentPartyId;
			}
		}
		else if (!otherHand.ThisPlayer.PlayerParty.IsInParty && !IsInParty)
		{
			flag = true;
			if (base.photonView.owner.ID > otherHand.ThisPlayer.photonView.owner.ID)
			{
				CurrentPartyId = Guid.NewGuid().ToString();
				otherHand.ThisPlayer.photonView.RPC("RpcAutoJoinParty", otherHand.ThisPlayer.photonView.owner, CurrentPartyId);
			}
		}
		if (flag)
		{
			MenuNotification.PlayNext("Party Join", 2f, null, followPlayer: false, (myHand.transform.position + otherHand.transform.position) / 2f, 0.3f);
		}
	}

	[PunRPC]
	public void RpcAutoJoinParty(string partyId)
	{
		CurrentPartyId = partyId;
		UpdatePartyLists();
	}

	private void DeferredUpdatePartyColor()
	{
		PhotonPlayer[] playerList = PhotonNetwork.playerList;
		foreach (PhotonPlayer photonPlayer in playerList)
		{
			Player player = photonPlayer.TagObject as Player;
			if (player != null && player.PlayerParty.IsInParty && player.PlayerParty.CurrentPartyId == CurrentPartyId)
			{
				string currentPartyColorId = player.PlayerParty.CurrentPartyColorId;
				if (!string.IsNullOrEmpty(currentPartyColorId))
				{
					CurrentPartyColorId = currentPartyColorId;
					break;
				}
			}
		}
	}

	public bool CanInvitePlayer(Player player)
	{
		return player != null && !groupPlayers.Contains(player);
	}

	public void InvitePlayer(Player player)
	{
		if (CanInvitePlayer(player))
		{
			invitedPlayers.Add(player);
			if (!IsInParty)
			{
				CurrentPartyId = Guid.NewGuid().ToString();
			}
			player.photonView.RPC("RpcInvitePlayerToParty", player.photonView.owner, PhotonNetwork.player);
		}
	}

	private string GetNextAvailableGroupColorId()
	{
		List<string> list = new List<string>();
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer player in otherPlayers)
		{
			string customPropertyString = player.GetCustomPropertyString(PartyColorIdProperty);
			if (!string.IsNullOrEmpty(customPropertyString) && !list.Contains(customPropertyString))
			{
				list.Add(customPropertyString);
			}
		}
		PUNNetworkManager.Instance.GroupColorVault.Colors.Shuffle();
		foreach (ColorVault.ColorToGuid color in PUNNetworkManager.Instance.GroupColorVault.Colors)
		{
			if (!list.Contains(color.guidString))
			{
				return color.guidString;
			}
		}
		UnityEngine.Debug.LogError("Could not find an unused party color, this is madness. Should never happen in a max 8 player game, add colors to PUNNetworkManager ColorVault.");
		return null;
	}

	private bool IsGroupColorIdAvailable(string playerPartyColorId)
	{
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer player in otherPlayers)
		{
			string customPropertyString = player.GetCustomPropertyString(PartyColorIdProperty);
			string customPropertyString2 = player.GetCustomPropertyString(PartyIdProperty);
			if (!string.IsNullOrEmpty(customPropertyString) && playerPartyColorId == customPropertyString && !string.IsNullOrEmpty(customPropertyString2) && customPropertyString2 != CurrentPartyId)
			{
				return false;
			}
		}
		return true;
	}

	public void KickPlayer(Player target)
	{
		if (IsInPartyWith(target))
		{
			target.photonView.RPC("RpcKickedFromParty", target.photonView.owner, CurrentPartyId);
		}
	}

	[PunRPC]
	public void RpcInvitePlayerToParty(PhotonPlayer invitingPhotonPlayer)
	{
		Player player = invitingPhotonPlayer.ToPlayer();
		if (!(player != null))
		{
			return;
		}
		if (groupPlayers.Contains(player) || PartyInvites.Contains(player))
		{
			UnityEngine.Debug.LogWarning("I am getting multiple invites from : " + player);
			return;
		}
		PartyInvites.Add(player);
		AudioManager.Play2DSFX(newPartyInviteClip);
		while (PartyInvites.Count > MaxInviteCount)
		{
			RespondToInvite(PartyInvites[0], response: false);
		}
		if (this.PartyInvitesUpdated != null)
		{
			this.PartyInvitesUpdated(obj: true);
		}
	}

	public void RespondToInvite(Player inviter, bool response)
	{
		if (!PartyInvites.Contains(inviter))
		{
			return;
		}
		PartyInvites.Remove(inviter);
		if (this.PartyInvitesUpdated != null)
		{
			this.PartyInvitesUpdated(obj: false);
		}
		inviter.photonView.RPC("RpcRespondToPartyInvite", inviter.photonView.owner, PhotonNetwork.player, response);
		if (response)
		{
			if (IsInParty)
			{
				LeaveCurrentParty();
			}
			string currentPartyId = inviter.PlayerParty.CurrentPartyId;
			if (!string.IsNullOrEmpty(currentPartyId))
			{
				CurrentPartyId = currentPartyId;
				GroupPlayersAdd(inviter);
			}
		}
		UpdatePartyLists();
	}

	public string[] GetExpectedPhotonUsers()
	{
		UpdatePartyLists();
		if (groupPlayers.Count > 0)
		{
			string[] array = new string[groupPlayers.Count + 1];
			for (int i = 0; i < groupPlayers.Count; i++)
			{
				array[i] = groupPlayers[i].photonView.owner.userId;
			}
			array[groupPlayers.Count] = base.photonView.owner.userId;
			return array;
		}
		return null;
	}

	[PunRPC]
	public void RpcRespondToPartyInvite(PhotonPlayer respondingPhotonPlayer, bool response)
	{
		Player player = respondingPhotonPlayer.ToPlayer();
		if (player != null)
		{
			if (response && !groupPlayers.Contains(player))
			{
				GroupPlayersAdd(player);
			}
			invitedPlayers.Remove(player);
		}
		UpdatePartyLists();
	}

	[PunRPC]
	public void RpcKickedFromParty(string partyId)
	{
		if (!(partyId != CurrentPartyId))
		{
			LeaveCurrentParty();
		}
	}

	private bool IsValidPartyPlayer(Player player)
	{
		return player != null && player.photonView.owner != base.photonView.owner && IsInParty && player.PlayerParty.CurrentPartyId == CurrentPartyId;
	}

	private void UpdatePartyLists(bool forcePartyChange = false)
	{
		bool flag = false || forcePartyChange;
		if (IsInParty)
		{
			Player[] array = groupPlayers.ToArray();
			foreach (Player player in array)
			{
				if (!IsValidPartyPlayer(player))
				{
					GroupPlayersRemove(player);
					flag = true;
				}
			}
			PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
			foreach (PhotonPlayer photonPlayer in otherPlayers)
			{
				Player player2 = photonPlayer.TagObject as Player;
				if (player2 != null && IsValidPartyPlayer(player2) && !groupPlayers.Contains(player2))
				{
					GroupPlayersAdd(player2);
					flag = true;
				}
			}
		}
		else if (groupPlayers.Count > 0)
		{
			groupPlayers.Clear();
			flag = true;
		}
		if (flag)
		{
			Player[] array2 = PartyInvites.ToArray();
			foreach (Player player3 in array2)
			{
				if (groupPlayers.Contains(player3) || player3 == null)
				{
					PartyInvites.Remove(player3);
					if (this.PartyInvitesUpdated != null)
					{
						this.PartyInvitesUpdated(obj: false);
					}
				}
			}
			Player[] array3 = invitedPlayers.ToArray();
			foreach (Player player4 in array3)
			{
				if (groupPlayers.Contains(player4) || player4 == null)
				{
					invitedPlayers.Remove(player4);
				}
			}
			if (this.PartyUpdateReceived != null)
			{
				this.PartyUpdateReceived();
			}
		}
		if (IsInParty && groupPlayers.Count == 0 && invitedPlayers.Count == 0)
		{
			if (flag)
			{
				timeEveryOneLeft = Time.time;
			}
			else if (Time.time - timeEveryOneLeft > partyIdleTimeoutWithNoPlayers)
			{
				LeaveCurrentParty();
			}
		}
	}

	private void GroupPlayersAdd(Player other)
	{
		groupPlayers.Add(other);
		if (base.isLocal)
		{
			AnalyticsHelper.PartyJoinedOther(other, PartySize);
		}
	}

	private void GroupPlayersRemove(Player other)
	{
		groupPlayers.Remove(other);
		if (base.isLocal)
		{
			AnalyticsHelper.PartyLeftOther(other, PartySize);
		}
	}

	public void LeaveCurrentParty()
	{
		if (groupPlayers.Count > 0)
		{
			AnalyticsHelper.PartyLeftSelf();
		}
		groupPlayers.Clear();
		CurrentPartyId = null;
	}

	public bool IsInPartyWith(Player player)
	{
		return player != null && IsInParty && groupPlayers.Contains(player);
	}

	public bool IsInvitedToParty(Player target)
	{
		return target != null && invitedPlayers.Contains(target);
	}

	[PunRPC]
	public void RpcDebugLeaveRoom()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.SwitchActivity("lockerroom");
		}
	}
}
public class PlayerStats : UnityEngine.MonoBehaviour
{
	public enum RecroomSteamStat
	{
		None = -1,
		xp,
		level,
		highfives,
		fistbumps,
		paddleball_games,
		paddleball_wins,
		paddleball_losses,
		discgolf_games,
		discgolf_wins,
		discgolf_losses,
		dodgeball_games,
		dodgeball_wins,
		dodgeball_losses,
		paintball_games,
		paintball_wins,
		paintball_losses,
		charades_games,
		record_video
	}

	public enum RecroomSteamAchievement
	{
		None = -1,
		login_first,
		outfit_first
	}

	public enum RecroomSteamLeaderboards
	{
		None = -1,
		paddleball_weekly,
		paddleball_alltime,
		paintball_hits_weekly,
		paintball_hits_alltime,
		paintball_wins_weekly,
		paintball_wins_alltime,
		paintball_flags_weekly,
		paintball_flags_alltime
	}

	private enum ActivityStat
	{
		games,
		wins,
		losses,
		wins_weekly
	}

	private string[] steamStatNames;

	private RecroomSteamStat[] steamStatValues;

	private Player thisPlayer;

	private CallResult<UserStatsReceived_t> remoteUserStatsReceived;

	protected Callback<UserStatsReceived_t> localUserStatsReceived;

	private Callback<UserStatsStored_t> localUserStatsStored;

	private Callback<UserAchievementStored_t> localUserAchievementStored;

	public bool IsInitialized { get; private set; }

	public event Action<Player, UserStatsReceived_t> StatsReceived;

	private void Awake()
	{
		thisPlayer = GetComponent<Player>();
		steamStatNames = Enum.GetNames(typeof(RecroomSteamStat));
		steamStatValues = (RecroomSteamStat[])Enum.GetValues(typeof(RecroomSteamStat));
	}

	private void Start()
	{
		if (!SteamManager.Initialized)
		{
			return;
		}
		RequestUserStats();
		if (thisPlayer.isLocal)
		{
			thisPlayer.LeftHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
			thisPlayer.RightHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
			if (ActivityManager.Instance != null && ActivityManager.Instance.SupportsPlayingGame)
			{
				thisPlayer.PlayerEvents.ActivityWonEvent += PlayerEvents_ActivityWonEvent;
			}
			StartCoroutine(RunFirstLoginAchievement());
			if (!GetAchievement(RecroomSteamAchievement.outfit_first))
			{
				thisPlayer.PlayerEvents.OutfitEquipEvent += PlayerEvents_OutfitEquipEvent;
			}
		}
	}

	private void PlayerEvents_OutfitEquipEvent(Player.BodyPart bodyPart)
	{
		if (thisPlayer.IsInChangingRoom)
		{
			SetAchievement(RecroomSteamAchievement.outfit_first);
			thisPlayer.PlayerEvents.OutfitEquipEvent -= PlayerEvents_OutfitEquipEvent;
		}
	}

	private void PlayerEvents_ActivityWonEvent(bool playerWon)
	{
		IncrementIntStat(GetActivitySteamStat(ActivityStat.games), 1);
		if (playerWon)
		{
			IncrementIntStat(GetActivitySteamStat(ActivityStat.wins), 1);
			IncrementIntStat(GetActivitySteamStat(ActivityStat.wins_weekly), 1);
			UpdateActivityWonLeaderboards();
		}
		else
		{
			IncrementIntStat(GetActivitySteamStat(ActivityStat.losses), 1);
		}
		if (SingletonMonoBehaviour<WebManager>.Instance != null && SingletonMonoBehaviour<WebManager>.Instance.LocalPlayerModel != null)
		{
			SingletonMonoBehaviour<WebManager>.Instance.LocalPlayerModel.XP += 100 + (playerWon ? 50 : 0);
			SingletonMonoBehaviour<WebManager>.Instance.UpdateLocalPlayerModel();
		}
	}

	private void UpdateActivityWonLeaderboards()
	{
		if (ActivityManager.ActivityName == "paddleball")
		{
			SingletonMonoBehaviour<LeaderboardManager>.Instance.IncrementLeaderboardScore(RecroomSteamLeaderboards.paddleball_weekly);
			SingletonMonoBehaviour<LeaderboardManager>.Instance.IncrementLeaderboardScore(RecroomSteamLeaderboards.paddleball_alltime);
		}
		else if (ActivityManager.ActivityName == "paintball")
		{
			SingletonMonoBehaviour<LeaderboardManager>.Instance.IncrementLeaderboardScore(RecroomSteamLeaderboards.paintball_wins_weekly);
			SingletonMonoBehaviour<LeaderboardManager>.Instance.IncrementLeaderboardScore(RecroomSteamLeaderboards.paintball_wins_alltime);
		}
	}

	private void PlayerHandGestures_GestureDetected(PlayerHand myHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture)
	{
		RecroomSteamStat stat = RecroomSteamStat.None;
		if (gesture == PlayerHandGestures.Gesture.Fistbump && !SingletonMonoBehaviour<SessionManager>.Instance.Fistbumps.Contains(otherHand.ThisPlayer.SteamID.m_SteamID))
		{
			stat = RecroomSteamStat.fistbumps;
			SingletonMonoBehaviour<SessionManager>.Instance.Fistbumps.Add(otherHand.ThisPlayer.SteamID.m_SteamID);
		}
		else if (gesture == PlayerHandGestures.Gesture.Highfive && !SingletonMonoBehaviour<SessionManager>.Instance.Highfives.Contains(otherHand.ThisPlayer.SteamID.m_SteamID))
		{
			stat = RecroomSteamStat.highfives;
			SingletonMonoBehaviour<SessionManager>.Instance.Highfives.Add(otherHand.ThisPlayer.SteamID.m_SteamID);
		}
		IncrementIntStat(stat, 1);
	}

	private IEnumerator RunFirstLoginAchievement()
	{
		if (PUNNetworkManager.Instance.IsInLockerRoom && !GetAchievement(RecroomSteamAchievement.login_first))
		{
			yield return new WaitForSeconds(4f);
			SetAchievement(RecroomSteamAchievement.login_first);
		}
	}

	public bool SetAchievement(RecroomSteamAchievement achievement)
	{
		if (thisPlayer.isLocal)
		{
			if (SteamUserStats.GetAchievement(achievement.ToString(), out var pbAchieved) && !pbAchieved)
			{
				return SteamUserStats.SetAchievement(achievement.ToString());
			}
		}
		else
		{
			UnityEngine.Debug.LogError("SetAchievement can only be called for the local user.");
		}
		return false;
	}

	public bool GetAchievement(RecroomSteamAchievement achievement)
	{
		bool pbAchieved2;
		if (thisPlayer.isLocal)
		{
			if (SteamUserStats.GetAchievement(achievement.ToString(), out var pbAchieved))
			{
				return pbAchieved;
			}
		}
		else if (thisPlayer.SteamID.IsValid() && SteamUserStats.GetUserAchievement(thisPlayer.SteamID, achievement.ToString(), out pbAchieved2))
		{
			return pbAchieved2;
		}
		return false;
	}

	public bool IncrementIntStat(RecroomSteamStat stat, int value)
	{
		if (GetIntStat(stat, out var value2))
		{
			return SetIntStat(stat, value2 + value);
		}
		return false;
	}

	public bool SetIntStat(RecroomSteamStat stat, int value)
	{
		if (stat == RecroomSteamStat.None || !thisPlayer.SteamID.IsValid())
		{
			return false;
		}
		if (thisPlayer.isLocal)
		{
			bool result = SteamUserStats.SetStat(stat.ToString(), value);
			SteamUserStats.StoreStats();
			return result;
		}
		UnityEngine.Debug.LogError("Can not call SetStats for other users. User : " + thisPlayer);
		return false;
	}

	public bool GetIntStat(RecroomSteamStat stat, out int value)
	{
		RequestUserStats();
		if (stat == RecroomSteamStat.None || !thisPlayer.SteamID.IsValid())
		{
			value = -1;
			return false;
		}
		if (thisPlayer.isLocal)
		{
			return SteamUserStats.GetStat(stat.ToString(), out value);
		}
		return SteamUserStats.GetUserStat(thisPlayer.SteamID, stat.ToString(), out value);
	}

	private RecroomSteamStat GetActivitySteamStat(ActivityStat activityStat)
	{
		string text = ActivityManager.ActivityName + "_" + activityStat;
		for (int i = 0; i < steamStatNames.Length; i++)
		{
			if (text == steamStatNames[i])
			{
				return steamStatValues[i];
			}
		}
		return RecroomSteamStat.None;
	}

	private void RequestUserStats()
	{
		if (thisPlayer.isLocal)
		{
			if (localUserStatsReceived == null)
			{
				localUserStatsStored = Callback<UserStatsStored_t>.Create(OnLocalUserStatsStored);
				localUserStatsReceived = Callback<UserStatsReceived_t>.Create(OnLocalUserStatsReceived);
				localUserAchievementStored = Callback<UserAchievementStored_t>.Create(OnLocalUserAchievementStored);
			}
			SteamUserStats.RequestCurrentStats();
		}
		else
		{
			if (remoteUserStatsReceived == null)
			{
				remoteUserStatsReceived = CallResult<UserStatsReceived_t>.Create(OnRemoteUserStatsReceived);
			}
			SteamAPICall_t hAPICall = SteamUserStats.RequestUserStats(thisPlayer.SteamID);
			remoteUserStatsReceived.Set(hAPICall);
		}
	}

	private void OnLocalUserAchievementStored(UserAchievementStored_t param)
	{
	}

	private void OnLocalUserStatsReceived(UserStatsReceived_t pCallback)
	{
		if (pCallback.m_eResult == EResult.k_EResultOK)
		{
			IsInitialized = true;
		}
		if (this.StatsReceived != null)
		{
			this.StatsReceived(thisPlayer, pCallback);
		}
	}

	private void OnLocalUserStatsStored(UserStatsStored_t pCallback)
	{
	}

	private void OnRemoteUserStatsReceived(UserStatsReceived_t pCallback, bool bIOFailure)
	{
		if (pCallback.m_eResult == EResult.k_EResultOK)
		{
			IsInitialized = true;
		}
		if (this.StatsReceived != null)
		{
			this.StatsReceived(thisPlayer, pCallback);
		}
	}
}
public class PlayerTeleportDecal : UnityEngine.MonoBehaviour
{
	public enum DecalVisibilityMode
	{
		None,
		Ground,
		GroundAndArrow,
		Avatar,
		AvatarAndGround,
		AvatarAndGroundAndArrow,
		ToolHit
	}

	[SerializeField]
	[Header("Avatar")]
	private Transform head;

	[SerializeField]
	private Transform body;

	[SerializeField]
	private Transform ground;

	[Header("Rotation Arrow")]
	[SerializeField]
	private Transform groundArrow;

	[Header("Tool Hit Visual")]
	[SerializeField]
	private TeleportChargeVisual toolHitVisual;

	[SerializeField]
	[Header("Materials")]
	private Material validMaterial;

	[SerializeField]
	private Material invalidMaterial;

	[HideInInspector]
	public List<Renderer> Renderers = new List<Renderer>();

	private DecalVisibilityMode visibilityMode;

	private bool isValidPosition;

	public DecalVisibilityMode VisibilityMode
	{
		get
		{
			return visibilityMode;
		}
		set
		{
			visibilityMode = value;
			bool active = visibilityMode == DecalVisibilityMode.Avatar || visibilityMode == DecalVisibilityMode.AvatarAndGround || visibilityMode == DecalVisibilityMode.AvatarAndGroundAndArrow;
			head.gameObject.SetActive(active);
			body.gameObject.SetActive(active);
			bool active2 = visibilityMode == DecalVisibilityMode.Ground || visibilityMode == DecalVisibilityMode.GroundAndArrow || visibilityMode == DecalVisibilityMode.AvatarAndGround || visibilityMode == DecalVisibilityMode.AvatarAndGroundAndArrow;
			ground.gameObject.SetActive(active2);
			bool active3 = visibilityMode == DecalVisibilityMode.AvatarAndGroundAndArrow || visibilityMode == DecalVisibilityMode.GroundAndArrow;
			groundArrow.gameObject.SetActive(active3);
			bool active4 = visibilityMode == DecalVisibilityMode.ToolHit;
			toolHitVisual.gameObject.SetActive(active4);
		}
	}

	public bool IsValidPosition
	{
		get
		{
			return isValidPosition;
		}
		set
		{
			if (isValidPosition != value)
			{
				isValidPosition = value;
				UpdateMaterials();
			}
		}
	}

	private void Awake()
	{
		Renderers.AddRange(GetComponentsInChildren<Renderer>(includeInactive: true));
		Renderer[] componentsInChildren = groundArrow.GetComponentsInChildren<Renderer>(includeInactive: true);
		foreach (Renderer item in componentsInChildren)
		{
			Renderers.Remove(item);
		}
		VisibilityMode = DecalVisibilityMode.None;
		UpdateMaterials();
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
	}

	public void UpdateAvatarDecal(Player player, Vector3 groundPoint)
	{
		ground.position = groundPoint;
		head.position = groundPoint + player.Head.HeightOffset;
		head.rotation = player.Head.transform.rotation;
		body.position = head.position - player.Body.ToHead;
		body.rotation = player.Body.transform.rotation;
	}

	public void UpdateRotationDecal(bool enabled, Player player, Quaternion teleportRotation)
	{
		if (enabled)
		{
			switch (VisibilityMode)
			{
			case DecalVisibilityMode.AvatarAndGround:
				VisibilityMode = DecalVisibilityMode.AvatarAndGroundAndArrow;
				break;
			case DecalVisibilityMode.Ground:
				VisibilityMode = DecalVisibilityMode.GroundAndArrow;
				break;
			}
			groundArrow.rotation = Quaternion.Euler(0f, player.Head.transform.rotation.eulerAngles.y, 0f) * teleportRotation;
		}
	}

	public void UpdateToolHitDecal(bool enabled, float charge, Vector3 toolHitPosition, Vector3 toolHitNormal)
	{
		if (enabled)
		{
			VisibilityMode = DecalVisibilityMode.ToolHit;
			toolHitVisual.Charge = charge;
			toolHitVisual.transform.position = toolHitPosition;
			toolHitVisual.transform.rotation = Quaternion.LookRotation(toolHitNormal, Vector3.up);
		}
	}

	private void UpdateMaterials()
	{
		foreach (Renderer renderer in Renderers)
		{
			renderer.material = ((!IsValidPosition) ? invalidMaterial : validMaterial);
		}
	}
}
public class PlayerTeleportRegionTracker : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private CollisionForwarder headTracker;

	[SerializeField]
	private CollisionForwarder torsoTracker;

	private Transform head;

	private Transform body;

	public Player ThisPlayer { get; private set; }

	private void Awake()
	{
		ThisPlayer = base.gameObject.GetComponentInParents<Player>();
		head = ThisPlayer.Head.transform;
		body = ThisPlayer.Body.transform;
	}

	private void Start()
	{
		headTracker.TriggerEnter += Tracker_TriggerEnter;
		torsoTracker.TriggerEnter += Tracker_TriggerEnter;
		headTracker.TriggerExit += Tracker_TriggerExit;
		torsoTracker.TriggerExit += Tracker_TriggerExit;
	}

	private void FixedUpdate()
	{
		if (head != null)
		{
			headTracker.Rigidbody.MovePosition(head.position);
			headTracker.Rigidbody.MoveRotation(head.rotation);
		}
		if (body != null)
		{
			torsoTracker.Rigidbody.MovePosition(body.position);
			torsoTracker.Rigidbody.MoveRotation(body.rotation);
		}
	}

	private bool CheckAvatarChangingRegion(Collider collider)
	{
		return collider.gameObject.layer == 5 && collider.gameObject.CompareTag("AvatarChangingRegion");
	}

	private void Tracker_TriggerEnter(Collider other)
	{
		if (CheckAvatarChangingRegion(other))
		{
			ThisPlayer.IsInChangingRoom = true;
		}
	}

	private void Tracker_TriggerExit(Collider other)
	{
		if (CheckAvatarChangingRegion(other))
		{
			ThisPlayer.IsInChangingRoom = false;
		}
	}
}
[DisallowMultipleComponent]
public class PlayerUI : Photon.MonoBehaviour
{
	[SerializeField]
	private Transform positionGlow;

	[SerializeField]
	private float positionGlowVisibleDuration = 0.5f;

	[SerializeField]
	private float positionGlowHeightOffset = 1f;

	[SerializeField]
	private Text nameLabelText;

	[SerializeField]
	private float nameLabelTextFadeSpeed = 15f;

	[SerializeField]
	private float nameHighlightAlphaMin = 0.15f;

	[SerializeField]
	private float nameHighlightAlphaMax = 0.95f;

	[SerializeField]
	private float nameHighlightOnTeamAlphaMin = 0.85f;

	[SerializeField]
	private float nameHighlightOnTeamAlphaMax = 1f;

	[SerializeField]
	private PlayerMenu menuPrefab;

	[SerializeField]
	private ParticleSystem highFiveParticles;

	[SerializeField]
	private ParticleSystem fistBumpParticles;

	[SerializeField]
	private UIPlayerCamera uIPlayerCameraPrefab;

	private Player thisPlayer;

	private bool _nameVisible;

	private float nameHighlightTargetAlpha = 1f;

	private bool _nameHighlighted;

	private float lastglowVisibleTime;

	private bool _glowVisible;

	public UIPlayerCamera UIPlayerCamera { get; private set; }

	private bool IsMenuButtonUp => IsLeftMenuButtonUp || IsRightMenuButtonUp;

	private bool IsLeftMenuButtonUp => SingletonMonoBehaviour<CameraRig>.IsInitialized && thisPlayer.LeftHand.ControllerIO != null && thisPlayer.LeftHand.Tool == null && thisPlayer.LeftHand.ControllerIO.MenuButtonUp;

	private bool IsRightMenuButtonUp => SingletonMonoBehaviour<CameraRig>.IsInitialized && thisPlayer.RightHand.ControllerIO != null && thisPlayer.RightHand.Tool == null && thisPlayer.RightHand.ControllerIO.MenuButtonUp;

	private bool NameVisible
	{
		get
		{
			return _nameVisible;
		}
		set
		{
			_nameVisible = value;
			nameLabelText.transform.parent.gameObject.SetActive(_nameVisible);
		}
	}

	private bool NameHighlighted
	{
		get
		{
			return _nameHighlighted;
		}
		set
		{
			_nameHighlighted = value;
			if (PlayerTeam == null)
			{
				nameHighlightTargetAlpha = ((!value) ? nameHighlightAlphaMin : nameHighlightAlphaMax);
			}
			else
			{
				nameHighlightTargetAlpha = ((!value) ? nameHighlightOnTeamAlphaMin : nameHighlightOnTeamAlphaMax);
			}
		}
	}

	public bool GlowVisible
	{
		get
		{
			return _glowVisible;
		}
		set
		{
			if (value != _glowVisible)
			{
				_glowVisible = value && ActivityManager.Instance.CanHighlightPlayer(thisPlayer.PhotonPlayer);
				positionGlow.gameObject.SetActive(_glowVisible);
			}
			if (_glowVisible)
			{
				lastglowVisibleTime = Time.time;
			}
		}
	}

	private ActivityTeam PlayerTeam
	{
		get
		{
			if (thisPlayer == null || ActivityManager.Instance == null || ActivityManager.Instance.GameState != ActivityGameState.PlayingGame)
			{
				return null;
			}
			return ActivityManager.Instance.PlayerManager.GetPlayerTeam(thisPlayer.PhotonPlayer);
		}
	}

	public PlayerMenu Menu { get; private set; }

	[Obsolete("Use the PlayerMenu system")]
	public void HideMenu()
	{
		throw new NotImplementedException();
	}

	private void Awake()
	{
		thisPlayer = GetComponent<Player>();
		thisPlayer.VisibilityChanged += ThisPlayer_VisibilityChanged;
		nameLabelText.transform.parent.gameObject.SetActive(value: false);
		Menu = UnityEngine.Object.Instantiate(menuPrefab);
		Menu.ThisPlayer = thisPlayer;
		thisPlayer.SetParentPlayerRoot(Menu.transform);
	}

	private void Start()
	{
		if (base.isLocal)
		{
			Menu.CreateLocalUserMenues();
			thisPlayer.PlayerParty.PartyInvitesUpdated += PlayerParty_PartyInvitesUpdated;
			thisPlayer.PlayerParty.PartyUpdateReceived += PlayerParty_PartyUpdateReceived;
			SingletonMonoBehaviour<CameraRig>.Instance.HeadGestureDetect.GestureDetected += HeadGestureDetect_GestureDetected;
			NameVisible = false;
			UIPlayerCamera = UnityEngine.Object.Instantiate(uIPlayerCameraPrefab);
			thisPlayer.SetParentPlayerRoot(UIPlayerCamera.transform);
		}
		else if (Player.LocalPlayer != null && Player.LocalPlayer.PlayerUI.Menu != null && Player.LocalPlayer.PlayerUI.Menu.Visible)
		{
			Player.LocalPlayer.PlayerUI.Menu.Refresh();
		}
		thisPlayer.LeftHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
		thisPlayer.RightHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
	}

	private void HeadGestureDetect_GestureDetected(HeadGestureDetect.Gesture gesture)
	{
	}

	private void PlayerHandGestures_GestureDetected(PlayerHand myHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture)
	{
		switch (gesture)
		{
		case PlayerHandGestures.Gesture.Highfive:
			thisPlayer.PlayerAudio.OnHighFive();
			if (highFiveParticles != null)
			{
				ParticleSystem particleSystem2 = UnityEngine.Object.Instantiate(highFiveParticles);
				particleSystem2.transform.position = (myHand.transform.position + otherHand.transform.position) / 2f;
				particleSystem2.Play();
				UnityEngine.Object.Destroy(particleSystem2.gameObject, particleSystem2.duration);
			}
			break;
		case PlayerHandGestures.Gesture.Fistbump:
			thisPlayer.PlayerAudio.OnFistBump();
			if (fistBumpParticles != null)
			{
				ParticleSystem particleSystem = UnityEngine.Object.Instantiate(fistBumpParticles);
				particleSystem.transform.position = (myHand.transform.position + otherHand.transform.position) / 2f;
				particleSystem.Play();
				UnityEngine.Object.Destroy(particleSystem.gameObject, particleSystem.duration);
			}
			break;
		}
		if (base.isLocal)
		{
			myHand.Vibrate(100);
		}
	}

	private void OnDestroy()
	{
		if (thisPlayer != null)
		{
			thisPlayer.VisibilityChanged -= ThisPlayer_VisibilityChanged;
			if (base.isLocal)
			{
				thisPlayer.PlayerParty.PartyInvitesUpdated -= PlayerParty_PartyInvitesUpdated;
				thisPlayer.PlayerParty.PartyUpdateReceived -= PlayerParty_PartyUpdateReceived;
			}
		}
	}

	private void Update()
	{
		if (base.isLocal && IsMenuButtonUp)
		{
			Player remotePlayer = null;
			if (IsLeftMenuButtonUp && thisPlayer.LeftHand.TargetRemotePlayer != null)
			{
				remotePlayer = thisPlayer.LeftHand.TargetRemotePlayer;
			}
			else if (IsRightMenuButtonUp && thisPlayer.RightHand.TargetRemotePlayer != null)
			{
				remotePlayer = thisPlayer.RightHand.TargetRemotePlayer;
			}
			Menu.MenuButtonPressed(remotePlayer);
		}
		if (!base.isLocal)
		{
			NameHighlighted = thisPlayer.IsTalking;
			NameVisible = SingletonMonoBehaviour<SettingsManager>.Instance.ShowNames;
		}
		ActivityTeam activityTeam = ((!(thisPlayer != null)) ? null : thisPlayer.Team);
		if (NameVisible)
		{
			nameLabelText.text = ((base.owner == null) ? "Name" : base.owner.name);
			Color color = Color.white;
			if (activityTeam != null)
			{
				color = activityTeam.Color;
			}
			else if (thisPlayer.PlayerParty.PartyColor.HasValue)
			{
				color = thisPlayer.PlayerParty.PartyColor.Value;
			}
			color.a = nameLabelText.color.a;
			if (color.a != nameHighlightTargetAlpha)
			{
				color.a = Mathf.SmoothStep(color.a, nameHighlightTargetAlpha, Time.deltaTime * nameLabelTextFadeSpeed);
			}
			nameLabelText.color = color;
		}
		if (activityTeam != null)
		{
			thisPlayer.PlayerOutfit.TeamIndicator = activityTeam.Color;
		}
		else
		{
			thisPlayer.PlayerOutfit.TeamIndicator = null;
		}
		if (GlowVisible)
		{
			if (Time.time - lastglowVisibleTime > positionGlowVisibleDuration)
			{
				GlowVisible = false;
				return;
			}
			positionGlow.transform.rotation = Quaternion.LookRotation(Vector3.forward);
			positionGlow.transform.position = thisPlayer.Head.transform.position + Vector3.up * positionGlowHeightOffset;
		}
	}

	private void ThisPlayer_VisibilityChanged(bool visible)
	{
		if (Menu != null && Menu.Visible)
		{
			Menu.Visible = false;
		}
	}

	private void PlayerParty_PartyInvitesUpdated(bool isAdd)
	{
		if (isAdd)
		{
			StartCoroutine(RunNotifyPartyInvite());
		}
		if (Menu != null)
		{
			if (Menu.Visible)
			{
				Menu.Refresh();
			}
			else if (isAdd)
			{
				Menu.HasUnseenMessages = true;
			}
		}
	}

	private void PlayerParty_PartyUpdateReceived()
	{
		if (Menu != null && Menu.Visible)
		{
			Menu.Refresh();
		}
	}

	private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (base.isLocal && Menu != null && Menu.Visible)
		{
			Menu.Refresh();
		}
	}

	private void OnPhotonPlayerDisconnected(PhotonPlayer otherPlayer)
	{
		if (base.isLocal && Menu != null && Menu.Visible)
		{
			Menu.Refresh();
		}
	}

	private IEnumerator RunNotifyPartyInvite()
	{
		thisPlayer.PlayerAudio.OnPartyInvite();
		MenuNotification.PlayNext("New message!", 2f, "(press Menu button)", followPlayer: true, null, 1f);
		thisPlayer.LeftHand.Vibrate(500);
		thisPlayer.RightHand.Vibrate(500);
		yield return new WaitForSeconds(0.5f);
		thisPlayer.LeftHand.Vibrate(500);
		thisPlayer.RightHand.Vibrate(500);
	}

	public void BroadcastPlayerMenuVisible(bool visible)
	{
		if (base.isLocal && thisPlayer.IsVisible)
		{
			base.photonView.RPC("RpcPlayerMenuVisible", PhotonTargets.Others, visible);
		}
	}

	[PunRPC]
	public void RpcPlayerMenuVisible(bool visible)
	{
		if (Menu != null)
		{
			Menu.Visible = visible && thisPlayer.IsVisible;
		}
	}
}
public class TrackedVelocity : UnityEngine.MonoBehaviour
{
	private const float RECENT_TIME = 0.05f;

	[SerializeField]
	private bool useUnscaledTime = true;

	private float previousUpdateTime;

	private Vector3 previousPosition = Vector3.zero;

	private Quaternion previousRotation = Quaternion.identity;

	private TimestampedRollingBufferVector3 linearVelocityHistory;

	private TimestampedRollingBufferVector3 angularVelocityHistory;

	private float now => (!useUnscaledTime) ? Time.time : Time.unscaledTime;

	public Vector3 LatestVelocity { get; private set; }

	public Vector3 LatestAngularVelocity { get; private set; }

	public Vector3 RecentLinearVelocity => GetAverageLinearVelocity(0.05f);

	public Vector3 RecentAngularVelocity => GetAverageAngularVelocity(0.05f);

	public Vector3 GetAverageLinearVelocity(float timeWindow)
	{
		if (linearVelocityHistory.TryGetAverageValueOverTime(now - timeWindow, now, out var value))
		{
			return value;
		}
		return LatestVelocity;
	}

	public Vector3 GetAverageAngularVelocity(float timeWindow)
	{
		if (angularVelocityHistory.TryGetAverageValueOverTime(now - timeWindow, now, out var value))
		{
			return value;
		}
		return LatestAngularVelocity;
	}

	public void Reset(Vector3 newVelocity, Vector3 newAngularVelocity)
	{
		LatestVelocity = newVelocity;
		LatestAngularVelocity = newAngularVelocity;
		if (linearVelocityHistory == null)
		{
			linearVelocityHistory = new TimestampedRollingBufferVector3();
		}
		if (angularVelocityHistory == null)
		{
			angularVelocityHistory = new TimestampedRollingBufferVector3();
		}
		linearVelocityHistory.Clear();
		angularVelocityHistory.Clear();
		linearVelocityHistory.Add(now, LatestVelocity);
		angularVelocityHistory.Add(now, LatestAngularVelocity);
		previousUpdateTime = now;
		previousPosition = base.transform.position;
		previousRotation = base.transform.rotation;
	}

	private void OnEnable()
	{
		Reset(Vector3.zero, Vector3.zero);
	}

	private void LateUpdate()
	{
		float num = now - previousUpdateTime;
		if (num > 0f)
		{
			LatestVelocity = (base.transform.position - previousPosition) / num;
			LatestAngularVelocity = UnityExtensions.AngularVelocityFromTo(previousRotation, base.transform.rotation) / num;
			linearVelocityHistory.Add(now, LatestVelocity);
			angularVelocityHistory.Add(now, LatestAngularVelocity);
		}
		previousUpdateTime = now;
		previousPosition = base.transform.position;
		previousRotation = base.transform.rotation;
	}
}
[DisallowMultipleComponent]
internal class SteamManager : UnityEngine.MonoBehaviour
{
	public static uint RECROOM_APP_ID = 471710u;

	private static SteamManager s_instance;

	private static bool s_EverInialized;

	private static bool m_shutDown;

	private bool m_bInitialized;

	private SteamAPIWarningMessageHook_t m_SteamAPIWarningMessageHook;

	private static SteamManager Instance
	{
		get
		{
			if (m_shutDown)
			{
				return null;
			}
			return s_instance;
		}
	}

	public static bool Initialized => Instance != null && Instance.m_bInitialized;

	private static void SteamAPIDebugTextHook(int nSeverity, StringBuilder pchDebugText)
	{
		UnityEngine.Debug.LogWarning(pchDebugText);
	}

	private void Awake()
	{
		if (s_instance != null)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		s_instance = this;
		if (s_EverInialized)
		{
			throw new Exception("Tried to Initialize the SteamAPI twice in one session!");
		}
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
		if (!Packsize.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Packsize Test returned false, the wrong version of Steamworks.NET is being run in this platform.", this);
		}
		if (!DllCheck.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] DllCheck Test returned false, One or more of the Steamworks binaries seems to be the wrong version.", this);
		}
		try
		{
			if (SteamAPI.RestartAppIfNecessary(new AppId_t(RECROOM_APP_ID)))
			{
				Application.Quit();
				return;
			}
		}
		catch (DllNotFoundException ex)
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Could not load [lib]steam_api.dll/so/dylib. It's likely not in the correct location. Refer to the README for more details.\n" + ex, this);
			Application.Quit();
			return;
		}
		m_bInitialized = SteamAPI.Init();
		if (!m_bInitialized)
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] SteamAPI_Init() failed. Refer to Valve's documentation or the comment above this line for more information.", this);
		}
		else
		{
			s_EverInialized = true;
		}
	}

	private void OnEnable()
	{
		if (s_instance == null)
		{
			s_instance = this;
		}
		if (m_bInitialized && m_SteamAPIWarningMessageHook == null)
		{
			m_SteamAPIWarningMessageHook = SteamAPIDebugTextHook;
			SteamClient.SetWarningMessageHook(m_SteamAPIWarningMessageHook);
		}
	}

	private void OnDestroy()
	{
		if (!(s_instance != this))
		{
			s_instance = null;
			if (m_bInitialized)
			{
				SteamAPI.Shutdown();
				m_shutDown = true;
			}
		}
	}

	private void Update()
	{
		if (m_bInitialized)
		{
			SteamAPI.RunCallbacks();
		}
	}
}
public class SteamScript : UnityEngine.MonoBehaviour
{
	protected Callback<GameOverlayActivated_t> m_GameOverlayActivated;

	private CallResult<NumberOfCurrentPlayers_t> m_NumberOfCurrentPlayers;

	private void OnEnable()
	{
		if (SteamManager.Initialized)
		{
			m_GameOverlayActivated = Callback<GameOverlayActivated_t>.Create(OnGameOverlayActivated);
			m_NumberOfCurrentPlayers = CallResult<NumberOfCurrentPlayers_t>.Create(OnNumberOfCurrentPlayers);
		}
	}

	private void Start()
	{
		if (SteamManager.Initialized)
		{
			string personaName = SteamFriends.GetPersonaName();
			UnityEngine.Debug.Log(personaName);
			base.gameObject.name = "SteamScript : " + personaName;
		}
	}

	private void Update()
	{
		if (Input.GetKeyDown(KeyCode.Space))
		{
			SteamFriends.ActivateGameOverlay("Friends");
		}
	}

	private void OnGameOverlayActivated(GameOverlayActivated_t pCallback)
	{
		if (pCallback.m_bActive != 0)
		{
			UnityEngine.Debug.Log("Steam Overlay has been activated");
		}
		else
		{
			UnityEngine.Debug.Log("Steam Overlay has been closed");
		}
	}

	private void OnNumberOfCurrentPlayers(NumberOfCurrentPlayers_t pCallback, bool bIOFailure)
	{
		if (pCallback.m_bSuccess != 1 || bIOFailure)
		{
			UnityEngine.Debug.Log("There was an error retrieving the NumberOfCurrentPlayers.");
		}
		else
		{
			UnityEngine.Debug.Log("The number of players playing your game: " + pCallback.m_cPlayers);
		}
	}
}
