		"Echuiben", "Gaelben", "Gliror", "Dregor", "Taureth", "Lhingiel", "Helviel", "Hadis", "Bastadis", "Falastor",
		"Duirronir", "Dinalagossion", "Narchon", "Orthellon", "Mallostor", "Eredhon", "Úhaelion", "Amarthon", "Thadhrion", "Nîdhel",
		"Cugiel", "Nûril", "Pedrien", "Leithriel", "Glîndaer", "Lîron", "Uilchon", "Barthion", "Ristedir"
	};

	public string NameOverride { get; set; }

	private void Awake()
	{
		SingletonMonoBehaviour<DebugManager>.Instance = this;
	}

	public void SetRandomName(RandomName type)
	{
		if (type == RandomName.Default)
		{
			NameOverride = string.Empty;
			NameOverride = Player.GenerateLocalPlayerName();
			ShowDebugMessage("Name: " + NameOverride);
		}
		else
		{
			List<string> otherPlayerNames = new List<string>();
			PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
			foreach (PhotonPlayer photonPlayer in otherPlayers)
			{
				otherPlayerNames.Add(photonPlayer.name);
			}
			List<string> list = null;
			list = type switch
			{
				RandomName.Girl => normalGirlNames, 
				RandomName.Honeypot => honeypotGirlNames, 
				_ => elvenNames, 
			};
			List<string> list2 = ((otherPlayerNames == null || otherPlayerNames.Count <= 0) ? list : (from d in list
				from o in otherPlayerNames
				where !d.Contains(o)
				select d).ToList());
			if (list2.Count == 0)
			{
				ShowDebugMessage("Failed to get random name");
				return;
			}
			NameOverride = list2.Random();
			ShowDebugMessage("Random name: " + NameOverride);
		}
		if (PhotonNetwork.player != null && !PhotonNetwork.offlineMode && PhotonNetwork.inRoom)
		{
			PhotonNetwork.player.name = NameOverride;
		}
	}

	private void ShowDebugMessage(string message)
	{
		MenuNotification.PlayNext(message, 1.5f, null, followPlayer: true, null, 0.5f);
	}
}
public class LeaderboardManager : SingletonMonoBehaviour<LeaderboardManager>
{
	public delegate void LeaderboardFound(SteamLeaderboardWrapper recLeaderboard);

	private CallResult<LeaderboardFindResult_t> LeaderboardFindResult;

	private int findLeaderboardCount;

	private void Awake()
	{
		SingletonMonoBehaviour<LeaderboardManager>.Instance = this;
	}

	private void Start()
	{
		LeaderboardFindResult = CallResult<LeaderboardFindResult_t>.Create(OnLeaderboardFindResult);
		StartCoroutine(RunDownloadAllLeaderboards());
	}

	private SteamLeaderboardWrapper GetDownloadedLeaderboard(PlayerStats.RecroomSteamLeaderboards leaderboardType)
	{
		return GetDownloadedLeaderboard(leaderboardType.ToString());
	}

	private SteamLeaderboardWrapper GetDownloadedLeaderboard(string leaderboardName)
	{
		foreach (SteamLeaderboardWrapper downloadedLeaderboard in SingletonMonoBehaviour<SessionManager>.Instance.DownloadedLeaderboards)
		{
			if (downloadedLeaderboard.Name == leaderboardName)
			{
				return downloadedLeaderboard;
			}
		}
		return null;
	}

	private IEnumerator RunDownloadAllLeaderboards()
	{
		foreach (int type in Enum.GetValues(typeof(PlayerStats.RecroomSteamLeaderboards)))
		{
			if (type != -1)
			{
				yield return RunFindLeaderboard((PlayerStats.RecroomSteamLeaderboards)type, null);
			}
		}
	}

	public void IncrementLeaderboardScore(PlayerStats.RecroomSteamLeaderboards leaderboardType, int amount = 1)
	{
		if (Player.LocalPlayer != null)
		{
			SteamLeaderboardWrapper downloadedLeaderboard = GetDownloadedLeaderboard(leaderboardType);
			if (downloadedLeaderboard != null)
			{
				downloadedLeaderboard.IncrementScore(amount);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Failed to get leaderboard : " + leaderboardType.ToString().Replace("_", " "));
			}
		}
	}

	public IEnumerator RunFindLeaderboard(PlayerStats.RecroomSteamLeaderboards leaderboardType, LeaderboardFound callback)
	{
		if (leaderboardType != PlayerStats.RecroomSteamLeaderboards.None)
		{
			string leaderboardName = leaderboardType.ToString();
			while (findLeaderboardCount > 1)
			{
				yield return null;
			}
			bool requestSent = false;
			float timer = 30f;
			do
			{
				timer -= Time.deltaTime;
				SteamLeaderboardWrapper downloadedItem = GetDownloadedLeaderboard(leaderboardName);
				if (downloadedItem != null)
				{
					callback?.Invoke(downloadedItem);
					yield break;
				}
				if (!requestSent)
				{
					requestSent = true;
					FindLeaderboard(leaderboardName);
				}
				yield return null;
			}
			while (timer >= 0f);
		}
		callback?.Invoke(null);
	}

	private void FindLeaderboard(string leaderboardName)
	{
		SteamLeaderboardWrapper downloadedLeaderboard = GetDownloadedLeaderboard(leaderboardName);
		if (downloadedLeaderboard != null)
		{
			downloadedLeaderboard.DownloadLeaderboardEntriesAsync();
			return;
		}
		findLeaderboardCount++;
		SteamAPICall_t hAPICall = SteamUserStats.FindLeaderboard(leaderboardName);
		LeaderboardFindResult.Set(hAPICall);
	}

	private void OnLeaderboardFindResult(LeaderboardFindResult_t pCallback, bool bIOFailure)
	{
		findLeaderboardCount--;
		if (pCallback.m_bLeaderboardFound != 0)
		{
			SingletonMonoBehaviour<SessionManager>.Instance.DownloadedLeaderboards.Add(new SteamLeaderboardWrapper(pCallback.m_hSteamLeaderboard));
		}
	}
}
