public static class RecroomPrefs
{
	[Serializable]
	private class SteamPreferences
	{
		public Dictionary<string, string> preferences = new Dictionary<string, string>();

		public byte[] ToByteArray()
		{
			BinaryFormatter binaryFormatter = new BinaryFormatter();
			MemoryStream memoryStream = new MemoryStream();
			binaryFormatter.Serialize(memoryStream, this);
			return memoryStream.ToArray();
		}

		public static SteamPreferences ByteArrayToSteamPreferences(byte[] arrBytes)
		{
			MemoryStream memoryStream = new MemoryStream();
			BinaryFormatter binaryFormatter = new BinaryFormatter();
			memoryStream.Write(arrBytes, 0, arrBytes.Length);
			memoryStream.Seek(0L, SeekOrigin.Begin);
			return (SteamPreferences)binaryFormatter.Deserialize(memoryStream);
		}
	}

	private const string fileName = "preferences.txt";

	private static SteamPreferences steamPreferences = null;

	private static CSteamID steamID = CSteamID.Nil;

	public static bool IsInitialized { get; private set; }

	public static void Initialize()
	{
		if (IsInitialized)
		{
			return;
		}
		steamID = SteamUser.GetSteamID();
		if (!SteamManager.Initialized || !steamID.IsValid())
		{
			return;
		}
		if (SteamRemoteStorage.FileExists("preferences.txt"))
		{
			int fileSize = SteamRemoteStorage.GetFileSize("preferences.txt");
			byte[] array = new byte[fileSize];
			SteamRemoteStorage.FileRead("preferences.txt", array, fileSize);
			try
			{
				byte[] arrBytes = StringCipher.Decrypt(array, GetEncryptionKey());
				steamPreferences = SteamPreferences.ByteArrayToSteamPreferences(arrBytes);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
				steamPreferences = null;
			}
		}
		if (steamPreferences == null)
		{
			steamPreferences = new SteamPreferences();
			UnityEngine.Debug.Log("Creating steam preferences preferences.txt");
		}
		IsInitialized = true;
	}

	private static string GetEncryptionKey()
	{
		if (steamID.IsValid())
		{
			return steamID.m_SteamID.ToString();
		}
		return "offlineUser";
	}

	public static void Save()
	{
		if (IsInitialized)
		{
			byte[] plainTextBytes = steamPreferences.ToByteArray();
			byte[] array = StringCipher.Encrypt(plainTextBytes, GetEncryptionKey());
			SteamRemoteStorage.FileWrite("preferences.txt", array, array.Length);
		}
		else
		{
			PlayerPrefs.Save();
		}
	}

	public static void DeleteAll()
	{
		if (IsInitialized)
		{
			steamPreferences.preferences.Clear();
		}
		else
		{
			PlayerPrefs.Save();
		}
	}

	public static void DeleteKey(string key)
	{
		if (IsInitialized)
		{
			if (HasKey(key))
			{
				steamPreferences.preferences.Remove(key);
			}
		}
		else
		{
			PlayerPrefs.Save();
		}
	}

	public static bool HasKey(string key)
	{
		if (IsInitialized)
		{
			return steamPreferences.preferences.ContainsKey(key);
		}
		return PlayerPrefs.HasKey(key);
	}

	public static int GetInt(string key, int defaultValue)
	{
		if (IsInitialized)
		{
			if (HasKey(key))
			{
				string s = steamPreferences.preferences[key];
				if (int.TryParse(s, out var result))
				{
					return result;
				}
			}
			return defaultValue;
		}
		return PlayerPrefs.GetInt(key, defaultValue);
	}

	public static float GetFloat(string key, float defaultValue)
	{
		if (IsInitialized)
		{
			if (HasKey(key))
			{
				string s = steamPreferences.preferences[key];
				if (float.TryParse(s, out var result))
				{
					return result;
				}
			}
			return defaultValue;
		}
		return PlayerPrefs.GetFloat(key, defaultValue);
	}

	public static string GetString(string key, string defaultValue = "")
	{
		if (IsInitialized)
		{
			if (HasKey(key))
			{
				return steamPreferences.preferences[key];
			}
			return defaultValue;
		}
		return PlayerPrefs.GetString(key, defaultValue);
	}

	public static void SetInt(string key, int value)
	{
		if (IsInitialized)
		{
			steamPreferences.preferences[key] = value.ToString();
		}
		else
		{
			PlayerPrefs.SetInt(key, value);
		}
	}

	public static void SetFloat(string key, float value)
	{
		if (IsInitialized)
		{
			steamPreferences.preferences[key] = value.ToString();
		}
		else
		{
			PlayerPrefs.SetFloat(key, value);
		}
	}

	public static void SetString(string key, string value)
	{
		if (IsInitialized)
		{
			steamPreferences.preferences[key] = value;
		}
		else
		{
			PlayerPrefs.SetString(key, value);
		}
	}
}
