				int value2 = (value ? 1 : 0);
				RecroomPrefs.SetInt(SHOW_ROOM_CENTER_PREF, value2);
				RecroomPrefs.Save();
				AnalyticsHelper.UserSettings(SHOW_ROOM_CENTER_PREF, string.Empty, value2);
			}
		}
	}

	public float GetTeleportBufferSize(TeleportBuffer buffer)
	{
		return teleportBufferSizeMap[buffer];
	}

	public void SetUserBlocked(int duration)
	{
		RecroomPrefs.SetString(MODERATOR_BLOCKED_TIME, DateTime.Now.ToString());
		RecroomPrefs.SetInt(MODERATOR_BLOCKED_DURATION, duration);
		RecroomPrefs.Save();
	}

	public int GetUserBlockedDurationSecondsRemaning()
	{
		if (PlayerPrefs.HasKey(MODERATOR_BLOCKED_TIME) && PlayerPrefs.HasKey(MODERATOR_BLOCKED_DURATION))
		{
			int num = PlayerPrefs.GetInt(MODERATOR_BLOCKED_DURATION, 0);
			string s = PlayerPrefs.GetString(MODERATOR_BLOCKED_TIME, string.Empty);
			if (num > 0 && DateTime.TryParse(s, out var result))
			{
				int num2 = Convert.ToInt32(DateTime.Now.Subtract(result).TotalSeconds);
				return num - num2;
			}
		}
		return 0;
	}

	private void Awake()
	{
		SingletonMonoBehaviour<SettingsManager>.Instance = this;
		teleportBufferSizeMap = new Dictionary<TeleportBuffer, float>();
		for (int i = 0; i < teleportBufferSizes.Length; i++)
		{
			if (!teleportBufferSizeMap.ContainsKey(teleportBufferSizes[i].buffer))
			{
				teleportBufferSizeMap.Add(teleportBufferSizes[i].buffer, teleportBufferSizes[i].distance);
			}
			else
			{
				UnityEngine.Debug.LogError("TeleportBufferSize can not contain duplicate values for " + teleportBufferSizes[i].buffer);
			}
		}
		if (teleportBufferSizes.Length != Enum.GetValues(typeof(TeleportBuffer)).Length)
		{
			UnityEngine.Debug.LogError("TeleportBufferSizes does not have correct number of values.");
		}
	}

	private void Start()
	{
		UnityEngine.Debug.Log("Quality setting : " + QualitySetting);
	}
}
public static class StringCipher
{
	private const int Keysize = 256;

	private const int DerivationIterations = 1000;

	public static byte[] Encrypt(byte[] plainTextBytes, string passPhrase)
	{
		byte[] array = Generate256BitsOfRandomEntropy();
		byte[] array2 = Generate256BitsOfRandomEntropy();
		Rfc2898DeriveBytes rfc2898DeriveBytes = new Rfc2898DeriveBytes(passPhrase, array, 1000);
		byte[] bytes = rfc2898DeriveBytes.GetBytes(32);
		using RijndaelManaged rijndaelManaged = new RijndaelManaged();
		rijndaelManaged.BlockSize = 256;
		rijndaelManaged.Mode = CipherMode.CBC;
		rijndaelManaged.Padding = PaddingMode.PKCS7;
		using ICryptoTransform transform = rijndaelManaged.CreateEncryptor(bytes, array2);
		using MemoryStream memoryStream = new MemoryStream();
		using CryptoStream cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Write);
		cryptoStream.Write(plainTextBytes, 0, plainTextBytes.Length);
		cryptoStream.FlushFinalBlock();
		byte[] first = array;
		first = first.Concat(array2).ToArray();
		first = first.Concat(memoryStream.ToArray()).ToArray();
		memoryStream.Close();
		cryptoStream.Close();
		return first;
	}

	public static byte[] Decrypt(byte[] cipherTextBytesWithSaltAndIv, string passPhrase)
	{
		byte[] salt = cipherTextBytesWithSaltAndIv.Take(32).ToArray();
		byte[] rgbIV = cipherTextBytesWithSaltAndIv.Skip(32).Take(32).ToArray();
		byte[] array = cipherTextBytesWithSaltAndIv.Skip(64).Take(cipherTextBytesWithSaltAndIv.Length - 64).ToArray();
		Rfc2898DeriveBytes rfc2898DeriveBytes = new Rfc2898DeriveBytes(passPhrase, salt, 1000);
		byte[] bytes = rfc2898DeriveBytes.GetBytes(32);
		using RijndaelManaged rijndaelManaged = new RijndaelManaged();
		rijndaelManaged.BlockSize = 256;
		rijndaelManaged.Mode = CipherMode.CBC;
		rijndaelManaged.Padding = PaddingMode.PKCS7;
		using ICryptoTransform transform = rijndaelManaged.CreateDecryptor(bytes, rgbIV);
		using MemoryStream memoryStream = new MemoryStream(array);
		using CryptoStream cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Read);
		byte[] array2 = new byte[array.Length];
		cryptoStream.Read(array2, 0, array2.Length);
		memoryStream.Close();
		cryptoStream.Close();
		return array2;
	}

	private static byte[] Generate256BitsOfRandomEntropy()
	{
		byte[] array = new byte[32];
		RNGCryptoServiceProvider rNGCryptoServiceProvider = new RNGCryptoServiceProvider();
		rNGCryptoServiceProvider.GetBytes(array);
		return array;
	}
}
public class WebManager : SingletonMonoBehaviour<WebManager>
{
	public delegate void GetPlayerResponse(PlayerModel p);

	private const string webURL = "http://recroomwebapplication2.azurewebsites.net/";

	private const string playerApi = "api/players/";

	public PlayerModel LocalPlayerModel { get; private set; }

	private void Awake()
	{
		SingletonMonoBehaviour<WebManager>.Instance = this;
	}

	private void Start()
	{
		StartCoroutine(GetOrCreateLocalPlayer());
	}

	private IEnumerator GetOrCreateLocalPlayer()
	{
		CSteamID steamID = SteamUser.GetSteamID();
		if (steamID.IsValid())
		{
			yield return StartCoroutine(GetPlayer(steamID, delegate(PlayerModel p)
			{
				if (p != null && p.IsValid)
				{
					LocalPlayerModel = p;
				}
			}));
			if (LocalPlayerModel == null || !LocalPlayerModel.IsValid)
			{
				yield return CreateLocalPlayer(steamID);
				yield return StartCoroutine(GetPlayer(steamID, delegate(PlayerModel p)
				{
					if (p != null && p.IsValid)
					{
						LocalPlayerModel = p;
					}
				}));
			}
		}
		if (LocalPlayerModel == null || !LocalPlayerModel.IsValid)
		{
			UnityEngine.Debug.LogError("Could not get the recroom web player model for steam id : " + steamID.m_SteamID);
		}
	}

	public IEnumerator GetPlayer(CSteamID steamID, GetPlayerResponse response)
	{
		string request = string.Format("{0}{1}?steamId={2}", "http://recroomwebapplication2.azurewebsites.net/", "api/players/", steamID.m_SteamID);
		WWW w = new WWW(request);
		yield return w;
		response?.Invoke(new PlayerModel(w.text));
	}

	protected IEnumerator CreateLocalPlayer(CSteamID steamID)
	{
		string name = SteamFriends.GetPersonaName();
		UnityEngine.Debug.Log("Creating a new PlayerModel");
		WWWForm form = new WWWForm();
		form.AddField("SteamID", steamID.m_SteamID.ToString());
		form.AddField("Name", name);
		yield return new WWW(string.Format("{0}{1}", "http://recroomwebapplication2.azurewebsites.net/", "api/players/"), form);
	}

	public void UpdateLocalPlayerModel()
	{
		if (LocalPlayerModel != null && LocalPlayerModel.IsValid)
		{
			Thread thread = new Thread(UpdateLocalPlayerModelAsync);
			thread.Start();
		}
		else
		{
			UnityEngine.Debug.LogError("Failed to update local player model, we dont have the data.");
		}
	}

	protected void UpdateLocalPlayerModelAsync()
	{
		string requestUriString = string.Format("{0}{1}{2}", "http://recroomwebapplication2.azurewebsites.net/", "api/players/", LocalPlayerModel.Id);
		HttpWebRequest httpWebRequest = (HttpWebRequest)WebRequest.Create(requestUriString);
		httpWebRequest.ContentType = "text/json";
		httpWebRequest.Method = "PUT";
		using (StreamWriter streamWriter = new StreamWriter(httpWebRequest.GetRequestStream()))
		{
			streamWriter.Write(LocalPlayerModel.ToJSON());
		}
		HttpWebResponse httpWebResponse = (HttpWebResponse)httpWebRequest.GetResponse();
		using (new StreamReader(httpWebResponse.GetResponseStream()))
		{
		}
	}
}
public class PlayerModel
{
	public int Id { get; private set; }

	public string Name { get; set; }

	public ulong SteamID { get; set; }

	public string Email { get; set; }

	public string Gender { get; set; }

	public int XP { get; set; }

	public int Level { get; set; }

	public int Reputation { get; set; }

	public bool IsValid { get; private set; }

	private PlayerModel()
	{
	}

	public PlayerModel(string jsonString)
	{
		try
		{
			if (Json.Deserialize(jsonString) is Dictionary<string, object> dictionary && dictionary.ContainsKey("Id"))
			{
				IsValid = true;
				Id = GetKey("Id", dictionary, 0);
				Name = GetKey<string>("Name", dictionary);
				SteamID = GetKey("SteamID", dictionary, 0uL);
				Gender = GetKey<string>("Gender", dictionary);
				XP = GetKey("XP", dictionary, 0);
				Level = GetKey("Level", dictionary, 0);
				Reputation = GetKey("Reputation", dictionary, 0);
			}
			else
			{
				IsValid = false;
			}
		}
		catch
		{
			IsValid = false;
		}
	}

	public string ToJSON()
	{
		Dictionary<string, object> dictionary = new Dictionary<string, object>();
		dictionary.Add("Id", Id);
		dictionary.Add("Name", Name);
		dictionary.Add("SteamID", SteamID);
		dictionary.Add("Email", Email);
		dictionary.Add("Gender", Gender);
		dictionary.Add("XP", XP);
		dictionary.Add("Level", Level);
		dictionary.Add("Reputation", Reputation);
		return Json.Serialize(dictionary);
	}

	private T GetKey<T>(string key, Dictionary<string, object> dict, [Optional] T defaultValue)
	{
		if (dict.ContainsKey(key))
		{
			try
			{
				return (T)Convert.ChangeType(dict[key], typeof(T));
			}
			catch
			{
			}
		}
		return defaultValue;
	}

	public override string ToString()
	{
		return $"Id:{Id},Name:{Name},XP:{XP},Rep:{Reputation}";
	}
}
public class TestManager : SingletonMonoBehaviour<TestManager>
{
	public enum TestMode
	{
		MoveBetweenActivities,
		WaintInActivity
	}

	public TestMode Mode;

	public string activityName = "lockerroom";

	private int defaultCullingMask = -1;

	private bool _mainCameraCulled;

	private bool mainCameraCulled
	{
		get
		{
			return _mainCameraCulled;
		}
		set
		{
			_mainCameraCulled = value;
			Camera component = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.GetComponent<Camera>();
			if (defaultCullingMask < 0)
			{
				defaultCullingMask = component.cullingMask;
			}
			component.cullingMask = ((!_mainCameraCulled) ? defaultCullingMask : 0);
		}
	}

	private void Awake()
	{
		UnityEngine.Object.Destroy(base.gameObject);
	}

	private void Start()
	{
		QualitySettings.SetQualityLevel(0);
		mainCameraCulled = true;
		StartCoroutine(RunTestMode());
	}

	private IEnumerator RunTestMode()
	{
		SingletonMonoBehaviour<OutfitManager>.Instance.RandomizePlayerOutfit();
		if (Mode == TestMode.MoveBetweenActivities)
		{
			while (true)
			{
				if (Player.LocalPlayer == null)
				{
					yield return null;
				}
				else
				{
					RandomlyMovePlayer();
					float timer = UnityEngine.Random.Range(15, 60);
					while (timer > 0f)
					{
						timer -= Time.deltaTime;
						if (UnityEngine.Random.value < 0.01f)
						{
							RandomlyMovePlayer();
						}
						yield return null;
					}
					while (ActivityManager.Instance == null)
					{
						yield return null;
					}
					ActivityManager.Instance.SwitchActivity((!(UnityEngine.Random.value < 0.25f)) ? null : "lockerroom");
				}
			}
		}
		if (Mode != TestMode.WaintInActivity)
		{
			yield break;
		}
		while (Player.LocalPlayer == null)
		{
			yield return null;
		}
		ActivityManager.Instance.SwitchActivity(activityName);
		while (true)
		{
			RandomlyMovePlayer();
			float timer2 = UnityEngine.Random.Range(25, 60);
			while (timer2 > 0f)
			{
				timer2 -= Time.deltaTime;
				if (UnityEngine.Random.value < 0.01f)
				{
					RandomlyMovePlayer();
				}
				yield return null;
			}
		}
	}

	private void RandomlyMovePlayer()
	{
		if (Player.LocalPlayer != null)
		{
			Vector3 position = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position;
			position.y = UnityEngine.Random.Range(1f, 2f);
			SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position = position;
			Vector3 localPosition = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.localPosition;
			localPosition.x = UnityEngine.Random.Range(-4f, 4f);
			localPosition.z = UnityEngine.Random.Range(-4f, 4f);
			SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.localPosition = localPosition;
		}
	}

	private void OnGUI()
	{
		GUILayout.BeginArea(new Rect(300f, 300f, 300f, 300f));
		GUILayout.BeginHorizontal();
		GUILayout.Box("Scene : " + SceneManagerHelper.ActiveSceneName);
		if (GUILayout.Button((!mainCameraCulled) ? "Stop render" : "Start render"))
		{
			mainCameraCulled = !mainCameraCulled;
		}
		GUILayout.EndHorizontal();
		GUILayout.EndArea();
	}
}
