public class BoxCastCollider : CastCollider
{
	private Vector3 colliderSize = Vector3.one;

	private Vector3[] localSpaceNormals;

	private float[] sideExtents;

	public BoxCastCollider(Rigidbody rigidbody, Collider collider, Vector3 colliderCenter)
		: base(rigidbody, collider, colliderCenter)
	{
		colliderSize = Vector3.Scale(collider.transform.lossyScale, (collider as BoxCollider).size);
		localSpaceNormals = new Vector3[6];
		ref Vector3 reference = ref localSpaceNormals[0];
		reference = Vector3.right;
		ref Vector3 reference2 = ref localSpaceNormals[1];
		reference2 = -Vector3.right;
		ref Vector3 reference3 = ref localSpaceNormals[2];
		reference3 = Vector3.up;
		ref Vector3 reference4 = ref localSpaceNormals[3];
		reference4 = -Vector3.up;
		ref Vector3 reference5 = ref localSpaceNormals[4];
		reference5 = Vector3.forward;
		ref Vector3 reference6 = ref localSpaceNormals[5];
		reference6 = -Vector3.forward;
		sideExtents = new float[6];
		sideExtents[0] = colliderSize.x / 2f;
		sideExtents[1] = sideExtents[0];
		sideExtents[2] = colliderSize.y / 2f;
		sideExtents[3] = sideExtents[2];
		sideExtents[4] = colliderSize.z / 2f;
		sideExtents[5] = sideExtents[4];
	}

	protected override RaycastHit[] CastAll(Vector3 origin, Quaternion orientation, Vector3 direction, float distance, int layerMask)
	{
		return Physics.BoxCastAll(origin, colliderSize / 2f, direction, orientation, distance, layerMask, QueryTriggerInteraction.Ignore);
	}

	protected override Vector3 GetColliderNormal(Vector3 origin, Quaternion orientation, Vector3 collisionPoint)
	{
		Vector3 vector = collisionPoint - origin;
		Vector3 lhs = Quaternion.Inverse(orientation) * vector;
		int num = -1;
		float num2 = float.MinValue;
		for (int i = 0; i < localSpaceNormals.Length; i++)
		{
			float num3 = Vector3.Dot(lhs, localSpaceNormals[i]) - sideExtents[i];
			if (num3 > num2)
			{
				num = i;
				num2 = num3;
			}
		}
		return orientation * localSpaceNormals[num];
	}

	protected override void DrawCastGizmo(Vector3 start, Vector3 end, Quaternion orientation)
	{
		Gizmos.color = Color.red;
		Matrix4x4 matrix = Matrix4x4.TRS(start, orientation, colliderSize);
		Gizmos.matrix = matrix;
		Gizmos.DrawWireCube(Vector3.zero, Vector3.one);
		Gizmos.color = Color.blue;
		matrix = Matrix4x4.TRS(end, orientation, colliderSize);
		Gizmos.matrix = matrix;
		Gizmos.DrawWireCube(Vector3.zero, Vector3.one);
		Gizmos.matrix = Matrix4x4.identity;
	}

	protected override void DrawHitGizmo(Vector3 point, Vector3 start, Quaternion orientation)
	{
		base.DrawHitGizmo(point, start, orientation);
		Vector3 colliderNormal = GetColliderNormal(start, orientation, point);
		Gizmos.DrawLine(point, point + colliderNormal * 0.25f);
		Gizmos.color = Color.red;
		Gizmos.DrawLine(start, point);
	}
}
