public class Card : Tool
{
	private bool spawnedByBox = true;

	public static Card CreateNewCard(string prefabName, Vector3 position, Quaternion rotation)
	{
		object[] data = new object[1] { true };
		return PhotonNetwork.Instantiate(prefabName, position, rotation, 0, data).GetComponent<Card>();
	}

	protected override void Awake()
	{
		base.Awake();
		if (base.photonView.instantiationData != null && base.photonView.instantiationData.Length > 0)
		{
			spawnedByBox = (bool)base.photonView.instantiationData[0];
		}
		else
		{
			spawnedByBox = false;
		}
		if (spawnedByBox)
		{
			SetCollisionLayer(Layers.DynamicPhysicsIgnoreDynamicPhysics);
			base.Rigidbody.isKinematic = true;
			if (SingletonMonoBehaviour<ToolCleanupManager>.Instance != null)
			{
				SingletonMonoBehaviour<ToolCleanupManager>.Instance.AddTool(this);
			}
		}
	}

	protected override void Reset(Vector3 position, Quaternion rotation, double networkTimestamp)
	{
		if (spawnedByBox)
		{
			if (SingletonMonoBehaviour<ToolCleanupManager>.Instance != null)
			{
				SingletonMonoBehaviour<ToolCleanupManager>.Instance.RemoveTool(this);
			}
			if (base.hasAuthority)
			{
				base.Owner.ToolController.ReleaseTool(this);
				PhotonNetwork.Destroy(base.gameObject);
			}
		}
		else
		{
			base.Reset(position, rotation, networkTimestamp);
		}
	}
}
public class CardBox : Tool
{
	private const string CURRENT_CARD_ID_KEY = "CURRENT_CARD_ID";

	private const string LAST_CARD_DESPAWN_TIME_KEY = "LAST_CARD_DESPAWN_TIME";

	[SerializeField]
	private string cardPrefabName = "[CharadesCard]";

	[SerializeField]
	private Transform cardSpawnRoot;

	[SerializeField]
	private float cardRespawnDuration = 0.5f;

	private Card card;

	protected override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!base.hasAuthority)
		{
			return;
		}
		Card currentCard = GetCurrentCard();
		if (currentCard == null)
		{
			float lastCardDespawnTime = GetLastCardDespawnTime();
			if (lastCardDespawnTime < 0f || PhotonNetwork.time - (double)lastCardDespawnTime > (double)cardRespawnDuration)
			{
				card = Card.CreateNewCard(cardPrefabName, cardSpawnRoot.position, cardSpawnRoot.rotation);
				SetCurrentCard(card);
			}
		}
		else if ((currentCard.transform.position - cardSpawnRoot.position).magnitude >= Mathf.Epsilon)
		{
			SetCurrentCard(null);
			SetLastCardDespawnTime((float)PhotonNetwork.time);
		}
	}

	private void SetCurrentCard(Card card)
	{
		int data = -1;
		if (card != null)
		{
			data = card.photonView.viewID;
		}
		base.ActivityData.SetData("CURRENT_CARD_ID", data);
	}

	private Card GetCurrentCard()
	{
		int data = base.ActivityData.GetData("CURRENT_CARD_ID", -1);
		if (data < 0)
		{
			return null;
		}
		PhotonView photonView = PhotonView.Find(data);
		if (photonView == null)
		{
			return null;
		}
		return photonView.GetComponent<Card>();
	}

	private void SetLastCardDespawnTime(float time)
	{
		base.ActivityData.SetData("LAST_CARD_DESPAWN_TIME", time);
	}

	private float GetLastCardDespawnTime()
	{
		return base.ActivityData.GetData("LAST_CARD_DESPAWN_TIME", -1f);
	}
}
public struct CastColliderHit
{
	public Rigidbody Rigidbody;

	public Collider Collider;

	public Vector3 Point;

	public float Distance;

	public Vector3 Normal;

	public Vector3 CastColliderNormal;

	public Collider CastCollider;
}
public abstract class CastCollider
{
	protected Collider collider;

	protected Rigidbody rigidbody;

	private Vector3 positionRigidbodySpace;

	private Quaternion rotationRigidbodySpace;

	private List<CastColliderHit> castColliderHits = new List<CastColliderHit>();

	private List<CastColliderHit> gizmoLastHits = new List<CastColliderHit>();

	private Vector3 gizmoLastInitialPosition = Vector3.zero;

	private Vector3 gizmoLastFinalPosition = Vector3.zero;

	private Quaternion gizmoLastOrientation = Quaternion.identity;

	public CastCollider(Rigidbody rigidbody, Collider collider, Vector3 colliderCenter)
	{
		this.rigidbody = rigidbody;
		this.collider = collider;
		Vector3 position = this.collider.transform.TransformPoint(colliderCenter);
		positionRigidbodySpace = this.rigidbody.transform.InverseTransformPoint(position);
		rotationRigidbodySpace = this.rigidbody.transform.InverseTransformRotation(collider.transform.rotation);
	}

	public CastColliderHit[] Cast(Vector3 initialPosition, Quaternion orientation, Vector3 direction, float distance, int layerMask)
	{
		initialPosition = Matrix4x4.TRS(initialPosition, orientation, rigidbody.transform.lossyScale).MultiplyPoint(positionRigidbodySpace);
		orientation *= rotationRigidbodySpace;
		castColliderHits.Clear();
		if (collider.gameObject.activeSelf && collider.enabled)
		{
			RaycastHit[] array = CastAll(initialPosition, orientation, direction, distance, layerMask);
			RaycastHit[] array2 = array;
			CastColliderHit item = default(CastColliderHit);
			for (int i = 0; i < array2.Length; i++)
			{
				RaycastHit raycastHit = array2[i];
				if (raycastHit.collider.enabled && raycastHit.collider.gameObject.activeSelf && (!(raycastHit.point.magnitude < Mathf.Epsilon) || !(raycastHit.distance < Mathf.Epsilon)))
				{
					item.Rigidbody = raycastHit.rigidbody;
					item.Collider = raycastHit.collider;
					item.Point = raycastHit.point;
					item.Distance = raycastHit.distance;
					item.Normal = raycastHit.normal;
					item.CastColliderNormal = GetColliderNormal(initialPosition, orientation, initialPosition + direction * raycastHit.distance);
					item.CastCollider = collider;
					castColliderHits.Add(item);
				}
			}
			if (castColliderHits.Count > 0)
			{
				gizmoLastHits.Clear();
				foreach (CastColliderHit castColliderHit in castColliderHits)
				{
					gizmoLastHits.Add(castColliderHit);
				}
				gizmoLastInitialPosition = initialPosition;
				gizmoLastFinalPosition = initialPosition + direction * distance;
				gizmoLastOrientation = orientation;
			}
		}
		return castColliderHits.ToArray();
	}

	public void DrawGizmos()
	{
		if (!collider.gameObject.activeSelf || !collider.enabled)
		{
			return;
		}
		foreach (CastColliderHit gizmoLastHit in gizmoLastHits)
		{
			DrawHitGizmo(gizmoLastHit.Point, gizmoLastInitialPosition, gizmoLastOrientation);
		}
		if (gizmoLastOrientation != Quaternion.identity)
		{
			DrawCastGizmo(gizmoLastInitialPosition, gizmoLastFinalPosition, gizmoLastOrientation);
		}
	}

	protected abstract RaycastHit[] CastAll(Vector3 origin, Quaternion orientation, Vector3 direction, float distance, int layerMask);

	protected abstract Vector3 GetColliderNormal(Vector3 origin, Quaternion orientation, Vector3 collisionPoint);

	protected abstract void DrawCastGizmo(Vector3 start, Vector3 end, Quaternion orientation);

	protected virtual void DrawHitGizmo(Vector3 point, Vector3 start, Quaternion orientation)
	{
		Gizmos.color = Color.green;
		Gizmos.DrawSphere(point, 0.02f);
	}
}
[DisallowMultipleComponent]
[RequireComponent(typeof(Rigidbody))]
public class CastCollisionRigidbody : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float castDuration = 0.05f;

	private Rigidbody rigidbody;

	private List<CastCollider> castColliders = new List<CastCollider>();

	private List<CastColliderHit> latestHits = new List<CastColliderHit>();

	public Rigidbody Rigidbody => rigidbody;

	private void Awake()
	{
		rigidbody = GetComponent<Rigidbody>();
		BoxCollider[] componentsInChildren = GetComponentsInChildren<BoxCollider>();
		foreach (BoxCollider boxCollider in componentsInChildren)
		{
			castColliders.Add(new BoxCastCollider(rigidbody, boxCollider, boxCollider.center));
		}
		SphereCollider[] componentsInChildren2 = GetComponentsInChildren<SphereCollider>();
		foreach (SphereCollider sphereCollider in componentsInChildren2)
		{
			castColliders.Add(new SphereCastCollider(rigidbody, sphereCollider, sphereCollider.center));
		}
	}

	public bool Cast(Vector3 initialPosition, Quaternion initialRotation, Vector3 direction, float distance, int layerMask, out CastColliderHit closestHit)
	{
		RunCast(initialPosition, initialRotation, direction, distance, layerMask);
		bool flag = false;
		int index = -1;
		float num = float.MaxValue;
		for (int i = 0; i < latestHits.Count; i++)
		{
			if (latestHits[i].Distance < num)
			{
				flag = true;
				index = i;
				num = latestHits[i].Distance;
			}
		}
		closestHit = ((!flag) ? default(CastColliderHit) : latestHits[index]);
		return flag;
	}

	public void CastToCollide(Vector3 initialPosition, Vector3 targetPosition, Quaternion targetRotation, Vector3 velocity, int layerMask)
	{
		if (!rigidbody.gameObject.activeSelf)
		{
			return;
		}
		Vector3 normalized = velocity.normalized;
		float num = 2f * castDuration * velocity.magnitude;
		initialPosition -= normalized * num / 2f;
		RunCast(initialPosition, targetRotation, normalized, num, layerMask);
		foreach (CastColliderHit latestHit in latestHits)
		{
			latestHit.Rigidbody.AddForceAtPosition(Vector3.Project(velocity, latestHit.CastColliderNormal), latestHit.Point, ForceMode.VelocityChange);
		}
	}

	private void RunCast(Vector3 initialPosition, Quaternion initialRotation, Vector3 direction, float distance, int layerMask)
	{
		latestHits.Clear();
		foreach (CastCollider castCollider in castColliders)
		{
			CastColliderHit[] array = castCollider.Cast(initialPosition, initialRotation, direction, distance, layerMask);
			CastColliderHit[] array2 = array;
			CastColliderHit hit;
			for (int i = 0; i < array2.Length; i++)
			{
				hit = array2[i];
				int num = -1;
				num = ((!(hit.Rigidbody != null)) ? latestHits.FindIndex((CastColliderHit x) => x.Collider == hit.Collider) : latestHits.FindIndex((CastColliderHit x) => x.Rigidbody == hit.Rigidbody));
				if (num < 0)
				{
					latestHits.Add(hit);
				}
				else if (latestHits[num].Distance < hit.Distance)
				{
					latestHits[num] = hit;
				}
			}
		}
	}

	private void OnDrawGizmos()
	{
		foreach (CastCollider castCollider in castColliders)
		{
			castCollider.DrawGizmos();
		}
	}
}
public class FlagTool : Tool
{
	private const string IS_IN_GOAL_KEY = "IS_IN_GOAL";

	private const string GOAL_CENTER_KEY = "GOAL_CENTER";

	private const string GOAL_RADIUS_KEY = "GOAL_RADIUS";

	private const string IS_AT_HOME_KEY = "IS_AT_HOME";

	private const string HOME_CENTER_KEY = "HOME_CENTER";

	private const string HOME_RADIUS_KEY = "HOME_RADIUS";

	[SerializeField]
	private Renderer beamRenderer;

	private FlagToolRenderer flagToolRenderer;

	public Color Color
	{
		set
		{
			flagToolRenderer.AccentColor = value;
			float a = beamRenderer.material.color.a;
			value.a = a;
			beamRenderer.material.color = value;
		}
	}

	public event Action<FlagTool> AtHomeEvent;

	public event Action<FlagTool> InGoalEvent;

	protected override void Awake()
	{
		base.Awake();
		flagToolRenderer = GetComponent<FlagToolRenderer>();
	}

	protected override void Start()
	{
		base.Start();
		base.Rigidbody.isKinematic = true;
	}

	protected override void OnDisable()
	{
		if (base.hasAuthority)
		{
			SetIsInGoal(inGoal: false);
		}
		base.OnDisable();
	}

	private void Update()
	{
		beamRenderer.enabled = true;
		Vector3 position;
		if (base.IsHeld && base.Owner != null)
		{
			if (base.Owner == Player.LocalPlayer)
			{
				beamRenderer.enabled = false;
			}
			position = base.Owner.CurrentFloorPosition;
		}
		else if (!TryGetBeamPosition(out position))
		{
			position = base.transform.position;
		}
		beamRenderer.transform.position = position;
		beamRenderer.transform.rotation = Quaternion.LookRotation(Vector3.up);
		if (base.hasAuthority)
		{
			GetGoal(out var center, out var radius);
			bool flag = Vector3.ProjectOnPlane(base.transform.position - center, Vector3.up).sqrMagnitude <= radius * radius;
			bool flag2 = IsInGoal();
			if (flag != flag2)
			{
				SetIsInGoal(flag);
			}
			GetHome(out center, out radius);
			bool flag3 = Vector3.ProjectOnPlane(base.transform.position - center, Vector3.up).sqrMagnitude <= radius * radius;
			bool flag4 = IsAtHome();
			if (flag3 != flag4)
			{
				SetIsAtHome(flag3);
			}
		}
	}

	protected override void Reset(Vector3 position, Quaternion rotation, double networkTimestamp)
	{
		base.Reset(position, rotation, networkTimestamp);
		base.Rigidbody.isKinematic = true;
	}

	private bool TryGetBeamPosition(out Vector3 position)
	{
		if (Physics.Raycast(base.transform.position + Vector3.up * 0.1f, -Vector3.up, out var hitInfo, float.MaxValue, 2048, QueryTriggerInteraction.Ignore))
		{
			position = hitInfo.point;
			return true;
		}
		position = Vector3.zero;
		return false;
	}

	public void MasterSetGoal(Vector3 center, float radius)
	{
		if (PhotonNetwork.isMasterClient)
		{
			base.ActivityData.SetData("GOAL_CENTER", center);
			base.ActivityData.SetData("GOAL_RADIUS", radius);
		}
	}

	private void GetGoal(out Vector3 center, out float radius)
	{
		center = base.ActivityData.GetData("GOAL_CENTER", Vector3.zero);
		radius = base.ActivityData.GetData("GOAL_RADIUS", 0f);
	}

	public bool IsInGoal()
	{
		return base.ActivityData.GetData("IS_IN_GOAL", defaultValue: false);
	}

	private void SetIsInGoal(bool inGoal)
	{
		base.ActivityData.SetData("IS_IN_GOAL", inGoal);
		if (inGoal)
		{
			base.photonView.RPC("RpcFireFlagEvent", PhotonTargets.All, false);
		}
	}

	public void MasterSetHome(Vector3 center, float radius)
	{
		if (PhotonNetwork.isMasterClient)
		{
			base.ActivityData.SetData("HOME_CENTER", center);
			base.ActivityData.SetData("HOME_RADIUS", radius);
		}
	}

	private void GetHome(out Vector3 center, out float radius)
	{
		center = base.ActivityData.GetData("HOME_CENTER", Vector3.zero);
		radius = base.ActivityData.GetData("HOME_RADIUS", 0f);
	}

	public bool IsAtHome()
	{
		return base.ActivityData.GetData("IS_AT_HOME", defaultValue: false);
	}

	private void SetIsAtHome(bool atHome)
	{
		base.ActivityData.SetData("IS_AT_HOME", atHome);
		if (atHome)
		{
			base.photonView.RPC("RpcFireFlagEvent", PhotonTargets.All, true);
		}
	}

	[PunRPC]
	public void RpcFireFlagEvent(bool atHome)
	{
		if (atHome && this.AtHomeEvent != null)
		{
			this.AtHomeEvent(this);
		}
		else if (this.InGoalEvent != null)
		{
			this.InGoalEvent(this);
		}
	}
}
public class Frisbee : Tool
{
	[Header("Frisbee Properties")]
	[Tooltip("Any faster than this will not lift the frisbee any more")]
	public static readonly float MaxAngularVelocity = 20f;

	[Tooltip("Any faster than this will not lift the frisbee any more")]
	public static readonly float MaxVelocity = 20f;

	[Tooltip("We will help you with the throw speed based on the percent of your current throw to the MaxVelocity. Higher speeds should get less assist.")]
	public AnimationCurve ThrowAssistCurve;

	[Tooltip("We will help you with the throw speed based on the percent of your current throw to the MaxVelocity. Higher speeds should get less assist.")]
	public float ThrowAssistMultiplier = 1f;

	[Tooltip("How much airlift can be applied to lift the object. 1 means as much as the gravity itself.")]
	[Range(0f, 1f)]
	[SerializeField]
	[Header("Aero Dynamics")]
	private float airLiftModifier = 0.85f;

	[Tooltip("How much angular torque to apply overall to stabilize this tool.")]
	[Range(0f, 1f)]
	[SerializeField]
	[Header("Angular Stability (Anti-Wobble)")]
	private float angularStabilityModifier = 0.9f;

	[SerializeField]
	[Tooltip("How stable the rotation will get overtime.")]
	[Range(0f, 1f)]
	private float angularStabilityPercent = 0.3f;

	[SerializeField]
	[Tooltip("How fast the frisbee is going to get to the percent stability.")]
	private float angularStabilitySpeed = 2f;

	public float GlideMultiplier = 1f;

	[Header("Beam")]
	public bool BeamEnabled;

	[SerializeField]
	private Renderer beamRenderer;

	[SerializeField]
	private Vector3 beamRotationOffset = new Vector3(90f, 0f, 0f);

	private bool wasShowBeam;

	private float showBeamTime;

	protected override void Start()
	{
		base.Start();
		if (beamRenderer != null)
		{
			beamRenderer.material.SetColor("_Color", base.ToolRenderer.Renderers[0].material.color);
			beamRenderer.gameObject.SetActive(value: false);
		}
	}

	protected override void FixedUpdate()
	{
		base.FixedUpdate();
		bool flag = false;
		if (!base.IsHeld)
		{
			float magnitude = base.Rigidbody.angularVelocity.magnitude;
			float a = Mathf.Clamp01(magnitude / MaxAngularVelocity);
			float magnitude2 = base.Rigidbody.velocity.magnitude;
			float b = Mathf.Clamp01(magnitude2 / MaxVelocity);
			float num = Vector3.Dot(Vector3.up, base.transform.up);
			float num2 = num * Mathf.Max(a, b) * base.Rigidbody.mass;
			if (num2 > 0.01f)
			{
				base.Rigidbody.AddForce(-Physics.gravity * num2 * airLiftModifier, ForceMode.Force);
				float num3 = num2 * angularStabilityModifier;
				Vector3 lhs = Quaternion.AngleAxis(num3 * magnitude * 57.29578f * angularStabilityPercent / angularStabilitySpeed, base.Rigidbody.angularVelocity) * base.transform.up;
				Vector3 vector = Vector3.Cross(lhs, Vector3.up);
				base.Rigidbody.AddTorque(vector * angularStabilitySpeed * angularStabilitySpeed * num3);
			}
			flag = magnitude < 0.1f && magnitude2 < 0.01f;
		}
		if (!(beamRenderer != null))
		{
			return;
		}
		if (BeamEnabled && Player.LocalPlayer != null && base.PlayerInteractionRestriction.PlayerInteractionAllowed(Player.LocalPlayer))
		{
			if (!wasShowBeam && flag)
			{
				showBeamTime = Time.time;
			}
			if (flag && Time.time - showBeamTime > 0.5f)
			{
				beamRenderer.gameObject.SetActive(value: true);
				beamRenderer.transform.position = base.transform.position;
				beamRenderer.transform.rotation = Quaternion.LookRotation(Vector3.forward) * Quaternion.Euler(beamRotationOffset);
			}
			else
			{
				beamRenderer.gameObject.SetActive(value: false);
			}
			wasShowBeam = flag;
		}
		else
		{
			beamRenderer.gameObject.SetActive(value: false);
			wasShowBeam = false;
		}
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		float num = Mathf.Clamp01(linearVelocity.magnitude / MaxVelocity);
		float num2 = 1f + ThrowAssistCurve.Evaluate(1f - num) * ThrowAssistMultiplier;
		base.Release(player, linearVelocity * num2, angularVelocity * num2);
	}
}
public class HandheldCameraTool : Tool
{
	[Header("Camera")]
	[SerializeField]
	private Transform lensTransform;

	[SerializeField]
	private Vector2 lowResolution = new Vector2(320f, 180f);

	[SerializeField]
	private Vector2 highResolution = new Vector2(640f, 360f);

	[SerializeField]
	private float fieldOfView = 60f;

	[SerializeField]
	private float nearClip = 0.05f;

	[SerializeField]
	private float farClip = 1000f;

	[SerializeField]
	private bool hideOwner = true;

	[Header("Screens")]
	[SerializeField]
	private Renderer[] screenRenderers;

	[SerializeField]
	private Renderer externalScreenRenderer;

	[SerializeField]
	private Material screenRenderMaterial;

	[SerializeField]
	private Material defaultScreenMaterial;

	[SerializeField]
	private bool blitToGameView;

	[Header("Smoothing")]
	[SerializeField]
	private float positionSmoothingTime = 0.25f;

	[SerializeField]
	[Header("Capture Feedback")]
	private GameObject recordingFeedback;

	[SerializeField]
	private Slider recordingProgressFeedback;

	[SerializeField]
	private GameObject exportingFeedback;

	[SerializeField]
	private Text savedFeedback;

	private RenderTexture renderTexture;

	private Camera camera;

	private Camera fullscreenBlitCamera;

	private Vector3 velocity = Vector3.zero;

	private Vector3 rotationVelocity = Vector3.zero;

	private bool? usingHighResolution;

	private float aspect = 1f;

	private VideoCapture videoCapture;

	private Material screenRenderMaterialCopy;

	private Animator animator;

	private static readonly int triggerId = Animator.StringToHash("Trigger");

	private static readonly int screenAnimationId = Animator.StringToHash("ScreenOpen");

	private float triggerAmount;

	private bool screenOpen;

	protected override void Awake()
	{
		base.Awake();
		aspect = lowResolution.x / lowResolution.y;
		videoCapture = GetComponent<VideoCapture>();
		if (videoCapture != null)
		{
			videoCapture.AspectRatio = aspect;
			videoCapture.HorizontalResolution = (int)highResolution.x;
			videoCapture.VerticalResolution = (int)highResolution.y;
			videoCapture.CaptureStartedEvent += OnCaptureStarted;
			videoCapture.ExportStartedEvent += OnExportStarted;
			videoCapture.ExportFinishedEvent += OnExportFinished;
		}
		exportingFeedback.SetActive(value: false);
		recordingFeedback.SetActive(value: false);
		recordingProgressFeedback.gameObject.SetActive(value: false);
		savedFeedback.gameObject.SetActive(value: false);
		screenRenderMaterialCopy = new Material(screenRenderMaterial);
		animator = GetComponentInChildren<Animator>();
	}

	protected override void Start()
	{
		base.Start();
		GameObject gameObject = UnityEngine.Object.Instantiate(Camera.main.gameObject);
		gameObject.name = base.gameObject.name + "_Camera";
		gameObject.tag = "Untagged";
		UnityEngine.Object.Destroy(gameObject.GetComponent<SteamVR_Camera>());
		UnityEngine.Object.Destroy(gameObject.GetComponent<FadeImageEffect>());
		UnityEngine.Object.Destroy(gameObject.GetComponent<GUILayer>());
		UnityEngine.Object.Destroy(gameObject.GetComponent<AudioListener>());
		UnityEngine.Object.Destroy(gameObject.GetComponent<DebugCameraControl>());
		for (int num = gameObject.transform.childCount - 1; num >= 0; num--)
		{
			UnityEngine.Object.Destroy(gameObject.transform.GetChild(num).gameObject);
		}
		camera = gameObject.GetComponent<Camera>();
		camera.cullingMask = -65537;
		camera.stereoTargetEye = StereoTargetEyeMask.None;
		camera.aspect = aspect;
		camera.fieldOfView = fieldOfView;
		camera.nearClipPlane = nearClip;
		camera.farClipPlane = farClip;
		fullscreenBlitCamera = base.gameObject.AddComponent<Camera>();
		fullscreenBlitCamera.clearFlags = CameraClearFlags.Color;
		fullscreenBlitCamera.aspect = aspect;
		fullscreenBlitCamera.cullingMask = 0;
		fullscreenBlitCamera.targetTexture = null;
		fullscreenBlitCamera.stereoTargetEye = StereoTargetEyeMask.None;
		fullscreenBlitCamera.depth = 9999f;
		fullscreenBlitCamera.enabled = false;
		SwitchTextureResolution(useHighResolution: false);
		if (externalScreenRenderer != null)
		{
			externalScreenRenderer.material = screenRenderMaterialCopy;
		}
		OpenScreen(open: false);
	}

	private void SwitchTextureResolution(bool useHighResolution)
	{
		if (!usingHighResolution.HasValue || usingHighResolution.Value != useHighResolution)
		{
			usingHighResolution = useHighResolution;
			Vector2 vector = ((!useHighResolution) ? lowResolution : highResolution);
			renderTexture = new RenderTexture((int)vector.x, (int)vector.y, 24);
			renderTexture.antiAliasing = ((QualitySettings.antiAliasing <= 0) ? 1 : QualitySettings.antiAliasing);
			if (camera != null)
			{
				camera.targetTexture = renderTexture;
			}
			screenRenderMaterialCopy.mainTexture = renderTexture;
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
		if (hideOwner && player == Player.LocalPlayer)
		{
			camera.cullingMask &= -257;
		}
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
		if (hideOwner && player == Player.LocalPlayer)
		{
			camera.cullingMask |= 256;
		}
		if (base.hasAuthority)
		{
			FinishCapturing();
			OpenScreen(open: false);
		}
	}

	public override void OnInputDown()
	{
		if (base.hasAuthority)
		{
			StartCapturing();
		}
	}

	public override void OnInputUp()
	{
		if (base.hasAuthority)
		{
			FinishCapturing();
		}
	}

	protected override void OnLock()
	{
		OpenScreen(open: true);
	}

	protected override void OnUnlock()
	{
		OpenScreen(open: false);
		if (base.hasAuthority)
		{
			FinishCapturing();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (videoCapture != null)
		{
			videoCapture.CaptureStartedEvent -= OnCaptureStarted;
			videoCapture.ExportStartedEvent -= OnExportStarted;
			videoCapture.ExportFinishedEvent -= OnExportFinished;
		}
		if (renderTexture != null)
		{
			UnityEngine.Object.Destroy(renderTexture);
		}
		if (camera != null)
		{
			UnityEngine.Object.Destroy(camera.gameObject);
		}
	}

	protected override void OnPhotonPlayerDisconnected(PhotonPlayer oldPlayer)
	{
		if (base.hasAuthority && (base.Owner == null || base.Owner.PhotonPlayer == oldPlayer))
		{
			FinishCapturing();
		}
		base.OnPhotonPlayerDisconnected(oldPlayer);
	}

	private void Update()
	{
		fullscreenBlitCamera.enabled = blitToGameView;
		if (SingletonMonoBehaviour<PlayerInputManager>.Instance != null)
		{
			SingletonMonoBehaviour<PlayerInputManager>.Instance.GUIEnabled = !blitToGameView;
		}
		camera.transform.position = Vector3.SmoothDamp(camera.transform.position, lensTransform.position, ref velocity, positionSmoothingTime);
		camera.transform.rotation = UnityExtensions.SmoothDamp(camera.transform.rotation, lensTransform.rotation, ref rotationVelocity, positionSmoothingTime);
		if (base.hasAuthority)
		{
			SetTrigger(InputAmount);
			UpdateCapture();
		}
	}

	private void OnRenderImage(RenderTexture src, RenderTexture dest)
	{
		Graphics.Blit(renderTexture, dest);
	}

	private void StartCapturing()
	{
		SwitchTextureResolution(useHighResolution: true);
		if (videoCapture != null && !videoCapture.IsCapturing)
		{
			videoCapture.StartCapture();
		}
	}

	private void FinishCapturing()
	{
		if (videoCapture != null && videoCapture.IsCapturing)
		{
			videoCapture.FinishCapture();
		}
		SwitchTextureResolution(useHighResolution: false);
	}

	private void UpdateCapture()
	{
		if (!(videoCapture != null) || !videoCapture.IsCapturing)
		{
			return;
		}
		if (!base.IsHeld)
		{
			FinishCapturing();
			OpenScreen(open: false);
			return;
		}
		float num = videoCapture.UpdateFrame(renderTexture);
		recordingProgressFeedback.value = num;
		if (num >= 1f)
		{
			FinishCapturing();
		}
	}

	private void OnCaptureStarted()
	{
		recordingFeedback.gameObject.SetActive(value: true);
		recordingProgressFeedback.gameObject.SetActive(value: true);
	}

	private void OnExportStarted()
	{
		recordingFeedback.gameObject.SetActive(value: false);
		recordingProgressFeedback.gameObject.SetActive(value: false);
		exportingFeedback.SetActive(value: true);
	}

	private void OnExportFinished(string filename)
	{
		exportingFeedback.SetActive(value: false);
		if (Player.LocalPlayer != null)
		{
			Player.LocalPlayer.PlayerStats.IncrementIntStat(PlayerStats.RecroomSteamStat.record_video, 1);
		}
		StartCoroutine(DisplayFileSaveFeedbackCoroutine(filename));
	}

	private IEnumerator DisplayFileSaveFeedbackCoroutine(string filename)
	{
		filename = Path.GetFileName(filename);
		savedFeedback.gameObject.SetActive(value: true);
		savedFeedback.text = filename + " Saved!";
		yield return new WaitForSeconds(2f);
		savedFeedback.gameObject.SetActive(value: false);
	}

	private void OpenScreen(bool open)
	{
		if (animator != null && animator.isActiveAndEnabled)
		{
			animator.SetBool(screenAnimationId, open);
		}
		if (externalScreenRenderer == null)
		{
			camera.enabled = open;
		}
		if (screenOpen != open)
		{
			screenOpen = open;
			Renderer[] array = screenRenderers;
			foreach (Renderer renderer in array)
			{
				renderer.material = ((!open) ? defaultScreenMaterial : screenRenderMaterialCopy);
			}
		}
	}

	private void SetTrigger(float trigger)
	{
		triggerAmount = trigger;
		if (animator != null && animator.isActiveAndEnabled)
		{
			animator.SetFloat(triggerId, triggerAmount);
		}
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading)
		{
			float trigger = (float)stream.ReceiveNext();
			SetTrigger(trigger);
			bool open = (bool)stream.ReceiveNext();
			OpenScreen(open);
		}
		else
		{
			stream.SendNext(triggerAmount);
			stream.SendNext(screenOpen);
		}
	}
}
public class HorseShoe : Tool
{
	public OccupiableSpawnPoint SpawnPoint { get; private set; }

	public void Spawn(OccupiableSpawnPoint spawnPoint)
	{
		if (base.hasAuthority)
		{
			SpawnPoint = spawnPoint;
			base.transform.position = SpawnPoint.transform.position;
			base.transform.rotation = SpawnPoint.transform.rotation;
		}
	}

	public void Kill()
