	}
}
public class MeshExtruderTool : Tool
{
	private const string EXTRUSION_ID_KEY = "EXTRUSION_ID";

	private const float TRIGGER_RELEASE_SPEED = 5f;

	[SerializeField]
	[Header("Extrusion")]
	private Transform extrusionPoint;

	[Tooltip("Amount of time between updates to the mesh")]
	[SerializeField]
	private float addControlPointInterval = 0.25f;

	private float lastControlPointAddTime;

	private Animator animator;

	private static readonly int triggerId = Animator.StringToHash("Trigger");

	private float triggerAmount;

	public Transform ExtrusionPoint => extrusionPoint;

	protected override void Awake()
	{
		base.Awake();
		animator = GetComponentInChildren<Animator>();
	}

	private void Update()
	{
		if (base.hasAuthority)
		{
			triggerAmount = InputAmount;
			animator.SetFloat(triggerId, triggerAmount);
			UpdateExtrusion();
		}
	}

	public override void OnInputDown()
	{
		base.OnInputDown();
		if (base.hasAuthority)
		{
			StartExtrudingMesh();
		}
	}

	public override void OnInputUp()
	{
		base.OnInputUp();
		if (base.hasAuthority)
		{
			StopExtrudingMesh();
		}
	}

	protected override void OnUnlock()
	{
		base.OnUnlock();
		if (base.hasAuthority)
		{
			FinishExtrusion();
		}
	}

	public override void OnTeleport()
	{
		base.OnTeleport();
		if (base.hasAuthority)
		{
			StopExtrudingMesh();
		}
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		if (base.hasAuthority)
		{
			FinishExtrusion();
		}
		base.Release(player, linearVelocity, angularVelocity);
	}

	protected override void OnPhotonPlayerDisconnected(PhotonPlayer oldPlayer)
	{
		if (base.hasAuthority && base.Owner.PhotonPlayer == oldPlayer)
		{
			FinishExtrusion();
		}
		base.OnPhotonPlayerDisconnected(oldPlayer);
	}

	private void UpdateExtrusion()
	{
		Extrusion extrusion = GetExtrusion();
		if (extrusion != null && extrusion.IsExtrudingMesh)
		{
			if (!base.IsHeld)
			{
				StopExtrudingMesh();
			}
			else if (Time.time - lastControlPointAddTime > addControlPointInterval)
			{
				lastControlPointAddTime = Time.time;
				extrusion.MasterAddControlPoint();
			}
		}
	}

	private void StartExtrudingMesh()
	{
		Extrusion extrusion = GetExtrusion();
		if (extrusion == null)
		{
			extrusion = Extrusion.CreateNewExtrusion(this);
			extrusion.ExtrusionFinishedEvent += OnExtrusionFinished;
			SetExtrusion(extrusion);
		}
		if (!extrusion.IsExtrudingMesh)
		{
			lastControlPointAddTime = Time.time;
			extrusion.MasterStartExtrudingNewMesh();
		}
	}

	private void StopExtrudingMesh()
	{
		Extrusion extrusion = GetExtrusion();
		if (extrusion != null && extrusion.IsExtrudingMesh)
		{
			extrusion.MasterFinishExtrudingCurrentMesh();
		}
	}

	private void FinishExtrusion()
	{
		Extrusion extrusion = GetExtrusion();
		if (extrusion != null)
		{
			if (extrusion.IsExtrudingMesh)
			{
				extrusion.MasterFinishExtrudingCurrentMesh();
			}
			extrusion.MasterFinishExtrusion();
		}
	}

	private void OnExtrusionFinished()
	{
		Extrusion extrusion = GetExtrusion();
		if (extrusion != null)
		{
			extrusion.ExtrusionFinishedEvent -= OnExtrusionFinished;
			SetExtrusion(null);
		}
	}

	private Extrusion GetExtrusion()
	{
		int data = base.ActivityData.GetData("EXTRUSION_ID", -1);
		if (data < 0)
		{
			return null;
		}
		PhotonView photonView = PhotonView.Find(data);
		if (photonView == null)
		{
			return null;
		}
		return photonView.GetComponent<Extrusion>();
	}

	private void SetExtrusion(Extrusion extrusion)
	{
		if (extrusion == null)
		{
			base.ActivityData.SetData("EXTRUSION_ID", -1);
		}
		else
		{
			base.ActivityData.SetData("EXTRUSION_ID", extrusion.photonView.viewID);
		}
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading)
		{
			triggerAmount = (float)stream.ReceiveNext();
			if (animator.isActiveAndEnabled)
			{
				animator.SetFloat(triggerId, triggerAmount);
			}
		}
		else
		{
			stream.SendNext(triggerAmount);
		}
	}
}
public class NetworkCollider : Photon.MonoBehaviour
{
	public delegate void ToolCollision(GameObject thisGameObject, Tool toolB, Vector3 point);

	public delegate void PlayerCollision(GameObject thisGameObject, Player player, Player.BodyPart bodyPart, Vector3 point);

	private const float COLLISION_COOLDOWN = 0.5f;

	public bool IsOnline = true;

	private Tool lastToolCollision;

	private float lastToolCollisionTime;

	private Player lastPlayerCollision;

	private float lastPlayerCollisionTime;

	public event ToolCollision ServerToolCollisionEnterEvent;

	public event PlayerCollision ServerPlayerCollisionEnterEvent;

	public event ToolCollision ServerToolTriggerEnterEvent;

	public event PlayerCollision ServerPlayerTriggerEnterEvent;

	private void OnTriggerEnter(Collider collider)
	{
		Vector3 position = base.transform.position;
		Tool colliderTool = collider.GetColliderTool();
		if (colliderTool != null)
		{
			FireToolCollisionRpc(isTrigger: true, colliderTool, position);
			return;
		}
		Player.BodyPart bodyPart;
		Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null)
		{
			FirePlayerCollisionRpc(isTrigger: true, colliderPlayer, bodyPart, position);
		}
	}

	private void OnCollisionEnter(Collision collision)
	{
		Vector3 point = ((collision.contacts.Length <= 0) ? base.transform.position : collision.contacts[0].point);
		Tool colliderTool = collision.GetColliderTool();
		if (colliderTool != null)
		{
			FireToolCollisionRpc(isTrigger: false, colliderTool, point);
			return;
		}
		Player.BodyPart bodyPart;
		Player colliderPlayer = collision.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null)
		{
			FirePlayerCollisionRpc(isTrigger: false, colliderPlayer, bodyPart, point);
		}
	}

	[PunRPC]
	public void RpcMasterToolCollisionEnterEvent(bool isTrigger, int toolId, Vector3 collisionPoint)
	{
		Tool tool = Tool.Find(toolId);
		if (tool != null)
		{
			if (isTrigger && this.ServerToolTriggerEnterEvent != null)
			{
				this.ServerToolTriggerEnterEvent(base.gameObject, tool, collisionPoint);
			}
			else if (!isTrigger && this.ServerToolCollisionEnterEvent != null)
			{
				this.ServerToolCollisionEnterEvent(base.gameObject, tool, collisionPoint);
			}
		}
	}

	[PunRPC]
	public void RpcMasterPlayerCollisionEnterEvent(bool isTrigger, PhotonPlayer hitPhotonPlayer, int playerBodyPart, Vector3 collisionPoint)
	{
		Player player = hitPhotonPlayer.ToPlayer();
		if (player != null)
		{
			if (isTrigger && this.ServerPlayerTriggerEnterEvent != null)
			{
				this.ServerPlayerTriggerEnterEvent(base.gameObject, player, (Player.BodyPart)playerBodyPart, collisionPoint);
			}
			else if (!isTrigger && this.ServerPlayerCollisionEnterEvent != null)
			{
				this.ServerPlayerCollisionEnterEvent(base.gameObject, player, (Player.BodyPart)playerBodyPart, collisionPoint);
			}
		}
	}

	private void FireToolCollisionRpc(bool isTrigger, Tool hitTool, Vector3 point)
	{
		if (!(hitTool == lastToolCollision) || !(Time.time - lastToolCollisionTime <= 0.5f))
		{
			lastToolCollision = hitTool;
			lastToolCollisionTime = Time.time;
			if (IsOnline && base.hasAuthority && hitTool.IsOnline)
			{
				base.photonView.RPC("RpcMasterToolCollisionEnterEvent", PhotonTargets.MasterClient, isTrigger, hitTool.GetComponent<PhotonView>().viewID, point);
			}
		}
	}

	private void FirePlayerCollisionRpc(bool isTrigger, Player hitPlayer, Player.BodyPart bodyPart, Vector3 point)
	{
		if (!(hitPlayer == lastPlayerCollision) || !(Time.time - lastPlayerCollisionTime <= 0.5f))
		{
			lastPlayerCollision = hitPlayer;
			lastPlayerCollisionTime = Time.time;
			if (IsOnline && base.hasAuthority)
			{
				base.photonView.RPC("RpcMasterPlayerCollisionEnterEvent", PhotonTargets.MasterClient, isTrigger, hitPlayer.PhotonPlayer, (int)bodyPart, point);
			}
		}
	}
}
public class NetworkToolSpawner : Tool
{
	public Tool ToolPrefab;

	private Coroutine pickupSpawnCoroutine;

	protected override void OnDestroy()
	{
		PhotonNetwork.RemoveRPCs(base.photonView);
		base.OnDestroy();
	}

	public void InstantiateTool(Vector3 position, Quaternion rotation)
	{
		int num = ToolPrefab.GetComponentsInChildren<PhotonView>(includeInactive: true).Length;
		int[] array = new int[num];
		for (int i = 0; i < array.Length; i++)
		{
			array[i] = PhotonNetwork.AllocateViewID();
		}
		base.photonView.RPC("SpawnToolOnNetwork", PhotonTargets.AllBufferedViaServer, position, rotation, array);
		PhotonNetwork.SendOutgoingCommands();
	}

	[PunRPC]
	public void SpawnToolOnNetwork(Vector3 pos, Quaternion rot, int[] ids)
	{
		Tool tool = UnityEngine.Object.Instantiate(ToolPrefab, pos, rot) as Tool;
		PhotonView[] componentsInChildren = tool.GetComponentsInChildren<PhotonView>(includeInactive: true);
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].viewID = ids[i];
		}
		if (tool != null && base.Owner.isLocal)
		{
			int handTypeId = 0;
			bool flag = false;
			if (base.Owner.LeftHand.Tool == this)
			{
				flag = true;
				handTypeId = 0;
			}
			else if (base.Owner.RightHand.Tool == this)
			{
				flag = true;
				handTypeId = 1;
			}
			if (flag && pickupSpawnCoroutine == null)
			{
				pickupSpawnCoroutine = StartCoroutine(RunPickupSpawn(tool, base.Owner, handTypeId));
			}
		}
	}

	public IEnumerator RunPickupSpawn(Tool tool, Player player, int handTypeId)
	{
		while (tool != null && tool.ToolRenderer == null)
		{
			yield return null;
		}
		if (player != null && tool != null && !tool.IsHeld)
		{
			player.ToolController.ReleaseTool(this);
			player.ToolController.TryPickupTool(tool, handTypeId);
		}
		yield return null;
		pickupSpawnCoroutine = null;
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		InstantiateTool(target.transform.position, target.transform.rotation);
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
	}
}
public class OutfitTool : Tool
{
	public static List<OutfitTool> All = new List<OutfitTool>();

	public Outfit OutfitTarget;

	private bool _isUsedByPlayer;

	private bool _visible;

	private bool _animateIn = true;

	private Vector3 startPosition = Vector3.zero;

	private Quaternion startRotation = Quaternion.identity;

	private float returnHomeSpeed = 0.5f;

	private bool movingBack;

	private float returnStartTime;

	[Header("Return to drawer position")]
	[SerializeField]
	private float maxDistanceFromOrigin = 0.25f;

	[SerializeField]
	private float maxAngleFromOrigin = 15f;

	private float drawerSpawSpeed = 180f;

	[SerializeField]
	private float animateInScaleSpeed = 15f;

	private float targetScale = 1f;

	private bool canCollideWithPlayer = true;

	private float dontCollideWithPlayerStartTime;

	private float dontCollideWithPlayerDuration;

	public bool IsUsedByPlayer
	{
		get
		{
			return _isUsedByPlayer;
		}
		set
		{
			_isUsedByPlayer = value;
			if (OutfitTarget != null && OutfitManager.GetMatchingBodyPart(OutfitTarget.Type) != Player.BodyPart.LeftHand)
			{
				foreach (Renderer renderer in base.ToolRenderer.Renderers)
				{
					renderer.gameObject.SetActive(!_isUsedByPlayer);
				}
				GhostVisual.gameObject.SetActive(_isUsedByPlayer);
			}
			SnapToSpawnPosition();
		}
	}

	public OutfitDrawer Drawer { get; set; }

	public int DrawerIndex { get; set; }

	public bool Visible
	{
		get
		{
			return _visible;
		}
		set
		{
			_visible = value;
			base.ToolRenderer.SetVisible(value);
			if (ToolCollider != null)
			{
				ToolCollider.enabled = value;
			}
			GhostVisual.enabled = value;
			if (GhostCollider != null)
			{
				GhostCollider.enabled = value;
			}
		}
	}

	public Collider ToolCollider { get; set; }

	public Vector3 DrawerPosition { get; set; }

	public Quaternion DrawerRotation { get; set; }

	public Renderer GhostVisual { get; set; }

	public Collider GhostCollider { get; set; }

	public bool AnimateIn
	{
		get
		{
			return _animateIn;
		}
		set
		{
			if (_animateIn == value)
			{
				return;
			}
			_animateIn = value;
			if (!_animateIn && Visible)
			{
				targetScale = 0f;
				if (ToolCollider != null)
				{
					ToolCollider.enabled = false;
				}
			}
			else if (_animateIn)
			{
				Visible = true;
				targetScale = 1f;
				base.ToolRenderer.transform.localScale = Vector3.zero;
			}
		}
	}

	private Vector3 targetSpawnPosition => DrawerPosition;

	private Quaternion targetSpawnRotation => DrawerRotation;

	protected override void Awake()
	{
		base.Awake();
		All.Add(this);
	}

	protected override void Start()
	{
		base.Start();
		pickedCollisionLayer = Layers.DynamicPhysicsIgnoreStaticPhysics;
		if (Player.LocalPlayer != null)
		{
			IsUsedByPlayer = Player.LocalPlayer.PlayerOutfit.IsWearing(OutfitTarget.Guid, OutfitTarget.Type);
			if (OutfitTarget.UsesHairColor)
			{
				PlayerOutfit_HairColorChanged(Player.LocalPlayer.PlayerOutfit.HairColor.color);
				Player.LocalPlayer.PlayerOutfit.HairColorChanged += PlayerOutfit_HairColorChanged;
			}
		}
		else
		{
			UnityEngine.Debug.LogError("Outfit Tool has LocalPlayer null at Start. " + base.gameObject.GetGameObjectHierarchy());
		}
		Visible = false;
		Drawer.UpdateToolVisibility();
	}

	private void PlayerOutfit_HairColorChanged(Color color)
	{
		base.ToolRenderer.Color = color;
	}

	protected override void OnDestroy()
	{
		All.Remove(this);
		if (Player.LocalPlayer != null && OutfitTarget != null && OutfitTarget.UsesHairColor)
		{
			Player.LocalPlayer.PlayerOutfit.HairColorChanged -= PlayerOutfit_HairColorChanged;
		}
		base.OnDestroy();
	}

	protected void Update()
	{
		if (!(Player.LocalPlayer != null))
		{
			return;
		}
		if (!base.IsHeld && Visible)
		{
			if (targetScale != base.ToolRenderer.transform.localScale.x)
			{
				float num = Mathf.SmoothStep(base.ToolRenderer.transform.localScale.x, targetScale, Time.deltaTime * animateInScaleSpeed);
				base.ToolRenderer.transform.localScale = Vector3.one * num;
				if (num <= 0.01f && !AnimateIn)
				{
					Visible = false;
				}
			}
			if (movingBack)
			{
				UpdatePathing(returnHomeSpeed, returnStartTime, Time.time, startPosition, targetSpawnPosition, startRotation, targetSpawnRotation);
				return;
			}
			float magnitude = (base.transform.localPosition - targetSpawnPosition).magnitude;
			float num2 = Quaternion.Angle(base.transform.localRotation, targetSpawnRotation);
			if (magnitude > maxDistanceFromOrigin || num2 > maxAngleFromOrigin)
			{
				StartMovingBack();
			}
		}
		else if (!canCollideWithPlayer && Time.time - dontCollideWithPlayerStartTime > dontCollideWithPlayerDuration)
		{
			canCollideWithPlayer = true;
		}
	}

	public void SnapToSpawnPosition()
	{
		base.transform.localPosition = targetSpawnPosition;
		base.transform.localRotation = targetSpawnRotation;
		if (base.Rigidbody != null)
		{
			base.Rigidbody.ClearVelocity();
			base.Rigidbody.useGravity = false;
			base.Rigidbody.isKinematic = true;
		}
		movingBack = false;
		canCollideWithPlayer = true;
	}

	public void DontCollideWithPlayer(float duration)
	{
		dontCollideWithPlayerDuration = duration;
		dontCollideWithPlayerStartTime = Time.time;
		canCollideWithPlayer = false;
	}

	protected override void OnPlayerTriggerEnter(Player hitPlayer, Player.BodyPart bodyPart, Vector3 point)
	{
		if (canCollideWithPlayer)
		{
			bool flag = bodyPart.IsHand();
			PlayerHand playerHand = null;
			if (flag)
			{
				playerHand = ((bodyPart != Player.BodyPart.LeftHand) ? base.Owner.RightHand : base.Owner.LeftHand);
			}
			if (base.IsHeld && OutfitManager.IsMatchingBodyPart(bodyPart, OutfitTarget.Type) && (!flag || playerHand.Tool != this))
			{
				SetOutfitToPlayer(hitPlayer, bodyPart);
			}
		}
	}

	private void SetOutfitToPlayer(Player player, Player.BodyPart bodyPart)
	{
		if (player != null)
		{
			bool isUsedByPlayer = player.PlayerOutfit.SetOutfit(OutfitTarget, bodyPart, playAudio: true);
			if (base.IsHeld)
			{
				player.ToolController.ReleaseTool(this);
			}
			IsUsedByPlayer = isUsedByPlayer;
		}
		else
		{
			UnityEngine.Debug.LogError(string.Concat("SetOutfitToPlayer has null player. BodyPart : ", bodyPart, " - ", base.gameObject.GetGameObjectHierarchy()));
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		Visible = true;
		base.gameObject.SetActive(value: true);
		base.ToolRenderer.transform.localScale = Vector3.one;
		base.transform.SetParent(player.transform.parent, worldPositionStays: true);
		if (base.Rigidbody != null)
		{
			base.Rigidbody.isKinematic = false;
		}
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
		base.transform.SetParent(Drawer.StartTransform, worldPositionStays: true);
		Visible = false;
		SnapToSpawnPosition();
		if (Drawer != null)
		{
			Drawer.UpdateToolVisibility();
			Visible = Drawer.IsOutfitToolVisible(this);
		}
		else
		{
			UnityEngine.Debug.LogWarning("OutfitTool release without a drawer. " + base.gameObject.GetGameObjectHierarchy());
		}
	}

	public override bool TryGetLocalPickupTransform(Transform handTransform, PlayerHand.HandType handType, out Vector3 position, out Quaternion rotation)
	{
		position = Vector3.zero;
		rotation = handTransform.InverseTransformRotation(base.transform.rotation);
		return true;
	}

	public void StartMovingBack()
	{
		returnHomeSpeed = drawerSpawSpeed;
		movingBack = true;
		returnStartTime = Time.time;
		startPosition = base.transform.localPosition;
		startRotation = base.transform.localRotation;
	}

	public static OutfitTool Find(Guid guid)
	{
		foreach (OutfitTool item in All)
		{
			if (item.OutfitTarget != null && item.OutfitTarget.Guid == guid)
			{
				return item;
			}
		}
		return null;
	}

	private void UpdatePathing(float speed, float startTime, float currentTime, Vector3 startPosition, Vector3 targetPosition, Quaternion startRotation, Quaternion targetRotation)
	{
		Vector3 a = Vector3.Project(startPosition, Vector3.up);
		Vector3 b = Vector3.Project(targetPosition, Vector3.up);
		Vector3 vector = Vector3.ProjectOnPlane(startPosition, Vector3.up);
		Vector3 vector2 = Vector3.ProjectOnPlane(targetPosition, Vector3.up);
		float magnitude = vector.magnitude;
		vector /= magnitude;
		float magnitude2 = vector2.magnitude;
		vector2 /= magnitude2;
		float num = Vector3.Angle(vector, vector2);
		if (num >= Mathf.Epsilon && Vector3.Dot(Vector3.Cross(vector, vector2), Vector3.up) < 0f)
		{
			num = 360f - num;
		}
		if (DrawerIndex > Drawer.OutfitCount / 2 && num < 90f)
		{
			num += 360f;
		}
		float num2 = num / speed;
		float num3 = Mathf.Clamp01((currentTime - startTime) / num2);
		if (num3 >= 1f)
		{
			SnapToSpawnPosition();
			return;
		}
		num *= num3;
		Vector3 normalized = (Quaternion.AngleAxis(num, Vector3.up) * vector).normalized;
		Vector3 vector3 = normalized * Mathf.Lerp(magnitude, magnitude2, num3);
		Vector3 vector4 = Vector3.Lerp(a, b, num3);
		base.transform.localPosition = vector3 + vector4;
		base.transform.localRotation = Quaternion.Slerp(startRotation, targetRotation, num3);
	}
}
public class ProximityOwnershipTransfer : Photon.MonoBehaviour
{
	private void Update()
	{
		if (base.hasAuthority)
		{
			Player player = Player.FindClosest(base.transform.position);
			if (player != null && player.photonView.ownerId != base.photonView.ownerId)
			{
				base.photonView.TransferOwnership(player.photonView.ownerId);
			}
		}
	}
}
public enum ColliderImpactType
{
	Default,
	Strong,
	Weak
}
[RequireComponent(typeof(Collider))]
public abstract class RecRoomCollider : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float kinematicBounciness = 0.6f;

	[SerializeField]
	private ColliderImpactType impactType;

	[HideInInspector]
	public Rigidbody ThisRigidbody;

	[HideInInspector]
	public TrackedVelocity ThisTrackedVelocity;

	protected float boundingRadius;

	public Collider ThisCollider { get; private set; }

	public float KinematicBounciness => kinematicBounciness;

	public ColliderImpactType ImpactType => impactType;

	private void Awake()
	{
		ThisCollider = GetComponent<Collider>();
	}

	private void OnEnable()
	{
		if (ThisCollider != null)
		{
			SphereCollider sphereCollider = ThisCollider as SphereCollider;
			if (sphereCollider != null)
			{
				boundingRadius = sphereCollider.radius;
			}
			else
			{
				boundingRadius = ThisCollider.bounds.extents.magnitude;
			}
		}
	}

	public virtual Vector3 GetCollisionNormal(Collision collision)
	{
		Vector3 vector = Vector3.zero;
		if (ThisRigidbody != null)
		{
			if (ThisRigidbody.isKinematic && ThisTrackedVelocity != null)
			{
				vector = ThisTrackedVelocity.RecentLinearVelocity;
			}
			else if (!ThisRigidbody.isKinematic)
			{
				vector = ThisRigidbody.velocity;
			}
		}
		if (vector.sqrMagnitude < Mathf.Epsilon)
		{
			vector = collision.relativeVelocity.normalized;
		}
		else
		{
			vector.Normalize();
		}
		Vector3 vector2 = Vector3.zero;
		if (collision.contacts != null && collision.contacts.Length > 0)
		{
			ContactPoint contactPoint = collision.contacts[0];
			vector2 = contactPoint.normal;
			Vector3 vector3 = -vector2;
			Vector3 origin = contactPoint.point - vector3;
			if (Physics.Raycast(origin, vector3, out var hitInfo, 2f, 1 << base.gameObject.layer) && Vector3.Dot(hitInfo.normal, vector2) >= 0f)
			{
				vector2 = hitInfo.normal;
			}
		}
		if (vector.sqrMagnitude > Mathf.Epsilon && Vector3.Dot(vector2, vector) < 0.3f)
		{
			vector2 = vector;
		}
		return vector2;
	}

	public bool IsOverlapping(Rigidbody otherRigidbody)
	{
		bool result = false;
		Collider[] array = OverlapBoundingSphere(1 << otherRigidbody.gameObject.layer);
		foreach (Collider collider in array)
		{
			if (collider.gameObject == otherRigidbody.gameObject)
			{
				result = true;
			}
		}
		return result;
	}

	public Collider[] OverlapBoundingSphere(int layerMask)
	{
		return Physics.OverlapSphere(ThisCollider.bounds.center, boundingRadius, layerMask);
	}
}
public class SphereCastCollider : CastCollider
{
	private float colliderRadius;

	public SphereCastCollider(Rigidbody rigidbody, Collider collider, Vector3 colliderCenter)
		: base(rigidbody, collider, colliderCenter)
	{
		Vector3 lossyScale = collider.transform.lossyScale;
		colliderRadius = Mathf.Max(lossyScale.x, lossyScale.y, lossyScale.z) * (collider as SphereCollider).radius;
	}

	protected override RaycastHit[] CastAll(Vector3 origin, Quaternion orientation, Vector3 direction, float distance, int layerMask)
	{
		return Physics.SphereCastAll(origin, colliderRadius, direction, distance, layerMask, QueryTriggerInteraction.Ignore);
	}

	protected override Vector3 GetColliderNormal(Vector3 origin, Quaternion orientation, Vector3 collisionPoint)
	{
		return (collisionPoint - origin).normalized;
	}

	protected override void DrawCastGizmo(Vector3 start, Vector3 end, Quaternion orientation)
	{
		Gizmos.color = Color.red;
		Gizmos.DrawWireSphere(start, colliderRadius);
		Gizmos.color = Color.blue;
		Gizmos.DrawWireSphere(end, colliderRadius);
	}
}
public class StickyNote : StickyTool
{
	private const float INTERPOLATE_TO_SURFACE_DURATION = 0.06f;

	[SerializeField]
	private float maxStickAngle = 45f;

	[SerializeField]
	private float castDistance = 0.4f;

	[SerializeField]
	private BoxCollider boxCollider;

	[Header("Sticky Note Audio")]
	[SerializeField]
	private RecRoomAudioClip onDetachAudio;

	[SerializeField]
	private RecRoomAudioClip onAttachAudio;

	protected override void Awake()
	{
		base.Awake();
		base.AttachEvent += OnAttach;
		base.DetachEvent += OnDetach;
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
		if (base.IsOnline && !base.hasAuthority)
		{
			return;
		}
		Vector3 center = base.transform.TransformPoint(boxCollider.center);
		Vector3 halfExtents = boxCollider.size.MultiplyComponents(boxCollider.transform.lossyScale) / 2f;
		RaycastHit[] array = Physics.BoxCastAll(center, halfExtents, base.transform.forward, base.transform.rotation, castDistance, 2048, QueryTriggerInteraction.Ignore);
		RaycastHit[] array2 = array;
		foreach (RaycastHit raycastHit in array2)
		{
			StickyNoteBoard component = raycastHit.collider.GetComponent<StickyNoteBoard>();
			if (component != null)
			{
				component.GetNoteAttachPosition(base.transform, out var targetPosition, out var targetRotation);
				if (Vector3.Angle(base.transform.forward, component.transform.forward) < maxStickAngle && component.WillFitOnBoard(targetPosition, targetRotation, halfExtents))
				{
					StartCoroutine(StickToBoardCoroutine(component, targetPosition, targetRotation));
					break;
				}
			}
		}
	}

	private IEnumerator StickToBoardCoroutine(StickyNoteBoard board, Vector3 targetPosition, Quaternion targetRotation)
	{
		base.Rigidbody.isKinematic = true;
		Vector3 velocity = base.TrackedVelocity.RecentLinearVelocity;
		Vector3 angularVelocity = base.TrackedVelocity.RecentAngularVelocity;
		for (float timer = 0f; timer < 0.06f; timer += Time.fixedDeltaTime)
		{
			Vector3 nextPosition = Vector3.SmoothDamp(base.Rigidbody.position, targetPosition, ref velocity, 0.06f);
			Vector3 targetEulerAngles = targetRotation.eulerAngles;
			Vector3 eulerAngles = base.transform.rotation.eulerAngles;
			eulerAngles.x = Mathf.SmoothDampAngle(eulerAngles.x, targetEulerAngles.x, ref angularVelocity.x, 0.06f);
			eulerAngles.y = Mathf.SmoothDampAngle(eulerAngles.y, targetEulerAngles.y, ref angularVelocity.y, 0.06f);
			eulerAngles.z = Mathf.SmoothDampAngle(eulerAngles.z, targetEulerAngles.z, ref angularVelocity.z, 0.06f);
			Quaternion nextRotation = Quaternion.Euler(eulerAngles);
			InterpolateRigidbodyTransform(nextPosition, nextRotation);
			yield return new WaitForFixedUpdate();
		}
		base.transform.position = targetPosition;
		base.transform.rotation = targetRotation;
		base.Rigidbody.ClearVelocity();
		board.MoveNoteToTop(this);
		PhotonView connectedPhotonView = board.gameObject.GetComponentInParent<PhotonView>();
		AttachToObject(connectedPhotonView);
	}

	private void InterpolateRigidbodyTransform(Vector3 position, Quaternion rotation)
	{
		Vector3 vector = (position - base.Rigidbody.position) / Time.fixedDeltaTime;
		Vector3 vector2 = UnityExtensions.AngularVelocityFromTo(base.Rigidbody.rotation, rotation) / Time.fixedDeltaTime;
		base.Rigidbody.velocity = vector.ValueOrZeroIfBogus();
		base.Rigidbody.angularVelocity = vector2.ValueOrZeroIfBogus();
		base.Rigidbody.MovePosition(position.ValueOrZeroIfBogus());
		base.Rigidbody.MoveRotation(rotation.ValueOrIdentityIfBogus());
	}

	private void OnAttach(StickyTool tool, bool suppressAudio)
	{
		ToolCleanup component = GetComponent<ToolCleanup>();
		if (component != null)
		{
			component.ResetCleanupOriginalPosition();
		}
		if (!suppressAudio)
		{
			AudioManager.Play3DSFX(onAttachAudio, base.transform.position);
		}
	}

	private void OnDetach(StickyTool tool, bool suppressAudio)
	{
		if (!suppressAudio)
		{
			AudioManager.Play3DSFX(onDetachAudio, base.transform.position);
		}
	}
}
[RequireComponent(typeof(BoxCollider))]
public class StickyNoteBoard : UnityEngine.MonoBehaviour
{
	private const float STACK_OFFSET = 0.001f;

	[SerializeField]
	private List<StickyNote> notes;

	private BoxCollider boxCollider;

	private void Awake()
	{
		boxCollider = GetComponent<BoxCollider>();
		RestackNotes();
	}

	public void GetNoteAttachPosition(Transform noteTransform, out Vector3 targetPosition, out Quaternion targetRotation)
	{
		float num = Vector3.Dot(base.transform.position - noteTransform.position, base.transform.forward) - (float)notes.Count * 0.001f;
		targetPosition = noteTransform.position + num * base.transform.forward;
		targetRotation = Quaternion.FromToRotation(noteTransform.forward, base.transform.forward) * noteTransform.rotation;
	}

	public bool WillFitOnBoard(Vector3 position, Quaternion rotation, Vector3 halfExtents)
	{
		Transform transform = boxCollider.transform;
		Vector3 vector = boxCollider.size / 2f;
		Vector3[] array = new Vector3[4]
		{
			new Vector3(0f - halfExtents.x, 0f - halfExtents.y, 0f),
			new Vector3(0f - halfExtents.x, halfExtents.y, 0f),
			new Vector3(halfExtents.x, halfExtents.y, 0f),
			new Vector3(halfExtents.x, 0f - halfExtents.y, 0f)
		};
		Vector3[] array2 = array;
		foreach (Vector2 vector2 in array2)
		{
			Vector3 vector3 = transform.InverseTransformPoint(position + rotation * vector2);
			if (Mathf.Abs(vector3.x) > vector.x || Mathf.Abs(vector3.y) > vector.y)
			{
				return false;
			}
		}
		return true;
	}

	public void MoveNoteToTop(StickyNote note)
	{
		notes.Remove(note);
		notes.Add(note);
		RestackNotes();
	}

	private void RestackNotes()
	{
		for (int i = 0; i < notes.Count; i++)
		{
			Transform transform = notes[i].transform;
			float num = Vector3.Dot(base.transform.position - transform.position, base.transform.forward) - (float)i * 0.001f;
			transform.position += num * base.transform.forward;
		}
	}
}
public class StickyTool : Tool
{
	public delegate void StickyToolAttachDelegate(StickyTool tool, bool suppressAudio);

	[SerializeField]
	[Header("Sticky Tool")]
	private PhotonView initiallyAttachedTo;

	private bool isAttached;

	private int attachViewID;

	private Vector3 attachRelativePosition;

	private Quaternion attachRelativeRotation;

	private PhotonView _attachPhotonViewField;

	private PhotonView attachPhotonView
	{
		get
		{
			return _attachPhotonViewField;
		}
		set
		{
			if (_attachPhotonViewField != value)
			{
				if (_attachPhotonViewField != null)
				{
					_attachPhotonViewField.OwnerChangedEvent -= AttachOwnerChanged;
				}
				_attachPhotonViewField = value;
				if (_attachPhotonViewField != null)
				{
					_attachPhotonViewField.OwnerChangedEvent += AttachOwnerChanged;
				}
			}
		}
	}

	public event StickyToolAttachDelegate AttachEvent;

	public event StickyToolAttachDelegate DetachEvent;

	protected override void Awake()
	{
		base.Awake();
		AttachToObject(initiallyAttachedTo, suppressAudio: true, broadcast: false);
	}

	protected override void Start()
	{
		base.Start();
		base.ResetEvent += OnReset;
	}

	protected override void OnDestroy()
	{
		Detach(suppressAudio: true);
		base.OnDestroy();
	}

	private void OnReset(Tool tool)
	{
		AttachToObject(initiallyAttachedTo, suppressAudio: true, broadcast: false);
	}

	protected virtual void LateUpdate()
	{
		if (isAttached && attachPhotonView != null)
		{
			base.transform.position = attachPhotonView.transform.TransformPoint(attachRelativePosition);
			base.transform.rotation = attachPhotonView.transform.TransformRotation(attachRelativeRotation);
		}
	}

	public override void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		Detach(suppressAudio: false);
		base.Pickup(player, target, targetSpacePickupPosition, targetSpacePickupRotation);
	}

	public override void Release(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		base.Release(player, linearVelocity, angularVelocity);
	}

	protected void AttachToObject(PhotonView connectedPhotonView, bool suppressAudio = false, bool broadcast = true)
	{
		if (connectedPhotonView != null && connectedPhotonView.ownerId != base.photonView.ownerId)
		{
			base.photonView.TransferOwnership(connectedPhotonView.ownerId);
		}
		int num = ((!(connectedPhotonView != null)) ? (-1) : connectedPhotonView.viewID);
		Vector3 vector = ((!(connectedPhotonView != null)) ? base.transform.position : connectedPhotonView.transform.InverseTransformPoint(base.transform.position));
		Quaternion quaternion = ((!(connectedPhotonView != null)) ? base.transform.rotation : connectedPhotonView.transform.InverseTransformRotation(base.transform.rotation));
		if (broadcast)
		{
			base.photonView.RPC("RpcAttachToObject", PhotonTargets.All, num, vector, quaternion, suppressAudio);
		}
		else
		{
			RpcAttachToObject(num, vector, quaternion, suppressAudio);
		}
	}

	protected void Detach(bool suppressAudio)
	{
		if (isAttached)
		{
			isAttached = false;
			base.Rigidbody.isKinematic = false;
			attachPhotonView = null;
			if (this.DetachEvent != null)
			{
				this.DetachEvent(this, suppressAudio);
			}
		}
	}

	[PunRPC]
	public void RpcAttachToObject(int viewId, Vector3 relativePosition, Quaternion relativeRotation, bool suppressAudio)
	{
		if (isAttached && this.DetachEvent != null)
		{
			this.DetachEvent(this, suppressAudio);
		}
		isAttached = true;
		attachViewID = viewId;
		attachRelativePosition = relativePosition.ValueOrZeroIfBogus();
		attachRelativeRotation = relativeRotation.ValueOrIdentityIfBogus();
		attachPhotonView = ((viewId == -1) ? null : PhotonView.Find(viewId));
		base.Rigidbody.isKinematic = true;
		base.transform.position = ((!(attachPhotonView != null)) ? attachRelativePosition : attachPhotonView.transform.TransformPoint(attachRelativePosition));
		base.transform.rotation = ((!(attachPhotonView != null)) ? attachRelativeRotation : attachPhotonView.transform.TransformRotation(attachRelativeRotation));
		base.Rigidbody.ClearVelocity();
		if (this.AttachEvent != null)
		{
			this.AttachEvent(this, suppressAudio);
		}
	}

	private void AttachOwnerChanged(int newOwnerId)
	{
		base.photonView.TransferOwnership(newOwnerId);
	}

	protected override void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		base.OnPhotonPlayerConnected(newPlayer);
		if (base.hasAuthority && isAttached)
		{
			base.photonView.RPC("RpcAttachToObject", newPlayer, attachViewID, attachRelativePosition, attachRelativeRotation, true);
		}
	}
}
