	public ActivityData ActivityData { get; protected set; }

	public bool IsLocked
	{
		get
		{
			return (!IsOnline) ? _isLocked_Offline : ActivityData.GetData("Tool.IsLocked", defaultValue: false);
		}
		set
		{
			if (IsOnline && IsLocked != value)
			{
				ActivityData.SetData("Tool.IsLocked", value);
			}
			else if (!IsOnline && _isLocked_Offline != value)
			{
				_isLocked_Offline = value;
				OnIsLockedChanged(null, null, null);
			}
		}
	}

	public Player Owner
	{
		get
		{
			if (IsOnline && base.authority != null)
			{
				return base.authority.TagObject as Player;
			}
			return Player.LocalPlayer;
		}
	}

	public bool IsHeld
	{
		get
		{
			if (PhotonNetwork.room == null)
			{
				return true;
			}
			if (IsOnline)
			{
				int data = ActivityData.GetData("Holder", PhotonPlayer.Invalid);
				return data != PhotonPlayer.Invalid;
			}
			return RigidbodyPickup.IsPickedUp;
		}
	}

	public bool IsMoving => Rigidbody.velocity.sqrMagnitude >= 0.25f;

	public bool IsOnline
	{
		get
		{
			bool? flag = isOnline;
			if (!flag.HasValue)
			{
				isOnline = base.photonView != null;
			}
			bool? flag2 = isOnline;
			return flag2.Value;
		}
	}

	public virtual bool OwnershipTransferAllowed => true;

	public bool InPersonalBubble { get; set; }

	public event Action<Tool> ResetEvent;

	public event ToolCollision ServerToolCollisionEnterEvent;

