	public event ToolCollision ServerToolTriggerEnterEvent;

	public event PlayerCollision ServerPlayerTriggerEnterEvent;

	public event PhotonViewCollision ServerPhotonViewTriggerEnterEvent;

	public event KillzoneReset ServerKillzoneResetEvent;

	public event Action<Tool> ServerPickupEvent;

	public event Action<Tool> ServerReleaseEvent;

	public event Action<Tool> PickupEvent;

	public event Action<Tool> ReleaseEvent;

	public event Action<Player, Tool, Vector3, Vector3> ForceApplied;

	private void OnEnable()
	{
		if (Rigidbody != null)
		{
			Rigidbody.maxAngularVelocity = 1f / Time.fixedDeltaTime;
		}
	}

	protected virtual void OnDisable()
	{
		if (Owner != null && Owner.isLocal)
		{
			Owner.ToolController.ReleaseTool(this);
		}
		if (!IsOnline || base.hasAuthority)
		{
			Rigidbody.ClearVelocity();
		}
	}

	protected virtual void Awake()
	{
		NetworkTransform = GetComponent<PUNNetworkTransform>();
		TrackedVelocity = GetComponent<TrackedVelocity>();
		RigidbodyPickup = GetComponent<RigidbodyPickup>();
		Rigidbody = GetComponent<Rigidbody>();
		ToolRenderer = GetComponent<ToolRenderer>();
		ToolAudio = GetComponent<ToolAudio>();
		PlayerInteractionRestriction = GetComponent<PlayerInteractionRestriction>();
		ActivityData = GetComponent<ActivityData>();
		Colliders = new List<ToolCollider>(GetComponentsInChildren<ToolCollider>(includeInactive: true));
		foreach (ToolCollider collider in Colliders)
		{
			collider.Tool = this;
			collider.ThisRigidbody = Rigidbody;
			collider.ThisTrackedVelocity = TrackedVelocity;
		}
		lastSpawnPosition = (lastPickupPosition = base.transform.position);
		lastSpawnRotation = (lastPickupRotation = base.transform.rotation);
		OnlyOwnerCanPickup = false;
		if ((!IsOnline || PhotonNetwork.isMasterClient) && IsOnline)
		{
			ActivityData.SetData("Holder", PhotonPlayer.Invalid);
		}
	}

	protected virtual void Start()
	{
		if (IsOnline)
		{
			if (ToolRenderer != null)
			{
				ToolRenderer.Mode = (IsLocked ? ToolRenderer.HighlightMode.Locked : ToolRenderer.HighlightMode.None);
			}
			ActivityData.RegisterCallback("Tool.IsLocked", OnIsLockedChanged);
		}
	}

	protected virtual void OnDestroy()
	{
		if (IsOnline)
		{
			ActivityData.UnregisterCallback("Tool.IsLocked", OnIsLockedChanged);
		}
	}

	protected virtual void FixedUpdate()
	{
		MasterCheckForCollisionEventListenerChanges();
		if ((!IsOnline || base.hasAuthority) && hasMaxSpeed)
		{
			float magnitude = Rigidbody.velocity.magnitude;
			if (magnitude > maxSpeed)
			{
				Rigidbody.velocity = Rigidbody.velocity / magnitude * maxSpeed;
			}
		}
		if ((!IsOnline || base.hasAuthority) && intersectingKillzones.Count > 0 && Rigidbody.velocity.sqrMagnitude < 0.01f)
		{
			ResetOnKillzone(intersectingKillzones[0]);
		}
		UpdateDynamicKinematicCollision();
		InPersonalBubble = false;
	}

	private void OnIsLockedChanged(ActivityData sender, PhotonPlayer player, string key)
	{
		bool isLocked = IsLocked;
		if (isLocked)
		{
			OnLock();
		}
		else if (!isLocked)
		{
			OnUnlock();
		}
		if (ToolRenderer != null)
		{
			ToolRenderer.Mode = (isLocked ? ToolRenderer.HighlightMode.Locked : ToolRenderer.HighlightMode.None);
		}
		if (SingletonMonoBehaviour<AudioManager>.Instance != null)
		{
			AudioManager.Play3DSFX((!isLocked) ? SingletonMonoBehaviour<AudioManager>.Instance.ToolUnLockedAudio : SingletonMonoBehaviour<AudioManager>.Instance.ToolLockedAudio, base.transform.position);
		}
		if (Owner != null && Owner.isLocal)
		{
			Vector3 vector = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position - base.transform.position;
			Vector3 value = base.transform.position + vector.normalized * 0.1f;
			MenuNotification.PlayNext((!isLocked) ? "Unlocked" : "Locked", 1f, null, followPlayer: false, value, 0.1f, billboard: true);
		}
	}

	protected virtual void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (PhotonNetwork.isMasterClient && shouldReportCollisionEventsToServer)
		{
			base.photonView.RPC("RpcReportCollisionEvents", newPlayer, shouldReportCollisionEventsToServer);
		}
	}

	protected virtual void OnPhotonPlayerDisconnected(PhotonPlayer oldPlayer)
	{
		if (IsOnline && IsHeld && PhotonNetwork.isMasterClient)
		{
			int data = ActivityData.GetData("Holder", PhotonPlayer.Invalid);
			if (data == oldPlayer.ID)
			{
				ActivityData.SetData("Holder", PhotonPlayer.Invalid, data);
				IsLocked = false;
				CmdReleaseEvent();
			}
		}
	}

	public virtual void OnOwnerRoleUpdated()
	{
	}

	public virtual void Pickup(Player player, Rigidbody target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		player.PlayerEvents.ToolPickup(this);
		if (this.PickupEvent != null)
		{
			this.PickupEvent(this);
		}
		lastPickupPosition = base.transform.position;
		lastPickupRotation = base.transform.rotation;
		RigidbodyPickup.Pickup(target, targetSpacePickupPosition, targetSpacePickupRotation);
		if (!IsOnline || base.hasAuthority)
		{
			if (IsOnline)
			{
				base.photonView.RPC("CmdPickupEvent", PhotonTargets.MasterClient);
			}
			SetCollisionLayer(pickedCollisionLayer);
			if (autoLock)
			{
				IsLocked = true;
			}
		}
		if (ToolAudio != null)
		{
			ToolAudio.OnPickup();
		}
	}

	public virtual bool TryGetLocalPickupTransform(Transform handTransform, PlayerHand.HandType handType, out Vector3 position, out Quaternion rotation)
	{
		Transform transform = ((handType != PlayerHand.HandType.Left) ? rightHandPickupTransform : leftHandPickupTransform);
		if (transform == null)
		{
			position = Vector3.zero;
			rotation = Quaternion.identity;
			return false;
		}
		position = transform.InverseTransformPoint(base.transform.position);
		rotation = transform.InverseTransformRotation(base.transform.rotation);
		return true;
	}

