	public virtual void ApplyForce(Vector3 position, Vector3 force)
	{
		if (IsOnline && OwnershipTransferAllowed && !base.hasAuthority && !IsHeld)
		{
			base.photonView.TransferOwnership(PhotonNetwork.player);
		}
		Vector3 normalized = force.normalized;
		float magnitude = Rigidbody.velocity.magnitude;
		Rigidbody.velocity = normalized * magnitude;
		Rigidbody.AddForce(force, ForceMode.Impulse);
		base.photonView.RPC("RpcOnToolForceApplied", PhotonTargets.All, PhotonNetwork.player, position, force);
	}

