[DisallowMultipleComponent]
public class ToolRenderer : UnityEngine.MonoBehaviour
{
	public enum HighlightMode
	{
		None,
		Physical,
		Magnet,
		SmartTool,
		Locked
	}

	protected static readonly Color noHighlightColor = new Color(0f, 0f, 0f, 0f);

	protected static readonly Color physicalPickupHighlightColor = new Color(0.75f, 0.25f, 0.25f, 1f);

	protected static readonly Color magnetPickupHighlightColor = new Color(0.5f, 0.5f, 0.5f, 1f);

	protected static readonly Color smartToolPickupHighlightColor = new Color(0f, 0.2f, 0.7f, 1f);

	protected static readonly Color lockedToolPickupHighlightColor = new Color(0.36f, 0.75f, 0f, 1f);

	[SerializeField]
	protected bool visibleWhileRemoteVisible;

	[SerializeField]
	protected List<Renderer> ignoredRenderers = new List<Renderer>();

	[Header("Accent Renderers")]
	[SerializeField]
	protected ModelMaterial[] accentRenderers;

	[SerializeField]
	protected Color defaultAccentColor;

	[SerializeField]
	[Header("Highlight")]
	protected bool supportsLockedHightlight = true;

	protected Color color = Color.white;

	protected HighlightMode mode;

	protected static int emissionColorId;

	protected Color accentColor;

	public Color AccentColor
	{
		get
		{
			return accentColor;
		}
		set
		{
			accentColor = value;
			if (accentRenderers != null)
			{
				ModelMaterial[] array = accentRenderers;
				for (int i = 0; i < array.Length; i++)
				{
					ModelMaterial modelMaterial = array[i];
					modelMaterial.Renderer.materials[modelMaterial.MaterialIndex].color = accentColor;
				}
			}
		}
	}

	public Color Color
	{
		set
		{
			color = value;
			foreach (Renderer renderer in Renderers)
			{
				Material[] materials = renderer.materials;
				foreach (Material material in materials)
				{
					material.color = color;
				}
			}
		}
	}

	public virtual HighlightMode Mode
	{
		get
		{
			return mode;
		}
		set
		{
			if (mode == value)
			{
				return;
			}
			mode = value;
			Color color = magnetPickupHighlightColor;
			color = ((mode == HighlightMode.Physical) ? physicalPickupHighlightColor : ((mode == HighlightMode.Magnet) ? magnetPickupHighlightColor : ((mode == HighlightMode.SmartTool) ? smartToolPickupHighlightColor : ((mode != HighlightMode.Locked || !supportsLockedHightlight) ? noHighlightColor : lockedToolPickupHighlightColor))));
			foreach (Renderer renderer in Renderers)
			{
				Material[] materials = renderer.materials;
				foreach (Material material in materials)
				{
					material.SetColor(emissionColorId, color);
				}
			}
		}
	}

	public List<Renderer> Renderers { get; private set; }

	public Bounds Bounds
	{
		get
		{
			UnityExtensions.GetCombinedRendererBounds(Renderers, out var bounds);
			return bounds;
		}
	}

	public bool Visible
	{
		get
		{
			return Renderers != null && Renderers[0].enabled && Renderers[0].gameObject.activeSelf;
		}
		private set
		{
			if (Renderers == null)
			{
				return;
			}
			foreach (Renderer renderer in Renderers)
			{
				renderer.enabled = value;
			}
			foreach (Renderer ignoredRenderer in ignoredRenderers)
			{
				ignoredRenderer.enabled = value;
			}
		}
	}

	public void SetVisible(bool toolVisible, bool remoteVisible = false)
	{
		Visible = toolVisible && (visibleWhileRemoteVisible || !remoteVisible);
	}

	protected virtual void Awake()
	{
		InitializeRenderer();
		ResetAccentColor();
	}

	public void ResetAccentColor()
	{
		AccentColor = defaultAccentColor;
	}

	private void InitializeRenderer()
	{
		Renderer[] componentsInChildren = GetComponentsInChildren<Renderer>();
		Renderer[] array = componentsInChildren;
		foreach (Renderer renderer in array)
		{
			if (!ignoredRenderers.Contains(renderer))
			{
				AddRenderer(renderer);
			}
		}
	}

	private void AddRenderer(Renderer renderer, Material highlightMaterialOverride = null)
	{
		if (Renderers == null)
		{
			Renderers = new List<Renderer>();
			emissionColorId = Shader.PropertyToID("_EmissionColor");
		}
		Material[] materials = renderer.materials;
		foreach (Material material in materials)
		{
			material.EnableKeyword("_EMISSION");
		}
		Renderers.Add(renderer);
	}

	public void SetupRenderer(Renderer newMeshRenderer, Material highlightMaterialOverride = null)
	{
		AddRenderer(newMeshRenderer, highlightMaterialOverride);
	}
}
public class ToolTrail : UnityEngine.MonoBehaviour
{
	[Header("Held Trails")]
	[SerializeField]
	private bool visibleWhileHeld = true;

	[SerializeField]
	private float heldTime = 2f;

	[SerializeField]
	[Header("Release Trails")]
	private bool visibleUponRelease = true;

	[SerializeField]
	private float releaseTime = 2f;

	[SerializeField]
	private bool fadeOutUponRelease;

	[SerializeField]
	private float releaseFadeOutDuration = 1f;

	private Tool thisTool;

	private TrailRenderer trailRenderer;

	private Coroutine releaseFadeCoroutine;

	private void Awake()
	{
		thisTool = GetComponentInParent<Tool>();
		thisTool.ReleaseEvent += OnRelease;
		thisTool.PickupEvent += OnPickup;
		trailRenderer = GetComponent<TrailRenderer>();
	}

	private void OnDisable()
	{
		StopReleaseFadeCoroutine();
	}

	private void OnDestroy()
	{
		thisTool.ReleaseEvent -= OnRelease;
		thisTool.PickupEvent -= OnPickup;
	}

	private void OnRelease(Tool tool)
	{
		if (!visibleUponRelease)
		{
			trailRenderer.time = 0f;
			return;
		}
		trailRenderer.time = releaseTime;
		if (fadeOutUponRelease)
		{
			StartReleaseFadeCoroutine();
		}
	}

	private void OnPickup(Tool tool)
	{
		StopReleaseFadeCoroutine();
		if (!visibleWhileHeld)
		{
			trailRenderer.time = 0f;
		}
		else
		{
			trailRenderer.time = heldTime;
		}
	}

	private void StartReleaseFadeCoroutine()
	{
		StopReleaseFadeCoroutine();
		releaseFadeCoroutine = StartCoroutine(ReleaseFadeCoroutine());
	}

	private void StopReleaseFadeCoroutine()
	{
		if (releaseFadeCoroutine != null)
		{
			StopCoroutine(releaseFadeCoroutine);
			releaseFadeCoroutine = null;
		}
	}

	private IEnumerator ReleaseFadeCoroutine()
	{
		float timeRemaining = releaseFadeOutDuration;
		while (timeRemaining >= 0f)
		{
			yield return null;
			timeRemaining -= Time.deltaTime;
			float t = timeRemaining / releaseFadeOutDuration;
			trailRenderer.time = releaseTime * t;
		}
		trailRenderer.time = 0f;
		releaseFadeCoroutine = null;
	}
}
public class ActivityContextMenu : UnityEngine.MonoBehaviour
{
