public class Billboard : UnityEngine.MonoBehaviour
{
	private void Update()
	{
		if (SingletonMonoBehaviour<CameraRig>.Instance != null)
		{
			Vector3 vector = base.transform.position - SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position;
			Vector3 normalized = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
			if (normalized != Vector3.zero)
			{
				base.transform.rotation = Quaternion.LookRotation(normalized, Vector3.up);
			}
		}
	}
}
public class BootSequence : UnityEngine.MonoBehaviour
{
	private IEnumerator Start()
	{
		GameObject[] rootGameObjects = SceneManager.GetActiveScene().GetRootGameObjects();
		foreach (GameObject go in rootGameObjects)
		{
			UnityEngine.Object.DontDestroyOnLoad(go);
		}
		GoogleAnalytics.StartTracking();
		yield return null;
		InitializePlayer();
		LoadInitialScene();
		UnityEngine.Object.Destroy(base.gameObject);
	}

	private void InitializePlayer()
	{
		string text = Player.GenerateLocalPlayerName();
		PhotonNetwork.player.name = text;
		AnalyticsHelper.UserName(text);
		PhotonNetwork.player.SetCustomProperties("prev_activity", "boot");
		if (SteamManager.Initialized)
		{
			CSteamID steamID = SteamUser.GetSteamID();
			if (steamID.IsValid())
			{
				long steamID2 = (long)steamID.m_SteamID;
				PhotonNetwork.player.SetCustomProperties("PlayerSteamId", steamID2);
			}
		}
	}

	private void LoadInitialScene()
	{
		bool isPresent = VRDevice.isPresent;
		string text = null;
		if (!isPresent)
		{
			SceneManager.LoadScene("vr_device_required");
		}
		else if (string.IsNullOrEmpty(text))
		{
			PUNNetworkManager.Instance.SwitchActivity("dormroom", null, createPrivateRoom: false, 0, offlineMode: true);
		}
		else
		{
			PUNNetworkManager.Instance.SwitchActivity(text);
		}
	}
}
public class ButtonCollider : UnityEngine.MonoBehaviour
{
	public Button Button;

	public float consequtiveClickInterval = 1f;

	private float lastTriggerEnterTime;

	private void OnTriggerEnter(Collider collider)
	{
		if (!Button.IsInteractable() || !(Time.time - lastTriggerEnterTime > consequtiveClickInterval))
		{
			return;
		}
		Player.BodyPart bodyPart;
		Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null && bodyPart.IsHand())
		{
			PlayerHand playerHand = ((bodyPart != Player.BodyPart.LeftHand) ? colliderPlayer.RightHand : colliderPlayer.LeftHand);
			Button.Select();
			if (playerHand != null && playerHand.IsVisible)
			{
				lastTriggerEnterTime = Time.time;
				Button.onClick.Invoke();
			}
		}
	}
}
public class ControllerButtonLabels : UnityEngine.MonoBehaviour
{
	public enum ButtonType
	{
		Touchpad,
		Menu,
		Trigger
	}

	[Serializable]
	private struct ButtonLabel
	{
		public ButtonType ButtonType;

		public string AttachPointName;

		public string Text;

		public Vector3 LocalPosition;

		public Vector3 RotationEuler;

		public float LocalScale;
	}

	[SerializeField]
	private Label buttonLabelPrefab;

	[SerializeField]
	private Color buttonColor = new Color(0.6f, 0.6f, 0.6f);

	[SerializeField]
	private ButtonLabel[] buttonLabels;

	private Dictionary<ButtonType, Label> buttonLabelMap = new Dictionary<ButtonType, Label>();

	private void Awake()
	{
		SteamVR_Utils.Event.Listen("render_model_loaded", OnRenderModelLoaded);
		ButtonLabel[] array = buttonLabels;
		for (int i = 0; i < array.Length; i++)
		{
			ButtonLabel buttonLabel = array[i];
			Label label = UnityEngine.Object.Instantiate(buttonLabelPrefab);
			label.transform.SetParent(base.transform);
			label.Text = buttonLabel.Text;
			label.ButtonColor = buttonColor;
			label.gameObject.SetActive(value: false);
			buttonLabelMap.Add(buttonLabel.ButtonType, label);
		}
	}

	private void OnDestroy()
	{
		SteamVR_Utils.Event.Remove("render_model_loaded", OnRenderModelLoaded);
	}

	public void SetButtonLabelVisibility(ButtonType button, bool visible)
	{
		Label value = null;
		if (buttonLabelMap.TryGetValue(button, out value))
		{
			value.Visible = visible;
		}
	}

	private void OnRenderModelLoaded(params object[] args)
	{
		if (((SteamVR_RenderModel)args[0]).gameObject != base.gameObject)
		{
			return;
		}
		ButtonLabel[] array = buttonLabels;
		for (int i = 0; i < array.Length; i++)
		{
			ButtonLabel buttonLabel = array[i];
			Label value = null;
			if (!buttonLabelMap.TryGetValue(buttonLabel.ButtonType, out value))
			{
				continue;
			}
			Transform transform = base.transform.Find(buttonLabel.AttachPointName);
			if (transform != null)
			{
				value.ButtonRenderer = transform.gameObject.GetComponent<Renderer>();
				transform = transform.Find("attach");
				if (transform != null)
				{
					value.transform.SetParent(transform, worldPositionStays: false);
					value.transform.localRotation = Quaternion.Euler(buttonLabel.RotationEuler);
					value.transform.localPosition = buttonLabel.LocalPosition;
					value.transform.localScale.Scale(new Vector3(buttonLabel.LocalScale, buttonLabel.LocalScale, 1f));
					value.gameObject.SetActive(value: true);
				}
			}
		}
	}
}
public class HandsetUI : UnityEngine.MonoBehaviour
{
	public Animator visualAnimator;

	public Text gameTime;

	public Text redTeamScore;

	public Text blueTeamScore;

	private float showDelay = 0.5f;

	private float showTimer;

	private LaserTeleporter laserTeleporter;

	private bool showing;

	public void Start()
	{
		showTimer = 0f;
		laserTeleporter = GetComponent<LaserTeleporter>();
		if (laserTeleporter.Player.isLocal && ActivityManager.Instance != null && ActivityManager.Instance.SupportsPlayingGame)
		{
			ActivityManager.Instance.PlayerManager.ScoresChangedEvent += PlayerManager_ScoresChangedEvent;
			base.enabled = true;
			Reset();
		}
		else
		{
			base.enabled = false;
		}
	}

	private void PlayerManager_ScoresChangedEvent()
	{
		ActivityTeam[] allTeams = ActivityManager.Instance.PlayerManager.GetAllTeams();
		if (allTeams != null && allTeams.Length > 0)
		{
			ActivityTeam[] array = allTeams;
			foreach (ActivityTeam activityTeam in array)
			{
				int teamScore = ActivityManager.Instance.PlayerManager.GetTeamScore(activityTeam);
				if (activityTeam.IsBlueTeam)
				{
					SetBlueTeamScore(teamScore);
				}
				else
				{
					SetRedTeamScore(teamScore);
				}
			}
		}
		else
		{
			Reset();
		}
	}

	private void Update()
	{
		if (!showing && laserTeleporter.TeleportLaserVisible)
		{
			showTimer += Time.deltaTime;
			if (showTimer > showDelay)
			{
				if (visualAnimator != null)
				{
					visualAnimator.SetTrigger("Show");
				}
				showing = true;
			}
		}
		else if (!laserTeleporter.TeleportLaserVisible)
		{
			showing = false;
			showTimer = 0f;
		}
		if (showing && ActivityManager.Instance.IsPlaying)
		{
			float timer = ((!ActivityManager.Instance.HasAGameTimer()) ? 0f : ActivityManager.Instance.GetTimeRemaining());
			SetTimer(timer);
		}
	}

	private void Reset()
	{
		SetRedTeamScore(0);
		SetBlueTeamScore(0);
		SetTimer(0f);
	}

	public void SetTimer(float time)
	{
		if (gameTime != null)
		{
			gameTime.text = time.ToTimeString();
		}
	}

	public void SetRedTeamScore(int score)
	{
		if (redTeamScore != null)
		{
			redTeamScore.text = score.ToString();
		}
	}

	public void SetBlueTeamScore(int score)
	{
		if (blueTeamScore != null)
		{
			blueTeamScore.text = score.ToString();
		}
	}
}
