public class JumbotronUI : UnityEngine.MonoBehaviour
{
	public const string NOT_ENOUGH_PLAYERS_STRING = "Not Enough Players...";

	private Canvas canvas;

	[SerializeField]
	[Header("Title")]
	protected Text Title;

	[SerializeField]
	[Header("Join Game")]
	private Button joinGameButton;

	[SerializeField]
	private Text joinGameButtonText;

	[SerializeField]
	private Button leaveGameButton;

	[SerializeField]
	[Header("Play Game")]
	private Button playButton;

	[SerializeField]
	private Text playButtonText;

	[SerializeField]
	private Button replayButton;

	[Header("Players")]
	[SerializeField]
	private Text playerListHeader;

	[SerializeField]
	private string playerListHeaderString = "Players";

	[SerializeField]
	private JumbotronPlayerEntry[] playerEntries;

	[SerializeField]
	[Header("Teams")]
	private Button switchTeamsButton;

	private string joinGameButtonDefaultText = string.Empty;

	private string playButtonDefaultText = string.Empty;

	protected virtual void Awake()
	{
		canvas = GetComponentInChildren<Canvas>();
		joinGameButtonDefaultText = joinGameButtonText.text;
		playButtonDefaultText = playButtonText.text;
	}

	protected virtual void Start()
	{
		if (canvas != null && ViveControllerInput.Instance != null)
		{
			canvas.worldCamera = ViveControllerInput.Instance.ControllerCamera;
		}
		ActivityManager.Instance.PlayerManager.RolesUpdatedEvent += OnRolesUpdated;
		ActivityManager.Instance.GameStateChangedEvent += OnGameStateChanged;
		ActivityManager.Instance.MasterClientChangedEvent += UpdateUI;
		ActivityManager.Instance.GameModeChangedEvent += UpdateUI;
		Title.text = ActivityManager.ActivityName;
		UpdateUI();
	}

	private void OnDestroy()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.PlayerManager.RolesUpdatedEvent -= OnRolesUpdated;
			ActivityManager.Instance.GameStateChangedEvent -= OnGameStateChanged;
			ActivityManager.Instance.MasterClientChangedEvent -= UpdateUI;
			ActivityManager.Instance.GameModeChangedEvent -= UpdateUI;
		}
	}

	private void OnGameStateChanged(ActivityGameState previousState, ActivityGameState nextState)
	{
		UpdateUI();
	}

	private void OnRolesUpdated(PhotonPlayer updatedPlayer)
	{
		UpdateUI();
	}

	protected virtual void UpdateUI()
	{
		PhotonPlayer[] activePlayersSortedBySlot = ActivityManager.Instance.PlayerManager.GetActivePlayersSortedBySlot();
		int maxActivePlayers = ActivityManager.Instance.PlayerManager.MaxActivePlayers;
		bool flag = ActivityManager.Instance.GameState == ActivityGameState.PreGame;
		if (flag)
		{
			playerListHeader.text = playerListHeaderString + " (" + ((activePlayersSortedBySlot != null) ? activePlayersSortedBySlot.Length : 0) + "/" + maxActivePlayers + ")";
		}
		else
		{
			playerListHeader.text = playerListHeaderString;
		}
		ActivityTeam[] allTeams = ActivityManager.Instance.PlayerManager.GetAllTeams();
		bool flag2 = allTeams != null && allTeams.Length > 0;
		int i = 0;
		if (flag2)
		{
			ActivityTeam[] array = allTeams;
			foreach (ActivityTeam team in array)
			{
				PhotonPlayer[] teamPlayers = ActivityManager.Instance.PlayerManager.GetTeamPlayers(team);
				int teamMaxPlayers = ActivityManager.Instance.PlayerManager.GetTeamMaxPlayers(team);
				UpdatePlayerEntries(ref i, teamPlayers, teamMaxPlayers, team);
			}
		}
		else
		{
			UpdatePlayerEntries(ref i, activePlayersSortedBySlot, maxActivePlayers, null);
		}
		for (; i < playerEntries.Length; i++)
		{
			playerEntries[i].Hide();
		}
		bool flag3 = ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player);
		bool flag4 = activePlayersSortedBySlot == null || activePlayersSortedBySlot.Length < maxActivePlayers;
		if (joinGameButton != null)
		{
			joinGameButton.gameObject.SetActive(flag3 && flag);
			joinGameButton.interactable = flag4;
			joinGameButtonText.text = ((!flag4) ? "Game Full" : joinGameButtonDefaultText);
			leaveGameButton.gameObject.SetActive(!flag3 && flag);
		}
		if (switchTeamsButton != null)
		{
			switchTeamsButton.gameObject.SetActive(flag2 && flag);
			switchTeamsButton.interactable = !flag3 && ActivityManager.Instance.PlayerManager.CanSwitchTeams(PhotonNetwork.player);
		}
		bool supportsPlayingGame = ActivityManager.Instance.SupportsPlayingGame;
		if (playButton != null)
		{
			playButton.gameObject.SetActive(supportsPlayingGame && flag);
			playButton.interactable = ActivityManager.Instance.ReadyToPlay && !flag3;
			playButtonText.text = ((!playButton.interactable && !flag3) ? "Not Enough Players..." : playButtonDefaultText);
		}
		if (replayButton != null)
		{
			replayButton.gameObject.SetActive(supportsPlayingGame && ActivityManager.Instance.GameState == ActivityGameState.PostGame);
		}
	}

	private void UpdatePlayButtons(ActivityGameState currentState)
	{
		bool supportsPlayingGame = ActivityManager.Instance.SupportsPlayingGame;
		bool flag = ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player);
		playButton.gameObject.SetActive(supportsPlayingGame && currentState == ActivityGameState.PreGame);
		playButton.interactable = ActivityManager.Instance.ReadyToPlay && !flag;
		playButtonText.text = ((!playButton.interactable && !flag) ? "Not Enough Players..." : playButtonDefaultText);
		replayButton.gameObject.SetActive(supportsPlayingGame && currentState == ActivityGameState.PostGame);
	}

	private void UpdatePlayerEntries(ref int playerEntryIndex, PhotonPlayer[] activePlayers, int maxPlayers, ActivityTeam team)
	{
		int i = 0;
		while (activePlayers != null && i < activePlayers.Length && i < maxPlayers && playerEntryIndex < playerEntries.Length)
		{
			playerEntries[playerEntryIndex++].Show(activePlayers[i], team);
			i++;
		}
		if (ActivityManager.Instance.GameState != ActivityGameState.PreGame)
		{
			return;
		}
		for (; i < maxPlayers; i++)
		{
			if (playerEntryIndex >= playerEntries.Length)
			{
				break;
			}
			playerEntries[playerEntryIndex++].ShowWaiting(team);
		}
	}

	public void ButtonPress_Play()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.PlayActivity();
		}
	}

	public void ButtonPress_Replay()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.ReplayActivity();
		}
	}

	public void ButtonPress_Restart()
	{
		if (ActivityManager.Instance != null)
		{
			ActivityManager.Instance.RestartActivity();
		}
	}

	public void ButtonPress_JoinGame()
	{
		if (ActivityManager.Instance != null && ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			ActivityManager.Instance.PlayerManager.RequestAutoAssignRole(PhotonNetwork.player);
		}
	}

	public void ButtonPress_LeaveGame()
	{
		if (ActivityManager.Instance != null && !ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			ActivityManager.Instance.PlayerManager.RequestToVacateRole(PhotonNetwork.player);
		}
	}

	public void ButtonPress_SwitchTeam()
	{
		if (ActivityManager.Instance != null && !ActivityManager.Instance.PlayerManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			ActivityManager.Instance.PlayerManager.RequestAutoAssignRoleOnDifferentTeam(PhotonNetwork.player);
		}
	}
}
public class Label : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Text text;

	[SerializeField]
	private UnityEngine.UI.Image line;

	private Renderer _buttonRenderer;

	public Color ButtonColor = Color.white;

	private bool _visible = true;

	public Renderer ButtonRenderer
	{
		get
		{
			return _buttonRenderer;
		}
