public class LeaderboardMenu : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class LeaderboardSelection
	{
		public string titleText;

		public string buttonText;

		public string scoreText = "Wins";

		public PlayerStats.RecroomSteamLeaderboards leaderboardType;

		[NonSerialized]
		public SteamLeaderboardWrapper steamLeaderboard;
	}

	[Serializable]
	public class ScoresMenu
	{
		public Text title;

		public Text ranks;

		public Text names;

		public Text scores;

		public Text scoresHeader;

		public void Clear()
		{
			ranks.text = string.Empty;
			names.text = string.Empty;
			scores.text = string.Empty;
		}
	}

	[SerializeField]
	[Header("Leaderboard")]
	private LeaderboardSelection[] leaderboardSelections;

	[SerializeField]
	private string friendsScoreTitleText = string.Empty;

	[SerializeField]
	private string globalScoreTitleText = string.Empty;

	[Tooltip("Toggle between global and friends scores")]
	public bool ShowGlobalScores = true;

	[Tooltip("Redownload the leader board data periodically.")]
	public float RefreshInternalSeconds = 360f;

	[Header("UI")]
	[SerializeField]
	private Text title;

	[SerializeField]
	private ScoresMenu topScores;

	[SerializeField]
	private ScoresMenu myScore;

	[SerializeField]
	private Button friendsScoresButton;

	[SerializeField]
	private Button globalScoresButton;

	[SerializeField]
	private Text leaderboardToggleButtonText;

	[SerializeField]
	private Button leaderboardToggleButton;

	private int currentSelectionIndex;

	private LeaderboardSelection ActiveSelection => leaderboardSelections[currentSelectionIndex];

	private IEnumerator Start()
	{
		if (!SteamManager.Initialized)
		{
			UnityEngine.Debug.LogError("Steam not initialized, we can not have leaderboards without steam." + base.gameObject.GetGameObjectHierarchy());
			base.gameObject.SetActive(value: false);
			yield break;
		}
		myScore.Clear();
		topScores.Clear();
		while (Player.LocalPlayer == null)
		{
			yield return null;
		}
		yield return new WaitForSeconds(1f);
		LeaderboardSelection[] array = leaderboardSelections;
		foreach (LeaderboardSelection selection in array)
		{
			yield return SingletonMonoBehaviour<LeaderboardManager>.Instance.RunFindLeaderboard(selection.leaderboardType, delegate(SteamLeaderboardWrapper recLeaderboard)
			{
				if (recLeaderboard != null)
				{
					selection.steamLeaderboard = recLeaderboard;
					selection.steamLeaderboard.EntriesDownloadedSelf += SteamLeaderboard_EntriesDownloadedSelf;
					selection.steamLeaderboard.EntriesDownloadedFriends += SteamLeaderboard_EntriesDownloadedFriends;
					selection.steamLeaderboard.EntriesDownloadedTop += SteamLeaderboard_EntriesDownloadedTop;
				}
			});
		}
		LeaderboardSelection[] array2 = leaderboardSelections;
		foreach (LeaderboardSelection selection2 in array2)
		{
			if (ActivityManager.Instance.SupportsPlayingGame && selection2.leaderboardType.ToString().Contains(ActivityManager.ActivityName))
			{
				ActivityManager.Instance.ActivityWonEvent += Instance_ActivityWonEvent;
				break;
			}
		}
		Canvas[] canvases = base.gameObject.GetComponentsInChildren<Canvas>();
		if (canvases != null)
		{
			Canvas[] array3 = canvases;
			foreach (Canvas canvas in array3)
			{
				canvas.worldCamera = ViveControllerInput.Instance.ControllerCamera;
			}
		}
		if (RefreshInternalSeconds > 0f)
		{
			InvokeRepeating("RefreshLeaderboards", RefreshInternalSeconds, RefreshInternalSeconds);
		}
		RefreshMenu();
	}

	private void Instance_ActivityWonEvent(PhotonPlayer arg1, ActivityTeam arg2)
	{
		RefreshLeaderboards();
	}

	private void RefreshLeaderboards()
	{
		StartCoroutine(RunRefreshLeaderboards());
	}

	private IEnumerator RunRefreshLeaderboards()
	{
		LeaderboardSelection[] array = leaderboardSelections;
		foreach (LeaderboardSelection selection in array)
		{
			if (selection != null && selection.steamLeaderboard != null)
			{
				selection.steamLeaderboard.DownloadLeaderboardEntriesAsync();
				yield return new WaitForSeconds(5f);
			}
		}
	}

	private void RefreshMenu()
	{
		topScores.Clear();
		myScore.Clear();
		title.text = "Loading...";
		if (ActiveSelection.steamLeaderboard != null)
		{
			title.text = ((!string.IsNullOrEmpty(ActiveSelection.titleText)) ? ActiveSelection.titleText : ActiveSelection.steamLeaderboard.Name);
			if (topScores.scoresHeader != null)
			{
				topScores.scoresHeader.text = ActiveSelection.scoreText;
			}
			if (ShowGlobalScores)
			{
				topScores.title.text = globalScoreTitleText;
				if (ActiveSelection.steamLeaderboard.EntriesTop != null)
				{
					FormatScores(topScores, ActiveSelection.steamLeaderboard.EntriesTop);
				}
			}
			else
			{
				topScores.title.text = friendsScoreTitleText;
				if (ActiveSelection.steamLeaderboard.EntriesFriends != null)
				{
					FormatScores(topScores, ActiveSelection.steamLeaderboard.EntriesFriends);
				}
			}
			if (ActiveSelection.steamLeaderboard.GetSelfScore(out var self))
			{
				myScore.ranks.text = self.m_nGlobalRank.ToString();
				myScore.names.text = SteamFriends.GetFriendPersonaName(self.m_steamIDUser);
				myScore.scores.text = self.m_nScore.ToString();
			}
		}
		UpdateButtons();
	}

	private void UpdateButtons()
	{
		globalScoresButton.interactable = !ShowGlobalScores;
		friendsScoresButton.interactable = ShowGlobalScores;
		if (ActiveSelection != null)
		{
			leaderboardToggleButtonText.text = ActiveSelection.buttonText;
		}
		leaderboardToggleButton.gameObject.SetActive(leaderboardSelections.Length > 1);
	}

	private void FormatScores(ScoresMenu scoresMenu, List<LeaderboardEntry_t> entries)
	{
		scoresMenu.names.text = string.Empty;
		scoresMenu.ranks.text = string.Empty;
		scoresMenu.scores.text = string.Empty;
		foreach (LeaderboardEntry_t entry in entries)
		{
			Text ranks = scoresMenu.ranks;
			ranks.text = ranks.text + entry.m_nGlobalRank + Environment.NewLine;
			Text names = scoresMenu.names;
			names.text = names.text + SteamFriends.GetFriendPersonaName(entry.m_steamIDUser) + Environment.NewLine;
			Text scores = scoresMenu.scores;
			scores.text = scores.text + entry.m_nScore + Environment.NewLine;
		}
	}

	private void SteamLeaderboard_EntriesDownloadedTop(SteamLeaderboardWrapper leaderboard, List<LeaderboardEntry_t> entries)
	{
		RefreshMenu();
	}

	private void SteamLeaderboard_EntriesDownloadedFriends(SteamLeaderboardWrapper leaderboard, List<LeaderboardEntry_t> entries)
	{
		RefreshMenu();
	}

	private void SteamLeaderboard_EntriesDownloadedSelf(SteamLeaderboardWrapper leaderboard, List<LeaderboardEntry_t> entries)
	{
		RefreshMenu();
	}

	public void Button_ShowGlobalScores(bool global)
	{
		ShowGlobalScores = global;
		RefreshMenu();
	}

	public void Button_ToggleLeaderboardSelection()
	{
		currentSelectionIndex = (currentSelectionIndex + 1) % leaderboardSelections.Length;
		RefreshMenu();
	}
}
public class MenuNotification : UnityEngine.MonoBehaviour
{
	public static List<MenuNotification> All = new List<MenuNotification>();

	[SerializeField]
	private WorldSpaceNotification.NotificationText title;

	[SerializeField]
	private WorldSpaceNotification.NotificationText subtitle;

	[SerializeField]
	private FloatValueCurve alphaEaseInCurve;

	private Coroutine playCoroutine;

	public bool IsPlaying => playCoroutine != null;

	public FollowTarget FollowTarget { get; private set; }

	private void Awake()
	{
		All.Add(this);
		title.Alpha = 0f;
		subtitle.Alpha = 0f;
		FollowTarget = GetComponent<FollowTarget>();
	}

	private void Start()
	{
		base.gameObject.SetActive(value: false);
	}

	private void OnDestroy()
	{
		All.Remove(this);
	}

	public void Play(string titleText, float duration = 5f, string subtitleText = null, bool followPlayer = true, bool billboard = false)
	{
		Stop();
		base.gameObject.SetActive(value: true);
		playCoroutine = StartCoroutine(PlayCoroutine(titleText, subtitleText, duration, followPlayer, billboard));
	}

	public void Stop()
	{
		if (playCoroutine != null)
		{
			StopCoroutine(playCoroutine);
			playCoroutine = null;
			base.gameObject.SetActive(value: false);
		}
	}

	private IEnumerator PlayCoroutine(string titleText, string subtitleText, float duration, bool followPlayer, bool billboard)
	{
		title.Text.text = titleText;
		subtitle.Text.text = subtitleText;
		Vector3 up = Vector3.up;
		Vector3 forward = base.transform.position - SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position;
		if (!billboard)
		{
			forward = Vector3.ProjectOnPlane(forward, up).normalized;
		}
		if (FollowTarget == null || !followPlayer)
		{
			base.transform.rotation = Quaternion.LookRotation(forward, up);
		}
		float timer = 0f;
		float easeInDuration = alphaEaseInCurve.Duration;
		float easeOutDuration = easeInDuration;
		float waitDuration = Mathf.Max(0f, duration - easeInDuration - easeOutDuration);
		while (timer < easeInDuration)
		{
			float t = timer / easeInDuration;
			if (FollowTarget == null || !followPlayer)
			{
				base.transform.position += up * 0.001f;
			}
			title.Alpha = alphaEaseInCurve.Evaluate(t);
			timer += Time.deltaTime;
			yield return new WaitForSeconds(Time.deltaTime);
		}
		title.Alpha = 1f;
		subtitle.Alpha = 1f;
		yield return new WaitForSeconds(waitDuration);
		timer = 0f;
		while (timer < easeOutDuration)
		{
			float t2 = 1f - timer / alphaEaseInCurve.Duration;
			if (FollowTarget == null || !followPlayer)
			{
				base.transform.position -= up * 0.001f;
			}
			title.Alpha = alphaEaseInCurve.Evaluate(t2);
			subtitle.Alpha = alphaEaseInCurve.Evaluate(t2);
			timer += Time.deltaTime;
			yield return new WaitForSeconds(Time.deltaTime);
		}
		title.Alpha = 0f;
		subtitle.Alpha = 0f;
		playCoroutine = null;
	}

	public static bool PlayNext(string titleText, float duration = 5f, string subtitleText = null, bool followPlayer = true, Vector3? worldSpacePosition = null, float scaleOverride = 1f, bool billboard = false)
	{
		MenuNotification nextAvailable = GetNextAvailable();
		if (nextAvailable != null)
		{
			if (followPlayer && nextAvailable.FollowTarget != null)
			{
				nextAvailable.FollowTarget.Target = ((!(Player.LocalPlayer != null)) ? SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform : Player.LocalPlayer.Head.transform);
				nextAvailable.FollowTarget.ForceUpdate();
			}
			else
			{
				nextAvailable.transform.position = ((!worldSpacePosition.HasValue) ? (Player.LocalPlayer.Head.transform.position + Player.LocalPlayer.Head.transform.forward) : worldSpacePosition.Value);
				Vector3 vector = nextAvailable.transform.position - SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position;
				if (!billboard)
				{
					vector = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
				}
				nextAvailable.transform.rotation = Quaternion.LookRotation(vector, Vector3.up);
			}
			nextAvailable.title.Text.transform.localScale = Vector3.one * scaleOverride;
			nextAvailable.subtitle.Text.transform.localScale = Vector3.one * scaleOverride;
			nextAvailable.Play(titleText, duration, subtitleText, followPlayer, billboard);
			return true;
		}
		return false;
	}

	public static MenuNotification GetNextAvailable()
	{
		foreach (MenuNotification item in All)
		{
			if (!item.IsPlaying)
			{
				return item;
			}
		}
		return null;
	}
}
public class PlayerMenu : UnityEngine.MonoBehaviour
{
	[Header("Sub Menus")]
	[SerializeField]
	private PlayerSubMenu[] subMenuPrefabs;

	[Tooltip("Do not change this value without changing all the submenues. Default 0.9")]
	[SerializeField]
	private float menuHeight = 0.9f;

	[Header("Animations")]
	[SerializeField]
	private Transform visualRoot;

	[SerializeField]
	[Header("Audio")]
	private RecRoomAudioClip menuVisibleAudio;

	[SerializeField]
	public RecRoomAudioClip buttonClickAudio;

	[Header("Remote network")]
	[SerializeField]
	private Transform remoteVisual;

	[SerializeField]
	[Header("Confirmation")]
	private PlayerSubMenu confirmationSubMenu;

	private ConfirmationMenuController confirmationMenuController;

	private MenuController[] controllers;

	private List<PlayerSubMenu> subMenues;

	private string messageOfTheDay = string.Empty;

	private bool autoloadMessageOfTheDayMenu;

	private string alertMessage = string.Empty;

	private string alertTitle = string.Empty;

	private bool showAlertMessage;

	private bool _visible;

	[HideInInspector]
	public bool ShowOOBEMessage;

	private Player _thisPlayer;

	private MOTDConfirmationMenuController messageOfTheDayMenuController;

	private PlayerFeedbackConfirmationMenuController playerFeedbackMenuController;

	private PlayerSubMenuMessages messagesSubMenu;

	private PlayerSubMenu peopleSubMenu;

	private Animator Animator { get; set; }

	public bool Visible
	{
		get
		{
			return _visible;
		}
		set
		{
			if (value == _visible)
			{
				return;
			}
			_visible = value;
			if (controllers != null)
			{
				MenuController[] array = controllers;
				foreach (MenuController menuController in array)
				{
					menuController.UpdateButtonInteractability();
				}
			}
			if (Animator != null)
			{
				Animator.SetTrigger((!_visible) ? "Hide" : "Show");
			}
			visualRoot.gameObject.SetActive(_visible);
			if (ThisPlayer.isLocal)
			{
				ThisPlayer.PlayerUI.BroadcastPlayerMenuVisible(_visible);
			}
			if (_visible)
			{
				AudioManager.Play3DSFX(menuVisibleAudio, base.transform.position);
				if (confirmationMenuController != null)
				{
					confirmationMenuController.Visible = false;
				}
				Refresh();
				UpdatePosition();
				if (HasUnseenMessages && ThisPlayer.isLocal)
				{
					StartCoroutine(RunShowMessagesSubMenu());
				}
				else if (ShowOOBEMessage)
				{
					SetHeaderButtonsInteractable(interactable: false);
					messageOfTheDayMenuController.ShowOOBE();
				}
				else if (showAlertMessage)
				{
					SetHeaderButtonsInteractable(interactable: false);
					messageOfTheDayMenuController.ShowAlertMessage(alertTitle, alertMessage);
				}
				else if (autoloadMessageOfTheDayMenu)
				{
					SetHeaderButtonsInteractable(interactable: false);
					messageOfTheDayMenuController.ShowMOTD(messageOfTheDay);
				}
			}
			else if (playerFeedbackMenuController != null && playerFeedbackMenuController.Visible)
			{
				playerFeedbackMenuController.Visible = false;
			}
		}
	}

	public Player ThisPlayer
	{
		get
		{
			return _thisPlayer;
		}
		set
		{
			_thisPlayer = value;
			visualRoot.gameObject.SetActive(value: false);
			bool isLocal = ThisPlayer.isLocal;
			for (int i = 0; i < visualRoot.transform.childCount; i++)
			{
				Transform child = visualRoot.transform.GetChild(i);
				child.gameObject.SetActive(isLocal);
			}
			remoteVisual.gameObject.SetActive(!isLocal);
		}
	}

	public bool HasUnseenMessages { get; set; }

	private void Awake()
	{
		Animator = base.gameObject.GetComponent<Animator>();
		visualRoot.gameObject.SetActive(value: false);
	}

	private void OnDestroy()
	{
		if (messageOfTheDayMenuController != null)
		{
			messageOfTheDayMenuController.ConfirmAction -= OnMessageOfTheDayDismissed;
		}
	}

	public void CreateLocalUserMenues()
	{
		subMenues = new List<PlayerSubMenu>();
		PlayerSubMenu[] array = subMenuPrefabs;
		foreach (PlayerSubMenu original in array)
		{
			PlayerSubMenu playerSubMenu = UnityEngine.Object.Instantiate(original);
			playerSubMenu.transform.SetParent(visualRoot, worldPositionStays: false);
			playerSubMenu.transform.localPosition = Vector3.zero;
			playerSubMenu.transform.localRotation = Quaternion.identity;
			playerSubMenu.PlayerMenu = this;
			subMenues.Add(playerSubMenu);
			if (!(playerSubMenu.Controller != null))
			{
				continue;
			}
			if (playerSubMenu.Controller is MessagesMenuController)
			{
				messagesSubMenu = playerSubMenu as PlayerSubMenuMessages;
			}
			else if (playerSubMenu.Controller is PartyMenuController)
			{
				peopleSubMenu = playerSubMenu;
			}
			else if (playerSubMenu.Controller is PlayerFeedbackConfirmationMenuController)
			{
				playerFeedbackMenuController = playerSubMenu.Controller as PlayerFeedbackConfirmationMenuController;
			}
			else if (playerSubMenu.Controller is MOTDConfirmationMenuController)
			{
				messageOfTheDayMenuController = playerSubMenu.Controller as MOTDConfirmationMenuController;
				if (messageOfTheDayMenuController != null)
				{
					messageOfTheDayMenuController.ConfirmAction += OnMessageOfTheDayDismissed;
				}
			}
		}
		controllers = visualRoot.GetComponentsInChildren<MenuController>(includeInactive: true);
		if (controllers != null)
		{
			MenuController[] array2 = controllers;
			foreach (MenuController menuController in array2)
			{
				menuController.Owner = ThisPlayer;
				menuController.gameObject.SetActive(value: true);
			}
		}
		confirmationSubMenu.PlayerMenu = this;
		confirmationMenuController = confirmationSubMenu.Controller as ConfirmationMenuController;
		RegisterWithViveInput();
		Button[] componentsInChildren = visualRoot.GetComponentsInChildren<Button>(includeInactive: true);
		Button[] array3 = componentsInChildren;
		foreach (Button button in array3)
		{
			button.onClick.AddListener(Button_PlayVFX);
		}
		Toggle[] componentsInChildren2 = visualRoot.GetComponentsInChildren<Toggle>(includeInactive: true);
		Toggle[] array4 = componentsInChildren2;
		foreach (Toggle toggle in array4)
		{
			toggle.onValueChanged.AddListener(Toggle_PlayVFX);
		}
	}

	private void RegisterWithViveInput()
	{
		Canvas[] componentsInChildren = GetComponentsInChildren<Canvas>(includeInactive: true);
		if (componentsInChildren != null && componentsInChildren.Length > 0 && ViveControllerInput.Instance != null)
		{
			Canvas[] array = componentsInChildren;
			foreach (Canvas canvas in array)
			{
				canvas.worldCamera = ViveControllerInput.Instance.ControllerCamera;
			}
		}
		else
		{
			UnityEngine.Debug.LogError(string.Concat(base.gameObject.GetGameObjectHierarchy(), " failed to RegisterWithViveInput. ViveControllerInput.Instance : ", ViveControllerInput.Instance, " - Canvas count : ", (componentsInChildren != null) ? componentsInChildren.Length : 0));
		}
	}

	private IEnumerator RunShowMessagesSubMenu()
	{
		yield return null;
		if (Visible)
		{
			if (messagesSubMenu != null)
			{
				messagesSubMenu.Selected = true;
			}
			HasUnseenMessages = false;
		}
		else
		{
			HasUnseenMessages = true;
		}
	}

	private void OnMessageOfTheDayDismissed(ConfirmationMenuController messageOfTheDayMenu)
	{
		SetHeaderButtonsInteractable(interactable: true);
		Visible = false;
	}

	public void SetHeaderButtonsInteractable(bool interactable)
	{
		foreach (PlayerSubMenu subMenue in subMenues)
		{
			subMenue.Interactable = interactable;
		}
	}

	public void ShowMessageOfTheDay(string message)
	{
		messageOfTheDay = message;
		autoloadMessageOfTheDayMenu = true;
		Visible = true;
		messageOfTheDayMenuController.ShowMOTD(messageOfTheDay);
	}

	public void ShowAlertMessage(string title, string message)
	{
		alertTitle = title;
		alertMessage = message;
		showAlertMessage = true;
		Visible = true;
		messageOfTheDayMenuController.ShowAlertMessage(title, message);
	}

	public void StopShowAlertMessage()
	{
		showAlertMessage = false;
	}

	public void ShowOOBEChangingRoomMessage()
	{
		messageOfTheDayMenuController.ShowOOBEChangingRoom();
	}

	public ConfirmationMenuController ShowConfirmation(string title, string body, string yesButton = "Ok", string noButton = "Cancel")
	{
		confirmationMenuController.ShowConfirmation(title, body, yesButton, noButton);
		Refresh();
		return confirmationMenuController;
	}

	public void ShowDefaultTab()
	{
		if (peopleSubMenu != null)
		{
			peopleSubMenu.Selected = true;
		}
	}

	public void MenuButtonPressed(Player remotePlayer = null)
	{
		if (remotePlayer != null)
		{
			Visible = true;
			ShowRemotePlayerMenu(remotePlayer);
			UpdatePosition();
			return;
		}
		if (!Visible)
		{
			ShowDefaultTab();
			Visible = true;
			return;
		}
		if (confirmationMenuController != null && confirmationMenuController.Visible)
		{
			confirmationMenuController.Visible = false;
			Refresh();
			return;
		}
		if (messageOfTheDayMenuController.Visible)
		{
			messageOfTheDayMenuController.Visible = false;
			Refresh();
		}
		MenuController[] array = controllers;
		foreach (MenuController menuController in array)
		{
			if (menuController.Visible && menuController.ShowSubMenu(show: false))
			{
				menuController.Refresh();
				return;
			}
		}
		Visible = false;
	}

	public void ShowRemotePlayerMenu(Player player)
	{
		if (peopleSubMenu != null)
		{
			peopleSubMenu.Selected = true;
			(peopleSubMenu.Controller as PartyMenuController).ShowPlayerMenu(player);
		}
	}

	public void Refresh()
	{
		if (subMenues == null)
		{
			return;
		}
		foreach (PlayerSubMenu subMenue in subMenues)
		{
			if (subMenue.TabHeaderButton != null)
			{
				subMenue.TabHeaderButton.gameObject.SetActive(confirmationMenuController == null || !confirmationMenuController.Visible);
			}
			if (subMenue.Selected || (subMenue.Controller != null && subMenue.Controller.Visible))
			{
				subMenue.Refresh();
			}
		}
	}

	private void UpdatePosition()
	{
		Transform transform = ThisPlayer.Head.transform;
		base.transform.rotation = Quaternion.Euler(0f, transform.rotation.eulerAngles.y, 0f);
		float num = menuHeight / 2f;
		base.transform.position = transform.position + base.transform.forward * 1.5f + Vector3.down * num;
		float num2 = ThisPlayer.CurrentFloorPosition.y + num;
		if (base.transform.position.y < num2)
		{
			base.transform.position = new Vector3(base.transform.position.x, num2, base.transform.position.z);
		}
	}

	public void OpenLoadSceneMenu(string sceneName)
	{
		if (!Visible)
		{
			Visible = true;
		}
		RunLoadScene(sceneName);
	}

	public void RunLoadScene(string sceneName)
	{
		if (ActivityManager.Instance != null)
		{
			if (ThisPlayer.PlayerParty.IsInParty && confirmationMenuController != null)
			{
				SetHeaderButtonsInteractable(interactable: false);
				string empty = string.Empty;
				string empty2 = string.Empty;
				string empty3 = string.Empty;
				string empty4 = string.Empty;
				if (sceneName == "dormroom")
				{
					empty = $"Go to your {sceneName}?";
					empty2 = "You will leave your current party!";
					empty3 = "OK";
					empty4 = "Cancel";
				}
				else
				{
					empty = ((!string.IsNullOrEmpty(sceneName)) ? ("Go to " + sceneName) : "Go to new activity");
					empty2 = "Who is going?";
					empty3 = "Bring party";
					empty4 = "Go alone";
				}
				ShowConfirmation(empty, empty2, empty3, empty4);
				confirmationMenuController.Data = new object[1] { sceneName };
				confirmationMenuController.ConfirmAction += LoadSceneConfirmation;
			}
			else
			{
				ActivityManager.Instance.SwitchActivity(sceneName);
				Visible = false;
			}
		}
		else
		{
			UnityEngine.Debug.LogError("Button_LoadScene '" + sceneName + "', ActivityManager is null.");
		}
	}

	private void LoadSceneConfirmation(ConfirmationMenuController confirmMenu)
	{
		confirmationMenuController.ConfirmAction -= LoadSceneConfirmation;
		SetHeaderButtonsInteractable(interactable: true);
		string text = confirmMenu.Data[0] as string;
		if (!confirmMenu.Confirm.HasValue)
		{
			return;
		}
		if (text == "dormroom")
		{
			if (confirmMenu.Confirm.Value)
			{
				ThisPlayer.PlayerParty.LeaveCurrentParty();
				ActivityManager.Instance.SwitchActivity(text);
				Visible = false;
			}
		}
		else
		{
			if (!confirmMenu.Confirm.Value)
			{
				ThisPlayer.PlayerParty.LeaveCurrentParty();
			}
			ActivityManager.Instance.SwitchActivity(text);
			Visible = false;
		}
	}

	public void RunPreviousActivityPlayerFeedbackMenu(string activityName)
	{
		if (!(playerFeedbackMenuController == null))
		{
			bool visible = Visible;
			if (!visible)
			{
				Visible = true;
			}
			SetHeaderButtonsInteractable(interactable: false);
			playerFeedbackMenuController.ConfirmAction += OnPlayerFeedbackMenuConfirmation;
			playerFeedbackMenuController.ShowConfirmation();
			playerFeedbackMenuController.Data = new object[2]
			{
				activityName,
				new bool?(visible)
			};
		}
	}

	private void OnPlayerFeedbackMenuConfirmation(ConfirmationMenuController confirmMenu)
	{
		confirmMenu.ConfirmAction -= LoadSceneConfirmation;
		SetHeaderButtonsInteractable(interactable: true);
		string activityName = confirmMenu.Data[0] as string;
		int num = (confirmMenu.ConfirmationValue.HasValue ? confirmMenu.ConfirmationValue.Value : 0);
		if (num < 0)
		{
			ActivityManager.PreviousActivityFeedbackEnabled = false;
			AnalyticsHelper.ActivityPlayerFeedbackDisabled(activityName);
		}
		else if (num == 0)
		{
			AnalyticsHelper.ActivityPlayerFeedbackDismissed(activityName);
		}
		else
		{
			AnalyticsHelper.ActivityPlayerFeedback(activityName, num);
		}
		bool? flag = confirmMenu.Data[1] as bool?;
		if (!flag.HasValue || !flag.Value)
		{
			Visible = false;
		}
	}

	private void Button_PlayVFX()
	{
		AudioManager.Play3DSFX(buttonClickAudio, base.transform.position);
	}

	private void Toggle_PlayVFX(bool value)
	{
		AudioManager.Play3DSFX(buttonClickAudio, base.transform.position);
	}

	private void Slider_PlayVFX(float value)
	{
		AudioManager.Play3DSFX(buttonClickAudio, base.transform.position);
	}
}
