public class Tooltip : UnityEngine.MonoBehaviour
{
	public string Message = "Hello";

	public float ShowDelay = 0.75f;

	private TooltipUI tooltipUI;

	private float hoverStartTime;

	private bool wasHovered;

	private bool isHovered;

	private Transform cursor;

	public bool Hovered { get; set; }

	private void Update()
	{
		if (isHovered != wasHovered)
		{
			if (isHovered)
			{
				hoverStartTime = Time.time;
			}
			else
			{
				Hide();
			}
		}
		if (isHovered)
		{
			if (tooltipUI != null && cursor != null)
			{
				tooltipUI.transform.position = cursor.position;
				Vector3 eulerAngles = cursor.rotation.eulerAngles;
				eulerAngles.z = 0f;
				tooltipUI.transform.rotation = Quaternion.Euler(eulerAngles);
				if (!cursor.gameObject.activeSelf)
				{
					Hide();
				}
			}
			else if (Time.time - hoverStartTime >= ShowDelay)
			{
				Show();
			}
		}
		wasHovered = isHovered;
	}

	private void LateUpdate()
	{
		isHovered = false;
	}

	private void OnDisable()
	{
		Hide();
	}

	public void SetHoverPoint(Transform hoveredCursor)
	{
		isHovered = true;
		if (cursor == null)
		{
			cursor = hoveredCursor;
		}
	}

	private void Hide()
	{
		if (tooltipUI != null)
		{
			tooltipUI.Release();
			tooltipUI = null;
		}
		cursor = null;
	}

	private void Show()
	{
		if (tooltipUI == null)
		{
			tooltipUI = TooltipUI.Acquire(Message);
		}
	}
}
public class TooltipUI : UnityEngine.MonoBehaviour
{
	public static List<TooltipUI> All = new List<TooltipUI>();

	[SerializeField]
	private TextMesh textMesh;

	[SerializeField]
	private Transform background;

	[SerializeField]
	private Vector2 backgroundHorizontalPadding = new Vector2(0.05f, 0.05f);

	private Renderer textRenderer;

	private Renderer backgroundRenderer;

	private float defaultTextAlpha;

	private float defaultBackgroundAlpha;

	private float fadeSpeed = 10f;

	public string Message
	{
		get
		{
			return textMesh.text;
		}
		set
		{
			textMesh.text = value;
			StartCoroutine(RunUpdateBoundsSize());
		}
	}

	private void Awake()
	{
		All.Add(this);
		base.gameObject.SetActive(value: false);
		textRenderer = textMesh.GetComponent<Renderer>();
		textRenderer.material.renderQueue = 10000;
		backgroundRenderer = background.GetComponent<Renderer>();
		backgroundRenderer.material.renderQueue = 9999;
		defaultTextAlpha = textRenderer.material.color.a;
		defaultBackgroundAlpha = backgroundRenderer.material.color.a;
	}

	private void OnDestroy()
	{
		All.Remove(this);
	}

	private void OnDisable()
	{
		if (textRenderer != null)
		{
			textRenderer.SetColorAlpha(0f);
			backgroundRenderer.SetColorAlpha(0f);
		}
	}

	private IEnumerator RunUpdateBoundsSize()
	{
		yield return null;
		Quaternion rotation = textMesh.transform.rotation;
		textMesh.transform.rotation = Quaternion.identity;
		Bounds bounds = textRenderer.bounds;
		Vector3 boundsSize = bounds.size;
		textMesh.transform.rotation = rotation;
		background.transform.localScale = new Vector3(boundsSize.x + backgroundHorizontalPadding.x, boundsSize.y + backgroundHorizontalPadding.y, boundsSize.z);
		Vector3 localBackgroundPosition = textMesh.transform.InverseTransformPoint(bounds.center);
		localBackgroundPosition.z = 0f;
		background.transform.localPosition = localBackgroundPosition;
	}

	public static TooltipUI Acquire(string message)
	{
		foreach (TooltipUI item in All)
		{
			if (item != null && !item.gameObject.activeSelf)
			{
				item.gameObject.SetActive(value: true);
				item.Message = message.Replace("\\n", Environment.NewLine);
				item.StartCoroutine(item.RunFadeIn());
				return item;
			}
		}
		return null;
	}

	public void Release()
	{
		base.gameObject.SetActive(value: false);
	}

	private IEnumerator RunFadeIn()
	{
		float t = 0f;
		while (t < 1f)
		{
			t = Mathf.SmoothStep(t, 1f, Time.deltaTime * fadeSpeed);
			textRenderer.SetColorAlpha(defaultTextAlpha * t);
			backgroundRenderer.SetColorAlpha(defaultBackgroundAlpha * t);
			yield return null;
		}
	}
}
public class WorldSpaceNotification : SingletonMonoBehaviour<WorldSpaceNotification>
{
	[Serializable]
	public class NotificationText
	{
		public Text Text;

		public Outline Outline;

		public float Alpha
		{
			set
			{
				Color color = Text.color;
				color.a = value;
				Text.color = color;
				Color effectColor = Outline.effectColor;
				effectColor.a = value;
				Outline.effectColor = effectColor;
			}
		}
	}

	[SerializeField]
	private NotificationText title;

	[SerializeField]
	private NotificationText subtitle;

	[SerializeField]
	private Vector3ValueCurve cameraOffsetEaseInCurve;

	[SerializeField]
	private FloatValueCurve alphaEaseInCurve;

	[SerializeField]
	private FloatValueCurve alphaEaseOutCurve;

	private Vector3 positionCameraSpace = Vector3.zero;

	private Coroutine playCoroutine;

	private void Awake()
	{
		SingletonMonoBehaviour<WorldSpaceNotification>.Instance = this;
		title.Alpha = 0f;
		subtitle.Alpha = 0f;
	}

	private void LateUpdate()
	{
		if (playCoroutine != null)
		{
			Vector3 position = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.position;
			Vector3 up = Vector3.up;
			Vector3 forward = SingletonMonoBehaviour<CameraRig>.Instance.CameraIO.transform.forward;
			Vector3 localSpaceRight = Vector3.Cross(forward, up);
			base.transform.position = positionCameraSpace.TransformToWorldSpace(position, localSpaceRight, up, forward);
			base.transform.rotation = Quaternion.LookRotation(forward, up);
		}
	}

	public void Play(string titleText, float duration = 5f, string subtitleText = null)
	{
		Stop();
		playCoroutine = StartCoroutine(PlayCoroutine(titleText, subtitleText, duration));
	}

	public void Stop()
	{
		if (playCoroutine != null)
		{
			StopCoroutine(playCoroutine);
		}
	}

	public static void DebugLog(object text)
	{
		SingletonMonoBehaviour<WorldSpaceNotification>.Instance.PlayDebug(text.ToString());
	}

	public static void DebugLog(string text)
	{
		SingletonMonoBehaviour<WorldSpaceNotification>.Instance.PlayDebug(text);
	}

	public void PlayDebug(string text, float expirationTime = 1f)
	{
		Stop();
		playCoroutine = StartCoroutine(PlayDebugCoroutine(text, expirationTime));
	}

	private IEnumerator PlayCoroutine(string titleText, string subtitleText, float duration)
	{
		title.Text.text = titleText;
		subtitle.Text.text = subtitleText;
		float timer = 0f;
		float waitDuration = Mathf.Max(0f, duration - cameraOffsetEaseInCurve.Duration - alphaEaseOutCurve.Duration);
		while (timer < cameraOffsetEaseInCurve.Duration)
		{
			float t = timer / cameraOffsetEaseInCurve.Duration;
			positionCameraSpace = cameraOffsetEaseInCurve.Evaluate(t);
			title.Alpha = alphaEaseInCurve.Evaluate(t);
			subtitle.Alpha = alphaEaseInCurve.Evaluate(t);
			timer += Time.deltaTime;
			yield return null;
		}
		title.Alpha = 1f;
		subtitle.Alpha = 1f;
		yield return new WaitForSeconds(waitDuration);
		timer = 0f;
		while (timer < alphaEaseOutCurve.Duration)
		{
			float t2 = timer / alphaEaseOutCurve.Duration;
			title.Alpha = alphaEaseOutCurve.Evaluate(t2);
			subtitle.Alpha = alphaEaseOutCurve.Evaluate(t2);
			timer += Time.deltaTime;
			yield return null;
		}
		title.Alpha = 0f;
		subtitle.Alpha = 0f;
		playCoroutine = null;
	}

	private IEnumerator PlayDebugCoroutine(string text, float expirationTime)
	{
		title.Text.text = text;
		title.Alpha = 1f;
		subtitle.Text.text = null;
		subtitle.Alpha = 0f;
		positionCameraSpace = cameraOffsetEaseInCurve.Evaluate(1f);
		yield return new WaitForSeconds(expirationTime);
		title.Alpha = 0f;
		playCoroutine = null;
	}
}
public class CollisionForwarder : UnityEngine.MonoBehaviour
