namespace DebugUtils
{
	public class ValueOverTime
	{
		private string name;

		private Color color;

		private float graphTimeLength;

		private float? overrideMin;

		private float? overrideMax;

		private List<Vector2> valueHistory;

		private GUIStyle bottomJustify;

		public ValueOverTime(string name, Color color, float graphTimeLength, float? overrideMin = null, float? overrideMax = null)
		{
			this.name = name;
			this.color = color;
			this.graphTimeLength = graphTimeLength;
			this.overrideMin = overrideMin;
			this.overrideMax = overrideMax;
			valueHistory = new List<Vector2>();
		}

		public void AddDataPoint(float value)
		{
			while (valueHistory.Count > 0 && Time.realtimeSinceStartup - valueHistory[0].x > graphTimeLength)
			{
				valueHistory.RemoveAt(0);
			}
			valueHistory.Add(new Vector2(Time.realtimeSinceStartup, value));
		}

		public void DrawGraph(Rect screenRect)
		{
			if (bottomJustify == null)
			{
				bottomJustify = new GUIStyle(GUI.skin.label);
				bottomJustify.alignment = TextAnchor.LowerLeft;
			}
			int num = 0;
			if (valueHistory.Count > 0)
			{
				num = Mathf.RoundToInt(valueHistory.Sum((Vector2 p) => p.y) / (float)valueHistory.Count);
			}
			GUI.Box(screenRect, $"{name} (Avg: {num})", GUI.skin.box);
			if (Event.current.type == EventType.Repaint && valueHistory.Count > 0)
			{
				screenRect.xMin += 1f;
				screenRect.xMax -= 1f;
				screenRect.yMin += 1f;
				screenRect.yMax -= 1f;
				Rect valueRect = new Rect
				{
					xMin = Time.realtimeSinceStartup - graphTimeLength,
					xMax = Time.realtimeSinceStartup,
					yMin = Mathf.Floor((!overrideMin.HasValue) ? Mathf.Min(-1f, valueHistory.Min((Vector2 p) => p.y)) : overrideMin.Value),
					yMax = Mathf.Ceil((!overrideMax.HasValue) ? Mathf.Max(1f, valueHistory.Max((Vector2 p) => p.y)) : overrideMax.Value)
				};
				GUI.Label(screenRect, ((int)valueRect.yMax).ToString());
				GUI.Label(screenRect, ((int)valueRect.yMin).ToString(), bottomJustify);
				DrawLine(new Vector2(valueRect.xMin, 0f), new Vector2(valueRect.xMax, 0f), valueRect, screenRect, Color.black);
				DrawPolyLine(valueHistory, valueRect, screenRect, color);
			}
		}

		private void DrawLine(Vector2 pointA, Vector2 pointB, Rect valueRect, Rect screenRect, Color color)
		{
			Drawing.DrawLine(ScaleToRect(pointA, valueRect, screenRect), ScaleToRect(pointB, valueRect, screenRect), color, 1f, antiAlias: false);
		}

		private void DrawPolyLine(IEnumerable<Vector2> points, Rect valueRect, Rect screenRect, Color color)
		{
			Drawing.DrawPolyLine(points.Select((Vector2 p) => ScaleToRect(p, valueRect, screenRect)), color, 1f, antiAlias: true);
		}

		private Vector2 ScaleToRect(Vector2 point, Rect valueRect, Rect screenRect)
		{
			point.x = Mathf.Lerp(screenRect.xMin, screenRect.xMax, (point.x - valueRect.xMin) / valueRect.width);
			point.y = Mathf.Lerp(screenRect.yMax, screenRect.yMin, (point.y - valueRect.yMin) / valueRect.height);
			return point;
		}
	}
}
