public class ObjectPool : SingletonMonoBehaviour<ObjectPool>
{
	[Serializable]
	public class ObjectPoolEntry
	{
		public GameObject Prefab;

		[NonSerialized]
		public List<GameObject> Objects = new List<GameObject>();

		public ObjectPoolEntry(GameObject prefab)
		{
			Prefab = prefab;
		}
	}

	public List<ObjectPoolEntry> Pools;

	private Transform poolContainer;

	private Transform activeObjectRoot => poolContainer ?? base.transform;

	private void Awake()
	{
		SingletonMonoBehaviour<ObjectPool>.Instance = this;
		SceneManager.activeSceneChanged += SceneManager_activeSceneChanged;
	}

	private void SceneManager_activeSceneChanged(Scene oldScene, Scene newScene)
	{
		if (poolContainer == null && ActivityManager.Instance != null)
		{
			poolContainer = new GameObject("ObjectPool Container").transform;
		}
	}

	public bool RegisterObjectPrefab(GameObject newPrefab)
	{
		if (FindPool(newPrefab.name) == null)
		{
			Pools.Add(new ObjectPoolEntry(newPrefab));
			return true;
		}
		return false;
	}

	private GameObject InstantiateNewObject(GameObject prefab)
	{
		GameObject gameObject = UnityEngine.Object.Instantiate(prefab);
		gameObject.name = prefab.name;
		gameObject.transform.parent = activeObjectRoot;
		return gameObject;
	}

	private ObjectPoolEntry FindPool(string name)
	{
		foreach (ObjectPoolEntry pool in Pools)
		{
			if (pool.Prefab.name == name)
			{
				return pool;
			}
		}
		return null;
	}

	public T Acquire<T>(string objectType)
	{
		ObjectPoolEntry objectPoolEntry = FindPool(objectType);
		if (objectPoolEntry != null)
		{
			while (objectPoolEntry.Objects.Count > 0)
			{
				GameObject gameObject = objectPoolEntry.Objects[0];
				objectPoolEntry.Objects.RemoveAt(0);
				if (gameObject != null)
				{
					gameObject.SetActive(value: true);
					return gameObject.GetComponent<T>();
				}
				UnityEngine.Debug.LogError("ObjectPool '" + objectType + "' contains a null entry!");
			}
			return InstantiateNewObject(objectPoolEntry.Prefab).GetComponent<T>();
		}
		return default(T);
	}

	public bool Release(GameObject obj)
	{
		ObjectPoolEntry objectPoolEntry = FindPool(obj.name);
		if (objectPoolEntry != null)
		{
			obj.SetActive(value: false);
			objectPoolEntry.Objects.Add(obj);
			obj.transform.parent = activeObjectRoot;
			return true;
		}
		UnityEngine.Object.Destroy(obj);
		return false;
	}
}
