public class PerformanceCounters : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class HistogramData
	{
		public string name;

		public Vector2 bounds;

		[NonSerialized]
		public int Count;

		[NonSerialized]
		public float Average;

		public void Accumulate(float value)
		{
			if (bounds.WithinBounds(value))
			{
				Average = (Average * (float)Count + value) / (float)(Count + 1);
				Count++;
			}
		}

		public void Reset()
		{
			Count = 0;
			Average = 0f;
		}
	}

	[SerializeField]
	private HistogramData[] fpsHistograms;

	[SerializeField]
	private HistogramData[] pingHistograms;

	[SerializeField]
	private float updateInterval = 1f;

	private float timeLeft;

	private int frameCount;

	private float accumulatedFPS;

	private float accumulatedPing;

	public float FPS { get; private set; }

	public float RountTripTime { get; private set; }

	private void Start()
	{
		FPS = 0f;
		RountTripTime = 0f;
		timeLeft = updateInterval;
	}

	private void Update()
	{
		frameCount++;
		accumulatedFPS += Time.timeScale / Time.deltaTime;
		timeLeft -= Time.deltaTime;
		accumulatedPing += PhotonNetwork.GetPing();
		if (timeLeft <= 0f && frameCount > 0)
		{
			FPS = accumulatedFPS / (float)frameCount;
			RountTripTime = accumulatedPing / (float)frameCount;
			RecordHistogramValues();
			accumulatedPing = 0f;
			accumulatedFPS = 0f;
			timeLeft = updateInterval;
			frameCount = 0;
		}
	}

	private void RecordHistogramValues()
	{
		for (int i = 0; i < fpsHistograms.Length; i++)
		{
			fpsHistograms[i].Accumulate(FPS);
		}
		for (int j = 0; j < pingHistograms.Length; j++)
		{
			pingHistograms[j].Accumulate(RountTripTime);
		}
	}

	public void ResetHistograms()
	{
		for (int i = 0; i < fpsHistograms.Length; i++)
		{
			fpsHistograms[i].Reset();
		}
		for (int j = 0; j < pingHistograms.Length; j++)
		{
			pingHistograms[j].Reset();
		}
	}

	public void LogHistogramsToAnalytics(string context)
	{
	}

	private string HistogramListToAnalytics(HistogramData[] histograms)
	{
		int num = 0;
		for (int i = 0; i < histograms.Length; i++)
		{
			num += histograms[i].Count;
		}
		if (num < 30)
		{
			return null;
		}
		string text = string.Empty;
		for (int j = 0; j < histograms.Length; j++)
		{
			if (histograms[j].Count > 0)
			{
				string text2 = text;
				text = text2 + histograms[j].name + "; distribution:" + ((float)histograms[j].Count * 100f / (float)num).ToString("F1") + "%; average:" + histograms[j].Average.ToString("F2");
				if (j < histograms.Length - 1)
				{
					text += Environment.NewLine;
				}
			}
		}
		return text;
	}
}
public class PooledParticle : UnityEngine.MonoBehaviour
{
	private ParticleSystem particles;

	private bool playOnEnable;

	private void Awake()
	{
		particles = GetComponent<ParticleSystem>();
		playOnEnable = particles.playOnAwake;
	}

	private void OnEnable()
	{
		if (particles != null && playOnEnable)
		{
			particles.Play();
			Invoke("DeferredHide", particles.duration);
		}
	}

	private void OnDisable()
	{
		CancelInvoke("DeferredHide");
	}

	private void DeferredHide()
	{
		SingletonMonoBehaviour<ObjectPool>.Instance.Release(base.gameObject);
	}

	public void Play()
	{
		particles.Play();
	}
}
