public class SingletonMonoBehaviour<T> : UnityEngine.MonoBehaviour where T : UnityEngine.MonoBehaviour
{
	private static T instance;

	public static T Instance
	{
		get
		{
			return instance;
		}
		protected set
		{
			if (instance == null)
			{
				instance = value;
			}
			else
			{
				UnityEngine.Debug.LogError("Created more than one singleton of " + typeof(T).ToString() + "!");
			}
		}
	}

	public static bool IsInitialized => Instance != null;
}
public class SteamLeaderboardWrapper
{
	public delegate void EntriesDownloaded(SteamLeaderboardWrapper leaderboard, List<LeaderboardEntry_t> entries);

	private CallResult<LeaderboardScoresDownloaded_t> LeaderboardScoresDownloadedTop;

	private CallResult<LeaderboardScoresDownloaded_t> LeaderboardScoresDownloadedSelf;

	private CallResult<LeaderboardScoresDownloaded_t> LeaderboardScoresDownloadedFriends;

	private CallResult<LeaderboardScoreUploaded_t> LeaderboardScoreUploaded;

	private SteamLeaderboardEntries_t m_SteamLeaderboardEntries;

	private SteamLeaderboard_t m_SteamLeaderboard;

	public List<LeaderboardEntry_t> EntriesSelf;

	public List<LeaderboardEntry_t> EntriesTop;

	public List<LeaderboardEntry_t> EntriesFriends;

	private static int downloadLeaderboardEntriesCount;

	private bool selfEntryDirty = true;

	public string Name { get; private set; }

	public event EntriesDownloaded EntriesDownloadedSelf;

	public event EntriesDownloaded EntriesDownloadedTop;

	public event EntriesDownloaded EntriesDownloadedFriends;

	public SteamLeaderboardWrapper(SteamLeaderboard_t m_SteamLeaderboard)
	{
		this.m_SteamLeaderboard = m_SteamLeaderboard;
		Name = SteamUserStats.GetLeaderboardName(m_SteamLeaderboard);
		LeaderboardScoresDownloadedTop = CallResult<LeaderboardScoresDownloaded_t>.Create(OnLeaderboardScoresDownloadedTop);
		LeaderboardScoresDownloadedSelf = CallResult<LeaderboardScoresDownloaded_t>.Create(OnLeaderboardScoresDownloadedSelf);
		LeaderboardScoresDownloadedFriends = CallResult<LeaderboardScoresDownloaded_t>.Create(OnLeaderboardScoresDownloadedFriends);
		LeaderboardScoreUploaded = CallResult<LeaderboardScoreUploaded_t>.Create(OnLeaderboardScoreUploaded);
		DownloadLeaderboardEntriesAsync();
	}

	public void UploadScore(int score, ELeaderboardUploadScoreMethod uploadMethod = ELeaderboardUploadScoreMethod.k_ELeaderboardUploadScoreMethodForceUpdate, int[] details = null)
	{
		int cScoreDetailsCount = ((details != null) ? details.Length : 0);
		SteamAPICall_t hAPICall = SteamUserStats.UploadLeaderboardScore(m_SteamLeaderboard, uploadMethod, score, details, cScoreDetailsCount);
		LeaderboardScoreUploaded.Set(hAPICall);
	}

	public void DownloadLeaderboardEntriesAsync()
	{
		SingletonMonoBehaviour<LeaderboardManager>.Instance.StartCoroutine(RunDownloadLeaderboardEntriesAsync());
	}

	private IEnumerator RunWaitForDownloadCount()
	{
		while (downloadLeaderboardEntriesCount > 3)
		{
			yield return null;
		}
	}

	private IEnumerator RunDownloadLeaderboardEntriesAsync()
	{
		selfEntryDirty = true;
		yield return RunWaitForDownloadCount();
		downloadLeaderboardEntriesCount++;
		SteamAPICall_t handle = SteamUserStats.DownloadLeaderboardEntries(m_SteamLeaderboard, ELeaderboardDataRequest.k_ELeaderboardDataRequestGlobalAroundUser, 0, 0);
		LeaderboardScoresDownloadedSelf.Set(handle);
		yield return RunWaitForDownloadCount();
		downloadLeaderboardEntriesCount++;
		handle = SteamUserStats.DownloadLeaderboardEntries(m_SteamLeaderboard, ELeaderboardDataRequest.k_ELeaderboardDataRequestGlobal, 0, 10);
		LeaderboardScoresDownloadedTop.Set(handle);
		yield return RunWaitForDownloadCount();
		downloadLeaderboardEntriesCount++;
		handle = SteamUserStats.DownloadLeaderboardEntries(m_SteamLeaderboard, ELeaderboardDataRequest.k_ELeaderboardDataRequestFriends, 0, 10);
		LeaderboardScoresDownloadedFriends.Set(handle);
	}

	private void OnLeaderboardScoreUploaded(LeaderboardScoreUploaded_t pCallback, bool bIOFailure)
	{
		if (pCallback.m_bSuccess != 0)
		{
			DownloadLeaderboardEntriesAsync();
		}
	}

	private void OnLeaderboardScoresDownloadedTop(LeaderboardScoresDownloaded_t pCallback, bool bIOFailure)
	{
		ProcessLeaderboardScoresDownloaded(pCallback, bIOFailure, ref EntriesTop, this.EntriesDownloadedTop);
	}

	private void OnLeaderboardScoresDownloadedSelf(LeaderboardScoresDownloaded_t pCallback, bool bIOFailure)
	{
		selfEntryDirty = false;
		ProcessLeaderboardScoresDownloaded(pCallback, bIOFailure, ref EntriesSelf, this.EntriesDownloadedSelf);
	}

	private void OnLeaderboardScoresDownloadedFriends(LeaderboardScoresDownloaded_t pCallback, bool bIOFailure)
	{
		ProcessLeaderboardScoresDownloaded(pCallback, bIOFailure, ref EntriesFriends, this.EntriesDownloadedFriends);
	}

	private void ProcessLeaderboardScoresDownloaded(LeaderboardScoresDownloaded_t pCallback, bool bIOFailure, ref List<LeaderboardEntry_t> entries, EntriesDownloaded entriesDownloaded)
	{
		downloadLeaderboardEntriesCount--;
		if (entries == null)
		{
			entries = new List<LeaderboardEntry_t>();
		}
		entries.Clear();
		for (int i = 0; i < pCallback.m_cEntryCount; i++)
		{
			if (SteamUserStats.GetDownloadedLeaderboardEntry(pCallback.m_hSteamLeaderboardEntries, i, out var pLeaderboardEntry, null, 0))
			{
				entries.Add(pLeaderboardEntry);
			}
		}
		entriesDownloaded?.Invoke(this, entries);
	}

	public bool GetSelfScore(out LeaderboardEntry_t self)
	{
		if (EntriesSelf != null)
		{
			foreach (LeaderboardEntry_t item in EntriesSelf)
			{
				if (item.m_steamIDUser == Player.LocalPlayer.SteamID && Player.LocalPlayer.SteamID.IsValid())
				{
					self = item;
					return true;
				}
			}
		}
		self = default(LeaderboardEntry_t);
		return false;
	}

	public void IncrementScore(int amount)
	{
		SingletonMonoBehaviour<LeaderboardManager>.Instance.StartCoroutine(RunIncrementScore(amount));
	}

	private IEnumerator RunIncrementScore(int amount)
	{
		DownloadLeaderboardEntriesAsync();
		while (selfEntryDirty)
		{
			yield return null;
		}
		int score = amount;
		if (GetSelfScore(out var selfScore))
		{
			score += selfScore.m_nScore;
		}
		UploadScore(score);
	}
}
