	{
		float num;
		float num2;
		if (bounds.x > bounds.y)
		{
			num = bounds.y;
			num2 = bounds.x;
		}
		else
		{
			num = bounds.x;
			num2 = bounds.y;
		}
		return value >= num && value <= num2;
	}

