public class CameraFade : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float fadeOutDelay = 0.4f;

	[SerializeField]
	private float fadeInDelay = 0.4f;

	[SerializeField]
	private float fadeOutDuration = 1f;

	[SerializeField]
	private float fadeInDuration = 0.25f;

	[SerializeField]
	private AnimateInOut effect;

	[SerializeField]
	private FadeImageEffect fadeEffect;

	private bool firstFadeIn = true;

	private Coroutine fadeCoroutine;

	public static CameraFade Instance { get; private set; }

	public float TotalFadeInDuration => fadeInDelay + fadeInDuration;

	public float TotalFadeOutDuration => fadeOutDelay + fadeOutDuration;

	public bool IsFading => fadeCoroutine != null;

	private void Awake()
	{
		Instance = this;
		fadeEffect = GetComponentInChildren<FadeImageEffect>(includeInactive: true);
	}

	public Coroutine Fade(bool fadeIn, bool prepForLevelSwitch = false)
	{
		if (fadeCoroutine != null)
		{
			StopCoroutine(fadeCoroutine);
		}
		fadeCoroutine = StartCoroutine(FadeCoroutine(fadeIn, prepForLevelSwitch));
		return fadeCoroutine;
	}

	private IEnumerator FadeCoroutine(bool fadeIn, bool prepForLevelSwitch)
	{
		AnimateInOutManager.SuppressAnimations = false;
		if (firstFadeIn)
		{
			firstFadeIn = false;
			yield return fadeEffect.FadeIn(fadeInDuration);
		}
		else
		{
			effect.StopEffect();
			effect.PlayEffect(fadeIn);
			if (fadeIn)
			{
				if (OpenVR.Compositor != null)
				{
					OpenVR.Compositor.SuspendRendering(bSuspend: false);
				}
				yield return new WaitForSeconds(fadeInDelay);
				if (OpenVR.Compositor != null)
				{
					OpenVR.Compositor.FadeToColor(0f, 0f, 0f, 0f, 0f, bBackground: false);
				}
				yield return fadeEffect.FadeIn(fadeInDuration);
			}
			else
			{
				yield return new WaitForSeconds(fadeOutDelay);
				yield return fadeEffect.FadeOut(fadeOutDuration);
				if (prepForLevelSwitch && OpenVR.Compositor != null)
				{
					OpenVR.Compositor.FadeToColor(0f, 0f, 0f, 0f, 1f, bBackground: false);
					OpenVR.Compositor.SuspendRendering(bSuspend: true);
				}
			}
		}
		fadeCoroutine = null;
	}
}
public class CollisionParticles : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class ParticlesToLayer
	{
		public string Name;

		public ParticleSystem ParticleSystemPrefab;

		public LayerMask Layers;

		public string Tag = string.Empty;

		[Tooltip("Per particle cooldown to limit the number of consequtive plays. Set it to the particle duration")]
		public float InstanceLimitDuration;

		private ParticleSystem particleSystemInstance;

		public float LastInstanceTime { get; set; }

		public ParticleSystem GetParticleSystem()
		{
			if (particleSystemInstance == null)
			{
				particleSystemInstance = UnityEngine.Object.Instantiate(ParticleSystemPrefab);
			}
			return particleSystemInstance;
		}

		public bool CanPlay(GameObject go, LayerMask layerMask)
		{
			if (Time.time - LastInstanceTime > InstanceLimitDuration && (Layers.value & (int)layerMask) == (int)layerMask && (string.IsNullOrEmpty(Tag) || go.CompareTag(Tag)))
			{
				LastInstanceTime = Time.time;
				return true;
			}
			return false;
		}
	}

	private Tool thisTool;

	[SerializeField]
	private ParticlesToLayer[] particleMappings;

	private void Awake()
	{
		thisTool = GetComponent<Tool>();
	}

	private void OnDestroy()
	{
		ParticlesToLayer[] array = particleMappings;
		foreach (ParticlesToLayer particlesToLayer in array)
		{
			ParticleSystem particleSystem = particlesToLayer.GetParticleSystem();
			if (particleSystem != null)
			{
				particleSystem.Stop();
				UnityEngine.Object.Destroy(particleSystem.gameObject);
			}
		}
	}

	private void OnCollisionEnter(Collision collision)
	{
		if (thisTool != null && thisTool.IsHeld)
		{
			return;
		}
		int num = 1 << collision.gameObject.layer;
		ParticlesToLayer[] array = particleMappings;
		foreach (ParticlesToLayer particlesToLayer in array)
		{
			if (particlesToLayer.CanPlay(collision.gameObject, num))
			{
				ParticleSystem particleSystem = particlesToLayer.GetParticleSystem();
				if (particleSystem != null)
				{
					particleSystem.Stop();
					UnityEngine.Debug.Log("OnCollision enter" + collision);
					particleSystem.transform.position = base.transform.position;
					particleSystem.Play();
				}
				break;
			}
		}
	}
}
public class FadeImageEffect : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Material fadeEffectMaterial;

	private int fadeId;

	public float Fade
	{
		set
		{
			fadeEffectMaterial.SetFloat(fadeId, value);
		}
	}

	private void Awake()
	{
		fadeId = Shader.PropertyToID("_Fade");
		Fade = 1f;
	}

	private void OnRenderImage(RenderTexture source, RenderTexture destination)
	{
		Graphics.Blit(source, destination, fadeEffectMaterial);
	}

	public Coroutine FadeIn(float duration)
	{
		base.enabled = true;
		StopAllCoroutines();
		return StartCoroutine(FadeCoroutine(fadeIn: true, duration));
	}

	public Coroutine FadeOut(float duration)
	{
		base.enabled = true;
		StopAllCoroutines();
		return StartCoroutine(FadeCoroutine(fadeIn: false, duration));
	}

	private IEnumerator FadeCoroutine(bool fadeIn, float duration)
	{
		float initialFade = ((!fadeIn) ? 0f : 1f);
		float finalFade = ((!fadeIn) ? 1f : 0f);
		float timer = 0f;
		while (timer < duration)
		{
			float t = timer / duration;
			Fade = Mathf.Lerp(initialFade, finalFade, t);
			timer += Time.deltaTime;
			yield return null;
		}
		Fade = finalFade;
		if (fadeIn)
		{
			base.enabled = false;
		}
	}
}
public class ParticleSystemsPlay : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool destroyOnDone = true;

	[SerializeField]
	private float destroyLifeTimeOverride = 5f;

	private void Start()
	{
		float num = destroyLifeTimeOverride;
		ParticleSystem[] componentsInChildren = GetComponentsInChildren<ParticleSystem>();
		foreach (ParticleSystem particleSystem in componentsInChildren)
		{
			num = Mathf.Max(num, particleSystem.startLifetime);
			particleSystem.Clear();
			particleSystem.Play();
		}
		if (destroyOnDone)
		{
			UnityEngine.Object.Destroy(base.gameObject, num);
		}
	}
}
public class PulsingBeam : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool gravityAligned;

	[SerializeField]
	private float scalePulseAmount;

	[SerializeField]
	private float scalePulseSpeed;

	private float startingScale;

	private void Awake()
	{
		startingScale = base.transform.localScale.x;
		scalePulseSpeed += UnityEngine.Random.Range(-0.2f, 0.2f);
	}

	private void FixedUpdate()
	{
		if (gravityAligned)
		{
			base.transform.rotation = Quaternion.LookRotation(Vector3.forward, Vector3.up);
		}
		Vector3 localScale = base.transform.localScale;
		localScale.z = (localScale.x = startingScale + Mathf.Sin(Time.time * scalePulseSpeed) * scalePulseAmount);
		base.transform.localScale = localScale;
	}
}
public class GifCapture : VideoCapture
{
	private float lastGifCaptureTime;

	private float gifCaptureStartTime;

	private Coroutine gifExportCoroutine;

	private List<RenderTexture> gifCaptureTextures = new List<RenderTexture>();

	public override string ExportDirectory => base.ExportDirectory + "Gifs\\";

	public override void StartCapture()
	{
		if (gifExportCoroutine == null)
		{
			base.IsCapturing = true;
			gifCaptureStartTime = Time.unscaledTime;
			lastGifCaptureTime = 0f;
			gifCaptureTextures.Clear();
			FireCaptureStartedEvent();
		}
	}

	public override void FinishCapture()
	{
		if (base.IsCapturing)
		{
			base.IsCapturing = false;
			gifExportCoroutine = StartCoroutine(GifExportCoroutine());
		}
	}

	public override float UpdateFrame(RenderTexture frame)
	{
		float result = 0f;
		if (base.IsCapturing)
		{
			if (Time.unscaledTime - lastGifCaptureTime >= capturePeriod)
			{
				lastGifCaptureTime = Time.unscaledTime;
				RenderTexture temporary = RenderTexture.GetTemporary(HorizontalResolution, VerticalResolution, 0);
				Graphics.Blit(frame, temporary);
				gifCaptureTextures.Add(temporary);
			}
			result = (Time.unscaledTime - gifCaptureStartTime) / maxDuration;
		}
		return result;
	}

	private IEnumerator GifExportCoroutine()
	{
		FireExportStartedEvent();
		MemoryStream memStream = new MemoryStream();
		yield return CaptureTheGIF.Instance.MakeGif(gifCaptureTextures, capturePeriod, memStream, closeWhenDone: false);
		string filename = VideoCapture.CurrentFileName;
		using (FileStream file = CaptureTheGIF.MakeFile(ExportDirectory, filename))
		{
			Thread thread = new Thread((ThreadStart)delegate
			{
				memStream.WriteTo(file);
				file.Flush();
				file.Close();
			});
			thread.Start();
			while (thread.ThreadState == System.Threading.ThreadState.Running)
			{
				yield return null;
			}
		}
		FireExportFinishedEvent(filename);
		gifExportCoroutine = null;
	}
}
public class MP4Capture : VideoCapture
{
	[SerializeField]
	private Material blitMaterial;

	private fcAPI.fcMP4Context mp4Context;

	private fcAPI.fcStream mp4OutputStream;

	private fcAPI.fcMP4Config mp4Config = fcAPI.fcMP4Config.default_value;

	private int videoId;

	private float captureStartTime;

	private string latestFilename;

	private RenderTexture scratchBuffer;

	public override string ExportDirectory => base.ExportDirectory + "Videos\\";

	protected override void Start()
	{
		base.Start();
		fcAPI.fcSetModulePath(Application.temporaryCachePath);
		fcAPI.fcMP4DownloadCodecBegin();
	}

	public override void StartCapture()
	{
		if (!SingletonMonoBehaviour<SettingsManager>.Instance.H264Plugin)
		{
			MenuNotification.PlayNext("Video camera is disabled! (check SETTINGS)", 1f, null, followPlayer: false, base.transform.position + Vector3.up * 0.1f, 0.1f);
			return;
		}
		VRSettings.renderScale = 0.5f;
		if (!base.IsCapturing)
		{
			base.IsCapturing = true;
			captureStartTime = Time.unscaledTime;
			InitializeContext();
			InitializeScratchBuffer();
			FireCaptureStartedEvent();
		}
	}

	public override float UpdateFrame(RenderTexture frame)
	{
		float result = 0f;
		if (base.IsCapturing)
		{
			Graphics.Blit(frame, scratchBuffer, blitMaterial);
			videoId = fcAPI.fcMP4AddVideoFrameTexture(mp4Context, scratchBuffer, Time.unscaledTime, videoId);
			GL.IssuePluginEvent(fcAPI.fcGetRenderEventFunc(), videoId);
			result = (Time.unscaledTime - captureStartTime) / maxDuration;
		}
		return result;
	}

	public override void FinishCapture()
	{
		if (base.IsCapturing)
		{
			ReleaseContext();
			FireExportStartedEvent();
			FireExportFinishedEvent(latestFilename);
			base.IsCapturing = false;
		}
		VRSettings.renderScale = 1f;
	}

	private void OnAudioFilterRead(float[] samples, int channels)
	{
		if (base.IsCapturing && channels == mp4Config.audio_num_channels)
		{
			fcAPI.fcMP4AddAudioFrame(mp4Context, samples, samples.Length);
		}
	}

	private void InitializeContext()
	{
		mp4Config = fcAPI.fcMP4Config.default_value;
		mp4Config.audio = false;
		mp4Config.audio_bitrate = 64000;
		mp4Config.audio_sampling_rate = AudioSettings.outputSampleRate;
		mp4Config.audio_num_channels = fcAPI.fcGetNumAudioChannels();
		mp4Config.video = true;
		mp4Config.video_height = VerticalResolution;
		mp4Config.video_width = HorizontalResolution;
		mp4Config.video_max_framerate = frameRate;
		mp4Config.video_bitrate = 8192000;
		mp4Context = fcAPI.fcMP4CreateContext(ref mp4Config);
		latestFilename = VideoCapture.CurrentFileName;
		mp4OutputStream = fcAPI.fcCreateFileStream(GetFullFilename(latestFilename));
		fcAPI.fcMP4AddOutputStream(mp4Context, mp4OutputStream);
	}

	private void InitializeScratchBuffer()
	{
		if (scratchBuffer != null)
		{
			if (scratchBuffer.IsCreated() && scratchBuffer.width == mp4Config.video_width && scratchBuffer.height == mp4Config.video_height)
			{
				return;
			}
			ReleaseScratchBuffer();
		}
		scratchBuffer = new RenderTexture(mp4Config.video_width, mp4Config.video_height, 0, RenderTextureFormat.ARGB32);
		scratchBuffer.wrapMode = TextureWrapMode.Repeat;
		scratchBuffer.Create();
	}

	private void ReleaseContext()
	{
		fcAPI.fcGuard(delegate
		{
			fcAPI.fcEraseDeferredCall(videoId);
			videoId = 0;
			if (mp4Context.ptr != IntPtr.Zero)
			{
				fcAPI.fcMP4DestroyContext(mp4Context);
				mp4Context.ptr = IntPtr.Zero;
			}
			if (mp4OutputStream.ptr != IntPtr.Zero)
			{
				fcAPI.fcDestroyStream(mp4OutputStream);
				mp4OutputStream.ptr = IntPtr.Zero;
			}
		});
	}

	private void ReleaseScratchBuffer()
	{
		if (scratchBuffer != null)
		{
			scratchBuffer.Release();
			scratchBuffer = null;
		}
	}

	private string GetFullFilename(string filename)
	{
		return Path.Combine(ExportDirectory, filename + ".mp4");
	}
}
public class PngCapture : VideoCapture
{
	public override string ExportDirectory => base.ExportDirectory + "Pngs\\";

	public override void StartCapture()
	{
		base.IsCapturing = true;
		FireCaptureStartedEvent();
	}

	public override void FinishCapture()
	{
		base.IsCapturing = false;
	}

	public override float UpdateFrame(RenderTexture frame)
	{
		if (!base.IsCapturing)
		{
			return 0f;
		}
		base.IsCapturing = false;
		FireExportStartedEvent();
		string fullFilename = GetFullFilename(VideoCapture.CurrentFileName);
		RenderTexture active = RenderTexture.active;
		RenderTexture.active = frame;
		Texture2D texture2D = new Texture2D(frame.width, frame.height, TextureFormat.ARGB32, mipmap: false);
		try
		{
			texture2D.ReadPixels(new Rect(0f, 0f, texture2D.width, texture2D.height), 0, 0);
			byte[] bytes = texture2D.EncodeToPNG();
			File.WriteAllBytes(fullFilename, bytes);
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
		}
		UnityEngine.Object.Destroy(texture2D);
		RenderTexture.active = active;
		FireExportFinishedEvent(fullFilename);
		return 1f;
	}

	private string GetFullFilename(string filename)
	{
		return Path.Combine(ExportDirectory, filename + ".png");
	}
}
public abstract class VideoCapture : UnityEngine.MonoBehaviour
{
	[SerializeField]
	protected int frameRate = 15;

	[SerializeField]
	protected float maxDuration = 30f;

	[HideInInspector]
	public float AspectRatio = 1f;

	[HideInInspector]
	public int HorizontalResolution = 1920;

	[HideInInspector]
	public int VerticalResolution = 1080;

	protected float capturePeriod;

	public bool IsCapturing { get; protected set; }

	public virtual string ExportDirectory => Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments) + "\\Rec Room\\";

	public static string CurrentFileName
	{
		get
		{
			string text = ActivityManager.ActivityName.Replace(" ", string.Empty);
			DateTime now = DateTime.Now;
			return $"{text}_{now.Year:D4}{now.Month:D2}{now.Day:D2}_{now.Hour:D2}{now.Minute:D2}{now.Second:D2}";
		}
	}

	public event Action CaptureStartedEvent;

	public event Action ExportStartedEvent;

	public event Action<string> ExportFinishedEvent;

	public abstract void StartCapture();

	public abstract void FinishCapture();

	public abstract float UpdateFrame(RenderTexture frame);

	protected virtual void Awake()
	{
		capturePeriod = 1f / (float)frameRate;
	}

	protected virtual void Start()
	{
		if (!Directory.Exists(ExportDirectory))
		{
			Directory.CreateDirectory(ExportDirectory);
		}
	}

	protected void FireCaptureStartedEvent()
	{
		if (this.CaptureStartedEvent != null)
		{
			this.CaptureStartedEvent();
		}
	}

	protected void FireExportStartedEvent()
	{
		if (this.ExportStartedEvent != null)
		{
			this.ExportStartedEvent();
		}
	}

	protected void FireExportFinishedEvent(string filename)
	{
		if (this.ExportFinishedEvent != null)
		{
			this.ExportFinishedEvent(filename);
		}
	}
}
public class GoogleAnalytics : UnityEngine.MonoBehaviour
{
	public const string GOOGLE_ANALYTICS_CLIENTID_PREF_KEY = "google_analytics_clientid_pref_key";

	public const string GOOGLE_ANALYTICS_SYSTEM_INFO_SUBMITED = "system_info_submited";

	public const string SYSTEM_INFO = "SystemInfo";

	private static GoogleAnalytics Instance = null;

	private static string _ClientId;

	private static GoogleAnalyticsClient client = null;

	private static string CurrentLevelName;

	private static bool IsSessionStarted = false;

	private static System.Random random = new System.Random((int)DateTime.Now.Ticks);

	public static GoogleAnalyticsClient Client
	{
		get
		{
			if (client == null)
			{
				StartTracking();
			}
			return client;
		}
	}

	public static string ClientId => _ClientId;

	public static string LoadedLevelName => SceneManager.GetActiveScene().name;

	private void Awake()
	{
		if (Instance != null)
		{
			UnityEngine.Object.DestroyImmediate(base.gameObject);
			return;
		}
		Instance = this;
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
	}

	private void Start()
	{
		GenerateClientId();
		client = new GoogleAnalyticsClient(_ClientId);
		if (!IsSessionStarted)
		{
			Client.CreateHit(GoogleAnalyticsHitType.SCREENVIEW);
			Client.StartSession();
			Client.SetUserLanguage(Application.systemLanguage.ToString());
			Client.SetScreenResolution(Screen.width, Screen.height);
			string action = $"{VRSettings.loadedDeviceName}_{VRDevice.model}";
			Client.SendEventHit("device", action, string.Empty);
			Client.Send();
			IsSessionStarted = true;
		}
		SendFirstScreenHit();
		SubmitSystemInfo();
		if (GoogleAnalyticsSettings.Instance.AutoExceptionTracking)
		{
			Application.logMessageReceived += HandleLog;
		}
		if (GoogleAnalyticsSettings.Instance.AutoCampaignTracking)
		{
			GA_AndroidTools.RequestReffer();
		}
		SceneManager.sceneLoaded += delegate
		{
			TrackNewLevel();
		};
	}

	public static void SetTrackingId(string TrackingId)
	{
		StartTracking();
		client.GenerateHeaders(TrackingId);
	}

	public static void StartTracking()
	{
		if (Instance == null)
		{
			GameObject gameObject = new GameObject("Google Analytics");
			gameObject.AddComponent<GoogleAnalytics>();
		}
	}

	private void OnApplicationPause(bool paused)
	{
		if (GoogleAnalyticsSettings.Instance.AutoAppResumeTracking)
		{
			if (paused)
			{
				Client.CreateHit(GoogleAnalyticsHitType.APPVIEW);
				Client.EndSession();
				Client.Send();
			}
			else if (Client != null)
			{
				Client.CreateHit(GoogleAnalyticsHitType.APPVIEW);
				Client.StartSession();
				Client.Send();
			}
		}
	}

	private void OnApplicationQuit()
	{
		if (GoogleAnalyticsSettings.Instance.AutoAppQuitTracking)
		{
			GoogleAnalyticsRequestCache.SendCashedRequests();
			Client.CreateHit(GoogleAnalyticsHitType.APPVIEW);
			Client.EndSession();
			Client.Send();
		}
	}

	private void HandleLog(string logString, string stackTrace, LogType type)
	{
		if (GoogleAnalyticsSettings.Instance.AutoExceptionTracking)
		{
			if (type == LogType.Exception)
			{
				Client.CreateHit(GoogleAnalyticsHitType.EXCEPTION);
				Client.SetExceptionDescription(logString);
				Client.SetScreenName(LoadedLevelName);
				Client.SetDocumentTitle(stackTrace);
				Client.SetIsFatalException(isFatal: false);
				Client.Send();
			}
			if (type == LogType.Error)
			{
				Client.CreateHit(GoogleAnalyticsHitType.EXCEPTION);
				Client.SetExceptionDescription(logString);
				Client.SetScreenName(LoadedLevelName);
				Client.SetDocumentTitle(stackTrace);
				Client.SetIsFatalException(isFatal: false);
				Client.Send();
			}
		}
	}

	private void OnReferalIntentReciver(string referrerString)
	{
		try
		{
			UnityEngine.Debug.Log("[OnReferalIntentReciver] referrerString:" + referrerString);
			int num = referrerString.LastIndexOf('?');
			UnityEngine.Debug.Log("[OnReferalIntentReciver] urlBeginIndex:" + num);
			if (num != -1)
			{
				num++;
				referrerString = referrerString.Substring(num, referrerString.Length - num);
			}
			Client.CreateHit(GoogleAnalyticsHitType.APPVIEW);
			string[] array = referrerString.Split('&');
			string[] array2 = array;
			foreach (string text in array2)
			{
				if (text.Equals(string.Empty))
				{
					continue;
				}
				UnityEngine.Debug.Log("[OnReferalIntentReciver] StringParams:kv " + text);
				string[] array3 = text.Split('=');
				string text2 = array3[0];
				string text3 = array3[1];
				if (string.IsNullOrEmpty(text2) || string.IsNullOrEmpty(text3))
				{
					continue;
				}
				switch (text2)
				{
				case "utm_campaign":
					Client.SetCampaignName(text3);
					break;
				case "utm_source":
					Client.SetCampaignSource(text3);
					break;
				case "utm_medium":
					Client.SetCampaignMedium(text3);
					break;
				case "utm_term":
				{
					string[] array4 = text3.Split('+');
					string[] array5 = array4;
					foreach (string keyword in array5)
					{
						Client.AddCampaignKeyword(keyword);
					}
					break;
				}
				case "utm_content":
					Client.SetCampaignContent(text3);
					break;
				case "gclid":
					Client.SetGoogleAdWordsID(text3);
					break;
				}
			}
			Client.Send();
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.Log("OnReferalIntentReciver:: parsing error");
			UnityEngine.Debug.Log(ex.Message);
		}
	}

	public static void SubmitSystemInfo()
	{
		if (GoogleAnalyticsSettings.Instance.SubmitSystemInfoOnFirstLaunch && !PlayerPrefs.HasKey("system_info_submited"))
		{
			PlayerPrefs.SetInt("system_info_submited", 1);
			Client.SendEventHit("SystemInfo", "deviceModel", SystemInfo.deviceModel);
			Client.SendEventHit("SystemInfo", "deviceName", SystemInfo.deviceName);
			Client.SendEventHit("SystemInfo", "deviceType", SystemInfo.deviceType.ToString());
			Client.SendEventHit("SystemInfo", "graphicsDeviceID", SystemInfo.graphicsDeviceID.ToString(), SystemInfo.graphicsDeviceID);
			Client.SendEventHit("SystemInfo", "graphicsDeviceVendorID", SystemInfo.graphicsDeviceVendorID.ToString(), SystemInfo.graphicsDeviceVendorID);
			Client.SendEventHit("SystemInfo", "graphicsDeviceName", SystemInfo.graphicsDeviceName);
			Client.SendEventHit("SystemInfo", "graphicsDeviceVendor", SystemInfo.graphicsDeviceVendor);
			Client.SendEventHit("SystemInfo", "graphicsDeviceVersion", SystemInfo.graphicsDeviceVersion);
			Client.SendEventHit("SystemInfo", "graphicsShaderLevel", SystemInfo.graphicsShaderLevel.ToString(), SystemInfo.graphicsShaderLevel);
			Client.SendEventHit("SystemInfo", "graphicsMemorySize", SystemInfo.graphicsMemorySize + "MB", SystemInfo.graphicsMemorySize);
			Client.SendEventHit("SystemInfo", "systemMemorySize", SystemInfo.systemMemorySize + "MB", SystemInfo.systemMemorySize);
			Client.SendEventHit("SystemInfo", "systemLanguage", Application.systemLanguage.ToString());
			Client.SendEventHit("SystemInfo", "operatingSystem", SystemInfo.operatingSystem);
			Client.SendEventHit("SystemInfo", "processorType", SystemInfo.processorType);
			Client.SendEventHit("SystemInfo", "processorCount", SystemInfo.processorCount.ToString(), SystemInfo.processorCount);
			Client.SendEventHit("SystemInfo", "supportsAccelerometer", (!SystemInfo.supportsAccelerometer) ? "false" : "true", SystemInfo.supportsAccelerometer ? 1 : 0);
			Client.SendEventHit("SystemInfo", "supportsLocationService", (!SystemInfo.supportsLocationService) ? "false" : "true", SystemInfo.supportsLocationService ? 1 : 0);
			Client.SendEventHit("SystemInfo", "supportsVibration", (!SystemInfo.supportsVibration) ? "false" : "true", SystemInfo.supportsVibration ? 1 : 0);
			Client.SendEventHit("SystemInfo", "supportsRenderTextures", (!SystemInfo.supportsRenderTextures) ? "false" : "true", SystemInfo.supportsRenderTextures ? 1 : 0);
			Client.SendEventHit("SystemInfo", "supportsImageEffects", (!SystemInfo.supportsImageEffects) ? "false" : "true", SystemInfo.supportsImageEffects ? 1 : 0);
			Client.SendEventHit("SystemInfo", "supportsShadows", (!SystemInfo.supportsShadows) ? "false" : "true", SystemInfo.supportsShadows ? 1 : 0);
		}
	}

	public static void RestorePrefKeys()
	{
		PlayerPrefs.SetString("google_analytics_clientid_pref_key", _ClientId);
		PlayerPrefs.SetInt("system_info_submited", 1);
	}

	public static void Send(string request)
	{
		if (Instance == null)
		{
			UnityEngine.Debug.LogWarning("GoogleAnalytics is destroyed, skipping the request and caching it for later send : " + request);
			GoogleAnalyticsRequestCache.SaveRequest(request);
			return;
		}
		byte[] bytes = Encoding.UTF8.GetBytes(request);
		if (GoogleAnalyticsSettings.Instance.IsRequetsCachingEnabled)
		{
			Instance.StartCoroutine(Instance.SendAnalytics(bytes, request));
		}
		else
		{
			SendSkipCache(request);
		}
	}

	public static void SendSkipCache(string request)
	{
		byte[] bytes = Encoding.UTF8.GetBytes(request);
		Client.GenerateWWW(bytes);
	}

	private IEnumerator SendAnalytics(byte[] data, string cache)
	{
		WWW www = Client.GenerateWWW(data);
		yield return www;
		if (www.error != null)
		{
			GoogleAnalyticsRequestCache.SaveRequest(cache);
		}
		else
		{
			GoogleAnalyticsRequestCache.SendCashedRequests();
		}
	}

	private static void SendFirstScreenHit()
	{
		if (GoogleAnalyticsSettings.Instance.AutoLevelTracking)
		{
			CurrentLevelName = LoadedLevelName;
			Client.CreateHit(GoogleAnalyticsHitType.APPVIEW);
			Client.SetScreenResolution(Screen.currentResolution.width, Screen.currentResolution.height);
			Client.SetViewportSize(Screen.width, Screen.height);
			Client.SetUserLanguage(Application.systemLanguage.ToString());
			Client.SetScreenName(GoogleAnalyticsSettings.Instance.LevelPrefix + CurrentLevelName + GoogleAnalyticsSettings.Instance.LevelPostfix);
			Client.Send();
		}
	}

	private static void TrackNewLevel()
	{
		if (GoogleAnalyticsSettings.Instance.AutoLevelTracking && !CurrentLevelName.Equals(LoadedLevelName))
		{
			CurrentLevelName = LoadedLevelName;
			Client.SendScreenHit(GoogleAnalyticsSettings.Instance.LevelPrefix + CurrentLevelName + GoogleAnalyticsSettings.Instance.LevelPostfix);
		}
	}

	private static void GenerateClientId()
	{
		if (PlayerPrefs.HasKey("google_analytics_clientid_pref_key"))
		{
			_ClientId = PlayerPrefs.GetString("google_analytics_clientid_pref_key");
			return;
		}
		_ClientId = RandomString(8) + SystemInfo.deviceUniqueIdentifier;
		PlayerPrefs.SetString("google_analytics_clientid_pref_key", _ClientId);
	}

	private static string RandomString(int size)
	{
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < size; i++)
		{
			char value = Convert.ToChar(Convert.ToInt32(Math.Floor(26.0 * random.NextDouble() + 65.0)));
			stringBuilder.Append(value);
		}
		return stringBuilder.ToString();
	}
}
