public class GoogleAnalyticsSettings : ScriptableObject
{
	private const string AnalyticsSettingsAssetName = "GoogleAnalyticsSettings";

	private const string AnalyticsSettingsAssetExtension = ".asset";

	public static string VERSION_NUMBER = "3.0.2";

	[SerializeField]
	public List<GAProfile> accounts = new List<GAProfile>();

	[SerializeField]
	public List<GAPlatfromBound> platfromBounds = new List<GAPlatfromBound>();

	public bool showAdditionalParams;

	public bool showAdvancedParams;

	public bool showCParams;

	public bool showAccounts = true;

	public bool showPlatfroms;

	public bool showTestingMode;

	public string AppName = "My App";

	public string AppVersion = "0.0.1";

	public bool UseHTTPS;

	public bool StringEscaping = true;

	public bool EditorAnalytics = true;

	public bool IsDisabled;

	public bool IsTestingModeEnabled;

	public int TestingModeAccIndex;

	public bool IsRequetsCachingEnabled = true;

	public bool IsQueueTimeEnabled = true;

	public bool AutoLevelTracking = true;

	public string LevelPrefix = "Level_";

	public string LevelPostfix = string.Empty;

	public bool AutoAppQuitTracking = true;

	public bool AutoCampaignTracking;

	public bool AutoExceptionTracking = true;

	public bool AutoAppResumeTracking = true;

	public bool SubmitSystemInfoOnFirstLaunch = true;

	public bool UsePlayerSettingsForAppInfo = true;

	private static GoogleAnalyticsSettings instance;

	public static GoogleAnalyticsSettings Instance
	{
		get
		{
			if (instance == null)
			{
				instance = Resources.Load("GoogleAnalyticsSettings") as GoogleAnalyticsSettings;
				if (instance == null)
				{
					instance = ScriptableObject.CreateInstance<GoogleAnalyticsSettings>();
				}
			}
			return instance;
		}
	}

	public void UpdateVersionAndName()
	{
	}

	public void AddProfile(GAProfile p)
	{
		accounts.Add(p);
	}

	public void RemoveProfile(GAProfile p)
	{
		accounts.Remove(p);
	}

	public void SetProfileIndexForPlatfrom(RuntimePlatform platfrom, int index, bool IsTesting)
	{
		foreach (GAPlatfromBound platfromBound in platfromBounds)
		{
			if (platfromBound.platfrom.Equals(platfrom))
			{
				if (IsTesting)
				{
					platfromBound.profileIndexTestMode = index;
				}
				else
				{
					platfromBound.profileIndex = index;
				}
				return;
			}
		}
		GAPlatfromBound gAPlatfromBound = new GAPlatfromBound();
		gAPlatfromBound.platfrom = platfrom;
		gAPlatfromBound.profileIndex = 0;
		gAPlatfromBound.profileIndexTestMode = 0;
		if (IsTesting)
		{
			gAPlatfromBound.profileIndexTestMode = index;
		}
		else
		{
			gAPlatfromBound.profileIndex = index;
		}
		platfromBounds.Add(gAPlatfromBound);
	}

	public int GetProfileIndexForPlatfrom(RuntimePlatform platfrom, bool IsTestMode)
	{
		foreach (GAPlatfromBound platfromBound in platfromBounds)
		{
			if (platfromBound.platfrom.Equals(platfrom))
			{
				int num = platfromBound.profileIndex;
				if (IsTestMode)
				{
					num = platfromBound.profileIndexTestMode;
				}
				if (num < accounts.Count)
				{
					return num;
				}
				return 0;
			}
		}
		return 0;
	}

	public string[] GetProfileNames()
	{
		List<string> list = new List<string>();
		foreach (GAProfile account in accounts)
		{
			list.Add(account.Name);
		}
		return list.ToArray();
	}

	public int GetProfileIndex(GAProfile p)
	{
		int num = 0;
		string[] profileNames = GetProfileNames();
		string[] array = profileNames;
		foreach (string text in array)
		{
			if (text.Equals(p.Name))
			{
				return num;
			}
			num++;
		}
		return 0;
	}

	public GAProfile GetCurentProfile()
	{
		bool isTestMode = false;
		return GetPrfileForPlatfrom(Application.platform, isTestMode);
	}

	public GAProfile GetPrfileForPlatfrom(RuntimePlatform platfrom, bool IsTestMode)
	{
		if (accounts.Count == 0)
		{
			return new GAProfile();
		}
		return accounts[GetProfileIndexForPlatfrom(platfrom, IsTestMode)];
	}
}
namespace GAMiniJSON
{
	public static class Json
	{
		private sealed class Parser : IDisposable
		{
			private enum TOKEN
			{
				NONE,
				CURLY_OPEN,
				CURLY_CLOSE,
				SQUARED_OPEN,
				SQUARED_CLOSE,
				COLON,
				COMMA,
				STRING,
				NUMBER,
				TRUE,
				FALSE,
				NULL
			}

			private const string WHITE_SPACE = " \t\n\r";

			private const string WORD_BREAK = " \t\n\r{}[],:\"";

			private StringReader json;

			private char PeekChar => Convert.ToChar(json.Peek());

			private char NextChar => Convert.ToChar(json.Read());

			private string NextWord
			{
				get
				{
					StringBuilder stringBuilder = new StringBuilder();
					while (" \t\n\r{}[],:\"".IndexOf(PeekChar) == -1)
					{
						stringBuilder.Append(NextChar);
						if (json.Peek() == -1)
						{
							break;
						}
					}
					return stringBuilder.ToString();
				}
			}

			private TOKEN NextToken
			{
				get
				{
					EatWhitespace();
					if (json.Peek() == -1)
					{
						return TOKEN.NONE;
					}
					switch (PeekChar)
					{
					case '{':
						return TOKEN.CURLY_OPEN;
					case '}':
						json.Read();
						return TOKEN.CURLY_CLOSE;
					case '[':
						return TOKEN.SQUARED_OPEN;
					case ']':
						json.Read();
						return TOKEN.SQUARED_CLOSE;
					case ',':
						json.Read();
						return TOKEN.COMMA;
					case '"':
						return TOKEN.STRING;
					case ':':
						return TOKEN.COLON;
					case '-':
					case '0':
					case '1':
					case '2':
					case '3':
					case '4':
					case '5':
					case '6':
					case '7':
					case '8':
					case '9':
						return TOKEN.NUMBER;
					default:
						return NextWord switch
						{
							"false" => TOKEN.FALSE, 
							"true" => TOKEN.TRUE, 
							"null" => TOKEN.NULL, 
							_ => TOKEN.NONE, 
						};
					}
				}
			}

			private Parser(string jsonString)
			{
				json = new StringReader(jsonString);
			}

			public static object Parse(string jsonString)
			{
				using Parser parser = new Parser(jsonString);
				return parser.ParseValue();
			}

			public void Dispose()
			{
				json.Dispose();
				json = null;
			}

			private Dictionary<string, object> ParseObject()
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				json.Read();
				while (true)
				{
					switch (NextToken)
					{
					case TOKEN.COMMA:
						continue;
					case TOKEN.NONE:
						return null;
					case TOKEN.CURLY_CLOSE:
						return dictionary;
					}
					string text = ParseString();
					if (text == null)
					{
						return null;
					}
					if (NextToken != TOKEN.COLON)
					{
						return null;
					}
					json.Read();
					dictionary[text] = ParseValue();
				}
			}

			private List<object> ParseArray()
			{
				List<object> list = new List<object>();
				json.Read();
				bool flag = true;
				while (flag)
				{
					TOKEN nextToken = NextToken;
					switch (nextToken)
					{
					case TOKEN.NONE:
						return null;
					case TOKEN.SQUARED_CLOSE:
						flag = false;
						break;
					default:
					{
						object item = ParseByToken(nextToken);
						list.Add(item);
						break;
					}
					case TOKEN.COMMA:
						break;
					}
				}
				return list;
			}

			private object ParseValue()
			{
				TOKEN nextToken = NextToken;
				return ParseByToken(nextToken);
			}

			private object ParseByToken(TOKEN token)
			{
				return token switch
				{
					TOKEN.STRING => ParseString(), 
					TOKEN.NUMBER => ParseNumber(), 
					TOKEN.CURLY_OPEN => ParseObject(), 
					TOKEN.SQUARED_OPEN => ParseArray(), 
					TOKEN.TRUE => true, 
					TOKEN.FALSE => false, 
					TOKEN.NULL => null, 
					_ => null, 
				};
			}

			private string ParseString()
			{
				StringBuilder stringBuilder = new StringBuilder();
				json.Read();
				bool flag = true;
				while (flag)
				{
					if (json.Peek() == -1)
					{
						flag = false;
						break;
					}
					char nextChar = NextChar;
					switch (nextChar)
					{
					case '"':
						flag = false;
						break;
					case '\\':
						if (json.Peek() == -1)
						{
							flag = false;
							break;
						}
						nextChar = NextChar;
						switch (nextChar)
						{
						case '"':
						case '/':
						case '\\':
							stringBuilder.Append(nextChar);
							break;
						case 'b':
							stringBuilder.Append('\b');
							break;
						case 'f':
							stringBuilder.Append('\f');
							break;
						case 'n':
							stringBuilder.Append('\n');
							break;
						case 'r':
							stringBuilder.Append('\r');
							break;
						case 't':
							stringBuilder.Append('\t');
							break;
						case 'u':
						{
							StringBuilder stringBuilder2 = new StringBuilder();
							for (int i = 0; i < 4; i++)
							{
								stringBuilder2.Append(NextChar);
							}
							stringBuilder.Append((char)Convert.ToInt32(stringBuilder2.ToString(), 16));
							break;
						}
						}
						break;
					default:
						stringBuilder.Append(nextChar);
						break;
					}
				}
				return stringBuilder.ToString();
			}

			private object ParseNumber()
			{
				string nextWord = NextWord;
				if (nextWord.IndexOf('.') == -1)
				{
					long.TryParse(nextWord, out var result);
					return result;
				}
				double.TryParse(nextWord, out var result2);
				return result2;
			}

			private void EatWhitespace()
			{
				while (" \t\n\r".IndexOf(PeekChar) != -1)
				{
					json.Read();
					if (json.Peek() == -1)
					{
						break;
					}
				}
			}
		}

		private sealed class Serializer
		{
			private StringBuilder builder;

			private Serializer()
			{
				builder = new StringBuilder();
			}

			public static string Serialize(object obj)
			{
				Serializer serializer = new Serializer();
				serializer.SerializeValue(obj);
				return serializer.builder.ToString();
			}

			private void SerializeValue(object value)
			{
				if (value == null)
				{
					builder.Append("null");
				}
				else if (value is string str)
				{
					SerializeString(str);
				}
				else if (value is bool)
				{
					builder.Append(value.ToString().ToLower());
				}
				else if (value is IList anArray)
				{
					SerializeArray(anArray);
				}
				else if (value is IDictionary obj)
				{
					SerializeObject(obj);
				}
				else if (value is char)
				{
					SerializeString(value.ToString());
				}
				else
				{
					SerializeOther(value);
				}
			}

			private void SerializeObject(IDictionary obj)
			{
				bool flag = true;
				builder.Append('{');
				foreach (object key in obj.Keys)
				{
					if (!flag)
					{
						builder.Append(',');
					}
					SerializeString(key.ToString());
					builder.Append(':');
					SerializeValue(obj[key]);
					flag = false;
				}
				builder.Append('}');
			}

			private void SerializeArray(IList anArray)
			{
				builder.Append('[');
				bool flag = true;
				foreach (object item in anArray)
				{
					if (!flag)
					{
						builder.Append(',');
					}
					SerializeValue(item);
					flag = false;
				}
				builder.Append(']');
			}

			private void SerializeString(string str)
			{
				builder.Append('"');
				char[] array = str.ToCharArray();
				char[] array2 = array;
				foreach (char c in array2)
				{
					switch (c)
					{
					case '"':
						builder.Append("\\\"");
						continue;
					case '\\':
						builder.Append("\\\\");
						continue;
					case '\b':
						builder.Append("\\b");
						continue;
					case '\f':
						builder.Append("\\f");
						continue;
					case '\n':
						builder.Append("\\n");
						continue;
					case '\r':
						builder.Append("\\r");
						continue;
					case '\t':
						builder.Append("\\t");
						continue;
					}
					int num = Convert.ToInt32(c);
					if (num >= 32 && num <= 126)
					{
						builder.Append(c);
					}
					else
					{
						builder.Append("\\u" + Convert.ToString(num, 16).PadLeft(4, '0'));
					}
				}
				builder.Append('"');
			}

			private void SerializeOther(object value)
			{
				if (value is float || value is int || value is uint || value is long || value is double || value is sbyte || value is byte || value is short || value is ushort || value is ulong || value is decimal)
				{
					builder.Append(value.ToString());
				}
				else
				{
					SerializeString(value.ToString());
				}
			}
		}

		public static object Deserialize(string json)
		{
			if (json == null)
			{
				return null;
			}
			return Parser.Parse(json);
		}

		public static string Serialize(object obj)
		{
			return Serializer.Serialize(obj);
		}
	}
}
