		public static void LookUpdate(GameObject target, System.Collections.Hashtable args)
		{
			CleanArgs(args);
			Vector3[] array = new Vector3[5];
			float num;
			if (args.Contains("looktime"))
			{
				num = (float)args["looktime"];
