		public static System.Collections.Hashtable Hash(params object[] args)
		{
			System.Collections.Hashtable hashtable = new System.Collections.Hashtable(args.Length / 2);
			if (args.Length % 2 != 0)
			{
				UnityEngine.Debug.LogError("Tween Error: Hash requires an even number of arguments!");
				return null;
			}
			for (int i = 0; i < args.Length - 1; i += 2)
			{
				hashtable.Add(args[i], args[i + 1]);
			}
			return hashtable;
		}

		private void Awake()
		{
			thisTransform = base.transform;
			RetrieveArgs();
			lastRealTime = Time.realtimeSinceStartup;
		}

		private IEnumerator Start()
		{
			if (delay > 0f)
			{
				yield return StartCoroutine("TweenDelay");
			}
			TweenStart();
		}

		private void Update()
		{
			if (!isRunning || physics)
			{
				return;
			}
			if (!reverse)
			{
				if (percentage < 1f)
				{
					TweenUpdate();
				}
				else
				{
					TweenComplete();
				}
			}
			else if (percentage > 0f)
			{
				TweenUpdate();
			}
			else
			{
				TweenComplete();
			}
		}

		private void FixedUpdate()
		{
			if (!isRunning || !physics)
			{
				return;
			}
			if (!reverse)
			{
				if (percentage < 1f)
				{
					TweenUpdate();
				}
				else
				{
					TweenComplete();
				}
			}
			else if (percentage > 0f)
			{
				TweenUpdate();
			}
			else
			{
				TweenComplete();
			}
		}

		private void LateUpdate()
		{
			if (tweenArguments.Contains("looktarget") && isRunning && (type == "move" || type == "shake" || type == "punch"))
			{
				LookUpdate(base.gameObject, tweenArguments);
			}
		}

		private void OnEnable()
		{
			if (isRunning)
			{
				EnableKinematic();
			}
			if (isPaused)
			{
				isPaused = false;
				if (delay > 0f)
				{
					wasPaused = true;
					ResumeDelay();
				}
			}
		}

		private void OnDisable()
		{
			DisableKinematic();
		}

		private static void DrawLineHelper(Vector3[] line, Color color, string method)
		{
			Gizmos.color = color;
			for (int i = 0; i < line.Length - 1; i++)
			{
				if (method == "gizmos")
				{
					Gizmos.DrawLine(line[i], line[i + 1]);
				}
				else if (method == "handles")
				{
					UnityEngine.Debug.LogError("iTween Error: Drawing a line with Handles is temporarily disabled because of compatability issues with Unity 2.6!");
				}
			}
		}

		private static void DrawPathHelper(Vector3[] path, Color color, string method)
		{
			Vector3[] pts = PathControlPointGenerator(path);
			Vector3 to = Interp(pts, 0f);
			Gizmos.color = color;
			int num = path.Length * 20;
			for (int i = 1; i <= num; i++)
			{
				float t = (float)i / (float)num;
				Vector3 vector = Interp(pts, t);
				if (method == "gizmos")
				{
					Gizmos.DrawLine(vector, to);
				}
				else if (method == "handles")
				{
					UnityEngine.Debug.LogError("iTween Error: Drawing a path with Handles is temporarily disabled because of compatability issues with Unity 2.6!");
				}
				to = vector;
			}
		}

		private static Vector3[] PathControlPointGenerator(Vector3[] path)
		{
			int num = 2;
			Vector3[] array = new Vector3[path.Length + num];
			Array.Copy(path, 0, array, 1, path.Length);
			ref Vector3 reference = ref array[0];
			reference = array[1] + (array[1] - array[2]);
			ref Vector3 reference2 = ref array[array.Length - 1];
			reference2 = array[array.Length - 2] + (array[array.Length - 2] - array[array.Length - 3]);
			if (array[1] == array[array.Length - 2])
			{
				Vector3[] array2 = new Vector3[array.Length];
				Array.Copy(array, array2, array.Length);
				ref Vector3 reference3 = ref array2[0];
				reference3 = array2[array2.Length - 3];
				ref Vector3 reference4 = ref array2[array2.Length - 1];
				reference4 = array2[2];
				array = new Vector3[array2.Length];
				Array.Copy(array2, array, array2.Length);
			}
			return array;
		}

		private static Vector3 Interp(Vector3[] pts, float t)
		{
			int num = pts.Length - 3;
			int num2 = Mathf.Min(Mathf.FloorToInt(t * (float)num), num - 1);
			float num3 = t * (float)num - (float)num2;
			Vector3 vector = pts[num2];
			Vector3 vector2 = pts[num2 + 1];
			Vector3 vector3 = pts[num2 + 2];
			Vector3 vector4 = pts[num2 + 3];
			return 0.5f * ((-vector + 3f * vector2 - 3f * vector3 + vector4) * (num3 * num3 * num3) + (2f * vector - 5f * vector2 + 4f * vector3 - vector4) * (num3 * num3) + (-vector + vector3) * num3 + 2f * vector2);
		}

		private static void Launch(GameObject target, System.Collections.Hashtable args)
		{
			if (!args.Contains("id"))
			{
				args["id"] = GenerateID();
			}
			if (!args.Contains("target"))
			{
				args["target"] = target;
			}
			tweens.Insert(0, args);
			target.AddComponent<iTween>();
		}

		private static System.Collections.Hashtable CleanArgs(System.Collections.Hashtable args)
		{
			System.Collections.Hashtable hashtable = new System.Collections.Hashtable(args.Count);
			System.Collections.Hashtable hashtable2 = new System.Collections.Hashtable(args.Count);
			foreach (DictionaryEntry arg in args)
			{
				hashtable.Add(arg.Key, arg.Value);
			}
			foreach (DictionaryEntry item in hashtable)
			{
				if (item.Value.GetType() == typeof(int))
				{
					int num = (int)item.Value;
					float num2 = num;
					args[item.Key] = num2;
				}
				if (item.Value.GetType() == typeof(double))
				{
					double num3 = (double)item.Value;
					float num4 = (float)num3;
					args[item.Key] = num4;
				}
			}
			foreach (DictionaryEntry arg2 in args)
			{
				hashtable2.Add(arg2.Key.ToString().ToLower(), arg2.Value);
			}
			args = hashtable2;
			return args;
		}

		private static string GenerateID()
		{
			return Guid.NewGuid().ToString();
		}

		private void RetrieveArgs()
		{
			foreach (System.Collections.Hashtable tween in tweens)
			{
				if ((GameObject)tween["target"] == base.gameObject)
				{
					tweenArguments = tween;
					break;
				}
			}
			id = (string)tweenArguments["id"];
			type = (string)tweenArguments["type"];
			_name = (string)tweenArguments["name"];
			method = (string)tweenArguments["method"];
			if (tweenArguments.Contains("time"))
			{
				time = (float)tweenArguments["time"];
			}
			else
			{
				time = Defaults.time;
			}
			if (GetComponent<Rigidbody>() != null)
			{
				physics = true;
			}
			if (tweenArguments.Contains("delay"))
			{
				delay = (float)tweenArguments["delay"];
			}
			else
			{
				delay = Defaults.delay;
			}
			if (tweenArguments.Contains("namedcolorvalue"))
			{
				if (tweenArguments["namedcolorvalue"].GetType() == typeof(NamedValueColor))
				{
					namedcolorvalue = (NamedValueColor)(int)tweenArguments["namedcolorvalue"];
				}
				else
				{
					try
					{
						namedcolorvalue = (NamedValueColor)(int)Enum.Parse(typeof(NamedValueColor), (string)tweenArguments["namedcolorvalue"], ignoreCase: true);
					}
					catch
					{
						UnityEngine.Debug.LogWarning("iTween: Unsupported namedcolorvalue supplied! Default will be used.");
						namedcolorvalue = NamedValueColor._Color;
					}
				}
			}
			else
			{
				namedcolorvalue = Defaults.namedColorValue;
			}
			if (tweenArguments.Contains("looptype"))
			{
				if (tweenArguments["looptype"].GetType() == typeof(LoopType))
				{
					loopType = (LoopType)(int)tweenArguments["looptype"];
				}
				else
				{
					try
					{
						loopType = (LoopType)(int)Enum.Parse(typeof(LoopType), (string)tweenArguments["looptype"], ignoreCase: true);
					}
					catch
					{
						UnityEngine.Debug.LogWarning("iTween: Unsupported loopType supplied! Default will be used.");
						loopType = LoopType.none;
					}
				}
			}
			else
			{
				loopType = LoopType.none;
			}
			if (tweenArguments.Contains("easetype"))
			{
				if (tweenArguments["easetype"].GetType() == typeof(EaseType))
				{
					easeType = (EaseType)(int)tweenArguments["easetype"];
				}
				else
				{
					try
					{
						easeType = (EaseType)(int)Enum.Parse(typeof(EaseType), (string)tweenArguments["easetype"], ignoreCase: true);
					}
					catch
					{
						UnityEngine.Debug.LogWarning("iTween: Unsupported easeType supplied! Default will be used.");
						easeType = Defaults.easeType;
					}
				}
			}
			else
			{
				easeType = Defaults.easeType;
			}
			if (tweenArguments.Contains("space"))
			{
				if (tweenArguments["space"].GetType() == typeof(Space))
				{
					space = (Space)(int)tweenArguments["space"];
				}
				else
				{
					try
					{
						space = (Space)(int)Enum.Parse(typeof(Space), (string)tweenArguments["space"], ignoreCase: true);
					}
					catch
					{
						UnityEngine.Debug.LogWarning("iTween: Unsupported space supplied! Default will be used.");
						space = Defaults.space;
					}
				}
			}
			else
			{
				space = Defaults.space;
			}
			if (tweenArguments.Contains("islocal"))
			{
				isLocal = (bool)tweenArguments["islocal"];
			}
			else
			{
				isLocal = Defaults.isLocal;
			}
			if (tweenArguments.Contains("ignoretimescale"))
			{
				useRealTime = (bool)tweenArguments["ignoretimescale"];
			}
			else
			{
				useRealTime = Defaults.useRealTime;
			}
			GetEasingFunction();
		}

		private void GetEasingFunction()
		{
			switch (easeType)
			{
			case EaseType.easeInQuad:
				ease = easeInQuad;
				break;
			case EaseType.easeOutQuad:
				ease = easeOutQuad;
				break;
			case EaseType.easeInOutQuad:
				ease = easeInOutQuad;
				break;
			case EaseType.easeInCubic:
				ease = easeInCubic;
				break;
			case EaseType.easeOutCubic:
				ease = easeOutCubic;
				break;
			case EaseType.easeInOutCubic:
				ease = easeInOutCubic;
				break;
			case EaseType.easeInQuart:
				ease = easeInQuart;
				break;
			case EaseType.easeOutQuart:
				ease = easeOutQuart;
				break;
			case EaseType.easeInOutQuart:
				ease = easeInOutQuart;
				break;
			case EaseType.easeInQuint:
				ease = easeInQuint;
				break;
			case EaseType.easeOutQuint:
				ease = easeOutQuint;
				break;
			case EaseType.easeInOutQuint:
				ease = easeInOutQuint;
				break;
			case EaseType.easeInSine:
				ease = easeInSine;
				break;
			case EaseType.easeOutSine:
				ease = easeOutSine;
				break;
			case EaseType.easeInOutSine:
				ease = easeInOutSine;
				break;
			case EaseType.easeInExpo:
				ease = easeInExpo;
				break;
			case EaseType.easeOutExpo:
				ease = easeOutExpo;
				break;
			case EaseType.easeInOutExpo:
				ease = easeInOutExpo;
				break;
			case EaseType.easeInCirc:
				ease = easeInCirc;
				break;
			case EaseType.easeOutCirc:
				ease = easeOutCirc;
				break;
			case EaseType.easeInOutCirc:
				ease = easeInOutCirc;
				break;
			case EaseType.linear:
				ease = linear;
				break;
			case EaseType.spring:
				ease = spring;
				break;
			case EaseType.easeInBounce:
				ease = easeInBounce;
				break;
			case EaseType.easeOutBounce:
				ease = easeOutBounce;
				break;
			case EaseType.easeInOutBounce:
				ease = easeInOutBounce;
				break;
			case EaseType.easeInBack:
				ease = easeInBack;
				break;
			case EaseType.easeOutBack:
				ease = easeOutBack;
				break;
			case EaseType.easeInOutBack:
				ease = easeInOutBack;
				break;
			case EaseType.easeInElastic:
				ease = easeInElastic;
				break;
			case EaseType.easeOutElastic:
				ease = easeOutElastic;
				break;
			case EaseType.easeInOutElastic:
				ease = easeInOutElastic;
				break;
			}
		}

		private void UpdatePercentage()
		{
			if (useRealTime)
			{
				runningTime += Time.realtimeSinceStartup - lastRealTime;
			}
			else
			{
				runningTime += Time.deltaTime;
			}
			if (reverse)
			{
				percentage = 1f - runningTime / time;
			}
			else
			{
				percentage = runningTime / time;
			}
			lastRealTime = Time.realtimeSinceStartup;
		}

		private void CallBack(string callbackType)
		{
			if (tweenArguments.Contains(callbackType) && !tweenArguments.Contains("ischild"))
			{
				GameObject gameObject = ((!tweenArguments.Contains(callbackType + "target")) ? base.gameObject : ((GameObject)tweenArguments[callbackType + "target"]));
				if (tweenArguments[callbackType].GetType() == typeof(string))
				{
					gameObject.SendMessage((string)tweenArguments[callbackType], tweenArguments[callbackType + "params"], SendMessageOptions.DontRequireReceiver);
					return;
				}
				UnityEngine.Debug.LogError("iTween Error: Callback method references must be passed as a String!");
				UnityEngine.Object.Destroy(this);
			}
		}

		private void Dispose()
		{
			for (int i = 0; i < tweens.Count; i++)
			{
				System.Collections.Hashtable hashtable = tweens[i];
				if ((string)hashtable["id"] == id)
				{
					tweens.RemoveAt(i);
					break;
				}
			}
			UnityEngine.Object.Destroy(this);
		}

		private void ConflictCheck()
		{
			UnityEngine.Component[] components = GetComponents<iTween>();
			UnityEngine.Component[] array = components;
			for (int i = 0; i < array.Length; i++)
			{
				iTween iTween2 = (iTween)array[i];
				if (iTween2.type == "value")
				{
					break;
				}
				if (!iTween2.isRunning || !(iTween2.type == type))
				{
					continue;
				}
				if (iTween2.method != method)
				{
					break;
				}
				if (iTween2.tweenArguments.Count != tweenArguments.Count)
				{
					iTween2.Dispose();
					break;
				}
				foreach (DictionaryEntry tweenArgument in tweenArguments)
				{
					if (!iTween2.tweenArguments.Contains(tweenArgument.Key))
					{
						iTween2.Dispose();
						return;
					}
					if (!iTween2.tweenArguments[tweenArgument.Key].Equals(tweenArguments[tweenArgument.Key]) && (string)tweenArgument.Key != "id")
					{
						iTween2.Dispose();
						return;
					}
				}
				Dispose();
			}
		}

		private void EnableKinematic()
		{
		}

		private void DisableKinematic()
		{
		}

		private void ResumeDelay()
		{
			StartCoroutine("TweenDelay");
		}

		private float linear(float start, float end, float value)
		{
			return Mathf.Lerp(start, end, value);
		}

		private float clerp(float start, float end, float value)
		{
			float num = 0f;
			float num2 = 360f;
			float num3 = Mathf.Abs((num2 - num) * 0.5f);
			float num4 = 0f;
			float num5 = 0f;
			if (end - start < 0f - num3)
			{
				num5 = (num2 - start + end) * value;
				return start + num5;
			}
			if (end - start > num3)
			{
				num5 = (0f - (num2 - end + start)) * value;
				return start + num5;
			}
			return start + (end - start) * value;
		}

		private float spring(float start, float end, float value)
		{
			value = Mathf.Clamp01(value);
			value = (Mathf.Sin(value * (float)Math.PI * (0.2f + 2.5f * value * value * value)) * Mathf.Pow(1f - value, 2.2f) + value) * (1f + 1.2f * (1f - value));
			return start + (end - start) * value;
		}

		private float easeInQuad(float start, float end, float value)
		{
			end -= start;
			return end * value * value + start;
		}

		private float easeOutQuad(float start, float end, float value)
		{
			end -= start;
			return (0f - end) * value * (value - 2f) + start;
		}

		private float easeInOutQuad(float start, float end, float value)
		{
			value /= 0.5f;
			end -= start;
			if (value < 1f)
			{
				return end * 0.5f * value * value + start;
			}
			value -= 1f;
			return (0f - end) * 0.5f * (value * (value - 2f) - 1f) + start;
		}

		private float easeInCubic(float start, float end, float value)
		{
			end -= start;
			return end * value * value * value + start;
		}

		private float easeOutCubic(float start, float end, float value)
		{
			value -= 1f;
			end -= start;
			return end * (value * value * value + 1f) + start;
		}

		private float easeInOutCubic(float start, float end, float value)
		{
			value /= 0.5f;
			end -= start;
			if (value < 1f)
			{
				return end * 0.5f * value * value * value + start;
			}
			value -= 2f;
			return end * 0.5f * (value * value * value + 2f) + start;
		}

		private float easeInQuart(float start, float end, float value)
		{
			end -= start;
			return end * value * value * value * value + start;
		}

		private float easeOutQuart(float start, float end, float value)
		{
			value -= 1f;
			end -= start;
			return (0f - end) * (value * value * value * value - 1f) + start;
		}

		private float easeInOutQuart(float start, float end, float value)
		{
			value /= 0.5f;
			end -= start;
			if (value < 1f)
			{
				return end * 0.5f * value * value * value * value + start;
			}
			value -= 2f;
			return (0f - end) * 0.5f * (value * value * value * value - 2f) + start;
		}

		private float easeInQuint(float start, float end, float value)
		{
			end -= start;
			return end * value * value * value * value * value + start;
		}

		private float easeOutQuint(float start, float end, float value)
		{
			value -= 1f;
			end -= start;
			return end * (value * value * value * value * value + 1f) + start;
		}

		private float easeInOutQuint(float start, float end, float value)
		{
			value /= 0.5f;
			end -= start;
			if (value < 1f)
			{
				return end * 0.5f * value * value * value * value * value + start;
			}
			value -= 2f;
			return end * 0.5f * (value * value * value * value * value + 2f) + start;
		}

		private float easeInSine(float start, float end, float value)
		{
			end -= start;
			return (0f - end) * Mathf.Cos(value * ((float)Math.PI / 2f)) + end + start;
		}

		private float easeOutSine(float start, float end, float value)
		{
			end -= start;
			return end * Mathf.Sin(value * ((float)Math.PI / 2f)) + start;
		}

		private float easeInOutSine(float start, float end, float value)
		{
			end -= start;
			return (0f - end) * 0.5f * (Mathf.Cos((float)Math.PI * value) - 1f) + start;
		}

		private float easeInExpo(float start, float end, float value)
		{
			end -= start;
			return end * Mathf.Pow(2f, 10f * (value - 1f)) + start;
		}

		private float easeOutExpo(float start, float end, float value)
		{
			end -= start;
			return end * (0f - Mathf.Pow(2f, -10f * value) + 1f) + start;
		}

		private float easeInOutExpo(float start, float end, float value)
		{
			value /= 0.5f;
			end -= start;
			if (value < 1f)
			{
				return end * 0.5f * Mathf.Pow(2f, 10f * (value - 1f)) + start;
			}
			value -= 1f;
			return end * 0.5f * (0f - Mathf.Pow(2f, -10f * value) + 2f) + start;
		}

		private float easeInCirc(float start, float end, float value)
		{
			end -= start;
			return (0f - end) * (Mathf.Sqrt(1f - value * value) - 1f) + start;
		}

		private float easeOutCirc(float start, float end, float value)
		{
			value -= 1f;
			end -= start;
			return end * Mathf.Sqrt(1f - value * value) + start;
		}

		private float easeInOutCirc(float start, float end, float value)
		{
			value /= 0.5f;
			end -= start;
			if (value < 1f)
			{
				return (0f - end) * 0.5f * (Mathf.Sqrt(1f - value * value) - 1f) + start;
			}
			value -= 2f;
			return end * 0.5f * (Mathf.Sqrt(1f - value * value) + 1f) + start;
		}

		private float easeInBounce(float start, float end, float value)
		{
			end -= start;
			float num = 1f;
			return end - easeOutBounce(0f, end, num - value) + start;
		}

		private float easeOutBounce(float start, float end, float value)
		{
			value /= 1f;
			end -= start;
			if (value < 0.36363637f)
			{
				return end * (7.5625f * value * value) + start;
			}
			if (value < 0.72727275f)
			{
				value -= 0.54545456f;
				return end * (7.5625f * value * value + 0.75f) + start;
			}
			if ((double)value < 0.9090909090909091)
			{
				value -= 0.8181818f;
				return end * (7.5625f * value * value + 0.9375f) + start;
			}
			value -= 21f / 22f;
			return end * (7.5625f * value * value + 63f / 64f) + start;
		}

		private float easeInOutBounce(float start, float end, float value)
		{
			end -= start;
			float num = 1f;
			if (value < num * 0.5f)
			{
				return easeInBounce(0f, end, value * 2f) * 0.5f + start;
			}
			return easeOutBounce(0f, end, value * 2f - num) * 0.5f + end * 0.5f + start;
		}

		private float easeInBack(float start, float end, float value)
		{
			end -= start;
			value /= 1f;
			float num = 1.70158f;
			return end * value * value * ((num + 1f) * value - num) + start;
		}

		private float easeOutBack(float start, float end, float value)
		{
			float num = 1.70158f;
			end -= start;
			value -= 1f;
			return end * (value * value * ((num + 1f) * value + num) + 1f) + start;
		}

		private float easeInOutBack(float start, float end, float value)
		{
			float num = 1.70158f;
			end -= start;
			value /= 0.5f;
			if (value < 1f)
			{
				num *= 1.525f;
				return end * 0.5f * (value * value * ((num + 1f) * value - num)) + start;
			}
			value -= 2f;
			num *= 1.525f;
			return end * 0.5f * (value * value * ((num + 1f) * value + num) + 2f) + start;
		}

		private float punch(float amplitude, float value)
		{
			float num = 9f;
			if (value == 0f)
			{
				return 0f;
			}
			if (value == 1f)
			{
				return 0f;
			}
			float num2 = 0.3f;
			num = num2 / ((float)Math.PI * 2f) * Mathf.Asin(0f);
			return amplitude * Mathf.Pow(2f, -10f * value) * Mathf.Sin((value * 1f - num) * ((float)Math.PI * 2f) / num2);
		}

		private float easeInElastic(float start, float end, float value)
		{
			end -= start;
			float num = 1f;
			float num2 = num * 0.3f;
			float num3 = 0f;
			float num4 = 0f;
			if (value == 0f)
			{
				return start;
			}
			if ((value /= num) == 1f)
			{
				return start + end;
			}
			if (num4 == 0f || num4 < Mathf.Abs(end))
			{
				num4 = end;
				num3 = num2 / 4f;
			}
			else
			{
				num3 = num2 / ((float)Math.PI * 2f) * Mathf.Asin(end / num4);
			}
			return 0f - num4 * Mathf.Pow(2f, 10f * (value -= 1f)) * Mathf.Sin((value * num - num3) * ((float)Math.PI * 2f) / num2) + start;
		}

		private float easeOutElastic(float start, float end, float value)
		{
			end -= start;
			float num = 1f;
			float num2 = num * 0.3f;
			float num3 = 0f;
			float num4 = 0f;
			if (value == 0f)
			{
				return start;
			}
			if ((value /= num) == 1f)
			{
				return start + end;
			}
			if (num4 == 0f || num4 < Mathf.Abs(end))
			{
				num4 = end;
				num3 = num2 * 0.25f;
			}
			else
			{
				num3 = num2 / ((float)Math.PI * 2f) * Mathf.Asin(end / num4);
			}
			return num4 * Mathf.Pow(2f, -10f * value) * Mathf.Sin((value * num - num3) * ((float)Math.PI * 2f) / num2) + end + start;
		}

		private float easeInOutElastic(float start, float end, float value)
		{
			end -= start;
			float num = 1f;
			float num2 = num * 0.3f;
			float num3 = 0f;
			float num4 = 0f;
			if (value == 0f)
			{
				return start;
			}
			if ((value /= num * 0.5f) == 2f)
			{
				return start + end;
			}
			if (num4 == 0f || num4 < Mathf.Abs(end))
			{
				num4 = end;
				num3 = num2 / 4f;
			}
			else
			{
				num3 = num2 / ((float)Math.PI * 2f) * Mathf.Asin(end / num4);
			}
			if (value < 1f)
			{
				return -0.5f * (num4 * Mathf.Pow(2f, 10f * (value -= 1f)) * Mathf.Sin((value * num - num3) * ((float)Math.PI * 2f) / num2)) + start;
			}
			return num4 * Mathf.Pow(2f, -10f * (value -= 1f)) * Mathf.Sin((value * num - num3) * ((float)Math.PI * 2f) / num2) * 0.5f + end + start;
		}
	}
}
public class SA_ScreenShotMaker : SA_Singleton<SA_ScreenShotMaker>
{
	public Action<Texture2D> OnScreenshotReady;

	public void GetScreenshot()
	{
		StartCoroutine(SaveScreenshot());
	}

	private IEnumerator SaveScreenshot()
	{
		yield return new WaitForEndOfFrame();
		int width = Screen.width;
		int height = Screen.height;
		Texture2D tex = new Texture2D(width, height, TextureFormat.RGB24, mipmap: false);
		tex.ReadPixels(new Rect(0f, 0f, width, height), 0, 0);
		tex.Apply();
		if (OnScreenshotReady != null)
		{
			OnScreenshotReady(tex);
		}
	}
}
public class SA_DataConverter
{
	public const char DATA_SPLITTER = '|';

	public const string DATA_SPLITTER2 = "|%|";

	public const string ARRAY_SPLITTER = "%%%";

	public const string DATA_EOF = "endofline";

	public static string SerializeArray(string[] array, string splitter = "%%%")
	{
		if (array == null)
		{
			return string.Empty;
		}
		if (array.Length == 0)
		{
			return string.Empty;
		}
		string text = string.Empty;
		int num = array.Length;
		for (int i = 0; i < num; i++)
		{
			if (i != 0)
			{
				text += splitter;
			}
			text += array[i];
		}
		return text;
	}

	public static string[] ParseArray(string arrayData, string splitter = "%%%")
	{
		List<string> list = new List<string>();
		string[] array = arrayData.Split(new string[1] { splitter }, StringSplitOptions.None);
		for (int i = 0; i < array.Length && !(array[i] == "endofline"); i++)
		{
			list.Add(array[i]);
		}
		return list.ToArray();
	}
}
public static class SA_Gameobject
{
	public static Sprite ToSprite(this Texture2D texture)
	{
		return Sprite.Create(texture, new Rect(0f, 0f, texture.width, texture.height), new Vector2(0.5f, 0.5f));
	}
}
public class SA_PrefabAsyncLoader : UnityEngine.MonoBehaviour
{
	private string PrefabPath;

	public event Action<GameObject> ObjectLoadedAction = delegate
	{
	};

	public static SA_PrefabAsyncLoader Create(string name)
	{
		SA_PrefabAsyncLoader sA_PrefabAsyncLoader = new GameObject("PrefabAsyncLoader").AddComponent<SA_PrefabAsyncLoader>();
		sA_PrefabAsyncLoader.LoadAsync(name);
		return sA_PrefabAsyncLoader;
	}

	public void LoadAsync(string name)
	{
		PrefabPath = name;
		StartCoroutine(Load());
	}

	public IEnumerator Load()
	{
		ResourceRequest request = Resources.LoadAsync(PrefabPath);
		yield return request;
		if (request.asset == null)
		{
			UnityEngine.Debug.LogWarning("Prefab not found at path: " + PrefabPath);
		}
		GameObject loadedObject = UnityEngine.Object.Instantiate(request.asset) as GameObject;
		this.ObjectLoadedAction(loadedObject);
	}
}
public class SA_WWWTextureLoader : UnityEngine.MonoBehaviour
{
	public static Dictionary<string, Texture2D> LocalCache = new Dictionary<string, Texture2D>();

	private string _url;

	public event Action<Texture2D> OnLoad = delegate
	{
	};

	public static SA_WWWTextureLoader Create()
	{
		return new GameObject("WWWTextureLoader").AddComponent<SA_WWWTextureLoader>();
	}

	public void LoadTexture(string url)
	{
		_url = url;
		if (LocalCache.ContainsKey(_url))
		{
			this.OnLoad(LocalCache[_url]);
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else
		{
			StartCoroutine(LoadCoroutin());
		}
	}

	private IEnumerator LoadCoroutin()
	{
		WWW www = new WWW(_url);
		yield return www;
		if (www.error == null)
		{
			UpdateLocalCache(_url, www.texture);
			this.OnLoad(www.texture);
		}
		else
		{
			this.OnLoad(null);
		}
		UnityEngine.Object.Destroy(base.gameObject);
	}

	private static void UpdateLocalCache(string url, Texture2D image)
	{
	}
}
public class SA_ModulesInfo
{
	public const int VERSION_UNDEFINED = 0;

	public const string VERSION_UNDEFINED_STRING = "Undefined";

	public static string FB_SDK_VersionCode
	{
		get
		{
			string result = "Undefined";
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				Type type = assembly.GetType("Facebook.FBBuildVersionAttribute");
				Type type2 = assembly.GetType("Facebook.IFacebook");
				if (type2 == null || type == null)
				{
					continue;
				}
				MethodInfo method = type.GetMethod("GetVersionAttributeOfType", BindingFlags.Static | BindingFlags.Public);
				if (method != null)
				{
					object obj = method.Invoke(null, new object[1] { type2 });
					PropertyInfo property = type.GetProperty("SdkVersion");
					if (obj != null && property != null && property.GetValue(obj, null) is string text)
					{
						result = text;
					}
				}
				break;
			}
			Type type3 = Type.GetType("Facebook.Unity.FacebookSdkVersion");
			if (type3 != null)
			{
				PropertyInfo property2 = type3.GetProperty("Build", BindingFlags.Static | BindingFlags.Public);
				if (property2 != null)
				{
					result = (string)property2.GetValue(null, null);
				}
			}
			return result;
		}
	}

	public static int FB_SDK_MajorVersionCode
	{
		get
		{
			string fB_SDK_VersionCode = FB_SDK_VersionCode;
			int result = 0;
			if (fB_SDK_VersionCode.Equals("Undefined"))
			{
				return result;
			}
			try
			{
				string[] array = fB_SDK_VersionCode.Split('.');
				result = Convert.ToInt32(array[0]);
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogWarning("FB_SDK_MajorVersionCode failed: " + ex.Message);
			}
			return result;
		}
	}
}
public class SA_IdFactory
{
	private const string PP_ID_KEY = "SA_IdFactory_Key";

	public static int NextId
	{
		get
		{
			int num = 1;
			if (PlayerPrefs.HasKey("SA_IdFactory_Key"))
			{
				num = PlayerPrefs.GetInt("SA_IdFactory_Key");
				num++;
			}
			PlayerPrefs.SetInt("SA_IdFactory_Key", num);
			return num;
		}
	}

	public static string RandomString
	{
		get
		{
			string element = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
			System.Random random = new System.Random();
			return new string((from s in Enumerable.Repeat(element, 8)
				select s[random.Next(s.Length)]).ToArray());
		}
	}
}
public abstract class SA_NonMonoSingleton<T> where T : SA_NonMonoSingleton<T>, new()
{
	private static T _Instance;

	public static T Instance
	{
		get
		{
			if (_Instance == null)
			{
				_Instance = new T();
			}
			return _Instance;
		}
	}
}
public abstract class SA_Singleton<T> : UnityEngine.MonoBehaviour where T : UnityEngine.MonoBehaviour
{
	private static T _instance;

	private static bool applicationIsQuitting;

	[Obsolete("instance is deprectaed, plase use Instance instaed")]
	public static T instance => Instance;

	public static T Instance
	{
		get
		{
			if (applicationIsQuitting)
			{
				return (T)null;
			}
			if (_instance == null)
			{
				_instance = UnityEngine.Object.FindObjectOfType(typeof(T)) as T;
				if (_instance == null)
				{
					_instance = new GameObject().AddComponent<T>();
					_instance.gameObject.name = _instance.GetType().Name;
				}
			}
			return _instance;
		}
	}

	public static bool HasInstance => !IsDestroyed;

	public static bool IsDestroyed
	{
		get
		{
			if (_instance == null)
			{
				return true;
			}
			return false;
		}
	}

	protected virtual void OnDestroy()
	{
		_instance = (T)null;
		applicationIsQuitting = true;
	}

	protected virtual void OnApplicationQuit()
	{
		_instance = (T)null;
		applicationIsQuitting = true;
	}
}
